script_name("grnd_adm_tools")
-- Версия лежит и в переменной: её показывает диагностика /mp diag, а сама
-- переменная одна на весь файл — не нужно искать строки по коду.
GRND_SCRIPT_VERSION = "1.19.65"
script_version(GRND_SCRIPT_VERSION)
script_dependencies("SAMPFUNCS")
require "lib.moonloader"
require "lib.sampfuncs"

local libList = {
    { "cjson",       "cjson",    false },
    { "lfs",         "lfs",      false },
    { "socket.http", "http",     false },
    { "inspect",     "inspect",  false },
    { "lume",        "lume",     false },
    { "memory",      "memory",   false },
    { "vkeys",       "vkeys",    false },
    { "encoding",    "encoding", false },
    { "bit",         "bit",      false },
    { "requests",    "requests", false },
}
local libs = {}
local failed = {}
for _, item in ipairs(libList) do
    local name, var, required = item[1], item[2], item[3]
    local ok, mod = pcall(require, name)
    if ok then
        libs[var] = mod
        _G[var] = mod
    else
        failed[#failed + 1] = name
        if required then error("Обязательная библиотека не найдена: " .. name) end
    end
end

-- Generated files live below resource/grnd; config paths remain unchanged.
GRND_STORAGE = {paths={}}
function grndStoragePath(kind,name)
    local S=GRND_STORAGE
    local key=kind.."/"..name
    if S.paths[key] then return S.paths[key] end
    local sep=package.config:sub(1,1)
    if not S.root then
        local dir
        if type(thisScript)=="function" then
            pcall(function()
                local script=thisScript()
                if script then dir=tostring(script.path or ""):match("^(.*)[/\\]") end
            end)
        end
        if not dir and type(getWorkingDirectory)=="function" then
            local ok,value=pcall(getWorkingDirectory)
            if ok and value and value~="" then dir=tostring(value) end
        end
        if not dir and type(this_script_dir)=="function" then
            local ok,value=pcall(this_script_dir)
            if ok and value and value~="" then dir=tostring(value) end
        end
        dir=(dir or "."):gsub("[/\\]+$", "")
        local function mkdir(path)
            if type(createDirectory)=="function" then pcall(createDirectory,path) end
            if libs.lfs and type(libs.lfs.mkdir)=="function" then pcall(libs.lfs.mkdir,path) end
        end
        mkdir(dir..sep.."resource")
        S.root=dir..sep.."resource"..sep.."grnd"
        mkdir(S.root)
        mkdir(S.root..sep.."logs")
        mkdir(S.root..sep.."cache")
    end
    S.paths[key]=S.root..sep..kind..sep..name
    return S.paths[key]
end

-- Unified portable configuration. No game state, credentials or log records.
GRND_CONFIG = {schema=1, sources={
    grnd_settings="settings", grnd_ui="ui", grnd_killlist="killlist",
    grnd_admins="admins", grnd_binder="binder", grnd_ring="ring",
    grnd_char="character", grnd_punish="punishments", grnd_chat="legacyFont",
    grnd_repquick="reportTemplates", grnd_reppunish="reportPunish",
    -- v1.19.27: настройки автопилота. Без этой строки open() бросал
    -- «Unknown configuration domain» и раздел вообще ничего не сохранял.
    grnd_repauto="reportAuto"
}}
do
    local C=GRND_CONFIG
    local ARRAY={}
    function C.array(t) return setmetatable(t or {},ARRAY) end
    local NULL={}
    local function utf(cp)
        if cp<128 then return string.char(cp) end
        if cp<2048 then return string.char(192+math.floor(cp/64),128+cp%64) end
        if cp<65536 then return string.char(224+math.floor(cp/4096),128+math.floor(cp/64)%64,128+cp%64) end
        return string.char(240+math.floor(cp/262144),128+math.floor(cp/4096)%64,128+math.floor(cp/64)%64,128+cp%64)
    end
    local function quote(s)
        return '"'..s:gsub('[%z\1-\31\\"]',function(ch)
            local escapes={['"']='\\"',['\\']='\\\\',['\n']='\\n',['\r']='\\r',['\t']='\\t'}
            return escapes[ch] or string.format('\\u%04x',ch:byte())
        end)..'"'
    end
    function C.encode(value,depth)
        depth=depth or 0;assert(depth<48,'JSON too deep')
        local t=type(value)
        if value==NULL or value==nil then return 'null' end
        if t=='string' then return quote(value) end
        if t=='boolean' then return value and 'true' or 'false' end
        if t=='number' then
            assert(value==value and math.abs(value)<math.huge,'Invalid JSON number')
            return (string.format('%.15g',value):gsub(',','.'))
        end
        assert(t=='table','Unsupported JSON value')
        local arr=getmetatable(value)==ARRAY or #value>0
        local result={};local indent=string.rep('  ',depth+1)
        if arr then
            for i=1,#value do result[#result+1]=indent..C.encode(value[i],depth+1) end
        else
            local keys={};for k in pairs(value) do assert(type(k)=='string','Non-string JSON key');keys[#keys+1]=k end
            table.sort(keys)
            for _,k in ipairs(keys) do result[#result+1]=indent..quote(k)..': '..C.encode(value[k],depth+1) end
        end
        local left,right=arr and '[' or '{',arr and ']' or '}'
        if #result==0 then return left..right end
        return left..'\n'..table.concat(result,',\n')..'\n'..string.rep('  ',depth)..right
    end
    function C.decode(s)
        assert(type(s)=='string' and #s<=2097152,'Invalid/oversized JSON')
        s=s:gsub('^\239\187\191','');local pos=1
        local function ws() local _,e=s:find('^[ \r\n\t]*',pos);pos=(e or pos-1)+1 end
        local function str()
            assert(s:sub(pos,pos)=='"','Expected string');pos=pos+1
            local out={}
            while pos<=#s do
                local ch=s:sub(pos,pos);pos=pos+1
                if ch=='"' then return table.concat(out) end
                if ch=='\\' then
                    ch=s:sub(pos,pos);pos=pos+1
                    local escapes={['"']='"',['\\']='\\',['/']='/',b='\b',f='\f',n='\n',r='\r',t='\t'}
                    if ch=='u' then
                        local h=s:sub(pos,pos+3);assert(h:match('^%x%x%x%x$'),'Bad unicode escape');pos=pos+4
                        local cp=tonumber(h,16)
                        if cp>=55296 and cp<=56319 then
                            assert(s:sub(pos,pos+1)=='\\u','Missing low surrogate');pos=pos+2
                            h=s:sub(pos,pos+3);assert(h:match('^%x%x%x%x$'),'Bad surrogate');pos=pos+4
                            local lo=tonumber(h,16);assert(lo>=56320 and lo<=57343,'Bad low surrogate')
                            cp=65536+(cp-55296)*1024+lo-56320
                        else assert(cp<56320 or cp>57343,'Unpaired surrogate') end
                        out[#out+1]=utf(cp)
                    else assert(escapes[ch],'Bad JSON escape');out[#out+1]=escapes[ch] end
                else assert(ch:byte()>=32,'Control in string');out[#out+1]=ch end
            end
            error('Unterminated string')
        end
        local parse
        parse=function(depth)
            assert(depth<48,'JSON too deep');ws();local ch=s:sub(pos,pos)
            if ch=='"' then return str() end
            if ch=='{' or ch=='[' then
                local arr=ch=='[';local result=arr and C.array() or {};pos=pos+1;ws()
                local ending=arr and ']' or '}'
                if s:sub(pos,pos)==ending then pos=pos+1;return result end
                while true do
                    if arr then result[#result+1]=parse(depth+1)
                    else
                        ws();local k=str();ws();assert(s:sub(pos,pos)==':','Missing colon');pos=pos+1
                        assert(result[k]==nil,'Duplicate key');result[k]=parse(depth+1)
                    end
                    ws();ch=s:sub(pos,pos);pos=pos+1
                    if ch==ending then return result end
                    assert(ch==',','Missing comma');ws()
                end
            end
            for word,v in pairs({['true']=true,['false']=false,['null']=NULL}) do
                if s:sub(pos,pos+#word-1)==word then pos=pos+#word;return v end
            end
            local start=pos
            if ch=='-' then pos=pos+1 end
            if s:sub(pos,pos)=='0' then pos=pos+1
            else assert(s:sub(pos,pos):match('[1-9]'),'Bad JSON value')
                repeat pos=pos+1 until not s:sub(pos,pos):match('%d')
            end
            if s:sub(pos,pos)=='.' then
                pos=pos+1;assert(s:sub(pos,pos):match('%d'),'Bad fraction')
                repeat pos=pos+1 until not s:sub(pos,pos):match('%d')
            end
            ch=s:sub(pos,pos)
            if ch=='e' or ch=='E' then
                pos=pos+1;ch=s:sub(pos,pos);if ch=='+' or ch=='-' then pos=pos+1 end
                assert(s:sub(pos,pos):match('%d'),'Bad exponent')
                repeat pos=pos+1 until not s:sub(pos,pos):match('%d')
            end
            local n=tonumber(s:sub(start,pos-1));assert(n and n==n and math.abs(n)<math.huge,'Bad number');return n
        end
        local result=parse(0);ws();assert(pos>#s,'Trailing JSON data');return result
    end
    function C.base()
        if C.baseDir then return C.baseDir end
        local dir
        if type(getWorkingDirectory)=='function' then local ok,v=pcall(getWorkingDirectory);if ok and v~='' then dir=v end end
        if not dir and type(thisScript)=='function' then
            pcall(function() dir=tostring(thisScript().path or ''):match('^(.*)[/\\]') end)
        end
        C.baseDir=tostring(dir or '.'):gsub('[/\\]+$','');return C.baseDir
    end
    function C.path()
        local sep=package.config:sub(1,1)
        local dir=C.base()..sep..'config'
        local function mkdir(p)
            if type(createDirectory)=='function' then pcall(createDirectory,p) end
            if libs.lfs and libs.lfs.mkdir then pcall(libs.lfs.mkdir,p) end
        end
        mkdir(dir);dir=dir..sep..'grnd_tools';mkdir(dir)
        C.filename=dir..sep..'config.json';return C.filename
    end
    local function read(path)
        local f,err,code=io.open(path,'rb');if not f then return nil,err,code end
        local s=f:read(2097153);f:close();return s or ''
    end
    function C.warn(message)
        C.error=tostring(message)
        if C.lastError~=C.error then
            C.lastError=C.error
            print('[GRND config] '..C.error)
            if type(grndChatSay)=='function' then pcall(grndChatSay,'[GRND] Ошибка config.json: '..C.error,-1) end
        end
    end
    local function unescape(s)
        return (s:gsub('\\(.)',function(c) if c=='n' then return '\n' end;return c end))
    end
    local function escape(s) return tostring(s):gsub('\\','\\\\'):gsub('\n','\\n'):gsub('\r','') end
    local function scalar(v,k)
        if k~='name' and k~='text' and k~='fontName' and k~='fontPath' and k~='playDate' and v:match('^%-?%d+%.?%d*$') then
            local n=tonumber(v);if n and n==n and math.abs(n)<math.huge then return n end
        end
        return v
    end
    function C.fromLegacy(section,body)
        local result={};local current=result
        if section=='binder' or section=='character' then result.items=C.array() end
        if section=='ring' then result.slots=C.array() end
        if section=='reportTemplates' or section=='reportPunish' then result.items=C.array() end
        for line in (body..'\n'):gmatch('([^\n]*)\n') do
            line=line:gsub('\r$','')
            if line=='---' and result.items then
                current={};result.items[#result.items+1]=current
            else
                local k,v=line:match('^([%w_%.]+)=(.*)$')
                if k then
                    local private=(section~='binder' and section~='character') and
                        (k:lower():find('password',1,true) or k:lower():find('passwd',1,true) or
                         k:lower():find('secret',1,true) or k:lower():find('token',1,true) or k=='login')
                    if not private and not (section=='admins' and (k=='playDate' or k=='playSec')) then
                        if result.items and (k=='name' or k=='text') then current[k]=unescape(v)
                        elseif section=='character' and current~=result and k=='id' then current[k]=v
                        elseif section=='punishments' and k:match('%.[rt]$') then
                            local values=C.array()
                            for item in v:gmatch('[^|]+') do values[#values+1]=k:match('%.t$') and (tonumber(item) or 1) or item end
                            current[k]=values
                        else current[k]=scalar(v,k) end
                    end
                elseif section=='ring' then
                    local side,index,key,mods,name,command=line:match('^([LRV])|(%d+)|(%d+)|(%d+)|([^|]*)|([^|]*)$')
                    if side then
                        local function dec(t) return (t:gsub('%%7[Cc]','|'):gsub('%%25','%%')) end
                        result.slots[#result.slots+1]={side=side,index=tonumber(index),key=tonumber(key),mods=tonumber(mods),name=dec(name),command=dec(command)}
                    end
                end
            end
        end
        if result.items and #result.items>0 and next(result.items[#result.items])==nil then table.remove(result.items) end
        -- A font filename is portable; a C:\\Users\\... install path is not.
        if section=='ui' and result.fontPath then result.fontPath=tostring(result.fontPath):match('[^/\\]+$') end
        return result
    end
    function C.toLegacy(section,record)
        local out={}
        local function fields(t,item)
            local keys={};for k in pairs(t) do if k~='items' and k~='slots' then keys[#keys+1]=k end end;table.sort(keys)
            for _,k in ipairs(keys) do
                local v=t[k]
                if type(v)=='table' then v=table.concat(v,'|')
                elseif type(v)=='boolean' then v=v and '1' or '0'
                elseif item and (k=='name' or k=='text') then v=escape(v)
                else v=tostring(v) end
                out[#out+1]=k..'='..v
            end
        end
        fields(record,false)
        for _,item in ipairs(record.items or {}) do out[#out+1]='---';fields(item,true) end
        if section=='ring' then
            for _,item in ipairs(record.slots or {}) do
                local function esc(t) return (tostring(t or ''):gsub('%%','%%25'):gsub('|','%%7C')) end
                out[#out+1]=table.concat({item.side,item.index,item.key,item.mods,esc(item.name),esc(item.command)},'|')
            end
        end
        return table.concat(out,'\n')..'\n'
    end
    local function plain(t)
        assert(type(t)=='table' and t~=NULL and getmetatable(t)~=ARRAY,'Expected JSON object')
    end
    function C.validate(doc)
        plain(doc);assert(doc.schemaVersion==1 and doc.tool=='grnd_tools','Unsupported config schema')
        plain(doc.sections);plain(doc.layout or {});plain(doc.hotkeys or {});plain(doc.clickwarp or {})
        local count=0
        local function scalarObject(t)
            plain(t)
            for k,v in pairs(t) do
                assert(type(k)=='string' and k:match('^[%w_%.]+$'),'Invalid key')
                assert(type(v)=='string' or type(v)=='number' or type(v)=='boolean','Invalid scalar')
                if type(v)=='string' then assert(not v:find('%z') and #v<=131072,'Invalid string') end
            end
        end
        for section,t in pairs(doc.sections) do
            plain(t);count=count+1;assert(count<32,'Too many sections')
            local normal={}
            for k,v in pairs(t) do
                if k=='items' or k=='slots' then
                    assert(type(v)=='table' and v~=NULL and #v<=1000,'Invalid items')
                    for _,item in ipairs(v) do
                        scalarObject(item)
                        if k=='slots' then
                            assert(item.side=='L' or item.side=='R' or item.side=='V','Invalid ring side')
                            for _,n in ipairs({'index','key','mods'}) do assert(type(item[n])=='number','Invalid ring key') end
                        end
                    end
                elseif section=='punishments' and k:match('%.[rt]$') then
                    assert(type(v)=='table' and v~=NULL and #v<=1000,'Invalid punishment list')
                    for _,q in ipairs(v) do assert(type(q)=='string' or type(q)=='number','Invalid reason/time') end
                else normal[k]=v end
            end
            scalarObject(normal)
        end
        scalarObject(doc.hotkeys or {});scalarObject(doc.clickwarp or {})
        for _,v in pairs(doc.layout or {}) do scalarObject(v) end
        return true
    end
    function C.ensure()
        if C.loaded then return C.doc end
        C.loaded=true
        C.doc={schemaVersion=1,tool='grnd_tools',sections={},layout={},hotkeys={},clickwarp={}}
        local filename=C.path();local body,readError,readCode=read(filename)
        if not body and readCode and readCode~=2 then
            C.readOnly=true;C.warn(readError);return C.doc
        end
        if not body then
            body,readError,readCode=read(filename..'.bak')
            if not body and readCode and readCode~=2 then
                C.readOnly=true;C.warn(readError);return C.doc
            end
            if body then C.recovered=true end
        end
        if body then
            local ok,doc=pcall(C.decode,body)
            local valid,why=false,doc
            if ok then valid,why=pcall(C.validate,doc) end
            if not valid then
                C.readOnly=true;C.warn('config.json повреждён или имеет неизвестную версию; файл НЕ перезаписан: '..tostring(why))
                return C.doc
            end
            C.doc=doc;doc.layout=doc.layout or {};doc.hotkeys=doc.hotkeys or {};doc.clickwarp=doc.clickwarp or {}
            C.lastSaved=C.recovered and nil or C.encode(doc);C.existed=true
            if C.recovered then C.dirty=true;C.lastSaved=nil end
            return doc
        end
        -- Import ONLY if config.json is absent. Imported JSON never mixes with
        -- the recipient's old per-module configuration files.
        local dirs={C.base()}
        if type(thisScript)=='function' then
            pcall(function() local d=tostring(thisScript().path or ''):match('^(.*)[/\\]');if d then table.insert(dirs,1,d) end end)
        end
        if type(this_script_dir)=='function' then local ok,d=pcall(this_script_dir);if ok and d then dirs[#dirs+1]=d end end
        local sep=package.config:sub(1,1)
        for base,section in pairs(C.sources) do
            if section~='legacyFont' then
                for _,dir in ipairs(dirs) do
                    local text=read(dir..sep..base..'.cfg')
                    if text and #text<=2097152 then C.doc.sections[section]=C.fromLegacy(section,text);break end
                end
            end
        end
        if not C.doc.sections.ui then
            for _,dir in ipairs(dirs) do
                local text=read(dir..sep..'grnd_chat.cfg')
                if text then
                    local old=C.fromLegacy('ui',text);local ui={}
                    for _,k in ipairs({'fontPath','fontName','fontSize','fontUser'}) do ui[k]=old[k] end
                    C.doc.sections.ui=ui;break
                end
            end
        end
        C.dirty=true;return C.doc
    end
    function C.open(path,mode)
        local base=tostring(path):match('([^/\\]+)%.cfg$')
        local section=C.sources[base]
        if not section then error('Unknown configuration domain: '..tostring(path)) end
        C.ensure();mode=mode or 'r'
        if mode:sub(1,1)=='r' then
            local record=C.doc.sections[section]
            if not record then return nil,'section not present' end
            local body=C.toLegacy(section,record);local cursor=1;local closed=false
            return {
                read=function(self,format) assert(not closed,'closed file');if format=='*a' then local out=body:sub(cursor);cursor=#body+1;return out end;error('Unsupported read') end,
                lines=function() return function() if closed or cursor>#body then return nil end;local last=body:find('\n',cursor,true) or #body+1;local line=body:sub(cursor,last-1);cursor=last+1;return line end end,
                close=function() closed=true;return true end
            }
        end
        if C.readOnly then return nil,'config.json is protected after a read error' end
        assert(mode:sub(1,1)=='w','Unsupported configuration mode')
        local chunks={};local closed=false
        return {
            write=function(self,...) assert(not closed,'closed file');for i=1,select('#',...) do chunks[#chunks+1]=tostring(select(i,...)) end;return self end,
            close=function()
                if closed then return true end;closed=true
                local record=C.fromLegacy(section,table.concat(chunks))
                if C.encode(record)~=C.encode(C.doc.sections[section]) then C.doc.sections[section]=record;C.dirty=true end
                return true
            end
        }
    end
    function C.flush()
        C.ensure();if C.readOnly or not C.dirty then return not C.readOnly end
        local ok,body=pcall(C.encode,C.doc)
        if not ok then C.warn(body);return false end
        if #body>2097152 then C.warn('Конфиг больше 2 MB; предыдущая версия сохранена');return false end
        if body==C.lastSaved then C.dirty=false;return true end
        local path=C.filename or C.path();local tmp=path..'.tmp';local bak=path..'.bak'
        local f,err=io.open(tmp,'wb');if not f then C.warn(err);return false end
        local written,why=pcall(function() assert(f:write(body..'\n'));assert(f:flush());assert(f:close()) end)
        if not written then pcall(f.close,f);os.remove(tmp);C.warn(why);return false end
        local existing,readError,readCode=read(path)
        if not existing and readCode and readCode~=2 then
            os.remove(tmp);C.warn(readError);return false
        end
        if existing then
            os.remove(bak)
            local moved,e=os.rename(path,bak)
            if not moved then os.remove(tmp);C.warn(e);return false end
        end
        local moved,e=os.rename(tmp,path)
        if not moved then
            if existing then os.rename(bak,path) end
            C.warn(e);return false
        end
        C.lastSaved=body;C.dirty=false;C.error=nil;C.lastError=nil;return true
    end
    function C.setLayout(name,values)
        C.ensure()
        if C.encode(C.doc.layout[name])~=C.encode(values) then C.doc.layout[name]=values;C.dirty=true end
    end
    C.hotkeyNames={'GRND_MENU_HOTKEY','GRND_GM_TOGGLE_KEY','GRND_SPEC_WARP_KEY','GRND_SPEC_CAR_KEY'}
    function C.restoreHotkeys()
        C.ensure()
        for _,key in ipairs(C.hotkeyNames) do
            local v=C.doc.hotkeys[key]
            if type(v)=='number' and v>=1 and v<=255 and v==math.floor(v) then _G[key]=v end
        end
    end
    C.clickFields={'enabled','mode','keyToggle','keyApply','keyVehicle','markerColor','maxDist'}
    function C.bindClickwarp(ref)
        C.ensure();C.clickRef=ref
        for _,key in ipairs(C.clickFields) do
            local v=C.doc.clickwarp[key]
            if type(v)==type(ref[key]) then
                if key=='mode' then
                    if v=='click' or v=='blip' or v=='aim' then ref[key]=v end
                elseif key:match('^key') then
                    if v>=1 and v<=255 and v==math.floor(v) then ref[key]=v end
                elseif key=='markerColor' then ref[key]=math.floor(math.max(0,math.min(255,v)))
                elseif key=='maxDist' then ref[key]=math.max(1,math.min(2000,v))
                else ref[key]=v end
            end
        end
    end
    C.panelFields={
        cameraExpanded={'GRND_CAM','expanded'},chatExpanded={'GRND_CHAT','expanded'},
        whExpanded={'GRND_WH','expanded'},tracerExpanded={'GRND_TRACER','expanded'},
        tracerPage={'GRND_TRACER','page'}
    }
    function C.restorePanels()
        local layout=C.ensure().layout
        local saved=layout.panels or {}
        local rc=_G.GRND_RC;local pos=layout.reconPunishments
        if rc and type(pos)=='table' and type(pos.x)=='number' and type(pos.y)=='number' then
            rc.punishPosX,rc.punishPosY=pos.x,pos.y
        end
        for key,field in pairs(C.panelFields) do
            local ref=_G[field[1]];local v=saved[key]
            if ref then
                if field[2]=='page' then
                    if v==1 or v==2 then ref[field[2]]=v end
                elseif type(v)=='boolean' then ref[field[2]]=v end
            end
        end
    end
    function C.extraSnapshot()
        local panels={}
        for key,field in pairs(C.panelFields) do
            local ref=_G[field[1]]
            if ref and (type(ref[field[2]])=='boolean' or type(ref[field[2]])=='number') then
                panels[key]=ref[field[2]]
            end
        end
        C.setLayout('panels',panels)
        local rc=_G.GRND_RC
        if rc and type(rc.punishPosX)=='number' and type(rc.punishPosY)=='number' then
            C.setLayout('reconPunishments',{x=rc.punishPosX,y=rc.punishPosY})
        end
        for _,key in ipairs(C.hotkeyNames) do
            local v=_G[key]
            if type(v)=='number' and C.doc.hotkeys[key]~=v then C.doc.hotkeys[key]=v;C.dirty=true end
        end
        if C.clickRef then
            for _,key in ipairs(C.clickFields) do
                local v=C.clickRef[key]
                if C.doc.clickwarp[key]~=v then C.doc.clickwarp[key]=v;C.dirty=true end
            end
        end
    end
end
-- End unified configuration module.

-- Daily chat logs: UTF-8 text, independent categories, bounded viewer.
GRND_LOG = {queue={},seen={},flags={},dates={},page=1,category='chat',history={}}
do
    local L=GRND_LOG
    L.types={{'chat','Общий чат'},{'action_admins','Действия администрации'},
        {'form_admin','Формы администраторов'},{'report','Репорты и ответы'},{'kill_list','Kill List'}}
    L.allowed={};for _,v in ipairs(L.types) do L.allowed[v[1]]=true end
    function L.utf(s) return grndUtf8Text and grndUtf8Text(s) or tostring(s or '') end
    function L.clean(s) return (L.utf(s):gsub('{%x%x%x%x%x%x%x%x}',''):gsub('{%x%x%x%x%x%x}',''):gsub('[\r\n%z]',' ')) end
    function L.lower(s) return grndLowerUtf and grndLowerUtf(s) or s:lower() end
    function L.warn(s,kind)
        s=tostring(s);kind=kind or 'viewer'
        if kind=='write' then L.writeError=s;L.error=s
        elseif kind=='dates' then L.dateError=s
        elseif kind=='read' then L.viewError=s
        else L.uiError=s end
        L.lastErrors=L.lastErrors or {}
        if L.lastErrors[kind]~=s then
            L.lastErrors[kind]=s;print('[GRND chat log/'..kind..'] '..s)
        end
    end
    function L.mkdir(p)
        if createDirectory then pcall(createDirectory,p) end
        if libs.lfs then pcall(libs.lfs.mkdir,p) end
    end
    function L.init()
        if L.ready then return end
        L.ready=true
        local C=GRND_CONFIG;C.ensure();local sep=package.config:sub(1,1)
        L.root=C.base()..sep..'config'..sep..'grnd_tools'..sep..'log';L.sep=sep
        L.mkdir(L.root)
        local flags=C.doc.layout.logging or {}
        for _,v in ipairs(L.types) do L.flags[v[1]]=flags[v[1]]~=false end
        C.setLayout('logging',L.flags)
    end
    function L.validDate(s)
        local d,m,y=tostring(s):match('^(%d%d)%-(%d%d)%-(%d%d%d%d)$')
        if not d then return false end
        d,m,y=tonumber(d),tonumber(m),tonumber(y)
        if m<1 or m>12 or y<1970 or y>9999 then return false end
        local days={31,28,31,30,31,30,31,31,30,31,30,31}
        if y%4==0 and (y%100~=0 or y%400==0) then days[2]=29 end
        return d>=1 and d<=days[m]
    end
    function L.path(date,kind)
        L.init();assert(L.validDate(date) and L.allowed[kind],'Invalid log path')
        return L.root..L.sep..date..L.sep..kind..'.txt'
    end
    function L.day(date)
        if L.currentDay==date then return end
        if L.tryDay==date and os.clock()-(L.tryAt or 0)<3 then return end
        L.tryDay=date;L.tryAt=os.clock()
        L.mkdir(L.root..L.sep..date)
        local success=true
        for _,v in ipairs(L.types) do
            local f,e=io.open(L.path(date,v[1]),'ab')
            if f then f:close() else success=false;L.warn(e,'write') end
        end
        L.dayError=not success
        if success then L.currentDay=date end
    end
    function L.toggle(kind)
        L.init();L.flags[kind]=not L.flags[kind]
        -- Copy: do not alias the config table before change detection.
        local copy={};for k,v in pairs(L.flags) do copy[k]=v end
        GRND_CONFIG.setLayout('logging',copy);GRND_CONFIG.dirty=true;GRND_CONFIG.flush()
    end
    function L.append(kind,text,stamp)
        L.init();if not L.flags[kind] then return end
        stamp=stamp or os.time();local date=os.date('%d-%m-%Y',stamp)
        if (L.count or 0)>=4000 then L.warn('Очередь логов переполнена: проверьте доступ к диску','write');return end
        local key=date..'/'..kind;local q=L.queue[key]
        if not q then q={date=date,kind=kind,lines={}};L.queue[key]=q end
        local line=L.utf(text):gsub('[\r\n%z]',' ')
        if #line>16384 then line=line:sub(1,16384)..' [обрезано]' end
        q.lines[#q.lines+1]='['..os.date('%H:%M:%S',stamp)..'] '..line..'\n'
        L.count=(L.count or 0)+1
    end
    function L.flush()
        L.init();local all=true
        for key,q in pairs(L.queue) do
            L.day(q.date)
            local f,e=io.open(L.path(q.date,q.kind),'ab')
            if f then
                local ok,err=pcall(function() assert(f:write(table.concat(q.lines)));assert(f:flush());assert(f:close()) end)
                if ok then L.count=L.count-#q.lines;L.queue[key]=nil else pcall(f.close,f);L.warn(err,'write');all=false end
            else L.warn(e,'write');all=false end
        end
        if all and L.currentDay and not L.dayError then
            L.error=nil;L.writeError=nil
            if L.lastErrors then L.lastErrors.write=nil end
        end
    end
    function L.response(text)
        local t=L.clean(text):gsub('^%s*%[%d%d:%d%d:%d%d%]%s*',''):gsub('^%s+','')
        local target=t:match('^Администратор%s+%S+%s+для%s+([^:]+):')
        if not target then
            local a=t:match('^<ADM>%s*(.*)$')
            if a then
                a=a:gsub('^%(%d+%)%s*','')
                target=a:match('^%S+%s+ответил%s+([^:]+):') or a:match('^%S+%s+ответила%s+([^:]+):')
            end
        end
        if not target then return end
        target=target:match('^%s*(.-)%s*$')
        -- v1.18.00: ID бывает и в КРУГЛЫХ скобках — так игрока называет
        -- админ-бот («Mixa_Grozz(25): дм»). Тогда «ответил Mixa_Grozz(25)»
        -- должен снимать строку из окна так же, как «ответил Player[113]».
        local nick,id=target:match('^(.-)%[(%d+)%]$')
        if not nick then nick,id=target:match('^(.-)%((%d+)%)$') end
        nick=(nick or target):gsub('%s+$','')
        if nick=='' or nick:find('%s') then return end
        return nick,tonumber(id)
    end
    function L.resolve(text)
        local nick,id=L.response(text);if not nick then return end
        local H=_G.GRND_REPHUD
        if H and H.items then
            for i=#H.items,1,-1 do
                local item=H.items[i]
                if L.lower(L.clean(item.nick))==L.lower(nick) and (not id or tonumber(item.pid)==id) then
                    table.remove(H.items,i)
                end
            end
        end
    end
    function L.duplicate(text,source)
        local key=L.clean(text):gsub('^%s*%[%d%d:%d%d:%d%d%]%s*',''):gsub('%[%d+%]','')
        local now=os.clock()
        for i=#L.seen,1,-1 do
            local e=L.seen[i]
            if now-e.at>1 then table.remove(L.seen,i) end
        end
        for _,e in ipairs(L.seen) do
            if e.key==key and not e.sources[source] then e.sources[source]=true;return true end
        end
        L.seen[#L.seen+1]={key=key,at=now,sources={[source]=true}}
        if #L.seen>512 then table.remove(L.seen,1) end
        return false
    end
    function L.capture(text,source)
        text=L.utf(text);if text=='' then return end
        L.resolve(text)
        if L.duplicate(text,source or 'direct') then return end
        local stamp=os.time()
        L.append('chat',text,stamp)
        local t=L.clean(text):gsub('^%s*%[%d%d:%d%d:%d%d%]%s*',''):gsub('^%s+','')
        if t:match('^Администратор%s+') then L.append('action_admins',text,stamp) end
        if L.response(text) or t:find('[К-во репорта:',1,true) then L.append('report',text,stamp) end
        if grndFormAdminLine then
            local _,_,body=grndFormAdminLine(text)
            if body and (body:find('/%a[%w_]*%s+') or body:match('^%s*%[ATOOLS%]%s*:')) then L.append('form_admin',text,stamp) end
        end
    end
    function L.nick(id)
        if sampGetPlayerNickname then local ok,n=pcall(sampGetPlayerNickname,id);if ok and n and n~='' then return L.utf(n) end end
        return 'Неизвестно'
    end
    L.weapons={[0]='Кулак',[1]='Кастет',[2]='Клюшка',[3]='Дубинка',[4]='Нож',[5]='Бита',[6]='Лопата',
        [7]='Кий',[8]='Катана',[9]='Бензопила',[16]='Граната',[17]='Слезоточивый газ',[18]='Коктейль Молотова',
        [22]='Colt 45',[23]='Silenced Pistol',[24]='Desert Eagle',[25]='Shotgun',[26]='Sawnoff Shotgun',
        [27]='Combat Shotgun',[28]='Micro Uzi',[29]='MP5',[30]='AK-47',[31]='M4',[32]='TEC-9',
        [33]='Rifle',[34]='Sniper Rifle',[35]='Rocket Launcher',[36]='Heat Seeker',[37]='Flamethrower',
        [38]='Minigun',[39]='Satchel Charge',[41]='Spraycan',[42]='Огнетушитель',[49]='Транспорт',
        [50]='Лопасти вертолёта',[51]='Взрыв',[53]='Утопление',[54]='Падение'}
    function L.death(killer,victim,reason)
        killer,victim,reason=tonumber(killer),tonumber(victim),tonumber(reason) or 0
        if not victim or victim<0 or victim==65535 then return end
        local v=L.nick(victim)..'['..victim..']';local weapon=(L.weapons[reason] or 'Неизвестно')..'['..reason..']'
        if killer and killer>=0 and killer~=65535 and killer~=victim then
            L.append('kill_list',L.nick(killer)..'['..killer..'] убил с помощью "'..weapon..'" > '..v)
        else L.append('kill_list',v..' погиб. Причина: "'..weapon..'"') end
    end
    function L.scanDates()
        L.init();L.flush();L.dateError=nil;local found={}
        local function add(n) if L.validDate(n) then found[n]=true end end
        if libs.lfs then
            local ok,e=pcall(function() for n in libs.lfs.dir(L.root) do
                if libs.lfs.attributes(L.root..L.sep..n,'mode')=='directory' then add(n) end
            end end);if not ok then L.warn(e,'dates') end
        elseif findFirstFile and findNextFile and findClose then
            local h,n=findFirstFile(L.root..L.sep..'*')
            if h and h~=-1 then
                repeat if n then add(n) end;n=findNextFile(h) until not n
                findClose(h)
            end
        else L.warn('Для списка дат требуется lfs или функции поиска файлов MoonLoader','dates') end
        if L.currentDay then add(L.currentDay) end
        L.dates={};for d in pairs(found) do L.dates[#L.dates+1]=d end
        local function order(d) return d:sub(7,10)..d:sub(4,5)..d:sub(1,2) end
        table.sort(L.dates,function(a,b) return order(a)>order(b) end);L.page=1
    end
    function L.openDates(kind)
        L.uiError=nil;L.category=kind;L.scanDates();L.dateOpen=true;L.viewerOpen=false;L.stopRead()
    end
    function L.stopRead()
        if L.reader then L.reader:close();L.reader=nil end
        L.busy=false
    end
    function L.loadPage(offset)
        L.stopRead();L.flush();L.offset=offset or 0;L.nextOffset=nil
        L.display='';L.lines={};L.bytes=0;L.viewError=nil;L.buffer=nil
        local f,e=io.open(L.path(L.date,L.category),'rb')
        if not f then L.viewError=e;return end
        local pos,err=f:seek('set',L.offset)
        if not pos then f:close();L.viewError=err;return end
        L.reader=f;L.busy=true
    end
    function L.readStep()
        if not L.reader then return end
        local f=L.reader
        for i=1,300 do
            local offset=f:seek();local line,err=f:read('*l')
            if not line then if err then L.warn(err,'read') end;L.stopRead();break end
            line=L.clean(line)
            if not L.query or L.query=='' or L.lower(line):find(L.lower(L.query),1,true) then
                if L.bytes+#line+1>60000 and #L.lines>0 then L.nextOffset=offset;L.stopRead();break end
                L.lines[#L.lines+1]=line;L.bytes=L.bytes+#line+1
            end
        end
        if not L.busy then L.display=table.concat(L.lines,'\n');L.buffer=nil end
    end
    function L.tick(force)
        L.init();L.day(os.date('%d-%m-%Y'))
        if force or os.clock()-(L.lastFlush or 0)>1 then L.lastFlush=os.clock();L.flush() end
        if L.viewerOpen and L.searchPending and os.clock()>=L.searchPending then
            L.searchPending=nil;L.query=L.bufferText(L.search,L.searchKind)
            L.history={};L.loadPage(0)
        end
        local ok,err=pcall(L.readStep)
        if not ok then pcall(L.stopRead);L.warn(err,'read') end
    end
    function L.close()
        L.viewerOpen=false;L.dateOpen=false;L.stopRead();L.uiUntil=os.clock()+0.2
    end
    function L.wanted() return L.viewerOpen or L.dateOpen or (L.uiUntil or 0)>os.clock() end
    function L.newBuffer(im,text,capacity)
        if im.new and im.new.char then
            local ffi=require 'ffi';local buf=im.new.char[capacity]();ffi.copy(buf,text,math.min(#text,capacity-1));return buf,'ffi'
        end
        return im.ImBuffer(text,capacity),'legacy'
    end
    function L.bufferText(b,kind)
        if kind=='ffi' then return require('ffi').string(b) end
        return tostring(b.v or b.value or '')
    end
    function L.windows(C)
        if not L.dateOpen and not L.viewerOpen then return false end
        local im=C.im;local colors,vars=0,0
        local TH=GRND_UIKIT.TH
        local function solid(c)
            c=c or TH.bg;local a=(c[4] or 255)/255
            return {(TH.bg[1] or 20)*(1-a)+(c[1] or 20)*a,
                (TH.bg[2] or 20)*(1-a)+(c[2] or 20)*a,
                (TH.bg[3] or 24)*(1-a)+(c[3] or 24)*a,255}
        end
        -- Visible, theme-derived outlines; independent of faint global borders.
        local edge=solid({TH.textHi[1],TH.textHi[2],TH.textHi[3],65})
        local divider=solid({TH.accent[1],TH.accent[2],TH.accent[3],95})
        for _,e in ipairs({{'WindowBg',solid(TH.bg)},{'Text',TH.textHi},{'Border',edge},{'Separator',divider},
            {'FrameBg',solid(TH.card)},{'FrameBgHovered',solid(TH.itemHover)},
            {'FrameBgActive',solid(TH.card)},{'ScrollbarBg',solid(TH.card)},
            {'ScrollbarGrab',TH.itemSel},{'ScrollbarGrabActive',TH.accent},
            {'Button',solid(TH.itemHover)},{'ButtonHovered',solid(TH.itemSel)},
            {'ButtonActive',solid(TH.itemPress)},
            {'TextSelectedBg',{TH.accent[1],TH.accent[2],TH.accent[3],100}}}) do
            if C.push(im.Col[e[1]],C.color(e[2])) then colors=colors+1 end
        end
        local function style(name,value)
            if im.StyleVar and im.StyleVar[name] and im.PushStyleVar then
                local ok=pcall(im.PushStyleVar,im.StyleVar[name],value)
                if ok then vars=vars+1 end
            end
        end
        style('Alpha',1);style('WindowRounding',12);style('FrameRounding',6)
        style('WindowBorderSize',1);style('FrameBorderSize',1)
        style('WindowPadding',im.ImVec2(16,14));style('FramePadding',im.ImVec2(10,7))
        style('ItemSpacing',im.ImVec2(8,10));style('ScrollbarSize',7)
        local function tip(text)
            if im.IsItemHovered and im.IsItemHovered() and im.SetTooltip then im.SetTooltip(text) end
        end
        local function draw()
            local dates=L.dateOpen;local key=dates and 'logDates' or 'logViewer'
            local sx,sy=getScreenResolution()
            local w=dates and 286 or math.min(1000,sx-32)
            local h=dates and math.min(438,sy-32) or math.min(650,sy-32)
            local p=GRND_CONFIG.ensure().layout[key] or {}
            im.SetNextWindowPos(im.ImVec2(math.max(0,math.min(sx-w,tonumber(p.x) or (sx-w)/2)),math.max(0,math.min(sy-h,tonumber(p.y) or (sy-h)/2))),C.once)
            im.SetNextWindowSize(im.ImVec2(w,h),C.always)
            if im.SetNextWindowBgAlpha then im.SetNextWindowBgAlpha(1) end
            if C.begin(dates and '##grnd_log_dates' or '##grnd_log_viewer',C.flags) then
                local pos=im.GetWindowPos();GRND_CONFIG.setLayout(key,{x=pos.x,y=pos.y})
                local caption='Дата'
                if not dates then
                    if im.Button('<##logback',im.ImVec2(30,28)) then L.openDates(L.category) end
                    tip('Выбрать другую дату');im.SameLine()
                    for _,t in ipairs(L.types) do if t[1]==L.category then caption=t[2] end end
                    caption=caption..'  /  '..L.date:gsub('%-','.')
                end
                if im.AlignTextToFramePadding then im.AlignTextToFramePadding() end
                im.TextUnformatted(caption)
                im.SameLine(w-44)
                if im.Button('x##logclose',im.ImVec2(28,28)) then L.close() end
                tip('Закрыть · Esc')
                im.Separator()
                if dates then
                    if L.dateError then im.TextWrapped('Не удалось прочитать список дат');tip(L.dateError)
                    elseif #L.dates==0 then im.TextUnformatted('Пока пусто') end
                    for i=(L.page-1)*7+1,math.min(#L.dates,L.page*7) do
                        local d=L.dates[i]
                        if im.Button(d:gsub('%-','.')..'##date'..d,im.ImVec2(w-32,32)) then
                            L.date=d;L.dateOpen=false;L.viewerOpen=true;L.query='';L.search=nil
                            L.searchPending=nil;L.history={};L.loadPage(0)
                        end
                    end
                    if #L.dates>7 then
                        if im.Button('<##datesprev',im.ImVec2(30,26)) and L.page>1 then L.page=L.page-1 end
                        im.SameLine();im.TextUnformatted(L.page..' / '..math.ceil(#L.dates/7));im.SameLine()
                        if im.Button('>##datesnext',im.ImVec2(30,26)) and L.page<math.ceil(#L.dates/7) then L.page=L.page+1 end
                    end
                else
                    if not L.search then L.search,L.searchKind=L.newBuffer(im,L.query or '',256) end
                    local searchColors=0
                    for _,entry in ipairs({{'FrameBg',{0,0,0,255}},
                        {'FrameBgHovered',{0,0,0,255}},{'FrameBgActive',{0,0,0,255}},
                        {'Border',{105,105,120,255}}}) do
                        if C.push(im.Col[entry[1]],C.color(entry[2])) then
                            searchColors=searchColors+1;colors=colors+1
                        end
                    end
                    local searchWidth=math.max(100,w-100)
                    local beforeSearchVars=vars
                    style('FrameRounding',8)
                    im.PushItemWidth(searchWidth)
                    local okInput,changed=pcall(function()
                        if L.searchKind=='ffi' then return im.InputText('Поиск##log_search',L.search,256) end
                        return im.InputText('Поиск##log_search',L.search)
                    end)
                    im.PopItemWidth()
                    if vars>beforeSearchVars then
                        im.PopStyleVar(vars-beforeSearchVars);vars=beforeSearchVars
                    end
                    if okInput and C.color32 and im.GetWindowDrawList and im.GetItemRectMin and im.GetItemRectMax then
                        -- Outline only the input frame, not its text label.
                        local dl=im.GetWindowDrawList()
                        local lo,hi=im.GetItemRectMin(),im.GetItemRectMax()
                        local active=im.IsItemActive and im.IsItemActive()
                        local outline=active and {TH.accent[1],TH.accent[2],TH.accent[3],230}
                            or {135,135,151,255}
                        if dl and dl.AddRect then
                            pcall(dl.AddRect,dl,im.ImVec2(lo.x+0.5,lo.y+0.5),
                                im.ImVec2(lo.x+searchWidth-0.5,hi.y-0.5),C.color32(outline),8,0,1.2)
                        end
                    end
                    C.pop(searchColors);colors=colors-searchColors
                    if not okInput then error(changed) end
                    if changed then L.searchPending=os.clock()+0.3 end
                    im.Separator()
                    local paged=#L.history>0 or L.nextOffset~=nil
                    if L.viewError then im.TextWrapped(L.viewError)
                    elseif L.busy then im.TextUnformatted('Поиск…')
                    elseif L.display=='' then im.TextUnformatted((L.query or '')~='' and 'Ничего не найдено' or 'Пока пусто')
                    else
                        if not L.buffer then L.buffer,L.bufferKind=L.newBuffer(im,L.display or '',65536) end
                        local aw,ah=w-32,h-(paged and 202 or 154)
                        if im.GetContentRegionAvail then
                            local ok,x,y=pcall(im.GetContentRegionAvail)
                            if ok then
                                if type(x)=='number' and type(y)=='number' then aw,ah=x,y-(paged and 54 or 2)
                                elseif x then
                                    local vector,vx,vy=pcall(function() return x.x,x.y end)
                                    if vector and tonumber(vx) and tonumber(vy) then aw,ah=vx,vy-(paged and 54 or 2) end
                                end
                            end
                        end
                        local size=im.ImVec2(math.max(40,aw),math.max(60,ah))
                        local flags=(im.InputTextFlags and im.InputTextFlags.ReadOnly) or im.ImGuiInputTextFlags_ReadOnly or 16384
                        if L.bufferKind=='ffi' then im.InputTextMultiline('##log_text',L.buffer,65536,size,flags)
                        else im.InputTextMultiline('##log_text',L.buffer,size,flags) end
                    end
                    if paged then
                        im.Separator()
                        if im.Button('<##logprev',im.ImVec2(30,26)) and #L.history>0 then L.loadPage(table.remove(L.history)) end
                        im.SameLine();im.TextUnformatted(tostring(#L.history+1));im.SameLine()
                        if im.Button('>##lognext',im.ImVec2(30,26)) and L.nextOffset then
                            L.history[#L.history+1]=L.offset;L.loadPage(L.nextOffset)
                        end
                    end
                    -- Refresh is available on demand, without an extra toolbar button.
                    -- MoonLoader virtual-key polling works with old FYP mimgui,
                    -- whose lazy enum table throws when ImGuiKey_F5 is absent.
                    local down=false
                    if type(isKeyDown)=='function' then
                        local ok,value=pcall(isKeyDown,0x74)
                        down=ok and value and true or false
                    end
                    local pressed=down and not L.f5Down
                    L.f5Down=down
                    if pressed and im.IsWindowFocused then
                        local ok,focused=pcall(im.IsWindowFocused,0)
                        if ok and focused then L.history={};L.loadPage(0) end
                    end
                end
            end
            C.finish()
        end
        local ok,err=pcall(draw)
        if not ok then C.recover();L.warn(err,'viewer')
        else L.uiError=nil end
        if vars>0 then im.PopStyleVar(vars) end
        C.pop(colors)
        return L.dateOpen or L.viewerOpen
    end
end
-- End daily chat logs.


