-- =====================================================================
-- АВТОРИЗАЦИЯ
-- =====================================================================
local authChat = { failAt = 0 }
local AUTH_FAIL_NEEDLES = {
    "Вы ввели неверный пароль", "неверный пароль", "Неверный пароль",
    "wrong password", "Wrong password",
    "\xc2\xfb \xe2\xe2\xe5\xeb\xe8 \xed\xe5\xe2\xe5\xf0\xed\xfb\xe9 \xef\xe0\xf0\xee\xeb\xfc",
    "\xed\xe5\xe2\xe5\xf0\xed\xfb\xe9 \xef\xe0\xf0\xee\xeb\xfc",
}
do
    local enc = encoding or libs.encoding
    if enc and enc.UTF8 then
        local phrases = { "Вы ввели неверный пароль", "неверный пароль", "Неверный пароль" }
        for _, p in ipairs(phrases) do
            local ok, ansi = pcall(function()
                local prev = enc.default
                enc.default = "CP1251"
                local out = enc.UTF8:decode(p)
                enc.default = prev
                return out
            end)
            if ok and type(ansi) == "string" and ansi ~= "" then
                AUTH_FAIL_NEEDLES[#AUTH_FAIL_NEEDLES + 1] = ansi
            end
        end
    end
end
local AUTH_FAIL_PAIRS = {
    { "неверн", "парол" },
    { "\xed\xe5\xe2\xe5\xf0\xed", "\xef\xe0\xf0\xee\xeb" },
    { "\xd0\xbd\xd0\xb5\xd0\xb2\xd0\xb5\xd1\x80\xd0\xbd", "\xd0\xbf\xd0\xb0\xd1\x80\xd0\xbe\xd0\xbb" },
}
local function authStrip(s)
    if type(s) ~= "string" then return "" end
    s = s:gsub("{%x%x%x%x%x%x}", "")
    s = s:gsub("%s+", " ")
    return s
end
local function authTextIsFail(raw)
    if type(raw) ~= "string" or raw == "" then return false end
    local s = authStrip(raw)
    for i = 1, #AUTH_FAIL_NEEDLES do
        local n = AUTH_FAIL_NEEDLES[i]
        if n ~= "" and s:find(n, 1, true) then return true end
    end
    for i = 1, #AUTH_FAIL_PAIRS do
        local a, b = AUTH_FAIL_PAIRS[i][1], AUTH_FAIL_PAIRS[i][2]
        if s:find(a, 1, true) and s:find(b, 1, true) then return true end
    end
    return false
end
local function authNoteFail()
    local state = _G.GRND_AUTH_STATE
    if type(state) ~= "table" or not state.windowSeen or state.showedAuthOk then return false end
    authChat.failAt = os.clock()
    return true
end
-- Use the first visible text colour for native SA-MP timestamps as well.
-- Network messages use RRGGBBAA; sampAddChatMessage uses AARRGGBB.
function grndChatLeadingRgb(text)
    local rest=tostring(text or '')
    local rgb
    while true do
        local code,tail=rest:match('^%s*{(%x%x%x%x%x%x)}(.*)$')
        if not code then break end
        rgb=tonumber(code,16);rest=tail
    end
    return rgb
end
function grndChatNativeColor(text,color)
    color=tonumber(color) or -1
    local rgb=grndChatLeadingRgb(text)
    if not rgb then return color end
    local alpha=math.floor((color%4294967296)/16777216)
    return alpha*16777216+rgb
end
function grndChatServerColor(text,color)
    color=tonumber(color) or -1
    local rgb=grndChatLeadingRgb(text)
    if not rgb then return color end
    return rgb*256+(color%256)
end

function onAddChatMessage(...)
    local n = select("#", ...)
    -- A wrong-password line is considered only while the known auth dialog is pending.
    for i = 1, n do
        local value = select(i, ...)
        if type(value) == "string" and authTextIsFail(value) then authNoteFail() end
    end
    if not grndSessionReady() then return end

    for i = 1, n do
        local text = select(i, ...)
        if type(text) == "string" and GRND_LOG then
            pcall(GRND_LOG.capture, text, "chat")
        end
    end
    -- Fallback for installations where samp.events is unavailable.
    for i = 1, n do
        local value = select(i, ...)
        if type(value) == "string" and value ~= "" then
            local hit = false
            if type(_G.grndFormsApprovedOnChat) == "function" then
                local ok, approved = pcall(_G.grndFormsApprovedOnChat, value, "chat")
                hit = ok and approved == true
            end
            if not hit and type(_G.grndFormWatchOnChat) == "function" then
                pcall(_G.grndFormWatchOnChat, value)
            end
        end
    end
end

-- =====================================================================
--  v1.12: ДИЗАЙН-СИСТЕМА (единый источник правды по цвету и вёрстке)
--
--  Раньше палитра лежала локальной таблицей внутри drawMenu, а по другим
--  окнам были рассыпаны литералы col32(255,255,255,...). Теперь:
--      GRND_UIKIT.TH        — АКТИВНАЯ палитра (её читают все окна);
--      GRND_UIKIT.apply(x)  — переключить палитру (мутирует тот же TH,
--                             поэтому менять ничего в окнах не нужно);
--      GRND_UIKIT.PAD/RAD   — отступы и радиусы «по умолчанию»;
--      GRND_UIKIT.set(x)    — применить + сохранить в конфиг.
--  Список тем и подписи — в NAMES/LABELS, выбор внизу левой панели.
-- =====================================================================
-- Violet / UI edition: opaque surfaces, restrained accents, accessible text.
GRND_UIKIT = {
    PAD = 20, GAP = 12, RAD = 6,
    NAMES = { "graphite", "emerald", "indigo", "amber", "rose" },
    LABELS = { graphite = "Графит / Violet", emerald = "Изумруд", indigo = "Индиго", amber = "Янтарь", rose = "Роза", custom = "Свой цвет" },
    current = "graphite",
    TH = {},
    PALETTES = {
        custom = { bg={18,17,23,255}, sidebar={14,13,18,255}, accent={164,112,224,255}, accent2={164,112,224,255} },
        rose = { bg={23,17,22,255}, sidebar={18,13,17,255}, accent={225,104,166,255}, accent2={225,104,166,255} },
        graphite = { bg={18,17,23,255}, sidebar={14,13,18,255}, accent={164,112,224,255}, accent2={164,112,224,255} },
        emerald = { bg={17,22,21,255}, sidebar={13,17,16,255}, accent={98,193,156,255}, accent2={98,193,156,255} },
        indigo = { bg={18,19,26,255}, sidebar={14,15,21,255}, accent={146,147,235,255}, accent2={146,147,235,255} },
        amber = { bg={23,21,18,255}, sidebar={18,16,14,255}, accent={218,177,106,255}, accent2={218,177,106,255} },
    },
    customRGB = {164,112,224},
    SHARED = {
        -- v1.19.04: тона текста подняты — на тёмном «стекле» прежние
        -- значения читались блекло (на это жаловались дважды: подписи
        -- кнопок и подписи вообще). Иерархия сохранена: hi > text > dim.
        line={255,255,255,20}, textHi={252,250,255,255},
        text={234,230,244,255}, textDim={198,192,216,255},
        textMuted={172,166,190,255}, itemSel={164,112,224,26},
        itemHover={255,255,255,10}, itemPress={255,255,255,18},
        card={255,255,255,5},
        -- Inner content surfaces only; outer window/sidebar stay unchanged.
        contentBg={255,255,255,13}, contentEdge={255,255,255,44},
    },
}
function GRND_UIKIT.apply(name)
    local pal = GRND_UIKIT.PALETTES[name]
    if not pal then return false end
    for k, v in pairs(GRND_UIKIT.SHARED) do GRND_UIKIT.TH[k] = v end
    for k, v in pairs(pal) do GRND_UIKIT.TH[k] = v end
    GRND_UIKIT.TH.itemSel = { pal.accent[1], pal.accent[2], pal.accent[3], 26 }
    GRND_UIKIT.current = name
    return true
end
-- User RGB is stored separately so switching presets never discards it.
function GRND_UIKIT.setCustom(r,g,b,activate)
    local rgb = {}
    for i,v in ipairs({r,g,b}) do
        v = tonumber(v)
        if not v or v ~= v then return false end
        rgb[i] = math.max(0,math.min(255,math.floor(v+0.5)))
    end
    if #rgb ~= 3 then return false end
    GRND_UIKIT.customRGB = rgb
    local pal = GRND_UIKIT.PALETTES.custom
    pal.accent = {rgb[1],rgb[2],rgb[3],255}
    pal.accent2 = pal.accent
    if activate or GRND_UIKIT.current == "custom" then GRND_UIKIT.apply("custom") end
    return true
end
-- Следующая тема по кругу (кнопка в настройках)
function GRND_UIKIT.next()
    local names = GRND_UIKIT.NAMES
    for i = 1, #names do
        if names[i] == GRND_UIKIT.current then
            return names[(i % #names) + 1]
        end
    end
    return names[1]
end
GRND_UIKIT.apply("graphite")

