local notify = {}
notify.chat = true
function notify.say(text, kind)
    print("{00FFAA}[GRND]{FFFFFF} " .. tostring(text))
    if notify.chat and type(sampAddChatMessage) == "function" then
        local col = 0x00FFAA
        if kind == "error" then col = 0xFF6666
        elseif kind == "warn" then col = 0xF79248
        elseif kind == "ok" then col = 0x4CD14F end
        local txt = "[GRND] " .. tostring(text)
        local cvt = _G.grndToAnsi
        if type(cvt) == "function" then
            local okC, recoded = pcall(cvt, txt)
            if okC and type(recoded) == "string" then txt = recoded end
        end
        pcall(sampAddChatMessage, txt, grndChatNativeColor(txt,col))
    end
end
notify.add = function(text, kind, life, force)
    if not force and type(_G.grndSessionReady) == "function" then
        local ok, ready = pcall(_G.grndSessionReady)
        if ok and not ready then return false end
    end
    notify.say(text, kind)
    return true
end
_G.GRND_ERRS = _G.GRND_ERRS or {}
function notify.err(where, err)
    local key = tostring(where) .. "|" .. tostring(err)
    if _G.GRND_ERRS[key] then return end
    _G.GRND_ERRS[key] = true
    table.insert(_G.GRND_ERRS, key)
    pcall(grndTrace, "ERROR", key)
    print("{FF6666}[GRND]{FFFFFF} ОШИБКА [" .. tostring(where) .. "]: " .. tostring(err))
    pcall(notify.say, "ошибка " .. tostring(where) .. ": " .. tostring(err), "error")
end
