-- =====================================================================
--  МОДУЛЬ 1: logRenderErr — раньше вызывался, но не был определён.
--  Без него любой error в рендере ронял весь ImGui-кадр (меню/Tab/F1).
-- =====================================================================
local _grndRenderErrSeen = {}
function logRenderErr(where, err)
    local key = tostring(where) .. "|" .. tostring(err)
    if _grndRenderErrSeen[key] then return end
    _grndRenderErrSeen[key] = true
    -- v1.5.6: последние ошибки рендера — в кольцевой буфер (попадают в дамп
    -- /grndkl dump). Без него о причинах видно только консоль игры.
    GRND_ERRLOG = GRND_ERRLOG or { n = 0 }
    local E = GRND_ERRLOG
    E.n = E.n + 1
    local idx = ((E.n - 1) % 24) + 1
    E[idx] = { at = os.date("%H:%M:%S"), where = tostring(where), err = tostring(err) }
    print("{FF6666}[GRND]{FFFFFF} рендер-ошибка [" .. tostring(where) .. "]: " .. tostring(err))
    pcall(grndTrace, "ERROR", "render: " .. key)
    pcall(notify.say, "рендер-ошибка " .. tostring(where) .. " (см. консоль)", "error")
end

