function grndAuthDialogActive()
    if sampIsDialogActive then
        local ok, res = pcall(sampIsDialogActive)
        if ok and res then return true end
    end
    return false
end
-- =====================================================================
--  v1.12.1: ЭКРАН ВХОДА — «МЁРТВАЯ ЗОНА» ДЛЯ ИНТЕРФЕЙСА
--
--  Проблема: на заходе (подключение, окно авторизации) на экране висели
--  чекеры (Kill List, «Админы в сети») и окно репорта. Причина — это
--  ПОЛЬЗОВАТЕЛЬСКИЕ НАСТРОЙКИ, сохранённые в конфигах с прошлой сессии:
--  «чекер включён» = «чекер рисуется», независимо от того, в игре ли игрок.
--  Плюс чекер админов успевал отправлять серверу /admins ещё до входа.
--
--  Теперь чекеры и серверные опросы ждут спавна и явного подтверждения
--  авторизации. Если auth-диалог увиден, gate остаётся закрытым до успешного
--  спавна; окно репорта на экране входа при этом закрывается.
-- =====================================================================
GRND_GATE = GRND_GATE or { blockedFrames = 0, suppressed = 0, why = "", unblockAt = 0 }
GRND_GATE.authSeen = false

-- Авторизацией считаем только явно подписанное окно входа/регистрации либо
-- диалог с явным запросом учётных данных. Обычные меню и окна после входа
-- больше не запускают «успешную авторизацию» и не выключают интерфейс.
local GRND_AUTH_TITLE_MARKERS = {
    "авторизац", "регистрац", "authorization", "authentication",
    "sign in", "login", "вход в игру", "вход на сервер", "вход в систему",
}
local GRND_AUTH_PROMPT_MARKERS = {
    "введите пароль", "введи пароль", "укажите пароль", "enter password",
    "enter your password", "введите логин", "enter login",
}
-- A few SA:MP builds return dialog text as raw CP1251 instead of UTF-8.
local GRND_AUTH_RAW_MARKERS = {
    "\xef\xe0\xf0\xee\xeb\xfc", "\xcf\xe0\xf0\xee\xeb\xfc",
    "\xcf\xc0\xd0\xce\xcb\xdc", -- пароль in lower/title/upper case
    "\xe0\xe2\xf2\xee\xf0\xe8\xe7\xe0\xf6", "\xc0\xe2\xf2\xee\xf0\xe8\xe7\xe0\xf6",
    "\xc0\xc2\xd2\xce\xd0\xc8\xc7\xc0\xd6", -- авторизац in upper case
    "\xeb\xee\xe3\xe8\xed", "\xcb\xee\xe3\xe8\xed", "\xcb\xce\xc3\xc8\xcd", -- логин
}

local function grndUiLower(s)
    local t = tostring(s or "")
    local convert = _G.grndToUtf
    if type(convert) == "function" then
        local ok, value = pcall(convert, t)
        if ok and type(value) == "string" and value ~= "" then t = value end
    end
    t = t:gsub("{%x%x%x%x%x%x%x%x}", ""):gsub("{%x%x%x%x%x%x}", "")
        :gsub("~%a~", " ")
    if type(_G.grndLowerUtf) == "function" then
        local ok, value = pcall(_G.grndLowerUtf, t)
        if ok and type(value) == "string" then return value end
    end
    return t:lower()
end

local function grndDialogPartsNow()
    if type(sampIsDialogActive) ~= "function" then return "", "" end
    local okActive, active = pcall(sampIsDialogActive)
    if not okActive or not active then return "", "" end
    local caption, text = "", ""
    if type(sampGetDialogCaption) == "function" then
        local ok, value = pcall(sampGetDialogCaption)
        if ok and type(value) == "string" then caption = value end
    end
    if type(sampGetDialogText) == "function" then
        local ok, value = pcall(sampGetDialogText)
        if ok and type(value) == "string" then text = value end
    end
    return caption, text
end

function grndDialogTextNow()
    local caption, text = grndDialogPartsNow()
    return caption .. "\n" .. text
end

function grndAuthDialogOpen()
    -- After confirmed login, ordinary server dialogs are not treated as auth UI.
    local authState = _G.GRND_AUTH_STATE
    if authState and authState.showedAuthOk then return false end
    local caption, text = grndDialogPartsNow()
    if caption == "" and text == "" then return false end
    local title, body = grndUiLower(caption), grndUiLower(text)
    local compactTitle = title:gsub("[%s:|%-]+", "")
    if compactTitle == "вход" or compactTitle == "пароль" then return true end
    for i = 1, #GRND_AUTH_TITLE_MARKERS do
        if title:find(GRND_AUTH_TITLE_MARKERS[i], 1, true) then return true end
    end
    for i = 1, #GRND_AUTH_PROMPT_MARKERS do
        if body:find(GRND_AUTH_PROMPT_MARKERS[i], 1, true) then return true end
    end
    -- Fallback for dialog APIs that expose CP1251 bytes that look like UTF-8.
    local raw = (caption .. "\n" .. text):lower()
    for i = 1, #GRND_AUTH_RAW_MARKERS do
        if raw:find(GRND_AUTH_RAW_MARKERS[i], 1, true) then return true end
    end
    local hasPassword = body:find("парол", 1, true) or body:find("password", 1, true)
    local hasPrompt = body:find("введите", 1, true) or body:find("введи", 1, true)
        or body:find("укажите", 1, true) or body:find("enter", 1, true)
        or body:find("аккаунт", 1, true) or body:find("account", 1, true)
        or body:find("логин", 1, true) or body:find("login", 1, true)
    return hasPassword and hasPrompt and true or false
end

-- true = интерфейс и серверные запросы запрещены (мы на экране входа)
function grndUiBlocked()
    local spawned
    if type(sampIsLocalPlayerSpawned) == "function" then
        local ok, sp = pcall(sampIsLocalPlayerSpawned)
        if ok then spawned = sp and true or false end
    end
    if grndAuthDialogOpen() then
        GRND_GATE.authSeen = true
        GRND_GATE.why = "окно авторизации"
        GRND_GATE.unblockAt = 0
        return true
    end
    if spawned == false then
        GRND_GATE.why = "не в игре"
        GRND_GATE.unblockAt = 0
        return true
    end
    local authState = _G.GRND_AUTH_STATE
    if GRND_GATE.authSeen and not (authState and authState.showedAuthOk) then
        GRND_GATE.why = "ожидание подтверждения авторизации"
        GRND_GATE.unblockAt = 0
        return true
    end
    if authState and authState.showedAuthOk then GRND_GATE.authSeen = false end
    GRND_GATE.why = ""
    if GRND_GATE.unblockAt == 0 then GRND_GATE.unblockAt = os.clock() end
    return false
end

-- «мы хотим что-то показать?» — для счётчика подавлений и тестов
function grndUiWantsToShow()
    return ((_G.GRND_KL and _G.GRND_KL.enabled)
        or (_G.GRND_AO and _G.GRND_AO.enabled)
        or (_G.GRND_REP and _G.GRND_REP.open)
        or (_G.GRND_REPHUD and _G.GRND_REPHUD.enabled)
        or (_G.GRND_CATCH and _G.GRND_CATCH.active)
        or (_G.GRND_RC and _G.GRND_RC.show)
        or (_G.GRND_TARGET_RING and _G.GRND_TARGET_RING.on)) and true or false
end

function grndIsSpawnedSafe()
    if type(sampIsLocalPlayerSpawned) ~= "function" then return false end
    local ok, res = pcall(sampIsLocalPlayerSpawned)
    return (ok and res) and true or false
end

-- Chat/dialog interception is silent during connection and authentication.
-- Spectator sessions are permitted once SA-MP reports the spectator state.
function grndSessionReady()
    if grndAuthDialogOpen() then return false end
    local authState = _G.GRND_AUTH_STATE
    if GRND_GATE.authSeen and not (authState and authState.showedAuthOk) then return false end
    if grndIsSpawnedSafe() then return true end
    if type(sampIsPlayerSpectating) == "function" then
        local ok, value = pcall(sampIsPlayerSpectating)
        if ok and value then return true end
    end
    return false
end
-- =====================================================================
--  v1.12: НАКАЗАНИЯ (данные). Причины/времена для кнопок рекона.
--  ТОЛЬКО ВИД: команды серверу пока не шлём. IBAN не добавляем никуда.
-- =====================================================================
GRND_PUN = _G.GRND_PUN or {}
do
    local P = GRND_PUN
    P.maxItems = 12
    if type(P.list) ~= "table" then
        -- порядок = порядок кнопок на странице «Наказания» бара
        P.list = {
            { id = "JAIL",  unit = "мин",  time = true  },
            { id = "BAN",   unit = "д",    time = true  },
            { id = "WARN",  unit = nil,    time = false },
            { id = "KICK",  unit = nil,    time = false },
            { id = "MUTE",  unit = "мин",  time = true  },
            { id = "SKICK", unit = nil,    time = false, locked = true },
            { id = "SBAN",  unit = "д",    time = true  },
        }
    end
    -- No preset reasons or durations: users configure their own lists.
    if type(P.data) ~= "table" then
        P.data = {}
        for _, item in ipairs(P.list) do
            P.data[item.id] = { reasons = {}, times = {} }
        end
    end
    if P.barOn == nil then P.barOn = true end   -- бар действий в слежке вкл/выкл
    P.editId     = P.editId or nil              -- id открытого редактора «Наказание: ID»
    P.addCol     = nil                          -- "r"/"t": какая колонка ждёт ввод
    P.buf        = nil                          -- ImGui-буфер ввода (создаётся лениво)
    P.focused    = false                        -- автофокус на поле ввода
    P.loaded     = P.loaded or false
    P.cfgDirty   = false
    P.cfgSavedAt = 0

    -- действия над игроком (6 в ряд, расширение в ширину)
    P.actions = {
        "Выдать ХП", "Выдать броню", "Подбросить", "Заспавнить", "Заморозить", "Разморозить",
        "Починить т/с", "Перевернуть т/с", "Заправить т/с", "Заспавнить т/с", "ТП на дорогу", "ТП к игроку",
        "ТП игрока к себе", "Оружие", "Отобрать все оружие", "Статистика", "Активные наказания", "Лицензии",
        "Сообщить в /a",
    }

    local function punCfgPath()
        if type(this_script_dir) == "function" then
            local okd, sd = pcall(this_script_dir)
            if okd and sd and tostring(sd) ~= "" then
                local pp = tostring(sd)
                while pp:sub(-1) == "/" or pp:sub(-1) == "\\" do pp = pp:sub(1, -2) end
                local sep = "\\"
                local okc, cf = pcall(function() return package.config end)
                if okc and type(cf) == "string" and #cf > 0 then sep = cf:sub(1, 1) end
                return pp .. sep .. "grnd_punish.cfg"
            end
        end
        return "grnd_punish.cfg"
    end

    function P.save()
        local ok, f = pcall(GRND_CONFIG.open, punCfgPath(), "w")
        if not ok or not f then return false end
        f:write("barOn=" .. (P.barOn and "1" or "0") .. "\n")
        if _G.GRND_RC and _G.GRND_RC.savedActionsWinX and _G.GRND_RC.savedActionsWinY then
            f:write("actX=" .. tostring(math.floor(_G.GRND_RC.savedActionsWinX)) .. "\n")
            f:write("actY=" .. tostring(math.floor(_G.GRND_RC.savedActionsWinY)) .. "\n")
        end
        for _, it in ipairs(P.list) do
            local d = P.data[it.id]
            if d then
                local r, t = {}, {}
                for _, s0 in ipairs(d.reasons or {}) do
                    local s = tostring(s0):gsub("[|\r\n]", "")
                    if s ~= "" then r[#r + 1] = s end
                end
                for _, n in ipairs(d.times or {}) do
                    n = tonumber(n)
                    if n and n > 0 then t[#t + 1] = tostring(math.floor(n)) end
                end
                f:write(it.id .. ".r=" .. table.concat(r, "|") .. "\n")
                f:write(it.id .. ".t=" .. table.concat(t, "|") .. "\n")
            end
        end
        pcall(f.close, f)
        P.cfgSavedAt = os.clock()
        P.cfgDirty = false
        return true
    end

    function P.load()
        if P.loaded then return end
        P.loaded = true
        local ok, f = pcall(GRND_CONFIG.open, punCfgPath(), "r")
        if not ok or not f then return end
        local idx = {}
        for _, it in ipairs(P.list) do idx[it.id] = it end
        for line in f:lines() do
            local k, v = tostring(line):match("^%s*([%w%.]+)%s*=%s*(.-)%s*$")
            if k == "barOn" then
                P.barOn = (v == "1")
            elseif k == "actX" then
                local n = tonumber(v)
                if n then
                    _G.GRND_RC = _G.GRND_RC or {}
                    _G.GRND_RC.savedActionsWinX = n
                end
            elseif k == "actY" then
                local n = tonumber(v)
                if n then
                    _G.GRND_RC = _G.GRND_RC or {}
                    _G.GRND_RC.savedActionsWinY = n
                end
            elseif k then
                local id, kind = k:match("^(%u+)%.([rt])$")
                if id and kind and idx[id] then
                    local d = P.data[id] or { reasons = {}, times = {} }
                    P.data[id] = d
                    local out = {}
                    for piece0 in tostring(v):gmatch("([^|]*)|?") do
                        local piece = piece0:gsub("^%s+", ""):gsub("%s+$", "")
                        if piece ~= "" and #out < (P.maxItems * 2) then
                            if kind == "t" then
                                local n = tonumber(piece)
                                if n and n > 0 then out[#out + 1] = math.floor(n) end
                            else
                                out[#out + 1] = piece
                            end
                        end
                    end
                    if kind == "r" then d.reasons = out else d.times = out end
                end
            end
        end
        pcall(f.close, f)
    end

    function P.entry(id)
        for _, it in ipairs(P.list) do
            if it.id == id then return it end
        end
        return nil
    end

    function P.counts(id)
        local d = P.data[id]
        if not d then return 0, 0 end
        return #(d.reasons or {}), #(d.times or {})
    end

    -- русский плюрал: 1 запись, 2 записи, 5 записей
    function P.plural(n, one, few, many)
        n = math.abs(tonumber(n) or 0) % 100
        local d10 = n % 10
        if n > 10 and n < 20 then return many end
        if d10 == 1 then return one end
        if d10 >= 2 and d10 <= 4 then return few end
        return many
    end

    -- ---------- буфер ввода редактора (как у окна репорта) ----------
    function P.ensureBuf(im)
        if P.buf then return true end
        if not (im and im.new and im.new.char) then return false end
        local ok, b = pcall(function() return im.new.char[64]() end)
        if ok and b then P.buf = b return true end
        return false
    end

    function P.clearBuf()
        if not P.buf then return end
        pcall(function() P.buf[0] = 0 end)
    end

    function P.readBuf()
        if not P.buf then return "" end
        local okS, v = pcall(function()
            local okF, ffi = pcall(require, "ffi")
            if okF and ffi then return ffi.string(P.buf) end
            return tostring(P.buf)
        end)
        if okS and type(v) == "string" then return v end
        return ""
    end

    -- добавление записи из редактора: валидация + сохранение.
    function P.commit(id, kind, raw)
        local it = P.entry(id)
        if not it then return false end
        local d = P.data[id]
        if not d then return false end
        raw = tostring(raw or ""):gsub("^%s+", ""):gsub("%s+$", "")
        if raw == "" then return false end
        local items = (kind == "t") and (d.times or {}) or (d.reasons or {})
        if #items >= P.maxItems then
            pcall(notify.add, "Не больше " .. tostring(P.maxItems) .. " записей в списке", "warn", 3)
            return false
        end
        if kind == "t" then
            local n = tonumber(raw:match("^(%d+)") or "")
            if not n or n < 1 then
                pcall(notify.add, "Время задаётся числом: 1…9999", "warn", 3)
                return false
            end
            items[#items + 1] = math.min(9999, math.floor(n))
            d.times = items
        else
            raw = raw:gsub("[|{}<>~%\r\n]", "")
            if raw == "" then
                pcall(notify.add, "Причина пустая или из недопустимых символов", "warn", 3)
                return false
            end
            -- не длиннее 24 символов (utf8-безопасная обрезка)
            local chars = {}
            for ch in raw:gmatch("[%z\1-\127\194-\244][\128-\191]*") do
                chars[#chars + 1] = ch
            end
            if #chars > 24 then
                raw = table.concat(chars, "", 1, 24)
                pcall(notify.add, "Причина обрезана до 24 символов", "warn", 3)
            end
            local low = raw:lower()
            for _, s in ipairs(items) do
                if tostring(s):lower() == low then
                    pcall(notify.add, "Такая причина уже есть", "warn", 2.5)
                    return false
                end
            end
            items[#items + 1] = raw
            d.reasons = items
        end
        P.cfgDirty = true
        pcall(P.save)
        return true
    end

    -- /pun — диагностика модуля: доказывает, что загружена НОВАЯ сборка,
    -- и показывает живое состояние редактора/бара. Печать — как у всех
    -- сообщений скрипта: sampAddChatMessage с {кодами}, не print (он в консоль).
    if type(sampRegisterChatCommand) == "function" then
    end
end

