GRND_GM_TOGGLE_KEY = 0x71          -- ФИКС: был только локалом внутри main,
                                    -- а onWindowMessage читал nil
local MENU_CLOSE_ON_ESC = true
-- ФИКС: в v1.1 любое (даже служебное, не наше) открытое серверное окно
-- полностью выключало M / TAB / F1 / T. Теперь блокируем только ввод в родном
-- чате (v1.7.0: свой чат удалён, «печатаю» определяется штатным API клиента),
-- а горячие клавиши остаются живыми. /hotkeys0 — вернуть старое поведение.
local BLOCK_KEYS_ON_ANY_DIALOG = false
-- TAB: true = держать и смотреть (как нативный таб), false = тап = вкл/выкл
local GRND_TAB_HOLD_MODE = false
-- патч samp.dll: байт VK_F1 (0x70) -> 0, чтобы не всплывало «SA-MP Keys».
-- Офсеты 0x752D0 / 0x713E0 для 0.3.7 R3; пишем ТОЛЬКО если по адресу 0x70.
local F1_UNBIND_DEFAULT = true
local GRND_TAB = { open = false, hook = false, specId = nil, held = false,
    downAt = 0 }
-- «зажата ли клавиша сейчас» + «сколько кадров её держали» — и для событий,
-- и для опроса. Раньше дебаунс считался по времени (os.clock), из-за чего
-- (а) два разных нажатия в пределах 0.25 с превращались в одно (M «не
-- закрывал» меню), и (б) автоповтор удержания всё-таки пролезал, если OS
-- присылала lparam без бита 30.
local GRND_TAP = {}   -- [vk] = { held = bool, downAt = сек, downFrame = кадр }
local function grndTapState(vk)
    local st = GRND_TAP[vk]
    if not st then st = { held = false, downAt = 0, downFrame = -9999 }
        GRND_TAP[vk] = st end
    return st
end
-- вызывается из onWindowMessage на KEYDOWN: true = это НОВОЕ нажатие
local function grndTapBegin(vk)
    local st = grndTapState(vk)
    if st.held then return false end
    st.held = true
    st.downAt = os.clock()
    st.downFrame = GRND_UIFRAME
    return true
end
local function grndTapEnd(vk)
    grndTapState(vk).held = false
end
local function grndTapHeldFrames(vk)
    return GRND_UIFRAME - (grndTapState(vk).downFrame or GRND_UIFRAME)
end
-- для опросного пути: не переключать, пока клавиша «не была отжата»
local function grndPollTap(vk)
    local st = grndTapState(vk)
    if st.held then return false end
    st.held, st.downAt, st.downFrame = true, os.clock(), GRND_UIFRAME
    return true
end
-- ссылки на объекты, живущие внутри grndMainBody (чтобы хоткеи работали
-- из onWindowMessage, не дожидаясь основного цикла)
local GRND_REF = { im = nil, menu = nil, clw = nil, spec = nil, gm = nil,
                   clwSetAiming = nil, clwApplyAim = nil }
-- ФИКС v1.2: мышь. Часть ImGui-обёрток не передаёт io.MouseDown, поэтому
-- «клик» по InvisibleButton может не срабатывать вообще (кнопки меню/чекеров!).
-- Держим собственное состояние кнопок из оконных сообщений.
GRND_MOUSE = { x = 0, y = 0, down = false, clicked = false, rdown = false,
               rclicked = false, mdown = false, mclicked = false,
               at = -99, frame = -1 }
-- счётчик кадров ImGui: «сырой» клик живёт ровно один кадр отрисовки
-- (иначе флаг либо теряется, либо превращается в вечный «нажат»)...
GRND_UIFRAME = 0
local function grndMouseXY(lparam)
    local lp = tonumber(lparam) or 0
    if lp < 0 then lp = lp + 0x100000000 end
    local x = lp % 65536
    local y = math.floor(lp / 65536) % 65536
    if x >= 32768 then x = x - 65536 end
    if y >= 32768 then y = y - 65536 end
    return x, y
end
function grndMouseInside(r)
    if not r or not r.w or r.w <= 0 then return false end
    local mx, my = GRND_MOUSE.x, GRND_MOUSE.y
    return mx >= r.x and mx <= r.x + r.w and my >= r.y and my <= r.y + r.h
end
-- жив ли ещё «сырой» клик: он выдаётся ровно на один кадр отрисовки ImGui
function grndClickAlive()
    return (GRND_MOUSE.frame or -9999) - GRND_UIFRAME <= 0
       and (GRND_MOUSE.frame or -9999) >= GRND_UIFRAME - 1
end
-- v1.11.11: самый надёжный способ узнать, зажата ли ПКМ, — прямой вызов
-- WinAPI GetAsyncKeyState через LuaJIT ffi (MoonLoader — LuaJIT). Если
-- фишка недоступна, возвращается nil и вызывающий код берёт другие
-- источники (isKeyDown / getMouseState / WM-метки).
local grndGAKS = nil
do
    local okF, ffi = pcall(require, "ffi")
    if okF and type(ffi) == "table" and ffi.cdef and ffi.load then
        pcall(function()
            ffi.cdef("short __stdcall GetAsyncKeyState(int vKey);")
            grndGAKS = ffi.load("user32").GetAsyncKeyState
        end)
    end
end
function grndRmbHeldWin()
    if not grndGAKS then return nil end
    local ok, st = pcall(grndGAKS, 0x02) -- VK_RBUTTON
    if not ok or st == nil then return nil end
    local v = tonumber(st)
    if not v then return nil end
    if v < 0 then v = v + 65536 end
    return v >= 32768
end
function grndConsumeMsg(passGame)
    if type(consumeWindowMessage) ~= "function" then return end
    -- Keep the message available to Lua callbacks; the second argument controls
    -- whether it also reaches the game (false for UI-owned input).
    pcall(consumeWindowMessage, true, passGame and true or false)
end
