-- Конфиг шрифта интерфейса. Раньше эти поля лежали в grnd_chat.cfg вместе с
-- настройками чата; теперь файл свой — grnd_ui.cfg. Старый grnd_chat.cfg
-- читается один раз, если нового ещё нет: выбранный шрифт не теряется.
function grndUiCfgSep()
    local ok, cf = pcall(function() return package.config end)
    if ok and type(cf) == "string" and #cf > 0 then return cf:sub(1, 1) end
    return "\\"
end
function grndUiCfgDir()
    if type(this_script_dir) == "function" then
        local okd, sd = pcall(this_script_dir)
        if okd and sd and tostring(sd) ~= "" then
            local pp = tostring(sd)
            while pp:sub(-1) == "/" or pp:sub(-1) == "\\" do pp = pp:sub(1, -2) end
            return pp
        end
    end
    return nil
end
function grndUiCfgPath()
    local d = grndUiCfgDir()
    if d then return d .. grndUiCfgSep() .. "grnd_ui.cfg" end
    return "grnd_ui.cfg"
end
function grndUiCfgSave()
    local path = grndUiCfgPath()
    local ok, f = pcall(GRND_CONFIG.open, path, "w")
    if not ok or not f then
        pcall(grndTrace, "cfg", "НЕ УДАЛОСЬ записать " .. tostring(path))
        return false
    end
    f:write("ver=1\n")
    f:write("fontSize=" .. tostring(GRND_FONT.fontSize or 16) .. "\n")
    -- v1.7.8: признак ОСОЗНАННОГО выбора шрифта (кнопки < >). Нужен, чтобы
    -- не путать старое умолчание arial.ttf с явно выбранным Arial.
    if GRND_FONT.fontUserChosen then
        f:write("fontUser=1\n")
    end
    if GRND_FONT.fontName then
        f:write("fontName=" .. tostring(GRND_FONT.fontName) .. "\n")
    end
    if GRND_FONT.fontPath then
        f:write("fontPath=" .. tostring(GRND_FONT.fontPath) .. "\n")
    end
    pcall(f.close, f)
    GRND_FONT.cfgDirty = false
    GRND_FONT.cfgSavedAt = os.clock()
    if not GRND_CONFIG.collecting then pcall(grndTrace, "cfg", "записан config/grnd_tools/config.json") end
    return true
end
function grndUiCfgLoad()
    if GRND_FONT.cfgLoaded then return end
    GRND_FONT.cfgLoaded = true
    local function parse(path)
        local ok, f = pcall(GRND_CONFIG.open, path, "r")
        if not ok or not f then return nil end
        local okc, content = pcall(function() return f:read("*a") end)
        pcall(function() f:close() end)
        if not okc or type(content) ~= "string" then return nil end
        return content
    end
    local content = parse(grndUiCfgPath())
    if not content then
        -- одноразовый перенос шрифта из старого конфига чата
        local d = grndUiCfgDir()
        local old = d and (d .. grndUiCfgSep() .. "grnd_chat.cfg") or "grnd_chat.cfg"
        content = parse(old)
        if content then
            pcall(grndTrace, "cfg", "шрифт перенесён из старого конфига: " .. old)
            GRND_FONT.cfgDirty = true
        end
    end
    if not content then
        pcall(grndTrace, "cfg", "конфига шрифта нет — берём системный/первый найденный")
        return
    end
    for line in (content .. "\n"):gmatch("([^\n]*)\n") do
        local k, v = line:match("^(%w+)=(.+)$")
        if k and v then
            if k == "fontName" or k == "fontPath" then
                GRND_FONT[k] = v
            elseif k == "fontUser" then
                -- v1.7.8: шрифт выбран вручную (кнопками < > в чекере)
                GRND_FONT.fontUserChosen = (v == "1")
            elseif k == "fontSize" then
                local num = tonumber(v)
                if num then
                    GRND_FONT.fontSize = math.max(9, math.min(40, math.floor(num + 0.5)))
                end
            end
        end
    end
end

