local grndCamMem, grndIsPlayerAiming -- shared forward declarations for early FOV helpers
local GRND_CAM = {
    enabled = false,
    dist = 12.0,            -- дистанция отдаления над персонажем (в метрах)
    curDist = 12.0,         -- текущая сглаженная дистанция
    heightMult = 1.0,       -- множитель высоты камеры над персонажем
    inVehicle = true,       -- применять в транспорте (авто/мото)
    resetOnAim = true,      -- сбрасывать при прицеливании с оружия
    wheelAdjust = true,     -- Alt + колесо мыши для регулировки
    wasActive = false,
    cfgDirty = false,
    cfgLoaded = false,
    -- v1.15.0: FOV-режим ДЛЯ МОЕГО ПЕРСОНАЖА (Настройки → Дистанция
    -- камеры). Живёт отдельно от дистанции: тумблер + ползунок.
    fovOn = false,          -- включён ли режим FOV
    fov = 80.0,             -- угол обзора (70 = стандарт игры)
    fovApplied = nil,       -- какой FOV применён сейчас
    fovLerpUntil = 0,       -- до какого момента идёт штатный лерп (не мешаем)
    fovEndHold = nil,       -- время финальной записи 70 после выключения
}
_G.GRND_CAM = GRND_CAM

-- Shared camera clock. Repeated calls in one game tick do not advance smoothing.
function grndCamNow()
    if type(getGameTimer)=='function' then
        local ok,v=pcall(getGameTimer)
        if ok and type(v)=='number' then return v/1000 end
    end
    return os.clock()
end
function grndCamReportError(part,err)
    GRND_CAM.errors=GRND_CAM.errors or {}
    local now=grndCamNow();local last=GRND_CAM.errors[part]
    if not last or now<last or now-last>=10 then
        GRND_CAM.errors[part]=now
        print('[GRND camera/'..tostring(part)..'] '..tostring(err))
    end
end
function grndCamSpectating()
    if _G.grndSpecNative and _G.grndSpecNative.camOn then return true end
    if _G.GRND_SPEC and _G.GRND_SPEC.active then return true end
    if _G.GRND_RC and _G.GRND_RC.show and tonumber(_G.GRND_RC.id) then return true end
    if type(sampIsPlayerSpectating)=='function' then
        local ok,v=pcall(sampIsPlayerSpectating);if ok and v then return true end
    end
    return false
end
function grndCamActiveBase()
    local M=grndCamMem and grndCamMem()
    if not M or not M.r8 then return nil end
    local ok,i=pcall(M.r8,0xB6F028+0x59)
    if not ok or type(i)~='number' or i<0 or i>2 then return nil end
    return 0xB6F028+0x174+i*0x238,M
end
function grndCamFovMem(fov,base)
    local active,M=grndCamActiveBase()
    base=base or active
    if not base or not M or not M.wf or type(fov)~='number'
        or fov~=fov or fov<5 or fov>170 then return false end
    return pcall(M.wf,base+0xB4,fov)
end
function grndCamFovReset()
    local C=GRND_CAM;local S=C.fovState
    if S then
        local M=grndCamMem and grndCamMem()
        if M and M.rf and M.wf then
            local ok,v=pcall(M.rf,S.base+0xB4)
            -- Do not overwrite a zoom another camera mode has already installed.
            if ok and type(v)=='number' and math.abs(v-S.current)<0.25 then
                pcall(M.wf,S.base+0xB4,S.original)
            end
        end
    end
    C.fovState=nil;C.fovApplied=nil;C.fovEndHold=nil
end
-- Transfer our FOV ownership across an active CCam slot change without treating
-- the copied display FOV as the new native default.
function grndCamFovTransfer(base)
    local C=GRND_CAM;local old=C.fovState
    if not old or old.base==base then return end
    local value,original=old.current,old.original
    grndCamFovReset()
    C.fovState={base=base,current=value,original=original,at=grndCamNow()}
    C.fovApplied=value
    grndCamFovMem(value,base)
end
function grndCamFovApply()
    local C=GRND_CAM
    local aiming=type(grndIsPlayerAiming)=='function' and grndIsPlayerAiming()
    local spawned=true
    if type(grndIsSpawned)=='function' then spawned=grndIsSpawned() end
    if grndCamSpectating() or aiming or not spawned then
        grndCamFovReset();return
    end
    local base,M=grndCamActiveBase()
    if not base or not M.rf or not M.r32 then return end
    -- Apply local-player FOV only to normal follow-camera modes, never to a
    -- transient fixed/script camera that another feature may currently own.
    local okMode,mode=pcall(M.r32,base+0x0C)
    if not okMode or type(mode)~='number' then return end
    mode=mode%65536
    if mode~=4 and mode~=18 then return end
    local ok,current=pcall(M.rf,base+0xB4)
    if not ok or type(current)~='number' or current~=current or current<5 or current>170 then return end
    local now=grndCamNow();local S=C.fovState
    if S and S.base~=base then
        local good,mode=false,nil
        if M.r32 then good,mode=pcall(M.r32,base+0x0C) end
        -- Native follow can switch CCam slots without ending the user's FOV
        -- setting. Carry the displayed value instead of restarting at default.
        if good and type(mode)=='number' and (mode%65536==4 or mode%65536==18) then
            grndCamFovTransfer(base);S=C.fovState
        else
            grndCamFovReset();S=nil
        end
    end
    if not S then
        if not C.fovOn then return end
        S={base=base,original=current,current=current,at=now-1/60}
        C.fovState=S
    end
    local dt=math.max(0,math.min(0.1,now-S.at));S.at=now
    local target=C.fovOn and math.max(45,math.min(110,tonumber(C.fov) or 80)) or S.original
    S.current=S.current+(target-S.current)*(1-math.exp(-10*dt))
    if math.abs(S.current-target)<0.02 then S.current=target end
    grndCamFovMem(S.current,base)
    C.fovApplied=S.current
    if not C.fovOn and S.current==target then C.fovState=nil;C.fovApplied=nil end
end

local GRND_ADMIN_CFG = {
    spAutoCar = true,
    spKeyLog = true,
    spShowInfo = true,
    repSound = true,
    repToasts = true,
    banConfirm = true,
    streamMode = false,
    spAutoRefresh = true,
    autoForms = true,
    autoGnews = false,
    -- v1.13.0: отчёт в /a только после ответа сервера (см. GRND_FORMWAIT)
