    "заспавнен", "восстановлен", "транспорт создан", "автомобиль создан",
}

-- «успешно» + слово по команде — тоже подтверждение
GRND_FORM_OK_BY_CMD = {
    jail   = { "тюрьм", "посад", "арест" },
    unjail = { "освобо", "выпус", "тюрьм" },
    mute   = { "мут", "mute" },
    rmute  = { "мут", "mute" },
    unmute = { "мут", "mute", "размуч" },
    ban    = { "бан", "ban", "блокиров" },
    kick   = { "кик", "kick", "отключ", "выгнан" },
    warn   = { "предупрежд", "варн", "warn" },
    unwarn = { "предупрежд", "варн", "warn" },
    slap   = { "слап", "slap", "шлеп" },
    spawn  = { "спавн", "spawn", "восстанов" },
    spcar  = { "транспорт", "автомобил", "создан" },
    -- v1.14.5: оффлайн-наказания
    offjail = { "тюрьм", "посад", "арест", "jail" },
    offmute = { "мут", "mute" },
    offban  = { "бан", "ban", "блокиров" },
    offwarn = { "предупрежд", "варн", "warn" },
}

-- включена ли проверка ответа сервера
function grndFormWaitCfgOn()
    return true -- built-in behaviour; no activation command
end

-- v1.14.1: включён ли режим «отчёт в /a сразу после ответа сервера»
function grndFormInstantCfgOn()
    if type(GRND_ADMIN_CFG) ~= "table" then return true end
    return GRND_ADMIN_CFG.formInstant ~= false
end

-- v1.14.1: пауза «дослушать» ответ сервера (0 … 2 сек, по умолчанию 0.20)
function grndFormSettleSec()
    local s = tonumber(_G.GRND_FORM_SETTLE_SEC)
    if not s then return 0 end
    if s < 0 then s = 0 end
    if s > 2 then s = 2 end
    return s
end

-- v1.14.1: строка заведомо НЕ является ответом сервера на нашу команду —
-- по ней «мгновенный» отчёт не отправляем (иначе первая же посторонняя
-- строка в чате закрывала бы ожидание). Отказ и подтверждение ловятся
-- ДО этой проверки (grndFormWaitClassify), поэтому формулировки вроде
-- «Игрок не найден или покинул сервер» всё равно дают «… была отклонена».
GRND_FORM_NOISE = {
    "форма от администратора",                      -- наше эхо в /a
    "государственн",                                -- гос. новости
    "подключился", "присоединился",                 -- входы/выходы игроков
    "покинул сервер", "вышел с сервера", "вышел из игры",
    "вошел в игру", "вошёл в игру",
    "зашел на сервер", "зашёл на сервер",
    "поздравляем", "повышен уровень", "новый уровень",  -- опыт/уровень
    "личное сообщение", "написал", "написала",          -- ЛС
}
function grndFormWaitIsNoise(u)
    local low = grndFormWaitLower(u)
    if low == "" then return true end
    for i = 1, #GRND_FORM_NOISE do
        if low:find(GRND_FORM_NOISE[i], 1, true) then return true end
    end
    return false
end

-- v1.14.2: включён ли «догон» (уточнение в /a, если отказ пришёл позже)
function grndFormCorrectCfgOn()
    return true -- built-in behaviour; no activation command
end

-- v1.14.2: строка «про нашу команду»? В ней есть ID цели или её ник
-- («/jail 5 …» -> 5, «/warn Nick_Name …» -> Nick_Name).
function grndFormWaitIsRelated(u)
    local W = _G.GRND_FORMWAIT
    if type(W) ~= "table" then return false end
    local t = grndFormWaitLower(tostring(u or ""))
    if t == "" then return false end
    local id = tonumber(W.targetId)
    if id then
        for num in t:gmatch("%d+") do
            if tonumber(num) == id then return true end
        end
    end
    local nick = tostring(W.targetNick or "")
    if #nick >= 3 and t:find(grndFormWaitLower(nick), 1, true) then return true end
    return false
end

-- любой текст (CP1251 от сервера или UTF-8) -> UTF-8 без цветовых кодов
function grndFormWaitNorm(text)
    local t = tostring(text or "")
    if t == "" then return "" end
    local u = t
    if type(_G.grndToUtf) == "function" then
        local ok, c = pcall(_G.grndToUtf, t)
        if ok and type(c) == "string" and c ~= "" then u = c end
    end
    u = u:gsub("{%x%x%x%x%x%x}", ""):gsub("{%X%X%X%X%X%X}", "")
    u = u:gsub("%s+", " ")
    return u
end

-- string.lower() в Lua НЕ переводит кириллицу UTF-8 в нижний регистр,
-- поэтому для сравнений берём готовый grndLowerUtf из скрипта (Ё/ё тоже).
function grndFormWaitLower(s)
    local t = tostring(s or "")
    if t == "" then return t end
    if type(_G.grndLowerUtf) == "function" then
        local ok, out = pcall(_G.grndLowerUtf, t)
        if ok and type(out) == "string" and out ~= "" then return out end
    end
    return t:lower()
end

-- варианты «Nick говорит: …» (в Lua-шаблонах НЕТ альтернации «|» — только список)
GRND_FORM_SAYS = { "Says", "says", "говорит", "кричит", "шепчет", "сказал", "вопит", "орет", "орёт" }

-- это реплика игрока/админа, а не ответ сервера?
function grndFormWaitIsReplika(u)
    local t = tostring(u or "")
    if t == "" then return false end
    if t:find("[%w_%-%.]+%s*%[%d+%]%s*:") then return true end       -- «Nick[12]: …»
    for i = 1, #GRND_FORM_SAYS do                                    -- «Nick говорит: …»
        local v = GRND_FORM_SAYS[i]                                  -- «Nick[12] говорит: …»
        if t:find("[%w_%-%.]+%s*" .. v .. "%s*:") then return true end
        if t:find("[%w_%-%.]+%s*%[%d+%]%s*" .. v .. "%s*:") then return true end
    end
    local key = grndFormWaitLower(t):gsub("[^%w]", "")
    if key:find("atools", 1, true) then return true end              -- чужой админ-тул
    return false
end

-- вырезать из строки текст причины из команды
function grndFormWaitProbe(u, reason)
    local t = tostring(u or "")
    local r = tostring(reason or "")
    if r == "" or #r < 3 then return t end
    local i = grndFormWaitLower(t):find(grndFormWaitLower(r), 1, true)
    if not i then return t end
    return (t:sub(1, i - 1) .. " " .. t:sub(i + #r)):gsub("%s+", " ")
end

-- «/jail 5 30 АФК | M.Fomin» -> «АФК»;  «/offjail Nick 30 АФК» -> «АФК»
function grndFormWaitReasonPart(cmd, cmdName)
    local s = tostring(cmd or "")
    s = s:gsub("^%s*[/%!%.]?%a[%w_]*%s*", "")              -- имя команды
    local spec = ""
    do
        local syn = GRND_FORM_SYNTAX[tostring(cmdName or ""):lower()]
        if type(syn) == "table" and type(syn.args) == "string" then spec = syn.args end
    end
    if spec:sub(1, 1) == "n" then
        s = s:gsub("^%s*%S+%s*", "")                        -- цель — НИК (/warn, /offjail …)
    else
        s = s:gsub("^%s*%d+%s+", "")                        -- цель — ID
    end
    if spec:find("t", 1, true) then
        s = s:gsub("^%s*%d+%s+", "")                        -- время
    end
    s = s:gsub("^%s*%d+%s*$", "")                           -- команда только с числом
    s = s:match("^(.-)%s*|%s*[%a\128-\255][%w\128-\255%.%-]-%.[%w\128-\255%.%-]+%s*$") or s
    s = s:gsub("^%s+", "")
    s = s:gsub("%s+$", "")
    return s
end

-- строка похожа на ОТКАЗ сервера? возвращает причину (строку) или nil
function grndFormWaitFail(u)
    local t = tostring(u or "")
    if t == "" then return nil end
    local low = grndFormWaitLower(t)
    if low:find("форма от администратора", 1, true) then return nil end   -- наше эхо
    if low:find("государственн", 1, true) then return nil end             -- гос.новости
    if low:find("уже", 1, true) or low:find("already", 1, true) then
        for i = 1, #GRND_FORM_ALREADY do
            if low:find(GRND_FORM_ALREADY[i], 1, true) then return t end
        end
    end
    for i = 1, #GRND_FORM_FAIL_WORDS do
        if low:find(GRND_FORM_FAIL_WORDS[i], 1, true) then return t end
    end
    return nil
end

-- строка похожа на ПОДТВЕРЖДЕНИЕ сервера?
function grndFormWaitOk(u, cmdName)
    local low = grndFormWaitLower(u)
    if low == "" then return false end
    for i = 1, #GRND_FORM_OK_WORDS do
        if low:find(GRND_FORM_OK_WORDS[i], 1, true) then return true end
    end
    if low:find("успешно", 1, true) or low:find("success", 1, true) then
        local words = GRND_FORM_OK_BY_CMD[tostring(cmdName or ""):lower()]
        if type(words) == "table" then
            for i = 1, #words do
                if low:find(words[i], 1, true) then return true end
            end
        end
    end
    return false
end

-- длина строки ПОСЛЕ перевода в CP1251 — именно её ограничивает SA-MP (~144)
function grndFormAnsiLen(s)
    s = tostring(s or "")
    if s == "" then return 0 end
    if type(grndAnsiText) == "function" then
        local ok, a = pcall(grndAnsiText, s)
        if ok and type(a) == "string" and a ~= "" then return #a end
    end
    return #s
end

-- КЛАССИФИКАТОР ответа сервера: «fail» / «ok» / nil (строка не про нашу команду).
-- Порядок важен:
--   1) «УЖЕ …» + наказание — самый надёжный признак отказа (те самые
--      «Игрок уже сидит в тюрьме», «У игрока уже есть мут»);
--   2) однозначное подтверждение успеха («Вы посадили игрока …») — раньше
--      общих слов отказа, иначе «… он не может двигаться 30 минут» в
--      подтверждении сервера приняли бы за отказ;
--   3) прочие формулировки отказа («не найден», «нельзя», «ошибка», …).
function grndFormWaitClassify(u, cmdName)
    local t = tostring(u or "")
    if t == "" then return nil end
    local low = grndFormWaitLower(t)
    if low:find("форма от администратора", 1, true) then return nil end   -- наше эхо
    if low:find("государственн", 1, true) then return nil end             -- гос.новости
    if low:find("уже", 1, true) or low:find("already", 1, true) then
        for i = 1, #GRND_FORM_ALREADY do
            if low:find(GRND_FORM_ALREADY[i], 1, true) then return "fail" end
        end
    end
    if grndFormWaitOk(low, cmdName) then return "ok" end
    if grndFormWaitFail(low) then return "fail" end
    return nil
end

-- обрезать строку до maxBytes байт, не разрывая UTF-8 символ
function grndFormUtf8Cut(s, maxBytes)
    s = tostring(s or "")
    maxBytes = tonumber(maxBytes) or 0
    if maxBytes <= 0 or #s <= maxBytes then return s end
    local cut = s:sub(1, maxBytes)
    while #cut > 0 do
        local b = cut:byte(#cut)
        if b and b >= 0x80 and b <= 0xBF then
            cut = cut:sub(1, #cut - 1)                 -- хвост многобайтового символа
        else
            if b and b >= 0xC0 then cut = cut:sub(1, #cut - 1) end   -- висячий ведущий байт
            break
        end
    end
    return cut
end

-- v1.14.9: отказ по ответу сервера — ДВА сообщения:
--   1) «/a Форма от администратора >> Nick >> была отклонена.»
--   2) «/a Игрок уже сидит в тюрьме.»     (текст сервера как есть)
function grndFormRejectMsg(nick)
    return grndFormBadMsg(nick)
end

function grndFormRejectSend(nick, reason)
    local head = grndFormRejectMsg(nick)
    grndChatSend(head)
    local detail = grndFormDetailMsg(reason)
    if detail ~= "" then grndChatSend(detail) end
    return head, detail
end

-- включить сторожа после отправки команды из формы
function grndFormWatchStart(form, cmd, cmdName)
    local W = _G.GRND_FORMWAIT
    if type(W) ~= "table" then return false end
    if not grndFormWaitCfgOn() then return false end    -- режим «отчёт сразу»
    -- если сторож ещё ждёт прошлую форму — доотчитываемся по ней как обычно
    if W.active then pcall(grndFormWatchFinish, "timeout") end
    local sec = tonumber(_G.GRND_FORM_WAIT_SEC) or 2.5
    if sec < 0.5 then sec = 0.5 end
    if sec > 10 then sec = 10 end
    W.active   = true
    W.done     = false
    W.nick     = tostring((type(form) == "table" and form.adminNick) or "")
    W.cmd      = tostring(cmd or "")
    W.cmdName  = tostring(cmdName or "")
    W.reason   = grndFormWaitReasonPart(cmd, cmdName)
    do
        -- v1.14.5: у оффлайн-команд (/offjail Nick …) первый аргумент — НИК,
        -- поэтому цифру в нике нельзя принимать за ID цели.
        local syn = GRND_FORM_SYNTAX[tostring(cmdName or ""):lower()]
        local spec = (type(syn) == "table" and type(syn.args) == "string") and syn.args or ""
        if spec:sub(1, 1) == "i" or spec:sub(1, 1) == "v" then
            W.targetId = tonumber(tostring(cmd or ""):match("[/%!%.]?%a[%w_]*%s+(%d+)")) or nil
        else
            W.targetId = nil
        end
    end
    W.sec      = sec
    W.at       = os.clock()
    W.last     = ""
    W.settleAt = nil      -- v1.14.1: когда «дослушать» ответ и отчитаться
    W.unknown  = ""       -- v1.14.1: последний неразобранный ответ сервера
    W.shadowUntil = nil   -- v1.14.2: до когда ждём опоздавший отказ («догон»)
    W.targetNick = ""     -- v1.14.2: ник цели для команд вида «/warn Nick …»
    do
        local syn = GRND_FORM_SYNTAX[tostring(cmdName or ""):lower()]
        if type(syn) == "table" and type(syn.args) == "string" and syn.args:sub(1, 1) == "n" then
            local tok = tostring(cmd or ""):match("^%s*[/%!%.]?%a[%w_]*%s+(%S+)") or ""
            if tok:find("^%d+$") then
                -- v1.14.12: цель — ID («/warn 15 DM | M.Fomin»). На сервер ушёл
                -- именно ID, но в ответе сервера может встретиться НИК цели,
                -- поэтому сторожу даём и ID, и известный ник: строку ответа он
                -- признает «про нашу команду» по любому из них.
                W.targetId = tonumber(tok) or W.targetId
                local on, nick = grndFormTargetOnline(tok)
                W.targetNick = (on and nick) or ""
            else
                W.targetNick = tok
            end
        end
    end
    pcall(grndTrace, "forms", string.format("сторож: жду ответ сервера %.1f с на «%s»", sec, W.cmd))
    return true
end

-- завершить сторожа: mode = «fail» (сервер отказал) / «ok» / «timeout»
function grndFormWatchFinish(mode, reason)
    local W = _G.GRND_FORMWAIT
    if type(W) ~= "table" or not W.active then return false end
    W.active = false
    W.done   = true
    local nick = W.nick
    if mode == "fail" then
        local why = grndFormWaitNorm(reason or W.last or "")
        local msg, detail = grndFormRejectSend(nick, why)
        pcall(grndTrace, "forms", "сторож: ОТКАЗ сервера -> " .. tostring(msg)
            .. " | " .. tostring(detail))
        if type(notify) == "table" and notify.add then
            local short = grndFormUtf8Cut(why, 70)     -- не рвём UTF-8 символы
            pcall(notify.add, "Сервер не применил наказание — в /a ушла отмена: " .. short, "warn", 5)
        end
    else
        grndFormAcceptSend(nick)
        pcall(grndTrace, "forms", "сторож: отказов нет -> форма принята (" .. tostring(mode) .. ")"
            .. ((mode == "answered" and W.unknown ~= nil and W.unknown ~= "")
                and (" | ответ сервера: " .. tostring(W.unknown)) or ""))
        -- v1.14.2: «догон». Отчёт ушёл мгновенно, но сервер мог прислать
        -- отказ чуть позже (второй строкой) — тогда в /a уйдёт уточнение.
        if (mode == "answered" or mode == "ok") and grndFormCorrectCfgOn() then
            W.shadowUntil = (W.at or os.clock()) + (tonumber(W.sec) or 2.5)
        else
            W.shadowUntil = nil
        end
    end
    return true
end

-- каждая серверная строка чата проходит через сторожа
function grndFormWatchOnChat(text)
    local W = _G.GRND_FORMWAIT
    if type(W) ~= "table" then return false end
    local u = grndFormWaitNorm(text)
    if u == "" then return false end
    if grndFormWaitIsReplika(u) then return false end

    -- v1.14.2: «ДОГОН». Отчёт уже ушёл (режим «мгновенно»), но сервер мог
    -- прислать отказ позже — например, второй строкой. Тогда в /a уходит
    -- уточнение «… была отклонена. <текст сервера>».
    if (not W.active) and W.shadowUntil and os.clock() <= W.shadowUntil then
        local probeC = grndFormWaitProbe(u, W.reason)
        if probeC ~= "" and not grndFormWaitIsNoise(u) then
            local vC = grndFormWaitClassify(probeC, W.cmdName)
            if vC == "fail" then
                W.shadowUntil = nil                    -- до отправки: своё эхо не считаем
                local msg, detail = grndFormRejectSend(W.nick, u)
                pcall(grndTrace, "forms", "догон: отказ пришёл позже -> в /a уточнение: "
                    .. tostring(msg) .. " | " .. tostring(detail))
                if type(notify) == "table" and notify.add then
                    local short = grndFormUtf8Cut(grndFormWaitNorm(u), 70)
                    pcall(notify.add, "Сервер отказал уже после отчёта — в /a ушло уточнение: "
                        .. short, "warn", 5)
                end
                return true
            end
        end
        return false
    end

    if not W.active then return false end
    local probe = grndFormWaitProbe(u, W.reason)
    if probe == "" then return false end
    local verdict = grndFormWaitClassify(probe, W.cmdName)
    W.last = u
    -- v1.14.2: в трассу пишем КАЖДУЮ строку, которую видит сторож, и её
    -- вердикт — так видно, почему скрипт решил «выдалось» или «не выдалось».
    pcall(grndTrace, "forms", string.format("сторож: строка «%s» -> %s", u,
        (verdict == "fail" and "ОТКАЗ") or (verdict == "ok" and "УСПЕХ")
        or "не про нашу команду"))
    if verdict == "fail" then
        grndFormWatchFinish("fail", u)                 -- текст сервера идёт в /a как есть
        return true
    elseif verdict == "ok" then
        grndFormWatchFinish("ok")                      -- сервер подтвердил — не ждём таймаут
        return true
    end
    -- v1.14.2: сервер что-то ответил, но ответ не распознан. Раньше в этом
    -- случае отчёт ждал конца окна ожидания (2.5 с) — отсюда «задержка».
    -- Теперь отчёт уходит МГНОВЕННО (GRND_FORM_SETTLE_SEC = 0); если нужен
    -- «пустышки» (вход/выход игрока, гос. новости и т. п.) мгновенный
    -- отчёт не вызывают — кроме тех, где есть ID или ник нашей цели.
    -- Текст ответа пишем в трассу: по нему видно, каких слов не хватает в
    -- GRND_FORM_OK_WORDS / GRND_FORM_FAIL_WORDS.
    if grndFormInstantCfgOn() and (not grndFormWaitIsNoise(u) or grndFormWaitIsRelated(u)) then
        W.unknown = u
        local settle = grndFormSettleSec()
        W.settleAt = os.clock() + settle
        pcall(grndTrace, "forms", string.format(
            "сторож: ответ сервера (пауза %.2f с): %s", settle, u))
        if settle <= 0 then
            grndFormWatchFinish("answered")            -- совсем без паузы
            return true
        end
    end
    return false
end

-- вызывается из основного цикла: таймаут ожидания ответа
function grndFormWatchTick()
    local W = _G.GRND_FORMWAIT
    if type(W) ~= "table" then return end
    local now = os.clock()
    if W.shadowUntil and now > W.shadowUntil then W.shadowUntil = nil end
    if not W.active then return end
    -- v1.14.1: сервер уже ответил — пауза «дослушать» истекла, отчитываемся
    -- сразу, не дожидаясь конца окна ожидания.
    if W.settleAt and now >= W.settleAt then
        grndFormWatchFinish("answered")
        return
    end
    if (now - (W.at or 0)) >= (W.sec or 2.5) then
        grndFormWatchFinish("timeout")
    end
end

-- =====================================================================
--  v1.13.0: ОКНО ФОРМЫ ЗАКРЫВАЕТСЯ МГНОВЕННО ([Y] / [N] / мышь / «+»).
--
--  Почему раньше «зависало»:
--   1) [Y]/[N] читались ТОЛЬКО внутри ImGui-кадра (wasKeyTapped). Кадр
--      рисуется не всегда (условие видимости не учитывало окно формы),
--      плюс тот же wasKeyTapped дёргали другие окна — нажатие терялось;
--   2) окно убиралось ПОСЛЕ отправки команды и уведомлений: любая ошибка
--      на этом пути оставляла GRND_FORMS.active непустым, и окно висело
--      до 30-секундного таймаута;
--   3) после закрытия мог остаться «последний кадр» с окном.
--
--  Теперь: состояние чистится ПЕРВЫМ делом, клавиши опрашиваются в
--  основном цикле каждый тик (grndFormsKeyTick), окно формы держит кадр
--  видимым, а после закрытия ещё ~0.35 с рисуется «пустой» кадр, чтобы
--  окно гарантированно стёрлось.
-- =====================================================================
_G.GRND_FORM_KEYS = _G.GRND_FORM_KEYS or { y = false, n = false }

-- подержать кадр, чтобы окно гарантированно стёрлось с экрана
-- =====================================================================
--  v1.14.13: ОКНО ФОРМЫ МОЖНО ПЕРЕСТАВИТЬ.
--
--  Раньше позиция была жёсткой: центр по X и 18% высоты, COND_ALWAYS —
--  окно всегда возвращалось на место, а флаг NoMove не давал его тянуть.
--
--  Теперь позиция своя (GRND_FORM_UI.x/y) и запоминается в конфиге,
--  поэтому форма открывается РОВНО там, куда её передвинули. Тащить —
--  за шапку при включённом курсоре (ПКМ), как окно рекона и HUD репортов:
--  без курсора ЛКМ уходит в игру (выстрел), тащить было бы нельзя.
--  Кнопка «×» из области захвата исключена. Позиция не выпускается за
--  пределы экрана (и после смены разрешения остаётся на экране).
-- =====================================================================

-- куда поставить окно: сохранённая позиция (или место по умолчанию),
-- вписанная в экран. Возвращает px, py.
function grndFormUiPos(resX, resY, fw, fh)
    local U = _G.GRND_FORM_UI
    if type(U) ~= "table" then U = {} end
    local w = tonumber(resX) or 1280
    local h = tonumber(resY) or 720
    fw = tonumber(fw) or 0
    fh = tonumber(fh) or 0
    local px = tonumber(U.x)
    local py = tonumber(U.y)
    if not px then px = math.floor((w - fw) / 2) end       -- место по умолчанию:
    if not py then py = math.floor(h * 0.18) end           -- центр сверху
    if px < 0 then px = 0 end
    if py < 0 then py = 0 end
    if px > w - fw then px = math.max(0, w - fw) end
    if py > h - fh then py = math.max(0, h - fh) end
    return px, py
end

-- один кадр перетаскивания окна формы. Возвращает px, py.
-- form — текущая форма (сменилась форма — перетаскивание бросаем, чтобы
-- окно не «поехало» за мышью уже без зажатой кнопки).
function grndFormUiDrag(form, px, py, fw, fh, resX, resY, headRect, skipRect)
    local U = _G.GRND_FORM_UI
    if type(U) ~= "table" then return px, py end
    if U.dragging and U.dragForm ~= form then
        -- форму приняли/отклонили прямо во время перетаскивания: окно уже
        -- стоит там, куда его дотащили, — позицию всё равно запоминаем
        U.dragging = false
        U.dragForm = nil
        if type(_G.grndCamCfgSave) == "function" then pcall(_G.grndCamCfgSave) end
    end

    local M = _G.GRND_MOUSE
    local mx = tonumber(M and M.x) or 0
    local my = tonumber(M and M.y) or 0
    local down = (M and M.down) and true or false
    local was = U.mouseWasDown and true or false
    U.mouseWasDown = down
    local justDown = down and not was
    local justUp = (not down) and was

    if U.dragging then
        if down then
            px = mx - (tonumber(U.dragDX) or 0)
            py = my - (tonumber(U.dragDY) or 0)
        else
            U.dragging = false
            U.dragForm = nil
            if not U.saved then                        -- пишем один раз на отпускании
                U.saved = true
                if type(_G.grndCamCfgSave) == "function" then pcall(_G.grndCamCfgSave) end
            end
        end
    elseif justDown and type(_G.grndMouseInside) == "function" then
        if _G.grndMouseInside(headRect)
            and not (skipRect and _G.grndMouseInside(skipRect)) then
            U.dragging = true
            U.dragForm = form
            U.saved = false
            U.dragDX = mx - px
            U.dragDY = my - py
        end
    end
    if justUp then U.saved = false end

    -- не выпускаем окно за экран
    local w = tonumber(resX) or 1280
    local h = tonumber(resY) or 720
    fw = tonumber(fw) or 0
    fh = tonumber(fh) or 0
    if px < 0 then px = 0 end
    if py < 0 then py = 0 end
    if px > w - fw then px = math.max(0, w - fw) end
    if py > h - fh then py = math.max(0, h - fh) end

    U.x, U.y = px, py
    return px, py
end

-- v1.14.15: ГЕОМЕТРИЯ ОКНА ФОРМЫ — ОДНА и для отрисовки, и для проверки
-- клика. Раньше координаты кнопок жили внутри блока отрисовки, а область
-- перетаскивания считалась отдельно: любое расхождение — и клик «промахивался».
GRND_FORM_POPUP_TIMEOUT_SEC = 5.0
GRND_FORM_UI_LAYOUT = {
    w = 400, h = 124,       -- компактное окно формы
    headH = 30,             -- высота шапки — область перетаскивания
    closeX = 374, closeY = 5, closeW = 20, closeH = 20,   -- «×»
    btnX = 12, btnY = 70, btnH = 34, btnGap = 8,          -- кнопки [Y] и [N]
}

-- прямоугольники окна: шапка, «×», «Принять», «Отклонить»
function grndFormUiRects(px, py)
    local L = _G.GRND_FORM_UI_LAYOUT
    if type(L) ~= "table" then return nil end
    px = tonumber(px) or 0
    py = tonumber(py) or 0
    local bx = tonumber(L.btnX) or 14
    local gap = tonumber(L.btnGap) or 8
    local bw = math.floor((L.w - 2 * bx - gap) / 2)
    return {
        head   = { x = px, y = py, w = L.w, h = L.headH },
        close  = { x = px + L.closeX, y = py + L.closeY, w = L.closeW, h = L.closeH },
        accept = { x = px + L.btnX, y = py + L.btnY, w = bw, h = L.btnH },
        reject = { x = px + L.btnX + bw + L.btnGap, y = py + L.btnY, w = bw, h = L.btnH },
    }
end

-- v1.14.15: клик по кнопкам окна, определённый ДО отрисовки кадра.
-- Возвращает «accept» / «reject» / nil. Срабатывает по ФРОНТУ нажатия ЛКМ
-- (GRND_MOUSE.down), поэтому одна и та же кнопка не срабатывает дважды:
-- после действия окно в этом кадре уже не рисуется.
function grndFormUiClick(px, py)
    local F = _G.GRND_FORMS
    local M = _G.GRND_MOUSE
    local U = _G.GRND_FORM_UI
    if type(F) ~= "table" or type(M) ~= "table" or type(U) ~= "table" then return nil end
    local down = M.down and true or false
    local was = U.clickWasDown and true or false
    U.clickWasDown = down
    if not (down and not was) then return nil end          -- нужен именно фронт
    -- защита от «сквозного» клика в следующую форму из очереди
    if tonumber(F.lastResolveAt) and (os.clock() - F.lastResolveAt) < 0.3 then
        return nil
    end
    local R = grndFormUiRects(px, py)
    if type(R) ~= "table" or type(_G.grndMouseInside) ~= "function" then return nil end
    if _G.grndMouseInside(R.close) then return "reject" end
    if _G.grndMouseInside(R.accept) then return "accept" end
    if _G.grndMouseInside(R.reject) then return "reject" end
    return nil
end

function grndFormsUiHold(sec)
    local F = _G.GRND_FORMS
    if type(F) ~= "table" then return end
    F.uiUntil = os.clock() + (tonumber(sec) or 0.35)
    if type(_G.ensureRender) == "function" then pcall(_G.ensureRender, true) end
end

-- «нужно ли рисовать кадр из-за формы» — для основного цикла и ImGui-гейта
function grndFormsUiWanted()
    local F = _G.GRND_FORMS
    if type(F) ~= "table" then return false end
    if F.active then return true end
    return (tonumber(F.uiUntil) or 0) > os.clock()
end

-- закрыть окно формы и выполнить действие: «accept» / «reject» / «approved» / «timeout»
function grndFormsResolve(action)
    local F = _G.GRND_FORMS
    if type(F) ~= "table" then return false end
    local form = F.active
    if not form then
        F.want = nil
        return false
    end
    -- 1) СНАЧАЛА убираем окно: даже если отправка команды упадёт с ошибкой,
    --    окно уже закрыто и не «зависнет» на экране.
    local nextForm = table.remove(F.queue or {}, 1)
    if type(nextForm) == "table" then nextForm.openedAt = os.clock() end
    F.active = nextForm
    F.want = nil
    F.lastResolveAt = os.clock()      -- v1.14.15: метка для «сквозного» клика
    grndFormsUiHold(0.35)
    -- v1.14.15: кадр на стирание заказываем ОБЕИМИ ручками — и глобальной
    -- ensureRender (может быть заглушкой до инициализации ImGui), и той, что
    -- реально выставляет im.Process. Иначе «последний кадр» с окном оставался
    -- на экране до следующего события.
    if type(_G.grndEnsureRender) == "function" then pcall(_G.grndEnsureRender, true) end
    do
        local K = _G.GRND_FORM_KEYS
        if type(K) == "table" then K.y, K.n = true, true end   -- одно нажатие = одно действие
    end
    -- 2) и только потом команды/уведомления
    if action == "accept" then
        local commandName = grndFormCommandName(form.cmd)
        -- Defensive guard for stale/legacy queue entries: unsupported commands
        -- close silently and never generate chat output or execute a command.
        if not grndFormIsAllowed(commandName) then
            pcall(grndTrace, "forms", "устаревшая команда формы проигнорирована: " .. tostring(form.cmd))
            return true
        end
        local okA, sentCmd, sentStatus, sentWhy = pcall(grndFormApply, form)
        if not okA then
            local applyErr = tostring(sentCmd)
            pcall(grndTrace, "forms", "ошибка приёма формы: " .. applyErr)
            sentCmd, sentStatus, sentWhy = form.cmd, "bad", applyErr
        end
        if type(notify) == "table" and notify.add then
            if sentStatus == "redirected" then
                local text = sentWhy
                    and "Форма /unban отклонена; пропишите её в Discord (сообщение не отправлено)"
                    or "Форма /unban отклонена — пропишите её в Discord"
                pcall(notify.add, text, sentWhy and "warn" or "info", 5)
            elseif sentStatus == "bad" then
                pcall(notify.add, "Форма не отправлена: " .. tostring(sentWhy or "команда неверна"), "warn", 5)
            elseif not grndFormIsPunish(commandName) then
                pcall(notify.add, "Форма принята: " .. tostring(sentCmd or form.cmd), "ok", 3)
            elseif grndFormWaitCfgOn() then
                pcall(notify.add, "Команда отправлена: " .. tostring(sentCmd or form.cmd)
                    .. " — жду ответ сервера", "ok", 3)
            else
                pcall(notify.add, "Форма принята: " .. tostring(sentCmd or form.cmd), "ok", 3)
            end
        end
    elseif action == "reject" then
        if type(notify) == "table" and notify.add then
            pcall(notify.add, "Форма от " .. grndUtf8Text(form.adminNick) .. " отклонена", "info", 2)
        end
    elseif action == "approved" then
        pcall(grndTrace, "forms", "форму уже одобрили без нас — окно закрыто")
        if type(notify) == "table" and notify.add then
            pcall(notify.add, "Форму уже одобрили в админ-чате — окно закрыто", "info", 3)
        end
    end
    return true
end

-- опрос [Y]/[N] из основного цикла — не зависит от ImGui-кадров
function grndFormsKeyTick()
    local K = _G.GRND_FORM_KEYS
    if type(K) ~= "table" then return end
    if type(isKeyDown) ~= "function" then return end
    local okY, dY = pcall(isKeyDown, 0x59)             -- Y
    local okN, dN = pcall(isKeyDown, 0x4E)             -- N
    local y = (okY and dY) and true or false
    local n = (okN and dN) and true or false
    local yPrev, nPrev = K.y or false, K.n or false
    K.y, K.n = y, n                                    -- состояние помним всегда,
    local yEdge = (y and not yPrev)                    -- чтобы «старое» нажатие
    local nEdge = (n and not nPrev)                    -- не сработало на новом окне
    if not (yEdge or nEdge) then return end
    local F = _G.GRND_FORMS
    if type(F) ~= "table" or not F.active then return end
    -- не перехватываем клавиши, пока открыт чат или диалог
    if type(sampIsChatInputActive) == "function" then
        local okC, isC = pcall(sampIsChatInputActive)
        if okC and isC then return end
    end
    if type(sampIsDialogActive) == "function" then
        local okD, isD = pcall(sampIsDialogActive)
        if okD and isD then return end
    end
    if yEdge then grndFormsResolve("accept") else grndFormsResolve("reject") end
end

-- =====================================================================
--  v1.13.0: «[ATOOLS]: +» В АДМИН-ЧАТЕ = ФОРМУ УЖЕ ОДОБРИЛИ БЕЗ НАС.
--  Окно формы закрывается сразу (без отправки команды и без отчёта в /a),
--  а из самой этой строки новая форма НЕ создаётся.
-- =====================================================================
function grndFormAdminLine(text)
    local u=grndFormWaitNorm(text)
    u=u:gsub("{%x%x%x%x%x%x%x%x}","")
    -- Channel mark must precede the sender header. Ordinary player chat is ignored.
    u=u:gsub("\194\160"," "):gsub("\239\187\191","")
    local start,finish=u:find("<[Aa][Dd][Mm]>")
    if not finish then start,finish=u:find("%[[Aa][Dd][Mm]%]") end
    if not finish then return nil end
    local prefix=u:sub(1,start-1)
    prefix=prefix:gsub("^%s*%[%d%d:%d%d:%d%d%]%s*",""):gsub("^%s*%[%d%d:%d%d%]%s*","")
    if prefix:find("%S") then return nil end  -- not a quoted ADM line in player chat
    local header=u:sub(finish+1)
    local nick,id,body=header:match("^%s*([^%s%[%]:]+)%s*%[(%d+)%]%s*:%s*(.*)$")
    if not nick then
        -- Optional rank text between <ADM> and Nick[ID], as in the old parser.
        nick,id,body=header:match(".-([^%s%[%]:]+)%s*%[(%d+)%]%s*:%s*(.*)$")
    end
    if not nick then return nil end
    return nick,tonumber(id),body,u
end

function grndFormsApprovedOnChat(text,source)
    local nick,id,body,clean=grndFormAdminLine(text)
    if not body then return false end
    local tag,tail=body:match("^%s*%[%s*([%a%s_%-]+)%]%s*:%s*(.-)%s*$")
    local tagged=tag and tag:lower():gsub("[^%a]","")=="atools"
    local hit=false
    if tagged then
        hit=tail:match("^%+[%s%.!]*$")~=nil
        if not hit then
            local low=grndFormWaitLower(tail)
            for _,word in ipairs({"принял","приняла","одобрил","одобрила","выполнено","accepted"}) do
                if low==word or low:sub(1,#word+1)==word.." " then hit=true;break end
            end
        end
    elseif _G.GRND_FORM_CLOSE_BARE_PLUS then
        hit=body:match("^%s*%+[%s%.!]*$")~=nil
    end
    if not hit then return false end
    local F=_G.GRND_FORMS
    if type(F)~="table" then return true end
    -- The same server line can reach both onServerMessage and onAddChatMessage.
    -- Do not let the second hook approve the NEXT form in the queue.
    source=source or "direct"
    local now=os.clock()
    local eventKey=nick:lower()..":"..id..":"..body
    local prev=F.lastApprovalEvent
    if prev and prev.key==eventKey and now-prev.at>=0 and now-prev.at<1
        and not prev.sources[source] then
        prev.sources[source]=true
        return true
    end
    F.lastApprovalEvent={key=eventKey,at=now,sources={[source]=true}}
    if F.active then
        local ok,err=pcall(grndFormsResolve,"approved")
        if not ok then pcall(grndTrace,"forms","ошибка закрытия ATOOLS: "..tostring(err)) end
    end
    return true
end


-- =====================================================================
--  v1.11.79: ЗАЯВКА НА ГОСУДАРСТВЕННЫЕ НОВОСТИ (/acceptgnews).
--
--  Сервер пишет в чат: «Появилась заявка на государственные новости, для
--  получения дополнительной информации: /acceptgnews». Ловим эту строку и
--  показываем окно «Принять гос.волну?» ([Y] принять / [N] отклонить).
--
--  [Y] отправляет на сервер /acceptgnews и в /a «Принял(-а)
--  государственную волну!». v1.14.34: если в чате пришло сообщение
--  «Администратор … принял заявку гос. волны игрока …», окно сразу
--  закрывается БЕЗ отправки команды или отчёта от нас.
-- =====================================================================
GRND_GNEWS_POPUP_TIMEOUT_SEC = 5.0
GRND_GNEWS = _G.GRND_GNEWS or { active = false, at = 0, uiUntil = 0 }

-- Держим короткий ПУСТОЙ кадр после закрытия: в mimgui без активного окна
-- обработчик OnFrame прекращает кадры, и прежняя картинка могла зависнуть.
function grndGnewsUiWanted()
    local G = _G.GRND_GNEWS
    if type(G) ~= "table" then return false end
    return (G.active == true) or ((tonumber(G.uiUntil) or 0) > os.clock())
end

function grndGnewsClose()
    local G = _G.GRND_GNEWS
    if type(G) ~= "table" or not G.active then return false end
    G.active = false
    G.preview = nil
    G.uiUntil = os.clock() + 0.35
    if type(_G.ensureRender) == "function" then pcall(_G.ensureRender, true) end
    if type(_G.grndEnsureRender) == "function" then pcall(_G.grndEnsureRender, true) end
    return true
end

-- текст сообщения в UTF-8 и без цветовых кодов (сервер шлёт CP1251)
function grndGnewsClean(text)
    local t = tostring(text or "")
    if t == "" then return "" end
    local u = t
    if type(_G.grndToUtf) == "function" then
        local ok, c = pcall(_G.grndToUtf, t)
        if ok and type(c) == "string" and c ~= "" then u = c end
    end
    u = u:gsub("{%x%x%x%x%x%x}", ""):gsub("{%X%X%X%X%X%X}", "")
    return u
end

-- Подтверждение ДРУГИМ администратором: только сообщение о реально
-- принятой заявке, не само приглашение /acceptgnews и не отказ/разговор.
-- Порядок слов важен; ники, их скобки и цветовые коды могут отличаться.
function grndGnewsAcceptedLine(u)
    local low = grndLowerUtf(u)
    local _, admEnd = low:find("администратор", 1, true)
    if not admEnd then return false end
    local acceptedStart, requestEnd = low:find("принял%s+заявк%S*", admEnd + 1)
    if not acceptedStart then
        acceptedStart, requestEnd = low:find("приняла%s+заявк%S*", admEnd + 1)
    end
    if not acceptedStart then return false end
    -- «не принял заявку» — не подтверждение, закрывать окно нельзя.
    if low:sub(admEnd + 1, acceptedStart - 1):find("%sне%s*$") then return false end
    local _, waveEnd = low:find("гос%.?%s*волны", requestEnd + 1)
    if not waveEnd then
        _, waveEnd = low:find("государственн%S*%s+волны", requestEnd + 1)
    end
    if not waveEnd then
        _, waveEnd = low:find("государственн%S*%s+новости", requestEnd + 1)
    end
    return waveEnd ~= nil and low:find("игрока", waveEnd + 1, true) ~= nil
end

function grndGnewsOnChat(text)
    local u = grndGnewsClean(text)
    if u == "" then return false end
    -- Сначала проверяем завершение даже при заблокированном UI: такая строка
    -- может содержать /acceptgnews, но НЕ должна заново открыть окно.
    if grndGnewsAcceptedLine(u) then
        grndGnewsClose()
        return true
    end
    if type(grndSessionReady) == "function" and not grndSessionReady() then return end
    local low = grndLowerUtf(u)
    -- основная примета — сама команда (ASCII, от кодировки не зависит),
    -- плюс текст заявки, если пришёл другой сборкой сервера
    local hit = (low:find("/acceptgnews", 1, true) ~= nil)
        or (low:find("заявка на государственные новости", 1, true) ~= nil)
    if not hit then return false end
    local G = GRND_GNEWS
    if type(G) ~= "table" then return false end
    if G.active then return false end          -- окно уже открыто — не дублируем
    G.active, G.at, G.preview = true, os.clock(), u:sub(1, 120)
    G.uiUntil = 0
    if type(_G.ensureRender) == "function" then pcall(_G.ensureRender, true) end
    return true
end

-- [Y]: принять волну и отчитаться в админ-чат, если она ЕЩЁ доступна.
function grndGnewsAccept()
    if not grndGnewsClose() then return false end
    grndChatSend("/acceptgnews")                          -- v1.14.14: всегда по-настоящему
    grndChatSend("/" .. tostring(_G.GRND_FORM_CH or "a")
        .. " Принял(-а) государственную волну!")          -- отчёт в чат (CP1251)
    return true
end


-- =====================================================================
--  v1.11.80: ХЕЛПЕРЫ ДЛЯ «ПАРАМЕТРОВ ИГРОКА».
--  v1.11.83: скорость — окно по КАДРАМ (без часов) + подстраховка данными
--            самой игры; оружие — из игры, серверная строка только как
--            подсказка (и мусор вида «Hbyc|0» больше не показывается).
-- =====================================================================
GRND_PARAM_CACHE = _G.GRND_PARAM_CACHE or {}

-- настройки сглаживания по каждому полю:
--   eps    — на сколько должно измениться значение, чтобы это был «новый» факт
--   hold   — сколько секунд держим последнее значение, если поле пропало
--   settle — сколько новое значение должно продержаться, чтобы его приняли
--   jump   — при каком изменении показываем сразу (nil — сразу не показываем)
--   frames/holdF — окно медианы в КАДРАХ (для скорости: без часов)
GRND_PARAM_CFG = {
    hp    = { eps = 0.5, hold = 3.0, settle = 0.25, jump = 5.0 },
    arm   = { eps = 0.5, hold = 3.0, settle = 0.25, jump = 5.0 },
    ammo  = { eps = 0.5, hold = 3.0, settle = 0.25, jump = 5.0 },
    ping  = { eps = 3.0, hold = 4.0, settle = 0.40, jump = 5.0 },
    speed = { eps = 1.0, hold = 3.0, settle = 0.30, frames = 15, holdF = 45 },
    weap  = { eps = 0,   hold = 3.0, settle = 0.55 },
}

GRND_PARAM_MED_FRAMES = 15      -- окно медианы: последние 15 кадров (~0.25 с)
GRND_PARAM_MED_HOLD   = 45      -- сколько кадров держим значение, если поле пропало

-- шкала: 100 = полная линия (если у игрока больше 100 — линия всё равно полная)
function grndParamScale(v)
    v = tonumber(v) or 100
    if v < 100 then return 100 end
    return v
end

-- стабильное ЧИСЛО параметра (убирает «тряску» между источниками)
function grndParamNum(id, key, raw)
    local now = os.clock()
    local ck = tostring(id or 0) .. ":" .. tostring(key)
    local C = _G.GRND_PARAM_CACHE
    local cfg = GRND_PARAM_CFG[key] or { eps = 0.5, hold = 3.0, settle = 0.30 }
    local e = C[ck]
    if not e then e = { key = key }; C[ck] = e end

    local n = tonumber(raw)
    if n == nil then
        -- поле пропало: короткие пропадания не показываем вообще
        if e.v ~= nil and (now - (e.at or 0)) < cfg.hold then return e.v end
        e.v, e.cand, e.candAt = nil, nil, nil
        return nil
    end
    -- округление у самых границ: 99.6 -> 100, 0.3 -> 0
    if math.abs(n - 100) < 0.5 then n = 100 elseif math.abs(n) < 0.5 then n = 0 end

    if e.v == nil then
        e.v, e.at = n, now
        return e.v
    end
    local d = math.abs(n - e.v)
    local eps = cfg.eps or 0.5
    if d < eps then
        e.at = now                       -- то же значение: «освежаем» и не мигаем
        e.cand, e.candAt = nil, nil
        return e.v
    end
    -- «сразу» показываем только настоящий прыжок (ХП/броня/пинг);
    -- у полей без cfg.jump мгновенных обновлений нет вообще
    if (cfg.jump and d >= cfg.jump) or eps <= 0 then
        e.v, e.at, e.cand, e.candAt = n, now, nil, nil
        return e.v
    end
    -- пограничное: показываем, только если продержалось settle секунд
    if e.cand ~= nil and math.abs(n - e.cand) < 0.5 and (now - (e.candAt or 0)) >= (cfg.settle or 0.3) then
        e.v, e.at, e.cand, e.candAt = n, now, nil, nil
        return e.v
    end
    if e.cand == nil or math.abs(n - e.cand) >= 0.5 then e.cand, e.candAt = n, now end
    e.at = now
    return e.v
end

-- v1.11.83: окно фильтра ПО КАДРАМ — для скорости. В версии 1.11.82 окно
-- считалось по os.clock(), а это ПРОЦЕССОРНОЕ время: в игре оно идёт не как
-- настенные часы, окно растягивалось на секунды, и медиана «залипала» на
-- нуле (скорость показывалась как 0). Здесь часов нет вообще: держим
-- последние GRND_PARAM_MED_FRAMES показаний, берём медиану и не даём
-- показаниям «дрожать» (мёртвая зона eps).
function grndParamFrames(id, key, raw, cfg)
    local ck = tostring(id or 0) .. ":" .. tostring(key)
    local C = _G.GRND_PARAM_CACHE
    local e = C[ck]
    if not e then e = { key = key, hist = {} }; C[ck] = e end
    e.hist = e.hist or {}

    local n = tonumber(raw)
    if n == nil then
        e.miss = (e.miss or 0) + 1
        if e.v ~= nil and e.miss <= (cfg.holdF or GRND_PARAM_MED_HOLD) then return e.v end
        e.v, e.hist, e.miss = nil, {}, 0
        return nil
    end
    e.miss = 0
    if math.abs(n - 100) < 0.5 then n = 100 elseif math.abs(n) < 0.5 then n = 0 end

    local h = e.hist
    h[#h + 1] = n
    local maxN = cfg.frames or GRND_PARAM_MED_FRAMES
    while #h > maxN do table.remove(h, 1) end
    local vals = {}
    for i = 1, #h do vals[i] = h[i] end
    table.sort(vals)
    local m = vals[math.ceil(#vals / 2)]

    if e.v == nil then e.v = m return e.v end
    if math.abs(m - e.v) >= (cfg.eps or 1) then e.v = m return e.v end
    return e.v
end

-- стабильная СТРОКА параметра (то же, но для текстовых полей)
function grndParamStr(id, key, raw)
    local now = os.clock()
    local ck = tostring(id or 0) .. ":" .. tostring(key)
    local C = _G.GRND_PARAM_CACHE
    local cfg = GRND_PARAM_CFG[key] or { hold = 3.0, settle = 0.5 }
    local e = C[ck]
    if not e then e = { key = key }; C[ck] = e end
    local s = tostring(raw or "")
    if s == "" then
        if e.v ~= nil and (now - (e.at or 0)) < (cfg.hold or 3) then return e.v end
        e.v, e.cand, e.candAt = nil, nil, nil
        return ""
    end
    if e.v == nil then e.v, e.at = s, now return e.v end
    if s == e.v then e.at = now e.cand, e.candAt = nil, nil return e.v end
    if e.cand == s and (now - (e.candAt or 0)) >= (cfg.settle or 0.5) then
        e.v, e.at, e.cand, e.candAt = s, now, nil, nil
        return e.v
    end
    if e.cand ~= s then e.cand, e.candAt = s, now end
    e.at = now
    return e.v
end

-- строка с числом внутри («100 км/ч», «12 мин»): сглаживаем ЧИСЛО (по кадрам,
-- если так задано в cfg), а хвост («км/ч») берём из последнего принятого
-- показания: сервер успевает присылать его обрезанным, и строка дёргалась.
function grndParamLabel(id, key, raw)
    local s = tostring(raw or "")
    if s == "" then return s end
    local pre, num, post = s:match("^(%s*)([-+]?%d+[%.,]?%d*)(.*)$")
    if not num then return s end
    local n = tonumber((num:gsub(",", ".")))
    if not n then return s end
    local cfg = GRND_PARAM_CFG[key] or {}
    local st
    if cfg.frames then
        st = grndParamFrames(id, key, n, cfg)
    else
        st = grndParamNum(id, key, n)
    end
    if st == nil then return s end
    -- хвост: выкидываем «полоски» (||||, ####, ====) — сервер меняет их
    -- каждым обновлением, из-за чего строка мигала
    post = tostring(post or ""):gsub("[|#=*_<>]+", " ")
    post = post:gsub("^%s+", ""):gsub("%s+$", "")
    if post ~= "" then post = " " .. post end
    pre = tostring(pre or "")
    local ck = tostring(id or 0) .. ":" .. tostring(key) .. ":tail"
    local T = _G.GRND_PARAM_TAIL
    if not T then T = {}; _G.GRND_PARAM_TAIL = T end
    local e = T[ck]
    if math.abs(n - st) < 0.75 then          -- это показание и есть текущее
        e = { pre = pre, post = post, at = os.clock() }
        T[ck] = e
    end
    if (not e) or (os.clock() - (e.at or 0)) > 5 then
        e = { pre = pre, post = post }
    end
    return tostring(e.pre or "") .. tostring(math.floor(st + 0.5)) .. tostring(e.post or "")
end

-- =====================================================================
--  v1.11.83: СКОРОСТЬ. Основной источник — сервер (её формат и единицы мы
--  не меняем), но если сервер показывает 0 или вообще ничего, а цель по
--  данным игры едет — показываем реальную скорость из игры в км/ч.
--  Раньше в этом случае в окне висел «0».
-- =====================================================================
function grndSpeedFromGame(id)
    local SN = _G.grndSpecNative
    if not SN then return nil end
    -- v1.19.59: id — всегда число (он же идёт в ключ сглаживания)
    id = tonumber(id)
    local ms = nil
    -- цель в транспорте: у педа в машине скорость нулевая, берём скорость машины
    if type(SN.getVehicleId) == "function"
        and type(sampGetCarHandleBySampVehicleId) == "function"
        and type(getCarSpeed) == "function" then
        local okv, vehId = pcall(SN.getVehicleId, id)
        if okv and type(vehId) == "number" and vehId >= 0 then
            local okh, vh = pcall(sampGetCarHandleBySampVehicleId, vehId)
            if okh and type(vh) == "number" and vh ~= 0 then
                local oks, sp = pcall(getCarSpeed, vh)
                if oks and type(sp) == "number" then ms = math.abs(sp) end
            end
        end
    end
    -- пешком (или если машину найти не удалось)
    if (not ms) or ms < 0.5 then
        if type(SN.pedOf) == "function" and type(getCharSpeed) == "function" then
            local okp, ped = pcall(SN.pedOf, id)
            if okp and ped then
                local oks, sp = pcall(getCharSpeed, ped)
                if oks and type(sp) == "number" then
                    sp = math.abs(sp)
                    if (not ms) or sp > ms then ms = sp end
                end
            end
        end
    end
    if not ms then return nil end
    if ms ~= ms or ms < 0 or ms > 300 then return nil end   -- NaN/мусор — не число
    -- 3.6 = м/с -> км/ч: getCarSpeed/getCharSpeed дают скорость в м/с
    -- (так считают все спидометры на MoonLoader: getCarSpeed(car) * 3.6)
    local kmh = grndParamFrames(id, "speed_game", ms * 3.6,
        { eps = 1.5, frames = GRND_PARAM_MED_FRAMES, holdF = GRND_PARAM_MED_HOLD })
    if kmh == nil then return nil end
    if kmh ~= kmh or kmh < 0 then return nil end
    return math.floor(kmh + 0.5)
end

-- итоговая строка для строки «Скорость».
-- v1.19.59: в карточку попадает ТОЛЬКО число и единица измерения. Раньше
-- сюда шла сырая серверная строка (полоски вида «|||| 45», хвосты «Hbyc|0»,
-- чужие символы) — в окне выходила «непонятная надпись». Теперь:
--   1) основной источник — измерение по самой игре (машина/пеший, км/ч),
--      сглаженное окном кадров (grndSpeedFromGame);
--   2) серверное число берём, только если игра ничего не дала ИЛИ цель
--      стоит, а сервер видит движение (у далёкой цели пед может не
--      стримиться, тогда игра честно показывает 0);
--   3) ни одного лишнего символа: «45 км/ч», «0 км/ч», «—».
function grndSpeedDisplay(id, serverRaw, bare)
    local g = grndSpeedFromGame(id)                  -- число км/ч или nil
    local sNum = tonumber(tostring(serverRaw or ""):match("%-?%d+"))
    local kmh
    if g ~= nil then
        kmh = g
        if kmh < 3 and sNum and sNum > kmh then kmh = sNum end
    else
        kmh = sNum
    end
    if kmh == nil then return "—" end
    if kmh < 0 then kmh = 0 end
    if kmh > 999 then kmh = 999 end
    local out = tostring(math.floor(kmh + 0.5))
    -- bare — значение для карточки: в образце единицы не пишутся (просто «45»)
    if not bare then out = out .. " км/ч" end
    return out
end

