do
    local KL = GRND_KL
    KL.enabled    = KL.enabled or false          -- тумблер чекера
    KL.rows       = KL.rows or 6                 -- сколько строк показывать
    KL.scale      = KL.scale or 1.0              -- размер килл-листа
    KL.x, KL.y    = KL.x, KL.y                   -- nil = позиция по умолчанию
    -- v1.8.3: эти флаги больше не настраиваются — всегда так.
    KL.showScore  = false                        -- счёт не показываем
    KL.showId     = true                         -- «Ник[ID]»
    KL.alignK     = true                         -- ники вплотную к значку
    KL.textShadow = true                         -- тень текста
    -- v1.16: подложка панели ВЫКЛЮЧЕНА по умолчанию — чекер выглядит как
    -- родной килл-лист игры (надписи прямо на картинке, без тёмного
    -- прямоугольника). Включается тумблером «Фон» в настройках чекера
    -- (вкладка «Чекеры»); выбранное значение хранится в конфиге.
    KL.bg         = (KL.bg == true)
    KL.fromChat   = true                         -- подхват из чата
    KL.newestTop  = true                         -- новые сверху
    KL.showWName  = (KL.showWName == true)       -- подпись оружия рядом со значком
    KL.showTime   = KL.showTime or false         -- время убийства
    KL.bgAlpha    = KL.bgAlpha or 120
    KL.maxHist    = 60                           -- глубина своей истории
    KL.expanded   = KL.expanded or false         -- раскрыта ли карточка в меню
    KL.anim       = KL.anim or 0                 -- анимация появления оверлея
    KL.animSet    = KL.animSet or 0              -- анимация раскрытия настроек
    KL.moving     = false                        -- режим «прилип к курсору»
    KL.armed      = false
    KL.armAt      = 0
    KL.cancel     = false
    KL.click      = false
    KL.hist       = KL.hist or {}                -- история: старые -> новые
    KL.snap       = KL.snap or {}                -- предыдущий снимок структуры
    KL.ptr        = nil                          -- указатель на stKillInfo (CDeathWindow)
    KL.off        = nil                          -- какой офсет указателя подошёл
    KL.slot       = nil                          -- адрес самой переменной-указателя
    KL.base       = nil                          -- база samp.dll
    KL.ver        = KL.ver                       -- версия клиента (по PE), если известна
    KL.src        = KL.src                       -- источник: "версия" / "api" / "офсет"
    KL.score      = KL.score or 0                -- оценка правдоподобности структуры
    KL.origEn     = KL.origEn                    -- iEnabled до первого гашения
    KL.apiOk      = KL.apiOk                     -- есть ли в сборке sampGetKillInfoPtr
    KL.verifyAt   = KL.verifyAt or 0             -- последняя проверка записи iEnabled
    KL.badReads   = 0
    KL.badValid   = 0
    KL.orient     = KL.orient or 1               -- 1: новый бой в слоте 1, 2: в слоте 5
    KL.snapAt     = 0
    KL.tickAt     = 0
    KL.validAt    = 0
    KL.memFail    = 0
    KL.nativeOff  = false
    KL.w, KL.h    = KL.w or 0, KL.h or 0
    KL.cfgLoaded  = false
    KL.cfgDirty   = false
    KL.cfgSavedAt = 0
    KL.scoreMap   = KL.scoreMap or {}
    KL.scoreMapAt = 0
    KL.scoreAt    = 0
    KL.warned     = false
    KL.ffiTried   = false
    KL.err        = nil

    local function klUtf(s)
        if type(s) ~= "string" or s == "" then return s end
        local ok, r = pcall(grndToUtf, s)
        if ok and type(r) == "string" then return r end
        return s
    end

    -- ---------- чтение строк структуры ----------
    local function klFfi()
        if KL.ffiTried then return KL.ffiStr ~= nil end
        KL.ffiTried = true
        local ok, ffi = pcall(require, "ffi")
        if ok and ffi then
            KL.ffi = ffi
            local ok2, fn = pcall(function()
                return function(a, n)
                    return ffi.string(ffi.cast("const char*", a), n)
                end
            end)
            if ok2 and type(fn) == "function" then KL.ffiStr = fn end
        end
        return KL.ffiStr ~= nil
    end

    local function klClip(s)
        if type(s) ~= "string" then return "" end
        local cut = s:find("%z")
        if cut then s = s:sub(1, cut - 1) end
        if #s > 24 then s = s:sub(1, 24) end
        return s
    end

    -- «безопасное» чтение (через memory.lua, без ffi-указателей)
    local function klNickSafe(a)
        local s
        if type(grndMemRdStr) == "function" then
            local ok, r = pcall(grndMemRdStr, a, 25)
            if ok and type(r) == "string" then s = r end
        end
        return klClip(s or "")
    end
    -- быстрое чтение (ffi, только для уже проверенного указателя)
    local function klNickFast(a)
        if klFfi() then
            local ok, r = pcall(KL.ffiStr, a, 25)
            if ok and type(r) == "string" then return klClip(r) end
        end
        return klNickSafe(a)
    end

    local function klEntryAt(p, i)
        local e = p + 4 + (i - 1) * 59
        local k = klNickFast(e)
        local v = klNickFast(e + 25)
        local kc = grndMemRd32(e + 50) or 0
        local vc = grndMemRd32(e + 54) or 0
        local ty = grndMemRd8(e + 58) or 0
        return { k = k, v = v, kc = kc, vc = vc, t = ty }
    end

    -- memory.lua отдаёт ЗНАКОВЫЕ int32: адрес выше 0x7FFFFFFF приходит
    -- отрицательным, поэтому все адреса нормализуем в u32.
    local function klNorm(v)
        v = tonumber(v)
        if not v then return nil end
        v = math.floor(v)
        if v < 0 then v = v + 0x100000000 end
        return v
    end

    -- ---------- структурная проверка указателя ----------
    -- ГЛАВНАЯ ПРАВКА v1.5.1. Объект CDeathWindow, на который указывает
    -- переменная по офсету в samp.dll, размещён в КУЧЕ процесса, а не
    -- внутри образа samp.dll. В v1.5 требовалось «указатель внутри образа» —
    -- поэтому структура не находилась никогда, и системный килл-лист не
    -- перехватывался. Теперь проверяем правдоподобность адреса и
    -- целостность полей структуры.
    local function klPtrPlausible(p)
        p = klNorm(p)
        if not p then return false end
        if p < 0x10000 or p > 0xFFFF0000 then return false end   -- до 4 ГБ (LAA)
        if p % 4 ~= 0 then return false end
        return true
    end

    -- Сырые байты: ffi (быстро), иначе memory.lua побайтово. Вызывается
    -- только при поиске структуры и редких проверках.
    local function klRawBytes(a, n)
        if klFfi() then
            local ok, s = pcall(KL.ffiStr, a, n)
            if ok and type(s) == "string" and #s == n then return s end
        end
        local t = {}
        for i = 0, n - 1 do
            local b = grndMemRd8(a + i)
            if b == nil then return nil end
            t[#t + 1] = string.char(b)
        end
        return table.concat(t)
    end

    -- В поле ника допустимы нули (пустая строка / хвост буфера) и байты
    -- >= 0x20 (в т.ч. 0x80+ — ники в CP1251/UTF-8).
    local function klNickBytesSane(s)
        if type(s) ~= "string" or #s ~= 25 then return false end
        for i = 1, 25 do
            local b = s:byte(i)
            if b ~= 0 and b < 0x20 then return false end
        end
        return true
    end

    -- «Похоже ли это на stKillInfo»: адрес правдоподобен, iEnabled = 0/1,
    -- все 50 байт каждого из пяти ников — текст или нули. Пустой список
    -- (нули) — это НОРМА (в начале сессии), поэтому текста не требую.
    -- Дополнительно считается оценка по полям после записей (m_pDevice,
    -- m_pFont, m_position, m_nLongestNickWidth) — чтобы выбрать лучшего
    -- кандидата и отсеять «нулевые» области памяти при переборе офсетов.
    local function klPtrOk(p)
        p = klNorm(p)
        if not klPtrPlausible(p) then return false, 0, "адрес" end
        local en = grndMemRd32(p)
        if en == nil then return false, 0, "не читается" end
        en = klNorm(en)
        if en ~= 0 and en ~= 1 then return false, 0, "iEnabled=" .. tostring(en) end
        for i = 1, 5 do
            local e = p + 4 + (i - 1) * 59
            if not (klNickBytesSane(klRawBytes(e, 25)) and klNickBytesSane(klRawBytes(e + 25, 25))) then
                return false, 0, "записи"
            end
        end
        local score = 0
        local pdev  = klNorm(grndMemRd32(p + 0x147) or 0)   -- m_pDevice
        local pfont = klNorm(grndMemRd32(p + 0x137) or 0)   -- m_pFont
        local posx  = grndMemRd32(p + 0x12F)                -- m_position[0]
        local posy  = grndMemRd32(p + 0x133)                -- m_position[1]
        local nickw = grndMemRd32(p + 0x12B)                -- m_nLongestNickWidth
        if pdev  >= 0x10000 and pdev  <= 0xFFFF0000 and pdev  % 4 == 0 then score = score + 3 end
        if pfont >= 0x10000 and pfont <= 0xFFFF0000 and pfont % 4 == 0 then score = score + 2 end
        if type(posx) == "number" and posx >= -4000 and posx <= 4000
            and type(posy) == "number" and posy >= -4000 and posy <= 4000 then score = score + 2 end
        if type(nickw) == "number" and nickw >= 0 and nickw <= 4096 then score = score + 1 end
        for i = 1, 5 do
            local e = p + 4 + (i - 1) * 59
            if klNickFast(e) ~= "" or klNickFast(e + 25) ~= "" then
                score = score + 2
                break
            end
        end
        return true, score, nil
    end

    -- ---------- версия клиента (PE-заголовок samp.dll) ----------
    local function klPeInfo(h)
        local pe = klNorm(grndMemRd32(h + 0x3C) or 0)
        if pe == 0 or pe > 0x1000 then return nil end
        if klNorm(grndMemRd32(h + pe) or 0) ~= 0x00004550 then return nil end
        local ep   = klNorm(grndMemRd32(h + pe + 0x28) or 0)   -- AddressOfEntryPoint
        local size = klNorm(grndMemRd32(h + pe + 0x50) or 0)   -- SizeOfImage
        return ep, size
    end

    -- ---------- разрешение указателя ----------
    local function klProbeRecord(off, src, p)
        local rec = { off = off, p = p, src = src }
        if not p or p == 0 then
            rec.why = "нуль"
            return rec
        end
        local ok, score, why = klPtrOk(p)
        rec.ok, rec.score, rec.why = ok, score, why
        if ok then rec.en = klNorm(grndMemRd32(p)) end
        return rec
    end

    -- =================================================================
    --  УНИВЕРСАЛЬНЫЙ ПОИСК УКАЗАТЕЛЯ (v1.5.5)
    -- =================================================================
    --  Проблема: таблица офсетов знает только «официальные» сборки. На
    --  кастомных лаунчерах/сборках (0.3.DL, чужие R-версии, обфускация)
    --  указатель на CDeathWindow лежит по другому адресу — и структура не
    --  находится НИКОГДА.
    --
    --  Решение: не угадывать офсет, а искать САМУ структуру по содержимому.
    --  В записываемых секциях данных samp.dll лежит указатель на объект в
    --  куче (CDeathWindow создаётся через new). Перебираем все 4-байтовые
    --  значения секций и проверяем:
    --     * адрес правдоподобен (0x10000..0xFFFF0000 — до 4 ГБ, кратен 4);
    --     * по адресу лежит iEnabled = 0 или 1;
    --     * все 5 записей по 59 байт содержат осмысленные ники (klPtrOk);
    --  и берём лучшего кандидата по оценке (m_pDevice, m_pFont, позиция,
    --  непустые ники). Так находится ЛЮБАЯ раскладка структуры.
    local function klSections(h)
        local out = {}
        local pe = klNorm(grndMemRd32(h + 0x3C) or 0)
        if pe == 0 or pe > 0x1000 then return out end
        if klNorm(grndMemRd32(h + pe) or 0) ~= 0x00004550 then return out end
        local nsec    = klNorm(grndMemRd32(h + pe + 0x06) or 0) or 0
        local optSize = klNorm(grndMemRd32(h + pe + 0x14) or 0) or 0
        if nsec <= 0 or nsec > 96 or optSize > 0x400 then return out end
        local st = h + pe + 0x18 + optSize
        for i = 0, nsec - 1 do
            local b = st + i * 40
            local name = (klRawBytes(b, 8) or ""):gsub("%z.*$", "")
            local vsize = klNorm(grndMemRd32(b + 0x08) or 0) or 0
            local va    = klNorm(grndMemRd32(b + 0x0C) or 0) or 0
            local rsize = klNorm(grndMemRd32(b + 0x10) or 0) or 0
            local chars = klNorm(grndMemRd32(b + 0x24) or 0) or 0
            -- размер для чтения: НЕ больше образа и не больше «сырых» данных
            -- секции (хвост page-aligned области может быть не отображён —
            -- читать его небезопасно). Нули за концом данных указателей не
            -- содержат, поэтому ничего не теряем.
            local sz = math.min(vsize > 0 and vsize or rsize,
                                rsize > 0 and rsize or vsize)
            out[#out + 1] = {
                name = name, va = va, size = sz,
                writable = (chars >= 0x80000000),                     -- MEM_WRITE
                exec = (math.floor(chars / 0x20000000) % 2 == 1),     -- MEM_EXECUTE
            }
        end
        return out
    end

    -- Все кандидаты-указатели, отсортированные по оценке структуры.
    function klScanCandidates(limit, maxBytes, timeLimit)
        local out = {}
        local startedAt = os.clock()
        local h = KL.base
        if not h then
            local ok, mh = pcall(getModuleHandle, "samp.dll")
            if ok and type(mh) == "number" and mh ~= 0 then h = klNorm(mh); KL.base = h end
        end
        if not h then KL.scanWhy = "нет samp.dll" return out end
        local secs = klSections(h)
        KL.secs = secs
        local order = {}
        for _, s in ipairs(secs) do
            -- код не сканируем: указатель на объект лежит в данных
            if s.size > 0 and s.size <= 4 * 1024 * 1024 and not (s.exec and not s.writable) then
                order[#order + 1] = s
            end
        end
        table.sort(order, function(a, b)
            if a.writable ~= b.writable then return a.writable end
            return a.size > b.size
        end)
        local budget = limit or 4096
        local checked, scanned = 0, 0
        for _, s in ipairs(order) do
            local bytes
            if klFfi() then
                local okr, str = pcall(KL.ffiStr, h + s.va, s.size)
                if okr and type(str) == "string" and #str == s.size then bytes = str end
            end
            local n = bytes and #bytes or math.min(s.size, 262144)
            -- v1.19.57: у автоматического перебора есть предел по объёму и
            -- времени — иначе он читал мегабайты секций в одном тике и
            -- подвешивал игру
            if maxBytes and n > maxBytes then n = maxBytes end
            local i = 0
            while i + 4 <= n do
                local p
                if bytes then
                    local b1, b2, b3, b4 = bytes:byte(i + 1, i + 4)
                    p = b1 + b2 * 256 + b3 * 65536 + b4 * 16777216
                else
                    p = klNorm(grndMemRd32(h + s.va + i) or -1) or -1
                end
                if klPtrPlausible(p) then
                    local en = klNorm(grndMemRd32(p) or -1)
                    if en == 0 or en == 1 then
                        checked = checked + 1
                        local okc, score = klPtrOk(p)
                        if okc then
                            out[#out + 1] = { p = p, slot = h + s.va + i,
                                              score = score or 0, sec = s.name }
                        end
                        if checked >= budget then break end
                    end
                end
                i = i + 4
            end
            scanned = scanned + 1
            if checked >= budget then break end
            if timeLimit and (os.clock() - startedAt) >= timeLimit then
                KL.scanStat = "перебор прерван по времени — продолжаю позже"
                break
            end
        end
        KL.scanStat = ("секций %d, проверено кандидатов %d, подошло %d, бюджет %d")
            :format(scanned, checked, #out, budget)
        table.sort(out, function(a, b) return a.score > b.score end)
        return out
    end

    -- Ручной поиск + печать результата (/grndkl scan).
    function grndKlScanNow()
        grndKlSay("ищу структуру килл-листа перебором памяти…")
        local t0 = os.clock()
        local cands = klScanCandidates(8192)
        local ms = math.floor((os.clock() - t0) * 1000)
        grndKlSay((KL.scanStat or "") .. (", время " .. ms .. " мс"))
        if #cands == 0 then
            grndKlSay("кандидатов нет — структуры в памяти samp.dll ещё нет (или клиент другой)")
            return false
        end
        for i = 1, math.min(#cands, 5) do
            local c = cands[i]
            grndKlSay(("  %d) %s  (переменная samp.dll+0x%X, секция %s, оценка %d)")
                :format(i, grndKlHx(c.p), c.slot - (KL.base or 0), tostring(c.sec), c.score))
        end
        local best = cands[1]
        KL.ptr, KL.slot, KL.off = best.p, best.slot, best.slot - (KL.base or 0)
        KL.src, KL.score = "поиск", best.score
        KL.origEn = klNorm(grndMemRd32(best.p))
        KL.memFail, KL.badReads, KL.badValid = 0, 0, 0
        grndKlSay(("структура принята: %s (iEnabled=%s), проверьте /grndkl test")
            :format(grndKlHx(best.p), tostring(KL.origEn)))
        return true
    end

    function grndKlResolve()
        if KL.ptr then return true end
        local ok, h = pcall(getModuleHandle, "samp.dll")
        if not ok or type(h) ~= "number" or h == 0 then return false end
        h = klNorm(h)
        KL.base = h
        KL.probe = {}
        local cands = {}
        local rank = { ["api"] = 3, ["версия"] = 2, ["офсет"] = 1, ["поиск"] = 1 }
        local function add(p, off, src, score, slot)
            cands[#cands + 1] = { p = p, off = off, src = src, score = score or 0, slot = slot }
        end

        -- 1) версия клиента -> точный офсет (самый надёжный путь)
        local ep, imgsize = klPeInfo(h)
        KL.entry, KL.imgsize = ep, imgsize          -- v1.5.5: для /grndkl
        local vi = ep and GRND_KL_VERS[ep]
        if vi then
            KL.ver = vi.ver
            local slot = h + vi.off
            local rec = klProbeRecord(vi.off, "версия", klNorm(grndMemRd32(slot)))
            KL.probe[#KL.probe + 1] = rec
            if rec.ok then add(rec.p, vi.off, "версия", rec.score, slot) end
        end

        -- 2) встроенная функция MoonLoader (если есть в сборке)
        if type(sampGetKillInfoPtr) == "function" then
            local ok2, p = pcall(sampGetKillInfoPtr)
            if ok2 and type(p) == "number" then
                local rec = klProbeRecord(0, "api", klNorm(p))
                KL.apiOk = rec.ok and true or false
                KL.probe[#KL.probe + 1] = rec
                if rec.ok then add(rec.p, 0, "api", rec.score, nil) end
            end
        end

        -- 3) перебор известных офсетов (для R4-2 / 0.3.DL и незнакомых сборок)
        for _, off in ipairs(GRND_KL_OFFS) do
            if not (vi and vi.off == off) then
                local slot = h + off
                local rec = klProbeRecord(off, "офсет", klNorm(grndMemRd32(slot)))
                KL.probe[#KL.probe + 1] = rec
                if rec.ok then add(rec.p, off, "офсет", rec.score, slot) end
            end
        end

        -- 4) v1.5.5: перебор памяти по содержимому структуры — для сборок,
        --    которых нет в таблице офсетов. Запускается нечасто (раз в 6 с и
        --    максимум 3 раза автоматически; дальше — вручную /grndkl scan).
        do
            local now = os.clock()
            local auto = (KL.scanTries or 0) < 3
            if ((now - (KL.scanAt or 0)) >= 6.0) and auto then
                KL.scanAt = now
                KL.scanTries = (KL.scanTries or 0) + 1
                -- авто-перебор: 1024 кандидата, 512 КБ на секцию и не больше
                -- 40 мс на тик — игра не замирает
                local okS, found = pcall(klScanCandidates, 1024, 524288, 0.04)
                if okS and found and #found > 0 then
                    KL.scanTop = found
                    for i = 1, math.min(#found, 3) do
                        local c = found[i]
                        if c.score >= 4 then
                            add(c.p, c.slot - h, "поиск", c.score, c.slot)
                        end
                    end
                    pcall(grndTrace, "killlist", ("перебор памяти: подходящих структур %d (%s)")
                        :format(#found, tostring(KL.scanStat)))
                end
            end
        end

        -- выбор: приоритет источника (api > версия > офсет/поиск), затем оценка.
        -- Для перебора офсетов и поиска требуется оценка >= 4: так
        -- отсеиваются «пустые» области, которые формально проходят проверку.
        local best
        for _, c in ipairs(cands) do
            if (c.src == "офсет" or c.src == "поиск") and c.score < 4 then c = nil end
            if c then
                if not best then
                    best = c
                else
                    local rb, rc = rank[best.src] or 0, rank[c.src] or 0
                    if rc > rb or (rc == rb and c.score > best.score) then best = c end
                end
            end
        end
        if not best then return false end
        KL.ptr    = best.p
        KL.off    = best.off
        KL.src    = best.src
        KL.score  = best.score or 0
        KL.slot   = best.slot or ((best.off and best.off > 0) and (h + best.off) or nil)
        KL.origEn = klNorm(grndMemRd32(KL.ptr))
        KL.err    = nil
        KL.memFail, KL.badReads, KL.badValid = 0, 0, 0
        if KL.src == "поиск" then
            pcall(grndTrace, "killlist", ("структура найдена перебором памяти: %s (samp.dll+0x%X, оценка %d)")
                :format(grndKlHx(KL.ptr), KL.off or 0, KL.score or 0))
        end
        return true
    end

    -- Сбросить указатель: клиент пересоздал структуру (реконнект) либо
    -- запись в неё не держится (офсет не от этой сборки).
    local function klForgetPtr()
        KL.ptr, KL.slot, KL.off, KL.src = nil, nil, nil, nil
        KL.origEn, KL.score = nil, 0
        KL.memFail, KL.badReads, KL.badValid = 0, 0, 0
        -- v1.6.0: указатель потерян — разрешаем поиск в памяти заново
        if KL.heapDone and (KL.heapAt or 0) > 0 then
            KL.heapDone, KL.heapAt, KL.heapBytes = false, nil, nil
            KL.heapStat = "указатель потерян — ищем заново"
        end
    end

    -- Погасить (show = false) или вернуть (show = true) системный килл-лист.
    -- true — только если запись прошла И подтвердилась чтением.
    function grndKlNativeShow(show)
        local KL2 = GRND_KL
        local ptr = KL2.ptr or KL2.apiPtr
        if not ptr then return false end
        local target = show and 1 or 0
        local ok = pcall(grndMemWr32, ptr, target)
        pcall(grndMemWr8, ptr, target)
        local rb = klNorm(grndMemRd32(ptr))
        KL2.nativeOff = (target == 0)
        if not (ok and rb == target) then return false end
        KL2.badReads = 0
        return true
    end

    -- ---------- счёт игроков («Ник[счёт]») ----------
    -- ВАЖНО (правка после первого игрового теста): вызов
    -- sampGetPlayerNickname(id) / sampGetPlayerScore(id) с НЕсуществующим
    -- (отключённым) id валит скрипт с ошибкой «cannot resume non-suspended
    -- coroutine», причём pcall её не перехватывает — скрипт умирает.
    -- Поэтому спрашиваем данные ТОЛЬКО у ids, которые сейчас подключены.
    local function klConnected(id)
        if type(id) ~= "number" then return false end
        if type(sampIsPlayerConnected) ~= "function" then return false end
        local ok, conn = pcall(sampIsPlayerConnected, id)
        return (ok and conn) and true or false
    end

    local function klNickOf(id)
        if type(sampGetPlayerNickname) ~= "function" then return nil end
        if not klConnected(id) then return nil end
        local ok, n = pcall(sampGetPlayerNickname, id)
        if ok and type(n) == "string" and n ~= "" then return n end
        return nil
    end

    local function klScore(id)
        if type(id) ~= "number" then return nil end
        if type(sampGetPlayerScore) ~= "function" then return nil end
        if not klConnected(id) then return nil end
        local ok, s = pcall(sampGetPlayerScore, id)
        if ok and type(s) == "number" then return s end
        return nil
    end

    local function klSampReady()
        if type(isSampAvailable) ~= "function" then return true end
        local ok, avail = pcall(isSampAvailable)
        return (ok and avail) and true or false
    end

    local function klScoreMapRefresh()
        local now = os.clock()
        -- v1.5.9: троттлинг действует и на ПУСТОЙ таблице (иначе при пустой
        -- таблице перебор 1000 ID запускался бы на каждой записи), а «ещё ни
        -- разу не перечитывали» (scoreMapAt = 0) больше не считается свежим:
        -- первая же запись получает свой счёт сразу, а не через 3 секунды.
        local last = tonumber(KL.scoreMapAt) or 0
        if last ~= 0 and (now - last) < 3.0 then return end
        KL.scoreMapAt = now
        local map = {}
        if type(sampIsPlayerConnected) ~= "function" or not klSampReady() then
            KL.scoreMap = map
            return
        end
        local maxId = 999
        if type(sampGetMaxPlayerId) == "function" then
            local ok, m = pcall(sampGetMaxPlayerId)
            if ok and type(m) == "number" and m > 0 and m < 1000 then maxId = m end
        end
        for id = 0, maxId do
            local n = klNickOf(id)          -- внутри уже есть проверка подключения
            if n then map[n] = id end
        end
        KL.scoreMap = map
    end

    -- v1.5.9: «ЗАМОРОЗКА» ЧИСЛА В СКОБКАХ.
    -- Раньше счёт перечитывался каждые 3 секунды (klScoreRefreshHist), поэтому
    -- «Ник[31]» через минуту становился «Ник[40]» — число менялось прямо в
    -- килл-листе. Теперь значение берётся ОДИН раз (как только игрок найден)
    -- и не меняется, пока ЭТА запись висит в списке — ровно так ведёт себя
    -- родной килл-лист клиента. Заново число появится только у НОВОЙ записи
    -- этого игрока (новое убийство — новый снимок).
    -- kid/vid (служебные ID для клика-слежки) продолжают обновляться, а для
    -- показа хранятся замороженные копии: kidF/vidF (ID) и ks/vs (счёт).
    local function klFreezeIds(rec)
        pcall(klScoreMapRefresh)                 -- внутри свой троттлинг: не чаще раза в 3 с
        local kidNow = KL.scoreMap[rec.k]
        local vidNow = KL.scoreMap[rec.v]
        if kidNow ~= nil then rec.kid = kidNow end          -- служебный, живой
        if vidNow ~= nil then rec.vid = vidNow end
        if rec.kidF == nil and kidNow ~= nil then rec.kidF = kidNow end   -- для показа
        if rec.vidF == nil and vidNow ~= nil then rec.vidF = vidNow end
        if rec.ks == nil and rec.kidF ~= nil then rec.ks = klScore(rec.kidF) end
        if rec.vs == nil and rec.vidF ~= nil then rec.vs = klScore(rec.vidF) end
    end
    local klResolveIds = klFreezeIds          -- прежнее имя (совместимость)

    -- Обход последних записей: добирает то, что не успело разрешиться сразу
    -- (игрока не было в таблице), но НИЧЕГО не перезаписывает.
    local function klScoreRefreshHist()
        for n = #KL.hist, math.max(1, #KL.hist - 19), -1 do
            local r = KL.hist[n]
            if r then pcall(klFreezeIds, r) end
        end
    end

    -- ---------- добавление записи ----------
    local function klPush(e, src)
        local now = os.clock()
        src = src or "mem"
        -- Дедупликация между ИСТОЧНИКАМИ: чат и память приносят одно и то же
        -- убийство — второе в течение 3 с не добавляем. Дубль из памяти
        -- возможен (та же пара убита снова) — его не режем, иначе теряются
        -- реальные повторные убийства одной и той же пары.
        for n = #KL.hist, 1, -1 do
            local r = KL.hist[n]
            if (now - (r.t or 0)) > 3.0 then break end
            if r.k == e.k and r.v == e.v and r.src ~= src then
                -- Это то же убийство, но из другого источника: строку не
                -- добавляем, зато добираем то, чего в ней не хватает —
                -- оружие из чата («(Deagle)») или цвета из памяти клиента.
                if (not r.wnameu) and e.wnameu then r.wnameu = e.wnameu end
                if (not r.typ or r.typ == 0) and e.t and e.t ~= 0 then r.typ = e.t end
                if src == "mem" or src == "rpc" then
                    if (not r.kc or r.kc == 0) and e.kc and e.kc ~= 0 then r.kc = e.kc end
                    if (not r.vc or r.vc == 0) and e.vc and e.vc ~= 0 then r.vc = e.vc end
                end
                return false
            end
        end
        local rec = {
            k = e.k, v = e.v,
            ku = klUtf(e.k), vu = klUtf(e.v),
            kc = e.kc, vc = e.vc, typ = e.t,
            -- v1.5.2: «чем убит». Для записей из памяти это id оружия
            -- (byteType записи stKillEntry); для подхвата из чата — название,
            -- если сервер пишет его в скобках: «Ник убил Ник (Deagle)».
            wnameu = e.wnameu,
            t = now, time = os.date("%H:%M:%S"),
            kid = nil, vid = nil, ks = nil, vs = nil,
            kidF = nil, vidF = nil,      -- v1.5.9: замороженные ID для показа
            src = src,
        }
        pcall(klFreezeIds, rec)                  -- ID в скобках всегда
        table.insert(KL.hist, rec)
        while #KL.hist > (KL.maxHist or 60) do table.remove(KL.hist, 1) end
        return true
    end

    function grndKlClear()
        GRND_KL.hist = {}
        GRND_KL.snap = {}
    end

    -- ---------- v1.7.5: ОСНОВНОЙ источник — RPC DeathMessage ----------
    -- samp.events.onPlayerDeathNotification приходит ДО того, как клиент
    -- добавит строку в родной килл-лист. Возвращаем false — родной список
    -- вообще не получает запись, а мы кладём её в свою историю с ID
    -- оружия и цветами игроков. Больше не зависим от поиска CDeathWindow.
    function grndKlFeedRpc(killerId, killedId, reason)
        if not KL.enabled then return false end
        killerId = tonumber(killerId) or 65535
        killedId = tonumber(killedId) or 65535
        reason = tonumber(reason) or 0
        local function nickOf(id)
            if id == 65535 or id < 0 then return "" end
            if type(sampGetPlayerNickname) ~= "function" then return "" end
            local okc, conn = pcall(sampIsPlayerConnected, id)
            local isMe = false
            if type(sampGetPlayerIdByCharHandle) == "function" then
                local okMe, res, myId = pcall(sampGetPlayerIdByCharHandle, PLAYER_PED)
                isMe = okMe and res and (tonumber(myId) == id) or false
            end
            if not ((okc and conn) or isMe) then return "" end
            local ok, n = pcall(sampGetPlayerNickname, id)
            if ok and type(n) == "string" then return n end
            return ""
        end
        local function colorOf(id)
            if id == 65535 or id < 0 or type(sampGetPlayerColor) ~= "function" then return 0 end
            local ok, c = pcall(sampGetPlayerColor, id)
            if ok and type(c) == "number" then
                if c < 0 then c = c + 0x100000000 end
                -- ARGB -> RGB (как в stKillEntry: 0x00RRGGBB)
                return c % 0x1000000
            end
            return 0
        end
        local k = nickOf(killerId)
        local v = nickOf(killedId)
        if v == "" then return false end
        local e = { k = k, v = v, kc = colorOf(killerId), vc = colorOf(killedId), t = reason }
        local pushed = klPush(e, "rpc")
        if pushed then
            local r = KL.hist[#KL.hist]
            if r then r.kid, r.vid = (killerId ~= 65535) and killerId or nil, killedId end
            KL.rpcAt = os.clock()
            KL.rpcCount = (KL.rpcCount or 0) + 1
        end
        return true
    end

    -- ---------- страховка: подхват убийств из чата ----------
    function grndKlFeedChat(text)
        -- v1.5.5: журнал для диагностики (/grndkl chat) — что пришло из чата и
        -- как это распозналось. Пишем ДО проверки тумблера, чтобы видеть и
        -- «подхват выключен».
        local clog
        do
            KL.chatLog = KL.chatLog or {}
            clog = KL.chatLog
            while #clog >= 14 do table.remove(clog, 1) end
            clog[#clog + 1] = { t = os.date("%H:%M:%S"), s = tostring(text or ""):sub(1, 96), r = "?" }
        end
        local clogEntry = clog[#clog]
        local function ret(v, tag)
            if clogEntry then clogEntry.r = tag end
            return v
        end
        if not KL.fromChat then return ret(false, "подхват выключен") end
        local s = tostring(text or "")
        s = s:gsub("{%x%x%x%x%x%x}", "")
        s = s:gsub("^%s+", ""):gsub("%s+$", "")
        if s == "" then return ret(false, "пустая строка") end
        -- v1.8.2: чат может прийти и CP1251, и UTF-8. Литералы «убил» в
        -- исходнике — UTF-8, поэтому сначала нормализуем строку, иначе
        -- кириллические ники/глаголы не совпадут и подхват молчит.
        s = klUtf(s)
        -- v1.5.2: оружие из скобок в конце сообщения — будет подписью в
        -- середине строки (если сервер его присылает).
        local wname
        do
            local w = s:match("%s*%(([^%)]*)%)%s*$")
            if w then
                w = w:gsub("^%s+", ""):gsub("%s+$", "")
                if w == "" or #w > 24 or w:match("^%d+$") then w = nil end
            end
            if w then wname = klUtf(w) end
        end
        local k, v
        k, v = s:match("^(.-)%s+убил%.?%s+(.-)$")
        if not k then k, v = s:match("^(.-)%s+убила%.?%s+(.-)$") end
        if not k then k, v = s:match("^(.-)%s+killed%s+(.-)$") end
        if not k then k, v = s:match("^(.-)%s+застрелил%.?%s+(.-)$") end
        if not k then return ret(false, "не «Ник убил Ник»") end
        local function nickChars(x)
            local n, i, len = 0, 1, #x
            while i <= len do
                local b = x:byte(i)
                if b >= 0xF0 then i = i + 4
                elseif b >= 0xE0 then i = i + 3
                elseif b >= 0xC0 then i = i + 2
                else i = i + 1 end
                n = n + 1
            end
            return n
        end
        local function clean(x)
            x = tostring(x or "")
            x = x:gsub("%s*%([^%)]*%)%s*$", "")      -- (Deagle) / (оружие)
            x = x:gsub("^%[%d+%]%s*", "")            -- [15] Ник
            x = x:gsub("%s*%[%d+%]%s*$", "")         -- Ник [15]
            x = x:gsub("^%s+", ""):gsub("%s+$", "")
            return x
        end
        k, v = clean(k), clean(v)
        if k == "" or v == "" then return ret(false, "пустые ники") end
        if nickChars(k) > 24 or nickChars(v) > 24 then return ret(false, "ник длиннее 24") end
        -- v1.8.2: кириллица в нике (UTF-8 / CP1251) больше не режется шаблоном %w
        local function nickOk(n)
            if n:find("[%c%s]") then return false end
            return n:find("[^%w_%.%-%[%]\128-\255]") == nil
        end
        if not nickOk(k) or not nickOk(v) then
            return ret(false, "ники не по шаблону")
        end
        local vl = v:lower()
        if vl == "вас" or vl == "you" or vl == "его" or vl == "её" then
            return ret(false, "жертва — «вас/you»")
        end
        local pushed = klPush({ k = k, v = v, kc = 0, vc = 0, t = 0, wnameu = wname }, "chat")
        return ret(pushed, pushed and ("распознано: " .. k .. " -> " .. v) or "дубль (уже есть)")
    end

    -- ---------- игрок по нику (клик по строке = «слежка») ----------
    -- Карту ник->id обновляем ТОЛЬКО по требованию: это обращения к игровому
    -- API (sampGetPlayerNickname по всем id), в фоне её дёргать незачем.
    function grndKlIdsNow()
        pcall(klScoreMapRefresh)
        return KL.scoreMap or {}
    end

    -- Ищем id по нику: точное совпадение, затем без учёта регистра и без
    -- серверных приставок вида «[15] Ник» (ник в списке может быть обрезан
    -- или дополнен сервером).
    function grndKlFindId(nick)
        nick = tostring(nick or "")
        if nick == "" then return nil end
        local map = KL.scoreMap
        if (not map) or (not next(map)) or (os.clock() - (KL.scoreMapAt or 0)) > 3.0 then
            map = grndKlIdsNow()
        end
        if not map then return nil end
        if map[nick] then return map[nick] end
        local function core(s)
            s = tostring(s or ""):gsub("^%[%d+%]%s*", "")
            if #s > 24 then s = s:sub(1, 24) end
            return s:lower()
        end
        local want = core(nick)
        if want == "" then return nil end
        local hit
        for n, id in pairs(map) do
            if core(n) == want then
                if hit == nil then hit = id end
            end
        end
        return hit
    end

    -- ---------- конфиг чекера ----------
    function grndKlCfgPath()
        if type(this_script_dir) == "function" then
            local okd, sd = pcall(this_script_dir)
            if okd and sd and tostring(sd) ~= "" then
                local pp = tostring(sd)
                while pp:sub(-1) == "/" or pp:sub(-1) == "\\" do pp = pp:sub(1, -2) end
                local sep = "\\"
                local okc, cf = pcall(function() return package.config end)
                if okc and type(cf) == "string" and #cf > 0 then sep = cf:sub(1, 1) end
                return pp .. sep .. "grnd_killlist.cfg"
            end
        end
        return "grnd_killlist.cfg"
    end

    function grndKlCfgSave()
        local ok, f = pcall(GRND_CONFIG.open, grndKlCfgPath(), "w")
        if not ok or not f then return false end
        local function w(k, v) f:write(k .. "=" .. tostring(v) .. "\n") end
        w("enabled", KL.enabled and 1 or 0)
        w("rows", math.floor(KL.rows or 6))
        w("scale", string.format("%.2f", KL.scale or 1.0))
        w("showScore", 0)
        w("alignK", 1)
        w("kMode", 3)          -- v1.8.3: ID/тень/чат зафиксированы (фон — с v1.16)
        w("textShadow", 1)
        w("showId", 1)
        w("showWName", KL.showWName and 1 or 0)
        w("showTime", KL.showTime and 1 or 0)
        w("fromChat", 1)
        w("newestTop", 1)
        w("bg", KL.bg and 1 or 0)      -- v1.16: фон — настраиваемый (по умолч. ВЫКЛ)
        w("bgAlpha", math.floor(KL.bgAlpha or 120))
        w("bgv", 2)                    -- метка версии оформления (см. загрузку)
        if KL.x then w("x", math.floor(KL.x)) end
        if KL.y then w("y", math.floor(KL.y)) end
        w("expanded", KL.expanded and 1 or 0)
        pcall(f.close, f)
        KL.cfgSavedAt = os.clock()
        KL.cfgDirty = false
        return true
    end

    function grndKlCfgLoad()
        local ok, f = pcall(GRND_CONFIG.open, grndKlCfgPath(), "r")
        KL.cfgLoaded = true
        if not ok or not f then return false end
        local bgvSeen = false      -- v1.16: конфиг уже знает про новый фон?
        for line in f:lines() do
            local k, v = tostring(line):match("^%s*([%w_]+)%s*=%s*(.-)%s*$")
            if k then
                local num = tonumber(v)
                if k == "enabled" then KL.enabled = (v == "1")
                elseif k == "rows" and num then KL.rows = math.max(1, math.min(24, math.floor(num)))
                elseif k == "scale" and num then
                    -- v1.6.3: границы как у ползунка в чекере — 0.5x..2.5x
                    -- (при базовом кегле 16 это 8..40 px)
                    KL.scale = math.max(0.5, math.min(2.5, num))
                elseif k == "showScore" then KL.showScore = (v == "1")
                elseif k == "alignK" then
                    -- v1.6.5: значение тумблера «Ники к значку» читается как
                    -- есть; по умолчанию (в свежем конфиге) он ВКЛЮЧЁН —
                    -- ники вплотную к значку, пустого места нет.
                    KL.alignK = (v == "1")
                elseif k == "kMode" and num then
                    KL.kMode = num      -- метка перевода конфига (см. ниже)
                elseif k == "textShadow" then KL.textShadow = (v == "1")
                elseif k == "showId" then KL.showId = (v == "1")
                elseif k == "showWName" then KL.showWName = (v == "1")
                elseif k == "showTime" then KL.showTime = (v == "1")
                elseif k == "fromChat" then KL.fromChat = (v == "1")
                elseif k == "newestTop" then KL.newestTop = (v == "1")
                elseif k == "bg" then KL.bg = (v == "1")
                elseif k == "bgv" and num then bgvSeen = true   -- v1.16
                elseif k == "bgAlpha" and num then KL.bgAlpha = math.max(0, math.min(255, num))
                elseif k == "x" and num then KL.x = num
                elseif k == "y" and num then KL.y = num
                elseif k == "expanded" then KL.expanded = (v == "1")
                end
            end
        end
        pcall(f.close, f)
        -- v1.8.3: эти опции больше не настраиваются. Старый конфиг мог
        -- выключить ID/тень — принудительно возвращаем рабочие значения.
        KL.showId, KL.showScore = true, false
        KL.alignK, KL.textShadow = true, true
        KL.fromChat, KL.newestTop = true, true
        -- v1.16: подложка панели теперь ВЫКЛЮЧЕНА по умолчанию. Конфиг,
        -- сохранённый старой версией (там всегда было bg=1), один раз
        -- переводим на «без фона» — чтобы новый вид появился сразу, без
        -- ручного вмешательства. Дальше значение читается из файла как
        -- есть, и тумблер «Фон» в настройках чекера его сохраняет.
        if not bgvSeen then
            KL.bg = false
            KL.cfgDirty = true
        end
        KL.bgv = 2
        if (tonumber(KL.kMode) or 0) < 3 then
            KL.kMode = 3
            KL.cfgDirty = true
        end
        return true
    end

    -- ---------- диагностика и самопроверка ----------
    function grndKlSay(s)
        print("[GRND-KL] " .. s)
        if type(sampAddChatMessage) == "function" then
            grndChatSay("{00D6AA}[KL]{FFFFFF} " .. s, -1)
        end
    end

    function grndKlHx(v) return v and string.format("0x%X", v) or "—" end

    function grndKlDiag()
        grndKlSay(("килл-лист: версия клиента %s, samp.dll %s"):format(KL.ver or "не определена", grndKlHx(KL.base)))
        grndKlSay(("встроенная sampGetKillInfoPtr: %s"):format(KL.apiOk and "есть" or "нет"))
        -- v1.6.0: гасится ли родной список и чем
        if KL.nativeOff then
            grndKlSay("перехват RPC DeathMessage: " .. ((KL.rpcCount or 0) > 0
                and (("работает, поймано %d"):format(KL.rpcCount)) or "пока ни одной записи"))
            grndKlSay("системный килл-лист гасится чекером (источник: "
                .. tostring(KL.nativeSrc or "?") .. ")")
        elseif KL.enabled then
            grndKlSay("системный килл-лист НЕ гасится: "
                .. tostring(KL.apiWhy or "нет sampGetKillInfoPtr и структуры"))
            grndKlSay("поиск структуры в памяти: " .. tostring(KL.heapStat or "не запускался")
                .. " · ускорить: /grndkl heap")
        else
            grndKlSay("чекер выключен — системный список работает как обычно")
        end
        -- v1.5.5: сведения о клиенте — по ним видно, почему не подошёл офсет
        grndKlSay(("клиент: entry point %s, образ %s, таблица офсетов %s"):format(
            grndKlHx(KL.entry), KL.imgsize and ("0x" .. string.format("%X", KL.imgsize)) or "—",
            KL.entry and (GRND_KL_VERS[KL.entry] and GRND_KL_VERS[KL.entry].ver or "НЕ знает этой сборки")
                     or "не прочитан"))
        if KL.ptr then
            local offs = (KL.off and KL.off > 0) and grndKlHx(KL.off) or "—"
            grndKlSay(("структура %s найдена (офсет %s, источник: %s, оценка %d)"):format(
                grndKlHx(KL.ptr), offs, tostring(KL.src or "?"), KL.score or 0))
            grndKlSay(("iEnabled=%s (при захвате было %s), чекер %s, записей в истории %d"):format(
                tostring(klNorm(grndMemRd32(KL.ptr))), tostring(KL.origEn),
                KL.enabled and "включён" or "выключен", #(KL.hist or {})))
            for i = 1, 5 do
                local e = KL.ptr + 4 + (i - 1) * 59
                grndKlSay(("  [%d] %s -> %s"):format(i, klNickFast(e), klNickFast(e + 25)))
            end
        else
            grndKlSay(("структура НЕ найдена (попыток: %d)"):format(KL.memFail or 0))
            for _, pr in ipairs(KL.probe or {}) do
                local offs = (pr.off and pr.off > 0) and ("+" .. grndKlHx(pr.off)) or "(api)"
                grndKlSay(("  %s %s -> %s  %s%s"):format(
                    tostring(pr.src or "?"), offs, grndKlHx(pr.p or 0),
                    pr.ok and ("ок, оценка " .. tostring(pr.score or 0))
                          or ("не подошёл: " .. tostring(pr.why or "?")),
                    pr.en and ("  iEnabled=" .. tostring(pr.en)) or ""))
            end
            if KL.scanStat then grndKlSay("перебор памяти: " .. KL.scanStat) end
            if KL.scanTop and #KL.scanTop > 0 then
                grndKlSay("лучшие кандидаты перебора (можно принять вручную через /grndkl scan):")
                for i = 1, math.min(#KL.scanTop, 5) do
                    local c = KL.scanTop[i]
                    grndKlSay(("  %d) %s (секция %s, оценка %d)"):format(
                        i, grndKlHx(c.p), tostring(c.sec), c.score))
                end
            end
            grndKlSay("если структура не находится — игра всё равно работает: убийства берутся из чата")
            grndKlSay("перебрать память сейчас: /grndkl scan · журнал чата: /grndkl chat")
            grndKlSay("полный отчёт в файл: /grndkl dump (resource/grnd/logs/grnd_kl_diag.txt)")
        end
        -- v1.5.7: чем нарисован текст и как стоят ники убийц
        local CH3 = GRND_FONT or {}
        grndKlSay("шрифт интерфейса: "
            .. tostring(CH3.fontLoadedPath or "НЕ загружен — системный шрифт обёртки")
            .. (CH3.ladderSizes and (" · кеглей в лестнице " .. tostring(#CH3.ladderSizes)) or ""))
        grndKlSay("выравнивание ников убийц: " .. tostring(KL.dbgAlign or "ещё не рисовалось"))
        local ATS = GRND_KL_ATLAS
        if ATS then
            if ATS.tex then
                grndKlSay(("значки оружия: оригинальный атлас загружен (%s)"):format(tostring(ATS.how)))
            else
                grndKlSay(("значки оружия: атлас НЕ загружен — запасной силуэт (%s)")
                    :format(tostring(ATS.why or "ещё не пробовали")))
                grndKlSay(("  функции обёртки: %s"):format(
                    (#(ATS.have or {}) > 0) and table.concat(ATS.have, ", ") or "ни одной"))
                for i, tr in ipairs(ATS.tries or {}) do
                    grndKlSay(("  %d) %s -> %s"):format(i, tr.name,
                        tr.ok and "ок" or ("не вышло: " .. tostring(tr.err))))
                end
                grndKlSay("  подробнее и с повтором: /grndkl tex")
            end
        end
        grndKlSay("в скобках у ника: " .. (KL.showId and "ID игрока" or "счёт игрока")
            .. " · берётся один раз при появлении записи и не меняется")
        grndKlSay("проверка записи в структуру: /grndkl test")
    end

    -- Самопроверка записи: пишем 0 -> читаем, пишем 1 -> читаем, возвращаем
    -- как было. Это ГАРАНТИРОВАННО показывает прямо в игре, что структура
    -- найдена верно и гашение системного списка реально работает.
    function grndKlSelfTest()
        if not KL.ptr then
            grndKlSay("самопроверка: структура не найдена — сначала /grndkl")
            return false
        end
        local cur = klNorm(grndMemRd32(KL.ptr))
        pcall(grndMemWr32, KL.ptr, 0)
        local rb0 = klNorm(grndMemRd32(KL.ptr))
        pcall(grndMemWr32, KL.ptr, 1)
        local rb1 = klNorm(grndMemRd32(KL.ptr))
        local okAll = (rb0 == 0 and rb1 == 1)
        pcall(grndMemWr32, KL.ptr, cur ~= nil and cur or 1)
        KL.badReads = 0
        grndKlSay(("самопроверка %s: 0 -> %s, 1 -> %s (было %s)"):format(
            okAll and "ПРОЙДЕНА" or "ПРОВАЛЕНА", tostring(rb0), tostring(rb1), tostring(cur)))
        if not okAll then
            KL.ptr, KL.slot, KL.src, KL.off = nil, nil, nil, nil
            grndKlSay("запись не проходит — ищу структуру заново (это не та сборка клиента)")
        end
        return okAll
    end

    -- =================================================================
    --  ДАМП ДИАГНОСТИКИ В ФАЙЛ (v1.5.6): /grndkl dump
    -- =================================================================
    --  Собирает в один текстовый файл всё, что нужно, чтобы разобраться
    --  издалека: версия и обёртка ImGui, база samp.dll и entry point,
    --  проверенные офсеты, кандидаты перебора памяти, состояние структуры,
    --  журнал значков (какие функции текстур есть в обёртке и что они
    --  вернули), журнал подхвата из чата, историю убийств, ошибки рендера и
    --  признаки окружения. Файл: resource/grnd/logs/grnd_kl_diag.txt.
    function grndKlDumpPath()
        return grndStoragePath("logs","grnd_kl_diag.txt")
    end

    function grndKlDump()
        local L = {}
        local function w(s) L[#L + 1] = tostring(s) end
        local function hx(v) return (type(v) == "number") and ("0x" .. string.format("%X", v)) or "—" end
        w("GRND TOOLS — диагностика килл-листа (чекер «Новый Kill List»)")
        w("сформировано: " .. tostring(os.date("%Y-%m-%d %H:%M:%S")))
        w("версия скрипта: 1.8.3")
        w("обёртка ImGui: " .. tostring(IMGUI_WRAP or "не определена"))
        if type(getMoonloaderVersion) == "function" then
            local okv, vmaj, vmin, vpat = pcall(getMoonloaderVersion)
            if okv then w(("MoonLoader: %s.%s.%s"):format(tostring(vmaj), tostring(vmin), tostring(vpat))) end
        end
        w("")
        w("=== СТРУКТУРА (stKillInfo / CDeathWindow) ===")
        w("база samp.dll: " .. hx(KL.base) .. ", entry point: " .. hx(KL.entry)
            .. ", размер образа: " .. hx(KL.imgsize))
        w("версия по таблице: " .. tostring(KL.ver or "НЕ определена"))
        if KL.ptr then
            w(("НАЙДЕНА: %s (samp.dll+0x%X), источник %s, оценка %d")
                :format(hx(KL.ptr), KL.off or 0, tostring(KL.src), KL.score or 0))
            w(("iEnabled сейчас: %s, при захвате: %s, гашение системного списка: %s")
                :format(tostring(klNorm(grndMemRd32(KL.ptr))), tostring(KL.origEn),
                        tostring(KL.nativeOff)))
            for i = 1, 5 do
                local e = KL.ptr + 4 + (i - 1) * 59
                w(("  запись %d: [%s] -> [%s]"):format(i, klNickFast(e), klNickFast(e + 25)))
            end
        else
            w(("НЕ НАЙДЕНА (попыток: %d)"):format(KL.memFail or 0))
        end
        w("")
        w("=== ПРОВЕРКИ ОФСЕТОВ ===")
        for _, pr in ipairs(KL.probe or {}) do
            w(("  %s %s -> %s  %s%s"):format(
                tostring(pr.src or "?"),
                (pr.off and pr.off > 0) and ("+" .. hx(pr.off)) or "(api)",
                hx(pr.p or 0),
                pr.ok and ("ок, оценка " .. tostring(pr.score or 0))
                      or ("не подошёл: " .. tostring(pr.why or "?")),
                pr.en and ("  iEnabled=" .. tostring(pr.en)) or ""))
        end
        w("")
        w("=== СИСТЕМНЫЙ КИЛЛ-ЛИСТ (гашение) ===")
        w("sampGetKillInfoPtr: " .. (KL.apiPtr and grndKlHx(KL.apiPtr)
            or ("НЕТ — " .. tostring(KL.apiWhy or "ещё не пробовали"))))
        w("гашение чекером: " .. (KL.nativeOff
            and ("АКТИВНО, источник " .. tostring(KL.nativeSrc or "?"))
            or (KL.enabled and "НЕ АКТИВНО — гасить нечем" or "не нужно (чекер выключен)")))
        w("поиск структуры в памяти: " .. tostring(KL.heapStat or "не запускался")
            .. (KL.heapDone and " · проход завершён" or "")
            .. (", записей-подписей " .. tostring(#(KL.hist or {}))))
        w("")
        w("=== ПЕРЕБОР ПАМЯТИ ===")
        w(tostring(KL.scanStat or "не запускался") .. ", автозапусков: " .. tostring(KL.scanTries or 0))
        for i = 1, math.min(#(KL.scanTop or {}), 8) do
            local c = KL.scanTop[i]
            w(("  %d) структура %s, переменная %s, секция %s, оценка %d")
                :format(i, hx(c.p), hx(c.slot), tostring(c.sec), c.score))
        end
        w("")
        w("=== ШРИФТ И ТЕКСТ (v1.5.7) ===")
        local CH2 = GRND_FONT or {}
        w("загруженный шрифт: " .. tostring(CH2.fontLoadedPath or "НЕ загружен — системный шрифт обёртки"))
        w("выбран в настройках: " .. tostring(CH2.fontPath or "не выбран")
            .. ", базовый кегль: " .. tostring(CH2.fontBase or "—"))
        do
            local sz = CH2.ladderSizes
            if type(sz) == "table" and #sz > 0 then
                local ss = {}
                for i = 1, #sz do ss[i] = tostring(sz[i]) end
                w("«лестница» кеглей: " .. tostring(#sz) .. " шт (" .. table.concat(ss, ", ") .. ")")
            else
                w("«лестница» кеглей: нет (текст рисуется растяжкой SetWindowFontScale)")
            end
        end
        w("выравнивание ников убийц: " .. tostring(KL.dbgAlign or "—")
            .. ", кегль строки: " .. tostring(KL.dbgFpx or "—") .. " px")
        -- v1.8.1: чем рисуется текст кил-листа (DX GDI либо ImGui-атлас)
        w("рендер текста: " .. (KL.dbgDx
            and ("DX GDI (как чат SA-MP): " .. tostring(KL.dbgDxFam or "?")
                .. ", кегль " .. tostring(KL.dbgDxPx or "?") .. " px, жирный")
            or "ImGui-атлас (render-библиотека недоступна)"))
        w("тень текста: " .. (KL.textShadow
            and ("мягкая (alpha " .. tostring(KL.dbgShA or 88) .. ")") or "выключена"))
        w("сетка строки: колонка ников убийц " .. tostring(KL.dbgColK or 0)
            .. " px, колонка ников жертв " .. tostring(KL.dbgColV or 0)
            .. " px, значки с " .. tostring(KL.dbgIconX or 0)
            .. " px, жертвы с " .. tostring(KL.dbgVx0 or 0)
            .. " px, высота строки " .. tostring(KL.dbgRowH or 0) .. " px")
        w("")
        w("=== ЗНАЧКИ «ЧЕМ УБИТ» ===")
        local ATS = GRND_KL_ATLAS or {}
        w("текстура атласа: " .. (ATS.tex and ("ЗАГРУЖЕНА (" .. tostring(ATS.how) .. ")")
                                  or ("НЕТ — " .. tostring(ATS.why or "ещё не пробовали"))))
        w("сборка из пикселей: " .. (ATS.runs and ("доступна, значков " .. tostring(ATS.runsCount or 0))
                                   or ("НЕТ — " .. tostring(ATS.runsWhy or "не собиралась"))))
        w("функции текстур у обёртки: "
            .. ((#(ATS.have or {}) > 0) and table.concat(ATS.have, ", ") or "НИ ОДНОЙ"))
        for i, tr in ipairs(ATS.tries or {}) do
            w(("  попытка %d: %s -> %s"):format(i, tostring(tr.name),
                tr.ok and "ок" or ("не вышло: " .. tostring(tr.err))))
        end
        if ATS.filePath then w("файл атласа: " .. tostring(ATS.filePath) .. (ATS.fileOk and " (записан)" or "")) end
        if ATS.fileWhy then w("про файл: " .. tostring(ATS.fileWhy)) end
        if ATS.ptrWhy then w("про буфер: " .. tostring(ATS.ptrWhy)) end
        w("")
        w("=== ИСТОРИЯ УБИЙСТВ ===")
        w(("записей: %d, подхват из чата: %s, системный список гасится: %s")
            :format(#(KL.hist or {}), tostring(KL.fromChat), tostring(KL.nativeOff)))
        w("в скобках у ника: " .. (KL.showId and "ID игрока" or "счёт игрока")
            .. " — значение фиксируется при появлении записи и НЕ меняется (v1.5.9)")
        for i = math.max(1, #(KL.hist or {}) - 9), #(KL.hist or {}) do
            local r = KL.hist[i]
            if r then
                w(("  [%s] %s (ID %s, счёт %s) -> %s (ID %s, счёт %s), оружие id=%s%s, источник %s")
                    :format(tostring(r.time), tostring(r.k), tostring(r.kidF), tostring(r.ks),
                            tostring(r.v), tostring(r.vidF), tostring(r.vs), tostring(r.typ),
                            r.wnameu and (" «" .. tostring(r.wnameu) .. "»") or "",
                            tostring(r.src)))
            end
        end
        w("")
        w("=== ЖУРНАЛ ЧАТА (подхват убийств) ===")
        for _, e in ipairs(KL.chatLog or {}) do
            w(("  [%s] %s | %s"):format(tostring(e.t), tostring(e.s), tostring(e.r)))
        end
        if #(KL.chatLog or {}) == 0 then w("  (сообщений не было)") end
        w("")
        w("=== ОШИБКИ РЕНДЕРА (последние) ===")
        local E = GRND_ERRLOG
        if E and E.n and E.n > 0 then
            for i = 1, math.min(E.n, 24) do
                local e = E[((E.n - i) % 24) + 1]
                if e then w(("  [%s] %s: %s"):format(tostring(e.at), tostring(e.where), tostring(e.err))) end
            end
        else
            w("  (не было)")
        end
        w("")
        w("=== ОКРУЖЕНИЕ ===")
        if type(grndTraceEnv) == "function" then
            local have, miss = grndTraceEnv()
            w("есть функции: " .. table.concat(have or {}, ", "))
            w("нет функций: " .. table.concat(miss or {}, ", "))
        end
        w(("кадров ImGui отрисовано: %s, состояние меню: %s")
            :format(tostring(T_frames and T_frames() or "?"),
                    tostring(_G.GRND_MENU and _G.GRND_MENU.open)))
        local path = grndKlDumpPath()
        local ok, f = pcall(io.open, path, "w")
        if not ok or not f then
            grndKlSay("дамп НЕ записался: " .. tostring(path))
            return false
        end
        pcall(f.write, f, "\239\187\191")          -- BOM: файл читается как UTF-8
        pcall(f.write, f, table.concat(L, "\r\n") .. "\r\n")
        pcall(f.close, f)
        grndKlSay("дамп записан: " .. path)
        grndKlSay("пришлите этот файл — в нём всё, что нужно для разбора")
        return true
    end

    -- Журнал подхвата из чата (/grndkl chat): последние строки сервера и то,
    -- как каждая распозналась. Нужен, когда структура не найдена и список
    -- работает только по сообщениям сервера.
    function grndKlChatDiag()
        local log = KL.chatLog or {}
        grndKlSay(("журнал чата: %d строк(и), подхват %s, записей в истории %d")
            :format(#log, KL.fromChat and "включён" or "ВЫКЛЮЧЕН", #(KL.hist or {})))
        if #log == 0 then
            grndKlSay("сообщений пока не было — серверные строки приходят через samp.events")
            return
        end
        for i = #log, math.max(1, #log - 9), -1 do
            local e = log[i]
            grndKlSay(("  [%s] %s | %s"):format(tostring(e.t), tostring(e.s), tostring(e.r)))
        end
        grndKlSay("если строки сервера не похожи на «Ник убил Ник» — пришли их, допишем разбор")
    end

    -- =================================================================
    --  ГАШЕНИЕ СИСТЕМНОГО КИЛЛ-ЛИСТА (v1.6.0)
    -- =================================================================
    --  Штатный способ, которым это делают во всех сниппетах MoonLoader:
    --      memory.setint8(sampGetKillInfoPtr(), 0)    -- каждый кадр
    --  Раньше скрипт звал sampGetKillInfoPtr() один раз (только ради чтения
    --  записей) и гасил список лишь тогда, когда структура уже найдена по
    --  версии/офсету/перебору. Не нашлась — системный список оставался на
    --  экране. Теперь указатель берётся из функции каждый раз, когда нужен.
    local function klApiProbe()
        if type(sampGetKillInfoPtr) ~= "function" then
            KL.apiWhy = "функции sampGetKillInfoPtr нет"
            return nil
        end
        local okp, p = pcall(sampGetKillInfoPtr)
        if not okp then
            KL.apiWhy = "вызов sampGetKillInfoPtr упал"
            return nil
        end
        p = klNorm(p)
        if not p or p < 0x10000 or p > 0xFFFF0000 or p % 4 ~= 0 then
            KL.apiWhy = (p == nil) and "вернула nil — указателя нет"
                or (("вернула %s — не похоже на указатель"):format(grndKlHx(p)))
            return nil
        end
        local en = grndMemRd32(p)
        if en == nil then
            KL.apiWhy = "по адресу " .. grndKlHx(p) .. " не читается"
            return nil
        end
        en = klNorm(en)
        if en ~= 0 and en ~= 1 then
            KL.apiWhy = ("по адресу %s первое поле = %s"):format(grndKlHx(p), tostring(en))
            return nil
        end
        KL.apiWhy, KL.apiEn = nil, en
        return p
    end

    -- =================================================================
    --  ПОИСК СТРУКТУРЫ В ПАМЯТИ ПРОЦЕССА (v1.6.0)
    -- =================================================================
    --  Перебор секций samp.dll помогает не на всех сборках: указателя на
    --  объект в образе может не быть вовсе (кастомный лаунчер, 0.3.DL,
    --  обфускация). Тогда ищем САМ ОБЪЕКТ: запись stKillEntry — это 25 байт
    --  ника убийцы (добитые нулями), сразу за ними 25 байт ника жертвы.
    --  Ники нам известны из истории убийств, поэтому подпись уникальная.
    local HEAP_MIN, HEAP_MAX = 0x10000, 0x7F000000
    local HEAP_STEP  = 256 * 1024           -- сколько читаем за один тик
    local HEAP_TOTAL = 384 * 1024 * 1024    -- предел одного прохода

    local function klKillNeedle(rec)
        if type(rec) ~= "table" then return nil end
        local k, v = tostring(rec.k or ""), tostring(rec.v or "")
        if k == "" or v == "" or #k > 25 or #v > 25 then return nil end
        if #k < 25 then k = k .. string.rep("\0", 25 - #k) end
        if #v < 25 then v = v .. string.rep("\0", 25 - #v) end
        return k .. v
    end

    local function klHeapK32()
        if KL.k32f ~= nil then return KL.k32f end
        KL.k32f = false
        if not klFfi() then return false end
        local ffi = KL.ffi
        local ok, k32 = pcall(ffi.load, "kernel32")
        if not ok or not k32 then return false end
        pcall(ffi.cdef, [[
            typedef struct { uint32_t BaseAddress, AllocationBase, AllocationProtect,
                             RegionSize, State, Protect, Type; } GRND_MBI32;
            uint32_t __stdcall VirtualQuery(const void* a, GRND_MBI32* b, uint32_t n);
        ]])
        KL.k32, KL.k32f = k32, k32
        return k32
    end

    -- Разбор одного прочитанного куска памяти: есть ли в нём наша структура
    local function klHeapScanBuffer(addr, buf)
        if type(buf) ~= "string" or #buf < 60 then return nil end
        local hist = KL.hist or {}
        local hits = 0
        for n = #hist, math.max(1, #hist - 7), -1 do
            local needle = klKillNeedle(hist[n])
            if needle then
                local pos = 1
                while hits < 400 do
                    local hit = buf:find(needle, pos, true)
                    if not hit then break end
                    hits = hits + 1
                    pos = hit + 1
                    -- запись может быть любой из пяти: пробуем каждую позицию
                    for i = 1, 5 do
                        local p = addr + (hit - 1) - 4 - (i - 1) * 59
                        if p > HEAP_MIN and p < HEAP_MAX then
                            local ok, score = klPtrOk(p)
                            if ok and (score or 0) >= 6 then return p, score end
                        end
                    end
                end
            end
        end
        return nil
    end

    -- Один шаг поиска (читает не больше HEAP_STEP байт); зовётся из тика,
    -- пока структура не найдена.
    local function klHeapTick()
        local k32 = klHeapK32()
        if not k32 then
            KL.heapStat = "ffi/kernel32 недоступны — поиск в памяти невозможен"
            KL.heapDone = true
            return nil
        end
        local ffi = KL.ffi
        local mbi  = ffi.new("GRND_MBI32[1]")
        local need = ffi.sizeof("GRND_MBI32")
        local addr = KL.heapAt or HEAP_MIN
        local read = 0
        while addr < HEAP_MAX and read < HEAP_STEP do
            local ok = pcall(k32.VirtualQuery, ffi.cast("const void*", addr), mbi, need)
            if not ok then
                addr = addr + 0x1000
            else
                local m = mbi[0]
                local base  = tonumber(m.BaseAddress) or 0
                local size  = tonumber(m.RegionSize) or 0
                local state = tonumber(m.State) or 0
                local prot  = tonumber(m.Protect) or 0
                local typ   = tonumber(m.Type) or 0
                if base == 0 or size == 0 then
                    addr = addr + 0x1000
                elseif state == 0x1000 and typ == 0x20000
                       and (prot == 0x04 or prot == 0x08 or prot == 0x40) then
                    -- приватная записываемая память (куча процесса)
                    local start = (addr > base) and addr or base
                    local avail = base + size - start
                    if avail <= 0 then
                        addr = base + size
                    else
                        local chunk = math.min(avail, HEAP_STEP - read)
                        if chunk < 64 then
                            addr = start + chunk
                        else
                            local from = start
                            if from - base >= 64 then from = from - 64 end
                            local s = KL.ffiStr(from, chunk)
                            if type(s) == "string" and #s >= 60 then
                                read = read + #s
                                local p, score = klHeapScanBuffer(from, s)
                                if p then
                                    KL.heapStat = ("нашли: %s (оценка %d)")
                                        :format(grndKlHx(p), score or 0)
                                    return p, score
                                end
                            end
                            addr = start + chunk
                        end
                    end
                else
                    addr = base + size
                end
            end
        end
        KL.heapBytes = (KL.heapBytes or 0) + read
        KL.heapAt = addr
        if addr >= HEAP_MAX or (KL.heapBytes or 0) >= HEAP_TOTAL then
            KL.heapDone = true
            KL.heapStat = ("проход завершён: пройдено %d МБ, структура не найдена")
                :format(math.floor((KL.heapBytes or 0) / 1048576))
        else
            KL.heapStat = ("сканируем память: %s (пройдено %d МБ)")
                :format(grndKlHx(addr), math.floor((KL.heapBytes or 0) / 1048576))
        end
        return nil
    end

    -- /grndkl ptr 0x1234ABCD — задать указатель вручную
    function grndKlSetPtr(hexstr)
        local h = tostring(hexstr or ""):gsub("^%s+", ""):gsub("%s+$", "")
        h = h:gsub("^0[xX]", "")
        local v = tonumber(h, 16)
        if not v then
            grndKlSay("укажи адрес в hex: /grndkl ptr 0x1234ABCD")
            return false
        end
        v = klNorm(v)
        local ok, score, why = klPtrOk(v)
        if not ok then
            grndKlSay(("адрес %s не похож на структуру: %s"):format(grndKlHx(v), tostring(why)))
            return false
        end
        KL.ptr, KL.src, KL.score = v, "вручную", score or 0
        KL.off, KL.slot = 0, nil
        KL.origEn, KL.badReads, KL.badValid = klNorm(grndMemRd32(v)), 0, 0
        grndKlSay(("указатель принят вручную: %s (оценка %d)"):format(grndKlHx(v), score or 0))
        return true
    end

    -- /grndkl heap — состояние поиска в памяти (+ ускоренный проход)
    function grndKlHeapDiag(force)
        grndKlSay("поиск структуры в памяти: " .. tostring(KL.heapStat or "не запускался"))
        grndKlSay(("позиция %s, пройдено %d МБ, записей в истории %d")
            :format(grndKlHx(KL.heapAt or HEAP_MIN),
                    math.floor((KL.heapBytes or 0) / 1048576),
                    #(KL.hist or {})))
        if not klHeapK32() then
            grndKlSay("ffi или kernel32 недоступны — перебирать память нечем")
            return
        end
        if force then
            KL.heapDone = false
            if (KL.heapBytes or 0) >= HEAP_TOTAL then KL.heapBytes = 0 end
            grndKlSay("делаю ускоренный проход (несколько МБ)...")
            for _ = 1, 24 do
                if klHeapTick() then break end
            end
            grndKlSay("состояние: " .. tostring(KL.heapStat or "—"))
        end
    end

    -- ---------- тик (крутится из основного цикла каждые wait(0)) ----------
    function grndKlTick()
        local now = os.clock()
        if not KL.cfgLoaded then KL.cfgLoaded = true; pcall(grndKlCfgLoad) end
        if not KL.termReg then
            KL.termReg = true
            if type(grndOnTerm) == "function" then
                grndOnTerm(function()
                    pcall(grndKlNativeShow, true)
                    pcall(grndKlCfgSave)
                end)
            end
        end
        if not KL.cmdReg then
            KL.cmdReg = true
            if type(sampRegisterChatCommand) == "function" then
                pcall(sampRegisterChatCommand, "grndkl", function(arg)
                    local a = tostring(arg or ""):lower()
                    a = a:gsub("^%s+", ""):gsub("%s+$", "")
                    if a == "test" then
                        pcall(grndKlSelfTest)
                    elseif a == "scan" then
                        pcall(grndKlScanNow)
                    elseif a == "tex" then
                        pcall(grndKlAtlasDiag)
                    elseif a == "chat" then
                        pcall(grndKlChatDiag)
                    elseif a == "dump" then
                        pcall(grndKlDump)
                    elseif a == "heap" then
                        pcall(grndKlHeapDiag, true)
                    elseif a:match("^ptr") then
                        pcall(grndKlSetPtr, a:sub(4))
                    else
                        pcall(grndKlDiag)
                    end
                end)
            end
        end
        -- разрешение указателя (с нарастающим интервалом, чтобы не долбить)
        if not KL.ptr then
            local wait = (KL.memFail < 10) and 0.8 or 10.0
            if (now - (KL.tickAt or 0)) >= wait then
                KL.tickAt = now
                if not grndKlResolve() then
                    KL.memFail = KL.memFail + 1
                    if KL.memFail == 10 and not KL.warned then
                        KL.warned = true
                        if type(notify.add) == "function" then
                            pcall(notify.add,
                                "Kill List: структура не найдена — работает подхват из чата, диагностика /grndkl",
                                "warn", 6)
                        end
                    end
                end
            end
        else
            -- изредка проверяем, что указатель ещё жив
            -- раз в 2 с убеждаемся, что указатель ещё жив: клиент может
            -- пересоздать CDeathWindow (реконнект/смена сервера)
            if (now - (KL.validAt or 0)) > 2.0 then
                KL.validAt = now
                -- v1.6.0: у указателей из sampGetKillInfoPtr / поиска в памяти /
                -- ручных «слота» нет — их проверяем прямо по структуре
                local okp
                if KL.slot then
                    local fresh = klNorm(grndMemRd32(KL.slot))
                    okp = (fresh == KL.ptr) and (klPtrOk(KL.ptr))
                else
                    okp = klPtrOk(KL.ptr) and true or false
                end
                if okp then
                    KL.badValid = 0
                else
                    KL.badValid = (KL.badValid or 0) + 1
                    if KL.badValid >= 2 then klForgetPtr() end
                end
            end
        end
        if KL.cfgDirty and (now - (KL.cfgSavedAt or 0)) > 0.8 then
            pcall(grndKlCfgSave)
        end
        -- ---- 1) указатель из штатной функции (как в сниппетах) ----------
        if (now - (KL.apiAt or 0)) > 0.5 then
            KL.apiAt = now
            local p = klApiProbe()
            if not p then KL.apiPtr = nil end   -- указатель протух — писать в него нельзя
            if p then
                if KL.apiPtr ~= p then
                    KL.apiPtr = p
                    pcall(grndTrace, "killlist",
                        "системный список: указатель из sampGetKillInfoPtr " .. grndKlHx(p))
                end
                if not KL.ptr then
                    local okp, score = klPtrOk(p)
                    if okp then
                        KL.ptr, KL.src, KL.score = p, "sampGetKillInfoPtr", score or 0
                        KL.off, KL.slot = 0, nil
                        KL.origEn = klNorm(grndMemRd32(p))
                        KL.memFail, KL.badReads, KL.badValid = 0, 0, 0
                        grndKlSay("структура взята из sampGetKillInfoPtr: " .. grndKlHx(p))
                    end
                end
            end
        end

        -- ---- 2) гашение системного списка КАЖДЫЙ кадр --------------------
        -- Клиент включает свой список заново при каждой новой строке, поэтому
        -- пишем 0 и в первый байт (как штатный сниппет), и в BOOL целиком.
        local target = KL.apiPtr or KL.ptr
        if KL.enabled and target then
            pcall(grndMemWr8, target, 0)
            pcall(grndMemWr32, target, 0)
            KL.nativeOff = true
            KL.nativeSrc = (KL.apiPtr == target) and "sampGetKillInfoPtr"
                                                      or tostring(KL.src or "структура")
            if (now - (KL.verifyAt or 0)) > 0.5 then
                KL.verifyAt = now
                local rb = klNorm(grndMemRd32(target))
                if rb == 0 then
                    KL.badReads = 0
                else
                    -- запись не держится (или это уже другая структура)
                    KL.badReads = (KL.badReads or 0) + 1
                    if KL.badReads >= 3 and target == KL.ptr and not KL.apiPtr then
                        klForgetPtr()
                        return
                    end
                end
            end
        elseif not KL.enabled then
            if KL.nativeOff then pcall(grndKlNativeShow, true) end
            KL.nativeOff, KL.nativeSrc = false, nil
        else
            -- чекер включён, но гасить нечем
            KL.nativeOff, KL.nativeSrc = false, nil
        end

        -- ---- 3) поиск структуры в памяти процесса (фоном) ----------------
        if KL.enabled and not KL.ptr and not KL.heapDone then
            local p, score = klHeapTick()
            if p then
                KL.ptr, KL.src, KL.score = p, "поиск в памяти", score or 0
                KL.off, KL.slot = 0, nil
                KL.origEn, KL.badReads, KL.badValid = klNorm(grndMemRd32(p)), 0, 0
                KL.heapDone = true
                grndKlSay(("структура найдена в памяти: %s (оценка %d)"):format(grndKlHx(p), score or 0))
            end
        end

        if not KL.ptr then return end
        KL.ptr = klNorm(KL.ptr) or KL.ptr

        -- снимок структуры ~5 раз в секунду
        if (now - (KL.snapAt or 0)) < 0.2 then return end
        KL.snapAt = now
        local cur = {}
        for i = 1, 5 do cur[i] = klEntryAt(KL.ptr, i) end
        local prev = KL.snap or {}
        local function key(e) return e.k .. "\1" .. e.v .. "\1" .. tostring(e.t) end
        if KL.rpcAt and (now - KL.rpcAt) < 600 and #prev > 0 then
            -- RPC-перехват работает: в память новые записи не попадают
            -- (мы их блокируем), снимок нужен только как контроль.
            KL.snap = cur
            return
        end
        if #prev == 0 then
            -- первый снимок: наполняем историю тем, что уже показано клиентом
            local order = (KL.orient == 2) and { 1, 2, 3, 4, 5 } or { 5, 4, 3, 2, 1 }
            for _, i in ipairs(order) do
                local e = cur[i]
                if e.k ~= "" and e.v ~= "" then klPush(e, "mem") end
            end
        else
            local cnt = {}
            for j = 1, #prev do
                local q = prev[j]
                if q then cnt[key(q)] = (cnt[key(q)] or 0) + 1 end
            end
            local added = {}
            for i = 1, 5 do
                local e = cur[i]
                if e.k ~= "" and e.v ~= "" then
                    local kk = key(e)
                    local c = cnt[kk] or 0
                    if c > 0 then cnt[kk] = c - 1
                    else added[#added + 1] = { i = i, e = e } end
                end
            end
            if #added == 1 then
                if added[1].i == 1 then KL.orient = 1
                elseif added[1].i == 5 then KL.orient = 2 end
            end
            -- при нескольких новых сразу порядок внутри снимка известен:
            -- при orient == 1 новые записи идут «сверху вниз» от самой свежей
            if #added > 1 and KL.orient == 1 then
                local rev = {}
                for n = #added, 1, -1 do rev[#rev + 1] = added[n] end
                added = rev
            end
            for _, a in ipairs(added) do klPush(a.e, "mem") end
        end
        KL.snap = cur
        -- обновляем счёт игроков для последних записей (и только пока
        -- чекер включён — меньше обращений к игровому API)
        if KL.enabled and (now - (KL.scoreAt or 0)) > 1.0 then
            KL.scoreAt = now
            pcall(klScoreMapRefresh)
            pcall(klScoreRefreshHist)
        end
    end
end

-- =====================================================================
--  МОДУЛЬ 12 (v1.8.5): чекер «Админы в сети».
--  Постоянный оверлей списка администрации. Обновляется командой
--  /admins (чат или диалог). Ответ своей команды из чата прячется,
--  чтобы не флудить. Свой онлайн за сегодня копится локально.
-- =====================================================================
GRND_AO = _G.GRND_AO or {}
do
    local AO = GRND_AO
    if AO.enabled == nil then AO.enabled = false end
    AO.interval  = tonumber(AO.interval) or 8
    AO.scale     = tonumber(AO.scale) or 1.0
    if AO.scale < 0.35 then AO.scale = 0.35 end
    -- v1.16: подложка списка ВЫКЛЮЧЕНА по умолчанию — надписи лежат прямо
    -- на картинке, как в родных оверлеях игры. Включается тумблером «Фон»
    -- в настройках чекера («Чекеры» -> «Админы в сети»).
    AO.bg        = (AO.bg == true)
    AO.bgAlpha   = tonumber(AO.bgAlpha) or 88
    AO.x, AO.y   = AO.x, AO.y
    AO.list      = AO.list or {}
    AO.expanded  = AO.expanded or false
    AO.anim      = AO.anim or 0
    AO.animSet   = AO.animSet or 0
    AO.moving    = false
    AO.armed     = false
    AO.armAt     = 0
    AO.cancel    = false
    AO.wantMove  = false
    AO.waiting   = false
    AO.hide      = false
    AO.ours      = false
    AO.replyTailUntil = nil
    AO.collect   = AO.collect or {}
    AO.gotHeader = false
    AO.gotLine   = false
    AO.nextAt    = 0
    AO.playDate  = AO.playDate
    AO.playSec   = tonumber(AO.playSec) or 0
    AO.afkSince  = AO.afkSince or {}
    AO.lvlCol    = AO.lvlCol or {}
    AO.cfgDirty  = AO.cfgDirty or false

    local AO_LVL_DEF = {
        { 210, 214, 220 },
        { 90, 210, 110 },
        { 80, 170, 255 },
        { 175, 110, 255 },
        { 255, 175, 60 },
        { 255, 85, 85 },
        { 255, 220, 70 },
        { 255, 90, 170 },
    }
    local function aoInitCols()
        AO.lvlCol = AO.lvlCol or {}
        for i = 1, 8 do
            local c = AO.lvlCol[i]
            if type(c) ~= "table" or not tonumber(c[1]) then
                local d = AO_LVL_DEF[i]
                AO.lvlCol[i] = { d[1], d[2], d[3] }
            end
        end
    end
    aoInitCols()

    local function aoToday()
        return os.date("%Y-%m-%d")
    end

    local function aoClamp(n, a, b)
        n = tonumber(n) or a
        if n < a then return a end
        if n > b then return b end
        return n
    end

    function grndAoCfgPath()
        if type(this_script_dir) == "function" then
            local okd, sd = pcall(this_script_dir)
            if okd and sd and tostring(sd) ~= "" then
                local pp = tostring(sd)
                while pp:sub(-1) == "/" or pp:sub(-1) == "\\" do pp = pp:sub(1, -2) end
                local sep = "\\"
                local okc, cf = pcall(function() return package.config end)
                if okc and type(cf) == "string" and #cf > 0 then sep = cf:sub(1, 1) end
                return pp .. sep .. "grnd_admins.cfg"
            end
        end
        return "grnd_admins.cfg"
    end

    function grndAoCfgSave()
        local ok, f = pcall(GRND_CONFIG.open, grndAoCfgPath(), "w")
        if not ok or not f then return false end
        local function w(k, v) f:write(k .. "=" .. tostring(v) .. "\n") end
        w("enabled", AO.enabled and 1 or 0)
        w("interval", math.floor(aoClamp(AO.interval, 3, 30)))
        w("scale", string.format("%.2f", aoClamp(AO.scale, 0.35, 2.5)))
        if AO.x then w("x", math.floor(AO.x)) end
        if AO.y then w("y", math.floor(AO.y)) end
        w("expanded", AO.expanded and 1 or 0)
        -- v1.16: подложка панели (по умолчанию ВЫКЛ) + метка оформления
        w("bg", AO.bg and 1 or 0)
        w("bgAlpha", math.floor(aoClamp(AO.bgAlpha or 88, 20, 220)))
        w("bgv", 2)
        w("playDate", tostring(AO.playDate or aoToday()))
        w("playSec", string.format("%.1f", tonumber(AO.playSec) or 0))
        aoInitCols()
        for i = 1, 8 do
            local c = AO.lvlCol[i] or AO_LVL_DEF[i]
            w("c" .. i, string.format("%d,%d,%d",
                math.floor(tonumber(c[1]) or 255),
                math.floor(tonumber(c[2]) or 255),
                math.floor(tonumber(c[3]) or 255)))
        end
        pcall(f.close, f)
        AO.cfgSavedAt = os.clock()
        AO.cfgDirty = false
        return true
    end

    function grndAoCfgLoad()
        local ok, f = pcall(GRND_CONFIG.open, grndAoCfgPath(), "r")
        AO.cfgLoaded = true
        if not ok or not f then return false end
        local bgvSeen = false      -- v1.16: конфиг уже знает про новый фон?
        for line in f:lines() do
            local k, v = tostring(line):match("^%s*([%w_]+)%s*=%s*(.-)%s*$")
            if k then
                local num = tonumber(v)
                if k == "enabled" then AO.enabled = (v == "1")
                elseif k == "bg" then AO.bg = (v == "1")
                elseif k == "bgv" and num then bgvSeen = true
                elseif k == "bgAlpha" and num then
                    AO.bgAlpha = aoClamp(math.floor(num), 20, 220)
                elseif k == "interval" and num then AO.interval = aoClamp(math.floor(num), 3, 30)
                elseif k == "scale" and num then AO.scale = aoClamp(num, 0.35, 2.5)
                elseif k == "x" and num then AO.x = num
                elseif k == "y" and num then AO.y = num
                elseif k == "expanded" then AO.expanded = (v == "1")
                elseif k == "playDate" then AO.playDate = v
                elseif k == "playSec" and num then AO.playSec = math.max(0, num)
                elseif k:match("^c%d+$") then
                    local n = tonumber(k:match("%d+"))
                    local r, g, b = tostring(v):match("(%d+)%s*,%s*(%d+)%s*,%s*(%d+)")
                    if n and n >= 1 and n <= 8 and r then
                        AO.lvlCol = AO.lvlCol or {}
                        AO.lvlCol[n] = { tonumber(r), tonumber(g), tonumber(b) }
                    end
                end
            end
        end
        pcall(f.close, f)
        aoInitCols()
        -- v1.16: подложка панели выключена по умолчанию; конфиг старой
        -- версии (без ключа bgv) один раз переводим на «без фона»,
        -- дальше значение читается из файла и хранит выбор тумблера «Фон».
        if not bgvSeen then
            AO.bg = false
            AO.cfgDirty = true
        end
        AO.bgv = 2
        if AO.playDate ~= aoToday() then
            AO.playDate = aoToday()
            AO.playSec = 0
        end
        return true
    end

    function grndAoStartMoving()
        AO.wantMove = true
        if not AO.enabled then
            AO.enabled = true
            AO.cfgDirty = true
        end
    end

    local function aoUtf(s)
        s = tostring(s or "")
        if s == "" then return s end
        if type(grndToUtf) == "function" then
            local ok, r = pcall(grndToUtf, s)
            if ok and type(r) == "string" then s = r end
        end
        return s
    end

    local function aoStrip(s)
        s = aoUtf(s)
        s = s:gsub("{%x%x%x%x%x%x%x%x}", "")
        s = s:gsub("{%x%x%x%x%x%x}", "")
        s = s:gsub("{/}", "")
        s = s:gsub("^%s+", ""):gsub("%s+$", "")
        s = s:gsub("^%d+[%.)]%s*", "")
        return s
    end

    local function aoHeadingText(s)
        return s:gsub("^[%s%=~%-]+", ""):gsub("[%s%=~%-]+$", "")
    end
    local function aoIsHeader(s)
        s=aoHeadingText(s)
        -- No substring matching: an admin-chat quote or server announcement
        -- mentioning administrators is NOT a checker response header.
        for _,empty in ipairs({"Нет администраторов в сети", "В сети нет администраторов",
            "Администраторов в сети нет", "No admins online", "No administrators online"}) do
            if s==empty or s==empty.."." then return true end
        end
        local heads={"Администраторов в сети", "Администраторы в сети", "Админы в сети", "Администрация в сети",
            "Администраторы онлайн", "Список администраторов", "Список администрации",
            "Администраторы online", "Admins online", "Administrators online", "Online admins"}
        for _,head in ipairs(heads) do
            if s==head or s==head..":" then return true end
            local tail=s:sub(#head+1)
            if s:sub(1,#head)==head and (tail:match("^%s*:?%s*%(%s*%d+%s*%)%s*:?$")
                or tail:match("^%s*:?%s*%[%s*%d+%s*%]%s*:?$")
                or tail:match("^%s*:%s*%d+%s*$")) then return true end
        end
        return false
    end
    local function aoIsOnlineReply(s)
        -- Серверы используют разные подписи для строки, которая идёт
        -- после /admins. Все варианты проверяем целиком, чтобы не скрыть
        -- обычное сообщение игрока с похожими словами.
        local prefixes = {
            "Ваш отыгранный онлайн",
            "Время администрирования за сегодня",
            "Время администрирования за день",
            "Administrative time today",
            "Played online today",
        }
        local prefix
        for _, candidate in ipairs(prefixes) do
            if s:sub(1, #candidate) == candidate then
                prefix = candidate
                break
            end
        end
        if not prefix then return false end
        local tail = s:sub(#prefix + 1)
        if tail == "" or tail == ":" then return true end
        if not tail:match("^[%s:%(]") or not tail:find("%d") then return false end
        -- Только числовая метаинформация времени, без произвольного текста.
        for _, word in ipairs({"за сегодня", "за день", "сегодня", "составляет",
            "часов", "часа", "час", "часы", "ч", "минуты", "минут", "минута", "мин", "м",
            "секунды", "секунд", "секунда", "сек", "с", "дней", "дня", "день"}) do
            tail = tail:gsub(word, "")
        end
        tail = tail:gsub("ч%.", ""):gsub("м%.", ""):gsub("с%.", "")
        return tail:gsub("[%s%p%d]", "") == ""
    end

    local function aoIsFooter(s)
        if s:match("^%-%-%-%-%-%-+$") or s:match("^======+$") then return true end
        for _,head in ipairs({"Всего администраторов", "Всего админов", "Итого администраторов",
            "Всего администрации", "Total admins", "Total administrators"}) do
            if s:sub(1,#head)==head and s:sub(#head+1):match("^%s*:%s*%d+%.?%s*$") then return true end
        end
        return false
    end
    local function aoHasAfk(s)
        if s:find("AFK", 1, true) or s:find("afk", 1, true) or s:find("Afk", 1, true) then
            return true
        end
        if s:find("АФК", 1, true) or s:find("афк", 1, true) or s:find("Афк", 1, true) then
            return true
        end
        return false
    end

    -- таймер из ответа /admins: [mm:ss] / [h:mm:ss] / N мин
    local function aoParseAfkSec(s)
        local h, m, sec = s:match("%[(%d+):(%d+):(%d+)%]")
        if h then
            return tonumber(h) * 3600 + tonumber(m) * 60 + tonumber(sec)
        end
        local mm, ss = s:match("%[(%d+):(%d+)%]")
        if mm then return tonumber(mm) * 60 + tonumber(ss) end
        local n = s:match("(%d+)%s*[Мм]ин")
        if n then return tonumber(n) * 60 end
        n = s:match("(%d+)%s*[Сс]ек")
        if n then return tonumber(n) end
        return nil
    end

    local function aoFindLevel(s)
        local n = s:match("%|%s*(%d+)")
        if n then return tonumber(n) end
        local i = s:find("ровень", 1, true)
        if not i then
            i = s:find("lvl", 1, true) or s:find("LVL", 1, true) or s:find("Lvl", 1, true)
        end
        if i then
            local before = s:sub(1, i - 1)
            n = before:match("(%d+)%s*$")
            if not n then n = before:match("(%d+)%s*%|%s*$") end
            if n then return tonumber(n) end
        end
        return nil
    end

    local function aoFindIdByNick(nick)
        if type(nick) ~= "string" or nick == "" then return nil end
        if type(sampGetPlayerIdByNickname) == "function" then
            local ok, id = pcall(sampGetPlayerIdByNickname, nick)
            if ok and type(id) == "number" and id >= 0 and id ~= 65535 then return id end
        end
        if type(sampGetMaxPlayerId) == "function"
           and type(sampIsPlayerConnected) == "function"
           and type(sampGetPlayerNickname) == "function" then
            local okm, maxid = pcall(sampGetMaxPlayerId)
            maxid = (okm and tonumber(maxid)) or 1000
            for i = 0, maxid do
                local okc, on = pcall(sampIsPlayerConnected, i)
                if okc and on then
                    local okn, n = pcall(sampGetPlayerNickname, i)
                    if okn and n == nick then return i end
                end
            end
        end
        return nil
    end

    local function aoParseLine(s)
        s=aoStrip(s)
        local nickPat="([A-Za-z][A-Za-z0-9]*_[A-Za-z0-9]+)"
        local nick,id,tail=s:match("^"..nickPat.."%s*%[(%d+)%]%s*(.*)$")
        if not nick and AO.gotHeader then
            nick,tail=s:match("^"..nickPat.."%s+(.+)$")
        end
        if not nick then return nil end
        -- Only response metadata is allowed after the nickname, not speech,
        -- punishments, reports, notifications or arbitrary text containing '| N'.
        local rest=(tail or ""):lower()
        for _,word in ipairs({"Главный администратор", "Заместитель", "Администратор",
            "главный администратор", "заместитель", "администратор",
            "Уровень", "уровень", "Уровня", "уровня", "Уровней", "уровней",
            "АФК", "Афк", "афк", "Минут", "минут", "мин", "сек", "час",
            "онлайн", "в сети", "level", "lvl", "afk", "online"}) do
            rest=rest:gsub(word, "")
        end
        if rest:gsub("[%s%p%d]", "")~="" then return nil end
        local lvl=aoFindLevel(tail or "")
        if not lvl then
            for _,label in ipairs({"Уровень", "уровень", "level", "lvl", "LVL"}) do
                local value=(tail or ""):match(label.."%s*[:=]?%s*(%d+)")
                if value then lvl=tonumber(value);break end
            end
        end
        local afk=aoHasAfk(tail or "")
        local afkSec=aoParseAfkSec(tail or "")
        if not lvl and not (AO.gotHeader and afk) then return nil end
        return {nick=nick,id=tonumber(id) or aoFindIdByNick(nick),lvl=lvl,
            afk=afk or afkSec~=nil,afkSec=afkSec}
    end

    local function aoCommit()
        if not AO.gotLine and not AO.gotHeader then
            AO.collect = {}
            return
        end
        local list = AO.collect or {}
        table.sort(list, function(a, b)
            local la, lb = tonumber(a.lvl) or -1, tonumber(b.lvl) or -1
            if la ~= lb then return la > lb end
            return tostring(a.nick or "") < tostring(b.nick or "")
        end)
        AO.list = list
        AO.parsedAt = os.clock()
        AO.collect = {}
        AO.gotHeader = false
        AO.gotLine = false
    end

    local function aoPush(e)
        if not e or not e.nick then return end
        AO.collect = AO.collect or {}
        for _, p in ipairs(AO.collect) do
            if p.nick == e.nick then
                if e.id and not p.id then p.id = e.id end
                if e.lvl and not p.lvl then p.lvl = e.lvl end
                if e.afk then p.afk = true end
                if e.afkSec then p.afkSec = e.afkSec end
                return
            end
        end
        AO.collect[#AO.collect + 1] = e
        AO.gotLine = true
        AO.lastLineAt = os.clock()
        AO.waitUntil = os.clock() + 2.2
    end

    -- Скрываем ТОЛЬКО строки ответа /admins, когда запрос отправлен фоновым чекером (AO.hide == true)
    function grndAoOnChat(color, text)
        local s=aoStrip(text)
        local now=os.clock()
        -- The server may send played-online AFTER the list footer. Retain only
        -- this narrowly matched trailer for three seconds; never mute all chat.
        if AO.replyTailUntil and now>AO.replyTailUntil then AO.replyTailUntil=nil end
        if AO.replyTailUntil and aoIsOnlineReply(s) then
            AO.replyTailUntil=nil
            return true
        end
        if not AO.waiting then return false end
        -- Если игрок сам ввёл /admins — парсим в чекер, но в чате оставляем
        if not AO.hide then
            local s = aoStrip(text)
            if s ~= "" then
                local e = aoParseLine(s)
                if e then aoPush(e) end
                if aoIsHeader(s) then AO.gotHeader = true end
                if aoIsFooter(s) then
                    AO.gotHeader = true
                    aoCommit()
                    AO.waiting = false
                end
            end
            return false
        end

        local s = aoStrip(text)
        if s == "" then return false end
        if aoIsOnlineReply(s) then
            AO.replyTailUntil = now + 3
            return true
        end

        -- 1. Строка с администратором (Nick_Name[id] | level ...)
        local e = aoParseLine(s)
        if e then
            aoPush(e)
            AO.replyTailUntil=now+3
            return true -- скрываем из чата, идёт только в чекер
        end

        -- 2. Нижняя граница / футер (Всего администраторов: N / -------)
        if aoIsFooter(s) then
            if AO.gotHeader or AO.gotLine then
                aoCommit()
                AO.replyTailUntil=now+3
                AO.waiting = false
                AO.hide = false
                AO.ours = false
                return true
            end
        end

        -- 3. Заголовок (Администраторы в сети / online)
        if aoIsHeader(s) then
            -- aoIsHeader matches the complete header, not a quoted chat fragment.
            AO.gotHeader = true
            AO.replyTailUntil=now+3
            AO.lastLineAt = os.clock()
            AO.waitUntil = os.clock() + 2.2
            return true
        end

        -- Обычные сообщения игроков/сервера не скрываются
        return false
    end
    function grndAoOnDialog(dialogId, style, title, button1, button2, text)
        if not AO.waiting then return false end
        local titleU = aoStrip(title)
        local raw = aoUtf(tostring(text or ""))
        raw = raw:gsub("\r\n", "\n"):gsub("\r", "\n")
        local head = titleU
        if head == "" then head = aoStrip(raw:sub(1, 120)) end
        if not aoIsHeader(head) then return false end
        AO.gotHeader = true
        if not raw:find("\n", 1, true) then raw = raw .. "\n" end
        for line in raw:gmatch("(.-)\n") do
            local e = aoParseLine(line)
            if e then aoPush(e) end
        end
        if not AO.gotLine then return false end
        aoCommit()
        AO.waiting = false
        local shouldHide = (AO.hide and true or false)
        if shouldHide then AO.replyTailUntil=os.clock()+3 end
        AO.hide = false
        AO.ours = false
        return shouldHide
    end

    function grndAoOnCommand(cmd)
        local c = tostring(cmd or "")
        c = c:gsub("^%s+", "")
        local low = c:lower()
        if low ~= "/admins" and not low:match("^/admins%s") then return end
        if AO.ours then
            AO.ours = false
            return
        end
        AO.replyTailUntil=nil -- manual /admins must remain visible, including its trailer
        AO.hide = false
        AO.waiting = true
        AO.waitUntil = os.clock() + 2.2
        AO.collect = {}
        AO.gotHeader = false
        AO.gotLine = false
        AO.lastLineAt = os.clock()
    end

    local function aoSampReady()
        if type(isSampAvailable) == "function" then
            local ok, r = pcall(isSampAvailable)
            if not ok or not r then return false end
        end
        return true
    end

    local function aoSpawned()
        if type(sampIsLocalPlayerSpawned) == "function" then
            local ok, r = pcall(sampIsLocalPlayerSpawned)
            if ok then return r and true or false end
        end
        return true
    end

    local function aoBusy()
        if type(grndIsTyping) == "function" then
            local ok, r = pcall(grndIsTyping)
            if ok and r then return true end
        end
        if GRND_KEYS then
            if GRND_KEYS.blocked or GRND_KEYS.dlgActive then return true end
        end
        return false
    end

    local function aoSend()
        if type(sampSendChat) ~= "function" then return false end
        AO.ours = true
        AO.hide = true
        AO.waiting = true
        AO.waitUntil = os.clock() + 2.2
        AO.collect = {}
        AO.gotHeader = false
        AO.gotLine = false
        AO.lastLineAt = os.clock()
        local ok = pcall(sampSendChat, "/admins")
        if not ok then
            AO.ours = false
            AO.waiting = false
            AO.hide = false
            return false
        end
        AO.sentAt = os.clock()
        AO.nextAt = os.clock() + aoClamp(AO.interval, 3, 30)
        return true
    end

    function grndAoTick()
        local now = os.clock()
        if not AO.cfgLoaded then
            AO.cfgLoaded = true
            pcall(grndAoCfgLoad)
        end
        if not AO.termReg then
            AO.termReg = true
            if type(grndOnTerm) == "function" then
                grndOnTerm(function() pcall(grndAoCfgSave) end)
            end
        end
        local today = aoToday()
        if AO.playDate ~= today then
            AO.playDate = today
            AO.playSec = 0
            AO.cfgDirty = true
        end
        local dt = now - (AO.tickAt or now)
        if dt < 0 then dt = 0 end
        if dt > 0.25 then dt = 0.25 end
        AO.tickAt = now
        if aoSampReady() and aoSpawned() then
            AO.playSec = (tonumber(AO.playSec) or 0) + dt
        end
        if AO.waiting then
            if now > (AO.waitUntil or 0) then
                aoCommit()
                AO.waiting = false
                AO.hide = false
                AO.ours = false
            end
        end
        -- v1.12.1: на экране входа (подключение/авторизация) сервер НЕ
        -- опрашиваем: раньше включённый чекер слал /admins ещё до входа.
        if grndUiBlocked() then
            if AO.waiting then AO.waiting, AO.hide, AO.ours = false, false, false end
            AO.replyTailUntil=nil
            AO.nextAt = now + 2.0
        elseif AO.enabled and aoSampReady() and not AO.waiting then
            if now >= (AO.nextAt or 0) and not aoBusy() then
                aoSend()
            end
        end
        if AO.cfgDirty and (now - (AO.cfgSavedAt or 0)) > 0.8 then
            pcall(grndAoCfgSave)
        end
        if now - (AO.playSavedAt or 0) > 20 then
            AO.playSavedAt = now
            pcall(grndAoCfgSave)
        end
    end
end


-- =====================================================================
--  МОДУЛЬ 13 (v1.10.1): кастомный рекон вместо системного HUD.
--  Система рисует textdraw’ы (GUN/AMMO/PING/HP/ARM/SPEED…).
--  Мы их прячем и показываем свои окна. Команды не шлём.
-- =====================================================================
GRND_RC = _G.GRND_RC or {}
do
    local RC = GRND_RC
    RC.show     = false
    RC.cursor   = false
    RC.id       = RC.id
    RC.nick     = RC.nick or ""
    RC.st       = RC.st or {}
    RC.live     = RC.live or {}
    RC.hoverUi  = false
    RC.actionsWinOpen = false
    RC.actSubPopup = nil
    RC.actionsWinFocus = false
    RC.interactHover  = false
    RC.actDragging    = false
    RC.savedActionsWinX = RC.savedActionsWinX or nil
    RC.savedActionsWinY = RC.savedActionsWinY or nil
    RC.hoverTarget    = nil
    RC.actTargetId    = nil
    RC.actTargetNick  = nil
    RC.actTargetPed   = nil
    RC.punDragging    = false
    RC.punishPosX     = nil
    RC.punishPosY     = nil
    RC.barPage  = tonumber(RC.barPage) or 1
    RC.actPage  = tonumber(RC.actPage) or 1
    RC.colP     = (RC.colP ~= false)
    RC.colS     = (RC.colS ~= false)
    RC.prompt   = nil
    RC.quick    = false
    RC.tdHide   = {}
    RC.tdOrig   = {}
    RC.tdKind   = {}
    RC.tdSeenAt = 0
    RC.rmbHeld  = false
    RC.specWasActive = false
    RC.lastTargetId = nil
    RC.reconTdActive = false
    RC.reconSeen = false
    RC.reconHidden = false
    RC.QUICK    = RC.QUICK or {
        "Приветствую, слежу за вами.",
        "Прекратите нарушение.",
        "Проследуйте в AZ.",
        "Сейчас разберусь, ожидайте.",
    }

    local function rcUtf(s)
        s = tostring(s or "")
        if s == "" then return s end
        if type(grndToUtf) == "function" then
            local ok, r = pcall(grndToUtf, s)
            if ok and type(r) == "string" then s = r end
        end
        return s
    end
    local function rcStrip(s)
        s = rcUtf(s)
        s = s:gsub("{%x%x%x%x%x%x%x%x}", "")
        s = s:gsub("{%x%x%x%x%x%x}", "")
        s = s:gsub("~%w~", "")
        s = s:gsub("<[^>]+>", "")
        s = s:gsub("[%c\r]", " ")
        s = s:gsub("^%s+", ""):gsub("%s+$", "")
        return s
    end

    local function rcSetLive(k, v)
        if v == nil then return end
        v = tostring(v):gsub("^%s+", ""):gsub("%s+$", "")
        if v == "" then return end
        RC.live = RC.live or {}
        RC.live[k] = v
    end

    local function rcAfterColon(s)
        local v = tostring(s or ""):match(":%s*(.*)$")
        if not v then return nil end
        v = v:gsub("^%s+", ""):gsub("%s+$", "")
        if v == "" then return nil end
        return v
    end

    -- подписи системного рекона с скрина
    -- только строки системного рекона вида «GUN: …», иначе ловим чужой HUD
    local RC_LABEL = {
        ammo = { "AMMO" },
        weap = { "GUN" },
        ping = { "PING" },
        afk  = { "AFK" },
        speed = { "SPEED" },
        frac = { "FRACTION", "Fraction" },
        arm  = { "ARM" },
        hp   = { "HP" },
    }
    local function rcKind(s)
        if type(s) ~= "string" or s == "" then return nil end
        local u = s:gsub("^%s+", "")
        local head = u:match("^([%a]+)%s*:")
        if not head then
            local idn = u:match("^%[%s*(%d+)%s*%]%s*$")
            if idn then return "id", idn end
            return nil
        end
        local up = head:upper()
        if up == "AMMO" then return "ammo" end
        if up == "GUN" then return "weap" end
        if up == "PING" then return "ping" end
        if up == "AFK" then return "afk" end
        if up == "SPEED" then return "speed" end
        if up == "FRACTION" then return "frac" end
        if up == "ARM" then return "arm" end
        if up == "HP" then return "hp" end
        return nil
    end
    local function rcKindCount()
        -- На этом сервере рекон — ОДИН global TextDraw (id 2048),
        -- внутри которого склеены все поля: имя, GUN, AMMO, PING...
        -- Поэтому считать только RC.tdKind нельзя: у одного TD будет один
        -- id, хотя полезных полей внутри него восемь.
        local n, seen = 0, {}
        local liveKeys = { "weap", "ammo", "ping", "afk", "hp", "arm", "frac", "speed" }
        for i = 1, #liveKeys do
            local k = liveKeys[i]
            if RC.live and RC.live[k] ~= nil and tostring(RC.live[k]) ~= "" then
                seen[k] = true
                n = n + 1
            end
        end
        for _, k in pairs(RC.tdKind or {}) do
            if k ~= "id" and k ~= "name" and k ~= "recon" and not seen[k] then
                seen[k] = true
                n = n + 1
            end
        end
        return n
    end
    local function rcConfirmed()
        return rcKindCount() >= 3
    end

    local function rcApplyKind(kind, s, extra)
        if kind == "id" then
            local idn = extra or s:match("%[%s*(%d+)%s*%]")
            if idn then
                RC.id = tonumber(idn)
                rcSetLive("id", idn)
            end
            return
        end
        local v = rcAfterColon(s) or extra
        if kind == "weap" then rcSetLive("weap", v)
        elseif kind == "ammo" then rcSetLive("ammo", v)
        elseif kind == "ping" then rcSetLive("ping", v)
        elseif kind == "afk" then rcSetLive("afk", v)
        elseif kind == "hp" then rcSetLive("hp", v)
        elseif kind == "arm" then rcSetLive("arm", v)
        elseif kind == "frac" then rcSetLive("frac", v)
        elseif kind == "speed" then rcSetLive("speed", v)
        end
    end

    -- Важно: на сервере пользователя рекон приходит не восемью TD, а одной
    -- строкой в global TextDraw #2048:
    --   Nick[ 234 ]GUN: ...AMMO: ...PING: ...AFK: ...HP: ...ARM: ...
    -- Разбираем её по позициям меток, не полагаясь на переводы строк.
    local RC_COMPOUND_FIELDS = {
        { kind = "weap", label = "GUN:" },
        { kind = "ammo", label = "AMMO:" },
        { kind = "ping", label = "PING:" },
        { kind = "afk",  label = "AFK:" },
        { kind = "hp",   label = "HP:" },
        { kind = "arm",  label = "ARM:" },
        { kind = "frac", label = "FRACTION:" },
        { kind = "speed", label = "SPEED:" },
    }
    local function rcParseCompound(text)
        text = tostring(text or "")
        if text == "" then return false end
        local upper = text:upper()
        local hits = {}
        for i = 1, #RC_COMPOUND_FIELDS do
            local def = RC_COMPOUND_FIELDS[i]
            local pos = upper:find(def.label, 1, true)
            if pos then
                hits[#hits + 1] = { pos = pos, kind = def.kind, label = def.label }
            end
        end
        if #hits == 0 then return false end
        table.sort(hits, function(a, b) return a.pos < b.pos end)

        -- Всё до первой метки — имя и ID цели.
        local prefix = text:sub(1, hits[1].pos - 1)
        local nick, idn = prefix:match("^%s*(.-)%[%s*(%d+)%s*%]%s*$")
        if nick and nick ~= "" then
            RC.nick = nick
            RC.id = tonumber(idn)
            rcSetLive("id", idn)
        end

        for i = 1, #hits do
            local h = hits[i]
            local from = h.pos + #h.label
            local to = (hits[i + 1] and hits[i + 1].pos or (#text + 1)) - 1
            local value = text:sub(from, to)
            value = value:gsub("^%s+", ""):gsub("%s+$", "")
            rcApplyKind(h.kind, "", value)
        end
        return true
    end

    local function rcLooksName(s)
        if type(s) ~= "string" then return false end
        if #s < 3 or #s > 32 then return false end
        if s:find(":", 1, true) then return false end
        if s:match("%[%s*%d+%s*%]") then return false end
        if s:find("GUN", 1, true) or s:find("HP", 1, true) or s:find("ARM", 1, true) then return false end
        if s:find("PING", 1, true) or s:find("SPEED", 1, true) then return false end
        -- ник_ник или Имя Фамилия
        if s:find("_", 1, true) then return true end
        if s:find(" ", 1, true) and not s:find("%d") then return true end
        return false
    end

    local function rcParseText(text)
        text = rcStrip(text)
        if text == "" then return false end
        -- Сначала пробуем формат одного склеенного TextDraw (#2048).
        if rcParseCompound(text) then return true end

        local hit = false
        text = text:gsub("\r\n", "\n"):gsub("\r", "\n")
        local function one(line)
            local kind, extra = rcKind(line)
            if kind then
                rcApplyKind(kind, line, extra)
                return true
            end
            return false
        end
        if text:find("\n", 1, true) then
            for line in (text .. "\n"):gmatch("(.-)\n") do
                if one(line) then hit = true end
            end
        else
            hit = one(text)
        end
        if (not hit) and rcLooksName(text) then
            RC.nick = text
            hit = true
        end
        return hit
    end

    local function rcTdExists(id)
        if type(sampTextdrawIsExists) ~= "function" then return nil end
        local ok, r = pcall(sampTextdrawIsExists, id)
        if ok then return r and true or false end
        return nil
    end
    local function rcTdString(id)
        if type(sampTextdrawGetString) ~= "function" then return "" end
        local ok, s = pcall(sampTextdrawGetString, id)
        if ok and type(s) == "string" then return s end
        return ""
    end
    local function rcHideTd(id)
        id = tonumber(id)
        if not id then return end
        RC.tdHide[id] = true
        if RC.tdOrig[id] == nil and type(sampTextdrawGetPos) == "function" then
            local ok, x, y = pcall(sampTextdrawGetPos, id)
            if ok and type(x) == "number" then
                RC.tdOrig[id] = { x = x, y = y }
            else
                RC.tdOrig[id] = false
            end
        elseif RC.tdOrig[id] == nil then
            RC.tdOrig[id] = false
        end
        if type(sampTextdrawSetPos) == "function" then
            pcall(sampTextdrawSetPos, id, -5000.0, -5000.0)
        end
    end
    local function rcRestoreTds()
        if type(sampTextdrawSetPos) == "function" then
            for id, pos in pairs(RC.tdOrig) do
                if type(pos) == "table" and pos.x then
                    pcall(sampTextdrawSetPos, id, pos.x, pos.y)
                end
            end
        end
        RC.tdHide = {}
        RC.tdOrig = {}
        RC.tdKind = {}; RC.tdSweep = nil
    end

    -- вызывается из samp.events: true = спрятать системный TD
    function grndRcOnTextDraw(id, text)
        id = tonumber(id)
        text = tostring(text or "")
        if not id then return false end
        local stripped = rcStrip(text)
        -- v1.12: запасной канал статистики. Сервер может ответить на /stats
        -- не диалогом, а текстдравом — этот путь раньше был написан, но
        -- нигде не вызывался (мёртвая ветка). Разбор включается сам: внутри
        -- grndStatsOnTextDraw есть проверка «ждём ли ответ» (ST.waiting).
        if stripped ~= "" and type(_G.grndStatsOnTextDraw) == "function" then
            pcall(_G.grndStatsOnTextDraw, stripped)
        end
        local kind, extra = rcKind(stripped)
        local compound = rcParseCompound(stripped)
        RC.tdKind = RC.tdKind or {}
        if compound then
            -- Один TD содержит сразу весь рекон.
            RC.tdKind[id] = "recon"
            kind = "recon"
        elseif kind then
            RC.tdKind[id] = kind
            rcApplyKind(kind, stripped, extra)
        elseif RC.show and rcLooksName(stripped) then
            RC.nick = stripped
            RC.tdKind[id] = "name"
            kind = "name"
        else
            return false
        end
        if not rcConfirmed() then return false end
        RC.reconHidden = false
        RC.reconMissingAt = nil
        RC.reconTdActive = true
        RC.reconSeen = true
        RC.tdSeenAt = os.clock()
        RC.tdGoneSince = nil
        RC.show = true
        for hid, _ in pairs(RC.tdKind) do
            rcHideTd(hid)
        end
        return true
    end

    local function grndRcForceClose(reason)
        RC.show = false
        RC.cursor = false
        RC.rmbHeld = false
        RC.prompt = nil
        RC.quick = false
        RC.id = nil
        RC.nick = ""
        RC.live = {}
        RC.actionsWinOpen = false
        RC.actSubPopup = nil
        RC.actionsWinFocus = false
        RC.interactHover = false
        RC.actDragging = false
        RC.hoverTarget = nil
        RC.actTargetId = nil
        RC.actTargetNick = nil
        RC.actTargetPed = nil
        RC.punDragging = false
        RC.reconSeen = false
        RC.reconTdActive = false
        RC.reconHidden = true
        RC.reconMissingAt = nil
        RC.closedAt = os.clock()
        RC.lastCursor = false
        RC.closeHandled = true
        RC.tdGoneSince = nil
        if RC.tdKind then RC.tdKind = {}; RC.tdSweep = nil end

        if type(_G.grndPlainCursorForceOff) == "function" then
            pcall(_G.grndPlainCursorForceOff)
        end
        if type(_G.grndNativeCursorShow) == "function" then
            pcall(_G.grndNativeCursorShow, false)
        end
        if type(rcRestoreTds) == "function" then
            pcall(rcRestoreTds)
        end

        local GS = _G.GRND_SPEC
        if GS then
            GS.manualExit = true
            GS.active = false
            GS.id = nil
            GS.nick = ""
            GS.confirmT = 0
        end

        local SA = _G.GRND_SPEC_AUTOREF
        if SA then
            SA.manualExit = true
            SA.lastTargetId = nil
            SA.lostSince = nil
            SA.refreshCount = 0
        end

        if type(_G.grndSpecNativeReleaseCam) == "function" then
            pcall(_G.grndSpecNativeReleaseCam)
        end
    end
    _G.grndRcForceClose = grndRcForceClose

    function grndRcOnTextDrawHide(id)
        id = tonumber(id)
        if not id then return end
        if id == 2048 or (RC.tdKind and RC.tdKind[id]) then
            local GS = _G.GRND_SPEC
            local tid = tonumber(GS and GS.id) or tonumber(RC.id)
                or (_G.GRND_SPEC_AUTOREF and tonumber(_G.GRND_SPEC_AUTOREF.lastTargetId))
            local conn = nil
            if type(sampIsPlayerConnected) == "function" and tid then
                local okc, cc = pcall(sampIsPlayerConnected, tid)
                if okc then conn = cc and true or false end
            end
            if conn == false then
                grndRcForceClose("quit")
                return
            end
            local manualExit = (GS and GS.manualExit)
                or (_G.GRND_SPEC_AUTOREF and _G.GRND_SPEC_AUTOREF.manualExit)
            if not manualExit and conn ~= false and tid then
                RC.reconTdActive = false
                RC.tdGoneSince = RC.tdGoneSince or os.clock()
                if RC.tdKind then RC.tdKind[id] = nil end
                return
            end
            grndRcForceClose("hide")
            if RC.tdKind then RC.tdKind[id] = nil end
            RC.tdGoneAt = os.clock()
        end
    end

    local function rcIsSpectating()
        for _, name in ipairs({ "sampIsPlayerSpectating", "isPlayerSpectating" }) do
            local f = _G[name]
            if type(f) == "function" then
                local ok, r = pcall(f)
                if ok and r == true then return true end
            end
        end
        if _G.GRND_SPEC and GRND_SPEC.active then return true end
        -- v1.11.0: нативный spectate по памяти (модуль 13b)
        local sn = _G.grndSpecNative
        if sn and sn.ok then
            local ok, on = pcall(sn.spectState, sn)
            if ok and on then return true end
            local ok2, on2 = pcall(sn.spectScan, sn)
            if ok2 and on2 then return true end
        end
        return false
    end

    -- v1.19.57: перебор текстдрауов идёт ПОРЦИЯМИ. Раньше один заход
    -- перебирал все 2305 id и на каждый делал два вызова SAMPFUNCS — в слежке
    -- это давало заметный рывок. Теперь за вызов 256 id (полный круг ~1 с),
    -- а решения принимаются в конце круга, как и раньше.
    local RC_TD_CHUNK = 256
    local function rcScanTextdraws()
        if type(sampTextdrawIsExists) ~= "function" then return 0 end
        -- После onHideTextDraw старый global TD может ещё оставаться в
        -- локальном кеше API. Не принимаем его за новую слежку, пока сервер
        -- не пришлёт новый Show/SetString.
        if RC.reconHidden then
            RC.reconTdActive = false
            RC.tdSweep = nil
            return 0
        end
        local sweep = RC.tdSweep
        if not sweep then
            sweep = { at = 0, hits = 0, names = {} }
            RC.tdSweep = sweep
            RC.tdKind = {}
        end
        local names, hits = sweep.names, sweep.hits
        local idFrom = sweep.at
        local idTo = math.min(2304, idFrom + RC_TD_CHUNK - 1)
        for id = idFrom, idTo do
            local ex = rcTdExists(id)
            if ex then
                local raw = rcTdString(id)
                local s = rcStrip(raw)
                if s ~= "" then
                    local kind, extra = rcKind(s)
                    local compound = rcParseCompound(s)
                    if compound then
                        RC.tdKind[id] = "recon"
                        hits = hits + 1
                    elseif kind then
                        RC.tdKind[id] = kind
                        rcApplyKind(kind, s, extra)
                        hits = hits + 1
                    elseif rcLooksName(s) then
                        names[#names + 1] = { id = id, s = s }
                    end
                end
            end
        end
        sweep.hits, sweep.at = hits, idTo + 1
        if sweep.at <= 2304 then
            -- порция пройдена, круг ещё нет: итоги подводим в конце круга
            return hits
        end
        RC.tdSweep = nil
        if hits > 0 then
            RC.reconTdActive = true
            RC.reconSeen = true
            RC.reconMissingAt = nil
            RC.tdGoneSince = nil
        elseif RC.show then
            RC.reconMissingAt = RC.reconMissingAt or os.clock()
            if os.clock() - RC.reconMissingAt > 0.75 then
                local manualExit = (_G.GRND_SPEC and _G.GRND_SPEC.manualExit)
                    or (_G.GRND_SPEC_AUTOREF and _G.GRND_SPEC_AUTOREF.manualExit)
                local tid = tonumber(RC.id) or (_G.GRND_SPEC and tonumber(_G.GRND_SPEC.id))
                    or (_G.GRND_SPEC_AUTOREF and tonumber(_G.GRND_SPEC_AUTOREF.lastTargetId))
                local conn = nil
                if type(sampIsPlayerConnected) == "function" and tid then
                    local okc, cc = pcall(sampIsPlayerConnected, tid)
                    if okc then conn = cc and true or false end
                end
                if conn == false then
                    grndRcForceClose("quit")
                elseif (rcIsSpectating() or not manualExit) and conn ~= false and tid then
                    RC.reconTdActive = false
                    RC.tdGoneSince = RC.tdGoneSince or os.clock()
                else
                    grndRcForceClose("scan_missing")
                end
            end
        else
            RC.reconTdActive = false
        end
        if hits == 0 then
            return 0
        end
        if not rcConfirmed() then
            return hits
        end
        if #names > 0 then
            RC.nick = names[1].s
            RC.tdKind[names[1].id] = "name"
        end
        for hid, _ in pairs(RC.tdKind) do
            rcHideTd(hid)
        end
        RC.tdSeenAt = os.clock()
        return hits
    end

    local function rcRehide()
        if type(sampTextdrawSetPos) ~= "function" then return end
        for id, _ in pairs(RC.tdHide) do
            pcall(sampTextdrawSetPos, id, -5000.0, -5000.0)
        end
    end

    -- заглушки, чтобы старые вызовы не падали
    function grndRcSend(cmd) return false end
    function grndRcCmd() return false end
    function grndRcRefresh() end
    function grndRcExit()
        RC.show = false
        RC.prompt = nil
        RC.quick = false
        RC.id = nil
        RC.nick = ""
        RC.live = {}
        RC.reconSeen = false
        RC.reconTdActive = false
        RC.reconHidden = true
        pcall(rcRestoreTds)
    end
    function grndRcOnChat() return false end
    function grndRcOnDialog() return false end
    function grndRcOnCommand() end
    function grndRcActive()
        return RC.show and true or false
    end

    -- === БЛОКИРОВКА СТАНДАРТНОГО РЕКОНА SA:MP ===
    -- v1.11.0: реальное гашение нативного box делает МОДУЛЬ 13b
    -- (grndSpecNative: калибровка и обнуление структуры spectate).
    -- Старая запись в «ped+0x486» удалена — это было угаданное значение
    -- и оно могло ломать память. Здесь остаётся только блокировка
    -- ручного ввода /spectate в чат.
    local function disableVanillaSpectate()
        -- Блокируем ввод команды /spectate в чат, если наш режим активен
        if GRND_KEYS.enterPressed and RC.show then
            -- Пытаемся получить текст из чата (если есть функция)
            local inputText = ""
            if type(getChatInput) == "function" then
                inputText = getChatInput() or ""
            elseif type(sampGetChatInput) == "function" then
                inputText = sampGetChatInput() or ""
            end
            
            if string.find(string.lower(inputText), "^/spectate") then
                -- Очищаем чат, если нашли команду спектата
                if type(clearChatInput) == "function" then
                    clearChatInput()
                elseif type(sampClearChatInput) == "function" then
                    sampClearChatInput()
                end
                GRND_KEYS.enterPressed = false
                return true -- Заблокировано
            end
        end
        return false
    end

    function grndRcTick()
        local now = os.clock()

        -- v1.11.0: МОДУЛЬ 13b — перехват нативного спектейта SAMP
        -- (гашение стандартного box + наша камера). До всего остального,
        -- чтобы окно ниже открывалось уже с живыми данными.
        if type(grndSpecNativeTick) == "function" then
            local okCamera,errCamera=pcall(grndSpecNativeTick)
            if not okCamera then grndCamReportError('follow',errCamera) end
        end

        -- Блокируем ванильный рекон перед всем остальным, если наш UI открыт
        if RC.show then
            disableVanillaSpectate()
        end
        
        local spec = rcIsSpectating() or grndSpecInSpec()

        -- v1.11.11: ПКМ — ЕДИНЫЙ переключатель курсора в слежке.
        -- Источники правды о нажатии (по убыванию надёжности):
        --   1) WinAPI GetAsyncKeyState через ffi — работает в любой сборке;
        --   2) SAMPFUNCS getMouseState / isMouseButtonDown;
        --   3) MoonLoader-опрос VK_RBUTTON (isKeyDown/wasKeyPressed);
        --   4) WM-метки (rmbWmTap/rclicked), если сообщения доходят.
        -- Одно физическое нажатие = ровно одно переключение: срабатываем по
        -- фронту «зажата» и ставим защёлку до полного отпускания кнопки.
        if RC.show then
            local down, src = false, nil
            local w = grndRmbHeldWin()
            if w ~= nil then
                down = w and true or false
                if down then src = "win" end
            else
                if type(isKeyDown) == "function" then
                    local okD, d = pcall(isKeyDown, 0x02) -- VK_RBUTTON
                    if okD and d then down = true; src = src or "vk" end
                end
                if type(getMouseState) == "function" then
                    local okM, ms = pcall(getMouseState)
                    if okM and type(ms) == "number" and math.floor(ms / 2) % 2 == 1 then
                        down = true; src = src or "gms"
                    end
                end
                if type(isMouseButtonDown) == "function" then
                    local okB, d2 = pcall(isMouseButtonDown, 2)
                    if okB and d2 then down = true; src = src or "mbd" end
                end
                if GRND_MOUSE and GRND_MOUSE.rdown then down = true; src = src or "wm" end
            end

            -- v1.11.18: лапки-защёлки опрашиваются КАЖДЫЙ кадр (даже когда
            -- не нужны) — иначе «хвост» (бит 0 GetAsyncKeyState: «была
            -- нажата с прошлого опроса») остаётся и на следующем кадре
            -- даёт ложное нажатие → двойное переключение курсора.
            local wkTap = false
            for _, fn in ipairs({ wasKeyPressed, isKeyJustPressed }) do
                if type(fn) == "function" then
                    local okP, p = pcall(fn, 0x02) -- VK_RBUTTON
                    if okP and p then wkTap = true end
                end
            end

            local tapped = false
            if down and not (RC.rmbHeld or false) then tapped = true end -- фронт
            if RC.rmbWmTap then tapped = true end
            -- rclicked читаем ПО ФРОНТУ и не гасим чужой флаг (он нужен UI):
            -- застрявшее значение не даст отложенное ложное переключение
            local rcNow = (GRND_MOUSE and GRND_MOUSE.rclicked) and true or false
            if rcNow and not (RC.rmbRcPrev or false) then tapped = true end
            RC.rmbRcPrev = rcNow
            if wkTap then tapped = true end
            RC.rmbWmTap = false
            if tapped then RC.rmbSrc = src or "tap" end

            -- взвод по сигналам отпускания — сразу (они достоверны)
            if RC.rmbWmUp then RC.rmbArmed = true end
            if (RC.rmbHeld or false) and not down then RC.rmbArmed = true end
            RC.rmbWmUp = false
            if RC.rmbWmHeld and now - (RC.rmbWmHeldAt or now) > 3 then
                RC.rmbWmHeld = false          -- зависший down без отпускания
            end
            -- страховка ТОЛЬКО для сборок без WM
            local sinceLast = now - (RC.rmbLastToggleAt or -99)
            if not RC.rmbWmSeen and sinceLast > 0.8 then
                RC.rmbArmed = true
            end
            -- v1.11.18: антидребезг — второе переключение НЕ РАНЬШЕ 0.25 с
            -- после первого. Отсроченный «хвост» нажатия (бит 0
            -- GetAsyncKeyState) приходит через ~16 мс и конструктивно не
            -- может устроить мигание «включился на миллисекунду и пропал».
            if tapped and (RC.rmbArmed ~= false) and sinceLast > 0.25 then
                RC.cursor = not RC.cursor
                RC.rmbLastToggleAt = now
                RC.rmbArmed = false
                RC.rmbSrc = src or "tap"
                if RC.cursor and _G.GRND_IM and _G.GRND_IM.Process ~= nil then
                    pcall(function() _G.GRND_IM.Process = true end)
                end
                -- v1.11.15: видимый курсор — не только флагом ImGui, но и
                -- нативным showCursor (на части сборок im.ShowCursor мёртв)
                if type(_G.grndNativeCursorShow) == "function" then
                    pcall(_G.grndNativeCursorShow, RC.cursor)
                end
            end
            RC.rmbHeld = down
        else
            RC.rmbHeld = false
            RC.rmbWmTap = false
            RC.rmbWmUp = false
            RC.rmbArmed = true
        end

        -- v1.19.57: скан идёт порциями по 256 id; вызываем чаще (0.12 с), но
        -- каждая порция дешёвая — полный круг складывается за ~1 с, как раньше,
        -- зато без рывка на кадр
        if (now - (RC.scanAt or 0)) > 0.12 then
            RC.scanAt = now
            pcall(rcScanTextdraws)
        end
        local targetId = (_G.GRND_SPEC and GRND_SPEC.active)
            and tonumber(GRND_SPEC.id) or nil
        local specRising = spec and not RC.specWasActive
        if specRising or (targetId and tonumber(RC.lastTargetId) ~= targetId) then
            -- Новый сеанс слежки: старый hidden относится только к прошлому
            -- сеансу. При этом stale spec после HideTextDraw не вызывает
            -- rising edge, потому что specWasActive сохраняется до фактического
            -- выхода из режима.
            if not RC.show then
                RC.reconHidden = false
                RC.reconSeen = false
                RC.reconTdActive = false
                RC.reconMissingAt = nil
            end
        end
        RC.specWasActive = spec
        if targetId then RC.lastTargetId = targetId end
        if targetId and RC.id and tonumber(RC.id) ~= targetId then
            -- Не переносим сведения предыдущей цели в новую карточку.
            RC.live = {}
            RC.nick = ""
            RC.tdKind = {}; RC.tdSweep = nil
            RC.tdHide = {}
            RC.tdOrig = {}
            RC.tdSeenAt = 0
        end
        if targetId then RC.id = targetId end

        -- Быстрая проверка: если цель отключилась от сервера во время рекона — закрываем всё мгновенно
        local curTid = tonumber(RC.id)
            or (_G.GRND_SPEC and tonumber(_G.GRND_SPEC.id))
            or (_G.GRND_SPEC_AUTOREF and tonumber(_G.GRND_SPEC_AUTOREF.lastTargetId))
        if curTid and type(sampIsPlayerConnected) == "function" then
            local okc, cc = pcall(sampIsPlayerConnected, curTid)
            if okc and not cc then
                grndRcForceClose("quit")
                if type(grndSpecForget) == "function" then
                    pcall(grndSpecForget, "quit")
                end
                return
            end
        end

        local want
        local manualExit = (_G.GRND_SPEC and _G.GRND_SPEC.manualExit)
            or (_G.GRND_SPEC_AUTOREF and _G.GRND_SPEC_AUTOREF.manualExit)
        if RC.reconHidden and manualExit then
            want = false
        elseif RC.reconSeen then
            if RC.reconTdActive then
                want = true
            else
                local specHold = spec or not manualExit
                local tidHold = (_G.GRND_SPEC
                    and tonumber(_G.GRND_SPEC.id)) or tonumber(RC.id)
                    or (_G.GRND_SPEC_AUTOREF and tonumber(_G.GRND_SPEC_AUTOREF.lastTargetId))
                local isConn = true
                if tidHold and type(sampIsPlayerConnected) == "function" then
                    local okcH, ccH = pcall(sampIsPlayerConnected, tidHold)
                    if okcH and not ccH then isConn = false end
                end
                if not isConn then
                    want = false
                else
                    local goneH = now - (RC.tdGoneSince or now)
                    want = specHold or goneH < 30.0
                end
            end
        else
            want = (spec or (RC.reconTdActive and rcConfirmed()) or not manualExit)
            if want then
                local tidHold = (_G.GRND_SPEC and tonumber(_G.GRND_SPEC.id)) or tonumber(RC.id)
                if tidHold and type(sampIsPlayerConnected) == "function" then
                    local okcH, ccH = pcall(sampIsPlayerConnected, tidHold)
                    if okcH and not ccH then want = false end
                end
            end
        end
        -- v1.11.77: ОКНО СТАТИСТИКИ (/stats) ВНЕ СЛЕЖКИ.
        -- Логика выше рассчитана на рекон во время слежки и «удерживает»
        -- окно, пока игрок сам не выйдет из слежки (not manualExit). Для
        -- окна, открытого только ради /stats, это не подходит: оно должно
        -- жить GRND_STATS_VIEW_KEEP секунд и закрываться само.
        if spec or RC.reconTdActive then
            RC.statsOnly = nil                  -- началась слежка — обычные правила
        end
        if RC.statsOnly and not spec and not RC.reconTdActive then
            if type(_G.grndStatsViewFresh) == "function"
                and _G.grndStatsViewFresh(now) then
                want = true                     -- окно статистики открыто
            else
                RC.statsView = nil
                want = false                    -- время вышло — закрываем
            end
        end
        if want then
            if not RC.show then
                RC.show = true
                -- v1.11.17: если рекон «моргнул» (закрыт < 0.4 с назад —
                -- серверный TD мигнул), состояние курсора СОХРАНЯЕМ, чтобы
                -- не было «включился на миллисекунду и пропал». Настоящий
                -- вход в слежку (пауза > 0.4 с) — курсор всегда выключен.
                if now - (RC.closedAt or -99) > 0.4 then
                    RC.cursor = false
                    if type(_G.grndPlainCursorForceOff) == "function" then
                        pcall(_G.grndPlainCursorForceOff)
                    end
                else
                    RC.cursor = RC.lastCursor and true or false
                    if type(_G.grndNativeCursorShow) == "function" then
                        pcall(_G.grndNativeCursorShow, RC.cursor)
                    end
                end
                RC.prompt = nil
                RC.quick = false
            end
            pcall(rcRehide)
            if not RC.id and _G.GRND_SPEC and GRND_SPEC.id then
                RC.id = tonumber(GRND_SPEC.id)
                if (RC.nick == "" or not RC.nick) and GRND_SPEC.nick then
                    RC.nick = tostring(GRND_SPEC.nick)
                end
            end
        elseif RC.show then
            RC.show = false
            -- v1.11.17: запоминаем состояние курсора; нативный курсор
            -- вернётся с задержкой (см. ниже closeHandled) — если рекон
            -- «моргнёт» и сразу откроется, курсор даже не дёрнется
            RC.closedAt = now
            RC.lastCursor = RC.cursor and true or false
            RC.closeHandled = false
            RC.cursor = false
            RC.prompt = nil
            RC.quick = false
            RC.id = nil
            RC.nick = ""
            RC.live = {}
            RC.actionsWinOpen = false
            RC.actSubPopup = nil
            RC.interactHover = false
            RC.actDragging = false
            RC.hoverTarget = nil
            RC.actTargetId = nil
            RC.actTargetNick = nil
            RC.actTargetPed = nil
            RC.punDragging = false
            RC.reconSeen = false
            RC.reconTdActive = false
            RC.reconHidden = true
            RC.reconMissingAt = nil
            pcall(rcRestoreTds)
        end
        -- v1.11.17: нативный курсор возвращается ТОЛЬКО когда рекон закрыт
        -- дольше 0.4 с (настоящий выход). Если за это время слежка
        -- «моргнула» и открылась заново — курсор вообще не трогали, и
        -- миллисекундных миганий «включился и пропал» не бывает.
        if not RC.show and RC.closeHandled == false and RC.closedAt then
            if now - RC.closedAt > 0.4 then
                RC.closeHandled = true
                if type(_G.grndNativeCursorShow) == "function"
                    and type(_G.grndPlainCursorIsOn) == "function" then
                    pcall(_G.grndNativeCursorShow, _G.grndPlainCursorIsOn())
                end
            end
        end
        -- Q/E страницы бара больше не требуются (панель содержит только Наказания)
    end
end

GRND_TRACE = {
    marks = {}, size = 0, head = 0, seq = 0, on = true,
    last = {}, startedAt = nil, dumped = 0, seen = 0, keys = {}, keysN = 0,
}
function now0()
    return grndTraceClock()
end
function grndTraceClock()
    local ok, c = pcall(os.clock)
    if ok and type(c) == "number" then return c end
    return 0
end
function grndTrace(tag, info)
    local T = GRND_TRACE
    if not T.on then return end
    local now = grndTraceClock()
    local last = T.rep and T.rep[tag]
    local gap = T.gap or 1.0
    if last and last.info == tostring(info or "") and (now - last.at) < gap then
        T.sup = (T.sup or 0) + 1
        return
    end
    T.rep = T.rep or {}
    T.rep[tag] = { info = tostring(info or ""), at = now }
    T.seq = T.seq + 1
    T.head = T.head + 1
    if T.head > 900 then T.head = 1 end
    if T.size < 900 then T.size = T.size + 1 end
    T.marks[T.head] = { at = grndTraceClock(), seq = T.seq, tag = tag,
        info = tostring(info or "") }
end
function grndTraceOnce(key, tag, val)
    local T = GRND_TRACE
    if not T.on then return end
    local s = tostring(val)
    if T.last[key] == s then return end
    T.last[key] = s
    grndTrace(tag, s)
end
function grndTraceDirs()
    local out, seen = {}, {}
    local function push(d)
        d = tostring(d or "")
        if d == "" or seen[d] then return end
        while d:sub(-1) == "/" or d:sub(-1) == "\\" do d = d:sub(1, -2) end
        if d == "" then return end
        seen[d] = true
        out[#out + 1] = d
    end
    if type(this_script_dir) == "function" then
        local okd, sd = pcall(this_script_dir)
        if okd then push(sd) end
    end
    local oki, info = pcall(function() return debug.getinfo(1, "S") end)
    if oki and info and info.source then
        local sc = tostring(info.source):gsub("^@", "")
        local dir = sc:match("^(.*[/\\])[^/\\]*$")
        if dir then push(dir) end
    end
    push("moonloader")
    push("")
    return out
end
function grndTracePath()
    local path=grndStoragePath("logs","grnd_trace.txt")
    if GRND_TRACE then
        GRND_TRACE.path=path
        GRND_TRACE.dir=GRND_STORAGE.root..package.config:sub(1,1).."logs"
    end
    return path
end
function grndTraceEnv()
    local api = { "sampIsDialogActive", "sampIsChatInputActive", "sampIsLocalPlayerSpawned",
        "sampAddChatEntry", "sampRegisterChatCommand", "sampGetChatLine",
        "showCursor", "isKeyClicked", "consumeWindowMessage", "isWindowActive",
        "getD3DDevicePtr", "sampGetCharHealth" }
    local have, miss = {}, {}
    for i = 1, #api do
        if type(_G[api[i]] or rawget(_G, api[i])) == "function" then
            have[#have + 1] = api[i]
        else
            miss[#miss + 1] = api[i]
        end
    end
    return have, miss
end
function grndTraceFrames(delta)
    local T = GRND_TRACE
    T.frames = (T.frames or 0) + (delta or 0)
    return T.frames
end
function T_frames()
    return GRND_TRACE.frames or 0
end
-- v1.7.0: кастомного чата нет — в трассу пишутся только флаги клавиатуры.
function grndTraceState()
    local T = GRND_TRACE
    if not T.on then return end
    local K = GRND_KEYS
    grndTraceOnce("busy", "СИСТЕМНЫЙ диалог открыт", K.authBusy)
    grndTraceOnce("blocked", "перехват клавиш снят", K.blocked)
    grndTraceOnce("spawn", "флаг спавна", K.spawnedNow)
    grndTraceOnce("typing", "родной ввод чата", K.typing)
    grndTraceOnce("tfresh", "уступаем печать", K.typingFresh)
    grndTraceOnce("uib", "меню/таблица открыты", K.uiBusy)
end
function grndTraceDiag()
    local out = {}
    local K = GRND_KEYS
    if IMGUI_WRAP == nil or tostring(IMGUI_WRAP):find("НЕТ") then
        out[#out + 1] = "ImGui НЕ загружен"
    elseif T_frames() == 0 then
        out[#out + 1] = "ни ОДНОГО кадра ImGui не отрисовано"
    end
    if K.authBusy then
        out[#out + 1] = "открыт СИСТЕМНЫЙ диалог сервера"
    end
    if K.typing then
        out[#out + 1] = "игрок печатает в родном чате — хоткеи уступают"
    end
    if #out == 0 then out[#out + 1] = "замечаний нет" end
    return out
end
function grndTraceDump(why)
    local T = GRND_TRACE
    local function now() return grndTraceClock() end
    T.path = nil
    local ok, f = pcall(io.open, grndTracePath(), "w")
    if not ok or not f then
        grndTrace("trace", "НЕ ЧЕГО писать: путь " .. tostring(grndTracePath()))
        return false
    end
    local have, miss = grndTraceEnv()
    local L = {}
    L[#L + 1] = "GRND TOOLS — ТРАССИРОВКА"
    L[#L + 1] = "причина: " .. tostring(why or "ручная")
    L[#L + 1] = "аптайм: " .. string.format("%.1f", grndTraceClock()) .. " с"
    L[#L + 1] = ""
    L[#L + 1] = "--- ОКРУЖЕНИЕ ---"
    L[#L + 1] = "ImGui: " .. tostring(IMGUI_WRAP or "не загружен")
    L[#L + 1] = "кадров: " .. tostring(T_frames())
    L[#L + 1] = "bit.lua: " .. (bit and "есть" or "НЕТ")
    L[#L + 1] = ""
    L[#L + 1] = "--- СОСТОЯНИЕ ---"
    local K = GRND_KEYS
    L[#L + 1] = "authBusy=" .. tostring(K.authBusy) .. " spawnedNow=" .. tostring(K.spawnedNow)
    L[#L + 1] = "typing(родной чат)=" .. tostring(K.typing) .. " blocked=" .. tostring(K.blocked)
    L[#L + 1] = "uiBusy=" .. tostring(K.uiBusy) .. " imguiText=" .. tostring(K.imguiText)
    L[#L + 1] = "чат: штатный ввод SA-MP + панель Tab /a; история текущей сессии"
    L[#L + 1] = "шрифт интерфейса: " .. tostring(GRND_FONT.fontLoadedPath
        or GRND_FONT.fontPath or "системный шрифт обёртки")
    L[#L + 1] = ""
    L[#L + 1] = "--- ДИАГНОЗ ---"
    local d = grndTraceDiag()
    for i = 1, #d do L[#L + 1] = i .. ") " .. d[i] end
    L[#L + 1] = ""
    L[#L + 1] = "--- ЖУРНАЛ ---"
    local i, cnt = T.head, 0
    while cnt < T.size do
        local m = T.marks[i]
        if m then
            L[#L + 1] = string.format("[%7.2f] #%d %-24s %s", m.at, m.seq, m.tag, m.info)
            cnt = cnt + 1
        end
        i = i - 1
        if i < 1 then i = 900 end
    end
    pcall(f.write, f, table.concat(L, "\n") .. "\n")
    pcall(f.close, f)
    return true, grndTracePath()
end
function grndTraceTick()
    local T = GRND_TRACE
    local now = grndTraceClock()
    if not T.startedAt then
        T.startedAt = now
        grndTrace("load", "скрипт запущен")
    end
    grndTraceState()
    if T.dumped < 1 and now - T.startedAt > 5 then
        T.dumped = 1
        pcall(grndTraceDump, "авто: 5 с после запуска")
    elseif T.dumped < 2 and now - T.startedAt > 30 then
        T.dumped = 2
        pcall(grndTraceDump, "авто: 30 с после запуска")
    end
end

-- =====================================================================
--  ТИК КЛАВИАТУРЫ И КОМАНД (v1.7.0: вместо «тика чата»)
--  ---------------------------------------------------------------------
--  Сам ввод и отправка остаются штатными. Надстройка GRND_INPUT (v1.15.44)
--  обрабатывается отдельно; здесь обновляются только флаги клавиатуры.
--  Осталось только то, что нужно хоткеям и интерфейсу:
--    * GRND_KEYS.authBusy  — открыт системный диалог сервера (авторизация):
--      перехват клавиш снимается, чтобы не мешать вводу пароля;
--    * GRND_KEYS.dlgActive — любой диалог сервера (для BLOCK_KEYS_ON_ANY_DIALOG);
--    * GRND_KEYS.spawnedNow — заспавнен ли игрок;
--    * GRND_KEYS.typing / typingFresh — игрок печатает В РОДНОМ ЧАТЕ
--      (штатный sampIsChatInputActive): M/F1/scoreboard уступают вводу;
--      Tab внутри чата теперь меняет канал через GRND_INPUT;
--    * регистрация команд /invis /inv /cam /camera и опциональной /camdiag
--      (она пишет диагностический лог только пока включена командой);
--    * отложенная запись конфига шрифта интерфейса (grnd_ui.cfg).
-- =====================================================================
function grndDialogActive()
    if type(sampIsDialogActive) == "function" then
        local ok, v = pcall(sampIsDialogActive)
        if ok then return v and true or false end
    end
    if type(sampGetDialogText) == "function" then
        local ok, txt = pcall(sampGetDialogText)
        if ok then return txt ~= nil end
    end
    return false
end

local grndToolCmdsReg = false
local function grndRegisterToolCmds()
    if grndToolCmdsReg then return end
    if type(sampRegisterChatCommand) ~= "function" then return end
    grndToolCmdsReg = true
    pcall(sampRegisterChatCommand, "invis", function()
        grndInvisToggle()
    end)
    pcall(sampRegisterChatCommand, "inv", function()
        grndInvisToggle()
    end)
    local function camCmd(arg)
        local a = tostring(arg or ""):gsub("^%s*(.-)%s*$", "%1")
        local num = tonumber(a)
        if num and num > 0 then
            GRND_CAM.enabled = true
            GRND_CAM.dist = math.max(2.0, math.min(50.0, num))
            GRND_CAM.cfgDirty = true
            pcall(grndCamCfgSave)
            if type(sampAddChatMessage) == "function" then
                pcall(grndChatSay, string.format(
                    "{00D6AA}[GRND]{FFFFFF} Камера отдалена: {00D6AA}%.1f м{FFFFFF}",
                    GRND_CAM.dist), -1)
            end
        else
            GRND_CAM.enabled = not GRND_CAM.enabled
            GRND_CAM.cfgDirty = true
            pcall(grndCamCfgSave)
            if type(sampAddChatMessage) == "function" then
                local st = GRND_CAM.enabled and "{00D6AA}ВКЛ{FFFFFF}" or "{FF6666}ВЫКЛ{FFFFFF}"
                pcall(grndChatSay, string.format(
                    "{00D6AA}[GRND]{FFFFFF} Отдаление камеры: %s (дистанция %.1f м)",
                    st, GRND_CAM.dist), -1)
            end
        end
    end
    pcall(sampRegisterChatCommand, "cam", camCmd)
    pcall(sampRegisterChatCommand, "camera", camCmd)
    pcall(sampRegisterChatCommand, "camdiag", function()
        if GRND_CAM_DIAG.enabled then
            local ok,path=grndCamDiagStop("manual")
            if type(grndChatSay)=="function" then
                pcall(grndChatSay,"{00D6AA}[GRND]{FFFFFF} CamDiag ВЫКЛ. Лог: " .. tostring(path or "ошибка"),-1)
            end
        else
            local ok,path=grndCamDiagStart()
            if type(grndChatSay)=="function" then
                if ok then
                    pcall(grndChatSay,"{00D6AA}[GRND]{FFFFFF} CamDiag ВКЛ. Открой/закрой проблемные окна 2–3 раза, затем снова /camdiag. Файл: resource/grnd/logs/grnd_camera_diag.log",-1)
                else
                    pcall(grndChatSay,"{FF6666}[GRND]{FFFFFF} CamDiag не стартовала: " .. tostring(path),-1)
                end
            end
            if ok then print("[GRND camera diag] log: " .. tostring(path)) end
        end
    end)
end

local function grndKeysTick()
    local spawnedNow = grndIsSpawnedSafe()
    local busy = grndAuthDialogActive()
    GRND_KEYS.spawnedNow = spawnedNow
    GRND_KEYS.authBusy = busy
    GRND_KEYS.dlgActive = grndDialogActive()
    -- печатает ли игрок в РОДНОМ чате — только штатный API клиента
    local natTyping = false
    if type(sampIsChatInputActive) == "function" then
        local okT, rT = pcall(sampIsChatInputActive)
        if okT and rT then natTyping = true end
    end
    GRND_KEYS.typing = natTyping
    if natTyping then
        if not GRND_KEYS.typingSince then GRND_KEYS.typingSince = os.clock() end
        GRND_KEYS.typingFresh = (os.clock() - GRND_KEYS.typingSince) < GRND_KEYS.typingTrust
    else
        GRND_KEYS.typingSince = nil
        GRND_KEYS.typingFresh = false
    end
    GRND_KEYS.blocked = busy
    pcall(grndTraceState)
    grndRegisterToolCmds()
    -- конфиг шрифта интерфейса пишется не чаще раза в 1.5 с и только если
    -- что-то реально поменялось (кнопки < > в чекере «Новый Kill List»)
    if GRND_FONT.cfgDirty and (os.clock() - (GRND_FONT.cfgSavedAt or 0)) > 1.5 then
        pcall(grndUiCfgSave)
    end
end

GRND_ONTERM = GRND_ONTERM or {}
function grndOnTerm(fn) table.insert(GRND_ONTERM, fn) end
function onScriptTerminate(scr, quitGame)
    -- Another script unloading must not restore our WH or clear our UI state.
    if scr and type(thisScript)=="function" and scr~=thisScript() then return end
    -- Capture before teardown resets toggles, buffers or positions.
    if type(grndConfigSnapshot)=="function" then pcall(grndConfigSnapshot,true) end
    pcall(grndCamDiagStop,"script unload")
    if GRND_BULK then
        GRND_BULK.stop("Скрипт выгружен.")
        if GRND_BULK.dirtyAt then pcall(grndCamCfgSave) end
    end
    if GRND_WH then
        if GRND_WH.dirtyAt then pcall(grndCamCfgSave) end
        pcall(GRND_WH.release)
    end
    if GRND_TRACER then
        if GRND_TRACER.dirtyAt then pcall(grndCamCfgSave) end
        if GRND_TRACER.font and type(renderReleaseFont) == "function" then
            pcall(renderReleaseFont, GRND_TRACER.font)
            GRND_TRACER.font = nil
        end
        GRND_TRACER.bullets = {}
    end
    if type(showCursor) == "function" then pcall(showCursor, false) end
    pcall(grndF1Rebind)
    if type(setPlayerControl) == "function" then
        pcall(setPlayerControl, PLAYER_HANDLE, true)
    end
    pcall(function()
        if GRND_INVIS then
            GRND_INVIS.on = false
            if PLAYER_PED then
                pcall(grndSetPedAlpha, PLAYER_PED, 255)
            end
        end
    end)
    pcall(grndCamUiEnd,false)
    pcall(grndCamDistanceRelease)
    -- v1.15.0: при выгрузке вернуть стандартный угол обзора
    pcall(function()
        if GRND_CAM and type(grndCamFovReset) == "function" then
            grndCamFovReset()
        end
    end)
    -- v1.15.3: при выгрузке вернуть чувствительность мыши игровой камеры
    pcall(function()
        if type(grndCamLookRestore) == "function" then grndCamLookRestore() end
    end)
    pcall(grndTraceDump, "выгрузка скрипта")
    if _G.GRND_MAIN_ERR then
        print("{FF6666}[GRND]{FFFFFF} main() упал: " .. tostring(_G.GRND_MAIN_ERR))
        if type(sampAddChatMessage) == "function" then
            pcall(grndChatSay, "{FF6666}[GRND] main() упал: "
                .. tostring(_G.GRND_MAIN_ERR), -1)
        end
    end
    for i = 1, #GRND_ONTERM do
        local ok, err = pcall(GRND_ONTERM[i], scr)
        if not ok then
            print("{FF6666}[GRND]{FFFFFF} onScriptTerminate #" .. i .. ": " .. tostring(err))
        end
    end
    pcall(GRND_CONFIG.flush)
    pcall(GRND_LOG.flush)
    pcall(GRND_LOG.stopRead)
end

-- =====================================================================
--  SPECTATE-ТРЕКИНГ (ОДНА копия — дубль удалён)
-- =====================================================================
local GRND_SPEC = { active = false, id = nil, nick = "", carId = nil, carHandle = nil, confirmT = 0, cmdName = "/sp", manualExit = true, isAutoRefreshing = false }
_G.GRND_SPEC = GRND_SPEC
GRND_SPEC_WARP_KEY = 0x58
GRND_SPEC_CAR_KEY = 0x43
GRND_SPEC_CARGO_KEY = 0x56
GRND_SPEC_PLAYER_CMD = "/getplayerpos %d %.2f %.2f %.2f"
GRND_SPEC_VEH_CMD = "/getcarpos %d %.2f %.2f %.2f"
GRND_SPEC_EXIT_KEYS = { 0x20 }
GRND_SPEC_CONFIRM_SEC = 20
GRND_SPEC_EVENTS = false
-- Только функции, которые действительно сообщают режим spectate.
-- sampGetPlayerState()/sampGetLocalPlayerState() возвращают обычное
-- состояние игрока и НЕ означают «в слежке»; их прежнее присутствие здесь
-- сбрасывало GRND_SPEC сразу после /sp.
local SPEC_STATE_FNAMES = {
    "sampIsPlayerSpectating", "isPlayerSpectating", "sampGetSpectating",
}
local specStateFn, specStateFnName = nil, nil
local specWatchT = 0
local specWasSpawned = false
local specArmId, specArmT = nil, 0
local function specProbeState()
    local function scan(fn)
        local res = { pcall(fn) }
        if not res[1] then return nil end
        local last = nil
        for j = 2, #res do
            if type(res[j]) == "number" or type(res[j]) == "boolean" then
                last = res[j]
            end
        end
        if last == nil then return nil end
        if type(last) == "boolean" then return last end
        return last == 9
    end
    if specStateFn then
        return scan(specStateFn)
    end
    for i = 1, #SPEC_STATE_FNAMES do
        local f = _G[SPEC_STATE_FNAMES[i]]
        if type(f) == "function" then
            local st = scan(f)
            if st ~= nil then
                specStateFn, specStateFnName = f, SPEC_STATE_FNAMES[i]
                return st
            end
        end
    end
    return nil
end
-- v1.19.40: фактическую слежку (игра сама подтверждает: sampIsPlayerSpectating
-- и родня) отдаём наружу — по ней автопилот решает, вставать ли на паузу.
-- true — слежка идёт, false — точно нет, nil — спросить не получилось.
_G.grndSpecProbeState = specProbeState
local SPEC_SPECTID_FNAMES = {
    "sampGetSpectateId", "sampGetSpectatedPlayerId",
    "sampGetPlayerSpectateId", "sampGetSpectatePlayerId",
}
local specSpectIdFn = nil
local function specProbeSpectId()
    local function scan(fn)
        local res = { pcall(fn) }
        if res[1] then
            for j = 2, #res do
                if type(res[j]) == "number" and res[j] >= 0 and res[j] <= 1000 then
                    return res[j]
                end
            end
        end
        return nil
    end
    if specSpectIdFn then
        return scan(specSpectIdFn)
    end
    for i = 1, #SPEC_SPECTID_FNAMES do
        local f = _G[SPEC_SPECTID_FNAMES[i]]
        if type(f) == "function" then
            local id = scan(f)
            if id then
                specSpectIdFn = f
                return id
            end
        end
    end
    return nil
end
-- v1.11.52: sampGetPlayerNickname/sampGetCharHandleBySampPlayerId с
-- НЕсуществующим id убивают скрипт/игру (в килл-листе это уже чинили:
-- «cannot resume non-suspended coroutine», pcall НЕ спасает). Перед
-- ЛЮБЫМ samp-вызовом с чужим id проверяем подключение.
local function specConnected(id)
    if type(id) ~= "number" or id < 0 or id > 1003 then return false end
    if type(sampIsPlayerConnected) ~= "function" then return true end
    local ok, conn = pcall(sampIsPlayerConnected, id)
    if not ok then return false end
    return conn and true or false
end
_G.specConnected = specConnected

function grndSpecForget(reason)
    if not GRND_SPEC.active and not GRND_SPEC.id then return end
    local oldId = GRND_SPEC.id
    local isTargetConn = oldId and specConnected(oldId)
    local autoRefreshOn = (GRND_ADMIN_CFG and GRND_ADMIN_CFG.spAutoRefresh ~= false)

    if reason == "quit" or reason == "key" then
        GRND_SPEC.manualExit = true
        if _G.GRND_SPEC_AUTOREF then
            _G.GRND_SPEC_AUTOREF.manualExit = true
            _G.GRND_SPEC_AUTOREF.lastTargetId = nil
            _G.GRND_SPEC_AUTOREF.lostSince = nil
            _G.GRND_SPEC_AUTOREF.refreshCount = 0
        end
        if reason == "quit" and type(_G.grndRcForceClose) == "function" then
            pcall(_G.grndRcForceClose, "quit")
        end
    end

    GRND_SPEC.active = false
    GRND_SPEC.id = nil
    GRND_SPEC.nick = ""
    GRND_SPEC.confirmT = 0

    if autoRefreshOn and isTargetConn and not GRND_SPEC.manualExit and (reason == "state" or reason == "stale" or reason == "spawn") then
        return
    end

    local why = ""
    if reason == "state" then why = " (игра: не в слежке)"
    elseif reason == "stale" then why = " (нет подтверждений)"
    elseif reason == "quit" then why = " (игрок вышел)"
    elseif reason == "spawn" then why = " (респавн)"
    elseif reason == "key" then why = " (выход клавишей)"
    end
    notify.add("Слежка: трекинг сброшен" .. why, "warn", 3)
end
local function specConfirm()
    GRND_SPEC.confirmT = os.clock()
end
function grndSpecInSpec()
    if not GRND_SPEC.active then return false end
    if not GRND_SPEC.id then return false end
    if not GRND_SPEC_EVENTS then
        if os.clock() - (GRND_SPEC.confirmT or 0) > GRND_SPEC_CONFIRM_SEC then
            return false
        end
    end
    return true
end
local SPEC_ON_CMDS = { sp = true, spec = true, spectate = true, recon = true }
local SPEC_OFF_CMDS = { spoff = true, specoff = true, stopspec = true, specstop = true,
    reoff = true, reconoff = true, despec = true, unspec = true,
    despectate = true, stopsp = true, spstop = true, endspec = true,
    spawn = true }
local function specCp2Utf(s)
    if type(s) ~= "string" or s == "" then return s or "" end
    local enc = encoding or (libs and libs.encoding)
    if not enc or not enc.UTF8 then return s end
    local ok, out = pcall(function()
        local prev = enc.default
        enc.default = "CP1251"
        local r = enc.UTF8:encode(s)
        enc.default = prev
        return r
    end)
    if ok and type(out) == "string" then return out end
    return s
end
local specLastTrack, specLastTrackT = "", 0
local function grndSpecTrackCommand(cmd)
    local raw = tostring(cmd or "")
    local nowT = os.clock()
    if raw == specLastTrack and nowT - specLastTrackT < 1.0 then return end
    specLastTrack, specLastTrackT = raw, nowT
    local c = raw:gsub("^%s*/", ""):lower()
    local name, arg = c:match("^(%a+)%s*(%d*)")
    if not name then return end
    if SPEC_ON_CMDS[name] then
        local id = tonumber(arg)
        if id then
            -- Это новый сеанс слежки, а не старый кешированный TextDraw.
            -- Сбрасываем блокировку только по фактическому /sp с ID.
            if _G.GRND_RC then
                GRND_RC.reconHidden = false
                GRND_RC.reconSeen = false
                GRND_RC.reconTdActive = false
                GRND_RC.reconMissingAt = nil
            end
            -- v1.11.52: id может не быть на сервере — тогда НЕ начинаем
            -- слежку и не трогаем samp-функции (иначе краш)
            if not specConnected(id) then
                notify.add("Слежка не начата: игрока #" .. id
                    .. " нет на сервере", "error", 5)
            else
                GRND_SPEC.active = true
                GRND_SPEC.id = id
                GRND_SPEC.cmdName = "/" .. name
                GRND_SPEC.manualExit = false
                GRND_SPEC.confirmT = os.clock()
                if type(sampGetPlayerNickname) == "function" then
                    local ok, n = pcall(sampGetPlayerNickname, id)
                    if ok and type(n) == "string" and n ~= "" then
                        GRND_SPEC.nick = specCp2Utf(n)
                    end
                end
                if GRND_SPEC.isAutoRefreshing then
                    GRND_SPEC.isAutoRefreshing = false
                else
                    if _G.GRND_SPEC_AUTOREF then
                        _G.GRND_SPEC_AUTOREF.manualExit = false
                        _G.GRND_SPEC_AUTOREF.lastTargetId = id
                        _G.GRND_SPEC_AUTOREF.lastTargetNick = GRND_SPEC.nick or ""
                        _G.GRND_SPEC_AUTOREF.lostSince = nil
                        _G.GRND_SPEC_AUTOREF.refreshCount = 0
                        _G.GRND_SPEC_AUTOREF.graceUntil = os.clock() + 2.5
                    end
                    local who = "#" .. id .. (GRND_SPEC.nick ~= "" and (" (" .. GRND_SPEC.nick .. ")") or "")
                    notify.add("Слежка: " .. who, "info", 5)
                end
            end
        elseif GRND_SPEC.active then
            GRND_SPEC.active = false
            GRND_SPEC.id = nil
            GRND_SPEC.nick = ""
            GRND_SPEC.confirmT = 0
            GRND_SPEC.manualExit = true
            if _G.GRND_SPEC_AUTOREF then
                _G.GRND_SPEC_AUTOREF.manualExit = true
                _G.GRND_SPEC_AUTOREF.lastTargetId = nil
                _G.GRND_SPEC_AUTOREF.lostSince = nil
                _G.GRND_SPEC_AUTOREF.refreshCount = 0
            end
            notify.add("Слежка выключена", "info", 3)
        end
    elseif SPEC_OFF_CMDS[name] then
        if GRND_SPEC.active then
            GRND_SPEC.active = false
            GRND_SPEC.id = nil
            GRND_SPEC.nick = ""
            GRND_SPEC.confirmT = 0
            GRND_SPEC.manualExit = true
            if _G.GRND_SPEC_AUTOREF then
                _G.GRND_SPEC_AUTOREF.manualExit = true
                _G.GRND_SPEC_AUTOREF.lastTargetId = nil
                _G.GRND_SPEC_AUTOREF.lostSince = nil
                _G.GRND_SPEC_AUTOREF.refreshCount = 0
            end
            notify.add("Слежка выключена", "info", 3)
        end
    end
end
-- =====================================================================
--  МОДУЛЬ 13b (v1.11.0): перехват нативного спектeйта SAMP
--
--  Цель: при входе в слежку стандартный box рекона SA:MP гасится,
--  вместо него остаётся наше окно (модуль 13) + наша камера на цели.
--
--  Как это устроено (без гаданий — всё верифицируется в рантайме):
--   1) Автоопределение версии SAMP по кандидатам 0.3.7 / R1 / R3 / R5 / DL.
--      Кандидат принимается только если:
--        a) CGame (в samp.dll) -> m_pPlayerPed == PLAYER_PED;
--        b) для живых игроков пул игроков возвращает валидный ped,
--           и sampGetPlayerIdByCharHandle(ped) отдаёт тот же id.
--      (Оффсеты посчитаны по заголовкам SAMP-API, packed(1);
--       перекрёстно сверены с публичными данными по 0.3.7.)
--   2) Калибровка структуры spectate клиента {mode, type, target}:
--      при /spec N число N — «эталон». Сканируем CLocalPlayer в поисках
--      структуры с target=N. Работает на ЛЮБОМ билде клиента.
--   3) Пока идёт слежка, структура обнуляется — ProcessSpectating
--      SAMP ничего не делает: и стандартный box, и его камера молчат.
--   4) Наша камера: attachCameraToCharLookAtChar (штатный MoonLoader)
--      держится на педе цели каждый кадр.
--   5) Данные для окна: координаты/скин/пинг — штатный API;
--      ХП/броня/авто — из пула игроков с sanity-проверками (если чтение
--      не проходит — в окне просто 0/«Нет», без ошибок).
-- =====================================================================
grndSpecNative = {
    ok = false, ver = nil, v = nil,
    lp = nil, pp = nil, pools = nil, di = nil,
    calOff = nil, calCands = {},
    camOn = false, camPed = nil,
    -- v1.14.58: камера слежки. Обход стен/интерьеров (v1.14.59 — ВСЕГДА
    -- включён, без тумблера): линия видимости от цели до камеры, при
    -- препятствии камера подтягивается к стене и никогда не уходит за неё.
    -- v1.15.0: умная слежка — авто-подстройка дистанции/высоты/ракурса под
    -- состояние цели (бег, машина, мото, лодка, вертолёт, самолёт, вода);
    -- FOV из слежки убран (переехал в Настройки → Дистанция камеры).
    -- camStart* — ракурс, на который камера встаёт при входе в слежку.
    camStartDist = 7.0, camStartPitch = 0.50, camStartAngle = 0.0,
    initT = nil, scanT = 0, scanCacheOn = false, scanCacheId = nil,
    -- Тесты могут подставить монотонные часы: S.clock = function() ... end.
    -- В обычной игре поле nil, поэтому используется os.clock().
    clock = nil,
    initLogged = false, failLogged = false,
}
do
    local S = grndSpecNative

    -- Часы вынесены в тестовый seam: os.clock() почти не продвигается в
    -- быстрых unit-тестах, поэтому throttle в spectScan нельзя надёжно
    -- проверить без виртуального времени. В игре поведение не меняется.
    local function clockNow()
        if type(S.clock) == "function" then
            local ok, value = pcall(S.clock)
            if ok and type(value) == "number" then return value end
        end
        local ok, value = pcall(os.clock)
        return (ok and type(value) == "number") and value or 0
    end

    -- v1.11.27: имена функций memory-библиотеки РАЗНЫЕ в разных сборках
    -- (getint32 / readint32 / readdword / readint...). Раньше здесь стоял
    -- только memory.readint — на сборках без него ВСЕ чтения молча падали:
    -- калибровка spectate не проходила (S.ok=false), скан пула не работал.
    local mem32 = memory and (memory.getint32 or memory.readint32
        or memory.readdword or memory.readint) or nil
    local mem8  = memory and (memory.getint8 or memory.readint8
        or memory.getuint8 or memory.readbyte or memory.getbyte) or nil
    local memf  = memory and (memory.getfloat or memory.readfloat) or nil
    local memw8 = memory and (memory.setint8 or memory.writeint8
        or memory.setbyte or memory.writebyte) or nil
    local memw32 = memory and (memory.setint32 or memory.writeint32
        or memory.writedword or memory.writeint) or nil
    -- v1.19.57: БЮДЖЕТ ЧТЕНИЙ НА ЗАХОД. Разбор структур samp.dll раньше мог
    -- за один тик сделать десятки тысяч чтений памяти и подвесить игру —
    -- именно это ловилось как «зашёл в слежку и всё зависло». Теперь каждый
    -- проход ограничен бюджетом: не успели — продолжаем следующим тиком,
    -- игра не встаёт ни на кадр.
    local BUDGET_MAX = 3000
    local budget = { n = 0, out = false, max = BUDGET_MAX, deadline = nil }
    local function budgetStart(limit, ms)
        budget.n, budget.out = 0, false
        budget.max = limit or BUDGET_MAX
        budget.deadline = ms and (os.clock() + ms / 1000) or nil
    end
    local function budgetSpend()
        budget.n = budget.n + 1
        if budget.n > budget.max then budget.out = true; return end
        -- время проверяем редко: os.clock() на каждом чтении сам стал бы дорогим
        if budget.deadline and (budget.n % 64 == 0)
            and os.clock() > budget.deadline then budget.out = true end
    end

    local function r8(a)
        if not mem8 then return nil end
        budgetSpend()
        local ok, v = pcall(mem8, a)
        return ok and v or nil
    end
    local function r32(a)
        if not mem32 then return nil end
        budgetSpend()
        local ok, v = pcall(mem32, a)
        if not ok or type(v) ~= "number" then return nil end
        if v < 0 then v = v + 4294967296 end
        return v
    end
    local function r16(a)
        local v = r32(a)
        return v and v % 65536 or nil
    end
    local function rf(a)
        if not memf then return nil end
        local ok, v = pcall(memf, a)
        return ok and v or nil
    end
    local function w8(a, v)  if memw8 then pcall(memw8, a, v) end end
    local function w32(a, v) if memw32 then pcall(memw32, a, v) end end

    local function validPtr(p)
        return type(p) == "number" and p > 0x10000 and p < 0x78000000
    end

    -- Кандидаты по версиям (см. таблицу в комментарии выше):
    -- net/game   — глобалы samp.dll (CNetGame*, CGame*)
    -- pools      — CNetGame -> Pools
    -- cplayer    — Pools -> CPlayerPool
    -- dinfo      — CPlayerPool -> массив CPlayerInfo
    -- infoPtr    — CPlayerInfo -> CRemotePlayer
    -- poolsVeh   — Pools -> CVehiclePool
    -- rpPed/rpVeh/rpArmor/rpHp — поля CRemotePlayer
    local VERS = {
        { name = "0.3.7-R1", net = 0x21A0F8, game = 0x21A10C,
          pools = { 0x3CD, 0x43C }, cplayer = { 0x18 },
          dinfo = { 0x22, 0x2E, 0x1E, 0x26, 0x16, 0x32 }, lpScanMax = 0x100,
          poolsVeh = 0x1C, infoPtr = 0x00, rpPed = 0x00,
          rpVeh = 0xAD, rpArmor = 0x1BC, rpHp = 0x1C0 },
        { name = "0.3.7", net = 0x21A0F8, game = 0x21A10C,
          pools = { 0x3CD }, cplayer = { 0x18, 0x08 },
          dinfo = { 0x2E, 0x22, 0x32, 0x2A, 0x1E }, lpScanMax = 0x100,
          poolsVeh = 0x1C, infoPtr = 0x00, rpPed = 0x00,
          rpVeh = 0xAD, rpArmor = 0x1B8, rpHp = 0x1BC },
        { name = "0.3.7-R3", net = 0x26E8DC, game = 0x26E8F4,
          pools = { 0x3DE }, cplayer = { 0x08 },
          dinfo = { 0x04, 0x08, 0x00, 0x0C }, lpScanMax = 0x1900,
          poolsVeh = 0x0C, infoPtr = 0x00, rpPed = 0x00,
          rpVeh = 0x0A, rpArmor = 0x1B0, rpHp = 0x1B4 },
        { name = "0.3.7-R5", net = 0x26EB94, game = 0x26EBAC,
          pools = { 0x3DA }, cplayer = { 0x04 },
          dinfo = { 0x40A, 0x406, 0x40E, 0x416 }, lpScanMax = 0x100,
          poolsVeh = 0x00, infoPtr = 0x0C, rpPed = 0x1E1,
          rpVeh = 0x1EB, rpArmor = 0x1B0, rpHp = 0x1B4 },
        { name = "0.3.DL", net = 0x2ACA24, game = 0x2ACA3C,
          pools = { 0x3DE }, cplayer = { 0x08 },
          dinfo = { 0x1A, 0x1E, 0x16, 0x22 }, lpScanMax = 0x100,
          poolsVeh = 0x0C, infoPtr = 0x08, rpPed = 0x04,
          rpVeh = 0x02, rpArmor = 0x1B0, rpHp = 0x1B4 },
    }

    local function liveIds(n)
        local ids = {}
        local function add(id)
            if type(id) ~= "number" or id < 0 or id >= 1004 then return end
            for _, k in ipairs(ids) do
                if k == id then return end
            end
            ids[#ids + 1] = id
        end
        if type(sampGetLocalPlayerId) == "function" then
            local ok, lid = pcall(sampGetLocalPlayerId)
            if ok then add(lid) end
        end
        local maxId = 128
        if type(sampGetMaxPlayerId) == "function" then
            local ok, m = pcall(sampGetMaxPlayerId)
            if ok and type(m) == "number" and m > maxId then maxId = m end
        end
        -- v1.19.57: сервер может разрешать и 500, и 1000 слотов — проверять
        -- их все дорого (каждый слот это вызовы SAMPFUNCS), а для калибровки
        -- хватает локального игрока и соседних слотов
        if maxId > 64 then maxId = 64 end
        for id = 0, maxId do
            if n and #ids >= n then break end
            if budget.out then break end
            -- v1.11.52: nickname с неподключённым id крашит — сначала
            -- проверяем подключение; без такой функции не сканируем
            -- вообще (калибровка подождёт следующего раза)
            local conn = nil
            if type(sampIsPlayerConnected) == "function" then
                local okc, c2 = pcall(sampIsPlayerConnected, id)
                conn = (okc and c2) and true or false
            end
            if conn and type(sampGetPlayerNickname) == "function" then
                local ok, nk = pcall(sampGetPlayerNickname, id)
                if ok and type(nk) == "string" and nk ~= "" then
                    add(id)
                end
            end
        end
        return ids
    end

    -- CLocalPlayer: указатель P, у которого *(P+0) == PLAYER_PED
    -- (первое поле класса всегда m_pPed — не зависит от версии).
    -- ВАЖНО: шаг 1, а не 4 — в packed(1) кладках указатель локального
    -- игрока в пуле может лежать на НЕвыровненном смещении (R1: 0x16).
    -- v1.19.57: скан указателя идёт СРЕЗАМИ. Раньше один вызов перебирал до
    -- 0x1900 адресов (до 6400 чтений) — на незнакомой сборке это несколько
    -- сотен миллисекунд в одном тике. Теперь за заход не больше LP_SLICE
    -- адресов, курсор продолжает с того же места в следующий заход.
    local LP_SLICE = 0x200
    local function findLocalPlayer(pPP, scanMax, di)
        if S.lpAtKey ~= tostring(pPP) .. ":" .. tostring(di) then
            S.lpAtKey, S.lpAt = tostring(pPP) .. ":" .. tostring(di), 0
        end
        local from = S.lpAt or 0
        local to = math.min(scanMax, from + LP_SLICE)
        for off = from, to do
            if budget.out then
                S.lpAt = off
                return nil
            end
            local p = r32(pPP + off)
            if validPtr(p) and r32(p) == PLAYER_PED then
                S.lpAt, S.lpAtKey = nil, nil
                return p
            end
        end
        if to < scanMax then
            S.lpAt = to + 1          -- срез пройден — продолжим следующим тиком
            return nil
        end
        S.lpAt, S.lpAtKey = nil, nil
        return nil
    end

    local function tryInit()
        if S.ok then return true end
        -- v1.19.57: заход ограничен и по числу чтений, и по времени (20 мс):
        -- не успели — продолжим со следующего захода, игра не встаёт
        budgetStart(1200, 20)
        local base
        if type(getModuleHandle) == "function" then
            local ok, b = pcall(getModuleHandle, "samp.dll")
            if ok and type(b) == "number" and b > 0 then base = b end
        end
        if not base then return false end
        for _, vt in ipairs(VERS) do
            local pGame = r32(base + vt.game)
            if validPtr(pGame) and r32(pGame + 0x08) == PLAYER_PED then
                local pNG = r32(base + vt.net)
                if validPtr(pNG) then
                    for _, bpo in ipairs(vt.pools) do
                        local pPools = r32(pNG + bpo)
                        if validPtr(pPools) then
                            for _, cpl in ipairs(vt.cplayer) do
                                local pPP = r32(pPools + cpl)
                                if validPtr(pPP) then
                                    local ids = liveIds(3)
                                    if #ids > 0 and not budget.out then
                                    for _, di in ipairs(vt.dinfo) do
                                        if budget.out then break end
                                        local good, bad = 0, 0
                                            for _, id in ipairs(ids) do
                                                local info = r32(pPP + di + id * 4)
                                                if validPtr(info) then
                                                    local rp = r32(info + vt.infoPtr)
                                                    if validPtr(rp) then
                                                        local ped = r32(rp + vt.rpPed)
                                                        local back
                                                        if validPtr(ped)
                                                            and type(sampGetPlayerIdByCharHandle) == "function" then
                                                            local okI, i2 = pcall(sampGetPlayerIdByCharHandle, ped)
                                                            if okI then back = i2 end
                                                        end
                                                        if back == id then
                                                            good = good + 1
                                                        else
                                                            bad = bad + 1
                                                        end
                                                    end
                                                end
                                            end
                                            if good >= 1 and bad == 0 and not budget.out then
                                                local pLP = findLocalPlayer(pPP, vt.lpScanMax, di)
                                                if pLP then
                                                    S.ok = true
                                                    S.ver = vt.name
                                                    S.v = vt
                                                    -- vt.dinfo — список кандидатов. Сохраняем
                                                    -- именно тот offset, на котором прошла
                                                    -- верификация; remoteOf() использует S.di.
                                                    S.di = di
                                                    S.pp = pPP
                                                    S.pools = pPools
                                                    S.lp = pLP
                                                    if not S.initLogged then
                                                        S.initLogged = true
                                                        print("{00FFAA}[GRND]{FFFFFF} слежка: версия SAMP \"" .. vt.name .. "\" — память верифицирована")
                                                    end
                                                    return true
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
        if not S.failLogged and not budget.out then
            S.failLogged = true
            print("{FBD38DFF}[GRND]{FFFFFF} слежка: версия SAMP не распознана (чтение памяти отключено, окно работает как раньше)")
        end
        return false
    end
    S.tryInit = tryInit

    -- ===== структура spectate: { char mode; char type; int target; } =====
    local MODE_OK = { [0] = true, [3] = true, [4] = true, [14] = true, [15] = true }

    -- Быстрое чтение по откалиброванному оффсету
    function S.spectState()
        local off = S.calOff
        if not off or not S.lp then return false, nil end
        local mode = r8(S.lp + off)
        local typ = r8(S.lp + off + 1)
        local obj = r32(S.lp + off + 2)
        if mode ~= nil and typ ~= nil and obj ~= nil
            and (typ == 1 or typ == 2) and obj >= 0 and obj <= 1999 then
            return true, (typ == 1 and obj <= 1003) and obj or nil
        end
        return false, nil
    end

    -- Сканирование (до калибровки): ищем любую валидную структуру.
    -- v1.19.57: идём СРЕЗАМИ по 128 смещений — один заход больше не делает
    -- до 1500 чтений памяти, полный круг набирается за четыре захода.
    local SCAN_STEP = 0x80
    function S.spectScan()
        if not S.ok or not S.lp then return false, nil end
        local now = clockNow()
        if now - (S.scanT or 0) < 0.25 then
            return S.scanCacheOn, S.scanCacheId
        end
        S.scanT = now
        budgetStart(700, 8)
        local on, tid = false, nil
        local from = S.scanAt or 0
        local to = math.min(0x1FF, from + SCAN_STEP - 1)
        for off = from, to do
            local mode = r8(S.lp + off)
            if MODE_OK[mode] then
                local typ = r8(S.lp + off + 1)
                if typ == 1 or typ == 2 then
                    local obj = r32(S.lp + off + 2)
                    if obj >= 0 and obj <= 1003 then
                        on, tid = true, (typ == 1) and obj or nil
                        break
                    end
                end
            end
        end
        if not on and to < 0x1FF then
            -- срез пройден, круг ещё нет: отдаём прошлый результат, идём дальше
            S.scanAt = to + 1
            return S.scanCacheOn, S.scanCacheId
        end
        S.scanAt = nil
        S.scanCacheOn, S.scanCacheId = on, tid
        return on, tid
    end

    -- Обнуляем структуру: нативная слежка SAMP перестаёт работать
    -- (стандартный box и его камера больше не рисуются)
    function S.killNative()
        local off = S.calOff
        if not off or not S.lp then return end
        w8(S.lp + off, 0)
        w8(S.lp + off + 1, 0)
        w32(S.lp + off + 2, -1)
    end

    -- Калибровка: targetId — эталон (из команды /spec N)
    function S.calibrate(targetId)
        if not S.ok or not S.lp then return end
        if S.calOff or type(targetId) ~= "number" then return end
        local found = {}
        for off = 0, 0x1FF do
            local mode = r8(S.lp + off)
            if MODE_OK[mode] then
                local typ = r8(S.lp + off + 1)
                if typ == 1 or typ == 2 then
                    local obj = r32(S.lp + off + 2)
                    if typ == 1 and obj == targetId then
                        found[#found + 1] = off
                    end
                end
            end
        end
        if #found > 0 then
            -- пересечение с кандидатами прошлых сессий (разборчиваем
            -- ложные совпадения, если они были)
            if next(S.calCands) then
                local set = {}
                for _, c in ipairs(found) do set[c] = true end
                local inter = {}
                for _, c in ipairs(S.calCands) do
                    if set[c] then inter[#inter + 1] = c end
                end
                if #inter > 0 then found = inter end
            end
            if #found == 1 then
                S.calOff = found[1]
                S.calCands = {}
                print("{00FFAA}[GRND]{FFFFFF} слежка: структура spectate откалибрована (0x" .. string.format("%X", S.calOff) .. ")")
            else
                S.calCands = found
            end
        end
    end

    -- ===== данные цели =====
    -- v1.11.29: адреса пулов — по gtamods (Peds = 0xB74490), шаг CPed
    -- 0x7C4, handle = (index<<8)|byteMap[index]. Возвращаем НАСТОЯЩИЙ
    -- handle — именно его понимает attachCameraToCharLookAtChar.
    local function poolHandleForId(id)
        if not mem32 then return nil end
        local okp, pool = pcall(mem32, 0xB74490)
        if not okp or type(pool) ~= "number"
            or pool <= 0x10000 or pool >= 0x78000000 then return nil end
        local oko, objs = pcall(mem32, pool)
        local okb, bmp = pcall(mem32, pool + 4)
        local oks, sz = pcall(mem32, pool + 8)
        if not (oko and okb and oks) then return nil end
        if type(sz) == "number" and sz < 0 then sz = sz + 4294967296 end
        if type(objs) ~= "number" or objs <= 0x10000 or objs >= 0x78000000
            or type(sz) ~= "number" or sz <= 0 or sz > 1000 then
            return nil
        end
        local stride = 0x7C4
        local function byteAt(i)
            if not mem8 then return nil end
            local ok, b = pcall(mem8, bmp + i)
            if not ok or type(b) ~= "number" then return nil end
            if b < 0 then b = b + 256 end
            return b % 256
        end
        -- 1) указатель цели из камеры (m_pTargetEntity) -> индекс -> handle
        local okt, t = pcall(mem32, 0xB6F028 + 0x958)
        if okt and type(t) == "number" and t >= objs and t < objs + sz * stride then
            local di = (t - objs) / stride
            if di == math.floor(di) and math.floor(di) > 0 then
                local b = byteAt(math.floor(di))
                if b and b < 128 then
                    local h = math.floor(di) * 256 + b
                    if h ~= PLAYER_PED then
                        return h, t
                    end
                end
            end
        end
        -- 2) полный скан с обратной функцией (если она живая, исключаем PLAYER_PED)
        if type(sampGetPlayerIdByCharHandle) == "function" then
            for i = 1, sz - 1 do
                local b = byteAt(i)
                if b and b < 128 then
                    local h = i * 256 + b
                    if h ~= PLAYER_PED then
                        local oki, found, rid = pcall(sampGetPlayerIdByCharHandle, h)
                        if type(found) == "number" then rid = found end
                        if oki and found ~= false and rid == id then return h, objs + i * stride end
                    end
                end
            end
        end
        return nil
    end

    function S.pedOf(id)
        if type(id) ~= "number" or id < 0 or id > 1003 then return nil end
        -- v1.11.52: не дёргать samp с отключённым id (краш)
        if type(sampIsPlayerConnected) == "function" then
            local okc, conn = pcall(sampIsPlayerConnected, id)
            if okc and not conn then return nil end
        end
        if type(sampGetCharHandleBySampPlayerId) ~= "function" then return nil end
        local ped = grndSpecApiHandle(sampGetCharHandleBySampPlayerId, id)
        local ok = ped ~= nil
        -- sampGetCharHandleBySampPlayerId возвращает HANDLE педа, а не
        -- указатель на память. Проверка validPtr() здесь отбрасывала почти
        -- все реальные handles и делала цель «не найденной».
        if ok and type(ped) == "number" and ped ~= 0 and ped ~= PLAYER_PED then
            if type(doesCharExist) == "function" then
                local okE, e = pcall(doesCharExist, ped)
                if okE and e then return ped end
            else
                return ped
            end
            -- A handle rejected by doesCharExist is not a live target.
        end
        local nowC = os.clock()
        local cc = S.pedCache
        if cc and cc.id == id and cc.ptr and cc.ptr ~= PLAYER_PED
            and nowC - (cc.t or 0) < 0.5 then
            return cc.ptr
        end
        local h = poolHandleForId(id)
        if h and h ~= PLAYER_PED then
            S.pedCache = { id = id, ptr = h, t = nowC }
            return h
        end
        return nil
    end

    function S.remoteOf(id)
        if not S.ok or not S.pp or not S.di then return nil end
        if type(id) ~= "number" or id < 0 or id > 1003 then return nil end
        local info = r32(S.pp + S.di + id * 4)
        if not validPtr(info) then return nil end
        local rp = r32(info + S.v.infoPtr)
        return validPtr(rp) and rp or nil
    end

    function S.getVehicleId(id)
        local rp = S.remoteOf(id)
        if not rp then return nil end
        local v = r16(rp + S.v.rpVeh)
        if v and v >= 0 and v <= 1999 then return v end
        return nil
    end

    function S.getHealth(id)
        local rp = S.remoteOf(id)
        if not rp then return nil end
        local f = rf(rp + S.v.rpHp)
        if type(f) == "number" and f >= 0 and f <= 200 then return f end
        return nil
    end

    function S.getArmor(id)
        local rp = S.remoteOf(id)
        if not rp then return nil end
        local f = rf(rp + S.v.rpArmor)
        if type(f) == "number" and f >= 0 and f <= 100 then return f end
        return nil
    end

    function S.getVehicleModel(vehId)
        if not S.ok or not S.pools then return nil end
        if type(vehId) ~= "number" or vehId < 0 or vehId > 1999 then return nil end
        local pVP = r32(S.pools + S.v.poolsVeh)
        if not validPtr(pVP) then return nil end
        local pv = r32(pVP + vehId * 4)
        if not validPtr(pv) then return nil end
        local model = r32(pv + 0x30)
        if model and model >= 1 and model <= 198 then return model end
        return nil
    end
end

-- Тик модуля 13b (вызывается из grndRcTick)
-- v1.11.22: камера слежки вынесена в отдельную функцию и тикает
-- КАЖДЫЙ кадр, даже когда структуры нативного spectate не найдены
-- (S.ok == false) — раньше на таких сборках весь блок камеры
-- просто не достигался и управление «ничего не применяло».
-- =====================================================================
--  v1.11.30: ПРЯМОЕ управление камерой GTA SA (без samp-attach).
--  Карта (GTA SA 1.0, эталонные оффсеты из plugin-sdk):
--    CCamera 0xB6F028:
--      +0x14 m_matrix (CMatrixLink*), +0x59 m_nActiveCam,
--      +0x174 m_aCams[3] (по 0x238; Front +0x190, Source +0x19C,
--      Up +0x1B4), +0x954 m_pRwCamera, +0x958 m_pTargetEntity,
--      +0x974 m_mCameraMatrix (RwMatrixTag: right+0x00, up+0x10,
--      at+0x20, pos+0x30).
--    0x52B730 — CCamera::Process (НЕ трогаем: внутри фейды и вывод),
--    0x527FA0 — CCamera::CamControl: байт 0xC3 замораживает только его.
--  Схема: на время слежки замораживаем CamControl и каждый кадр пишем
--  орбиту в m_mCameraMatrix (+ дубли в m_matrix и RwFrame) — остальная
--  часть CCamera::Process сама переносит матрицу на экран
--  (CopyCameraMatrixToRWCam). При выходе из слежки байт восстанавливается.
-- =====================================================================
GRND_CAM_DIRECT = { locked = false, orig = nil, camIdx = nil,
    copyOk = false, copyFn = nil, reason = "" }

local GRND_CAM_MEM_CACHE
grndCamMem = function()
    local m = memory
    if not m then return nil end
    if GRND_CAM_MEM_CACHE and GRND_CAM_MEM_CACHE.owner==m then return GRND_CAM_MEM_CACHE end
    GRND_CAM_MEM_CACHE={owner=m,
        w16 = m.setint16 or m.writeint16 or m.writeword,
        r32 = m.getint32 or m.readint32 or m.readdword or m.readint,
        r8  = m.getint8 or m.readint8 or m.readbyte or m.getbyte,
        rf  = m.getfloat or m.readfloat,
        wf  = m.setfloat or m.writefloat,
        w8  = m.setint8 or m.writeint8 or m.writebyte or m.setbyte,
        w32 = m.setint32 or m.writeint32 or m.writedword or m.writeint,
    }
    return GRND_CAM_MEM_CACHE
end
function grndCamWriteMode(M,addr,mode)
    if M.w16 then return pcall(M.w16,addr,mode) end
    if not M.r32 or not M.w32 then return false end
    local ok,v=pcall(M.r32,addr)
    if not ok or type(v)~='number' then return false end
    v=v%4294967296
    return pcall(M.w32,addr,math.floor(v/65536)*65536+mode)
end

-- v1.11.34: замораживаем НЕ весь CCamera::Process, а только подфункцию
-- CamControl (0x527FA0, адрес из эталонного plugin-sdk). Process при этом
-- продолжает работать: фейды слежки доигрываются (нет «Загрузка...»/белой
-- пелены), матрица каждый кадр выводится на экран, а положение камеры
-- пересчитываться перестаёт — его пишем мы.
GRND_CAM_MOVER_ADDR = 0x527FA0

function grndCamMoverUnlock()
    local M = GRND_CAM_DIRECT
    if not M.locked then return end
    local mm = grndCamMem()
    if mm and mm.w8 and M.orig then pcall(mm.w8, GRND_CAM_MOVER_ADDR, M.orig) end
    M.locked = false
end

-- Записать матрицу (4 вектора, шаг 0x10, флаги не трогаем)
local function grndCamWriteMat(MM, base, rx, ry, rz, ux, uy, uz,
    fx, fy, fz, px, py, pz)
    local function v(off, x, y, z)
        pcall(MM.wf, base + off, x)
        pcall(MM.wf, base + off + 4, y)
        pcall(MM.wf, base + off + 8, z)
    end
    v(0x00, rx, ry, rz)   -- right
    v(0x10, ux, uy, uz)   -- up
    v(0x20, fx, fy, fz)   -- at (куда смотрим)
    v(0x30, px, py, pz)   -- pos (позиция камеры)
end

-- =====================================================================
--  v1.15.1: владение камерой слежки через ШТАТНЫЙ механизм игры:
--  CCamera::TakeControlNoEntity (0x50C8B0) с приоритетом СКРИПТА
--  (whoIsInControl = 1). Код игры «2» после этого самой игрой
--  отклоняется (guard в CCamera::TakeControl: who==2 при cur==1 —
--  выйти) — игра и скрипт больше не дергают камеру в разные стороны,
--  а именно эта борьба давала рывки камеры, когда цель едет в машине.
--  При выходе из слежки — CCamera::Restore (0x50B930) возвращает
--  камеру игре.
-- =====================================================================
local GRND_CAMAPI = { ffi = nil, take = nil, restore = nil, tried = false }

local function grndCamApi()
    if GRND_CAMAPI.tried then return GRND_CAMAPI end
    GRND_CAMAPI.tried = true
    local ok, ffi = pcall(require, "ffi")
    if not ok or type(ffi) ~= "table" or not ffi.cast then return GRND_CAMAPI end
    GRND_CAMAPI.ffi = ffi
    pcall(function()
        GRND_CAMAPI.take = ffi.cast(
            "void(__thiscall*)(void*, const void*, short, int)", 0x50C8B0)
        GRND_CAMAPI.restore = ffi.cast(
            "void(__thiscall*)(void*)", 0x50B930)
    end)
    return GRND_CAMAPI
end

-- Забрать камеру в FIXED-режим скрипта (JUMPCUT, без плавного перехода).
-- point — куда смотрим. Возвращает false, если FFI недоступен (тогда
-- работает старый механизм прямой записи памяти).
function grndSpecTakeCam(x, y, z)
    local A = grndCamApi()
    if not (A.take and A.ffi and A.ffi.new) then return false end
    local ok = pcall(function()
        local ffi = A.ffi
        local vec = ffi.new("float[3]", { x or 0, y or 0, z or 0 })
        -- 2 = SWITCHTYPE_JUMPCUT; 1 = управление СКРИПТОМ (приоритет)
        A.take(ffi.cast("void*", 0xB6F028), ffi.cast("const void*", vec), 2, 1)
    end)
    return ok and true or false
end

function grndSpecRestoreCam()
    local A = grndCamApi()
    if not (A.restore and A.ffi and A.ffi.cast) then return false end
    local ok = pcall(A.restore, A.ffi.cast("void*", 0xB6F028))
    return ok and true or false
end

-- =====================================================================
--  v1.11.35: камера слежки через ШТАТНЫЙ игровой механизм «скриптовой
--  фиксированной камеры» (так работают CLEO-опкоды 015F/0160).
--  Ничего не замораживаем и не патчим: зовём родные функции
--    CCamera::TakeControlNoEntity   = 0x50C8B0
--    CCamera::SetCamPositionForFixedMode = 0x50BEC0
--    CCamera::Restore               = 0x50B930
--  через FFI и дублируем те же поля прямой записью. Фейды, вход в
--  слежку и вывод на экран остаются полностью штатными.
-- =====================================================================
GRND_CAM_FIXED = { fns = nil, src = nil, up = nil, tgt = nil,
    called = false, reason = "" }

-- v1.11.39: камера слежки на этой сборке — режим MODE_FOLLOWPED (md=4,
-- wc=1): игра сама следует за целью и игнорирует поля фиксированной
-- камеры. Поэтому:
--   зум колесом   -> пед-зум игры (0xB6F0C8/CC/D0/D4/D8),
--   поворот/высота-> смещение точки взгляда вокруг цели (без ломания
--                    самой слежки).
-- Оригинальный зум сохраняем при входе и возвращаем при выходе.
GRND_ZOOM_SAVED = nil

function grndCamZoomRestore()
    local s = GRND_ZOOM_SAVED
    GRND_ZOOM_SAVED = nil
    local MM = grndCamMem()
    if not MM or not MM.w32 or type(s) ~= "table" then return end
    local C = 0xB6F028
    local function wr(off, v)
        if type(v) == "number" then pcall(MM.w32, C + off, v) end
    end
    wr(0xC8, s.nPedZoom)
    wr(0xCC, s.fPedZoomBase)
    wr(0xD0, s.fPedZoomTotal)
    wr(0xD4, s.fPedZoomSmoothed)
    wr(0xD8, s.fPedZoomValueScript)
end

-- v1.11.44: ПРАВИЛЬНОЕ чтение координат сущности. Раньше читал
-- CEntity+0x30 — а там лежит m_nLodIndex (мусор), поэтому камера
-- орбитала «в небе». Позиция сущности: если есть матрица
-- (CPlaceable+0x14 = CMatrixLink*) — в ней (см. эталон
-- CPlaceable::GetPosition), иначе — в m_placement (+0x04).
-- v1.14.44: normalize MoonLoader's (found, handle) return values.
function grndSpecApiHandle(fn, id)
    if type(fn) ~= "function" then return nil end
    local ok, found, handle = pcall(fn, id)
    if not ok or found == false then return nil end
    local h = type(found) == "boolean" and handle or found
    if type(h) == "number" and h > 0 then return h end
    return nil
end

function grndSpecVehicle(S, id, ped)
    local car
    if ped and type(isCharInAnyCar) == "function" then
        local ok, seated = pcall(isCharInAnyCar, ped)
        if ok and seated then
            car = grndSpecApiHandle(storeCarCharIsInNoSave, ped)
        elseif ok then
            return nil -- do not reuse a stale remote vehicle ID after exiting
        end
    end
    if not car and S and type(S.getVehicleId) == "function" then
        local ok, vid = pcall(S.getVehicleId, id)
        if ok and type(vid) == "number" and vid >= 0 and vid < 2000 then
            car = grndSpecApiHandle(sampGetCarHandleBySampVehicleId, vid)
        end
    end
    if car and type(doesVehicleExist) == "function" then
        local ok, exists = pcall(doesVehicleExist, car)
        if not ok or not exists then return nil end
    end
    return car
end

-- =====================================================================
--  v1.15.0: УМНАЯ СЛЕЖКА — сама подстраивается под состояние цели:
--  бег/ходьба, машина, мотоцикл, лодка, вертолёт, самолёт, вода.
--  Параметры: extra  — на сколько отдаляться от базовой дистанции;
--  speedF/speedCap  — авто-отдаление по скорости (м на м/с, потолок);
--  aimH             — куда целимся (высота над точкой цели);
--  vRate            — как плавно догоняем цель по высоте;
--  pitch            — комфортный наклон орбиты (рад), к нему камера
--                     сама приходит, пока игрок не крутит камеру.
--  Зум колесом (2–30 м) при этом НЕ трогается — пользователь всегда
--  может отдалиться/приблизиться вручную.
-- =====================================================================
local GRND_SPEC_PLANES = { [460]=true, [476]=true, [511]=true, [512]=true,
    [513]=true, [519]=true, [520]=true, [553]=true, [577]=true, [592]=true,
    [593]=true }
local GRND_SPEC_HELIS = { [417]=true, [425]=true, [447]=true, [469]=true,
    [487]=true, [488]=true, [497]=true, [548]=true, [563]=true }
local GRND_SPEC_BOATS = { [430]=true, [446]=true, [452]=true, [453]=true,
    [454]=true, [472]=true, [473]=true, [484]=true, [493]=true, [595]=true }
local GRND_SPEC_BIKES = { [448]=true, [461]=true, [462]=true, [463]=true,
    [468]=true, [481]=true, [509]=true, [510]=true, [521]=true, [522]=true,
    [523]=true, [581]=true, [586]=true }

function grndSpecSmartState(S, inVehicle, vehicle, ped)
    local st = { state = "foot", extra = 0, speedF = 0.12, speedCap = 2.5,
                 aimH = 1.0, vRate = 14, pitch = 0.50 }
    -- скорость цели (м/с): по транспорту — штатный getCarSpeed, иначе —
    -- оценка по смещению позиции (S.camSpeedEst, считается в followApply)
    local speed = tonumber(S.camSpeedEst) or 0
    if inVehicle and vehicle then
        if S.camProfileVehicle ~= vehicle then
            S.camProfileVehicle = vehicle
            S.camVehicleModel = nil
            if type(getCarModel) == "function" then
                local okM, model = pcall(getCarModel, vehicle)
                if okM then S.camVehicleModel = model end
            end
        end
        if type(getCarSpeed) == "function" then
            local okS, v = pcall(getCarSpeed, vehicle)
            if okS and tonumber(v) then speed = math.max(speed, tonumber(v)) end
        end
        local model = S.camVehicleModel
        if model and GRND_SPEC_HELIS[model] then
            st.state, st.extra, st.aimH, st.vRate, st.pitch =
                "heli", 8.0, 1.3, 8, 0.30
            st.speedF, st.speedCap = 0.45, 16
        elseif model and GRND_SPEC_PLANES[model] then
            st.state, st.extra, st.aimH, st.vRate, st.pitch =
                "plane", 12.0, 1.4, 6, 0.24
            st.speedF, st.speedCap = 0.55, 22
        elseif model and GRND_SPEC_BOATS[model] then
            st.state, st.extra, st.aimH, st.vRate, st.pitch =
                "boat", 5.0, 0.9, 7, 0.38
            st.speedF, st.speedCap = 0.35, 12
        elseif model and GRND_SPEC_BIKES[model] then
            st.state, st.extra, st.aimH, st.vRate, st.pitch =
                "bike", -1.0, 0.9, 12, 0.42
            st.speedF, st.speedCap = 0.25, 8
        else
            st.state, st.extra, st.aimH, st.vRate, st.pitch =
                "car", 0.5, 0.65, 12, 0.42
            st.speedF, st.speedCap = 0.30, 10
        end
    else
        S.camProfileVehicle = nil
        local inWater = false
        if ped and type(isCharInWater) == "function" then
            local okW, w = pcall(isCharInWater, ped)
            if okW and w then inWater = true end
        end
        if inWater then
            st.state, st.extra, st.aimH, st.vRate, st.pitch =
                "swim", 1.0, 1.15, 7, 0.35
            st.speedF, st.speedCap = 0.10, 2.0
        end
    end
    -- авто-отдаление по скорости (снаружи сглаживается через camExtra)
    st.speed = math.max(0, speed)
    st.extra = st.extra + math.min(st.speedCap, st.speed * st.speedF)
    -- заголовок движения цели (рад) — для авто-разворота камеры за спину
    local heading = nil
    if inVehicle and vehicle and type(getCarHeading) == "function" then
        local okH, h = pcall(getCarHeading, vehicle)
        if okH and tonumber(h) then heading = math.rad(tonumber(h)) end
    elseif ped and type(getCharHeading) == "function" then
        local okH, h = pcall(getCharHeading, ped)
        if okH and tonumber(h) then heading = math.rad(tonumber(h)) end
    end
    if heading then S.camHeadingRad = heading end
    return st
end

function grndCamEntPos(MM, t)
    if not MM or not MM.r32 or not MM.rf then return nil end
    local okm, mp = pcall(MM.r32, t + 0x14)
    if okm and type(mp) == "number" and mp > 0x10000 and mp < 0x78000000 then
        local okx, x = pcall(MM.rf, mp + 0x30)
        local oky, y = pcall(MM.rf, mp + 0x34)
        local okz, z = pcall(MM.rf, mp + 0x38)
        if okx and oky and okz then return x, y, z end
    end
    local okx, x = pcall(MM.rf, t + 0x04)
    local oky, y = pcall(MM.rf, t + 0x08)
    local okz, z = pcall(MM.rf, t + 0x0C)
    if okx and oky and okz then return x, y, z end
    return nil
end

-- =====================================================================
--  v1.14.58: КАМЕРА СЛЕЖКИ НЕ УХОДИТ ЗА СТЕНУ.
--  Между точкой взгляда цели и позицией камеры проверяем линию видимости
--  (здания + динамические объекты; транспорт, педы и частицы не трогаем —
--  иначе камера «прыгала» бы от любой машины). Если между ними геометрия,
--  камера подтягивается к стене по тому же направлению взгляда, поэтому
--  цель остаётся в кадре.
--  v1.14.59: обход стен всегда включён; камера НИКОГДА не ставится за
--  стеной (даже если стена ближе служебного минимума — раньше в этом
--  случае её заталкивало внутрь геометрии, отсюда «залезание в текстуры»);
--  точка удара разбирается в любом виде ответа processLineOfSight, а при
--  мусорных координатах ищется бинарным поиском по лучу.
-- =====================================================================
GRND_CAM_COLLIDE_MIN = 1.1     -- полезный минимум до цели (совместимость)
GRND_CAM_COLLIDE_MARGIN = 0.55 -- отступ камеры от стены (не резать текстуры)
GRND_CAM_COLLIDE_FLOOR = 0.25  -- абсолютный минимум до точки взгляда

-- Точка пересечения линии видимости с геометрией (nil — путь чистый)
function grndCamLosPoint(ax, ay, az, bx, by, bz)
    if type(processLineOfSight) ~= "function" then return nil end
    local function cast(x1, y1, z1, x2, y2, z2)
        local ok, hit, a, b, c = pcall(processLineOfSight,
            x1, y1, z1, x2, y2, z2,
            true,   -- checkSolid: постройки/стены (в т.ч. интерьеры)
            false,  -- car
            false,  -- ped
            true,   -- object
            false,  -- particle
            false,  -- seeThrough
            false,  -- ignoreSomeObjects: v1.15.1 — проверяем ВСЮ геометрию
                    -- (и объекты «для камеры» тоже): в пропущенных объектах
                    -- (заборы, решётки, ширмы) камера и залезала в текстуры
            false)  -- shotThrough
        if not ok or not hit then return false end
        return true, a, b, c
    end
    local function num(v)
        local n = tonumber(v)
        return (n and n == n) and n or nil
    end
    -- Обёртки processLineOfSight иногда отдают мусор: принимаем только
    -- координаты в разумных пределах карты.
    local function sane(x, y, z)
        if not (x and y and z) then return false end
        if math.abs(x) > 20000 or math.abs(y) > 20000 or math.abs(z) > 20000 then return false end
        if x == 0 and y == 0 and z == 0 then return false end
        return true
    end
    local hit, a, b, c = cast(ax, ay, az, bx, by, bz)
    if not hit then return nil end
    -- разные обёртки отдают точку по-разному:
    -- (hit, {x=,y=,z=,...}) / (hit, {x,y,z}) / (hit, x, y, z)
    local x, y, z
    if type(a) == "table" then
        local q = a.pos or a.position or a
        x, y, z = num(q.x) or num(q[1]),
                  num(q.y) or num(q[2]),
                  num(q.z) or num(q[3])
    else
        x, y, z = num(a), num(b), num(c)
    end
    if sane(x, y, z) then return x, y, z end
    -- hit есть, а координаты мусорные: находим границу бинарным поиском
    -- по лучу (только факт пересечения — без рекурсии в cast)
    local lo, hi = 0.0, 1.0
    local dx, dy, dz = bx - ax, by - ay, bz - az
    -- v1.19.57: 6 шагов вместо 10 — точность ~1.5% длины луча (на 7 м это
    -- ~10 см), а вызовов processLineOfSight на треть меньше: именно они и
    -- подвешивали кадр в слежке у стены.
    for _ = 1, 6 do
        local mid = (lo + hi) * 0.5
        local h2 = cast(ax, ay, az, ax + dx * mid, ay + dy * mid, az + dz * mid)
        if h2 then hi = mid else lo = mid end
    end
    return ax + dx * lo, ay + dy * lo, az + dz * lo
end

-- Подтянуть камеру (px,py,pz) к стене на пути от точки взгляда (ax,ay,az).
-- Возвращает новую позицию и признак «было препятствие».
-- v1.14.59: камеру НИКОГДА не ставим за стеной. Раньше минимум (1.1 м)
-- выталкивал камеру СКВОЗЬ близкую стену внутрь текстуры; теперь она
-- всегда остаётся перед геометрией (отступ 0.55 м, в тесноте — 0.3 м).
function grndCamAvoidWalls(ax,ay,az,px,py,pz,minDist,shoulders)
    local dx,dy,dz=px-ax,py-ay,pz-az
    local dist=math.sqrt(dx*dx+dy*dy+dz*dz)
    if dist<0.001 then return px,py,pz,false end
    local ux,uy,uz=dx/dist,dy/dist,dz/dist
    local horizontal=math.sqrt(ux*ux+uy*uy)
    local rx,ry=1,0
    if horizontal>0.001 then rx,ry=-uy/horizontal,ux/horizontal end
    local allowed=dist;local hit=false
    -- Centre and two parallel shoulder rays: no recursive recasts toward an
    -- already clipped endpoint; small lateral clearance protects camera corners.
    -- v1.19.57: центральный луч — всегда, плечевые — только когда центральный
    -- упёрся в геометрию или раз в три тика: каждый луч это до семи вызовов
    -- processLineOfSight, и в слежке они съедали кадр.
    local rays = { 0 }
    if shoulders ~= false then rays[#rays + 1] = -0.18; rays[#rays + 1] = 0.18 end
    for _,offset in ipairs(rays) do
        local sx,sy=ax+rx*offset,ay+ry*offset
        local hx,hy,hz=grndCamLosPoint(sx,sy,az,px+rx*offset,py+ry*offset,pz)
        if hx then
            local along=(hx-sx)*ux+(hy-sy)*uy+(hz-az)*uz
            local cross2=(hx-sx-ux*along)^2+(hy-sy-uy*along)^2+(hz-az-uz*along)^2
            if along>=0 and along<=dist+0.05 and cross2<0.09 then
                local margin=math.min(0.45,along*0.5)
                allowed=math.min(allowed,math.max(0,along-margin));hit=true
            end
        end
    end
    return ax+ux*allowed,ay+uy*allowed,az+uz*allowed,hit
end
function grndCamClearance(S,desired,safe,hit,now,dt)
    safe=math.max(0,math.min(desired,safe))
    if S.value==nil then S.value=safe end
    if hit and (not S.hit or safe<S.value-0.03) then S.holdUntil=now+0.18 end
    S.hit=hit
    if safe<S.value then
        S.value=safe -- collision safety: never smooth through solid geometry
    elseif now>=(S.holdUntil or 0) and safe-S.value>0.025 then
        S.value=S.value+(safe-S.value)*(1-math.exp(-3*math.max(0,math.min(0.1,dt))))
    end
    S.value=math.min(S.value,safe,desired)
    return S.value
end

-- v1.15.0: grndCamFovRestore удалён — слежка больше не трогает FOV.

function grndCamFollowApply(S, now)
    local MM = grndCamMem()
    if not MM or not MM.rf or not MM.wf or not MM.w32 then return end
    local C = 0xB6F028
    local function goodEnt(e)
        return type(e) == "number" and e > 0x10000 and e < 0x78000000
    end
    local function goodXYZ(x, y, z)
        if type(x) ~= "number" or type(y) ~= "number" or type(z) ~= "number" then return false end
        if x ~= x or y ~= y or z ~= z then return false end
        if math.abs(x) > 20000 or math.abs(y) > 20000
            or math.abs(z) > 20000 then return false end
        if x == 0 and y == 0 and z == 0 then return false end
        return true
    end
    -- v1.11.50: проверка «указатель лежит внутри пула» — единственный
    -- надёжный способ убедиться, что это реально пед/транспорт в этой
    -- сборке (samp-функции здесь отдают мусор).
    local function inPool(MM, ptrVar, stride, e)
        if not goodEnt(e) then return false end
        local okp, pool = pcall(MM.r32, ptrVar)
        if not okp or not goodEnt(pool) then return false end
        local oko, objs = pcall(MM.r32, pool)
        local oks, sz = pcall(MM.r32, pool + 8)
        if not oko or not oks then return false end
        if type(sz) == "number" and sz < 0 then sz = sz + 4294967296 end
        if type(objs) ~= "number" or objs <= 0x10000
            or objs >= 0x78000000 or type(sz) ~= "number"
            or sz <= 0 or sz > 4096 then return false end
        return e >= objs and e < objs + sz * stride
    end
    -- v1.11.47/50: если сущность — ПЕД, сидящий в транспорте, его
    -- собственные координаты НЕ обновляются (матрица сидящего педа
    -- пустеет, позиция застывает в точке посадки). Берём координаты его
    -- машины (CPed+0x58C = m_pVehicle, сверено с эталонной структурой).
    -- Указатель машины ОБЯЗАТЕЛЬНО валидируется пулом транспортов —
    -- иначе +0x58C может содержать мусор. Шаг CVehicle = 0x5A0
    -- (сверено с эталонной структурой).
    local function smartPos(MM, ent)
        local x, y, z = grndCamEntPos(MM, ent)
        if MM.r8 then
            local okb, tb = pcall(MM.r8, ent + 0x36)
            if okb and type(tb) == "number" then
                if tb < 0 then tb = tb + 256 end
                if tb % 8 == 3 then -- ENTITY_TYPE_PED
                    local okv, veh = pcall(MM.r32, ent + 0x58C)
                    if okv and goodEnt(veh)
                        and inPool(MM, 0xB74494, 0x5A0, veh) then
                        local vx, vy, vz = grndCamEntPos(MM, veh)
                        if goodXYZ(vx, vy, vz) then
                            return vx, vy, vz
                        end
                    end
                end
            end
        end
        return x, y, z
    end
    -- v1.11.46: координаты цели берём из НЕСКОЛЬКИХ источников — когда
    -- цель в машине, слежка может целиться в транспорт, крепить камеру к
    -- нему или вообще временно сбрасывать m_pTargetEntity.
    -- v1.11.48: диагностика — что видно на каждой ступени (/camdbg)
    local DB = { t = now or os.clock() }
    S.camDbg = DB
    local function tbyte(e)
        if not MM.r8 or not goodEnt(e) then return nil end
        local okb, b = pcall(MM.r8, e + 0x36)
        if not okb or type(b) ~= "number" then return nil end
        if b < 0 then b = b + 256 end
        return b % 8
    end
    local localPedPtr = nil
    if type(getCharPointer) == "function" and PLAYER_PED then
        local okP, ptr = pcall(getCharPointer, PLAYER_PED)
        if okP and type(ptr) == "number" then localPedPtr = ptr end
    end
    if not localPedPtr and MM.r32 then
        local okP, ptr = pcall(MM.r32, 0xB6F5F0)
        if okP and type(ptr) == "number" then localPedPtr = ptr end
    end

    local tx, ty, tz
    local srcUsed = "none"
    local inVehicle = false
    local pedHandle = S.camPed
    local vehicle = S.camVehicle
    local okP, x, y, z
    if vehicle and type(getCarCoordinates) == "function" then
        okP, x, y, z = pcall(getCarCoordinates, vehicle)
        inVehicle = okP and goodXYZ(x, y, z) or false
    elseif pedHandle and type(getCharCoordinates) == "function" then
        okP, x, y, z = pcall(getCharCoordinates, pedHandle)
    end
    if okP and goodXYZ(x, y, z) then
        tx, ty, tz = x, y, z
        srcUsed = inVehicle and "vehicle-api" or "ped-api"
    end
    -- v1.15.0: умная слежка — параметры камеры по состоянию цели
    -- (бег/машина/мото/лодка/вертолёт/самолёт/вода) + авто-отдаление
    -- по скорости. Зум колесом пользователя не перекрывается.
    local smart
    if S.camAfk and not inVehicle and not vehicle and not S.camPed
        and type(S.camSmart)=="table" then
        local prev=S.camSmart
        local speedF=tonumber(prev.speedF) or 0
        local speedCap=tonumber(prev.speedCap) or 0
        local prevSpeed=tonumber(prev.speed) or 0
        smart={
            state=prev.state or "foot",
            extra=(tonumber(prev.extra) or 0)-math.min(speedCap,prevSpeed*speedF),
            speedF=speedF,speedCap=speedCap,speed=0,
            aimH=tonumber(prev.aimH) or 1.0,
            vRate=tonumber(prev.vRate) or 14,
            pitch=tonumber(prev.pitch) or 0.50,
        }
    else
        smart=grndSpecSmartState(S,inVehicle,vehicle,S.camPed)
    end
    local extra, aimHeight, verticalRate = smart.extra, smart.aimH, smart.vRate
    S.camSmart = smart
    local blend = 1 - math.exp(-3 * (S.camDt or 1 / 60)) -- v1.15.1: мягче
    if not S.camUiBlocked or S.camExtra==nil then
        S.camExtra = (S.camExtra or extra) + (extra - (S.camExtra or extra)) * blend
        S.camAimHeight = (S.camAimHeight or aimHeight)
            + (aimHeight - (S.camAimHeight or aimHeight)) * blend
    end
    -- 1) m_pTargetEntity (исключаем локального игрока)
    local ok, t = pcall(MM.r32, C + 0x958)
    if not ok then t = nil end
    if localPedPtr and t == localPedPtr then t = nil end
    DB.tgt, DB.ttype = t, tbyte(t)
    if not goodXYZ(tx, ty, tz) and goodEnt(t) then
        if MM.r32 then
            local okv, v1 = pcall(MM.r32, t + 0x58C)
            if okv then
                DB.tveh = v1
                DB.tvehOk = inPool(MM, 0xB74494, 0x5A0, v1)
            end
        end
        tx, ty, tz = smartPos(MM, t)
        if goodXYZ(tx, ty, tz) then srcUsed = "tgt" end
    end
    if not goodXYZ(tx, ty, tz) then
        -- 2) m_pAttachedEntity (камера, прицепленная к транспорту цели)
        tx, ty, tz = nil, nil, nil
        local ok2, t2 = pcall(MM.r32, C + 0x95C)
        if not ok2 then t2 = nil end
        if localPedPtr and t2 == localPedPtr then t2 = nil end
        DB.att = t2
        if goodEnt(t2) then
            tx, ty, tz = smartPos(MM, t2)
            if goodXYZ(tx, ty, tz) then srcUsed = "att" end
        end
    end
    if not goodXYZ(tx, ty, tz) then
        -- 3) пед цели слежки (S.camPed; строго исключаем локального админа)
        tx, ty, tz = nil, nil, nil
        local ped = S.camPed
        if (localPedPtr and ped == localPedPtr) or ped == PLAYER_PED then
            ped = nil
        end
        DB.ped, DB.ptype = ped, tbyte(ped)
        if goodEnt(ped) then
            DB.veh = nil
            if MM.r32 then
                local okv, v0 = pcall(MM.r32, ped + 0x58C)
                if okv then DB.veh = v0 end
            end
            tx, ty, tz = smartPos(MM, ped)
            if goodXYZ(tx, ty, tz) then srcUsed = "ped" end
        elseif type(ped) == "number" and ped > 0
            and ped < 0x40000 and ped ~= PLAYER_PED then
            local idx = math.floor(ped / 256)
            if idx > 0 and idx < 1000 then
                local okp, pool = pcall(MM.r32, 0xB74490)
                if okp and goodEnt(pool) then
                    local oko, objs = pcall(MM.r32, pool)
                    if oko and goodEnt(objs) then
                        tx, ty, tz = smartPos(MM,
                            objs + idx * 0x7C4)
                        if goodXYZ(tx, ty, tz) then
                            srcUsed = "pool"
                        end
                    end
                end
            end
        end
    end
    if goodXYZ(tx, ty, tz) then
        -- v1.11.51: счётчик суммарного смещения принятых координат —
        -- если цель «едет», а он стоит на месте, координаты мёртвые
        local pv = S.camPrevXYZ
        if pv then
            local dd = math.sqrt((tx - pv[1]) ^ 2
                + (ty - pv[2]) ^ 2 + (tz - pv[3]) ^ 2)
            if dd > 0.001 then S.camMoved = (S.camMoved or 0) + dd end
            -- v1.15.0: оценка скорости цели (м/с) для умной слежки
            local inst = dd / math.max(S.camDt or 1 / 60, 0.001)
            if inst > 150.0 then inst = 150.0 end
            S.camSpeedEst = (S.camSpeedEst or inst)
                + (inst - (S.camSpeedEst or inst))
                * math.min(1, (S.camDt or 1 / 60) * 2.5) -- v1.15.1: мягче
        end
        S.camPrevXYZ = { tx, ty, tz }
        S.camLastTgt = { x = tx, y = ty, z = tz, t = now or os.clock() }
        S.camFailT = nil
        DB.src = srcUsed
        DB.xyz = ("%d %d %d"):format(tx, ty, tz)
        S.camNok = (S.camNok or 0) + 1
    else
        -- 4) последняя известная позиция цели: при смерти/респавне/интерьере держим камеру на ней!
        local lt = S.camLastTgt
        if lt and goodXYZ(lt.x, lt.y, lt.z) then
            tx, ty, tz = lt.x, lt.y, lt.z
            DB.src = "cache"
        else
            DB.src = "none"
            S.camNfail = (S.camNfail or 0) + 1
            S.camFailT = S.camFailT or (now or os.clock())
            return
        end
    end
    -- Мгновенно позиционируем камеру на цели (без лерпа из неба)
    local sm = S.camTgtSmooth
    if sm then
        local jumpDist = math.sqrt((tx - sm.x)^2 + (ty - sm.y)^2 + (tz - sm.z)^2)
        if jumpDist > 25.0 then
            sm = { x = tx, y = ty, z = tz }
            S.camWallD=nil;S.camWallFilter=nil;S.camSpeedEst=0
        else
            local alpha = 1 - math.exp(-10 * (S.camDt or 1 / 60)) -- v1.15.1: мягче
            sm.x = sm.x + (tx - sm.x) * alpha
            sm.y = sm.y + (ty - sm.y) * alpha
            local alphaZ = 1 - math.exp(-verticalRate * (S.camDt or 1 / 60))
            sm.z = sm.z + (tz - sm.z) * alphaZ
        end
    else
        sm = { x = tx, y = ty, z = tz }
    end
    S.camTgtSmooth = sm
    tx, ty, tz = sm.x, sm.y, sm.z
    -- v1.11.43: НИЧЕГО не замораживаем (в этой сборке патч кода, похоже,
    -- попадает не туда и подбрасывает персонажа). Вместо этого переводим
    -- активную камеру в режим FIXED (0xF) и каждый кадр кормим её нашей
    -- орбитальной позицией — игра сама её обрабатывает штатно.
    local a = S.camAngle or 0
    local d = math.max(2, (S.camDistCur or S.camDist or 10.0) + (S.camExtra or 0))
    -- v1.11.46: орбита по СФЕРЕ вокруг цели — угол наклона (шаг
    -- вверх/вниз) теперь угловой, поэтому работает на любой дистанции.
    local p = S.camPitch or 0.35
    local cp = math.cos(p)
    local px = tx + math.sin(a) * cp * d
    local py = ty - math.cos(a) * cp * d
    local pz = tz + math.sin(p) * d + 0.6
    -- v1.11.57: у транспорта «ноль» ниже, чем у педа — целимся не в
    -- крышу, а в середину корпуса
    local aimZ = tz + (S.camAimHeight or 1.0)
    -- v1.14.58: обходим стены и интерьеры. Камера слежки не должна уходить
    -- за геометрию: если между целью и камерой стена — камера встаёт перед
    -- ней (внутри комнаты), сохраняя выбранный ракурс.
    -- v1.14.59: обход ВСЕГДА включён (тумблера больше нет). Разрешённая
    -- дистанция сглаживается: к стене камера подходит быстро, а отходит
    -- плавно — раньше она прыгала (дёргалась) на границе «стена/нет стены».
    do
        local orbD = math.sqrt((px - tx) ^ 2 + (py - ty) ^ 2 + (pz - aimZ) ^ 2)
        local wantD = orbD
        S.camRayPhase = ((S.camRayPhase or 0) + 1) % 3
        local nx, ny, nz, hitWall = grndCamAvoidWalls(
            tx, ty, aimZ, px, py, pz, GRND_CAM_COLLIDE_MIN,
            S.camRayPhase == 0 or S.camWallHit == true)
        if hitWall then
            local ddx, ddy, ddz = nx - tx, ny - ty, nz - aimZ
            wantD = math.sqrt(ddx * ddx + ddy * ddy + ddz * ddz)
            S.camWallHit = true
        else
            S.camWallHit = nil
        end
        S.camWallFilter=S.camWallFilter or {}
        local curD=grndCamClearance(S.camWallFilter,orbD,wantD,hitWall,now or grndCamNow(),S.camDt or 1/60)
        S.camWallD=curD
        if curD < orbD - 0.001 then
            local s = curD / math.max(orbD, 0.001)
            px = tx + (px - tx) * s
            py = ty + (py - ty) * s
            pz = aimZ + (pz - aimZ) * s
        end
    end
    local function wv(b, off, x, y, z)
        pcall(MM.wf, b + off, x)
        pcall(MM.wf, b + off + 4, y)
        pcall(MM.wf, b + off + 8, z)
    end
    -- v1.11.54: читаем режим АКТИВНОЙ камеры ДО нашей записи. Если он
    -- не 0xF (FIXED) — значит между нашими кадрами кто-то (игра/самп,
    -- когда цель в транспорте) уводит камеру в свой режим, и наша
    -- перезапись проигрывает гонку.
    if MM.r32 then
        local aci = 0
        if MM.r8 then
            local oka, acb = pcall(MM.r8, C + 0x59)
            if oka and type(acb) == "number" then
                if acb < 0 then acb = acb + 256 end
                aci = (acb % 256) % 3
            end
        end
        local okpm, pm = pcall(MM.r32, C + 0x174 + aci * 0x238 + 0x0C)
        if okpm and type(pm) == "number" then
            pm=pm%65536 -- camera mode is a 16-bit field
            DB.preMode = pm
            if pm == 0xF then
                S.camHeld = (S.camHeld or 0) + 1
            else
                S.camLost = (S.camLost or 0) + 1
            end
        end
        local okmg, mg = pcall(MM.r32, C + 0xC38)
        if okmg and type(mg) == "number" then
            DB.preMTG = mg % 65536
        end
    end
    -- v1.11.53: пишем режим и векторы ВО ВСЕ ТРИ CCam. Когда цель в
    -- машине, слежка периодически заново переключает камеру (в т.ч.
    -- между CCam) — так любая из них уже готова нашим орбитальным
    -- положением.
    for ci2 = 0, 2 do
        local base = C + 0x174 + ci2 * 0x238
        grndCamWriteMode(MM, base + 0x0C, 0xF) -- preserve adjacent camera flags
        wv(base, 0x160, px, py, pz)        -- m_vecCamFixedModeSource
        wv(base, 0x154, tx, ty, aimZ)      -- m_vecCamFixedModeVector
        wv(base, 0x16C, 0, 0, 1)           -- m_vecCamFixedModeUpOffSet
    end
    -- v1.11.53: игра каждый кадр ровняет режим активной камеры по
    -- m_nModeToGoTo (+0xC38, short). Когда слежка пересаживает цель в
    -- машину, она заново «берёт» камеру и уводит режим в свой. Держим
    -- здесь FIXED (верхние 16 бит — поле фейда — НЕ трогаем).
    local okg, gv = pcall(MM.r32, C + 0xC38)
    if okg and type(gv) == "number" then
        if gv < 0 then gv = gv + 4294967296 end
        local hi = math.floor(gv / 65536) * 65536
        pcall(MM.w32, C + 0xC38, hi + 0xF)
    end
    -- v1.11.55/56: когда цель в машине, слежка периодически заново
    -- берёт камеру и стартует ПЛАВНЫЙ ПЕРЕХОД (интерполяцию). Пока
    -- переход активен, игра гоняет камеру по нему и НЕ обрабатывает наш
    -- FIXED. Гасим флаги перехода (смещения сверены с эталонной
    -- CCamera; фейды НЕ трогаем). ВАЖНО (фикс 1.11.56): ВХОД в слежку
    -- сам использует эти переходы — если их гасить в момент входа,
    -- персонаж улетает в небо. Поэтому гасим ТОЛЬКО когда:
    --  * вход уже завершился (>=2.5 с с начала), И
    --  * за последние 3 с был повторный захват камеры (цель в машине).
    if DB.preMode ~= nil and DB.preMode ~= 0xF then
        S.camReTakeAt = now or os.clock()
    end
    -- v1.15.1: и главный «забор» камеры — штатный TakeControlNoEntity
    -- с приоритетом скрипта (who=1): после этого игровые повторные
    -- захваты (who=2) отклоняются САМОЙ ИГРОЙ (guard в TakeControl) —
    -- камера перестаёт дёргаться, когда цель едет в машине.
    if not S.camTakeDone and (not S.camTakeTryAt or now-S.camTakeTryAt>=0.5) then
        S.camTakeTryAt=now
        if grndSpecTakeCam(tx, ty, aimZ) then S.camTaken=true;S.camTakeDone=true end
    elseif S.camTaken and MM.r32 then
        local okw, wv2 = pcall(MM.r32, C + 0xB0)
        local who = (okw and type(wv2) == "number") and wv2 or 1
        if who ~= 1 then
            S.camReTakeAt = now or os.clock()
            local trT = S.camRetakeT or 0
            if now - trT > 0.25 then
                S.camRetakeT = now
                grndSpecTakeCam(tx, ty, aimZ)
            end
        end
    end
    local nowK = now or os.clock()
    local ageK = nowK - (S.camActiveSince or nowK)
    local canKill = ageK > 2.5 and S.camReTakeAt
        and nowK - (S.camReTakeAt or 0) < 3.0
    if canKill and MM.w8 then
        pcall(MM.w8, C + 0x3A, 0) -- m_bWaitForInterpolToFinish
        pcall(MM.w8, C + 0x32, 0) -- m_bStartInterScript
        pcall(MM.w8, C + 0x33, 0) -- m_bStartingSpline
        pcall(MM.w8, C + 0x2A, 0) -- m_bJust_Switched
        pcall(MM.w8, C + 0x58, 0) -- v1.15.1: m_bTransitionState
    end
    -- Дубль на уровне CCamera (страховка)
    wv(C, 0x86C, px, py, pz)               -- m_vecFixedModeSource
    wv(C, 0x854, tx, ty, aimZ)             -- m_vecFixedModeVector
    wv(C, 0x878, 0, 0, 1)                  -- m_vecFixedModeUpOffSet
    -- v1.15.0: FOV из слежки убран — игра в режиме FIXED сама держит свой
    -- угол обзора (70). FOV-режим теперь живёт только для МОЕГО персонажа
    -- (Настройки → Дистанция камеры, см. grndCamFovApply).
    S.camAppliedMode = 0xF
end

function grndSpecCamControl(S, now)
    local uiBlocked=grndCamWindowsOpen()
    S.camUiBlocked=uiBlocked
    local clock = now
    if type(getGameTimer) == "function" then
        local okT, ms = pcall(getGameTimer)
        if okT and type(ms) == "number" then clock = ms / 1000 end
    end
    if S.camFrameAt==clock then return end -- one follow update per game tick
    S.camDt = math.max(0, math.min(0.1, clock - (S.camFrameAt or (clock - 1 / 60))))
    S.camFrameAt = clock
    -- 2) Наша слежка: гасим нативную, держим нашу камеру
    local active = (GRND_SPEC and GRND_SPEC.active) and true or false
    local tid = active and tonumber(GRND_SPEC.id) or nil
    -- v1.11.21: если слежка нативная и не была перехвачена (GRND_SPEC не
    -- взведён), камеру всё равно ведём по цели из панели рекона — иначе
    -- управление камерой «ничего не применяет» на таких заходах
    if not tid and GRND_RC and GRND_RC.show and tonumber(GRND_RC.id) then
        tid = tonumber(GRND_RC.id)
        active = true
    end
    if active and tid then
        grndCamUiEnd(true)
        grndCamDistanceRelease()
        grndCamFovReset()
        grndCamLookRestore()
        if S.ok and not S.calOff and now - (S.calT or 0) > 0.25 then
            S.calT = now
            S.calibrate(tid)
        end
        -- v1.11.60: при смене цели сглаживание позиции сбрасывается —
        -- иначе камера «летела» бы через всю карту к новой цели
        if S.camTgtId ~= tid then
            -- v1.14.58: стартовый ракурс берём из настроек (Рекон → Камера
            -- слежки): по умолчанию камера встаёт за спиной цели, чуть выше
            -- линии её взгляда, на удобной для наблюдения дистанции.
            local d0 = math.max(2.0, math.min(30.0, tonumber(S.camStartDist) or 7.0))
            S.camDist, S.camDistCur = d0, d0
            S.camPitch = math.max(-0.15, math.min(1.35,
                tonumber(S.camStartPitch) or 0.5))
            S.camAngle = tonumber(S.camStartAngle) or 0.0
            S.lastMX, S.lastMY = nil, nil
            S.mouseReady,S.mouseTick=nil,nil
            S.camPed, S.camVehicle = nil, nil
            S.camExtra, S.camAimHeight, S.camProfileVehicle = nil, nil, nil
            S.camActiveSince = now
            S.camTgtId = tid
            S.camTgtSmooth = nil
            S.camWallD = nil;S.camWallFilter=nil -- v1.14.59: сглаживание стены — с нуля
            S.camLastTgt = nil
            S.camPrevXYZ = nil
            S.camSmart = nil          -- v1.15.0: умная слежка — с нуля
            S.camSpeedEst = nil
            S.camHeadingRad = nil
            S.camLastInput = now
        end
        local ped = S.pedOf(tid)
        if ped and ped ~= PLAYER_PED then
            if S.calOff then S.killNative() end
            S.camPed = ped
        else
            ped = nil
            S.camPed = nil
        end
        S.camVehicle = grndSpecVehicle(S, tid, ped)
        if S.camVehicle and S.calOff then S.killNative() end
        local lt0 = S.camLastTgt
        local targetPaused=false
        if type(grndSpecTargetIsPaused)=="function" then
            local okPause,isPaused=pcall(grndSpecTargetIsPaused,tid)
            targetPaused=okPause and isPaused and true or false
        end
        S.camAfk=targetPaused
        local alive0 = ped or S.camVehicle
            or (lt0 and (os.clock() - (lt0.t or 0) < 6.0 or targetPaused))
        if alive0 then
            S.camOn = true
            -- v1.11.19: орбитальная камера слежки. Вращение — мышью
            -- (пока курсор выключен) и стрелками ВЛЕВО/ВПРАВО; высота —
            -- мышью по вертикали; дистанция — колесом (см. WM_WHEEL).
            -- v1.11.58: пока открыт чат/ввод — мышь камеру НЕ крутит
            -- v1.15.2: пока открыто ЛЮБОЕ окно — мышь камеру не крутит
            local dx,dy=grndCamMouseDelta(S,uiBlocked)
            if not uiBlocked and (dx~=0 or dy~=0) then
                S.camLastInput=now
                S.camAngle=(S.camAngle or 0)-dx*0.006
                local curP=S.camPitch or math.atan2((S.camHeight or 2.5)-0.6,S.camDist or 10)
                S.camPitch=math.max(-0.15,math.min(1.35,curP-dy*0.003))
            end
            -- v1.11.58: клавиши камеры не работают, пока открыт чат
            -- v1.15.2: и пока открыто ЛЮБОЕ окно
            if type(isKeyDown) == "function"
                and not uiBlocked then
                local CK = GRND_RC and GRND_RC.camKeys or {}
                local function held(vk)
                    local okK, down = pcall(isKeyDown, vk)
                    return (okK and down) or CK[vk] == true
                end
                local dt = S.camDt
                if held(0x25) then S.camAngle = (S.camAngle or 0) - 1.8 * dt
                    S.camLastInput = now end
                if held(0x27) then S.camAngle = (S.camAngle or 0) + 1.8 * dt
                    S.camLastInput = now end
                if held(0x26) then S.camPitch = math.min(1.35, (S.camPitch or 0.42) + 1.2 * dt)
                    S.camLastInput = now end
                if held(0x28) then S.camPitch = math.max(-0.15, (S.camPitch or 0.42) - 1.2 * dt)
                    S.camLastInput = now end
                if held(0xBB) or held(0x6B) then S.camDist = math.min(30, (S.camDist or 10) + 8 * dt)
                    S.camLastInput = now end
                if held(0xBD) or held(0x6D) then S.camDist = math.max(2, (S.camDist or 10) - 8 * dt)
                    S.camLastInput = now end
            end
            -- v1.15.0: УМНАЯ СЛЕЖКА — авто-ракурс. Пока игрок сам крутит
            -- камеру (мышь/клавиши/колесо — camLastInput), НИЧЕГО не
            -- навязываем. После паузы камера сама:
            --  * подбирает наклон под состояние цели (бег/машина/полёт/вода);
            --  * при быстром движении плавно встаёт за спину цели.
            -- v1.15.2: пока открыто ЛЮБОЕ окно — авто-довороты на паузе,
            -- таймер бездействия сбрасывается (после закрытия окна камера
            -- не дёрнется — подождёт паузу заново).
            if targetPaused then
                -- AFK is stationary: don't let a stale speed estimate auto-orbit
                -- the camera; keep manual mouse/arrow control fully available.
                S.camSpeedEst=0
                if lt0 and type(lt0.x)=="number" and type(lt0.y)=="number" and type(lt0.z)=="number" then
                    S.camPrevXYZ={lt0.x,lt0.y,lt0.z}
                end
                S.camLastInput=now
            end
            if uiBlocked then
                S.camLastInput = now
            else
                local idleT = now - (S.camLastInput or 0)
                if idleT > 3.0 then
                    local smart = S.camSmart
                    if smart and smart.pitch then
                        local cur = S.camPitch or 0.5
                        local k = math.min(1, 0.5 * (S.camDt or 1 / 60))
                        S.camPitch = cur + (smart.pitch - cur) * k
                    end
                end
                if idleT > 4.0 and (S.camSpeedEst or 0) > 3.0 and S.camHeadingRad then
                    local want = -S.camHeadingRad
                    local cur = S.camAngle or 0
                    local diff = want - cur
                    while diff > math.pi do diff = diff - 2 * math.pi end
                    while diff < -math.pi do diff = diff + 2 * math.pi end
                    local k = math.min(1, 0.6 * (S.camDt or 1 / 60))
                    S.camAngle = cur + diff * k
                end
            end
            -- Камера применяется СРАЗУ на цели, без секундного ожидания в небе
            S.camActiveSince = S.camActiveSince or now
            local dT = S.camDist or 10.0
            S.camDistCur = (S.camDistCur or dT)
                + (dT - (S.camDistCur or dT)) * (1 - math.exp(-12 * S.camDt))
            grndCamFollowApply(S, now)
        else
            -- Цель временно не найдена (смерть/респавн/интерьер) — НЕ бросаем камеру в небо!
            local manualExit = (_G.GRND_SPEC and _G.GRND_SPEC.manualExit)
                or (_G.GRND_SPEC_AUTOREF and _G.GRND_SPEC_AUTOREF.manualExit)
            if manualExit and S.camOn then
                grndSpecNativeReleaseCam()
            end
        end
    end
    local manualExitAll = (_G.GRND_SPEC and _G.GRND_SPEC.manualExit)
        or (_G.GRND_SPEC_AUTOREF and _G.GRND_SPEC_AUTOREF.manualExit)
    if S.camOn and (manualExitAll or not active) then
        if manualExitAll then
            grndSpecNativeReleaseCam()
        end
    end
end

function grndSpecNativeTick()
    local S = grndSpecNative
    local now = os.clock()
    if not S.ok then
        -- v1.11.22: камера работает независимо от нативных структур
        grndSpecCamControl(S, now)
        -- первая попытка — сразу, следующие — не чаще раза в 2 секунды
        local lastInit = S.initT
        if lastInit and now - lastInit < 2.0 then return end
        S.initT = now
        -- верификацию запускаем только когда подключены к серверу
        local lid
        if type(sampGetLocalPlayerId) == "function" then
            local ok, l = pcall(sampGetLocalPlayerId)
            if ok and type(l) == "number" then lid = l end
        end
        if type(lid) == "number" and type(sampGetPlayerNickname) == "function" then
            local ok, nk = pcall(sampGetPlayerNickname, lid)
            if ok and type(nk) == "string" and nk ~= "" then
                S.tryInit()
            end
        end
        return
    end
    -- 1) Нативная слежка (F4 или то, что не перехватили) — подхватываем
    local on, natId
    if S.calOff then
        on, natId = S.spectState()
    else
        on, natId = S.spectScan()
        if on and natId then S.calibrate(natId) end
    end
    if on and natId then
        local okN, nk = pcall(sampGetPlayerNickname, natId)
        local alive = okN and type(nk) == "string" and nk ~= ""
        local cur = (GRND_SPEC and GRND_SPEC.active) and tonumber(GRND_SPEC.id) or nil
        if alive and not cur then
            pcall(grndSpecTrackCommand, "/sp " .. tostring(natId))
        end
    end
    grndSpecCamControl(S, now)
end

function grndSpecNativeReleaseCam()
    local S = grndSpecNative
    if not S.camOn then return end
    S.camOn = false
    S.camPed, S.camVehicle = nil, nil
    S.camExtra, S.camAimHeight, S.camProfileVehicle = nil, nil, nil
    S.camTgtId, S.camFrameAt = nil, nil
    S.lastMX, S.lastMY = nil, nil
    S.mouseReady,S.mouseTick=nil,nil
    S.camActiveSince = nil
    S.camWaitingFade = nil
    S.camReTakeAt = nil
    S.camTgtSmooth = nil
    S.camWallD = nil;S.camWallFilter=nil
    S.camWallHit = nil
    S.camSmart = nil
    S.camSpeedEst = nil
    S.camHeadingRad = nil
    S.camLastInput = nil
    if grndCamMoverUnlock then pcall(grndCamMoverUnlock) end
    if grndCamZoomRestore then pcall(grndCamZoomRestore) end
    -- v1.15.1: вернуть камеру игре (CCamera::Restore), если забирали её
    -- через TakeControlNoEntity
    if S.camTaken and grndSpecRestoreCam then pcall(grndSpecRestoreCam) end
    S.camTakeDone, S.camTaken, S.camRetakeT, S.camTakeTryAt = nil, nil, nil, nil
    -- Normal FOV is reacquired on the next camera tick after ownership returns.
    -- setCameraBehindPlayer зовём ТОЛЬКО если локальный игрок НЕ в режиме спектатора (иначе камера улетает в небо)
    local isLocalSpec = false
    if type(sampIsPlayerSpectating) == "function" then
        local okS, sp = pcall(sampIsPlayerSpectating)
        if okS and sp then isLocalSpec = true end
    end
    if not isLocalSpec and type(setCameraBehindPlayer) == "function" then
        pcall(setCameraBehindPlayer)
    end
end
local function cp1251_to_utf8(s)
    if type(s) ~= "string" or s == "" then return s or "" end
    local enc = encoding or libs.encoding
    if not enc or not enc.UTF8 then return s end
    local ok, out = pcall(function()
        local prev = enc.default
        enc.default = "CP1251"
        local r = enc.UTF8:encode(s)
        enc.default = prev
        return r
    end)
    if ok and type(out) == "string" then return out end
    return s
end
-- =====================================================================
--  АВТО-ОБНОВЛЕНИЕ СЛЕЖКИ ПРИ ПОТЕРЕ ЦЕЛИ (DESYNC / ИНТЕРЬЕР / РЕСПАВН)
-- =====================================================================
local GRND_SPEC_AUTOREF = {
    lastTargetId = nil,
    lastTargetNick = "",
    seenTarget = false,
    lostSince = nil,
    lastRefreshAt = 0,
    refreshCount = 0,
    graceUntil = 0,
    targetPaused = false,
    pauseTargetId = nil,
    pauseCheckAt = 0,
    manualExit = true,
}
_G.GRND_SPEC_AUTOREF = GRND_SPEC_AUTOREF

-- Query the target's native SA-MP paused/AFK state at most 5 Hz.
-- The camera and auto-refresh loop share this cache instead of polling each frame.
function grndSpecTargetIsPaused(id)
    id=tonumber(id)
    if not id then return false end
    local S=_G.GRND_SPEC_AUTOREF
    local now=os.clock()
    if S and S.pauseTargetId==id and now-(S.pauseCheckAt or -999)<0.20 then
        return S.targetPaused==true
    end
    local paused=false
    if type(sampIsPlayerPaused)=="function" then
        local ok,value=pcall(sampIsPlayerPaused,id)
        if ok then
            paused=(value==true) or (type(value)=="number" and value~=0)
        end
    end
    if S then
        S.pauseTargetId=id
        S.pauseCheckAt=now
        S.targetPaused=paused
    end
    return paused
end

local function grndIsTargetPresent(id)
    if type(id) ~= "number" or id < 0 or id > 1003 then return false, nil end
    local S = _G.grndSpecNative
    local ped = grndSpecApiHandle(sampGetCharHandleBySampPlayerId, id)
    if ped and type(doesCharExist) == "function" then
        local ok, exists = pcall(doesCharExist, ped)
        if not ok or not exists then ped = nil end
    end
    if ped and ped ~= PLAYER_PED then return true, ped end
    if grndSpecVehicle(S, id, nil) then return true, nil end
    if S and S.camTgtId == id and S.camLastTgt
        and os.clock() - (S.camLastTgt.t or 0) < 1.5 then return true, nil end
    return false, nil
end

function grndSpecAutoRefreshTick()
    local cfgOn = (GRND_ADMIN_CFG and GRND_ADMIN_CFG.spAutoRefresh ~= false)
    if not cfgOn then return end

    local S = _G.GRND_SPEC_AUTOREF
    if not S or S.manualExit then return end

    local targetId = (_G.GRND_SPEC and _G.GRND_SPEC.active and _G.GRND_SPEC.id)
        or (_G.GRND_RC and _G.GRND_RC.show and _G.GRND_RC.id)
        or S.lastTargetId
    targetId = tonumber(targetId)
    if not targetId then return end

    local now = os.clock()
    -- Connection/presence/AFK checks need only 5 Hz, not a pool lookup per frame.
    if now - (S.checkAt or -999) < 0.2 then return end
    S.checkAt = now

    -- Disconnect still ends the session; a paused/AFK player remains a valid target.
    if not specConnected(targetId) then
        S.manualExit = true
        S.lastTargetId = nil
        S.lostSince = nil
        S.refreshCount = 0
        S.targetPaused = false
        S.pauseTargetId = nil
        if type(_G.grndRcForceClose) == "function" then
            pcall(_G.grndRcForceClose, "quit")
        end
        return
    end

    -- AFK targets can temporarily lose their streamed ped. Keep the session and
    -- last camera anchor instead of repeatedly sending /sp to a connected player.
    if grndSpecTargetIsPaused(targetId) then
        S.targetPaused = true
        S.seenTarget = true
        S.lostSince = nil
        S.refreshCount = 0
        return
    end
    S.targetPaused = false

    -- Во время грейс-периода ждём ответ сервера
    if now < (S.graceUntil or 0) then return end

    local present, newPed = grndIsTargetPresent(targetId)
    if present then
        S.seenTarget = true
        S.lostSince = nil
        S.refreshCount = 0
        if newPed and _G.GRND_RC and _G.GRND_RC.actionsWinOpen and _G.GRND_RC.actTargetId == targetId then
            _G.GRND_RC.actTargetPed = newPed
        end
        if type(sampGetPlayerNickname) == "function" then
            local ok, nk = pcall(sampGetPlayerNickname, targetId)
            if ok and type(nk) == "string" and nk ~= "" then
                S.lastTargetNick = specCp2Utf(nk)
            end
        end
        return
    end

    -- Игрок пропал (рассинхрон / смена интерьера / респавн)
    if not S.lostSince then
        S.lostSince = now
        return
    end

    local lostDuration = now - S.lostSince
    -- Allow seat/vehicle transitions and short stream gaps without a new /sp.
    if lostDuration >= 3.0 then
        local cooldown = ((S.refreshCount or 0) >= 4) and 12.0 or 6.0
        if (now - (S.lastRefreshAt or 0)) >= cooldown then
            S.refreshCount = (S.refreshCount or 0) + 1
            S.lastRefreshAt = now
            S.graceUntil = now + 1.8

            local cmdBase = (_G.GRND_SPEC and _G.GRND_SPEC.cmdName) or "/sp"
            local cmd = cmdBase .. " " .. tostring(targetId)

            if _G.GRND_SPEC then
                _G.GRND_SPEC.active = true
                _G.GRND_SPEC.id = targetId
                _G.GRND_SPEC.isAutoRefreshing = true
                _G.GRND_SPEC.manualExit = false
            end
            if _G.GRND_RC then
                _G.GRND_RC.reconHidden = false
                _G.GRND_RC.show = true
                _G.GRND_RC.id = targetId
            end

            if type(sampSendChat) == "function" then
                pcall(sampSendChat, cmd)
            end
            if type(grndSpecTrackCommand) == "function" then
                pcall(grndSpecTrackCommand, cmd)
            end

            local who = "#" .. tostring(targetId)
            local nk = (_G.GRND_SPEC and _G.GRND_SPEC.nick ~= "" and _G.GRND_SPEC.nick) or S.lastTargetNick
            if nk and nk ~= "" then who = who .. " (" .. nk .. ")" end

            if notify and notify.add then
                notify.add("Слежка: цель " .. who .. " потеряна, обновляю (" .. cmd .. ")...", "warn", 2)
            end
            print("{FFAA00}[GRND]{FFFFFF} авто-обновление слежки: " .. cmd .. " (попытка " .. S.refreshCount .. ")")
        end
    end
end

-- =====================================================================
--  ХЕЛПЕРЫ ДЕЙСТВИЙ НАД ИГРОКОМ В РЕКОНЕ (v1.12.0)
-- =====================================================================
-- На проекте максимум 100 ХП: старые значения 101..160 из открытого
-- рекон-окна тоже обрезаем. Применяется и перед отправкой /hp.
function grndRcClampHp(value)
    local n = tonumber(value)
    if not n or n ~= n then n = 100 end
    return math.max(0, math.min(100, math.floor(n)))
end

function _G.grndGetTargetVehId(tid, ped)
    if _G.grndSpecNative and type(_G.grndSpecNative.getVehicleId) == "function" and tid then
        local okV, vid = pcall(_G.grndSpecNative.getVehicleId, tid)
        if okV and vid and vid > 0 then return vid end
    end
    if _G.GRND_RC and _G.GRND_RC.live and _G.GRND_RC.live.carId and _G.GRND_RC.live.carId > 0 then
        return _G.GRND_RC.live.carId
    end
    if (not ped or (type(doesCharExist) == "function" and not doesCharExist(ped))) and tid and type(sampGetCharHandleBySampPlayerId) == "function" then
        local okP, p = pcall(sampGetCharHandleBySampPlayerId, tid)
        if okP and p and (type(doesCharExist) ~= "function" or doesCharExist(p)) then
            ped = p
        end
    end
    if ped and type(doesCharExist) == "function" and doesCharExist(ped) then
        if type(isCharInAnyCar) == "function" and isCharInAnyCar(ped) then
            local car = getCarCharIsUsing(ped)
            if car and type(sampGetVehicleIdByCarHandle) == "function" then
                local okV, vid = pcall(sampGetVehicleIdByCarHandle, car)
                if okV and vid and vid > 0 then return vid end
            end
        end
    end
    return nil
end

function _G.grndHandleActionBtn(cleanLabel, tid, tNick, targetPed)
    local RC = _G.GRND_RC
    if not RC then return end

    if not tid then
        if notify and notify.add then notify.add("Цель не найдена", "warn", 2) end
        return
    end

    if cleanLabel == "Выдать ХП" then
        RC.actSubPopup = (RC.actSubPopup == "hp") and nil or "hp"
        RC.actHpVal = grndRcClampHp(RC.actHpVal)
    elseif cleanLabel == "Выдать броню" then
        RC.actSubPopup = (RC.actSubPopup == "arm") and nil or "arm"
        RC.actArmVal = RC.actArmVal or 100
    elseif cleanLabel == "Подбросить" then
        RC.actSubPopup = nil
        sampSendChat("/slap " .. tostring(tid))
        if notify and notify.add then notify.add("Подброшен игрок " .. tNick .. " (/slap " .. tid .. ")", "ok", 2) end
    elseif cleanLabel == "Заспавнить" then
        RC.actSubPopup = nil
        sampSendChat("/spawn " .. tostring(tid))
        if notify and notify.add then notify.add("Заспавнен игрок " .. tNick .. " (/spawn " .. tid .. ")", "ok", 2) end
    elseif cleanLabel == "Заморозить" then
        RC.actSubPopup = nil
        sampSendChat("/freeze " .. tostring(tid))
        if notify and notify.add then notify.add("Заморожен игрок " .. tNick .. " (/freeze " .. tid .. ")", "ok", 2) end
    elseif cleanLabel == "Разморозить" then
        RC.actSubPopup = nil
        sampSendChat("/unfreeze " .. tostring(tid))
        if notify and notify.add then notify.add("Разморожен игрок " .. tNick .. " (/unfreeze " .. tid .. ")", "ok", 2) end
    elseif cleanLabel == "Починить т/с" then
        RC.actSubPopup = nil
        sampSendChat("/fixcar " .. tostring(tid))
        if notify and notify.add then notify.add("Починено т/с игрока " .. tNick .. " (/fixcar " .. tid .. ")", "ok", 2) end
    elseif cleanLabel == "Перевернуть т/с" then
        RC.actSubPopup = nil
        sampSendChat("/flip " .. tostring(tid))
        if notify and notify.add then notify.add("Перевёрнуто т/с игрока " .. tNick .. " (/flip " .. tid .. ")", "ok", 2) end
    elseif cleanLabel == "Заправить т/с" then
        RC.actSubPopup = (RC.actSubPopup == "fuel") and nil or "fuel"
        local curV = _G.grndGetTargetVehId(tid, targetPed)
        if curV then RC.actFuelVehId = curV end
        RC.actFuelVal = RC.actFuelVal or 150
    elseif cleanLabel == "Заспавнить т/с" then
        RC.actSubPopup = nil
        local vid = _G.grndGetTargetVehId(tid, targetPed)
        if vid then
            sampSendChat("/spcar " .. tostring(vid))
            if notify and notify.add then notify.add("Заспавнен транспорт #" .. vid .. " (/spcar " .. vid .. ")", "ok", 2) end
        else
            if notify and notify.add then notify.add("Игрок " .. tNick .. " не в транспорте (ID т/с не найден)", "warn", 2.5) end
        end
    elseif cleanLabel == "ТП к игроку" then
        RC.actSubPopup = nil
        if lua_thread and lua_thread.create then
            lua_thread.create(function()
                pcall(sampSendChat, "/spoff")
                wait(200)
                pcall(sampSendChat, "/goto " .. tostring(tid))
            end)
        else
            pcall(sampSendChat, "/spoff")
            pcall(sampSendChat, "/goto " .. tostring(tid))
        end
        if notify and notify.add then notify.add("Телепортация к игроку " .. tNick .. " (/spoff -> /goto " .. tid .. ")", "ok", 2) end
    elseif cleanLabel == "ТП игрока к себе" then
        RC.actSubPopup = nil
        sampSendChat("/gethere " .. tostring(tid))
        if notify and notify.add then notify.add("Телепортация игрока " .. tNick .. " к себе (/gethere " .. tid .. ")", "ok", 2) end
    elseif cleanLabel == "Оружие" then
        RC.actSubPopup = nil
        sampSendChat("/weap " .. tostring(tid))
    elseif cleanLabel == "Отобрать все оружие" then
        RC.actSubPopup = nil
        sampSendChat("/rgun " .. tostring(tid))
        if notify and notify.add then notify.add("Отобрано оружие у игрока " .. tNick .. " (/rgun " .. tid .. ")", "ok", 2) end
    elseif cleanLabel == "Статистика" then
        RC.actSubPopup = nil
        -- v1.11.77: запрос идёт через скрипт (окно ответа сервера прячется,
        -- данные попадают в карточку) и сразу открывается окно статистики
        if type(_G.grndStatsRequest) == "function" then
            pcall(_G.grndStatsRequest, tid, "button")
        else
            sampSendChat("/stats " .. tostring(tid))
        end
        if type(_G.grndStatsPopup) == "function" then
            pcall(_G.grndStatsPopup, tid, tNick)
        end
    elseif cleanLabel == "Активные наказания" then
        RC.actSubPopup = nil
        sampSendChat("/getinfo " .. tostring(tid))
    elseif cleanLabel == "Лицензии" then
        RC.actSubPopup = nil
        sampSendChat("/alic " .. tostring(tid))
    elseif cleanLabel == "Сообщить в /a" then
        RC.actSubPopup = (RC.actSubPopup == "report_a") and nil or "report_a"
    else
        RC.actSubPopup = nil
        if notify and notify.add then
            pcall(notify.add, "«" .. cleanLabel .. "» [" .. tNick .. "]: команда подключится позже", "info", 2.2)
        end
    end
end

function _G.grndDrawActSubPopup(RC, TH, tid, tNick, targetPed, apos, adl, aat, afill, aframe, AW, AH_PAD, subY, subH, H)
    H = H or {}
    -- v1.11.72b: обёртка ImGui — из параметра (H.imgui) или из _G.
    -- РАНЬШЕ здесь стояло local im = _G.imgui, а _G.imgui скрипт не
    -- выставлял: im == nil -> МОЛЧАЛИВЫЙ return -> панель «открывалась»
    -- (высота окна уже увеличена на subH), но внутри было пусто: ни
    -- ползунка, ни кнопок «Выдать», и ни одной ошибки в логе.
    local im = H.imgui or _G.grndImgui or _G.imgui
    if subH <= 0 then return end
    if not im then
        -- Последний шанс: получаем обёртку сами (страховка от того самого
        -- nil, из-за которого панель была пустой).
        local okR, mod = pcall(require, "mimgui")
        if okR and type(mod) == "table" then im = mod end
        if not im then
            local okR2, mod2 = pcall(require, "imgui")
            if okR2 and type(mod2) == "table" then im = mod2 end
        end
    end
    if not im then
        RC.actSubError = "нет обёртки ImGui (im == nil) — панель не может рисовать"
        return
    end

    -- =================================================================
    --  v1.11.72: ГЛАВНАЯ ПРИЧИНА «панель расширяется, но ничего не
    --  появляется» в кнопках «Выдать ХП / броню / Заправить / Сообщить в /a».
    --
    --  Эта функция объявлена в начале файла, а uiText / col32 / c4 /
    --  drawnWb — локальные внутри замыкания grndMainBody (ниже по файлу).
    --  Здесь они читались как ГЛОБАЛЬНЫЕ = nil, поэтому первый же вызов
    --  падал с «attempt to call a nil value»: окно успевало вырасти по
    --  высоте (subH), а содержимое не рисовалось. Хуже того, ошибка рвала
    --  кадр МЕЖДУ im.Begin и im.End — ImGui оставался с незакрытым окном.
    --
    --  Теперь: примитивы приходят параметром (или из _G-регистрации), а
    --  если их нет — работают безопасные заглушки.
    -- =================================================================
    local uiText  = H.uiText  or _G.grndUiText
    local col32   = H.col32   or _G.grndCol32
    local c4      = H.c4      or _G.grndC4
    local drawnWb = H.drawnWb or _G.grndDrawnWb
    if not col32 then
        col32 = function(r, g, b, a)
            r, g, b, a = (r or 0) % 256, (g or 0) % 256, (b or 0) % 256, (a or 255) % 256
            if bit and bit.bor and bit.lshift then
                return bit.bor(r, bit.lshift(g, 8), bit.lshift(b, 16), bit.lshift(a, 24))
            end
            return r + g * 0x100 + b * 0x10000 + a * 0x1000000
        end
    end
    if not c4 then
        c4 = function(t)
            t = t or { 255, 255, 255, 255 }
            return im.ImVec4((t[1] or 0) / 255, (t[2] or 0) / 255,
                (t[3] or 0) / 255, (t[4] or 255) / 255)
        end
    end
    if not drawnWb then
        drawnWb = function(str, scale) return grndTextW(str) * (scale or 1) end
    end
    if not uiText then
        uiText = function(x, y, str)
            pcall(im.SetCursorPos, im.ImVec2(x, y))
            if type(im.TextUnformatted) == "function" then
                pcall(im.TextUnformatted, tostring(str))
            elseif type(im.Text) == "function" then
                pcall(im.Text, tostring(str))
            end
            return 0, 0
        end
    end

    local boxW = AW - AH_PAD * 2
    local boxH = subH - 6
    local boxY = subY + 3

    -- Тонкий разделитель
    adl:AddRectFilled(aat(AH_PAD, subY), aat(AW - AH_PAD, subY + 1), col32(255, 255, 255, 18))

    -- Фон карточки
    afill(AH_PAD, boxY, boxW, boxH, col32(14, 20, 28, 235), 8)
    aframe(AH_PAD + 0.5, boxY + 0.5, boxW - 1, boxH - 1, col32(TH.accent[1], TH.accent[2], TH.accent[3], 95), 8)

    -- Кнопка закрытия «×»
    im.SetCursorPos(im.ImVec2(AW - AH_PAD - 22, boxY + 5))
    if im.InvisibleButton("##act_sub_x", im.ImVec2(18, 18)) then
        RC.actSubPopup = nil
    end
    local xHov = (im.IsItemHovered and im.IsItemHovered()) or false
    uiText(AW - AH_PAD - 18, boxY + 5, "×", xHov and c4(TH.textHi) or c4(TH.textMuted), 0.9)

    if RC.actSubPopup == "hp" then
        RC.actHpVal = grndRcClampHp(RC.actHpVal)
        uiText(AH_PAD + 14, boxY + 8, "Выдать ХП игроку " .. tNick .. ":", c4(TH.textHi), 0.92)
        uiText(AH_PAD + 270, boxY + 7, tostring(math.floor(RC.actHpVal)) .. " HP", c4(TH.accent), 1.05)

        local slX = AH_PAD + 14
        local slY = boxY + 32
        local slW = math.floor(boxW * 0.44)
        local hpRatio = RC.actHpVal / 100

        afill(slX, slY + 5, slW, 6, col32(255, 255, 255, 28), 3)
        if hpRatio > 0.01 then
            afill(slX, slY + 5, slW * hpRatio, 6, col32(TH.accent[1], TH.accent[2], TH.accent[3], 230), 3)
        end
        adl:AddCircleFilled(aat(slX + slW * hpRatio, slY + 8), 6.5, col32(255, 255, 255, 250))
        adl:AddCircle(aat(slX + slW * hpRatio, slY + 8), 6.5, col32(TH.accent[1], TH.accent[2], TH.accent[3], 240), 12, 1.5)

        im.SetCursorPos(im.ImVec2(slX - 4, slY))
        im.InvisibleButton("##act_hp_sl", im.ImVec2(slW + 8, 18))
        if (im.IsItemActive and im.IsItemActive()) and GRND_MOUSE and GRND_MOUSE.down then
            local rel = math.max(0, math.min(1, (GRND_MOUSE.x - (apos.x + slX)) / slW))
            RC.actHpVal = math.floor(rel * 100 + 0.5)
        end

        local qVals = { 100, 50, 0 }
        local qX = slX + slW + 12
        for _, qv in ipairs(qVals) do
            im.SetCursorPos(im.ImVec2(qX, boxY + 28))
            local qClicked = im.InvisibleButton("##act_hp_q_" .. qv, im.ImVec2(40, 24))
            local qHov = (im.IsItemHovered and im.IsItemHovered()) or false
            if qClicked then RC.actHpVal = qv end
            afill(qX, boxY + 28, 40, 24, qHov and col32(255, 255, 255, 24) or col32(255, 255, 255, 12), 5)
            aframe(qX + 0.5, boxY + 28.5, 39, 23, col32(255, 255, 255, 22), 5)
            local qlbl = tostring(qv)
            local qtw = drawnWb(qlbl, 0.8)
            uiText(qX + (40 - qtw) / 2, boxY + 32, qlbl, qHov and c4(TH.textHi) or c4(TH.text), 0.8)
            qX = qX + 46
        end

        local apW = 120
        local apX = AW - AH_PAD - apW - 10
        im.SetCursorPos(im.ImVec2(apX, boxY + 27))
        local apClicked = im.InvisibleButton("##act_hp_apply", im.ImVec2(apW, 26))
        local apHov = (im.IsItemHovered and im.IsItemHovered()) or false
        local apAct = (im.IsItemActive and im.IsItemActive()) or false
        if apClicked then
            if tid then
                local amount = grndRcClampHp(RC.actHpVal)
                RC.actHpVal = amount
                sampSendChat("/hp " .. tostring(tid) .. " " .. tostring(amount))
                if notify and notify.add then notify.add("Выдано " .. tostring(amount) .. " ХП игроку " .. tNick, "ok", 2) end
            end
            RC.actSubPopup = nil
        end
        afill(apX, boxY + 27, apW, 26, (apAct or apHov) and col32(TH.accent[1], TH.accent[2], TH.accent[3], 230) or col32(TH.accent[1], TH.accent[2], TH.accent[3], 180), 6)
        aframe(apX + 0.5, boxY + 27.5, apW - 1, 25, col32(255, 255, 255, 60), 6)
        local btxt = "Выдать ХП"
        local btw = drawnWb(btxt, 0.86)
        uiText(apX + (apW - btw) / 2, boxY + 32, btxt, c4(TH.textHi), 0.86)

    elseif RC.actSubPopup == "arm" then
        RC.actArmVal = RC.actArmVal or 100
        uiText(AH_PAD + 14, boxY + 8, "Выдать броню игроку " .. tNick .. ":", c4(TH.textHi), 0.92)
        uiText(AH_PAD + 270, boxY + 7, tostring(math.floor(RC.actArmVal)) .. " Брони", c4(TH.accent), 1.05)

        local slX = AH_PAD + 14
        local slY = boxY + 32
        local slW = math.floor(boxW * 0.44)
        local armRatio = math.max(0, math.min(1, RC.actArmVal / 100))

        afill(slX, slY + 5, slW, 6, col32(255, 255, 255, 28), 3)
        if armRatio > 0.01 then
            afill(slX, slY + 5, slW * armRatio, 6, col32(TH.accent[1], TH.accent[2], TH.accent[3], 230), 3)
        end
        adl:AddCircleFilled(aat(slX + slW * armRatio, slY + 8), 6.5, col32(255, 255, 255, 250))
        adl:AddCircle(aat(slX + slW * armRatio, slY + 8), 6.5, col32(TH.accent[1], TH.accent[2], TH.accent[3], 240), 12, 1.5)

        im.SetCursorPos(im.ImVec2(slX - 4, slY))
        im.InvisibleButton("##act_arm_sl", im.ImVec2(slW + 8, 18))
        if (im.IsItemActive and im.IsItemActive()) and GRND_MOUSE and GRND_MOUSE.down then
            local rel = math.max(0, math.min(1, (GRND_MOUSE.x - (apos.x + slX)) / slW))
            RC.actArmVal = math.floor(rel * 100 + 0.5)
        end

        local qVals = { 100, 50, 0 }
        local qX = slX + slW + 12
        for _, qv in ipairs(qVals) do
            im.SetCursorPos(im.ImVec2(qX, boxY + 28))
            local qClicked = im.InvisibleButton("##act_arm_q_" .. qv, im.ImVec2(40, 24))
            local qHov = (im.IsItemHovered and im.IsItemHovered()) or false
            if qClicked then RC.actArmVal = qv end
            afill(qX, boxY + 28, 40, 24, qHov and col32(255, 255, 255, 24) or col32(255, 255, 255, 12), 5)
            aframe(qX + 0.5, boxY + 28.5, 39, 23, col32(255, 255, 255, 22), 5)
            local qlbl = tostring(qv)
            local qtw = drawnWb(qlbl, 0.8)
            uiText(qX + (40 - qtw) / 2, boxY + 32, qlbl, qHov and c4(TH.textHi) or c4(TH.text), 0.8)
            qX = qX + 46
        end

        local apW = 120
        local apX = AW - AH_PAD - apW - 10
        im.SetCursorPos(im.ImVec2(apX, boxY + 27))
        local apClicked = im.InvisibleButton("##act_arm_apply", im.ImVec2(apW, 26))
        local apHov = (im.IsItemHovered and im.IsItemHovered()) or false
        local apAct = (im.IsItemActive and im.IsItemActive()) or false
        if apClicked then
            if tid then
                sampSendChat("/arm " .. tostring(tid) .. " " .. tostring(math.floor(RC.actArmVal)))
                if notify and notify.add then notify.add("Выдано " .. tostring(math.floor(RC.actArmVal)) .. " брони игроку " .. tNick, "ok", 2) end
            end
            RC.actSubPopup = nil
        end
        afill(apX, boxY + 27, apW, 26, (apAct or apHov) and col32(TH.accent[1], TH.accent[2], TH.accent[3], 230) or col32(TH.accent[1], TH.accent[2], TH.accent[3], 180), 6)
        aframe(apX + 0.5, boxY + 27.5, apW - 1, 25, col32(255, 255, 255, 60), 6)
        local btxt = "Выдать броню"
        local btw = drawnWb(btxt, 0.86)
        uiText(apX + (apW - btw) / 2, boxY + 32, btxt, c4(TH.textHi), 0.86)

    elseif RC.actSubPopup == "fuel" then
        RC.actFuelVal = RC.actFuelVal or 150
        -- v1.11.72: внешний вызов — только по проверке типа + запасной
        -- источник ID транспорта из живых данных рекона.
        local vehGetter = _G.grndGetTargetVehId
        local vid = RC.actFuelVehId
            or (type(vehGetter) == "function" and vehGetter(tid, targetPed))
            or (RC.live and tonumber(RC.live.carId))
        local vInfo = vid and ("ID транспорта: #" .. tostring(vid)) or "т/с не обнаружен"
        uiText(AH_PAD + 14, boxY + 8, "Заправить т/с (" .. vInfo .. "):", c4(TH.textHi), 0.92)
        uiText(AH_PAD + 310, boxY + 7, tostring(math.floor(RC.actFuelVal)) .. " / 150 л", c4(TH.accent), 1.05)

        local slX = AH_PAD + 14
        local slY = boxY + 32
        local slW = math.floor(boxW * 0.44)
        local fuelRatio = math.max(0, math.min(1, RC.actFuelVal / 150))

        afill(slX, slY + 5, slW, 6, col32(255, 255, 255, 28), 3)
        if fuelRatio > 0.01 then
            afill(slX, slY + 5, slW * fuelRatio, 6, col32(TH.accent[1], TH.accent[2], TH.accent[3], 230), 3)
        end
        adl:AddCircleFilled(aat(slX + slW * fuelRatio, slY + 8), 6.5, col32(255, 255, 255, 250))
        adl:AddCircle(aat(slX + slW * fuelRatio, slY + 8), 6.5, col32(TH.accent[1], TH.accent[2], TH.accent[3], 240), 12, 1.5)

        im.SetCursorPos(im.ImVec2(slX - 4, slY))
        im.InvisibleButton("##act_fuel_sl", im.ImVec2(slW + 8, 18))
        if (im.IsItemActive and im.IsItemActive()) and GRND_MOUSE and GRND_MOUSE.down then
            local rel = math.max(0, math.min(1, (GRND_MOUSE.x - (apos.x + slX)) / slW))
            RC.actFuelVal = math.floor(rel * 150 + 0.5)
        end

        local qVals = { 150, 100, 50 }
        local qX = slX + slW + 12
        for _, qv in ipairs(qVals) do
            im.SetCursorPos(im.ImVec2(qX, boxY + 28))
            local qClicked = im.InvisibleButton("##act_fuel_q_" .. qv, im.ImVec2(40, 24))
            local qHov = (im.IsItemHovered and im.IsItemHovered()) or false
            if qClicked then RC.actFuelVal = qv end
            afill(qX, boxY + 28, 40, 24, qHov and col32(255, 255, 255, 24) or col32(255, 255, 255, 12), 5)
            aframe(qX + 0.5, boxY + 28.5, 39, 23, col32(255, 255, 255, 22), 5)
            local qlbl = tostring(qv)
            local qtw = drawnWb(qlbl, 0.8)
            uiText(qX + (40 - qtw) / 2, boxY + 32, qlbl, qHov and c4(TH.textHi) or c4(TH.text), 0.8)
            qX = qX + 46
        end

        local apW = 120
        local apX = AW - AH_PAD - apW - 10
        im.SetCursorPos(im.ImVec2(apX, boxY + 27))
        local apClicked = im.InvisibleButton("##act_fuel_apply", im.ImVec2(apW, 26))
        local apHov = (im.IsItemHovered and im.IsItemHovered()) or false
        local apAct = (im.IsItemActive and im.IsItemActive()) or false
        if apClicked then
            if vid then
                sampSendChat("/setfuel " .. tostring(vid) .. " " .. tostring(math.floor(RC.actFuelVal)))
                if notify and notify.add then notify.add("Транспорт #" .. vid .. " заправлен на " .. tostring(math.floor(RC.actFuelVal)) .. " л", "ok", 2) end
                RC.actSubPopup = nil
            else
                if notify and notify.add then notify.add("ID транспорта не определен (игрок должен быть в авто)", "warn", 2.5) end
            end
        end
        afill(apX, boxY + 27, apW, 26, (apAct or apHov) and col32(TH.accent[1], TH.accent[2], TH.accent[3], 230) or col32(TH.accent[1], TH.accent[2], TH.accent[3], 180), 6)
        aframe(apX + 0.5, boxY + 27.5, apW - 1, 25, col32(255, 255, 255, 60), 6)
        local btxt = "Заправить"
        local btw = drawnWb(btxt, 0.86)
        uiText(apX + (apW - btw) / 2, boxY + 32, btxt, c4(TH.textHi), 0.86)

    elseif RC.actSubPopup == "report_a" then
        local bW = math.floor((boxW - 36) / 2)
        local bH = 34
        local bY = boxY + 8

        local b1X = AH_PAD + 12
        im.SetCursorPos(im.ImVec2(b1X, bY))
        local b1Clicked = im.InvisibleButton("##act_a_help", im.ImVec2(bW, bH))
        local b1Hov = (im.IsItemHovered and im.IsItemHovered()) or false
        local b1Act = (im.IsItemActive and im.IsItemActive()) or false
        if b1Clicked then
            local who = grndUtf8Text(tNick) .. " [" .. tostring(tid or 0) .. "]"
            grndChatSend("/a Игрок " .. who .. " нуждается в помощи!")
            if notify and notify.add then notify.add("Отправлено в /a: Игрок " .. who .. " нуждается в помощи!", "ok", 2.5) end
            RC.actSubPopup = nil
        end
        afill(b1X, bY, bW, bH, (b1Act or b1Hov) and col32(TH.accent[1], TH.accent[2], TH.accent[3], 60) or col32(255, 255, 255, 14), 7)
        aframe(b1X + 0.5, bY + 0.5, bW - 1, bH - 1, (b1Act or b1Hov) and col32(TH.accent[1], TH.accent[2], TH.accent[3], 180) or col32(255, 255, 255, 30), 7)
        local txt1 = "Запросить помощь"
        local tw1 = drawnWb(txt1, 0.92)
        uiText(b1X + (bW - tw1) / 2, bY + 8, txt1, (b1Hov or b1Act) and c4(TH.textHi) or c4(TH.text), 0.92)

        local b2X = b1X + bW + 12
        im.SetCursorPos(im.ImVec2(b2X, bY))
        local b2Clicked = im.InvisibleButton("##act_a_spec", im.ImVec2(bW, bH))
        local b2Hov = (im.IsItemHovered and im.IsItemHovered()) or false
        local b2Act = (im.IsItemActive and im.IsItemActive()) or false
        if b2Clicked then
            local who = grndUtf8Text(tNick) .. " [" .. tostring(tid or 0) .. "]"
            grndChatSend("/a Следите за игроком " .. who)
            if notify and notify.add then notify.add("Отправлено в /a: Следите за игроком " .. who, "ok", 2.5) end
            RC.actSubPopup = nil
        end
        afill(b2X, bY, bW, bH, (b2Act or b2Hov) and col32(TH.accent[1], TH.accent[2], TH.accent[3], 60) or col32(255, 255, 255, 14), 7)
        aframe(b2X + 0.5, bY + 0.5, bW - 1, bH - 1, (b2Act or b2Hov) and col32(TH.accent[1], TH.accent[2], TH.accent[3], 180) or col32(255, 255, 255, 30), 7)
        local txt2 = "Попросить следить"
        local tw2 = drawnWb(txt2, 0.92)
        uiText(b2X + (bW - tw2) / 2, bY + 8, txt2, (b2Hov or b2Act) and c4(TH.textHi) or c4(TH.text), 0.92)
    end

    -- v1.11.72b: содержимое нарисовано — счётчик для диагностики.
    RC.actSubDrawn = (RC.actSubDrawn or 0) + 1
    RC.actSubDrawnAt = os.clock()
    RC.actSubError = nil
end

-- =====================================================================
--  ОСНОВНОЕ ТЕЛО СКРИПТА
--  МОДУЛЬ 5b: больше НЕТ ожидания isSampLoaded() — рендер жив
--  с самого старта (загрузка GTA -> коннект к серверу).
-- =====================================================================
-- =====================================================================
--  v1.14.0: БИНДЕР
--
--  Вкладка «Биндер» (или команда /binder). Слева — список биндов,
--  справа — текст, задержка и клавиша. «Выдать» или клавиша активации
--  отправляет непустые строки на сервер через обычный чат SA-MP
--  (sampSendChat / grndChatSend), по одной, с заданной паузой.
--
--  Задержка: от 0.5 мс до 5 сек, шкала логарифмическая (иначе
--  миллисекунды были бы неразличимы на линейном слайдере).
--  Первая строка уходит сразу, дальше — пауза между строками.
--  Пока открыт чат или диалог, отправка стоит на паузе и сама
--  продолжается. ESC или повторное нажатие клавиши — стоп.
--  wait() в главном цикле не используется: остальные модули не
--  замирают на время бинда.
--
--  Конфиг: grnd_binder.cfg рядом со скриптом.
--  // в начале строки — комментарий, на сервер не уходит.
--  {myid} {mynick} {time} подставляются в момент отправки.
-- =====================================================================
GRND_BINDER = GRND_BINDER or {
    binds = {},
    sel = nil,
    nextId = 1,
    loaded = false,
    dirty = false,
    saveAt = 0,
    scroll = 0,
    binding = false,
    renaming = false,
    running = false,
    runIndex = 1,
    runDelay = 1,
    nextAt = 0,
    hold = false,
    arm = {},
    byKey = {},
    bufCap = 16384,
    nameCap = 96,
    minMs = 0.5,
    maxMs = 5000,
    maxBinds = 48,
    maxSend = 200,
    welcomed = false,
}

function grndBinderClampDelay(ms)
    ms = tonumber(ms)
    if not ms then return 1000 end
    if ms ~= ms or ms == math.huge or ms == -math.huge then return 1000 end
    if ms < 0.5 then return 0.5 end
    if ms > 5000 then return 5000 end
    return ms
end

function grndBinderSnapDelay(ms)
    ms = grndBinderClampDelay(ms)
    local snapped
    if ms < 10 then
        snapped = math.floor(ms * 10 + 0.5) / 10
    elseif ms < 100 then
        snapped = math.floor(ms + 0.5)
    elseif ms < 1000 then
        snapped = math.floor(ms / 5 + 0.5) * 5
    else
        snapped = math.floor(ms / 50 + 0.5) * 50
    end
    return grndBinderClampDelay(snapped)
end

function grndBinderMsToT(ms)
    ms = grndBinderClampDelay(ms)
    local a, b = math.log(0.5), math.log(5000)
    return (math.log(ms) - a) / (b - a)
end

function grndBinderTToMs(t)
    t = tonumber(t) or 0
    if t < 0 then t = 0 elseif t > 1 then t = 1 end
    local a, b = math.log(0.5), math.log(5000)
    return grndBinderSnapDelay(math.exp(a + t * (b - a)))
end

-- Без string.format("%f"): на русской локали Windows он ставит запятую.
function grndBinderFormatDelay(ms)
    ms = grndBinderClampDelay(ms)
    if ms >= 1000 then
        local tenths = math.floor(ms / 100 + 0.5)
        return string.format("%d.%d сек.", math.floor(tenths / 10), tenths % 10)
    elseif ms >= 10 then
        return string.format("%d мс", math.floor(ms + 0.5))
    else
        local tenths = math.floor(ms * 10 + 0.5)
        return string.format("%d.%d мс", math.floor(tenths / 10), tenths % 10)
    end
end

function grndBinderUtf8Cut(s, maxc)
    s = tostring(s or "")
    maxc = maxc or 24
    local n, out, cut = 0, {}, false
    for ch in s:gmatch("[%z\1-\127\194-\244][\128-\191]*") do
        n = n + 1
        if n > maxc then cut = true break end
        out[#out + 1] = ch
    end
    return table.concat(out), cut
end

function grndBinderEscape(s)
    s = tostring(s or ""):gsub("\r", "")
    s = s:gsub("\\", "\\\\")
    s = s:gsub("\n", "\\n")
    return s
end

function grndBinderUnescape(s)
    s = tostring(s or "")
    local out, i, n = {}, 1, #s
    while i <= n do
        local c = s:sub(i, i)
        if c == "\\" and i < n then
            local n1 = s:sub(i + 1, i + 1)
            if n1 == "n" then
                out[#out + 1] = "\n"
            elseif n1 == "\\" then
                out[#out + 1] = "\\"
            else
                out[#out + 1] = n1
            end
            i = i + 2
        else
            out[#out + 1] = c
            i = i + 1
        end
    end
    return table.concat(out)
end

-- Строки, которые реально уйдут на сервер (пустые и // пропускаются).
function grndBinderCollectLines(text)
    local out = {}
    text = tostring(text or ""):gsub("\r\n", "\n"):gsub("\r", "\n")
    for line in (text .. "\n"):gmatch("([^\n]*)\n") do
        local s = line:gsub("^%s+", ""):gsub("%s+$", "")
        if s ~= "" and not s:match("^//") then
            out[#out + 1] = s
        end
    end
    return out
end

function grndBinderCountLines(text)
    return #grndBinderCollectLines(text)
end

function grndBinderCfgPath()
    if type(this_script_dir) == "function" then
        local ok, sd = pcall(this_script_dir)
        if ok and sd and tostring(sd) ~= "" then
            local pp = tostring(sd)
            while pp:sub(-1) == "/" or pp:sub(-1) == "\\" do pp = pp:sub(1, -2) end
            local sep = "\\"
            local okc, cf = pcall(function() return package.config end)
            if okc and type(cf) == "string" and #cf > 0 then sep = cf:sub(1, 1) end
            return pp .. sep .. "grnd_binder.cfg"
        end
    end
    return "grnd_binder.cfg"
end

function grndBinderById(id)
    local B = GRND_BINDER
    id = tonumber(id)
    if not id then return nil end
    for i = 1, #B.binds do
        if B.binds[i].id == id then return B.binds[i], i end
    end
    return nil
end

function grndBinderSelected()
    local B = GRND_BINDER
    local b = grndBinderById(B.sel)
    if b then return b end
    if B.binds[1] then
        B.sel = B.binds[1].id
        return B.binds[1]
    end
    return nil
end

function grndBinderReindex()
    local B = GRND_BINDER
    B.byKey = {}
    local seen = {}
    for i = 1, #B.binds do
        local b = B.binds[i]
        local k = tonumber(b.key) or 0
        if k < 1 or k > 255 or k == 0x10 then k = 0 end
        if k > 0 then
            if seen[k] then
                k = 0
            else
                seen[k] = true
                B.byKey[k] = b
            end
        end
        b.key = k
    end
end

function grndBinderTouch()
    local B = GRND_BINDER
    B.dirty = true
    B.saveAt = os.clock() + 0.45
end

function grndBinderSerialize()
    local B = GRND_BINDER
    local parts = {
        "v=1",
        "sel=" .. tostring(B.sel or 0),
        "next=" .. tostring(B.nextId or 1),
    }
    for i = 1, #B.binds do
        local b = B.binds[i]
        parts[#parts + 1] = "---"
        parts[#parts + 1] = "id=" .. tostring(b.id or i)
        parts[#parts + 1] = "name=" .. grndBinderEscape(b.name or "Бинд")
        parts[#parts + 1] = "key=" .. tostring(b.key or 0)
        parts[#parts + 1] = "delay=" .. tostring(grndBinderClampDelay(b.delay))
        parts[#parts + 1] = "text=" .. grndBinderEscape(b.text or "")
    end
    parts[#parts + 1] = "---"
    parts[#parts + 1] = ""
    return table.concat(parts, "\n")
end

function grndBinderParse(content)
    local binds, sel, nextId = {}, nil, 1
    local cur = nil
    local function finish()
        if not cur or not cur._seen then
            cur = nil
            return
        end
        local id = tonumber(cur.id) or (#binds + 1)
        if id < 1 then id = #binds + 1 end
        local name = grndBinderUtf8Cut(tostring(cur.name or "Бинд"), 24)
        if name == "" then name = "Бинд" end
        local key = tonumber(cur.key) or 0
        if key < 0 or key > 255 then key = 0 end
        local text = tostring(cur.text or ""):gsub("%z", "")
        if #text > 12000 then text = text:sub(1, 12000) end
        binds[#binds + 1] = {
            id = id,
            name = name,
            key = key,
            delay = grndBinderClampDelay(cur.delay),
            text = text,
        }
        if id >= nextId then nextId = id + 1 end
        cur = nil
    end
    content = tostring(content or "")
    for line in (content .. "\n"):gmatch("([^\n]*)\n") do
        line = line:gsub("\r$", "")
        if line == "---" then
            finish()
            -- закрывающий «---» не должен порождать пустой бинд:
            -- запись появится, только если ниже есть хотя бы одно поле
            cur = { name = "Бинд", key = 0, delay = 1000, text = "", _seen = false }
        elseif cur then
            local k, v = line:match("^([%a]+)=(.*)$")
            if k == "name" or k == "text" then
                cur._seen = true
                cur[k] = grndBinderUnescape(v or "")
            elseif k == "id" or k == "key" or k == "delay" then
                cur._seen = true
                cur[k] = v
            end
        else
            local k, v = line:match("^([%a]+)=(.*)$")
            if k == "sel" then sel = tonumber(v) end
            if k == "next" then
                local n = tonumber(v)
                if n and n > nextId then nextId = n end
            end
        end
    end
    finish()
    -- уникальные id
    local used = {}
    for i = 1, #binds do
        local id = binds[i].id
        if used[id] then
            id = nextId
            nextId = nextId + 1
            binds[i].id = id
        end
        used[id] = true
        if id >= nextId then nextId = id + 1 end
    end
    if #binds > 48 then
        while #binds > 48 do binds[#binds] = nil end
    end
    return binds, sel, nextId
end

function grndBinderDefaults()
    local B = GRND_BINDER
    B.binds = {
        { id = 1, name = "Бинд", key = 0, delay = 1000, text = "" },
    }
    B.sel = 1
    B.nextId = 2
    grndBinderReindex()
end

function grndBinderLoad()
    local B = GRND_BINDER
    if B.loaded then return end
    B.loaded = true
    local path = grndBinderCfgPath()
    local ok, f = pcall(GRND_CONFIG.open, path, "r")
    if not ok or not f then
        grndBinderDefaults()
        return
    end
    local okc, content = pcall(function() return f:read("*a") end)
    pcall(function() f:close() end)
    if not okc or type(content) ~= "string" or content == "" then
        grndBinderDefaults()
        return
    end
    local okp, binds, sel, nextId = pcall(grndBinderParse, content)
    if not okp or type(binds) ~= "table" then
        grndBinderDefaults()
        pcall(notify.add, "Конфиг биндера не прочитался — начат заново", "warn", 4)
        return
    end
    if #binds == 0 then
        -- An explicitly empty portable binder stays empty after restart.
        B.binds={};B.sel=nil;B.nextId=nextId or 1
        grndBinderReindex()
        return
    end
    B.binds = binds
    B.nextId = nextId or (#binds + 1)
    B.sel = sel
    if not grndBinderById(B.sel) then
        B.sel = binds[1].id
    end
    grndBinderReindex()
end

function grndBinderSave()
    local B = GRND_BINDER
    if type(grndBinderFlushBuf) == "function" then grndBinderFlushBuf() end
    local path = grndBinderCfgPath()
    local body = grndBinderSerialize()
    local ok, f = pcall(GRND_CONFIG.open, path, "w")
    if not ok or not f then
        if not B.saveFailNotified then
            B.saveFailNotified = true
            pcall(notify.add, "Не удалось сохранить config/grnd_tools/config.json", "error", 4)
        end
        B.dirty = true
        B.saveAt = os.clock() + 2
        return false
    end
    local okw = pcall(function()
        f:write(body)
        f:close()
    end)
    if not okw then
        pcall(function() f:close() end)
        B.dirty = true
        B.saveAt = os.clock() + 2
        return false
    end
    B.dirty = false
    B.saveFailNotified = false
    return true
end

function grndBinderNote(text, kind)
    if notify and type(notify.add) == "function" then
        pcall(notify.add, text, kind or "info", 2.6)
    elseif type(sampAddChatMessage) == "function" then
        pcall(sampAddChatMessage, "[GRND] " .. tostring(text), -1)
    else
        print("[GRND] " .. tostring(text))
    end
end

function grndBinderEnsureBuf(im)
    local B = GRND_BINDER
    if B.buf and B.bufIm == im then return true end
    if not (im and im.new and im.new.char) then return false end
    local cap = 16384
    local ok, buf = pcall(function() return im.new.char[cap]() end)
    if not (ok and buf) then
        cap = 4096
        ok, buf = pcall(function() return im.new.char[cap]() end)
    end
    if not (ok and buf) then return false end
    B.buf, B.bufCap, B.bufIm, B.bufBindId = buf, cap, im, nil
    return true
end

function grndBinderEnsureNameBuf(im)
    local B = GRND_BINDER
    if B.nameBuf and B.nameBufIm == im then return true end
    if not (im and im.new and im.new.char) then return false end
    local ok, buf = pcall(function() return im.new.char[96]() end)
    if not (ok and buf) then return false end
    B.nameBuf, B.nameCap, B.nameBufIm, B.nameBufId = buf, 96, im, nil
    return true
end

function grndBinderWriteCBuf(buf, cap, text)
    text = tostring(text or ""):gsub("%z", "")
    if #text >= cap then text = text:sub(1, cap - 1) end
    local ok, ffi = pcall(require, "ffi")
    if not ok or not ffi then return false end
    local okw = pcall(function()
        ffi.fill(buf, cap, 0)
        if #text > 0 then ffi.copy(buf, text) end
    end)
    return okw
end

function grndBinderReadCBuf(buf)
    if not buf then return "" end
    local ok, ffi = pcall(require, "ffi")
    if not ok or not ffi then return "" end
    local ok2, s = pcall(ffi.string, buf)
    -- v1.14.21: ФИКС — «return s:gsub(...)» утаскивал ВТОРОЕ значение gsub
    -- (счётчик) наружу; в «tonumber(grndBinderReadCBuf(...))» оно уезжало
    -- в аргумент base и валило сохранение точки. Скобки режут до одного.
    if ok2 and type(s) == "string" then return (s:gsub("%z", "")) end
    return ""
end

function grndBinderWriteBuf(text)
    local B = GRND_BINDER
    if not B.buf then return end
    grndBinderWriteCBuf(B.buf, B.bufCap or 16384, text)
end

function grndBinderReadBuf()
    return (grndBinderReadCBuf(GRND_BINDER.buf))
end

function grndBinderFlushBuf()
    local B = GRND_BINDER
    if not B.buf or not B.bufBindId then return end
    local b = grndBinderById(B.bufBindId)
    if not b then return end
    local s = grndBinderReadBuf()
    if s ~= (b.text or "") then
        b.text = s
        B.dirty = true
    end
end

function grndBinderSelect(id)
    local B = GRND_BINDER
    id = tonumber(id)
    if not id or B.sel == id then return end
    if B.renaming then pcall(grndBinderCommitRename) end
    grndBinderFlushBuf()
    B.sel = id
    B.bufBindId = nil
    B.renaming = false
    B.renameSeen = false
    B.renameFocus = false
    B.binding = false
end

function grndBinderUniqueName(base)
    local B = GRND_BINDER
    local used = {}
    for i = 1, #B.binds do used[B.binds[i].name] = true end
    if not used[base] then return base end
    local i = 2
    while used[base .. " " .. i] do i = i + 1 end
    return base .. " " .. i
end

function grndBinderAdd()
    local B = GRND_BINDER
    grndBinderLoad()
    if #B.binds >= (B.maxBinds or 48) then
        grndBinderNote("Не больше " .. tostring(B.maxBinds or 48) .. " биндов", "warn")
        return
    end
    local id = B.nextId or 1
    B.nextId = id + 1
    local b = {
        id = id,
        name = grndBinderUniqueName("Бинд"),
        key = 0,
        delay = 1000,
        text = "",
    }
    B.binds[#B.binds + 1] = b
    grndBinderFlushBuf()
    B.sel = id
    B.bufBindId = nil
    B.scrollToSel = true
    B.focusEditor = true
    B.renaming = false
    grndBinderReindex()
    grndBinderSave()
end

function grndBinderDelete(id)
    local B = GRND_BINDER
    local _, idx = grndBinderById(id)
    if not idx then return end
    if B.running and B.runId == id then grndBinderStop("quiet") end
    if B.bufBindId == id then B.bufBindId = nil end
    table.remove(B.binds, idx)
    if B.sel == id then
        local nb = B.binds[idx] or B.binds[idx - 1]
        B.sel = nb and nb.id or nil
        B.bufBindId = nil
    end
    B.renaming = false
    grndBinderReindex()
    grndBinderSave()
end

function grndBinderBeginRename(im)
    local B=GRND_BINDER
    local cur=grndBinderSelected()
    if not cur then return false end
    if not grndBinderEnsureNameBuf(im) then
        grndBinderNote("Поле названия недоступно в этой сборке ImGui", "error")
        return false
    end
    grndBinderWriteCBuf(B.nameBuf,B.nameCap or 96,cur.name or "")
    B.nameBufId=cur.id
    B.renaming=true; B.renameSeen=false; B.renameFocus=false
    B.renameError=nil; B.binding=false
    return true
end

function grndBinderCommitRename()
    local B=GRND_BINDER
    local b=grndBinderById(B.nameBufId or B.sel)
    if not b or not B.nameBuf then return false end
    local nm=grndBinderReadCBuf(B.nameBuf)
    nm=nm:gsub("[%c]", ""):gsub("^%s+", ""):gsub("%s+$", "")
    nm=grndBinderUtf8Cut(nm,24)
    if nm=="" then
        B.renameError="Введите название"
        return false
    end
    local changed=nm~=b.name
    b.name=nm
    if B.runId==b.id then B.runName=nm end
    B.renaming=false;B.renameSeen=false;B.renameFocus=false
    B.nameActive=false;B.nameBufId=nil;B.renameError=nil
    if changed then
        local saved=grndBinderSave()
        if not saved then grndBinderNote("Название изменено, запись на диск будет повторена", "warn") end
        return saved
    end
    return true
end

function grndBinderReservedKey(vk)
    if vk >= 0x01 and vk <= 0x06 then return "кнопка мыши" end
    if vk == 0x09 then return "TAB" end
    if vk == 0x0D then return "ENTER" end
    if vk == 0x70 then return "F1" end
    if vk == 0x1B then return "ESC" end
    if GRND_MENU_HOTKEY and vk == GRND_MENU_HOTKEY then return "меню" end
    if GRND_CHAT and GRND_CHAT.key and vk == GRND_CHAT.key then return "чат" end
    return nil
end

function grndBinderCaptureKey(vk)
    local B = GRND_BINDER
    if vk == 0x1B then
        B.binding = false
        grndBinderNote("Назначение клавиши отменено", "info")
        return
    end
    if vk == 0x08 or vk == 0x2E then
        local b = grndBinderSelected()
        if b then b.key = 0 end
        B.binding = false
        grndBinderReindex()
        grndBinderSave()
        grndBinderNote("Клавиша активации сброшена", "warn")
        return
    end
    local why = grndBinderReservedKey(vk)
    if not why and _G.GRND_TARGET_RING and GRND_TARGET_RING.slots then
        for _, side in ipairs({ "left", "right", "vehicle" }) do
            local entries = GRND_TARGET_RING.slots[side] or {}
            for _, s in ipairs(entries) do
                if s.key == vk then why = "используется кругом целей"; break end
            end
            if why then break end
        end
    end
    if why then
        grndBinderNote("Эту клавишу нельзя занять (" .. why .. ")", "warn")
        return
    end
    local b = grndBinderSelected()
    if not b then
        B.binding = false
        return
    end
    for i = 1, #B.binds do
        local o = B.binds[i]
        if o.id ~= b.id and o.key == vk then
            o.key = 0
            grndBinderNote("Клавиша снята с «" .. o.name .. "»", "info")
        end
    end
    b.key = vk
    B.binding = false
    B.arm = B.arm or {}
    B.arm[vk] = true
    grndBinderReindex()
    grndBinderSave()
    local kn = (type(grndKeyName) == "function") and grndKeyName(vk) or string.format("0x%02X", vk)
    local extra = ""
    if GRND_INVIS and GRND_INVIS.key == vk then extra = " (ещё и невидимость)" end
    if GRND_ABRK and GRND_ABRK.key == vk then extra = " (ещё и AirBreak)" end
    grndBinderNote("Клавиша активации: " .. kn .. extra, "ok")
end

function grndBinderInputBlocked()
    local B = GRND_BINDER
    if B.binding or B.renaming or B.textActive then return true end
    if type(grndIsTyping) == "function" and grndIsTyping() then return true end
    if type(grndUiBlocked) == "function" and grndUiBlocked() then return true end
    if GRND_INVIS and GRND_INVIS.binding then return true end
    if GRND_ABRK and GRND_ABRK.binding then return true end
    if GRND_AREP and GRND_AREP.binding then return true end
    if GRND_CATCH and GRND_CATCH.binding then return true end
    if GRND_CHAT and GRND_CHAT.binding then return true end
    return false
end

function grndBinderExpand(line)
    if not line:find("{", 1, true) then return line end
    local id = "?"
    if type(sampGetLocalPlayerId) == "function" then
        local ok, v = pcall(sampGetLocalPlayerId)
        if ok and type(v) == "number" and v >= 0 then id = tostring(math.floor(v)) end
    end
    local nick = ""
    if id ~= "?" and type(sampGetPlayerNickname) == "function" then
        local ok, v = pcall(sampGetPlayerNickname, tonumber(id))
        if ok and type(v) == "string" and v ~= "" then
            if type(grndUtf8Text) == "function" then
                local oku, u = pcall(grndUtf8Text, v)
                if oku and type(u) == "string" and u ~= "" then nick = u end
            end
            if nick == "" and type(grndCp1251ToUtf8) == "function" then
                nick = grndCp1251ToUtf8(v)
            end
            if nick == "" then nick = v end
        end
    end
    if nick == "" then nick = "?" end
    local tm = os.date("%H:%M:%S")
    line = line:gsub("{myid}", id)
    line = line:gsub("{mynick}", nick)
    line = line:gsub("{time}", tm)
    return line
end

function grndBinderSendLine(line)
    local B = GRND_BINDER
    line = grndBinderExpand(line)
    local cut
    line, cut = grndBinderUtf8Cut(line, 144)
    if cut and not B.truncNotified then
        B.truncNotified = true
        grndBinderNote("Строка длиннее 144 символов — обрезана", "warn")
    end
    if line == "" then return false end
    if type(grndChatSend) == "function" then
        return grndChatSend(line) and true or false
    end
    if type(sampSendChat) == "function" then
        return pcall(sampSendChat, line) and true or false
    end
    return false
end

function grndBinderOnEsc()
    local B = GRND_BINDER
    if not B then return false end
    if B.renaming then
        B.renaming = false
        B.renameSeen = false
        B.renameFocus = false
        B.nameBufId = nil
        return true
    end
    if B.binding then
        B.binding = false
        grndBinderNote("Назначение клавиши отменено", "info")
        return true
    end
    if B.running then
        grndBinderStop("esc")
        return true
    end
    return false
end

function grndBinderStop(why)
    local B = GRND_BINDER
    if not B.running then return end
    local name = B.runName or "Бинд"
    local sent = math.max(0, (B.runIndex or 1) - 1)
    local total = B.queue and #B.queue or 0
    B.running = false
    B.hold = false
    B.queue = nil
    B.runId = nil
    B.failStreak = 0
    if why == "done" then
        grndBinderNote("Бинд «" .. name .. "» отправлен (" .. tostring(total) .. ")", "ok")
    elseif why == "quiet" then
        return
    elseif why == "fail" then
        grndBinderNote("Сервер не принял сообщения, бинд остановлен", "error")
    elseif why == "despawn" then
        grndBinderNote("Бинд остановлен: вы не в игре", "warn")
    else
        grndBinderNote("Бинд «" .. name .. "» остановлен (" .. sent .. "/" .. total .. ")", "warn")
    end
end

function grndBinderStart(bind)
    local B = GRND_BINDER
    if not bind then return false end
    grndBinderFlushBuf()
    bind = grndBinderById(bind.id) or bind
    local lines = grndBinderCollectLines(bind.text)
    if #lines == 0 then
        grndBinderNote("Бинд «" .. tostring(bind.name) .. "» пустой", "warn")
        return false
    end
    if #lines > (B.maxSend or 200) then
        grndBinderNote("В бинде больше 200 строк — уйдут первые 200", "warn")
        while #lines > 200 do lines[#lines] = nil end
    end
    if type(sampSendChat) ~= "function" and type(grndChatSend) ~= "function" then
        grndBinderNote("Чат ещё не готов", "warn")
        return false
    end
    if type(grndIsSpawnedSafe) == "function" and not grndIsSpawnedSafe() then
        grndBinderNote("Вы ещё не в игре", "warn")
        return false
    end
    if B.running then grndBinderStop("quiet") end
    B.running = true
    B.runId = bind.id
    B.runName = bind.name
    B.queue = lines
    B.runIndex = 1
    B.runDelay = grndBinderClampDelay(bind.delay) / 1000
    B.nextAt = os.clock()
    B.hold = false
    B.truncNotified = false
    B.failStreak = 0
    B.sentOk = 0
    grndBinderNote("«" .. bind.name .. "»: " .. #lines .. " стр., задержка "
        .. grndBinderFormatDelay(bind.delay), "ok")
    if type(_G.grndEnsureRender) == "function" then pcall(_G.grndEnsureRender, true) end
    return true
end

function grndBinderToggle(bind)
    local B = GRND_BINDER
    if not bind then return end
    local now = os.clock()
    if B.lastToggleId == bind.id and (now - (B.lastToggleAt or -10)) < 0.12 then
        return
    end
    B.lastToggleAt = now
    B.lastToggleId = bind.id
    if B.running and B.runId == bind.id then
        grndBinderStop("key")
    else
        grndBinderStart(bind)
    end
end

function grndBinderIssue()
    local B = GRND_BINDER
    grndBinderFlushBuf()
    local b = grndBinderSelected()
    if not b then
        grndBinderNote("Сначала нажмите «Добавить»", "warn")
        return
    end
    if B.running and B.runId == b.id then
        grndBinderStop("button")
        return
    end
    grndBinderStart(b)
end

function grndBinderTickSend()
    local B = GRND_BINDER
    if not B.running or type(B.queue) ~= "table" then return end
    if type(grndIsSpawnedSafe) == "function" and not grndIsSpawnedSafe() then
        grndBinderStop("despawn")
        return
    end
    local blocked = false
    if type(grndIsTyping) == "function" and grndIsTyping() then blocked = true end
    if type(grndUiBlocked) == "function" and grndUiBlocked() then blocked = true end
    if B.textActive and (os.clock() - (B.drewAt or 0)) < 0.35 then blocked = true end
    if blocked then
        B.hold = true
        return
    end
    if B.hold then
        B.hold = false
        if (B.runIndex or 1) <= 1 then
            B.nextAt = os.clock()
        else
            B.nextAt = os.clock() + (B.runDelay or 1)
        end
    end
    local now = os.clock()
    local guard = 0
    -- Не больше 40 строк за кадр: при 0.5 мс это как раз нужный темп,
    -- а огромная вставка не подвешивает кадр.
    while B.running and B.runIndex <= #B.queue and now >= (B.nextAt or 0) and guard < 40 do
        local ok = grndBinderSendLine(B.queue[B.runIndex])
        if ok then
            B.sentOk = (B.sentOk or 0) + 1
            B.failStreak = 0
        else
            B.failStreak = (B.failStreak or 0) + 1
            if B.failStreak >= 3 then
                grndBinderStop("fail")
                return
            end
        end
        B.runIndex = B.runIndex + 1
        B.nextAt = (B.nextAt or now) + (B.runDelay or 1)
        guard = guard + 1
        now = os.clock()
    end
    if B.running and B.runIndex > #B.queue then
        grndBinderStop("done")
    end
end

function grndBinderKeyHeld(vk)
    if not vk or vk <= 0 then return false end
    if (vk == 0xA0 or vk == 0xA1) and GRND_ABRK and GRND_ABRK.wmShiftDown == vk then
        return true
    end
    if grndGAKS then
        local ok, st = pcall(grndGAKS, vk)
        if ok and st ~= nil then
            local v = tonumber(st)
            if v then
                if v < 0 then v = v + 65536 end
                return v >= 32768
            end
        end
    end
    if type(isKeyDown) == "function" then
        local ok, d = pcall(isKeyDown, vk)
        if ok and d then return true end
    end
    return false
end

function grndBinderPollKeys()
    local B = GRND_BINDER
    if B.binding then return end
    B.arm = B.arm or {}
    local blocked = grndBinderInputBlocked()
    for vk, bind in pairs(B.byKey) do
        local held = grndBinderKeyHeld(vk)
        if not held then
            B.arm[vk] = nil
        elseif not B.arm[vk] then
            B.arm[vk] = true
            if not blocked then
                grndBinderToggle(bind)
                break
            end
        end
    end
end

function grndBinderOnKeyMsg(isDown, wp, lp)
    local ok, eaten = pcall(function()
        local B = GRND_BINDER
        if not B or not B.loaded then return false end
        local vk = wp
        if type(grndShiftSideVK) == "function" then
            vk = grndShiftSideVK(wp, lp) or wp
        end
        if not vk or vk <= 0 or vk > 255 then return false end
        if B.binding then
            if isDown then grndBinderCaptureKey(vk) end
            return true
        end
        if not B.byKey or not B.byKey[vk] then return false end
        B.arm = B.arm or {}
        B.ate = B.ate or {}
        if isDown then
            -- В чате/поле ввода клавишу не трогаем: и вниз, и вверх должны
            -- дойти до игры, иначе кнопка «залипает».
            if grndBinderInputBlocked() then
                B.arm[vk] = true
                B.ate[vk] = false
                return false
            end
            if B.arm[vk] then
                return B.ate[vk] and true or false
            end
            B.arm[vk] = true
            B.ate[vk] = true
            grndBinderToggle(B.byKey[vk])
            return true
        end
        local ate = B.ate[vk]
        B.arm[vk] = nil
        B.ate[vk] = nil
        return ate and true or false
    end)
    if not ok then
        if not GRND_BINDER._keyErr then
            GRND_BINDER._keyErr = true
            print("{FF6666}[GRND]{FFFFFF} биндер/клавиша: " .. tostring(eaten))
        end
        return false
    end
    return eaten and true or false
end

function grndBinderOnWheel(wparam, lparam)
    local ok, eaten = pcall(function()
        local B = GRND_BINDER
        local r = B and B.listScreen
        if not r or (os.clock() - (r.at or 0)) > 0.4 then return false end
        local x, y
        if type(grndMouseXY) == "function" then
            x, y = grndMouseXY(lparam)
        elseif GRND_MOUSE then
            x, y = GRND_MOUSE.x, GRND_MOUSE.y
        end
        if not x or not y then return false end
        if x < r.x or x > r.x + r.w or y < r.y or y > r.y + r.h then return false end
        local wpRaw = tonumber(wparam) or 0
        local dRaw = math.floor(wpRaw / 65536) % 65536
        if dRaw >= 32768 then dRaw = dRaw - 65536 end
        local notch = (dRaw > 0 and 1) or (dRaw < 0 and -1) or 0
        if notch == 0 then return false end
        B.scroll = (B.scroll or 0) - notch * 34
        B.wheelStamp = os.clock()
        return true
    end)
    if not ok then return false end
    return eaten and true or false
end

function grndBinderOpenMenu()
    local menu = GRND_REF and GRND_REF.menu
    if not menu then
        grndBinderNote("Меню ещё не готово — подождите секунду", "warn")
        return
    end
    menu.open = true
    if type(MENU_TABS) == "table" then
        for i = 1, #MENU_TABS do
            if MENU_TABS[i].id == "binder" then
                menu.tab = i
                break
            end
        end
    end
    if type(_G.grndEnsureRender) == "function" then pcall(_G.grndEnsureRender, true) end
    if type(grndUiControls) == "function" then pcall(grndUiControls, true) end
end

function grndBinderRegisterCmd()
    local B = GRND_BINDER
    if B.cmdReg then return end
    if type(sampRegisterChatCommand) ~= "function" then return end
    B.cmdReg = true
    pcall(sampRegisterChatCommand, "binder", function(arg)
        local a = tostring(arg or ""):lower():gsub("%s+", "")
        if a == "stop" then
            if GRND_BINDER.running then grndBinderStop("cmd")
            else grndBinderNote("Сейчас ничего не отправляется", "info") end
            return
        end
        if a == "test" then
            grndBinderSelfTest()
            return
        end
        grndBinderOpenMenu()
    end)
end

function grndBinderHookTerm()
    local B = GRND_BINDER
    if B.termHooked or type(grndOnTerm) ~= "function" then return end
    B.termHooked = true
    grndOnTerm(function()
        if GRND_BINDER and GRND_BINDER.dirty then pcall(grndBinderSave) end
    end)
end

function grndBinderTick()
    local B = GRND_BINDER
    grndBinderLoad()
    grndBinderRegisterCmd()
    grndBinderHookTerm()
    if B.textActive and (os.clock() - (B.drewAt or 0)) > 0.45 then
        B.textActive = false
    end
    grndBinderPollKeys()
    grndBinderTickSend()
    if B.dirty and os.clock() >= (B.saveAt or 0) then
        grndBinderSave()
    end
end

function grndBinderFit(s, maxW, tsize)
    s = tostring(s or "")
    if s == "" then return s end
    if type(tsize) ~= "function" then
        local chars = {}
        for ch in s:gmatch("[%z\1-\127\194-\244][\128-\191]*") do
            chars[#chars + 1] = ch
            if #chars >= 16 then break end
        end
        if #chars >= 16 then return table.concat(chars, "", 1, 15) .. "…" end
        return s
    end
    local w = tsize(s)
    if type(w) ~= "number" then w = 0 end
    if w <= maxW then return s end
    local chars = {}
    for ch in s:gmatch("[%z\1-\127\194-\244][\128-\191]*") do
        chars[#chars + 1] = ch
    end
    local lo, hi, best = 1, #chars, "…"
    while lo <= hi do
        local mid = math.floor((lo + hi) / 2)
        local trial = table.concat(chars, "", 1, mid) .. "…"
        local tw = tsize(trial)
        if type(tw) ~= "number" then tw = maxW + 1 end
        if tw <= maxW then
            best = trial
            lo = mid + 1
        else
            hi = mid - 1
        end
    end
    return best
end

-- Пуш цветов с гарантированным Pop: несбалансированный стек ImGui
-- роняет все окна скрипта до конца кадра.
function grndBinderPushColors(im, cols)
    local n = 0
    if not (im and im.PushStyleColor and im.ImVec4) then return 0 end
    for i = 1, #cols do
        local c = cols[i]
        if c[1] ~= nil then
            local ok = pcall(im.PushStyleColor, c[1], im.ImVec4(
                c[2] / 255, c[3] / 255, c[4] / 255, c[5] / 255))
            if ok then n = n + 1 end
        end
    end
    return n
end

function grndBinderPopColors(im, n)
    if not n or n <= 0 or not (im and im.PopStyleColor) then return end
    if not pcall(im.PopStyleColor, n) then
        for _ = 1, n do pcall(im.PopStyleColor) end
    end
end

function grndBinderEditMulti(im, buf, cap, w, h)
    local B = GRND_BINDER
    if B.multiSig == 0 then return false, B.multiErr end
    if type(im.InputTextMultiline) ~= "function" then
        B.multiSig = 0
        B.multiErr = "нет InputTextMultiline"
        return false, B.multiErr
    end
    local sz = im.ImVec2(math.max(40, w), math.max(40, h))
    local function call(sig)
        if sig == 1 then return im.InputTextMultiline("##grnd_bind_edit", buf, cap, sz) end
        if sig == 2 then return im.InputTextMultiline("##grnd_bind_edit", buf, sz) end
        return im.InputTextMultiline("##grnd_bind_edit", buf, cap)
    end
    local sig = B.multiSig or 1
    local ok, a = pcall(call, sig)
    if ok then
        B.multiSig = sig
        B.multiLocked = true
        return true, a
    end
    if B.multiLocked then
        return false, B.multiErr or tostring(a)
    end
    for s = 1, 3 do
        if s ~= sig then
            local ok2, a2 = pcall(call, s)
            if ok2 then
                B.multiSig = s
                B.multiLocked = true
                return true, a2
            end
            a = a2
        end
    end
    B.multiSig = 0
    B.multiErr = tostring(a)
    B.multiLocked = true
    return false, B.multiErr
end

function grndBinderDraw(ctx)
    local ok, err = pcall(grndBinderDrawInner, ctx)
    if ok then return end
    GRND_BINDER.lastErr = tostring(err)
    local msg = grndUiErrLog("биндер", err)
    if ctx and type(ctx.uiText) == "function" then
        local col = (type(ctx.rgba) == "function") and ctx.rgba(255, 130, 130, 255) or nil
        pcall(ctx.uiText, (ctx.cardX or 16) + 12, (ctx.cardY or 16) + 14,
            "Ошибка биндера: " .. msg, col)
        pcall(ctx.uiText, (ctx.cardX or 16) + 12, (ctx.cardY or 16) + 32,
            "подробности в resource/grnd/logs/grnd_err.log",
            (type(ctx.rgba) == "function") and ctx.rgba(140, 148, 166, 255) or nil)
    end
end

function grndBinderDrawInner(ctx)
    if type(ctx) ~= "table" then return end
    local im, dl, at = ctx.im, ctx.dl, ctx.at
    local uiText, tsize, roundRect = ctx.uiText, ctx.tsize, ctx.roundRect
    local col32, rgba = ctx.col32, ctx.rgba
    if not (im and dl and at and uiText and roundRect and col32 and rgba) then return end
    local B = GRND_BINDER
    grndBinderLoad()
    B.drewAt = os.clock()

    local cardX, cardY = ctx.cardX or 0, ctx.cardY or 0
    local cardW, cardH = ctx.cardW or 400, ctx.cardH or 300
    local x0, y0 = cardX + 8, cardY + 8
    local innerW = math.max(200, cardW - 16)
    local innerH = math.max(160, cardH - 16)

    -- v1.14.17: своей панели больше нет — раздел лежит прямо на «карточке»
    -- окна, как и остальные вкладки (те же цвета, то же скругление 9).

    local listW = math.max(118, math.min(158, math.floor(innerW * 0.27)))
    local gap = 24
    local rightX = x0 + 8 + listW + gap
    local rightW = x0 + innerW - 8 - rightX
    if rightW < 160 then
        listW = 118
        rightX = x0 + 8 + listW + gap
        rightW = x0 + innerW - 8 - rightX
    end

    -- v1.14.17: единая сетка — все строки по 30 px с шагом 6, как в окне
    local btnH = 30
    local row1 = y0 + 8
    local actionsY = row1 + btnH + 6
    local row2 = actionsY + btnH + 14
    local row3 = row2 + btnH + 6
    local editY = row3 + btnH + 8
    local hintH = 18
    local bottom = y0 + innerH - 8
    local editH = bottom - editY - hintH
    if editH < 72 then
        hintH = 0
        editH = bottom - editY
    end
    if editH < 48 then editH = 48 end
    local listY = actionsY
    local listH = bottom - listY

    -- v1.14.17: кнопки — общие для всего окна (grndUiButton): «стекло»,
    -- скругление 9, акцентная рамка у выбранной. Ровные высоты ниже.
    local function gbtn(x, y, w, h, label, tag, selected, danger)
        return grndUiButton(ctx, "##gbd_" .. tag, x, y, w, h, label,
            { selected = selected, danger = danger, cutW = w - 12 })
    end

    -- Separate the navigation list, action header, parameters and text editor.
    local TH=grndUiTheme()
    local function hr(x1,x2,y)
        dl:AddRectFilled(at(x1,y),at(x2,y+1),col32(255,255,255,22))
    end
    local sepX=rightX-gap/2
    dl:AddRectFilled(at(sepX,row1),at(sepX+1,bottom),col32(255,255,255,24))
    hr(x0+8,x0+8+listW,row1+btnH+3)
    hr(rightX,rightX+rightW,actionsY+btnH+6)
    hr(rightX,rightX+rightW,editY-5)

    if gbtn(x0+8,row1,listW,btnH,"Добавить","add",false,false) then grndBinderAdd() end
    local cur=grndBinderSelected()
    local titleW=rightW
    if B.renaming and cur and grndBinderEnsureNameBuf(im) then
        if B.nameBufId~=cur.id then
            grndBinderWriteCBuf(B.nameBuf,B.nameCap or 96,cur.name or "")
            B.nameBufId=cur.id; B.renameFocus=false
        end
        -- Always size the input: the previous implicit width overlapped Delete.
        im.SetCursorPos(im.ImVec2(rightX,row1+3))
        if not B.renameFocus and im.SetKeyboardFocusHere then
            pcall(im.SetKeyboardFocusHere);B.renameFocus=true
        end
        local sized=false
        if im.PushItemWidth then sized=pcall(im.PushItemWidth,titleW) end
        local fl=im.InputTextFlags and im.InputTextFlags.EnterReturnsTrue or 0
        local pushed=grndBinderPushColors(im,{
            {im.Col and im.Col.FrameBg,TH.bg[1],TH.bg[2],TH.bg[3],255},
            {im.Col and im.Col.Text,TH.textHi[1],TH.textHi[2],TH.textHi[3],255}})
        local okN,retN=pcall(im.InputText,"##gbd_name",B.nameBuf,B.nameCap or 96,fl)
        B.nameActive=(im.IsItemActive and im.IsItemActive()) or (im.IsItemFocused and im.IsItemFocused()) or false
        grndBinderPopColors(im,pushed)
        if sized and im.PopItemWidth then pcall(im.PopItemWidth) end
        B.renameSeen=true
        if okN and retN and fl~=0 then grndBinderCommitRename() end
    else
        B.nameActive=false
        local shown=grndBinderFit(cur and cur.name or "Нет бинда",titleW-12,tsize)
        if gbtn(rightX,row1,titleW,btnH,shown,"title",false,false) and cur then
            grndBinderBeginRename(im)
        end
    end
    -- Visible actions, not a hidden click target. ESC also cancels via existing handler.
    local actionW=math.min(132,math.floor((rightW-8)/2))
    if B.renaming then
        if gbtn(rightX,actionsY,actionW,btnH,"Сохранить","rename_save",true,false) then
            grndBinderCommitRename()
        end
        if gbtn(rightX+actionW+8,actionsY,actionW,btnH,"Отмена","rename_cancel",false,false) then
            grndBinderOnEsc()
            B.nameActive=false;B.renameError=nil
        end
    else
        if gbtn(rightX,actionsY,actionW,btnH,"Переименовать","rename",false,false) and cur then
            grndBinderBeginRename(im)
        end
        if gbtn(rightX+actionW+8,actionsY,actionW,btnH,"Удалить","del",false,true) then
            if cur then grndBinderDelete(cur.id);cur=grndBinderSelected()
            else grndBinderNote("Нечего удалять","warn") end
        end
    end

    -- список
    local itemH, igap = 30, 6
    local stride = itemH + igap
    local contentH = math.max(0, #B.binds * stride - igap)
    local maxScroll = math.max(0, contentH - listH)
    if B.scrollToSel and cur then
        for i = 1, #B.binds do
            if B.binds[i].id == cur.id then
                local iy = (i - 1) * stride
                if iy < (B.scroll or 0) then B.scroll = iy
                elseif iy + itemH > (B.scroll or 0) + listH then
                    B.scroll = iy + itemH - listH
                end
                break
            end
        end
        B.scrollToSel = false
    end
    B.scroll = math.max(0, math.min(maxScroll, B.scroll or 0))

    local okWp, wp = pcall(im.GetWindowPos)
    if okWp and wp and wp.x then
        B.listScreen = {
            x = wp.x + x0 + 8, y = wp.y + listY,
            w = listW, h = listH, at = os.clock(),
        }
    end
    local wheel = 0
    if im.GetIO then
        local okIo, io = pcall(im.GetIO)
        if okIo and io then wheel = tonumber(io.MouseWheel) or 0 end
    end
    local mx, my = nil, nil
    if im.GetIO then
        local okIo, io = pcall(im.GetIO)
        if okIo and io and io.MousePos then mx, my = io.MousePos.x, io.MousePos.y end
    end
    if (not mx) and GRND_MOUSE then mx, my = GRND_MOUSE.x, GRND_MOUSE.y end
    local listHov = false
    if mx and B.listScreen then
        local r = B.listScreen
        listHov = mx >= r.x and mx <= r.x + r.w and my >= r.y and my <= r.y + r.h
    end
    if listHov and wheel ~= 0 and (os.clock() - (B.wheelStamp or 0)) > 0.05 then
        B.scroll = math.max(0, math.min(maxScroll, B.scroll - wheel * 34))
    end

    if dl.PushClipRect then
        pcall(dl.PushClipRect, dl, at(x0 + 8, listY), at(x0 + 8 + listW, listY + listH), true)
    end
    if #B.binds == 0 then
        uiText(x0 + 14, listY + 8, "Пусто", rgba(96, 104, 122, 200))
    end
    local first = math.floor((B.scroll or 0) / stride)
    local vis = math.ceil(listH / stride) + 2
    for i = first + 1, math.min(#B.binds, first + vis) do
        local b = B.binds[i]
        local iy = listY + (i - 1) * stride - (B.scroll or 0)
        if iy + itemH >= listY - 2 and iy <= listY + listH + 2 then
            local sel = cur and b.id == cur.id
            if gbtn(x0 + 8, iy, listW, itemH, b.name, "row" .. tostring(b.id), sel, false) then
                grndBinderSelect(b.id)
                cur = grndBinderSelected()
            end
            if sel then
                -- акцентная полоска слева, как у активной вкладки меню
                local ac = (GRND_UIKIT and GRND_UIKIT.TH or {}).accent or { 0, 214, 170, 255 }
                roundRect(dl, at(x0 + 8, iy + 6), at(x0 + 11, iy + itemH - 6),
                    col32(ac[1], ac[2], ac[3], 255), 2)
            end
            if B.running and B.runId == b.id then
                dl:AddCircleFilled(at(x0 + 18, iy + itemH / 2), 3.2, col32(255, 226, 90, 255))
            end
        end
    end
    if dl.PopClipRect then pcall(dl.PopClipRect, dl) end
    if contentH > listH + 1 then
        local trackX = x0 + 8 + listW - 4
        roundRect(dl, at(trackX, listY), at(trackX + 3, listY + listH), col32(255, 255, 255, 18), 2)
        local barH = math.max(16, listH * (listH / contentH))
        local barY = listY
        if maxScroll > 0 then
            barY = listY + (B.scroll / maxScroll) * (listH - barH)
        end
        local ac = (GRND_UIKIT and GRND_UIKIT.TH or {}).accent or { 0, 214, 170, 255 }
        roundRect(dl, at(trackX, barY), at(trackX + 3, barY + barH),
            col32(ac[1], ac[2], ac[3], 200), 2)
    end

    -- строка: счётчик, Выдать, слайдер, задержка
    cur = grndBinderSelected()
    local liveText = cur and (cur.text or "") or ""
    if cur and B.buf and B.bufBindId == cur.id then
        liveText = grndBinderReadBuf()
    end
    local nLines = cur and grndBinderCountLines(liveText) or 0
    local countLabel = "Строк в бинде: " .. tostring(nLines)
    uiText(rightX, row2 + 8, countLabel, rgba(198, 205, 219, 255))
    local countW = 132
    if tsize then
        local cw = tsize(countLabel)
        if type(cw) == "number" and cw > 20 then countW = cw end
    end
    local issueX = rightX + countW + 8
    local sendingThis = B.running and cur and B.runId == cur.id
    local issueLabel = sendingThis and "Стоп" or "Выдать"
    local issueW = 90
    if gbtn(issueX, row2, issueW, btnH, issueLabel, "issue", false, sendingThis) then
        grndBinderIssue()
    end

    local word = "Задержка"
    local wordW = 72
    if tsize then
        local ww = tsize(word)
        if type(ww) == "number" then wordW = ww end
    end
    local showWord = rightW > 390
    local valSample = cur and grndBinderFormatDelay(cur.delay) or "1.0 сек."
    local valW = 62
    if tsize then
        local vw = tsize(valSample)
        if type(vw) == "number" then valW = math.max(54, vw) end
    end
    local valX = rightX + rightW - valW
    if showWord then valX = valX - wordW - 8 end
    local slX = issueX + issueW + 10
    local slW = valX - slX - 8
    if slW < 36 then
        showWord = false
        valX = rightX + rightW - valW
        slW = valX - slX - 8
    end
    local delayMs = cur and grndBinderClampDelay(cur.delay) or 1000
    if cur and slW >= 28 then
        -- v1.14.17: общий слайдер окна (градиент акцента, белый кругляш)
        local nr = grndUiSlider(ctx, "##gbd_delay", slX, row2, slW, btnH,
            grndBinderMsToT(delayMs))
        if nr then
            local nms = grndBinderTToMs(nr)
            if nms ~= delayMs then
                cur.delay = nms
                delayMs = nms
                if B.running and B.runId == cur.id then
                    B.runDelay = nms / 1000
                end
                grndBinderTouch()
            end
        end
    end
    uiText(valX, row2 + 8, grndBinderFormatDelay(delayMs), rgba(233, 237, 246, 255))
    if showWord then
        uiText(valX + valW + 8, row2 + 8, word, rgba(140, 148, 166, 255))
    end

    -- клавиша активации
    local keyLabel
    if B.binding then
        keyLabel = "Нажмите клавишу..."
    elseif cur and cur.key and cur.key > 0 and type(grndKeyName) == "function" then
        keyLabel = grndKeyName(cur.key)
    elseif cur and cur.key and cur.key > 0 then
        keyLabel = string.format("0x%02X", cur.key)
    else
        keyLabel = "Не назначено"
    end
    local keyW = math.max(132, math.min(210, rightW * 0.42))
    if gbtn(rightX, row3, keyW, btnH, keyLabel, "key", B.binding, false) and cur then
        B.binding = not B.binding
        if B.binding then
            B.renaming = false
            if GRND_INVIS then GRND_INVIS.binding = false end
            if GRND_ABRK then GRND_ABRK.binding = false end
            if GRND_AREP then GRND_AREP.binding = false end
            if GRND_CATCH then GRND_CATCH.binding = false end
            if GRND_CHAT then GRND_CHAT.binding = false end
        end
    end
    uiText(rightX + keyW + 10, row3 + 8, "Клавиша активации", rgba(140, 148, 166, 255))

    local prog = ""
    if B.running then
        local sent = math.max(0, (B.runIndex or 1) - 1)
        local total = B.queue and #B.queue or 0
        local who = (cur and B.runId == cur.id) and "" or ("«" .. tostring(B.runName or "") .. "» ")
        prog = (B.hold and "пауза " or "отправка ") .. who .. sent .. "/" .. total
    end
    if prog ~= "" and tsize then
        local pw = tsize(prog)
        if type(pw) == "number" then
            local px = rightX + rightW - pw
            if px > rightX + keyW + 150 then
                uiText(px, row3 + 4, prog, rgba(255, 220, 110, 255))
            end
        end
    elseif prog ~= "" then
        uiText(rightX, row3 + 28, prog, rgba(255, 220, 110, 255))
    end

    -- поле текста (в стиле окна: тёмная врезка, тонкая светлая рамка)
    roundRect(dl, at(rightX, editY), at(rightX + rightW, editY + editH), col32(0, 0, 0, 70), 9)
    if dl.AddRect then
        pcall(dl.AddRect, dl, at(rightX + 0.5, editY + 0.5),
            at(rightX + rightW - 0.5, editY + editH - 0.5),
            col32(255, 255, 255, 22), 9, 0, 1)
    end

    local edited = false
    if cur and grndBinderEnsureBuf(im) then
        if B.bufBindId ~= cur.id then
            grndBinderWriteBuf(cur.text or "")
            B.bufBindId = cur.id
        end
        if B.focusEditor and im.SetKeyboardFocusHere then
            pcall(im.SetKeyboardFocusHere)
            B.focusEditor = false
        end
        local pushed = grndBinderPushColors(im, {
            { im.Col and im.Col.FrameBg, TH.bg[1], TH.bg[2], TH.bg[3], 255 },
            { im.Col and im.Col.FrameBgHovered, TH.sidebar[1], TH.sidebar[2], TH.sidebar[3], 255 },
            { im.Col and im.Col.FrameBgActive, TH.bg[1], TH.bg[2], TH.bg[3], 255 },
            { im.Col and im.Col.Text, 233, 237, 246, 255 },
            { im.Col and im.Col.Border, 255, 255, 255, 40 },
        })
        im.SetCursorPos(im.ImVec2(rightX + 4, editY + 4))
        local okM, errM = pcall(grndBinderEditMulti, im, B.buf, B.bufCap or 16384, rightW - 8, editH - 8)
        grndBinderPopColors(im, pushed)
        if not okM then
            B.lastErr = tostring(errM)
            okM = false
        else
            okM = errM
        end
        if okM then
            edited = true
            B.textActive = false
            if im.IsItemActive and im.IsItemActive() then B.textActive = true end
            if im.IsItemFocused and im.IsItemFocused() then B.textActive = true end
            local s = grndBinderReadBuf()
            if s ~= (cur.text or "") then
                cur.text = s
                grndBinderTouch()
            end
        end
    else
        B.textActive = false
    end

    if cur and not edited then
        -- запасной редактор: одна строка + кнопки, если многострочного поля нет
        local lines = {}
        local raw = tostring(cur.text or ""):gsub("\r\n", "\n"):gsub("\r", "\n")
        for line in (raw .. "\n"):gmatch("([^\n]*)\n") do
            lines[#lines + 1] = line
        end
        if #lines > 1 and lines[#lines] == "" then lines[#lines] = nil end
        local showN = math.min(#lines, math.max(1, math.floor((editH - 36) / 16)))
        for i = 1, showN do
            local s = lines[i]
            if #s > 80 then s = s:sub(1, 78) .. "…" end
            uiText(rightX + 8, editY + 4 + (i - 1) * 16, (s == "" and " " or s), rgba(198, 205, 219, 230), 0.9)
        end
        if B.multiErr and not B.multiErrShown then
            B.multiErrShown = true
            grndBinderNote("Поле текста: запасной режим (" .. tostring(B.multiErr) .. ")", "warn")
        end
        if grndBinderEnsureNameBuf(im) then
            -- отдельный буфер строки ввода, чтобы не затирать название
            if not B.lineBuf then
                local okL, lb = pcall(function() return im.new.char[160]() end)
                if okL and lb then B.lineBuf = lb end
            end
            if B.lineBuf then
                im.SetCursorPos(im.ImVec2(rightX + 4, editY + editH - 28))
                pcall(im.InputText, "##gbd_line", B.lineBuf, 144)
                local addX = rightX + rightW - 92
                if gbtn(addX, editY + editH - 28, 88, 24, "В конец", "addline", false, false) then
                    local piece = grndBinderReadCBuf(B.lineBuf)
                    piece = piece:gsub("[\r\n]", "")
                    if piece ~= "" then
                        if cur.text and cur.text ~= "" then
                            cur.text = cur.text .. "\n" .. piece
                        else
                            cur.text = piece
                        end
                        grndBinderWriteCBuf(B.lineBuf, 160, "")
                        B.bufBindId = nil
                        grndBinderTouch()
                        grndBinderSave()
                    end
                end
            end
        end
    elseif not cur then
        uiText(rightX + 12, editY + 12, "Нажмите «Добавить», чтобы создать бинд",
            rgba(140, 148, 166, 220))
        B.textActive = false
    end

    if hintH > 0 then
        local hint
        if B.renaming then
            hint = B.renameError or "Название: до 24 символов · Enter — сохранить · Esc — отмена"
        elseif B.binding then
            hint = "ESC — отмена, Backspace или DEL — сбросить клавишу"
        else
            hint = "Строка = сообщение на сервер · // комментарий · {myid} {mynick} {time}"
        end
        uiText(rightX, bottom - 16, hint, rgba(96, 104, 122, 210), 0.86)
    end
end

function grndBinderSelfTest()
    local fails = {}
    local function near(name, got, exp, eps)
        got, exp = tonumber(got), tonumber(exp)
        if not got or not exp or math.abs(got - exp) > (eps or 0.001) then
            fails[#fails + 1] = name .. " got=" .. tostring(got) .. " exp=" .. tostring(exp)
        end
    end
    local function eq(name, got, exp)
        if got ~= exp then
            fails[#fails + 1] = name .. " got=" .. tostring(got) .. " exp=" .. tostring(exp)
        end
    end
    near("min", grndBinderClampDelay(0), 0.5)
    near("max", grndBinderClampDelay(9000), 5000)
    near("nil", grndBinderClampDelay(nil), 1000)
    near("nan", grndBinderClampDelay(0/0), 1000)
    near("t0", grndBinderMsToT(0.5), 0, 0.0001)
    near("t1", grndBinderMsToT(5000), 1, 0.0001)
    near("back0", grndBinderTToMs(0), 0.5, 0.05)
    near("back1", grndBinderTToMs(1), 5000, 1)
    eq("fmt0", grndBinderFormatDelay(0.5), "0.5 мс")
    eq("fmt1", grndBinderFormatDelay(1000), "1.0 сек.")
    eq("fmt5", grndBinderFormatDelay(5000), "5.0 сек.")
    eq("fmt250", grndBinderFormatDelay(250), "250 мс")
    local lines = grndBinderCollectLines(" a \n\n// коммент\n/b\n   \nпривет")
    eq("n", #lines, 3)
    eq("l1", lines[1], "a")
    eq("l2", lines[2], "/b")
    eq("l3", lines[3], "привет")
    local sample = "a\\b\nстрока"
    eq("esc", grndBinderUnescape(grndBinderEscape(sample)), sample)
    local body = "v=1\nsel=2\nnext=3\n---\nid=2\nname="
        .. grndBinderEscape("Король М4") .. "\nkey=66\ndelay=0.5\ntext="
        .. grndBinderEscape("/a тест\n//x\nпривет") .. "\n---\n"
    local binds, sel = grndBinderParse(body)
    eq("parseN", #binds, 1)
    eq("parseName", binds[1].name, "Король М4")
    near("parseDelay", binds[1].delay, 0.5)
    eq("parseText", binds[1].text, "/a тест\n//x\nпривет")
    eq("parseSel", sel, 2)
    local cut, was = grndBinderUtf8Cut("привет", 3)
    eq("cut", cut, "при")
    eq("cutFlag", was, true)
    local msg
    if #fails == 0 then
        msg = "Биндер: проверка пройдена"
        print("{00FFAA}[GRND]{FFFFFF} " .. msg)
    else
        msg = "Биндер: ошибок " .. tostring(#fails)
        print("{FF6666}[GRND]{FFFFFF} " .. msg .. " | " .. table.concat(fails, " | "))
    end
    grndBinderNote(msg, #fails == 0 and "ok" or "error")
    return #fails == 0
end

-- =====================================================================
--  v1.14.17: ОБЩИЕ ЭЛЕМЕНТЫ ИНТЕРФЕЙСА (кнопка/слайдер в стиле окна).
--
--  Раньше биндер рисовал свои плоские зелёные кнопки, а остальные разделы —
--  «стеклянные» строки с акцентом темы. Теперь и биндер, и «Персонаж»
--  пользуются этими двумя помощниками, чтобы всё окно было в одном стиле.
-- =====================================================================
-- Rectangular reference-style switch. Hit area remains 46x24.
-- State is also encoded by position, not colour alone. No external textures.
function grndUiSwitchPaint(ctx, x, y, on, hovered, id, dt)
    local dl, at, col32, rect = ctx.dl, ctx.at, ctx.col32, ctx.roundRect
    local theme = GRND_UIKIT.TH
    local ac = theme.accent
    GRND_UIKIT.switchMotion = GRND_UIKIT.switchMotion or {}
    local cache = GRND_UIKIT.switchMotion
    local goal = on and 1 or 0
    local key = tostring(id or (tostring(x) .. ":" .. tostring(y)))
    local value = cache[key]
    if value == nil then value = goal end
    value = value + (goal - value) * math.min(1, math.max(0, dt or 0.016) * 18)
    cache[key] = value
    -- Inset visual track: 44x22, softly rounded corners rather than a pill.
    rect(dl, at(x+1,y+1), at(x+45,y+23), col32(ac[1],ac[2],ac[3],on and 17 or 7), 4)
    if dl.AddRect then
        pcall(dl.AddRect,dl,at(x+1.5,y+1.5),at(x+44.5,y+22.5),
            col32(ac[1],ac[2],ac[3],hovered and 220 or (on and 145 or 70)),4,0,1.2)
    end
    local kx = x + 5 + 22 * value
    rect(dl,at(kx,y+5),at(kx+14,y+19),
        col32(ac[1],ac[2],ac[3],math.floor(80+175*value)),3)
end

-- Sidebar styles: five preset swatches and a user RGB editor.
-- Flat light-grey brand asset in resource/grnd_logo.png (900 x 384 RGBA; caption is rendered separately as native UI text).
-- Texture creation is called only by the existing pre-frame/initialization hook.
GRND_BRAND_LOGO = {width=900,height=384}
function grndBrandLogoLoad(im)
    local L=GRND_BRAND_LOGO
    if L.tex and L.im==im then return true end
    if L.retryAt and os.clock()<L.retryAt then return false end
    local dirs={}
    local function add(dir)
        if type(dir)=="string" and dir~="" then
            dirs[#dirs+1]=(dir:gsub("[/\\]+$", ""))
        end
    end
    if type(thisScript)=="function" then
        pcall(function()
            local sc=thisScript()
            if sc then add(tostring(sc.path or ""):match("^(.*)[/\\]")) end
        end)
    end
    if type(this_script_dir)=="function" then
        local ok,dir=pcall(this_script_dir);if ok then add(dir) end
    end
    if type(getWorkingDirectory)=="function" then
        local ok,dir=pcall(getWorkingDirectory);if ok then add(dir) end
    end
    local sep=package.config:sub(1,1)
    local path,data
    for _,dir in ipairs(dirs) do
        local candidate=dir..sep.."resource"..sep.."grnd_logo.png"
        local ok,f=pcall(io.open,candidate,"rb")
        if ok and f then
            local read,bytes=pcall(f.read,f,"*a");pcall(f.close,f)
            if read and type(bytes)=="string" and #bytes>24 then
                path,data=candidate,bytes;break
            end
        end
    end
    if not data then
        L.error="resource/grnd_logo.png not found next to grnd_adm_tools.lua"
    else
        -- File loader is common to both wrappers; memory loading also handles
        -- non-ASCII install paths in builds where D3DX file loading rejects them.
        for _,name in ipairs({"CreateTextureFromFileInMemory","CreateTextureFromFile","LoadTextureFromFile"}) do
            if type(im[name])=="function" then
                local ok,tex
                if name=="CreateTextureFromFileInMemory" then
                    ok,tex=pcall(im[name],data,#data)
                else ok,tex=pcall(im[name],path) end
                if ok and tex and tex~=0 then
                    L.tex,L.im,L.path,L.error=tex,im,path,nil
                    return true
                end
            end
        end
        L.error="ImGui could not load resource/grnd_logo.png"
    end
    L.retryAt=os.clock()+2
    if not L.warned then
        L.warned=true
        print("[GRND UI] "..tostring(L.error).."; using text logo")
    end
    return false
end

function grndBrandLogoDraw(ctx)
    local L=GRND_BRAND_LOGO
    if not L.tex then return false end
    local im,dl=ctx.im,ctx.dl
    local width=math.min(ctx.w,ctx.h*L.width/L.height)
    local height=width*L.height/L.width
    local x=ctx.x+(ctx.w-width)/2
    local y=ctx.y+(ctx.h-height)/2
    if dl.AddImage then
        local alpha=math.floor(255*math.max(0,math.min(1,ctx.alpha or 1)))
        local ok=pcall(dl.AddImage,dl,L.tex,ctx.at(x,y),ctx.at(x+width,y+height),
            im.ImVec2(0,0),im.ImVec2(1,1),ctx.col32(255,255,255,alpha))
        if ok then return true end
    end
    return false
end

function grndUiStylePanel(ctx)
    local im,dl,at,rect,col = ctx.im,ctx.dl,ctx.at,ctx.roundRect,ctx.col32
    local U, x,y,w = GRND_UIKIT,ctx.x,ctx.y,ctx.w
    local function text(px,py,label,t,scale)
        ctx.uiText(px,py,label,ctx.rgba(t[1],t[2],t[3],t[4] or 255),scale)
    end
    local function save()
        U.styleDirty=false
        U.styleSavedAt=os.clock()
        local ok,result=pcall(grndCamCfgSave)
        U.styleSaveError = not (ok and result ~= false)
    end
    dl:AddRectFilled(at(x,y),at(x+w,y+1),col(255,255,255,20))
    local tw=ctx.tsize("Стиль")
    text(x+(w-tw)/2,y+13,"Стиль",U.TH.textHi)
    local size,gap=26,6
    local sx=x+(w-(6*size+5*gap))/2
    local by=y+39
    for i=1,6 do
        local bx=sx+(i-1)*(size+gap)
        local name=U.NAMES[i] or "custom"
        local ac=U.PALETTES[name].accent
        im.SetCursorPos(im.ImVec2(bx,by))
        if im.InvisibleButton("##style_footer_"..name,im.ImVec2(size,size)) then
            if name=="custom" then
                U.pickerOpen=not U.pickerOpen
                if U.pickerOpen then
                    U.setCustom(U.customRGB[1],U.customRGB[2],U.customRGB[3],true)
                end
            else
                U.apply(name)
                U.pickerOpen=false
            end
            save()
        end
        local hovered=im.IsItemHovered and im.IsItemHovered()
        rect(dl,at(bx,by),at(bx+size,by+size),col(ac[1],ac[2],ac[3],hovered and 245 or 195),4)
        if name=="custom" then
            -- Rainbow dots: no icon fonts or textures required.
            local colors={{240,91,103},{244,194,78},{91,199,150},{82,157,232},{181,109,227}}
            for j,c in ipairs(colors) do
                local angle=(j-1)*math.pi*2/5-math.pi/2
                dl:AddCircleFilled(at(bx+13+math.cos(angle)*7,by+13+math.sin(angle)*7),3,col(c[1],c[2],c[3],255))
            end
        else
            -- Small palette glyph, matching the sample's coloured tiles.
            if dl.AddCircle then
                pcall(dl.AddCircle,dl,at(bx+13,by+12),6,col(255,255,255,230),16,1.1)
            end
            for j=0,2 do
                local angle=math.pi+(j*math.pi/3)
                dl:AddCircleFilled(at(bx+13+math.cos(angle)*3.5,by+12+math.sin(angle)*3.5),1,col(255,255,255,245))
            end
            dl:AddCircleFilled(at(bx+15,by+16),2,col(ac[1],ac[2],ac[3],255))
        end
        if U.current==name then
            if dl.AddRect then pcall(dl.AddRect,dl,at(bx-1.5,by-1.5),at(bx+size+1.5,by+size+1.5),col(240,236,248,230),5,0,1) end
        end
        if hovered and im.BeginTooltip and im.EndTooltip and im.Text then
            im.BeginTooltip()
            im.Text(U.LABELS[name])
            im.EndTooltip()
        end
    end
    -- Keep footer height stable within the frame when the editor is toggled.
    if ctx.h>100 and U.pickerOpen then
        local rgb=U.customRGB
        local hex=string.format("#%02X%02X%02X",rgb[1],rgb[2],rgb[3])
        text(x,y+83,"Свой цвет",U.TH.textDim,0.9)
        text(x+w-ctx.tsize(hex),y+83,hex,U.TH.textHi)
        local dragging=false
        for i,label in ipairs({"R","G","B"}) do
            local ry=y+109+(i-1)*34
            text(x,ry+3,label,U.TH.textDim)
            local v,changed=ctx.slider(x+23,ry,w-61,rgb[i],0,255,1,"style_rgb_"..label)
            dragging=dragging or (im.IsItemActive and im.IsItemActive()) or false
            text(x+w-29,ry+3,tostring(rgb[i]),U.TH.textHi,0.9)
            if changed then
                rgb[i]=v
                U.setCustom(rgb[1],rgb[2],rgb[3],true)
                U.styleDirty=true
            end
        end
        if U.styleDirty and (not dragging or os.clock()-(U.styleSavedAt or 0)>0.25) then save() end
        im.SetCursorPos(im.ImVec2(x,y+219))
        if im.InvisibleButton("##style_done",im.ImVec2(w,25)) then
            U.pickerOpen=false
            save()
        end
        rect(dl,at(x,y+219),at(x+w,y+244),col(255,255,255,13),4)
        local label=U.styleSaveError and "Не удалось сохранить" or "Готово"
        text(x+(w-ctx.tsize(label))/2,y+224,label,U.TH.textHi,0.9)
    end
end

function grndUiTheme()
    return (GRND_UIKIT and GRND_UIKIT.TH) or {}
end

-- Кнопка в стиле окна: скругление 9, «стекло» 255/255/255, акцентная рамка
-- у выбранной, красноватый фон у danger. Возвращает clicked, hovered.
function grndUiButton(ctx, id, x, y, w, h, label, opts)
    opts = opts or {}
    local im, dl, at = ctx.im, ctx.dl, ctx.at
    local uiText, tsize, roundRect, col32 = ctx.uiText, ctx.tsize, ctx.roundRect, ctx.col32
    if not (im and dl and at and uiText and roundRect and col32) then return false, false end
    local TH = grndUiTheme()
    local shown = label
    if opts.cutW and type(grndBinderFit) == "function" and tsize then
        shown = grndBinderFit(label, opts.cutW, tsize)
    end
    im.SetCursorPos(im.ImVec2(x, y))
    local clicked = im.InvisibleButton(id, im.ImVec2(w, h)) and true or false
    local hov = (im.IsItemHovered and im.IsItemHovered()) or false
    -- opts.hover = true: вызывающий сам знает, что курсор на кнопке (своя
    -- проверка мыши). Тогда заливка здесь и слой подсветки у вызывающего
    -- берут ОДНО значение, и кнопка не мигает между двумя состояниями.
    if opts.hover == true then hov = true end
    local act = (im.IsItemActive and im.IsItemActive()) or false
    local ac = TH.accent or { 0, 214, 170, 255 }
    local bg, border
    if opts.danger then
        bg = (hov or act) and col32(255, 96, 96, 56) or col32(255, 96, 96, 34)
        border = col32(255, 96, 96, (hov or act) and 130 or 84)
    elseif opts.selected then
        bg = col32(ac[1], ac[2], ac[3], 38)
        border = col32(ac[1], ac[2], ac[3], 115)
    elseif act then
        bg = col32(255, 255, 255, 44)
        border = col32(255, 255, 255, 78)
    elseif hov then
        bg = col32(255, 255, 255, 34)
        border = col32(255, 255, 255, 66)
    else
        -- v1.19.06: спокойное состояние тоже должно читаться. Раньше заливка
        -- была 10/255 (≈4 %), и кнопка «пропадала», пока под неё не наведёшь
        -- курсор: единственной видимой частью оставался hoverLayer, а он
        -- рисуется только при наведении.
        bg = col32(255, 255, 255, 22)
        border = col32(255, 255, 255, 40)
    end
    roundRect(dl, at(x, y), at(x + w, y + h), bg, 6)
    if dl.AddRect then
        pcall(dl.AddRect, dl, at(x + 0.5, y + 0.5), at(x + w - 0.5, y + h - 0.5),
            border, 6, 0, 1)
    end
    local tw, th = 0, 14
    if tsize then
        local a, b = tsize(shown)
        tw = (type(a) == "number" and a) or 0
        th = (type(b) == "number" and b) or 14
    end
    local tx
    if opts.align == "left" then
        tx = x + 12
    else
        tx = x + math.max(4, (w - tw) / 2)
    end
    -- v1.19.03: подписи кнопок заметно ярче. Прежние тона темы (textHi/textDim)
    -- на тёмном «стекле» и мелком кегле читались тускло — просили ярче.
    local tc = opts.muted and { 216, 211, 234, 255 } or { 250, 248, 255, 255 }
    uiText(tx, y + (h - th) / 2, shown, ctx.rgba(tc[1], tc[2], tc[3], tc[4]))
    return clicked, hov
end

-- =====================================================================
--  НАСТРОЙКИ → АДМИН → КРУГ: 18 + 3 действий. Компактный список и
--  редактор активного слота: единый стиль с остальными вкладками.
-- =====================================================================
function grndRingUiFlush()
    local R = _G.GRND_TARGET_RING
    if not R or not R.uiBufSide or not R.uiNameBuf or not R.uiCmdBuf then return end
    local slot = grndRingSlot(R.uiBufSide, R.uiBufIndex)
    if not slot or type(grndBinderReadCBuf) ~= "function" then return end
    local name = grndRingClean(grndBinderReadCBuf(R.uiNameBuf), 32)
    local cmd = grndRingClean(grndBinderReadCBuf(R.uiCmdBuf), 144)
    if name ~= slot.name or cmd ~= slot.command then
        slot.name, slot.command = name, cmd
        grndRingTouch()
    end
end

local function grndRingUiSelect(side, i)
    local R = _G.GRND_TARGET_RING
    grndRingUiFlush()
    R.uiSide, R.uiIndex = side, i
    R.uiBufSide, R.uiBufIndex = nil, nil
    R.capture, R.uiStatus = nil, ""
    R.uiView = "editor"
end

function grndRingUiDraw(ctx)
    if type(ctx) ~= "table" then return false end
    local im, dl, at = ctx.im, ctx.dl, ctx.at
    local uiText, roundRect, col32 = ctx.uiText, ctx.roundRect, ctx.col32
    local tsize, rgba = ctx.tsize, ctx.rgba
    if not (im and dl and at and uiText and roundRect and col32 and rgba and tsize) then
        return false
    end
    grndRingLoad()
    local R = _G.GRND_TARGET_RING
    local TH = grndUiTheme()
    local accent = TH.accent or { 0, 214, 170, 255 }
    local px, py, width, height = ctx.cardX, ctx.cardY, ctx.cardW, ctx.cardH
    if width < 220 or height < 150 then return false end
    local ix, iw = px + 16, width - 32
    R.uiMode = R.uiMode == "vehicle" and "vehicle" or "player"
    R.uiSide = R.uiMode == "vehicle" and "vehicle"
        or (R.uiSide == "right" and "right" or "left")
    R.uiIndex = math.min(R.uiMode == "vehicle" and 3 or 9,
        math.max(1, tonumber(R.uiIndex) or 1))
    -- В узком меню список и редактор ВСЕГДА занимают всю ширину.
    -- Прежние два тесных блока в одной строке обрезали названия и поля.
    R.uiView = R.uiView == "editor" and "editor" or "list"

    roundRect(dl, at(px, py), at(px + width, py + height),
        col32(255, 255, 255, 10), 10)
    if dl.AddRect then
        pcall(dl.AddRect, dl, at(px + 0.5, py + 0.5),
            at(px + width - 0.5, py + height - 0.5),
            col32(255, 255, 255, 17), 10, 0, 1)
    end
    local function fit(text, widthLimit)
        if type(grndBinderFit) == "function" then
            return grndBinderFit(text, math.max(10, widthLimit), tsize)
        end
        return text
    end
    local function button(x, y, w, h, label, tag, selected, danger)
        if w < 15 then return false end
        return grndUiButton(ctx, "##grnd_ring_" .. tag, x, y, w, h,
            label, { selected = selected, danger = danger, cutW = w - 18 })
    end
    local tabGap = 8
    local tabW = math.floor((iw - tabGap) / 2)
    if button(ix, py + 12, tabW, 30, "Игроки · 18", "mode_players",
            R.uiMode == "player") then
        grndRingUiFlush()
        R.uiMode, R.uiSide, R.uiIndex = "player", "left", 1
        R.uiBufSide, R.capture, R.uiStatus, R.uiView = nil, nil, "", "list"
    end
    if button(ix + tabW + tabGap, py + 12, iw - tabW - tabGap, 30,
            "Транспорт · 3", "mode_vehicles", R.uiMode == "vehicle") then
        grndRingUiFlush()
        R.uiMode, R.uiSide, R.uiIndex = "vehicle", "vehicle", 1
        R.uiBufSide, R.capture, R.uiStatus, R.uiView = nil, nil, "", "list"
    end

    if R.uiView == "list" then
        local playerMode = R.uiMode == "player"
        local gap = 10
        local colW = math.floor((iw - gap) / 2)
        if playerMode then
            -- Заголовки привязаны к X своей колонки, а не выровнены
            -- пробелами (пропорциональный шрифт давал перекос).
            uiText(ix + 4, py + 53, "ЛЕВЫЙ РЯД", rgba(156, 173, 192, 255), 0.82)
            uiText(ix + colW + gap + 4, py + 53, "ПРАВЫЙ РЯД",
                rgba(156, 173, 192, 255), 0.82)
        else
            uiText(ix + 4, py + 53, "КОМАНДЫ ДЛЯ ТРАНСПОРТА",
                rgba(156, 173, 192, 255), 0.82)
        end
        local startY = py + 77
        local cap = playerMode and 9 or 3
        local rowStep = math.min(32, math.max(20,
            math.floor((height - 109) / cap)))
        local cellH = rowStep - 3
        local function slotCell(x, y, w, side, i)
            local slot = grndRingSlot(side, i)
            local id = "##grnd_ring_slot_" .. side .. "_" .. i
            im.SetCursorPos(im.ImVec2(x, y))
            local clicked = im.InvisibleButton(id, im.ImVec2(w, cellH))
            local hov = im.IsItemHovered and im.IsItemHovered() or false
            local selected = R.uiSide == side and R.uiIndex == i
            local bg = selected and col32(accent[1], accent[2], accent[3], 36)
                or col32(255, 255, 255, hov and 18 or 8)
            local border = selected and col32(accent[1], accent[2], accent[3], 120)
                or col32(255, 255, 255, hov and 40 or 16)
            roundRect(dl, at(x, y), at(x + w, y + cellH), bg, 7)
            if dl.AddRect then
                pcall(dl.AddRect, dl, at(x + 0.5, y + 0.5),
                    at(x + w - 0.5, y + cellH - 0.5), border, 7, 0, 1)
            end
            local key = grndRingKeyLabel(slot)
            local keyW = 0
            if key ~= "" then
                keyW = math.min(math.floor(w * 0.43), math.max(36,
                    math.floor((tsize(key) or 0) + 15)))
                local chipX = x + w - keyW - 7
                roundRect(dl, at(chipX, y + 3), at(x + w - 5, y + cellH - 3),
                    col32(accent[1], accent[2], accent[3], 33), 5)
                uiText(chipX + 6, y + (cellH - 14) / 2,
                    fit(key, keyW - 12), rgba(accent[1], accent[2], accent[3], 255), 0.79)
            end
            uiText(x + 10, y + (cellH - 14) / 2,
                string.format("%02d", i), rgba(156, 173, 192, 255), 0.8)
            local name = slot.name ~= "" and slot.name or "Настроить слот"
            local room = w - 43 - (keyW > 0 and keyW + 6 or 0)
            uiText(x + 36, y + (cellH - 14) / 2,
                fit(name, room), slot.name ~= "" and rgba(235, 241, 249, 255)
                    or rgba(148, 159, 176, 255), 0.86)
            if clicked then grndRingUiSelect(side, i) end
        end
        for i = 1, cap do
            local y = startY + (i - 1) * rowStep
            if y + cellH <= py + height - 24 then
                slotCell(ix, y, playerMode and colW or iw,
                    playerMode and "left" or "vehicle", i)
                if playerMode then
                    slotCell(ix + colW + gap, y, iw - colW - gap, "right", i)
                end
            end
        end
        local hint = playerMode
            and "При нажатии к команде добавится ID игрока на линии"
            or "При нажатии к команде добавится SA-MP ID машины"
        uiText(ix + 4, py + height - 20, fit(hint, iw - 8),
            rgba(153, 167, 184, 255), 0.8)
        return true
    end

    -- Редактор одного слота на всю ширину карточки.
    local side, i = R.uiSide, R.uiIndex
    local slot = grndRingSlot(side, i)
    if not slot then return false end
    local backW, backH = math.min(118, math.floor(iw * 0.28)), 27
    if button(ix + iw - backW, py + 51, backW, backH,
            "← К списку", "back") then
        grndRingUiFlush()
        R.uiView, R.capture = "list", nil
        return true
    end
    local heading = side == "vehicle" and "Транспорт"
        or (side == "right" and "Правый ряд" or "Левый ряд")
    uiText(ix + 3, py + 54,
        fit(string.format("%s · слот %02d", heading, i), iw - backW - 18),
        rgba(236, 242, 249, 255), 1)
    local compact = height < 355
    local nameY = py + (compact and 84 or 97)
    local cmdY = py + (compact and 143 or 164)
    local keyY = py + (compact and 201 or 231)
    local bindY = py + (compact and 221 or 252)
    local previewLabelY = py + (compact and 255 or 306)
    local previewY = py + (compact and 275 or 329)
    local statusY = py + (compact and 295 or 362)

    if (not R.uiNameBuf or R.uiIm ~= im) and im.new and im.new.char then
        local okN, nb = pcall(function() return im.new.char[128]() end)
        local okC, cb = pcall(function() return im.new.char[384]() end)
        if okN and nb and okC and cb then
            R.uiNameBuf, R.uiCmdBuf = nb, cb
            R.uiIm, R.uiBufSide, R.uiBufIndex = im, nil, nil
        end
    end
    local canInput = R.uiNameBuf and R.uiCmdBuf
        and type(grndBinderWriteCBuf) == "function"
        and type(grndBinderReadCBuf) == "function"
        and type(im.InputText) == "function"
    if canInput then
        if R.uiBufSide ~= side or R.uiBufIndex ~= i then
            grndRingUiFlush()
            grndBinderWriteCBuf(R.uiNameBuf, 128, slot.name or "")
            grndBinderWriteCBuf(R.uiCmdBuf, 384, slot.command or "")
            R.uiBufSide, R.uiBufIndex = side, i
        end
        local function input(id, buf, cap, y, placeholder)
            im.SetCursorPos(im.ImVec2(ix, y))
            if type(im.PushItemWidth) == "function" then
                pcall(im.PushItemWidth, iw)
            end
            local styled = 0
            if type(grndBinderPushColors) == "function" then
                styled = grndBinderPushColors(im, {
                    { im.Col and im.Col.FrameBg, 12, 17, 24, 255 },
                    { im.Col and im.Col.Text, 237, 243, 249, 255 },
                })
            end
            if type(im.InputTextWithHint) == "function" then
                pcall(im.InputTextWithHint, id, placeholder, buf, cap)
            else
                pcall(im.InputText, id, buf, cap)
            end
            if styled > 0 and type(grndBinderPopColors) == "function" then
                grndBinderPopColors(im, styled)
            end
            if type(im.PopItemWidth) == "function" then pcall(im.PopItemWidth) end
        end
        uiText(ix, nameY, "НАЗВАНИЕ НА КРУГЕ", rgba(164, 181, 200, 255), 0.82)
        input("##grnd_ring_name", R.uiNameBuf, 128, nameY + 19,
            "Например: Телепорт к игроку")
        uiText(ix, cmdY, "КОМАНДА БЕЗ ID", rgba(164, 181, 200, 255), 0.82)
        input("##grnd_ring_cmd", R.uiCmdBuf, 384, cmdY + 19,
            "/gethere")
        grndRingUiFlush()
    else
        uiText(ix, nameY, "Ввод текста ImGui недоступен",
            rgba(255, 130, 130, 255), 0.9)
    end
    uiText(ix, keyY, "ГОРЯЧАЯ КЛАВИША", rgba(164, 181, 200, 255), 0.82)
    local capturing = R.capture and R.capture.side == side and R.capture.index == i
    local bindLabel = capturing and "Нажмите сочетание…"
        or ((slot.key or 0) > 0 and grndRingKeyLabel(slot)
            or "+ Назначить клавишу")
    local bindW = math.floor((iw - 8) * 0.65)
    if button(ix, bindY, bindW, 29, bindLabel, "capture", capturing) then
        R.capture = capturing and nil or { side = side, index = i }
        if R.capture and _G.GRND_BINDER then GRND_BINDER.binding = false end
        R.uiStatus = R.capture and "Нажмите клавишу с Ctrl, Alt или Shift"
            or "Назначение отменено"
    end
    if button(ix + bindW + 8, bindY, iw - bindW - 8, 29,
            "Очистить", "clear") then
        grndRingBind(side, i, 0, 0)
        R.capture = nil
        R.uiStatus = "Клавиша очищена"
    end
    local liveCmd = grndRingClean(slot.command, 144)
    local badCommand = liveCmd ~= "" and not liveCmd:match("^/[%w_]+")
    local kind = R.uiMode == "vehicle" and "vehicle" or "player"
    local source, suffix, syntaxErr = grndRingCommandParts(liveCmd, "<ID>", kind)
    local tooLong = false
    if not badCommand and not syntaxErr and liveCmd ~= "" then
        -- Проверяем длину с максимальным настоящим ID, не с текстом <ID>.
        local samplePrefix, sampleSuffix = grndRingCommandParts(liveCmd, 1003, kind)
        local encoded = samplePrefix
        if type(grndAnsiText) == "function" then
            local ok, val = pcall(grndAnsiText, samplePrefix)
            if ok and type(val) == "string" then encoded = val end
        end
        tooLong = #encoded + #sampleSuffix > 127
    end
    local example = badCommand and "Ошибка: команда должна начинаться с /"
        or syntaxErr and ("Ошибка: " .. syntaxErr)
        or tooLong and "Слишком длинная команда: сократите для ID"
        or liveCmd ~= "" and (source .. suffix)
        or "Например: /gethere <ID>"
    uiText(ix, previewLabelY, "ИТОГОВАЯ КОМАНДА",
        rgba(accent[1], accent[2], accent[3], 255), 0.82)
    uiText(ix, previewY, fit(example, iw - 4),
        (badCommand or syntaxErr or tooLong) and rgba(255, 130, 130, 255)
            or rgba(235, 241, 249, 255), 0.92)
    local status = R.uiStatus or ""
    if status == "" and R.lastSentLine then
        status = "Последняя отправка: " .. R.lastSentLine
    end
    if status == "" then status = "ID — в конец; исключение: /hp ID 100" end
    if statusY + 14 < py + height then
        uiText(ix, statusY, fit(status, iw - 4),
            rgba(153, 167, 184, 255), 0.77)
    end
    return true
end

-- Горизонтальный слайдер в стиле окна: дорожка «стекло», заливка градиентом
-- акцента, белый кругляш. ratio 0..1; возвращает новый ratio во время тяги.
function grndUiSlider(ctx, id, x, y, w, h, ratio)
    local im, dl, at = ctx.im, ctx.dl, ctx.at
    local col32, roundRect = ctx.col32, ctx.roundRect
    if not (im and dl and at and col32 and roundRect) then return nil end
    local TH = grndUiTheme()
    -- ВАЖНО: в draw-лист цвета идут ЧИСЛОМ (col32), а не таблицей ImVec4 —
    -- rgba/c4 в меню возвращают ImVec4 только для uiText.
    local function u32(t) return col32(t[1], t[2], t[3], t[4] or 255) end
    ratio = math.max(0, math.min(1, ratio or 0))
    local ty = y + h / 2
    roundRect(dl, at(x, ty - 3), at(x + w, ty + 3), col32(255, 255, 255, 14), 3)
    local fw = math.max(4, w * ratio)
    if ctx.gradRect and TH.accent and TH.accent2 then
        ctx.gradRect(dl, at(x, ty - 3), at(x + fw, ty + 3), u32(TH.accent), u32(TH.accent2), 3)
    else
        roundRect(dl, at(x, ty - 3), at(x + fw, ty + 3), col32(0, 214, 170, 255), 3)
    end
    im.SetCursorPos(im.ImVec2(x - 4, y))
    im.InvisibleButton(id, im.ImVec2(w + 8, h))
    local act = (im.IsItemActive and im.IsItemActive()) or false
    local newRatio = nil
    if act then
        local mx = nil
        if im.GetIO then
            local okIo, io = pcall(im.GetIO)
            if okIo and io and io.MousePos then mx = io.MousePos.x end
        end
        if (not mx) and GRND_MOUSE then mx = GRND_MOUSE.x end
        if mx then
            -- экранные координаты дорожки
            local okWp, wp = pcall(im.GetWindowPos)
            if okWp and wp and wp.x then
                local f = (mx - (wp.x + x)) / math.max(1, w)
                newRatio = math.max(0, math.min(1, f))
            end
        end
    end
    local kx = x + w * ratio
    roundRect(dl, at(kx-5,ty-7), at(kx+5,ty+7), u32(TH.accent), 3)
    return newRatio
end

-- =====================================================================
--  v1.14.17: ВКЛАДКА «ПЕРСОНАЖ».
--
--  Состав — как в референсе, но в стиле этого окна:
--    * «Настройка погоды и времени» — два слайдера с точными +/-;
--      крайняя левая позиция = серверная погода/серверное время;
--    * «Выдача себе» — /hp без аргументов, /arm <мой ID> 100,
--      починить т/с; у ХП и брони нет дополнительных настроек;
--    * «Телепорты» — вкладки «Создать»/«Поиск», список сохранённых точек
--      (клик — телепорт, карандаш — редактор, корзина — удалить) и
--      редактор X/Y/Z с «Внести текущие координаты».
--
--  Значения и точки живут в grnd_char.cfg (формат как у конфига биндера).
--  Телепорт — клиентский, теми же функциями, что и ClickWarp.
--  Выдача себе — /hp без ID; /arm и /fixcar с ID первой строки TAB.
-- =====================================================================
GRND_CHAR = GRND_CHAR or {
    loaded = false,
    weather = 1,
    hour = 12,
    -- Значение ползунков «Серверная/Серверное» по умолчанию.
    weatherOn = false,
    hourOn = false,
    -- Старые значения из grnd_char.cfg храним для совместимости, но
    -- кнопки теперь имеют фиксированный синтаксис и их не используют.
    hpVal = 100,
    armVal = 100,
    tpTab = "create",
    tpQuery = "",
    tpScroll = 0,
    tpEdit = nil,
    points = {},
    dirty = false,
    saveAt = 0,
}

function grndCharCfgPath()
    if type(this_script_dir) == "function" then
        local ok, sd = pcall(this_script_dir)
        if ok and sd and tostring(sd) ~= "" then
            local pp = tostring(sd)
            while pp:sub(-1) == "/" or pp:sub(-1) == "\\" do pp = pp:sub(1, -2) end
            local sep = "\\"
            local okc, cf = pcall(function() return package.config end)
            if okc and type(cf) == "string" and #cf > 0 then sep = cf:sub(1, 1) end
            return pp .. sep .. "grnd_char.cfg"
        end
    end
    return "grnd_char.cfg"
end

-- В SA 1.0 обычные погоды только 0..19. 20 — подводная, 21+
-- экспериментальные/служебные; 46+ могут делать кадр красным/пустым.
-- Старый grnd_char.cfg мог сохранить ID до 100: вместо верхней границы
-- ставим безопасную ясную погоду 1, не подменяем её на песчаную бурю 19.
function grndCharSafeWeather(w)
    local n = tonumber(w)
    if not n or n ~= n or n < 0 or n >= 20 then return 1 end
    return math.floor(n)
end

local GRND_CHAR_SEED = false
function grndCharGenId()
    if not GRND_CHAR_SEED then
        math.randomseed((os.time() % 100000) + math.floor(os.clock() * 1000))
        GRND_CHAR_SEED = true
    end
    local chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
    for _ = 1, 8 do
        local s = {}
        for i = 1, 8 do
            local k = math.random(1, #chars)
            s[i] = chars:sub(k, k)
        end
        local id = table.concat(s)
        local dup = false
        for _, p in ipairs(GRND_CHAR.points) do
            if p.id == id then dup = true; break end
        end
        if not dup then return id end
    end
    return tostring(os.clock()):gsub("%D", ""):sub(1, 8)
end

function grndCharSerialize()
    local C = GRND_CHAR
    -- v2: при первом запуске новой шкалы старый v1 сбрасывает погодный
    -- и временной override к серверу. Следующие выборы хранятся как обычно.
    local out = { "v=2" }
    out[#out + 1] = "weather=" .. tostring(grndCharSafeWeather(C.weather))
    out[#out + 1] = "hour=" .. tostring(math.floor(C.hour or 12))
    out[#out + 1] = "hp=" .. tostring(math.max(1,
        math.min(100, math.floor(tonumber(C.hpVal) or 100))))
    out[#out + 1] = "arm=" .. tostring(math.floor(C.armVal or 100))
    out[#out + 1] = "wOn=" .. (C.weatherOn and "1" or "0")
    out[#out + 1] = "hOn=" .. (C.hourOn and "1" or "0")
    for i = 1, #C.points do
        local p = C.points[i]
        out[#out + 1] = "---"
        out[#out + 1] = "id=" .. tostring(p.id or "")
        out[#out + 1] = "name=" .. grndBinderEscape(p.name or "")
        out[#out + 1] = ("x=%.3f"):format(tonumber(p.x) or 0)
        out[#out + 1] = ("y=%.3f"):format(tonumber(p.y) or 0)
        out[#out + 1] = ("z=%.3f"):format(tonumber(p.z) or 0)
    end
    return table.concat(out, "\n") .. "\n"
end

function grndCharParse(body)
    local pts, vals, cur = {}, {}, nil
    for line in tostring(body or ""):gmatch("[^\r\n]+") do
        if line == "---" then
            if cur then pts[#pts + 1] = cur end
            cur = {}
        else
            local k, v = line:match("^([%w_]+)=(.*)$")
            if k then
                if cur then cur[k] = v else vals[k] = v end
            end
        end
    end
    if cur then pts[#pts + 1] = cur end
    local points = {}
    for _, raw in ipairs(pts) do
        local id = tostring(raw.id or "")
        if id ~= "" then
            points[#points + 1] = {
                id = id,
                name = grndBinderUnescape(raw.name or ""),
                x = tonumber(raw.x) or 0,
                y = tonumber(raw.y) or 0,
                z = tonumber(raw.z) or 0,
            }
        end
    end
    return points, vals
end

function grndCharLoad()
    local C = GRND_CHAR
    if C.loaded then return end
    C.loaded = true
    local ok, f = pcall(GRND_CONFIG.open, grndCharCfgPath(), "r")
    if ok and f then
        local body = f:read("*a") or ""
        pcall(function() f:close() end)
        local points, vals = grndCharParse(body)
        C.points = points
        C.weather = grndCharSafeWeather(vals.weather or C.weather)
        C.hour = math.max(0, math.min(23, tonumber(vals.hour) or C.hour))
        C.hpVal = math.max(1, math.min(100, math.floor(tonumber(vals.hp) or C.hpVal)))
        C.armVal = math.max(0, math.min(100, tonumber(vals.arm) or C.armVal))
        local oldWeatherOn, oldHourOn = (vals.wOn == "1"), (vals.hOn == "1")
        local legacy = vals.v ~= "2"
        local invalidWeather = vals.weather and tonumber(vals.weather) ~= C.weather
        local invalidHp = vals.hp and tonumber(vals.hp) ~= C.hpVal
        -- Однократный переход v1 -> v2: новый крайний пункт шкалы
        -- «Серверная/Серверное» становится режимом по умолчанию. Числа,
        -- телепорты и выдача себе сохраняются; прочее не затрагиваем.
        C.weatherOn = (not legacy) and oldWeatherOn
        C.hourOn = (not legacy) and oldHourOn
        if legacy then
            if oldWeatherOn then grndCharReleaseWeather() end
            if oldHourOn then grndCharUnfreezeTime() end
            C.hLastApplied = nil
        elseif invalidWeather and C.weatherOn then
            -- На случай старого небезопасного ID в повреждённом v2-конфиге.
            grndCharReleaseWeather()
        end
        if legacy or invalidWeather or invalidHp then grndCharSave() end
    end
end

function grndCharSave()
    local C = GRND_CHAR
    local ok, f = pcall(GRND_CONFIG.open, grndCharCfgPath(), "w")
    if not ok or not f then
        C.dirty = true
        C.saveAt = os.clock() + 2
        return false
    end
    pcall(function()
        f:write(grndCharSerialize())
        f:close()
    end)
    C.dirty = false
    return true
end

function grndCharTouch()
    local C = GRND_CHAR
    C.dirty = true
    C.saveAt = os.clock() + 0.8
end

-- ---------- погода/время: только клиентская смена (SA-MP) ----------
-- При включённом override значения держатся каждый кадр (wait(0)).
-- Крайний левый пункт обеих шкал — сервер; справа от него 0, 1, ...
function grndCharApplyWeather(w)
    w = grndCharSafeWeather(w)
    -- Используем один проверенный opcode 01B6. Ранее код ещё записывал
    -- ОДИН байт в 0xC81318, но этот адрес — двухбайтовый weather lock:
    -- высокий байт мог остаться от старого ID и порождать битую погоду.
    -- setWeather/setGameWeather не входят в стандартный API MoonLoader.
    if type(forceWeatherNow) == "function" then pcall(forceWeatherNow, w) end
end

function grndCharReleaseWeather()
    -- opcode 01B7 снимает принудительную погоду после нажатия «×».
    if type(releaseWeather) == "function" then pcall(releaseWeather) end
end

function grndCharApplyTime(h)
    h = math.floor(h or 0)
    -- 00C0 — реальная функция MoonLoader для игрового времени.
    -- setGameTime/setTime в стандартном API нет: предыдущие вызовы ничего
    -- не делали, только byte-записи срабатывали.
    if type(setTimeOfDay) == "function" then pcall(setTimeOfDay, h, 0) end
    -- CClock (GTA SA 1.0): байт часа 0xB70153, минуты 0xB70152.
    grndCharMemWrite8(0x00B70153, h)
    grndCharMemWrite8(0x00B70152, 0)
    -- Ход часов стоит, минутный таймер штатно возвращаем на «×».
    grndCharMemWriteInt32(0x00B7015C, 2000000000)
    -- Не трогаем память timecycle/цветов. Цвет определяется только
    -- штатной парой «время + обычная погода» игры.
    GRND_CHAR.hLastApplied = h
end

-- вернуть обычный ход часов (1 игровая минута = 1000 мс)
function grndCharUnfreezeTime()
    grndCharMemWriteInt32(0x00B7015C, 1000)
end

-- Единая точка управления для слайдера и кнопок +/-.
-- -1 означает «Серверная/Серверное», 0..19/23 — своё значение.
function grndCharSelectWeather(value)
    local C = GRND_CHAR
    local n = math.floor(tonumber(value) or -1)
    if n < 0 then
        if C.weatherOn then
            C.weatherOn = false
            grndCharReleaseWeather()
            grndCharTouch()
        end
    else
        n = grndCharSafeWeather(n)
        if not C.weatherOn or C.weather ~= n then
            C.weather = n
            C.weatherOn = true
            grndCharApplyWeather(n)
            grndCharTouch()
        end
    end
end

function grndCharSelectTime(value)
    local C = GRND_CHAR
    local n = math.floor(tonumber(value) or -1)
    if n < 0 then
        if C.hourOn then
            C.hourOn = false
            grndCharUnfreezeTime()
            C.hLastApplied = nil
            grndCharTouch()
        end
    else
        n = math.max(0, math.min(23, n))
        if not C.hourOn or C.hour ~= n then
            C.hour = n
            C.hourOn = true
            grndCharApplyTime(n)
            grndCharTouch()
        end
    end
end

-- dword в память игры: setint32 / setuint32 / write+размер
function grndCharMemWriteInt32(addr, v)
    if type(memory) ~= "table" then return false end
    local fn = memory.setint32 or memory.setuint32 or memory.write
    if type(fn) ~= "function" then return false end
    local ok = pcall(fn, addr, v, 4)
    if not ok then ok = pcall(fn, addr, v) end
    return ok
end

-- байт в память игры; moonloader-библиотека memory называется по-разному
-- (setint8/writeint8/setbyte/writebyte/write) — берём первую найденную.
-- Лишний аргумент размера setint8 просто игнорирует, memory.write он нужен.
function grndCharMemWrite8(addr, v)
    if type(memory) ~= "table" then return false end
    local fn = memory.setint8 or memory.writeint8 or memory.setbyte
        or memory.writebyte or memory.write
    if type(fn) ~= "function" then return false end
    local ok = pcall(fn, addr, v, 1)
    if not ok then ok = pcall(fn, addr, v) end
    return ok
end

-- v1.14.26: закрепление КАЖДЫЙ кадр (поток на wait(0)). Раньше контроль
-- был раз в 2 с — сервер успевал поставить своё время/погоду, и кадр с
-- чужим значением отрисовывался: отсюда дёргание. Теперь наши значения
-- пишутся каждый кадр и чужие просто не успевают появиться на экране.
function grndCharApplyTick()
    local C = GRND_CHAR
    if not C.loaded then grndCharLoad() end
    -- Защита и при горячей перезагрузке: старый C.weather мог быть 100.
    local safe = grndCharSafeWeather(C.weather)
    if safe ~= C.weather then C.weather = safe; grndCharTouch() end
    if C.weatherOn then grndCharApplyWeather(safe) end
    if C.hourOn then
        if C.hour ~= C.hLastApplied then
            -- полное применение (функции, заморозка) — при
            -- включении/смене значения
            grndCharApplyTime(C.hour)
        else
            -- закрепление времени: байты каждый кадр, дёргаться нечему
            grndCharMemWrite8(0x00B70153, C.hour)
            grndCharMemWrite8(0x00B70152, 0)
        end
    end
end

if not GRND_CHAR.threadStarted then
    GRND_CHAR.threadStarted = true
    if lua_thread and type(lua_thread.create) == "function" then
        local okT = pcall(lua_thread.create, function()
            while true do
                wait(0)
                pcall(grndCharApplyTick)
            end
        end)
        if not okT then GRND_CHAR.threadStarted = false end
    end
end

-- ---------- выдача себе: серверные команды ----------
function grndCharMyId()
    -- Свежая первая строка нашего TAB с пометкой localp; helper TAB
    -- дополнительно сверяет ID персонажа с SA-MP, чтобы не взять чужого.
    if type(grndTabFirstLocalId) ~= "function" then return nil end
    local ok, id = pcall(grndTabFirstLocalId)
    if ok and type(id) == "number" and id >= 0 and id < 1004
        and id == math.floor(id) then return id end
    return nil
end
function grndCharSelfHp()
    -- Команда сервера сама определяет, кому дать ХП. Ни ID, ни число
    -- после /hp не дописываем и TAB для этого не опрашиваем.
    if type(sampSendChat) == "function" then
        sampSendChat("/hp")
        pcall(notify.add, "Отправлена команда /hp", "ok", 2)
    end
end
function grndCharSelfArm()
    -- TAB обновляется при каждом клике, первая строка — только наш игрок.
    local id = grndCharMyId()
    if id == nil then
        pcall(notify.add, "Броня: ваш ID не подтверждён в TAB", "warn", 3)
        return
    end
    if type(sampSendChat) == "function" then
        sampSendChat("/arm " .. id .. " 100")
        pcall(notify.add, "Отправлена команда /arm " .. id .. " 100", "ok", 2)
    end
end
function grndCharSelfFix()
    -- Та же актуальная первая строка TAB, что и для выдачи брони.
    local id = grndCharMyId()
    if id == nil then
        pcall(notify.add, "Ремонт: ваш ID не подтверждён в TAB", "warn", 3)
        return
    end
    if type(sampSendChat) == "function" then
        sampSendChat("/fixcar " .. id)
        pcall(notify.add, "Отправлена команда /fixcar " .. id, "ok", 2)
    end
end

-- ---------- телепорт (клиентский, как ClickWarp) ----------
function grndCharGetPos()
    if type(getCharCoordinates) ~= "function" then return nil end
    local ok, x, y, z = pcall(getCharCoordinates, PLAYER_PED)
    if ok and type(x) == "number" and type(y) == "number" and type(z) == "number" then
        return x, y, z
    end
    return nil
end

function grndCharSurfaceZ(x, y, zHint)
    zHint = tonumber(zHint) or 0
    if type(processLineOfSight) == "function" then
        local okL, hit, col = pcall(processLineOfSight,
            x, y, zHint + 60.0, x, y, zHint - 60.0,
            true, true, false, true, false, false, false, false)
        if okL and hit and type(col) == "table" and type(col.pos) == "table"
            and type(col.pos[3]) == "number" then
            return col.pos[3]
        end
    end
    if type(getGroundZFor3dCoord) == "function" then
        local ok, z = pcall(getGroundZFor3dCoord, x, y, 50.0, 0, 1)
        if ok and type(z) == "number" and z ~= 0 then return z end
    end
    if type(getGroundZForCoord) == "function" then
        local ok, z = pcall(getGroundZForCoord, x, y)
        if ok and type(z) == "number" and z ~= 0 then return z end
    end
    return nil
end

function grndCharWarp(x, y, z)
    x, y, z = tonumber(x), tonumber(y), tonumber(z)
    if not (x and y and z) then return false end
    if type(grndIsSpawned) == "function" and not grndIsSpawned() then
        pcall(notify.add, "Телепорт: вы ещё не заспавнены", "warn", 3)
        return false
    end
    local okIn, inCar = false, false
    if type(isCharInAnyCar) == "function" then
        okIn, inCar = pcall(isCharInAnyCar, PLAYER_PED)
    end
    if okIn and inCar and type(getCarCharIsUsing) == "function"
        and type(setCarCoordinates) == "function" then
        local okC, car = pcall(getCarCharIsUsing, PLAYER_PED)
        if okC and car and car ~= 0 then
            local sz = grndCharSurfaceZ(x, y, z) or z
            local okW = pcall(setCarCoordinates, car, x, y, sz + 0.5)
            if okW then
                if type(setCarVelocity) == "function" then pcall(setCarVelocity, car, 0, 0, 0) end
                pcall(notify.add, ("Телепорт -> %.1f, %.1f, %.1f"):format(x, y, z), "ok", 3)
                return true
            end
        end
    end
    if type(setCharCoordinates) == "function" then
        local sz = grndCharSurfaceZ(x, y, z) or z
        local ok = pcall(setCharCoordinates, PLAYER_PED, x, y, sz + 0.05)
        if ok then
            if type(setCharVelocity) == "function" then
                pcall(setCharVelocity, PLAYER_PED, 0, 0, 0)
            end
            pcall(notify.add, ("Телепорт -> %.1f, %.1f, %.1f"):format(x, y, z), "ok", 3)
            return true
        end
    end
    pcall(notify.add, "Телепорт: функция недоступна", "error", 3)
    return false
end

function grndCharPointById(id)
    local C = GRND_CHAR
    for i = 1, #C.points do
        if C.points[i].id == id then return C.points[i], i end
    end
    return nil, nil
end

function grndCharDeletePoint(id)
    local C = GRND_CHAR
    local p, i = grndCharPointById(id)
    if not p then return end
    table.remove(C.points, i)
    if C.tpEdit and C.tpEdit.id == id then C.tpEdit = nil end
    pcall(notify.add, "Точка «" .. (p.name or "") .. "» удалена", "info", 2)
    grndCharTouch()
    grndCharSave()
end

-- =====================================================================
--  Отрисовка вкладки «Персонаж»
-- =====================================================================
-- =====================================================================
--  v1.14.18: журнал ошибок отрисовки. Игра не даёт скопировать текст
--  со экрана, поэтому ошибка и traceback пишутся в resource/grnd/logs/grnd_err.log.
--  Его можно открыть блокнотом и прислать содержимое.
-- =====================================================================
function grndUiErrLogPath()
    return grndStoragePath("logs","grnd_err.log")
end

function grndUiErrLog(where, err)
    local msg = tostring(err)
    local tb = ""
    if type(debug) == "table" and type(debug.traceback) == "function" then
        local okT, t = pcall(debug.traceback, "", 2)
        if okT then tb = tostring(t) end
    end
    print("{FF6666}[GRND]{FFFFFF} " .. tostring(where) .. ": " .. msg)
    local ok, f = pcall(io.open, grndUiErrLogPath(), "w")
    if ok and f then
        pcall(function()
            f:write("where: " .. tostring(where) .. "\n")
            f:write("error: " .. msg .. "\n")
            f:write("traceback:\n" .. tb .. "\n")
            f:close()
        end)
    end
    return msg
end

function grndCharDraw(ctx)
    local ok, err = pcall(grndCharDrawInner, ctx)
    if not ok then
        local msg = grndUiErrLog("персонаж", err)
        if ctx and ctx.uiText and ctx.cardX then
            pcall(ctx.uiText, ctx.cardX + 16, ctx.cardY + 16,
                "Ошибка раздела «Персонаж»: " .. msg,
                ctx.rgba(255, 110, 110, 255))
            pcall(ctx.uiText, ctx.cardX + 16, ctx.cardY + 34,
                "подробности в resource/grnd/logs/grnd_err.log",
                ctx.rgba(140, 148, 166, 255))
        end
    end
end

function grndCharDrawInner(ctx)
    if type(ctx) ~= "table" then return end
    local im, dl, at = ctx.im, ctx.dl, ctx.at
    local uiText, tsize, roundRect = ctx.uiText, ctx.tsize, ctx.roundRect
    local col32, rgba = ctx.col32, ctx.rgba
    if not (im and dl and at and uiText and roundRect and col32 and rgba) then return end
    local TH = grndUiTheme()
    local c4 = ctx.c4 or function(t) return rgba(t[1], t[2], t[3], t[4] or 255) end
    local C = GRND_CHAR
    grndCharLoad()
    if C.dirty and os.clock() > (C.saveAt or 0) then grndCharSave() end

    local cardX, cardY = ctx.cardX or 0, ctx.cardY or 0
    local cardW, cardH = ctx.cardW or 400, ctx.cardH or 300
    local x0, y0 = cardX + 8, cardY + 4
    local cw = math.max(240, cardW - 16)
    local viewH = math.max(160, cardH - 8)

    -- мышь: io.MousePos — ЭКРАННЫЕ координаты, контент рисуется в
    -- координатах ОКНА, поэтому для колеса/скроллбара переводим в оконные
    local mx, my, wheel = nil, nil, 0
    if im.GetIO then
        local okIo, io = pcall(im.GetIO)
        if okIo and io then
            wheel = tonumber(io.MouseWheel) or 0
            if io.MousePos then mx, my = io.MousePos.x, io.MousePos.y end
        end
    end
    if (not mx) and GRND_MOUSE then mx, my = GRND_MOUSE.x, GRND_MOUSE.y end
    local wpx, wpy = 0, 0
    local okWp, wp = pcall(im.GetWindowPos)
    if okWp and wp and wp.x then wpx, wpy = wp.x, wp.y end
    local lx, ly = nil, nil
    if mx and my then lx, ly = mx - wpx, my - wpy end

    local overCard = lx and ly
        and lx >= x0 and lx <= x0 + cw and ly >= y0 and ly <= y0 + viewH
    local totalPrev = math.max(viewH, C.totalH or viewH)
    if overCard and wheel ~= 0 and (os.clock() - (C.wheelStamp or 0)) > 0.05 then
        C.wheelStamp = os.clock()
        local maxS = math.max(0, totalPrev - viewH)
        C.scroll = math.max(0, math.min(maxS, (C.scroll or 0) - wheel * 42))
    end

    -- буферы ImGui (название точки и координаты)
    local haveBufs = false
    if im and im.new and im.new.char then
        if C.bufIm ~= im then
            C.bufIm = im
            C.nameBuf, C.xBuf, C.yBuf, C.zBuf = nil, nil, nil, nil
            C.editBoundId = nil
        end
        local okB = pcall(function()
            if not C.nameBuf then C.nameBuf = im.new.char[96]() end
            if not C.xBuf then C.xBuf = im.new.char[32]() end
            if not C.yBuf then C.yBuf = im.new.char[32]() end
            if not C.zBuf then C.zBuf = im.new.char[32]() end
        end)
        haveBufs = okB and true or false
    end

    local ROWH, RGAP, SEC = 34, 6, 14
    local CAPH = 24
    local oy = y0 - (C.scroll or 0)
    local y = oy + 6

    if dl.PushClipRect then
        pcall(dl.PushClipRect, dl, at(x0, y0), at(x0 + cw, y0 + viewH), true)
    end
    local function vis(yy, hh) return yy + hh >= y0 - 2 and yy <= y0 + viewH + 2 end

    local function caption(text)
        if vis(y, CAPH) then
            local ac, ac2 = TH.accent, TH.accent2
            if ctx.gradRect and ac and ac2 then
                ctx.gradRect(dl, at(x0, y + 5), at(x0 + 3, y + 17),
                    col32(ac[1], ac[2], ac[3], ac[4] or 255),
                    col32(ac2[1], ac2[2], ac2[3], ac2[4] or 255), 2)
            end
            uiText(x0 + 10, y + 3, text, c4(TH.text or { 198, 205, 219, 255 }), 0.95)
        end
        y = y + CAPH
    end

    local function tinput(id, buf, cap, bx, by, bw, bh)
        im.SetCursorPos(im.ImVec2(bx, by))
        local pushed = grndBinderPushColors(im, {
            { im.Col and im.Col.FrameBg, 13, 15, 20, 255 },
            { im.Col and im.Col.FrameBgHovered, 18, 21, 29, 255 },
            { im.Col and im.Col.FrameBgActive, 22, 26, 34, 255 },
            { im.Col and im.Col.Text, 233, 237, 246, 255 },
            { im.Col and im.Col.Border, 255, 255, 255, 40 },
        })
        local okI = pcall(im.InputText, id, buf, cap)
        grndBinderPopColors(im, pushed)
        if not okI then return false end
        if dl.AddRect then
            pcall(dl.AddRect, dl, at(bx + 0.5, by + 0.5), at(bx + bw - 0.5, by + bh - 0.5),
                col32(255, 255, 255, 26), 7, 0, 1)
        end
        return true
    end

    -- ================= ПОГОДА / ВРЕМЯ =================
    caption("Настройка погоды и времени")
    -- Слева от 0 — серверный режим (-1). Оба способа управления (кнопки
    -- и перетаскивание) проходят через grndCharSelectWeather/Time.
    local function sliderRow(tag, val, vmax, label, serverLabel, onVal)
        if vis(y, ROWH) then
            roundRect(dl, at(x0, y), at(x0 + cw, y + ROWH), col32(255, 255, 255, 7), 9)
            local lw, lh = 0, 14
            if tsize then
                local a, b = tsize(label)
                lw = (type(a) == "number" and a) or 0
                lh = (type(b) == "number" and b) or 14
            end
            local lbW = math.max(56, lw + 10)
            local btnW, gap = 22, 6
            local plusX = x0 + cw - 8 - lbW - btnW
            local text = (val < 0) and serverLabel or tostring(val)
            local tw, th = 0, 14
            if tsize then
                local a, b = tsize(text)
                tw = (type(a) == "number" and a) or 0
                th = (type(b) == "number" and b) or 14
            end
            -- На узком окне сжимаем бейдж, сохраняя +/- и минимум места
            -- для слайдера. На обычном экране показываем слово целиком.
            local vbW = math.max(62, math.min(math.max(76, tw + 16), plusX - x0 - 86))
            local badgeX = x0 + 6
            local minusX = badgeX + vbW + gap
            local slX = minusX + btnW + gap
            local slW = plusX - gap - slX
            local accent = TH.accent or { 0, 214, 170, 255 }
            roundRect(dl, at(badgeX, y + 5), at(badgeX + vbW, y + ROWH - 5),
                val < 0 and col32(accent[1], accent[2], accent[3], 32)
                    or col32(255, 255, 255, 10), 7)
            local scale = 0.95
            if type(im.SetWindowFontScale) == "function" and tw > 0 then
                scale = math.min(scale, (vbW - 8) / tw)
            elseif tw * scale > vbW - 8 then
                text = "Серв."
                if tsize then tw, th = tsize(text) end
                scale = 0.95
            end
            uiText(badgeX + (vbW - tw * scale) / 2,
                y + (ROWH - th * scale) / 2, text,
                val < 0 and rgba(accent[1], accent[2], accent[3], 255)
                    or rgba(233, 237, 246, 255), scale)

            -- [число/сервер] [ − ] [------ползунок------] [ + ] [подпись]
            local minus = grndUiButton(ctx, "##gch_minus_" .. tag,
                minusX, y + 5, btnW, ROWH - 10, "-", { muted = val <= -1 })
            if minus and val > -1 then onVal(val - 1) end
            if slW >= 32 then
                local nr = grndUiSlider(ctx, "##gch_sl_" .. tag,
                    slX, y, slW, ROWH, (val + 1) / (vmax + 1))
                if nr then
                    local nv = math.max(-1, math.min(vmax,
                        math.floor(-1 + nr * (vmax + 1) + 0.5)))
                    if nv ~= val then onVal(nv) end
                end
            end
            local plus = grndUiButton(ctx, "##gch_plus_" .. tag,
                plusX, y + 5, btnW, ROWH - 10, "+", { muted = val >= vmax })
            if plus and val < vmax then onVal(val + 1) end
            uiText(x0 + cw - 8 - lw, y + (ROWH - lh) / 2, label,
                c4(TH.text or { 198, 205, 219, 255 }), 0.95)
        end
        y = y + ROWH + RGAP
    end
    sliderRow("w", C.weatherOn and C.weather or -1, 19,
        "Погода", "Серверная", grndCharSelectWeather)
    sliderRow("t", C.hourOn and C.hour or -1, 23,
        "Время", "Серверное", grndCharSelectTime)
    y = y + SEC - RGAP

    -- ================= ВЫДАЧА СЕБЕ =================
    caption("Выдача себе")
    -- v1.14.31: цельные кнопки, без шестерёнок и отдельных слайдеров.
    local function selfRow(tag, label, onAct)
        if vis(y, ROWH) then
            local clicked = grndUiButton(ctx, "##gch_self_" .. tag,
                x0, y, cw, ROWH, label, {})
            if clicked and onAct then onAct() end
        end
        y = y + ROWH + RGAP
    end
    selfRow("hp", "Выдать себе ХП", grndCharSelfHp)
    selfRow("arm", "Выдать себе броню", grndCharSelfArm)
    selfRow("fix", "Починить транспорт", grndCharSelfFix)
    y = y + SEC - RGAP

    -- ================= ТЕЛЕПОРТЫ =================
    -- v1.14.20: без вкладок «Создать/Поиск» и лишних кнопок — сразу список.
    -- Клик по строке — телепорт, карандаш — редактор, корзина — удалить.
    caption("Телепорты")
    local LH, LGAP = 30, 4
    local ICONW = 28
    local function pencilIcon(cx, cy, col)
        pcall(dl.AddLine, dl, at(cx - 3.5, cy + 3.5), at(cx + 2.5, cy - 2.5), col, 1.4)
        pcall(dl.AddLine, dl, at(cx + 2.5, cy - 2.5), at(cx + 4.0, cy - 1.0), col, 1.4)
        pcall(dl.AddLine, dl, at(cx + 4.0, cy - 1.0), at(cx - 2.0, cy + 5.0), col, 1.4)
        pcall(dl.AddLine, dl, at(cx - 2.0, cy + 5.0), at(cx - 3.5, cy + 3.5), col, 1.4)
    end
    local function trashIcon(cx, cy, col)
        pcall(dl.AddRect, dl, at(cx - 3.5, cy - 3), at(cx + 3.5, cy + 4.5), col, 1.5, 0, 1.3)
        pcall(dl.AddLine, dl, at(cx - 5, cy - 3), at(cx + 5, cy - 3), col, 1.3)
        pcall(dl.AddLine, dl, at(cx - 1.8, cy - 5), at(cx + 1.8, cy - 5), col, 1.3)
        pcall(dl.AddLine, dl, at(cx - 1.2, cy - 1), at(cx - 1.2, cy + 2.5), col, 1.1)
        pcall(dl.AddLine, dl, at(cx + 1.2, cy - 1), at(cx + 1.2, cy + 2.5), col, 1.1)
    end
    if #C.points == 0 then
        if vis(y, 26) then
            local msg = "Нет сохранённых точек — создайте первую ниже"
            local mw = 0
            if tsize then mw = tsize(msg) or 0 end
            uiText(x0 + (cw - mw) / 2, y + 6, msg, c4(TH.textMuted or { 96, 104, 122, 255 }), 0.9)
        end
        y = y + 30
    end
    for _, p in ipairs(C.points) do
        if vis(y, LH) then
            local bw = cw - 2 * (ICONW + 6)
            local clicked = grndUiButton(ctx, "##gch_tp_" .. tostring(p.id),
                x0, y, bw, LH, "Точка: " .. (p.name or p.id), { align = "left", cutW = bw - 24 })
            if clicked then grndCharWarp(p.x, p.y, p.z) end
            local ex = x0 + bw + 6
            im.SetCursorPos(im.ImVec2(ex, y))
            local ecl = im.InvisibleButton("##gch_tpe_" .. tostring(p.id), im.ImVec2(ICONW, LH))
            local ehov = (im.IsItemHovered and im.IsItemHovered()) or false
            if ehov then roundRect(dl, at(ex + 1, y + 1), at(ex + ICONW - 1, y + LH - 1),
                col32(255, 255, 255, 12), 7) end
            pencilIcon(ex + ICONW / 2, y + LH / 2,
                ehov and col32(233, 237, 246, 255) or col32(140, 148, 166, 255))
            if ecl then
                C.tpEdit = { id = p.id, isNew = false }
                C.editBoundId = nil
            end
            local dx = ex + ICONW + 6
            im.SetCursorPos(im.ImVec2(dx, y))
            local dcl = im.InvisibleButton("##gch_tpd_" .. tostring(p.id), im.ImVec2(ICONW, LH))
            local dhov = (im.IsItemHovered and im.IsItemHovered()) or false
            if dhov then roundRect(dl, at(dx + 1, y + 1), at(dx + ICONW - 1, y + LH - 1),
                col32(255, 96, 96, 30), 7) end
            trashIcon(dx + ICONW / 2, y + LH / 2,
                dhov and col32(255, 128, 128, 255) or col32(140, 148, 166, 255))
            if dcl then grndCharDeletePoint(p.id) end
        end
        y = y + LH + LGAP
    end
    y = y + 2

    -- новая точка (сразу с текущими координатами)
    if vis(y, ROWH) then
        local clicked = grndUiButton(ctx, "##gch_tp_add", x0, y, cw, ROWH,
            "+ Сохранить текущую точку", {})
        if clicked then
            local px, py, pz = grndCharGetPos()
            C.tpEdit = { id = grndCharGenId(), isNew = true,
                nx = px or 0, ny = py or 0, nz = pz or 0 }
            C.editBoundId = nil
        end
    end
    y = y + ROWH + 10

    -- редактор точки
    if C.tpEdit then
        local E = C.tpEdit
        local p = grndCharPointById(E.id)
        if not p and not E.isNew then
            C.tpEdit = nil
        else
            local PH = 4 * (30 + 6) + 22
            if vis(y, PH) then
                roundRect(dl, at(x0, y), at(x0 + cw, y + PH), col32(0, 0, 0, 70), 9)
                pcall(dl.AddRect, dl, at(x0 + 0.5, y + 0.5), at(x0 + cw - 0.5, y + PH - 0.5),
                    col32(255, 255, 255, 22), 9, 0, 1)
                local ey = y + 8
                uiText(x0 + 12, ey + 4, "Точка: " .. tostring(E.id),
                    c4(TH.textDim or { 140, 148, 166, 255 }), 0.9)
                ey = ey + 22
                if haveBufs and C.editBoundId ~= E.id then
                    local bxv, byv, bzv, bname
                    if p then
                        bxv, byv, bzv, bname = p.x, p.y, p.z, p.name
                    else
                        bxv, byv, bzv = E.nx or 0, E.ny or 0, E.nz or 0
                        bname = ""
                    end
                    grndBinderWriteCBuf(C.xBuf, 32, ("%.3f"):format(bxv))
                    grndBinderWriteCBuf(C.yBuf, 32, ("%.3f"):format(byv))
                    grndBinderWriteCBuf(C.zBuf, 32, ("%.3f"):format(bzv))
                    grndBinderWriteCBuf(C.nameBuf, 96, bname or "")
                    C.editBoundId = E.id
                end
                local nlW = 60
                uiText(x0 + 12, ey + 8, "Имя", c4(TH.textMuted or { 96, 104, 122, 255 }), 0.9)
                if haveBufs then
                    tinput("##gch_en", C.nameBuf, 90, x0 + nlW + 8, ey, cw - nlW - 20, 30)
                end
                ey = ey + 36
                local labW = 14
                local inpW = math.floor((cw - 24 - 3 * labW - 2 * 10) / 3)
                local cx = x0 + 12
                local coords = { { C.xBuf, "X" }, { C.yBuf, "Y" }, { C.zBuf, "Z" } }
                for i = 1, 3 do
                    local buf, lab = coords[i][1], coords[i][2]
                    if haveBufs then
                        tinput("##gch_ec" .. lab, buf, 26, cx, ey, inpW, 30)
                    end
                    uiText(cx + inpW + 4, ey + 8, lab,
                        c4(TH.textMuted or { 96, 104, 122, 255 }), 0.9)
                    cx = cx + inpW + labW + 10
                end
                ey = ey + 36
                local insCl = grndUiButton(ctx, "##gch_e_ins", x0 + 12, ey, cw - 24, 30,
                    "Внести текущие координаты", {})
                if insCl and haveBufs then
                    local px, py, pz = grndCharGetPos()
                    if px then
                        grndBinderWriteCBuf(C.xBuf, 32, ("%.3f"):format(px))
                        grndBinderWriteCBuf(C.yBuf, 32, ("%.3f"):format(py))
                        grndBinderWriteCBuf(C.zBuf, 32, ("%.3f"):format(pz))
                    else
                        pcall(notify.add, "Телепорты: координаты недоступны", "warn", 2)
                    end
                end
                ey = ey + 36
                local halfW = math.floor((cw - 24 - 8) / 2)
                local svCl = grndUiButton(ctx, "##gch_e_save", x0 + 12, ey, halfW, 30,
                    "Сохранить", { selected = true })
                local cnCl = grndUiButton(ctx, "##gch_e_cancel", x0 + 12 + halfW + 8, ey,
                    halfW, 30, "Отмена", {})
                if svCl and haveBufs then
                    local nx = tonumber(grndBinderReadCBuf(C.xBuf))
                    local ny = tonumber(grndBinderReadCBuf(C.yBuf))
                    local nz = tonumber(grndBinderReadCBuf(C.zBuf))
                    local nm = grndBinderReadCBuf(C.nameBuf):gsub("^%s+", ""):gsub("%s+$", "")
                    if not (nx and ny and nz) then
                        pcall(notify.add, "Телепорты: координаты — числа", "warn", 3)
                    else
                        if nm == "" then nm = "точка " .. tostring(#C.points + 1) end
                        if p then
                            p.x, p.y, p.z, p.name = nx, ny, nz, nm
                        else
                            C.points[#C.points + 1] = { id = E.id, name = nm, x = nx, y = ny, z = nz }
                        end
                        grndCharTouch()
                        grndCharSave()
                        pcall(notify.add, "Точка «" .. nm .. "» сохранена", "ok", 2)
                        C.tpEdit = nil
                    end
                end
                if cnCl then C.tpEdit = nil end
            end
            y = y + PH + 8
        end
    end

    C.totalH = (y - oy) + 8
    if dl.PopClipRect then pcall(dl.PopClipRect, dl) end

    -- полоса прокрутки справа (колесо листает, по полосе можно тянуть)
    local totalH = math.max(viewH, C.totalH or viewH)
    if totalH > viewH + 1 then
        local trX = x0 + cw - 5
        roundRect(dl, at(trX, y0), at(trX + 3, y0 + viewH), col32(255, 255, 255, 14), 2)
        local maxS = totalH - viewH
        local barH = math.max(24, viewH * (viewH / totalH))
        local barY = y0 + ((C.scroll or 0) / maxS) * (viewH - barH)
        local ac = TH.accent or { 0, 214, 170, 255 }
        roundRect(dl, at(trX, barY), at(trX + 3, barY + barH),
            col32(ac[1], ac[2], ac[3], 200), 2)
        if lx and ly and lx >= trX - 4 and lx <= trX + 7
            and ly >= y0 and ly <= y0 + viewH then
            local down = false
            if im.IsMouseDown then
                local okD, d = pcall(im.IsMouseDown, 0)
                down = (okD and d) and true or false
            end
            if down then
                local t = (ly - y0) / math.max(1, viewH)
                C.scroll = math.max(0, math.min(maxS, t * totalH - barH / 2))
            end
        end
    end
end
-- Unified Admin settings: scrollable cards, no nested section tabs.
function grndAdminSettingsDraw(C)
    local im=C.im
    local TH=grndUiTheme()
    im.SetCursorPos(im.ImVec2(C.x,C.y))
    local opened,visible=pcall(im.BeginChild,'##grnd_admin_cards',im.ImVec2(C.w,C.h),false,0)
    if not opened then
        C.uiText(C.x+8,C.y+8,'Не удалось открыть настройки администратора',C.rgba(255,135,135,255),0.9)
        return false
    end
    local function draw()
        if visible==false then return end
        local dl=im.GetWindowDrawList();local pos=im.GetWindowPos()
        local sy=im.GetScrollY and im.GetScrollY() or 0
        local sx=im.GetScrollX and im.GetScrollX() or 0
        local function at(x,y) return im.ImVec2(pos.x+x-sx,pos.y+y-sy) end
        local function col(t) return C.col32(t[1],t[2],t[3],t[4] or 255) end
        local function color(t) return C.rgba(t[1],t[2],t[3],t[4] or 255) end
        local x,y,w=4,6,math.max(220,C.w-26)
        local function fit(text,limit)
            if grndBinderFit then return grndBinderFit(text,math.max(30,limit),C.tsize) end
            return text
        end
        local function text(px,py,s,c,scale) return C.uiText(px,py,s,color(c),scale or 1) end
        local function surface(py,h)
            C.roundRect(dl,at(x,py),at(x+w,py+h),C.col32(255,255,255,10),10)
            if dl.AddRect then pcall(dl.AddRect,dl,at(x+0.5,py+0.5),at(x+w-0.5,py+h-0.5),col(TH.contentEdge or TH.line),10,0,1) end
        end
        local function toggle(px,py,on,id)
            im.SetCursorPos(im.ImVec2(px,py))
            local hit=im.InvisibleButton('##admin_'..id,im.ImVec2(46,24))
            local hovered=im.IsItemHovered and im.IsItemHovered() or false
            grndUiSwitchPaint({dl=dl,at=at,col32=C.col32,roundRect=C.roundRect},px,py,on,hovered,'admin_'..id,C.dt)
            return hit
        end
        local function slider(px,py,width,value,min,max,step,id)
            local fraction=math.max(0,math.min(1,(value-min)/(max-min)))
            C.roundRect(dl,at(px,py+8),at(px+width,py+14),C.col32(255,255,255,32),3)
            if fraction>0 then C.roundRect(dl,at(px,py+8),at(px+width*fraction,py+14),col(TH.accent),3) end
            im.SetCursorPos(im.ImVec2(px-5,py))
            im.InvisibleButton('##admin_slider_'..id,im.ImVec2(width+10,24))
            local new=value
            if im.IsItemActive and im.IsItemActive() then
                local mouse=im.GetMousePos and im.GetMousePos() or im.GetIO().MousePos
                if mouse then
                    local f=math.max(0,math.min(1,(mouse.x-at(px,py).x)/width))
                    new=math.max(min,math.min(max,min+math.floor((f*(max-min))/step+0.5)*step))
                end
            end
            local k=px+width*fraction
            C.roundRect(dl,at(k-4,py+3),at(k+4,py+19),col(TH.accent),3)
            return new,new~=value
        end
        local function save() if grndCamCfgSave then pcall(grndCamCfgSave) end end
        local function simple(title,description,on,id,change)
            surface(y,66)
            text(x+16,y+11,fit(title,w-92),TH.textHi,1.02)
            text(x+16,y+36,fit(description,(w-36)/0.84),TH.textMuted,0.84)
            if toggle(x+w-62,y+10,on,id) then change(not on);save() end
            y=y+78
        end
        simple('Формы из админ-чата','Показывать форму для ручного подтверждения Y / N',
            GRND_ADMIN_CFG.autoForms~=false,'forms',function(v) GRND_ADMIN_CFG.autoForms=v end)
        simple('Авто /acceptgnews','Приём заявок на государственные новости',
            GRND_ADMIN_CFG.autoGnews==true,'gnews',function(v) GRND_ADMIN_CFG.autoGnews=v end)

        -- WH parameters are inline, not a separate floating subwindow.
        local W=GRND_WH
        local whHeight=W.expanded and 176 or 64
        surface(y,whHeight)
        text(x+16,y+10,'WH на игроков',TH.textHi,1.02)
        text(x+16,y+35,'Ники, здоровье и броня игроков',TH.textMuted,0.84)
        if toggle(x+w-108,y+10,W.enabled,'wh') then
            W.enabled=not W.enabled;W.scanAt=-999;W.players={};W.nativeAt=-999;W.dirtyAt=os.clock()
            if W.nativeTick then pcall(W.nativeTick) end;save()
        end
        im.SetCursorPos(im.ImVec2(x+w-42,y+8))
        if im.InvisibleButton('##admin_wh_expand',im.ImVec2(30,28)) then W.expanded=not W.expanded end
        text(x+w-32,y+12,W.expanded and 'v' or '>',TH.textMuted)
        if whHeight>64 then
            dl:AddLine(at(x+16,y+64),at(x+w-16,y+64),col(TH.line),1)
            text(x+16,y+80,'Дальность',TH.textHi,0.92)
            local v,changed=slider(x+110,y+76,w-198,W.distance or 300,10,800,10,'wh_distance')
            if changed then W.distance=v;W.dirtyAt=os.clock();save() end
            text(x+w-76,y+80,tostring(math.floor(W.distance or 300))..' м',TH.accent,0.88)
            text(x+16,y+124,'Скелет',TH.textHi,0.92)
            if toggle(x+w-62,y+118,W.skeleton,'wh_skeleton') then
                W.skeleton=not W.skeleton;W.dirtyAt=os.clock()
                if W.skeleton and W.initBones then pcall(W.initBones) end;save()
            end
        end
        y=y+whHeight+12

        grndTracerUi({im=im,dl=dl,at=at,uiText=C.uiText,roundRect=C.roundRect,
            col32=C.col32,rgba=C.rgba,toggle=toggle,slider=slider,dt=C.dt,
            x=x,y=y,w=w,h=424})
        y=y+54+math.floor(370*(GRND_TRACER.anim or 0))+12

        local R=GRND_TARGET_RING
        if R.settingsExpanded==nil then
            local saved=GRND_CONFIG.ensure().layout.adminCards or {}
            R.settingsExpanded=saved.ring==true
        end
        surface(y,62)
        text(x+16,y+10,'Кольцевое меню',TH.textHi,1.02)
        text(x+16,y+34,'Действия над игроками и транспортом',TH.textMuted,0.84)
        im.SetCursorPos(im.ImVec2(x,y))
        if im.InvisibleButton('##admin_ring_expand',im.ImVec2(w,62)) then
            R.settingsExpanded=not R.settingsExpanded
            if not R.settingsExpanded then grndRingUiFlush();R.capture=nil end
            GRND_CONFIG.setLayout('adminCards',{ring=R.settingsExpanded})
        end
        text(x+w-32,y+15,R.settingsExpanded and 'v' or '>',TH.textMuted)
        y=y+70
        if R.settingsExpanded then
            grndRingUiDraw({im=im,dl=dl,at=at,uiText=C.uiText,roundRect=C.roundRect,
                col32=C.col32,rgba=C.rgba,tsize=C.tsize,cardX=x,cardY=y,cardW=w,cardH=450})
            y=y+462
        end
        im.SetCursorPos(im.ImVec2(0,y));im.Dummy(im.ImVec2(1,1))
    end
    local ok,err=pcall(draw)
    im.EndChild()
    if not ok then
        C.uiText(C.x+8,C.y+8,'Ошибка настроек: '..tostring(err),C.rgba(255,135,135,255),0.85)
        return false
    end
    return true
end
-- End unified Admin settings.

-- >>> ПАНЕЛЬ МП: НАЧАЛО БЛОКА
-- =====================================================================
--  МОДУЛЬ 15: ПАНЕЛЬ МП (мероприятие)
--  ---------------------------------------------------------------------
--  Вкладка «Панель МП» (id = "mppanel" в MENU_TABS) рисуется функцией
--  MP.draw; очередь команд крутится в pcall(MP.tick) основного цикла;
--  разбор репорта — pcall(MP.onServerMessage, text) в sampev.onServerMessage
--  модуля 14. Команда /mp — состояние МП, заготовки.
--
--  РАБОТА ТОЛЬКО С РЕПОРТАМИ: ловим строки вида
--  "Nik_Name[ID]: сообщение от игрока [К-во репорта: N]".
--  Обычные реплики чата (без маркера) игнорируются.
--
--  КАК РАБОТАЕТ
--      1. Админ набивает форму: сообщения в /msg, триггер, что выдать
--         игроку после телепорта, что забрать, тайминги, заготовки.
--      2. «Создать МП» -> валидация -> объявления уходят в /msg (по одному,
--         с паузой). Пока объявления шлются, слежение выключено; как
--         только они закончились - включается слежение за репортом.
--      3. Строка репорта в чате:  "Nik_Name[ID]: текст [К-во репорта: N]"
--         разбирается на ник / ID / текст. Если в тексте есть триггер,
--         игрок попадает в очередь, и для него СТРОГО ПОСЛЕДОВАТЕЛЬНО:
--              /ans ID <текст ответа>      (пауза ansDelay)
--              /gethere ID                 (пауза tpDelay)
--              /rgun ID                    (если «забрать оружие»)
--              /arm ID 1                   (если «забрать броню»)
--              /gun ID оружие патроны      (строки раздела «Оружие»)
--              /arm ID количество          (строки раздела «Броня»)
--              /hp ID количество           (строки раздела «Здоровье»)
--              /setskin ID скин            (строки раздела «Скин»)
--      4. Всё, что уходит на сервер, идёт через ОДНУ очередь: не больше
--         ОДНОЙ команды за интервал, с заданными паузами между шагами.
--
--  ЗАЩИТА ОТ СПАМА (это главное)
--      * разбор чата ограничен по частоте («ведро токенов») + дешёвый
--        фильтр ДО конвертации кодировки;
--      * на игрока — блокировка на время обработки и кулдаун в секундах
--        (повторные репорты того же игрока игнорируются);
--      * очередь игроков и число участников ограничены потолком, при
--        переполнении игрок отбрасывается (память не растёт);
--      * перед каждой командой проверяется, что игрок ещё в сети;
--      * команды собираются ТОЛЬКО из проверенных чисел и ID — в чат
--        не может уйти мусор, который ломает разбор на сервере;
--      * ни один сбой панели не роняет скрипт: всё под pcall.
--
--  КОДИРОВКИ. Файл UTF-8. В чат — только через grndChatSend/grndAnsiText
--  (CP1251), на панель — только UTF-8. Конвертеры берём те же, что у
--  скрипта (grndToUtf / grndUtf8ToCp1251), чтобы не расходились.
--  Конфиг: <папка скрипта>/grnd_tools/grnd_mp.cfg (рядом с config.json).
--
--  СТИЛЬ. Ничего не экспортирует наружу, кроме _G.GRND_MP (для /mp и
--  диагностики). Имена функций — с префиксом MP., чтобы не пересечься
--  с остальными модулями.
-- =====================================================================
_G.MP = (function()
local MP = {}
_G.GRND_MP = MP

-- конвертеры кодировок самого скрипта (локальные функции выше по
-- файлу). В стенде их нет — тогда работают _G/encoding.
local scriptToUtf = grndToUtf
local scriptToAnsi = grndUtf8ToCp1251

-- ---------------------------------------------------------------------
--  КОНСТАНТЫ
-- ---------------------------------------------------------------------
local MAX_MSG     = 8      -- максимум строк объявления
local MAX_ROWS    = 6      -- максимум строк в разделе выдачи
local MAX_PRESETS = 12     -- максимум заготовок
local MAX_QUEUE   = 40     -- максимум игроков в очереди
local LOG_MAX     = 40     -- длина журнала действий
local SEND_RATE   = 0.105  -- минимальный интервал отправки команд
local ANNOUNCE_CMD = "/msg" -- канал оповещений МП
local MAX_CMD_BYTES = 144  -- безопасный предел строки SA-MP
local PARSE_RATE  = 250    -- сколько строк чата разбирать в секунду
local PARSE_BURST = 400    -- ...и сколько за раз попыток

-- Ответ на репорт ФИКСИРОВАННЫЙ: текст не меняется из панели и не пишется
-- в конфиг, чтобы со временем не «уехал» и не разошёлся с серверным.
local ANSWER = "Приветствую, вы телепортированы на мероприятие, приятной игры!"

-- ---------------------------------------------------------------------
--  1. КОДИРОВКИ И ТЕКСТ
-- ---------------------------------------------------------------------
local function isUtf8(s)
    if not s:find("[\128-\255]") then return true end
    local i, n = 1, #s
    while i <= n do
        local c = s:byte(i)
        if c < 128 then
            i = i + 1
        else
            local need
            if c >= 240 and c <= 244 then need = 3
            elseif c >= 224 and c <= 239 then need = 2
            elseif c >= 194 and c <= 223 then need = 1
            else return false end
            for k = 1, need do
                local b = s:byte(i + k)
                if not b or b < 128 or b > 191 then return false end
            end
            i = i + need + 1
        end
    end
    return true
end

local function encLib()
    local ok, enc = pcall(require, "encoding")
    if ok and enc then return enc end
    return _G.encoding
end

-- CP1251 (или уже UTF-8) -> UTF-8: для ImGui и разбора репортов.
local function toUtf(s)
    s = tostring(s or "")
    if s == "" or not s:find("[\128-\255]") then return s end
    if isUtf8(s) then return s end
    local cvt = scriptToUtf or _G.grndToUtf
    if type(cvt) == "function" then
        local ok, out = pcall(cvt, s)
        if ok and type(out) == "string" and out ~= "" then return out end
    end
    local enc = encLib()
    if enc and enc.UTF8 then
        local prev = enc.default
        enc.default = "CP1251"
        local ok, out = pcall(function() return enc.UTF8:encode(s) end)
        enc.default = prev
        if ok and type(out) == "string" and out ~= "" then return out end
    end
    return s
end

-- UTF-8 -> CP1251: для sampSendChat / sampAddChatMessage.
local function toAnsi(s)
    s = tostring(s or "")
    if s == "" or not s:find("[\128-\255]") then return s end
    if not isUtf8(s) then return s end
    local cvt = scriptToAnsi or _G.grndToAnsi
    if type(cvt) == "function" then
        local ok, out = pcall(cvt, s)
        if ok and type(out) == "string" and out ~= "" then return out end
    end
    local enc = encLib()
    if enc and enc.UTF8 then
        local prev = enc.default
        enc.default = "CP1251"
        local ok, out = pcall(function() return enc.UTF8:decode(s) end)
        enc.default = prev
        if ok and type(out) == "string" and out ~= "" then return out end
    end
    -- крайний случай: без конвертера кириллица не уходит «как есть»,
    -- чтобы не превратить её в «Ð¤Ð¾Ñ€Ð¼Ð°» у всех в чате
    return (s:gsub("[^\32-\126]", "?"))
end

local function ansiText(s)
    s = tostring(s or "")
    if s == "" then return s end
    local fn = _G.grndAnsiText
    if type(fn) == "function" then
        local ok, out = pcall(fn, s)
        if ok and type(out) == "string" and out ~= "" then return out end
    end
    return toAnsi(s)
end

local function lowerUtf(s)
    s = tostring(s or "")
    local fn = _G.grndLowerUtf
    if type(fn) == "function" then
        local ok, out = pcall(fn, s)
        if ok and type(out) == "string" then return out end
    end
    return s:lower()
end

-- Обрезка по символам (без разрыва UTF-8-последовательности).
local function utfCut(s, maxChars)
    s = tostring(s or "")
    if maxChars <= 0 then return "" end
    local chars = {}
    for ch in s:gmatch("[%z\1-\127\194-\244][\128-\191]*") do
        chars[#chars + 1] = ch
        if #chars >= maxChars then return table.concat(chars) end
    end
    return s
end

local function utfLen(s)
    local fn = _G.grndUtf8Len
    if type(fn) == "function" then
        local ok, v = pcall(fn, tostring(s or ""))
        if ok and type(v) == "number" then return v end
    end
    local n = 0
    for _ in tostring(s or ""):gmatch("[%z\1-\127\194-\244][\128-\191]*") do n = n + 1 end
    return n
end

local function cleanText(s)
    s = tostring(s or "")
    s = s:gsub("^\239\187\191", "")
    -- Удаляем только реальные SA-MP colour codes. Шаблон из шести точек
    -- раньше съедал обычные фрагменты вида "{текст}".
    s = s:gsub("{%x%x%x%x%x%x%x%x}", "")
    s = s:gsub("{%x%x%x%x%x%x}", "")
    s = s:gsub("[%c]", " ")
    s = s:gsub("%s+", " ")
    s = s:gsub("^%s+", "")
    s = s:gsub("%s+$", "")
    return utfCut(s, 160)
end

local function now()
    if type(getGameTimer) == "function" then
        local ok, v = pcall(getGameTimer)
        if ok and type(v) == "number" then return v / 1000 end
    end
    return os.clock()
end

local function say(text, kind)
    -- Один префикс «МП»: раньше запасной путь печатал «МП: МП: ...».
    local body = tostring(text or "")
    if type(notify) == "table" and type(notify.add) == "function" then
        pcall(notify.add, "МП: " .. body, kind or "info", 4)
        return
    end
    print("{00FFAA}[GRND]{FFFFFF} МП: " .. body)
    if type(grndChatSay) == "function" then
        local col = -1
        if kind == "ok" then col = 0x4CD14F
        elseif kind == "warn" then col = 0xF79248
        elseif kind == "error" then col = 0xFF6666 end
        pcall(grndChatSay, "{A478FD}[МП]{FFFFFF} " .. body, col)
    end
end

local function numOr(v, def, lo, hi)
    v = tonumber(v)
    if not v or v ~= v then return def end
    if lo then v = math.max(lo, v) end
    if hi then v = math.min(hi, v) end
    return v
end

local function copyList(values, limit)
    local out = {}
    for i, value in ipairs(values or {}) do
        if limit and i > limit then break end
        out[#out + 1] = value
    end
    return out
end

-- ---------------------------------------------------------------------
--  2. СОСТОЯНИЕ
-- ---------------------------------------------------------------------
local installHook       -- объявляется ниже, но нужен старту без основной цепочки
