local function logIt(text, kind)
    MP.log[#MP.log + 1] = { t = os.date("%H:%M:%S"), text = tostring(text or ""), kind = kind or "info" }
    while #MP.log > LOG_MAX do table.remove(MP.log, 1) end
end

local function flash(text, kind)
    MP.flash = { text = tostring(text or ""), kind = kind or "info", at = now() }
end

-- ---------------------------------------------------------------------
--  3. КОНФИГ (grnd_mp.cfg рядом со скриптом, содержимое в CP1251)
-- ---------------------------------------------------------------------
local function esc(s)
    s = tostring(s or "")
    -- Экранируем и разделитель строк «;». Раньше причина/значение с
    -- точкой с запятой silently раскалывалось на две записи.
    s = s:gsub("\\", "\\\\"):gsub("\r", ""):gsub("\n", "\\n")
    s = s:gsub("|", "\\p"):gsub("=", "\\e"):gsub(";", "\\s")
    return s
end

local function unesc(s)
    s = tostring(s or "")
    local out, i = {}, 1
    while i <= #s do
        local c = s:sub(i, i)
        if c == "\\" then
            local n = s:sub(i + 1, i + 1)
            if n == "n" then out[#out + 1] = "\n"
            elseif n == "\\" then out[#out + 1] = "\\"
            elseif n == "p" then out[#out + 1] = "|"
            elseif n == "e" then out[#out + 1] = "="
            elseif n == "s" then out[#out + 1] = ";"
            elseif n ~= "" then out[#out + 1] = n
            else out[#out + 1] = "\\" end
            i = i + 2
        else
            out[#out + 1] = c
            i = i + 1
        end
    end
    return table.concat(out)
end

local function rowsToStr(rows)
    local out = {}
    for _, v in ipairs(rows or {}) do out[#out + 1] = esc(v) end
    return table.concat(out, ";")
end

local function strToRows(s)
    -- Разбираем «;» только вне escape-последовательностей.
    local out, buf, i = {}, {}, 1
    s = tostring(s or "")
    local function add()
        local piece = unesc(table.concat(buf)):gsub("^%s+", ""):gsub("%s+$", "")
        if piece ~= "" and #out < MAX_ROWS then out[#out + 1] = piece end
        buf = {}
    end
    while i <= #s do
        local c = s:sub(i, i)
        if c == "\\" and i < #s then
            buf[#buf + 1] = c .. s:sub(i + 1, i + 1)
            i = i + 2
        elseif c == ";" then
            add(); i = i + 1
        else
            buf[#buf + 1] = c; i = i + 1
        end
    end
    add()
    return out
end

-- Конфиг панели лежит рядом с основным конфигом скрипта:
-- <папка скрипта>/grnd_tools/grnd_mp.cfg (тот же принцип, что у config.json).
local function legacyCfgPath()
    local sep = package.config:sub(1, 1)
    local dir
    if type(thisScript) == "function" then
        pcall(function()
            local script = thisScript()
            if script then dir = tostring(script.path or ""):match("^(.*)[/\\]") end
        end)
    end
    if (not dir or dir == "") and type(getWorkingDirectory) == "function" then
        local ok, value = pcall(getWorkingDirectory)
        if ok and value and value ~= "" then dir = tostring(value) end
    end
    if (not dir or dir == "") and type(this_script_dir) == "function" then
        local ok, value = pcall(this_script_dir)
        if ok and value and value ~= "" then dir = tostring(value) end
    end
    dir = (dir or "."):gsub("[/\\]+$", "")
    local folder = dir .. sep .. "grnd_tools"
    if type(createDirectory) == "function" then pcall(createDirectory, folder) end
    if type(libs) == "table" and libs.lfs and type(libs.lfs.mkdir) == "function" then
        pcall(libs.lfs.mkdir, folder)
    end
    return folder .. sep .. "grnd_mp.cfg"
end

local function cfgPath()
    -- Все настройки панели теперь лежат рядом с config.json. Так не
    -- появляются две независимые копии grnd_mp.cfg после миграции.
    if type(GRND_CONFIG) == "table" and type(GRND_CONFIG.path) == "function" then
        local ok, jsonPath = pcall(GRND_CONFIG.path)
        if ok and type(jsonPath) == "string" and jsonPath ~= "" then
            local dir = jsonPath:match("^(.*)[/\\][^/\\]+$")
            if dir and dir ~= "" then
                local sep = package.config:sub(1, 1)
                return dir .. sep .. "grnd_mp.cfg"
            end
        end
    end
    return legacyCfgPath()
end

local LEGACY_CFG_PATH = legacyCfgPath()

MP.cfgPath = cfgPath()
MP.legacyCfgPath = LEGACY_CFG_PATH

-- разбор строки заготовки по «|» с учётом экранирования
local function splitEsc(line)
    local parts, i, n = {}, 1, #line
    local buf = {}
    while i <= n do
        local c = line:sub(i, i)
        if c == "\\" then
            buf[#buf + 1] = c .. line:sub(i + 1, i + 1)
            i = i + 2
        elseif c == "|" then
            parts[#parts + 1] = table.concat(buf)
            buf = {}
            i = i + 1
        else
            buf[#buf + 1] = c
            i = i + 1
        end
    end
    parts[#parts + 1] = table.concat(buf)
    return parts
end

local function presetLine(p)
    local t = {
        esc(p.name), esc(p.trigger),
        tostring(p.msgDelay), tostring(p.gap), tostring(p.ansDelay), tostring(p.tpDelay),
        tostring(p.cooldown), tostring(p.maxPlayers),
        p.takeGun and "1" or "0", p.takeArmor and "1" or "0",
        p.gunOn and "1" or "0", rowsToStr(p.gunRows),
        p.armorOn and "1" or "0", rowsToStr(p.armorRows),
        p.hpOn and "1" or "0", rowsToStr(p.hpRows),
        p.skinOn and "1" or "0", rowsToStr(p.skinRows),
    }
    for i, m in ipairs(p.messages or {}) do
        if i > MAX_MSG then break end
        t[#t + 1] = esc(m)
    end
    return "p=" .. table.concat(t, "|")
end

local function readPreset(line)
    local parts = splitEsc(line)
    local BASE = 18          -- полей до списка сообщений
    if #parts < BASE + 1 then
        -- заготовка старого формата: 20 полей, третьим и четвёртым шли
        -- nBefore/nText (объявление перед ответом). Их просто пропускаем.
        if #parts >= 21 then
            parts = { parts[1], parts[2], unpack(parts, 5) }
        elseif #parts < 19 then
            return nil
        end
    end
    local messages = {}
    for j = BASE + 1, #parts do
        if #messages >= MAX_MSG then break end
        messages[#messages + 1] = unesc(parts[j])
    end
    local p = {
        name = unesc(parts[1]), trigger = unesc(parts[2]),
        msgDelay   = numOr(parts[3], 1.5, 0.1, 60),
        gap        = numOr(parts[4], 0.35, 0.05, 10),
        ansDelay   = numOr(parts[5], 1.2, 0, 60),
        tpDelay    = numOr(parts[6], 0.8, 0, 60),
        cooldown   = numOr(parts[7], 180, 0, 86400),
        maxPlayers = numOr(parts[8], 50, 1, 500),
        takeGun = parts[9] == "1", takeArmor = parts[10] == "1",
        gunOn   = parts[11] == "1", gunRows   = strToRows(parts[12]),
        armorOn = parts[13] == "1", armorRows = strToRows(parts[14]),
        hpOn    = parts[15] == "1", hpRows    = strToRows(parts[16]),
        skinOn  = parts[17] == "1", skinRows  = strToRows(parts[18]),
        messages = messages,
    }
    return p
end

local formSnapshot          -- вперёд: используется в API заготовок ниже
local function applyPreset(p)
    if not p then return end
    MP.form.trigger   = p.trigger or ""
    MP.form.msgDelay  = numOr(p.msgDelay, 1.5, 0.1, 60)
    MP.form.gap       = numOr(p.gap, 0.35, 0.05, 10)
    MP.form.ansDelay  = numOr(p.ansDelay, 1.2, 0, 60)
    MP.form.tpDelay   = numOr(p.tpDelay, 0.8, 0, 60)
    MP.form.cooldown  = numOr(p.cooldown, 180, 0, 86400)
    MP.form.maxPlayers = math.floor(numOr(p.maxPlayers, 50, 1, 500))
    MP.take.gun   = p.takeGun and true or false
    MP.take.armor = p.takeArmor and true or false
    -- Не привязываем рабочую форму к таблице заготовки: раньше изменение
    -- строки после загрузки молча меняло саму сохранённую заготовку.
    MP.give.gun   = { on = p.gunOn and true or false,   rows = copyList(p.gunRows, MAX_ROWS) }
    MP.give.armor = { on = p.armorOn and true or false, rows = copyList(p.armorRows, MAX_ROWS) }
    MP.give.hp    = { on = p.hpOn and true or false,    rows = copyList(p.hpRows, MAX_ROWS) }
    MP.give.skin  = { on = p.skinOn and true or false,  rows = copyList(p.skinRows, MAX_ROWS) }
    MP.form.messages = {}
    for i, m in ipairs(p.messages or {}) do
        if i > MAX_MSG then break end
        MP.form.messages[i] = m
    end
    MP.fields = {}      -- буферы ввода пересоздадутся под новые значения
    MP.trigDirty = true
    MP.touch()
end
_G.grndMpApplyPreset = applyPreset

formSnapshot = function()
    local msgs = {}
    for i, m in ipairs(MP.form.messages) do
        if i > MAX_MSG then break end
        msgs[i] = m
    end
    return {
        trigger = MP.form.trigger,
        msgDelay = MP.form.msgDelay, gap = MP.form.gap,
        ansDelay = MP.form.ansDelay, tpDelay = MP.form.tpDelay,
        cooldown = MP.form.cooldown, maxPlayers = MP.form.maxPlayers,
        takeGun = MP.take.gun, takeArmor = MP.take.armor,
        gunOn = MP.give.gun.on,   gunRows   = copyList(MP.give.gun.rows, MAX_ROWS),
        armorOn = MP.give.armor.on, armorRows = copyList(MP.give.armor.rows, MAX_ROWS),
        hpOn = MP.give.hp.on,     hpRows    = copyList(MP.give.hp.rows, MAX_ROWS),
        skinOn = MP.give.skin.on, skinRows  = copyList(MP.give.skin.rows, MAX_ROWS),
        messages = msgs,
    }
end

function MP.currentForm()
    -- runtimeForm уже плоский снимок. До запуска строим такой же снимок,
    -- иначе dryRun видел MP.form без полей gunRows/takeGun.
    return MP.runtimeForm or formSnapshot()
end

-- ===== ПУБЛИЧНОЕ API ЗАГОТОВОК (используется и интерфейсом, и /mp) =====
function MP.savePreset(name)
    local nm = utfCut(cleanText(name), 32)
    if nm == "" then return false, "Введите название заготовки" end
    local snap = formSnapshot()
    snap.name = nm
    for i, p in ipairs(MP.presets) do
        if p.name == snap.name then
            MP.presets[i] = snap
            MP.presetName = ""
            MP.touch()
            return true, "Заготовка «" .. snap.name .. "» обновлена"
        end
    end
    if #MP.presets >= MAX_PRESETS then table.remove(MP.presets, 1) end
    MP.presets[#MP.presets + 1] = snap
    MP.presetName = ""
    MP.touch()
    return true, "Заготовка «" .. snap.name .. "» сохранена"
end

function MP.usePreset(index)
    local p = tonumber(index)
    p = p and MP.presets[p]
    if not p then
        for i, v in ipairs(MP.presets) do
            if v.name == tostring(index) then p = v break end
        end
    end
    if not p then return false, "Заготовка не найдена" end
    applyPreset(p)
    return true, "Заготовка «" .. tostring(p.name) .. "» загружена"
end

function MP.deletePreset(index)
    -- принимаем и номер заготовки, и её название
    local i = tonumber(index)
    if not i or not MP.presets[i] then
        local want = tostring(index or "")
        for k, v in ipairs(MP.presets) do
            if v.name == want then i = k break end
        end
    end
    if not i or not MP.presets[i] then return false end
    local name = MP.presets[i].name
    table.remove(MP.presets, i)
    MP.touch()
    return true, "Заготовка «" .. tostring(name) .. "» удалена"
end

function MP.save()
    local body = { "ver=2" }
    for i, m in ipairs(MP.form.messages or {}) do
        if i > MAX_MSG then break end
        body[#body + 1] = "msg" .. i .. "=" .. esc(m)
    end
    local f = MP.form
    body[#body + 1] = "trigger=" .. esc(f.trigger)
    body[#body + 1] = "msgDelay=" .. tostring(f.msgDelay)
    body[#body + 1] = "gap=" .. tostring(f.gap)
    body[#body + 1] = "ansDelay=" .. tostring(f.ansDelay)
    body[#body + 1] = "tpDelay=" .. tostring(f.tpDelay)
    body[#body + 1] = "cooldown=" .. tostring(f.cooldown)
    body[#body + 1] = "maxPlayers=" .. tostring(f.maxPlayers)
    body[#body + 1] = "takeGun=" .. (MP.take.gun and "1" or "0")
    body[#body + 1] = "takeArmor=" .. (MP.take.armor and "1" or "0")
    local order = { "gun", "armor", "hp", "skin" }
    for _, key in ipairs(order) do
        local g = MP.give[key]
        body[#body + 1] = key .. "On=" .. (g.on and "1" or "0")
        body[#body + 1] = key .. "Rows=" .. rowsToStr(g.rows)
    end
    for _, preset in ipairs(MP.presets or {}) do
        body[#body + 1] = presetLine(preset)
    end

    local encoded = ansiText(table.concat(body, "\n") .. "\n")
    if #encoded > 2 * 1024 * 1024 then
        say("конфиг слишком большой и не сохранён", "error")
        return false
    end

    -- Атомарная запись: панель не оставляет пустой/обрезанный конфиг после
    -- сбоя записи или перезапуска игры.
    local path, tmp, bak = MP.cfgPath, MP.cfgPath .. ".tmp", MP.cfgPath .. ".bak"
    local hadOld = false
    local ok, err = pcall(function()
        local fh = assert(io.open(tmp, "wb"), "не удалось открыть временный конфиг")
        local wrote, why = fh:write(encoded)
        assert(wrote, why or "ошибка записи временного конфига")
        assert(fh:flush())
        assert(fh:close())

        local probe = io.open(path, "rb")
        if probe then
            hadOld = true
            probe:close()
            os.remove(bak)
            assert(os.rename(path, bak))
        end
        local moved, moveErr = os.rename(tmp, path)
        if not moved then
            if hadOld then pcall(os.rename, bak, path) end
            error(moveErr or "не удалось заменить конфиг")
        end
    end)
    if not ok then
        os.remove(tmp)
        say("не удалось сохранить настройки: " .. tostring(err), "error")
        return false
    end
    return true
end

function MP.load()
    if MP.loaded then return end
    MP.loaded = true

    local candidates = { MP.cfgPath }
    if MP.legacyCfgPath and MP.legacyCfgPath ~= MP.cfgPath then
        candidates[#candidates + 1] = MP.legacyCfgPath
    end
    local text, source
    for _, path in ipairs(candidates) do
        local ok, fh = pcall(io.open, path, "rb")
        if ok and fh then
            local okRead, data = pcall(fh.read, fh, 2 * 1024 * 1024 + 1)
            pcall(fh.close, fh)
            if okRead and type(data) == "string" and #data > 0
                and #data <= 2 * 1024 * 1024 then
                text, source = data, path
                break
            end
        end
    end
    if not text or text == "" then return end

    local presetBuf
    local function flushPreset()
        if not presetBuf then return end
        local preset = readPreset(presetBuf)
        if preset and preset.name ~= "" and #MP.presets < MAX_PRESETS then
            MP.presets[#MP.presets + 1] = preset
        end
        presetBuf = nil
    end

    for raw in (text .. "\n"):gmatch("([^\n]*)\n") do
        local line = toUtf((tostring(raw):gsub("\r$", "")))
        line = line:gsub("^\239\187\191", "")
        local k, v = line:match("^([%w_]+)=(.*)$")
        if k == "p" then
            flushPreset()
            presetBuf = v
        elseif presetBuf then
            flushPreset()
            -- This line is a normal setting and must not be lost.
            k, v = line:match("^([%w_]+)=(.*)$")
        end
        if not presetBuf and k then
            if k == "trigger" then MP.form.trigger = unesc(v)
            elseif k == "msgDelay" then MP.form.msgDelay = numOr(v, 1.5, 0.1, 60)
            elseif k == "gap" then MP.form.gap = numOr(v, 0.35, 0.105, 60)
            elseif k == "ansDelay" then MP.form.ansDelay = numOr(v, 1.2, 0, 60)
            elseif k == "tpDelay" then MP.form.tpDelay = numOr(v, 0.8, 0, 60)
            elseif k == "cooldown" then MP.form.cooldown = numOr(v, 180, 0, 86400)
            elseif k == "maxPlayers" then MP.form.maxPlayers = math.floor(numOr(v, 50, 1, 500))
            elseif k == "takeGun" then MP.take.gun = (v == "1")
            elseif k == "takeArmor" then MP.take.armor = (v == "1")
            elseif k == "gunOn" then MP.give.gun.on = (v == "1")
            elseif k == "armorOn" then MP.give.armor.on = (v == "1")
            elseif k == "hpOn" then MP.give.hp.on = (v == "1")
            elseif k == "skinOn" then MP.give.skin.on = (v == "1")
            elseif k == "gunRows" then MP.give.gun.rows = strToRows(v)
            elseif k == "armorRows" then MP.give.armor.rows = strToRows(v)
            elseif k == "hpRows" then MP.give.hp.rows = strToRows(v)
            elseif k == "skinRows" then MP.give.skin.rows = strToRows(v)
            else
                local idx = k:match("^msg(%d+)$")
                if idx then
                    idx = tonumber(idx)
                    if idx and idx >= 1 and idx <= MAX_MSG then
                        MP.form.messages[#MP.form.messages + 1] = unesc(v)
                    end
                end
            end
        end
    end
    flushPreset()

    -- Миграция выполняется отложенно, после первого успешного тика.
    if source and source ~= MP.cfgPath then MP.dirtyAt = now() end
    MP.fields = {}
    MP.trigDirty = true
end

function MP.touch()
    MP.dirtyAt = now()
end

-- ---------------------------------------------------------------------
--  4. РАЗБОР СТРОКИ РЕПОРТА
--     "Nik_Name[261]: помогите  [К-во репорта: 25]"
-- ---------------------------------------------------------------------
function MP.parseReport(text)
    if type(text) ~= "string" or text == "" then return nil end
    if #text > 400 then return nil end
    -- ДЕШЁВЫЙ фильтр: до конвертации кодировки. Под спамом отсекает
    -- почти всё одним find.
    if not text:find("%]%s*:") then return nil end
    local t = cleanText(toUtf(text))
    local nick, pid, msg = t:match("^(.-)%s*%[(%d+)%]%s*:%s*(.+)$")
    if not nick then return nil end
    nick = nick:gsub("^%s+", ""):gsub("%s+$", "")
    local numericId = tonumber(pid)
    if nick == "" or utfLen(nick) > 32 or not numericId or numericId < 0 or numericId > 1003 then
        return nil
    end
    -- маркер репорта обязателен: "… [К-во репорта: N]". Обычная реплика
    -- вида "Ник[261]: привет" репортом не считается.
    local cnt = msg:match("%[К%-во репорта:%s*(%d*)%]")
    if not cnt then cnt = msg:match("репорта:%s*(%d*)%]") end
    if not cnt then return nil end
    if cnt == "" then cnt = 1 end     -- сервер прислал номер пустым
    msg = msg:gsub("%[К%-во репорта:%s*%d*%]", "")
    msg = msg:gsub("%[Кол%-во репорта:%s*%d*%]", "")
    msg = cleanText(msg)
    if msg == "" then msg = "текст репорта" end
    return nick, numericId, msg, tonumber(cnt) or 1
end

-- ---------------------------------------------------------------------
--  5. СЕТЬ И ОТПРАВКА
-- ---------------------------------------------------------------------
function MP.connected()
    if type(isSampAvailable) == "function" then
        local ok, v = pcall(isSampAvailable)
        if ok and (v == false or v == 0) then return false end
    end
    if type(sampGetGamestate) == "function" then
        local ok, state = pcall(sampGetGamestate)
        state = ok and tonumber(state) or nil
        if state then return state == 3 end
    end
    if type(sampIsLocalPlayerConnected) == "function" then
        local ok, v = pcall(sampIsLocalPlayerConnected)
        if ok then return v == true or v == 1 end
    end
    return true    -- нет API — считаем, что подключение есть
end

function MP.online(id)
    id = tonumber(id)
    if not id or id < 0 or id > 1003 then return false end
    if type(sampIsPlayerConnected) == "function" then
        local ok, v = pcall(sampIsPlayerConnected, id)
        if ok then return v == true or v == 1 end
    end
    return true
end

function MP.send(cmd)
    if type(cmd) ~= "string" or cmd == "" then return false end
    if cmd:find(string.char(0), 1, true)
        or cmd:find(string.char(10), 1, true)
        or cmd:find(string.char(13), 1, true) then
        logIt("команда содержит недопустимый перенос — остановлено", "error")
        return false
    end
    local text = ansiText(cmd)
    if #text > MAX_CMD_BYTES then
        -- Нельзя возвращать true: раньше команда пропускалась, но шаг
        -- считался выполненным и игрок получал неполный сценарий.
        logIt("команда длиннее " .. tostring(MAX_CMD_BYTES) .. " байт — остановлено", "error")
        return false
    end
    local send = _G.grndChatSend
    if type(send) == "function" then
        local ok, res = pcall(send, cmd)
        return ok and res ~= false
    end
    if type(sampSendChat) ~= "function" then return false end
    local ok = pcall(sampSendChat, text)
    return ok
end

-- ПРОВЕРКА ФОРМЫ БЕЗ ЗАПУСКА: показывает, какие команды ушли бы игроку.
-- Ничего не отправляет на сервер — можно гонять хоть перед каждым МП.
function MP.dryRun()
    local err = MP.validate()
    if err then
        MP.preview = { ok = false, at = now(), text = err }
        return false, err
    end
    local sample = { id = 261, nick = "Nik_Name" }
    local lines = {}
    for _, st in ipairs(MP.buildSteps(sample)) do
        local cmd = tostring(st.cmd)
        cmd = cmd:gsub("%%ID%%", function() return tostring(sample.id) end)
        cmd = cmd:gsub("%%NICK%%", function() return sample.nick end)
        lines[#lines + 1] = cmd
    end
    local ann = 0
    for _, m in ipairs(MP.form.messages) do
        if cleanText(m) ~= "" then ann = ann + 1 end
    end
    MP.preview = { ok = true, at = now(), lines = lines, announce = ann,
        text = string.format("Форма в порядке: %d команд игроку, объявлений: %d",
            #lines, ann) }
    logIt("Проверка формы: " .. MP.preview.text, "ok")
    return true, MP.preview.text, lines
end

-- ---------------------------------------------------------------------
--  6. ДВИЖОК МЕРОПРИЯТИЯ
-- ---------------------------------------------------------------------
local CATS = {
    { key = "gun",   title = "Оружие",  hint = "ID оружия и патроны, например 31 200",
      pattern = "^(%d+)%s+(%d+)$", sample = "/gun ID 31 200" },
    { key = "armor", title = "Броня",   hint = "количество, например 100",
      pattern = "^(%d+)$", sample = "/arm ID 100" },
    { key = "hp",    title = "Здоровье", hint = "количество, например 100",
      pattern = "^(%d+)$", sample = "/hp ID 100" },
    { key = "skin",  title = "Скин",    hint = "ID скина, например 27",
      pattern = "^(%d+)$", sample = "/setskin ID 27" },
}
local CAT_CMD = {
    gun = "/gun %ID% %V%",
    armor = "/arm %ID% %V%",
    hp = "/hp %ID% %V%",
    skin = "/setskin %ID% %V%",
}

-- Проверка формы перед запуском. Возвращает текст ошибки или nil.
function MP.validate()
    local f = MP.form
    local trig = cleanText(f.trigger)
    if trig == "" then return "Укажите триггер — без него репорты не отфильтруются" end
    if utfLen(trig) > 32 then return "Триггер длиннее 32 символов" end
    if trig:find("[%z\r\n]") then return "Триггер содержит перенос строки" end

    -- Убираем пустые элементы с компактированием. Простое присваивание nil
    -- внутри ipairs раньше обрывало список на первой пустой строке.
    local messages = {}
    for i = 1, math.min(#(f.messages or {}), MAX_MSG) do
        local t = cleanText(f.messages[i])
        if t ~= "" then
            t = utfCut(t, 120)
            if #ansiText(ANNOUNCE_CMD .. " " .. t) > MAX_CMD_BYTES then
                return "Объявление №" .. tostring(i) .. " слишком длинное для чата"
            end
            messages[#messages + 1] = t
        end
    end
    f.messages = messages

    for _, cat in ipairs(CATS) do
        local g = MP.give[cat.key]
        local one = ""
        for i = 1, math.min(#(g.rows or {}), MAX_ROWS) do
            local candidate = cleanText(g.rows[i])
            if candidate ~= "" then
                one = candidate
                break
            end
        end
        if g.on then
            local rows = {}
            local v = one:gsub("[;|\\]", " "):gsub("%s+", " ")
            v = v:gsub("^%s+", ""):gsub("%s+$", "")
            if v ~= "" then rows[1] = v end
            if #rows == 0 then
                return "Раздел «" .. cat.title .. "» включён, но данных нет"
            end
            for _, v in ipairs(rows) do
                local a, b = v:match("^(%d+)%s+(%d+)$")
                local n = tonumber(v)
                if cat.key == "gun" then
                    if not a or not b then
                        return cat.title .. ": нужно указать ID оружия и патроны"
                    end
                    if tonumber(a) < 1 or tonumber(a) > 46 then
                        return cat.title .. ": ID оружия должен быть от 1 до 46"
                    end
                    if tonumber(b) < 1 or tonumber(b) > 9999 then
                        return cat.title .. ": патроны должны быть от 1 до 9999"
                    end
                elseif cat.key == "armor" or cat.key == "hp" then
                    if not n or n < 0 or n > 1000 then
                        return cat.title .. ": значение должно быть числом от 0 до 1000"
                    end
                elseif cat.key == "skin" then
                    if not n or n < 0 or n > 311 then
                        return cat.title .. ": ID скина должен быть от 0 до 311"
                    end
                end
            end
            g.rows = rows
        else
            -- Выключение раздела не удаляет его заготовленное значение.
            g.rows = one ~= "" and { one } or {}
        end
    end

    f.trigger    = trig
    -- Тайминги не являются настройкой панели: серверный сценарий идёт
    -- с единым безопасным интервалом, как в исходной форме МП.
    f.msgDelay   = SEND_RATE
    f.gap        = SEND_RATE
    f.ansDelay   = SEND_RATE
    f.tpDelay    = SEND_RATE
    f.cooldown   = numOr(f.cooldown, 180, 0, 86400)
    f.maxPlayers = math.floor(numOr(f.maxPlayers, 50, 1, 500))
    MP.fields = {}
    MP.trigDirty = true
    MP.touch()
    return nil
end

-- Шаги обработки одного игрока. %ID% и %V% подставляются при отправке.
function MP.buildSteps(job)
    local f = MP.currentForm()
    local gap = tonumber(f.gap) or SEND_RATE
    local steps = {}
    -- 1) ответ на репорт — текст фиксированный
    steps[#steps + 1] = { cmd = "/ans %ID% " .. ANSWER, pause = f.ansDelay }
    steps[#steps + 1] = { cmd = "/gethere %ID%", pause = f.tpDelay }
    if f.takeGun then steps[#steps + 1] = { cmd = "/rgun %ID%", pause = gap } end
    if f.takeArmor then steps[#steps + 1] = { cmd = "/arm %ID% 1", pause = gap } end
    local sections = {
        { key = "gun", on = f.gunOn, rows = f.gunRows },
        { key = "armor", on = f.armorOn, rows = f.armorRows },
        { key = "hp", on = f.hpOn, rows = f.hpRows },
        { key = "skin", on = f.skinOn, rows = f.skinRows },
    }
    for _, cat in ipairs(sections) do
        if cat.on then
            for _, row in ipairs(cat.rows or {}) do
                local v = tostring(row):gsub("%s+", " ")
                steps[#steps + 1] = {
                    cmd = (CAT_CMD[cat.key]:gsub("%%V%%", function() return v end)),
                    pause = gap,
                }
            end
        end
    end
    return steps
end

function MP.stop(reason)
    if not MP.active then return false end
    local lost = #MP.jobs + (MP.cur and 1 or 0)
    MP.active = false
    MP.watch = false
    MP.jobs, MP.cur, MP.announce = {}, nil, nil
    MP.lock, MP.cool = {}, {}
    MP.runtimeForm = nil
    MP.nextAt = 0
    local text = reason or "МП остановлено"
    if lost > 0 then text = text .. " (" .. lost .. " в очереди снято)" end
    logIt(text, "warn")
    flash(text, "warn")
    say(text, "warn")
    MP.touch()
    return true
end

function MP.start()
    if MP.active then
        flash("МП уже запущено", "warn")
        return false
    end
    if type(grndUiBlocked) == "function" then
        local okBlocked, blocked = pcall(grndUiBlocked)
        if okBlocked and blocked then
            flash("МП нельзя запустить на экране авторизации", "error")
            return false
        end
    end
    local err = MP.validate()
    if err then
        flash(err, "error")
        logIt("Запуск отменён: " .. err, "error")
        return false
    end
    if not MP.connected() then
        flash("Нет подключения к серверу", "error")
        return false
    end
    if type(_G.grndChatSend) ~= "function" and type(sampSendChat) ~= "function" then
        flash("Нет функции отправки команд в чат", "error")
        return false
    end
    if not MP.chainReady and type(installHook) == "function" then
        local okCall, hooked = pcall(installHook)
        MP.hookOk = okCall and hooked == true
        if not MP.hookOk then
            flash("Не удалось подключить обработчик чата", "error")
            return false
        end
    end

    -- Снимок делает текущий запуск предсказуемым: редактирование формы
    -- во время уже идущего МП не меняет сценарий у игроков в очереди.
    MP.runtimeForm = formSnapshot()
    local run = MP.runtimeForm
    local t = now()
    MP.active = true
    MP.watch = false
    MP.startedAt = t
    MP.players, MP.sent, MP.done = 0, 0, 0
    MP.jobs, MP.cur, MP.cool, MP.lock = {}, nil, {}, {}
    MP.nextAt = t
    MP.tokens, MP.lastTokenAt = PARSE_BURST, t
    MP.lastMessageText, MP.lastMessageAt = nil, -math.huge
    MP.trigCache, MP.trigCacheAt, MP.trigDirty = nil, nil, true
    MP.stat = { parsed = 0, matched = 0, skipped = 0, dropped = 0 }

    local steps = {}
    for _, m in ipairs(run.messages or {}) do
        local t2 = cleanText(m)
        if t2 ~= "" then
            steps[#steps + 1] = { cmd = ANNOUNCE_CMD .. " " .. t2, pause = run.msgDelay }
        end
    end
    if #steps > 0 then
        MP.announce = { steps = steps, step = 1 }
        logIt("Отправляю объявлений: " .. #steps, "info")
    else
        MP.announce = nil
        MP.watch = true
    end
    logIt("МП запущено, триггер: «" .. run.trigger .. "»", "ok")
    if not MP.hookOk and not MP.chainReady then
        -- Запасной хук будет поставлен tick(), если основная цепочка
        -- sampev.onServerMessage не была зарегистрирована.
        logIt("перехват чата будет проверен автоматически", "info")
    end
    flash("МП запущено", "ok")
    MP.touch()
    return true
end

local function finishJob(job)
    MP.lock[job.id] = nil
    local run = MP.currentForm()
    MP.cool[job.id] = now() + (tonumber(run.cooldown) or 180)
    MP.done = MP.done + 1
    MP.cur = nil
    logIt(job.nick .. " [" .. job.id .. "] — готово", "ok")
end

-- ЕДИНАЯ ТОЧКА ОТПРАВКИ: одна команда за вызов, ничего не спешит.
function MP.pump()
    if not MP.active then return end
    local t = now()
    if t < MP.nextAt then return end
    if not MP.connected() then
        MP.stop("Соединение потеряно")
        return
    end

    local job = MP.announce or MP.cur
    if not job then
        if #MP.jobs == 0 then
            -- v1.19.03: здесь был автостоп по «лимиту участников» — убран.
            -- МП не заканчивается само: только кнопка «Остановить» или /mp stop.
            MP.nextAt = t + 0.5
            return
        end
        job = table.remove(MP.jobs, 1)
        MP.cur = job
        job.step = 1
        if job.id then
            logIt(job.nick .. " [" .. job.id .. "] — в обработке")
        end
    end

    local st = job.steps[job.step]
    if not st then
        if job.id then
            finishJob(job)
        else
            MP.announce = nil
            MP.watch = true
            logIt("Объявления отправлены, слежение включено", "ok")
            flash("Слежение за репортом включено", "ok")
        end
        return
    end

    if job.id then
        if MP.lock[job.id] == nil then
            MP.cur = nil          -- очередь сбросили вручную
            return
        end
        if not MP.online(job.id) then
            logIt(job.nick .. " [" .. job.id .. "] вышел — отменено", "warn")
            MP.lock[job.id] = nil
            MP.players = math.max(0, (MP.players or 0) - 1)
            local run = MP.currentForm()
            MP.cool[job.id] = t + (tonumber(run.cooldown) or 180)
            MP.cur = nil
            return
        end
    end

    local cmd = tostring(st.cmd):gsub("%%ID%%", function() return tostring(job.id or 0) end)
    if not MP.send(cmd) then
        MP.stop("Отправка команды не удалась")
        return
    end
    job.step = job.step + 1
    if job.id then
        MP.sent = MP.sent + 1
        MP.lastCmd = cmd
    end
    -- SEND_RATE — только нижняя граница: пользовательские паузы не
    -- затираются, но и слишком быстрый поток команд не допускается.
    local gap = tonumber(st.pause) or 0
    MP.nextAt = t + math.max(SEND_RATE, gap)
end

-- ---------------------------------------------------------------------
--  7. ПРИЁМ РЕПОРТА (горячий путь — на каждой строке чата)
-- ---------------------------------------------------------------------
function MP.onServerMessage(text)
    -- Основной обработчик и запасной хук могут увидеть одну строку дважды.
    -- Ставим флаг готовности здесь и отбрасываем только мгновенный дубль,
    -- не блокируя реальные одинаковые репорты через несколько кадров.
    MP.chainSeen, MP.chainReady, MP.hookOk = true, true, true
    if not (MP.active and MP.watch) then return end
    if type(text) ~= "string" or text == "" then return end
    local t = now()
    if MP.lastMessageText == text and t - (MP.lastMessageAt or -math.huge) >= 0
        and t - (MP.lastMessageAt or -math.huge) < 0.05 then
        return
    end
    MP.lastMessageText, MP.lastMessageAt = text, t

    -- быстрый выход по длине и по форме строки (до конвертации)
    if #text > 400 then return end
    if not text:find("%]%s*:") then return end

    -- Ведро токенов: отрицательный скачок таймера не должен обнулить его.
    local dt = t - (MP.lastTokenAt or t)
    if dt < 0 then dt = 0 end
    MP.tokens = math.min(PARSE_BURST,
        (MP.tokens or PARSE_BURST) + dt * PARSE_RATE)
    MP.lastTokenAt = t
    if MP.tokens < 1 then
        MP.stat = MP.stat or { parsed = 0, matched = 0, skipped = 0, dropped = 0 }
        MP.stat.dropped = MP.stat.dropped + 1
        return
    end
    MP.tokens = MP.tokens - 1

    local nick, id, msg, cnt = MP.parseReport(text)
    if not id then return end
    MP.stat = MP.stat or { parsed = 0, matched = 0, skipped = 0, dropped = 0 }
    MP.stat.parsed = MP.stat.parsed + 1

    local run = MP.currentForm()
    local trig = MP.trigCache
    if trig == nil or MP.trigDirty or (t - (MP.trigCacheAt or 0)) > 2 then
        trig = lowerUtf(run.trigger)
        MP.trigCache, MP.trigCacheAt, MP.trigDirty = trig, t, false
    end
    if trig == "" then return end
    if not lowerUtf(msg):find(trig, 1, true) then
        MP.stat.skipped = MP.stat.skipped + 1
        return
    end
    MP.stat.matched = MP.stat.matched + 1

    -- анти-спам
    if MP.lock[id] then return end
    local cool = MP.cool[id]
    if cool and t < cool then return end
    if (#MP.jobs + (MP.cur and 1 or 0)) >= MAX_QUEUE then
        MP.stat.dropped = MP.stat.dropped + 1
        logIt("очередь переполнена — " .. nick .. " [" .. id .. "] пропущен", "warn")
        return
    end
    if not MP.online(id) then return end

    MP.lock[id] = true
    MP.players = MP.players + 1
    local job = { id = id, nick = nick, at = t, step = 1, cnt = cnt }
    job.steps = MP.buildSteps(job)
    MP.jobs[#MP.jobs + 1] = job
    logIt(nick .. " [" .. id .. "] — в очередь (" .. #MP.jobs .. "), репорт №" .. tostring(cnt))
end

-- ---------------------------------------------------------------------
--  8. ПЕРЕХВАТ ЧАТА (страховка, если цепочка скрипта недоступна)
--     Пометка «уже наш» хранится в слабой таблице: rawget/rawset на
--     функции не работают ни в LuaJIT, ни в Lua 5.4+.
-- ---------------------------------------------------------------------
local HOOKED = setmetatable({}, { __mode = "k" })

installHook = function()
    local ok, sampev = pcall(require, "samp.events")
    if not ok or not sampev then
        ok, sampev = pcall(require, "lib.samp.events")
    end
    if not ok or not sampev then return false end
    local prev = sampev.onServerMessage
    if type(prev) ~= "function" then prev = nil end
    if prev and HOOKED[prev] then
        MP.hookOk = true
        MP.chainReady = true
        return true
    end
    local function wrapper(color, text, ...)
        local r1, r2, r3
        if prev then r1, r2, r3 = prev(color, text, ...) end
        pcall(MP.onServerMessage, text)
        return r1, r2, r3
    end
    HOOKED[wrapper] = true
    sampev.onServerMessage = wrapper
    MP.hookOk = true
    return true
end

-- ---------------------------------------------------------------------
--  9. ИНТЕРФЕЙС
-- ---------------------------------------------------------------------
local bitLib = _G.bit

local function rgba(r, g, b, a)
    local im = _G.GRND_IM
    if im and im.ImVec4 then
        return im.ImVec4((tonumber(r) or 0) / 255, (tonumber(g) or 0) / 255,
            (tonumber(b) or 0) / 255, (tonumber(a) or 255) / 255)
    end
    return { r = r, g = g, b = b, a = a }
end

local function col32(r, g, b, a)
    a = a or 255
    r = math.floor(tonumber(r) or 0) % 256
    g = math.floor(tonumber(g) or 0) % 256
    b = math.floor(tonumber(b) or 0) % 256
    a = math.floor(tonumber(a) or 0) % 256
    if bitLib and bitLib.bor and bitLib.lshift then
        return bitLib.bor(r, bitLib.lshift(g, 8), bitLib.lshift(b, 16), bitLib.lshift(a, 24))
    end
    return r + g * 0x100 + b * 0x10000 + a * 0x1000000
end

local function roundRect(dl, p1, p2, col, rounding, flags)
    if rounding and rounding > 0 then
        local ok = pcall(dl.AddRectFilled, dl, p1, p2, col, rounding, flags or 0)
        if ok then return end
    end
    pcall(dl.AddRectFilled, dl, p1, p2, col)
end

local function frameRect(dl, p1, p2, col, rounding, thickness)
    if dl.AddRect then
        pcall(dl.AddRect, dl, p1, p2, col, rounding or 0, 0, thickness or 1)
    end
end

local HAS_MULTI = nil
local function gradRect(dl, p1, p2, c1, c2, rounding)
    if HAS_MULTI == nil then
        local im = _G.GRND_IM
        HAS_MULTI = (im and im.ImDrawList_AddRectFilledMultiColor) and true or false
    end
    if HAS_MULTI then
        local im = _G.GRND_IM
        if im.ImDrawList_AddRectFilledMultiColor then
            local ok = pcall(im.ImDrawList_AddRectFilledMultiColor, dl, p1, p2, c1, c2, c2, c1)
            if ok then return end
        end
    end
    local ok = pcall(dl.AddRectFilledMultiColor, dl, p1, p2, c1, c2, c2, c1)
    if ok then return end
    roundRect(dl, p1, p2, c1, rounding or 0)
end

local function tsizeOf(im, s)
    s = tostring(s or "")
    if im and im.CalcTextSize then
        local ok, r = pcall(im.CalcTextSize, s)
        if ok then
            local tp = type(r)
            if tp == "table" or tp == "cdata" then
                local xx, yy = tonumber(r and r.x), tonumber(r and r.y)
                if xx then return xx, yy or 14 end
            elseif tp == "number" then
                return r, 14
            end
        end
    end
    return utfLen(s) * 7, 14
end

local function uiTextFallback(im)
    return function(x, y, str, col, scale)
        im.SetCursorPos(im.ImVec2(x, y))
        if scale and scale ~= 1 and type(im.SetWindowFontScale) == "function" then
            pcall(im.SetWindowFontScale, scale)
        end
        if im.TextUnformatted then im.TextUnformatted(tostring(str))
        else im.Text(tostring(str)) end
        if scale and scale ~= 1 and type(im.SetWindowFontScale) == "function" then
            pcall(im.SetWindowFontScale, 1)
        end
    end
end

-- ---- буферы ввода -------------------------------------------------
local function newBuf(im, cap)
    if im.new and im.new.char then
        local ok, b = pcall(function() return im.new.char[cap]() end)
        if ok and b then return b, "ffi" end
    end
    if type(im.ImBuffer) == "function" then
        local ok, b = pcall(im.ImBuffer, cap)
        if ok and b then return b, "legacy" end
    end
    return nil, nil
end

local function writeBuf(f, text)
    if f.kind == "ffi" then
        local w = _G.grndBinderWriteCBuf
        if type(w) == "function" then pcall(w, f.buf, f.cap, text) return end
        local ok, ffi = pcall(require, "ffi")
        if ok then
            pcall(function()
                ffi.fill(f.buf, f.cap, 0)
                if #text > 0 then ffi.copy(f.buf, text) end
            end)
        end
    else
        pcall(function() f.buf.v = text end)
    end
end

local function readBuf(f)
    if f.kind == "ffi" then
        local r = _G.grndBinderReadCBuf
        if type(r) == "function" then
            local ok, v = pcall(r, f.buf)
            if ok and type(v) == "string" then return v end
        end
        local ok, ffi = pcall(require, "ffi")
        if ok then
            local ok2, s = pcall(ffi.string, f.buf)
            if ok2 and type(s) == "string" then return (s:gsub("%z", "")) end
        end
        return ""
    end
    local ok, v = pcall(function() return f.buf.v end)
    if not ok or v == nil then ok, v = pcall(function() return f.buf.value end) end
    return (ok and v ~= nil) and tostring(v) or ""
end

local function fieldBuf(key, cap, value)
    local f = MP.fields[key]
    if f and (f.cap ~= cap or f.im ~= _G.GRND_IM) then f = nil end
    if not f then
        f = { cap = cap, im = _G.GRND_IM }
        local buf, kind = newBuf(_G.GRND_IM, cap)
        if not buf then return nil end
        f.buf, f.kind = buf, kind
        MP.fields[key] = f
    end
    -- буфер живёт по значению модели: если значение сменилось извне
    -- (заготовка, /mp, сброс) — переписываем поле сами
    value = tostring(value or "")
    if f.model == nil or f.model ~= value then
        writeBuf(f, value)
        f.model = value
    end
    return f
end

local function fieldSync(key)
    local f = MP.fields[key]
    if f then f.model = nil end
end

local function dropFields(prefix)
    for k in pairs(MP.fields) do
        if type(k) == "string" and k:sub(1, #prefix) == prefix then MP.fields[k] = nil end
    end
end

-- Поле ввода.
-- Два требования, из-за которых оно раньше выглядело кривым и теряло текст:
--   1) рамку рисует ImGui (FrameBg), значит наша рамка должна лечь РОВНО на
--      тот же прямоугольник: та же ширина, та же высота, то же скругление,
--      иначе видно двойной контур и «перекошенное» поле;
--   2) буфер нельзя перезаписывать моделью, пока в него вводят: сначала
--      читаем буфер, и только если он разошёлся с моделью — отдаём новое
--      значение наверх. Раньше было наоборот, и набранное пропадало.
-- Поле ввода.
-- Из-за чего раньше было «криво» и пропадал текст:
--   * рамку рисует ImGui (FrameBg) — наша рамка должна лечь РОВНО на тот же
--     прямоугольник. Считать его на глаз нельзя: берём настоящие габариты
--     поля из GetItemRectMin/Max и обводим именно их;
--   * буфер нельзя перезаписывать моделью, пока в него вводят: сначала
--     читаем буфер и только если он разошёлся с моделью — отдаём новое
--     значение наверх. Раньше было наоборот, и набранное исчезало.
local theme                       -- объявлена заранее: нужна в textInput
local INPUT_SIG = nil
local FIELD_H, FIELD_IM = nil, nil   -- настоящая высота поля в этой сборке ImGui
local BIG_INPUT_H = 30                -- тонкая строка с вертикально центрированным текстом
local MULTILINE_MIN_H = 40             -- Multiline нужен только для действительно высоких полей

local function itemRect(im, fbX, fbY, fbW, fbH)
    -- габариты последнего элемента; ImGui отдаёт их в экранных координатах
    if type(im.GetItemRectMin) == "function" and type(im.GetItemRectMax) == "function" then
        local ok1, a = pcall(im.GetItemRectMin)
        local ok2, b = pcall(im.GetItemRectMax)
        local okp, p = pcall(im.GetWindowPos)
        if ok1 and ok2 and okp and a and b and p and a.x and b.x and p.x then
            return a.x - p.x, a.y - p.y, b.x - a.x, b.y - a.y
        end
    end
    return fbX, fbY, fbW, fbH
end

-- Обёртки над push/pop самого ImGui. Панель собирает ctx сама и хелперов
-- окна (grndPushCol/grndPushStyleF) у неё нет — поэтому пушим напрямую и
-- считаем, что удалось, чтобы потом снять ровно столько же.
local function mpPushCol(im, idx, r, g, b, a)
    if not (im and im.PushStyleColor and idx ~= nil and im.ImVec4) then return false end
    -- конструктор цвета тоже под pcall: в части сборок im.ImVec4 — не функция,
    -- а тип, и прямое обращение уронило бы отрисовку всей панели
    local okC, col = pcall(im.ImVec4, r / 255, g / 255, b / 255, (a or 255) / 255)
    if not okC then return false end
    return pcall(im.PushStyleColor, idx, col)
end
local function mpPushVar2(im, idx, vx, vy)
    if not (im and idx ~= nil) then return false end
    local v
    if im.ImVec2 then
        local okV, vec = pcall(im.ImVec2, vx, vy)
        if okV then v = vec end
    end
    if not v then v = { x = vx, y = vy } end
    if im.PushStyleVarVec2 and pcall(im.PushStyleVarVec2, idx, v) then return true end
    if im.PushStyleVar and pcall(im.PushStyleVar, idx, v) then return true end
    return false
end
local function mpPushVarF(im, idx, val)
    if not (im and idx ~= nil) then return false end
    if im.PushStyleVarFloat and pcall(im.PushStyleVarFloat, idx, val) then return true end
    if im.PushStyleVar and pcall(im.PushStyleVar, idx, val) then return true end
    return false
end

-- Снять ровно n цветов/переменных стиля. Снимаем ПО ОДНОМУ: в части сборок
-- PopStyleColor(n) молча снимает только один элемент и стек ImGui утекает —
-- тогда цвета во всём меню начинают «дёргаться» и мигать. Одиночный вызов
-- работает одинаково везде, а если он не принимает аргумент — есть фолбэк.
local function mpPopCols(im, n)
    n = tonumber(n) or 0
    if not im or n <= 0 then return end
    for _ = 1, n do
        if not pcall(im.PopStyleColor, 1) then pcall(im.PopStyleColor) end
    end
end
local function mpPopVars(im, n)
    n = tonumber(n) or 0
    if not im or n <= 0 then return end
    for _ = 1, n do
        if not pcall(im.PopStyleVar, 1) then pcall(im.PopStyleVar) end
    end
end

-- Поле ввода.
-- v1.19.05: выглядит как поле «Название» в «Репорт → Ответы на репорт»:
-- тёмная заливка, отступ текста 9 px, тонкая рамка (белая — спокойно,
-- ярче — при наведении, акцентная — в фокусе). Раньше цвета задавались
-- через grndBinderPushColors (в этой сборке его может не быть), высота
-- подгонялась «на глаз», и поле отличалось от остальных разделов.
local function textInput(ctx, key, id, cap, value, x, y, w, h, hint, onChange)
    local im = ctx.im
    local f = fieldBuf(key, cap, value)
    if not f then
        ctx.uiText(x + 2, y + 5, "поля ввода недоступны в этой сборке ImGui",
            ctx.c4({ 255, 120, 120, 255 }), 0.85)
        return tostring(value or "")
    end
    -- Высота самого InputText равна высоте строки: раньше кэш реальной
    -- высоты оставлял тонкий виджет внутри высокой внешней разметки.
    local fh = h
    local oy = y
    im.SetCursorPos(ctx.pos(x, oy))
    -- Некоторые сборки ImGui игнорируют только PushItemWidth для InputText.
    -- Дублируем ширину через SetNextItemWidth, чтобы менялось именно поле,
    -- а не только окружающая разметка.
    local inputW = math.floor(w)
    if im.SetNextItemWidth then pcall(im.SetNextItemWidth, inputW) end
    local pushedWidth = false
    if im.PushItemWidth then pushedWidth = pcall(im.PushItemWidth, inputW) end
    -- InputText в некоторых moonimgui-сборках всё равно остаётся высотой
    -- около 20 px, даже при изменении FramePadding. Для крупных полей
    -- используем настоящий multiline-виджет с явным размером — он остаётся
    -- обычным текстовым полем, но его кликаемая область действительно высокая.
    -- Для тонкой однострочной строки используем обычный InputText:
    -- он умеет вертикально центрировать текст через FramePadding.
    -- Multiline оставляем только для реально высоких полей.
    local useMultiline = h >= MULTILINE_MIN_H and type(im.InputTextMultiline) == "function"
    local multilineUsed = useMultiline
    -- поле делаем заметно крупнее: высота InputText = шрифт + 2*FramePadding.y,
    -- поэтому поднимаем вертикальный паддинг под высоту строки
    -- Отступы текста внутри поля и тонкая рамка ImGui — как у поля
    -- «Название»: 9 px слева, строка по центру высоты поля.
    local padN = 0
    if im.StyleVar and im.StyleVar.FramePadding and not useMultiline then
        if mpPushVar2(im, im.StyleVar.FramePadding, 9,
            math.max(2, math.floor((h - 14) / 2))) then padN = 1 end
    end
    local borderN = 0
    if im.StyleVar and im.StyleVar.FrameBorderSize then
        if mpPushVarF(im, im.StyleVar.FrameBorderSize, 1) then borderN = 1 end
    end
    local nCol = 0
    if im.Col then
        if mpPushCol(im, im.Col.FrameBg, 12, 15, 22, 255) then nCol = nCol + 1 end
        if mpPushCol(im, im.Col.FrameBgHovered, 18, 22, 31, 255) then nCol = nCol + 1 end
        if mpPushCol(im, im.Col.FrameBgActive, 21, 26, 36, 255) then nCol = nCol + 1 end
        if mpPushCol(im, im.Col.Text, 233, 237, 246, 255) then nCol = nCol + 1 end
        if mpPushCol(im, im.Col.Border, 255, 255, 255, 36) then nCol = nCol + 1 end
    end

    local function callMultiline()
        local sz = im.ImVec2(inputW, h)
        -- В разных версиях mimgui порядок аргументов отличается:
        -- FFI-буфер обычно требует capacity перед размером, а ImBuffer —
        -- только размер. Пробуем совместимые сигнатуры и запоминаем удачную.
        local function invoke(sig)
            if sig == 1 then return im.InputTextMultiline(id, f.buf, cap, sz, 0) end
            if sig == 2 then return im.InputTextMultiline(id, f.buf, cap, sz) end
            if sig == 3 then return im.InputTextMultiline(id, f.buf, sz, 0) end
            return im.InputTextMultiline(id, f.buf, sz)
        end
        local order
        if f.multiSig then
            order = { f.multiSig }
        elseif f.kind == "ffi" then
            order = { 1, 2, 3, 4 }
        else
            order = { 3, 4, 1, 2 }
        end
        local lastErr = "InputTextMultiline недоступен"
        for _, sig in ipairs(order) do
            local okM, result = pcall(invoke, sig)
            if okM then
                f.multiSig = sig
                return result
            end
            lastErr = result
            if f.multiSig then f.multiSig = nil end
        end
        error(lastErr)
    end

    local function call(sig, withHint)
        if useMultiline then
            return callMultiline()
        elseif withHint and hint and im.InputTextWithHint then
            local ok, r = pcall(im.InputTextWithHint, id, hint, f.buf, cap)
            if ok then return r end
            return im.InputTextWithHint(id, hint, f.buf)
        elseif sig == 1 then
            return im.InputText(id, f.buf, cap)
        else
            return im.InputText(id, f.buf)
        end
    end
    local ok, changed = pcall(call, INPUT_SIG or 1, true)
    if not ok and useMultiline then
        -- Fallback для старых обёрток без рабочей сигнатуры Multiline.
        useMultiline = false
        multilineUsed = false
        ok, changed = pcall(call, INPUT_SIG or 1, true)
    end
    if not ok and INPUT_SIG == nil then
        ok, changed = pcall(call, 1, false)      -- нет InputTextWithHint
    end
    if not ok and INPUT_SIG == nil then
        INPUT_SIG = 2                             -- нет аргумента с длиной
        ok, changed = pcall(call, 2, false)
    end
    if ok and INPUT_SIG == nil then INPUT_SIG = 1 end

    local rx, ry, rw, rh = itemRect(im, x, oy, w, fh)
    if rh and rh > 4 and rh < 200 and FIELD_IM ~= im then
        FIELD_H, FIELD_IM = rh, im
    elseif rh and rh > 4 and rh < 200 then
        FIELD_H = rh
    end

    -- снимаем по одному: счётная форма в части сборок снимает только один
    -- элемент, и стек стилей утекал (от этого «дёргались» цвета в меню)
    if nCol > 0 and im.PopStyleColor then mpPopCols(im, nCol) end
    if (padN + borderN) > 0 and im.PopStyleVar then mpPopVars(im, padN + borderN) end
    if pushedWidth and im.PopItemWidth then pcall(im.PopItemWidth) end

    -- Рамка по фактическим габаритам поля — как у «Название»: спокойная
    -- белая, ярче при наведении, акцентная в фокусе (одна рамка, не две).
    local hov, act = false, false
    if im.IsItemHovered then pcall(function() hov = im.IsItemHovered() and true or false end) end
    if im.IsItemActive then pcall(function() act = im.IsItemActive() and true or false end) end
    local accentCol = (theme().accent) or { 164, 112, 224, 255 }
    local edge = act and col32(accentCol[1], accentCol[2], accentCol[3], 190)
        or (hov and col32(255, 255, 255, 60) or col32(255, 255, 255, 30))
    if ctx.dl.AddRect then
        pcall(ctx.dl.AddRect, ctx.dl, ctx.at(rx + 0.5, ry + 0.5),
            ctx.at(rx + rw - 0.5, ry + rh - 0.5), edge, 6, 0, 1)
    end

    -- У Multiline нет InputTextWithHint; рисуем подсказку поверх пустого
    -- поля, сохраняя тот же внешний вид и ручной ввод.
    local vBefore = readBuf(f)
    if multilineUsed and hint and vBefore == "" then
        local hintFontH = tonumber(im.FontSize) or 14
        if hintFontH <= 0 then hintFontH = 14 end
        local hintY = oy + math.max(2, math.floor((h - hintFontH) / 2))
        ctx.uiText(x + 10, hintY, hint, ctx.c4(theme().textMuted), 0.88)
    end

    -- Главное: буфер — источник истины, модель догоняет его, а не наоборот.
    local v = vBefore
    local modelChanged = false
    if f.model == nil or v ~= f.model then
        f.model = v
        modelChanged = true
        if onChange then pcall(onChange, v) end
    end
    if not modelChanged and onChange and tostring(value or "") ~= v then
        pcall(onChange, v)
        modelChanged = true
    end
    if modelChanged then MP.touch() end
    return v
end

theme = function()
    local fn = _G.grndUiTheme
    if type(fn) == "function" then
        local ok, t = pcall(fn)
        if ok and type(t) == "table" then return t end
    end
    local k = _G.GRND_UIKIT
    if k and type(k.TH) == "table" then return k.TH end
    return {
        bg = { 18, 17, 23, 255 }, line = { 255, 255, 255, 20 },
        -- v1.19.04: тона подняты вместе с GRND_UIKIT.SHARED (подписи блекли)
        textHi = { 252, 250, 255, 255 }, text = { 234, 230, 244, 255 },
        textDim = { 198, 192, 216, 255 }, textMuted = { 172, 166, 190, 255 },
        accent = { 164, 112, 224, 255 }, accent2 = { 164, 112, 224, 255 },
    }
end

local function statusColor(kind)
    local TH = theme()
    if kind == "ok" then return { 120, 220, 150, 255 } end
    if kind == "warn" then return { 247, 176, 92, 255 } end
    if kind == "error" then return { 255, 120, 120, 255 } end
    return TH.accent or { 164, 112, 224, 255 }
end

local function trashIcon(ctx, cx, cy, col)
    local dl, at = ctx.dl, ctx.at
    pcall(dl.AddRectFilled, dl, at(cx - 3.5, cy - 3), at(cx + 3.5, cy + 4.5), col)
    pcall(dl.AddLine, dl, at(cx - 5, cy - 3), at(cx + 5, cy - 3), col, 1.3)
    pcall(dl.AddLine, dl, at(cx - 1.8, cy - 5), at(cx + 1.8, cy - 5), col, 1.3)
    pcall(dl.AddLine, dl, at(cx - 1.2, cy - 1), at(cx - 1.2, cy + 2.5), col, 1.1)
    pcall(dl.AddLine, dl, at(cx + 1.2, cy - 1), at(cx + 1.2, cy + 2.5), col, 1.1)
end

local function gearIcon(ctx, cx, cy, col)
    -- DrawList принимает именно ImU32, не ImVec4: поэтому цвет приходит
    -- сюда уже упакованным через col32, иначе шестерёнка молча исчезает.
    local dl, at = ctx.dl, ctx.at
    local r0, r1 = 5.0, 8.0
    for i = 0, 7 do
        local a = -math.pi / 2 + i * math.pi / 4
        pcall(dl.AddLine, dl,
            at(cx + math.cos(a) * r0, cy + math.sin(a) * r0),
            at(cx + math.cos(a) * r1, cy + math.sin(a) * r1), col, 2.0)
    end
    if dl.AddCircle then
        pcall(dl.AddCircle, dl, at(cx, cy), 5.2, col, 16, 1.8)
    end
    if dl.AddCircleFilled then
        pcall(dl.AddCircleFilled, dl, at(cx, cy), 2.0,
            col32(18, 17, 23, 255), 12)
    end
end

-- Наведение для слоя подсветки и для заливки кнопки должно приходить из
-- ОДНОГО источника на кадр. Раньше заливку выбирал ImGui (IsItemHovered),
-- а слой подсветки — наша проверка курсора: значения могли разойтись на
-- кадр, и кнопка мигала («дёргалась») между спокойным и подсвеченным видом.
local MP_HOVER = { id = nil, frame = -99 }
local function mpWindowHovered(im)
    if not (im and im.IsWindowHovered) then return true end
    local ok, over = pcall(im.IsWindowHovered)
    if not ok then return true end
    return over and true or false
end

-- Дополнительный предохранитель к «своему» клику панели (см. ownMouseClick).
-- ImGui не во всех сборках отдаёт ItemHovered для кнопок внутри вкладки,
-- поэтому клик там считается по координате мыши. Координата может прийти
-- раньше, чем ImGui обновит курсор (WM-сообщение «забегает вперёд»), и тогда
-- нажимается соседняя ячейка — со стороны это выглядит как «кнопка пропала,
-- а потом появилась». Если сборка умеет сказать, что ввод готов
-- (onClickReady/onInputReady) — уважаем ответ; если функции нет, поведение
-- прежнее, а один раз в консоль уходит пояснение.
local CLICK_GATE_MISS = 0
local function onClickReady()
    local fns = { _G.onClickReady, _G.grndOnClickReady, _G.onInputReady }
    local seen = false
    for i = 1, #fns do
        local f = fns[i]
        if type(f) == "function" then
            seen = true
            local ok, ready = pcall(f)
            if ok and ready == false then return false end
        end
    end
    if not seen then
        CLICK_GATE_MISS = CLICK_GATE_MISS + 1
        if CLICK_GATE_MISS == 1 then
            pcall(print, "{FFCC66}[GRND]{FFFFFF} панель МП: сборка не сообщает готовность ввода"
                .. " (onClickReady) — резервный клик по координате мыши")
        end
    end
    return true
end

-- слой подсветки при наведении: рисуем поверх кнопки, поэтому работает
-- и с хелпером основного скрипта, и с запасной отрисовкой
local function hoverLayer(ctx, x, y, w, h, opts)
    local c = opts.danger and { 255, 96, 96 } or theme().accent
    roundRect(ctx.dl, ctx.at(x + 1, y + 1), ctx.at(x + w - 1, y + h - 1),
        col32(c[1], c[2], c[3], 46), 6)
    frameRect(ctx.dl, ctx.at(x + 0.5, y + 0.5), ctx.at(x + w - 0.5, y + h - 0.5),
        col32(c[1], c[2], c[3], 165), 6, 1)
end

local function button(ctx, id, x, y, w, h, label, opts)
    opts = opts or {}
    -- ВАЖНО: im — ЛОКАЛЬНАЯ из ctx. Раньше ниже в ownMouseClick стояло «im.»
    -- без объявления: в скрипте нет глобальной im (есть только _G.GRND_IM),
    -- поэтому при наведении на кнопку панели вылетало
    -- «attempt to index a nil value (global 'im')» — ошибка появлялась ровно
    -- тогда, когда курсор входил в кнопку (v1.19.05–1.19.07).
    local im = ctx.im
    -- id всегда со «##»: иначе ImGui нарисует сам текст id внутри кнопки
    local full = (type(id) == "string" and id:sub(1, 2) == "##") and id or ("##mp_" .. tostring(id))

    -- В некоторых сборках MoonLoader штатный ImGui получает WM-клик на кадр
    -- позже/раньше своего состояния. Берём собственную координату мыши как
    -- резерв: это не заменяет ImGui, а только спасает hover/click именно
    -- внутри этой кнопки.
    -- Курсор внутри кнопки?
    -- ВАЖНО (v1.19.05): обе «мыши» — и ImGui.GetIO().MousePos, и WM lParam —
    -- приходят в ОДНИХ координатах (клиентская область окна игры), а
    -- ctx.x/ctx.y — позиция окна меню в тех же координатах. Раньше здесь
    -- была ВТОРАЯ проверка «как будто мышь задана в локальных координатах
    -- окна»: она совпадала почти с любой точкой экрана, и кнопки панели
    -- нажимались «в рандомном месте» (клик у верхнего левого угла попадал
    -- в кнопку, нарисованную ниже). Вторую проверку убрали совсем.
    local function pointInside(mx, my)
        local ox, oy = tonumber(ctx.x), tonumber(ctx.y)
        if not mx or not my or not ox or not oy then return false end
        return mx >= ox + x and mx <= ox + x + w
            and my >= oy + y and my <= oy + y + h
    end
    local function ioMousePos()
        local im = ctx.im
        if not im or type(im.GetIO) ~= "function" then return nil, nil end
        local ok, io = pcall(im.GetIO)
        if not ok or not io or not io.MousePos then return nil, nil end
        local okp, mx, my = pcall(function() return io.MousePos.x, io.MousePos.y end)
        if okp then return tonumber(mx), tonumber(my) end
        return nil, nil
    end
    local function ownMouseInside()
        local mx, my = ioMousePos()
        if pointInside(mx, my) then return true end
        local m = _G.GRND_MOUSE
        if type(m) ~= "table" then return false end
        return pointInside(tonumber(m.x), tonumber(m.y))
    end
    local function ioMouseClicked()
        local im = ctx.im
        if not im or type(im.GetIO) ~= "function" then return false end
        local ok, io = pcall(im.GetIO)
        if not ok or not io or not io.MouseClicked then return false end
        local okc, clicked = pcall(function() return io.MouseClicked[0] end)
        return okc and clicked and true or false
    end
    local function polledMouseClick()
        local m = _G.GRND_MOUSE
        if type(m) ~= "table" then return false end
        local frame = tonumber(_G.GRND_UIFRAME) or 0
        if m._mpPollFrame == frame then return m._mpPollClick and true or false end
        m._mpPollFrame = frame
        m._mpPollClick = false
        local down
        if type(_G.isMouseButtonDown) == "function" then
            local ok, value = pcall(_G.isMouseButtonDown, 1)
            if ok then down = value and true or false end
        end
        if down == nil and type(_G.isKeyDown) == "function" then
            local ok, value = pcall(_G.isKeyDown, 0x01)
            if ok then down = value and true or false end
        end
        if down == nil then return false end
        local previous = m._mpPollDown and true or false
        m._mpPollDown = down
        m._mpPollClick = down and not previous
        return m._mpPollClick
    end
    local function ownMouseClick()
        if not ownMouseInside() then return false end
        -- и курсор должен быть над ОКНОМ панели: без этого «сырой» клик,
        -- который проглотило другое окно поверх панели, нажимал кнопку
        if im.IsWindowHovered then
            local okW, overWindow = pcall(im.IsWindowHovered)
            if okW and overWindow == false then return false end
        end
        if ioMouseClicked() then return true end
        if type(_G.grndClickAlive) == "function" and _G.grndClickAlive() then
            if _G.GRND_MOUSE and _G.GRND_MOUSE.clicked then return true end
        end
        -- дальше — только резервные пути (опроса нет готовности ввода)
        if not onClickReady() then return false end
        return polledMouseClick()
    end

    -- Наведение считаем один раз и отдаём его и заливке, и слою подсветки.
    local frame = tonumber(_G.GRND_UIFRAME) or 0
    local own = ownMouseInside() and mpWindowHovered(ctx.im) or false
    -- одиночный «провал» наведения гасим: глаз читает его как мигание
    local function settle(hov)
        if hov then
            MP_HOVER.id, MP_HOVER.frame = full, frame
            return true
        end
        if MP_HOVER.id == full and (frame - (MP_HOVER.frame or -99)) <= 1 then
            return true
        end
        return false
    end

    local fn = _G.grndUiButton
    if type(fn) == "function" then
        local args = opts
        if own and not opts.hover then
            args = {}
            for k, v in pairs(opts) do args[k] = v end
            args.hover = true
        end
        local ok, clicked, hov = pcall(fn, ctx, full, x, y, w, h, label, args)
        if ok then
            if not hov and own then hov = true end
            if settle(hov) then hoverLayer(ctx, x, y, w, h, opts) end
            if clicked then return true end
            if ownMouseClick() then
                _G.GRND_MOUSE.clicked = false
                return true
            end
            return false
        end
    end
    -- запасная кнопка, если основной хелпер недоступен
    im.SetCursorPos(ctx.pos(x, y))
    local clicked = im.InvisibleButton(full, im.ImVec2(w, h)) and true or false
    local hov = (im.IsItemHovered and im.IsItemHovered()) or false
    if not hov then hov = own end
    hov = settle(hov)
    if not clicked and ownMouseClick() then
        _G.GRND_MOUSE.clicked = false
        clicked = true
    end
    local ac0 = theme().accent
    local bg, bd
    -- v1.19.06: спокойные кнопки панели больше не «исчезают» — заливка и
    -- рамка видны и без наведения (hoverLayer лишь добавляет акцент).
    if opts.danger then
        bg = col32(255, 96, 96, 34)
        bd = col32(255, 96, 96, 84)
    elseif opts.selected then
        bg = col32(ac0[1], ac0[2], ac0[3], 38)
        bd = col32(ac0[1], ac0[2], ac0[3], 115)
    else
        bg = col32(255, 255, 255, 22)
        bd = col32(255, 255, 255, 40)
    end
    roundRect(ctx.dl, ctx.at(x, y), ctx.at(x + w, y + h), bg, 6)
    frameRect(ctx.dl, ctx.at(x + 0.5, y + 0.5), ctx.at(x + w - 0.5, y + h - 0.5), bd, 6, 1)
    local tw = ctx.tsize(label)
    local TH = theme()
    local lx = math.max(6, (w - tw) / 2)
    if opts.align == "left" then lx = 12 end
    local lc = opts.muted and { 216, 211, 234, 255 }
        or (opts.danger and { 255, 188, 188, 255 })
        or { 250, 248, 255, 255 }   -- v1.19.03: подписи кнопок ярче
    ctx.uiText(x + lx, y + (h - 14) / 2, label, ctx.c4(lc), 1.0)
    if hov then hoverLayer(ctx, x, y, w, h, opts) end
    return clicked
end

local function switchRow(ctx, id, x, y, on)
    local im = ctx.im
    im.SetCursorPos(ctx.pos(x, y))
    local clicked = im.InvisibleButton("##mpsw_" .. id, im.ImVec2(46, 24)) and true or false
    local hov = (im.IsItemHovered and im.IsItemHovered()) or false
    local paint = _G.grndUiSwitchPaint
    if type(paint) == "function" then
        pcall(paint, ctx, x, y, on, hov, "mp_" .. id, 0.016)
    else
        local ac = theme().accent
        roundRect(ctx.dl, ctx.at(x + 1, y + 1), ctx.at(x + 45, y + 23),
            on and col32(ac[1], ac[2], ac[3], 150) or col32(255, 255, 255, 34), 6)
        frameRect(ctx.dl, ctx.at(x + 1.5, y + 1.5), ctx.at(x + 44.5, y + 22.5),
            col32(255, 255, 255, on and 70 or 40), 6, 1)
        roundRect(ctx.dl, ctx.at(x + 5 + (on and 22 or 0), y + 5),
            ctx.at(x + 19 + (on and 22 or 0), y + 19),
            col32(255, 255, 255, on and 255 or 130), 3)
    end
    return clicked
end

local M_ROW  = 34   -- высота поля, кнопки, тумблера
local BIG_ROW = BIG_INPUT_H   -- крупные поля: объявления, триггер, имя заготовки
local MP_FIELD_MAX_W = 620     -- строки длиннее по горизонтали, но не до края карточки
local M_LBL  = 20   -- строка подписи над полем
local M_GAP  = 10   -- отступ между строками внутри раздела
local M_SEC  = 32   -- шапка раздела: линия + заголовок
local CARD_R = 7    -- скругление карточек

-- маленькая кнопка-иконка (корзина у строки)
local function iconButton(ctx, key, x, y, draw, onClick, rowHeight)
    local im = ctx.im
    local rh = tonumber(rowHeight) or M_ROW
    y = y + math.floor((rh - 24) / 2)     -- по центру строки
    im.SetCursorPos(ctx.pos(x, y))
    local clicked = im.InvisibleButton("##mp_" .. key, im.ImVec2(26, 24)) and true or false
    local hov = (im.IsItemHovered and im.IsItemHovered()) or false
    if hov then
        roundRect(ctx.dl, ctx.at(x, y), ctx.at(x + 26, y + 24), col32(255, 96, 96, 34), 6)
    end
    draw(ctx, x + 13, y + 12, col32(255, 120, 120, hov and 255 or 150))
    if clicked and onClick then onClick() end
    return clicked
end

-- разделы выдачи: название, подсказка и ключ в MP.give
local GIVE_CATS = {
    { key = "gun",   title = "Оружие",  hint = "31 200" },
    { key = "armor", title = "Броня",   hint = "100" },
    { key = "hp",    title = "Здоровье", hint = "100" },
    { key = "skin",  title = "Скин",    hint = "27" },
}

-- что забирать при телепорте
local TAKE_CATS = {
    { key = "gun",   title = "Оружие" },
    { key = "armor", title = "Броня" },
}

local GIVE_POPUP_HINT = {
    gun = "ID оружия и патроны, например: 31 200",
    armor = "количество брони, например: 100",
    hp = "количество HP, например: 100",
    skin = "ID скина, например: 27",
}

local GIVE_POPUP_TITLE = {
    gun = "ОРУЖИЕ",
    armor = "БРОНЯ",
    hp = "ЗДОРОВЬЕ",
    skin = "СКИН",
}

-- Ширина подписи в панели: текст рисуется кеглем 0.92, поэтому ширину из
-- tsize умножаем на тот же коэффициент (иначе шестерёнка «уезжает»).
local function mpTextW(ctx, s, scale)
    local w = 0
    if type(ctx.tsize) == "function" then
        local ok, v = pcall(ctx.tsize, tostring(s or ""))
        if ok and type(v) == "number" then w = v end
    end
    if w <= 0 then w = #tostring(s or "") * 7 end
    return w * (tonumber(scale) or 1)
end

-- Небольшая интерактивная шестерёнка. Она не меняет тумблер — только
-- открывает компактное окно ручного ввода строк конкретной выдачи.
local function gearButton(ctx, key, cx, cy, active)
    local im = ctx.im
    local x, y, size = cx - 15, cy - 15, 30
    im.SetCursorPos(ctx.pos(x, y))
    local clicked = im.InvisibleButton("##mp_gear_" .. key, im.ImVec2(size, size)) and true or false
    local hovered = (im.IsItemHovered and im.IsItemHovered()) and true or false
    local th = theme()
    local base = active and (th.accent or { 184, 135, 244 })
        or (th.textMuted or { 170, 164, 184 })
    if hovered then base = { 255, 222, 255, 255 } end
    roundRect(ctx.dl, ctx.at(x + 3, y + 3), ctx.at(x + size - 3, y + size - 3),
        col32(base[1], base[2], base[3], hovered and 48 or 26), 7)
    gearIcon(ctx, cx, cy, col32(base[1], base[2], base[3], hovered and 255 or (active and 250 or 225)))
    return clicked
end

local function drawGivePopup(ctx, cx, y, cw, key)
    local G = MP.give[key]
    if not G then return y end
    -- У каждой категории одна ручная настройка: оружие+патроны,
    -- броня, HP или ID скина. Старые дополнительные строки сворачиваем
    -- только один раз, чтобы не перезаписывать ввод на каждом кадре.
    if type(G.rows) ~= "table" or #G.rows == 0 then
        G.rows = { "" }
    elseif #G.rows > 1 then
        local one = ""
        for i = 1, math.min(#G.rows, MAX_ROWS) do
            local candidate = cleanText(G.rows[i])
            if candidate ~= "" then one = candidate break end
        end
        G.rows = { one }
        MP.touch()
    end

    local px, pw = cx + 8, cw - 16
    local innerX, innerW = px + 12, pw - 24
    local popupH = 58 + (M_ROW + 6) + M_ROW + 16
    local ac = theme().accent or { 164, 112, 224 }

    roundRect(ctx.dl, ctx.at(px, y), ctx.at(px + pw, y + popupH),
        col32(14, 15, 22, 245), 8)
    frameRect(ctx.dl, ctx.at(px + 0.5, y + 0.5), ctx.at(px + pw - 0.5, y + popupH - 0.5),
        col32(ac[1], ac[2], ac[3], 180), 8, 1)
    ctx.uiText(innerX, y + 10, "НАСТРОЙКА: " .. (GIVE_POPUP_TITLE[key] or key),
        ctx.c4(theme().textHi), 0.95)
    ctx.uiText(innerX, y + 31, GIVE_POPUP_HINT[key] or "Введите значение вручную",
        ctx.c4(theme().textMuted), 0.78)
    if button(ctx, "give_close_" .. key, px + pw - 92, y + 9, 80, 26, "Закрыть", {}) then
        MP.givePopup = nil
    end
    roundRect(ctx.dl, ctx.at(innerX, y + 51), ctx.at(innerX + innerW, y + 53),
        col32(255, 255, 255, 42), 1)

    textInput(ctx, "givepop:" .. key, "##mp_givepop_" .. key, 64, G.rows[1],
        innerX, y + 58, innerW, M_ROW, GIVE_POPUP_HINT[key],
        function(v) G.rows[1] = v end)
    return y + popupH
end

-- ---------------------------------------------------------------------
--  ВЁРСТКА ПАНЕЛИ
--
--  Правила, по которым панель не разъезжается:
--    • одна колонка, всё от одного левого края до одного правого;
--    • высота поля 26, шаг между строками 8, отступ раздела 14;
--    • раздел отделён линией, заголовок с акцентной полоской;
--    • подпись — над полем, тумблер — справа от подписи.
--  Координаты локальные (как их отдаёт меню); окно добавляется только
--  в ctx.at() — для списка отрисовки.
-- ---------------------------------------------------------------------

-- ---- раздел: линия, акцент, заголовок -------------------------------
local function section(ctx, x, y, w, title)
    y = y + 8
    -- v1.19.03: линия есть только у ОСНОВНЫХ блоков — внутри разделов её
    -- больше нет (в «ВЫДАТЬ» и «ЗАБРАТЬ» к каждой строке шла своя черта,
    -- из-за чего панель выглядела «расчерченной»).
    roundRect(ctx.dl, ctx.at(x, y), ctx.at(x + w, y + 2),
        col32(255, 255, 255, 58), 1)
    y = y + 10
    local ac = theme().accent or { 164, 112, 224 }
    roundRect(ctx.dl, ctx.at(x, y), ctx.at(x + 4, y + 14),
        col32(ac[1], ac[2], ac[3], 235), 2)
    ctx.uiText(x + 10, y - 1, title, ctx.c4(theme().textHi), 1.0)
    return y + 21
end

local function divider(ctx, x, y, w)
    roundRect(ctx.dl, ctx.at(x, y), ctx.at(x + w, y + 2),
        col32(255, 255, 255, 64), 1)
end

-- ---- подпись + тумблер справа, поле под ними -------------------------
local function labelAt(ctx, x, y, w, label, right)
    if right ~= nil then
        ctx.uiText(x, y + 2, label, ctx.c4(theme().textDim), 0.92)
        local rw = ctx.tsize(right)
        ctx.uiText(x + w - rw, y + 2, right, ctx.c4(theme().textMuted), 0.85)
    else
        ctx.uiText(x, y + 2, label, ctx.c4(theme().textDim), 0.92)
    end
    return y + M_LBL
end

-- ---- подпись + поле ---------------------------------------------------
local function fieldAt(ctx, x, y, w, label, key, id, cap, value, hint, onChange, fieldHeight)
    y = labelAt(ctx, x, y, w, label)
    local h = tonumber(fieldHeight) or M_ROW
    textInput(ctx, key, id, cap, value, x, y, w, h, hint, onChange)
    return y + h
end

-- содержимое карточки для «Выдачи в радиусе»: пока заглушка. Верхние
-- кнопки («Создать МП» / «Выдача в радиусе») при этом остаются на месте.
local function drawRadiusView(ctx, cx, y, cw)
    y = section(ctx, cx, y, cw, "ВЫДАЧА В РАДИУСЕ")
    local TH = theme()
    ctx.uiText(cx + 2, y + 6, "Раздел в разработке", ctx.c4(TH.textHi), 1.25)
    ctx.uiText(cx + 2, y + 40,
        "Выдача оружия и брони всем игрокам рядом появится позже.",
        ctx.c4(TH.textDim), 0.95)
    ctx.uiText(cx + 2, y + 62,
        "Пока рабочее окно — форма МП: вернуться можно кнопкой «Создать МП».",
        ctx.c4(TH.textDim), 0.95)
    y = y + 92
    if button(ctx, "back_mp", cx, y, 240, M_ROW, "Вернуться в панель МП", {}) then
        MP.view = "mp"
        MP.scroll = 0
        MP.flash = { text = "Панель МП", at = now(), kind = "info" }
    end
    return y + M_ROW
end

-- Открыть окно меню на нужной вкладке. Кнопки «Создать МП» и
-- «Выдача в радиусе» только переключают окно; само МП запускает
-- «Начать» внизу панели.
local function openTab(tabId)
    local menu = _G.GRND_MENU
    if type(menu) ~= "table" then return false end
    menu.open = true
    local tabs = _G.GRND_MENU_TABS
    if type(tabs) == "table" then
        for i = 1, #tabs do
            if type(tabs[i]) == "table" and tabs[i].id == tabId then
                menu.tab = i
                break
            end
        end
    end
    if type(_G.grndEnsureRender) == "function" then pcall(_G.grndEnsureRender, true) end
    return true
end

-- =====================================================================
--  ОТРИСОВКА
-- =====================================================================
function MP.draw(raw)
    -- любая ошибка отрисовки не должна ронять кадр меню: сообщаем
    -- внутри карточки и пишем подробности в лог отрисовки
    local okDraw, err = pcall(MP.drawInner, raw)
    if okDraw then
        MP.drawError = nil
        return
    end
    MP.drawError = tostring(err)
    local fn = _G.grndUiErrLog
    if type(fn) == "function" then pcall(fn, "панель МП", err) end
    -- один раз на текст ошибки — и в чат: лог-файл не всегда получается
    -- переслать, а строку из чата можно просто скопировать
    MP.errSaid = MP.errSaid or {}
    if not MP.errSaid[MP.drawError] then
        MP.errSaid[MP.drawError] = true
        pcall(say, "панель МП: ошибка — " .. tostring(err):sub(1, 140) .. " (подробности: /mp diag)", "error")
    end
    local im = _G.GRND_IM
    if im then
        local okPos, pos = pcall(im.GetWindowPos)
        if okPos and pos and pos.x then
            local x = (raw and raw.x or 0) + 16
            local y = (raw and raw.y or 0) + 14
            pcall(function()
                im.SetCursorPos(im.ImVec2(x, y))
                im.TextUnformatted("Ошибка панели МП: " .. tostring(err))
                im.SetCursorPos(im.ImVec2(x, y + 20))
                im.TextUnformatted("подробности: /mp diag (или resource/grnd/logs/grnd_err.log)")
            end)
        end
    end
end

function MP.drawInner(raw)
    local im = _G.GRND_IM
    if not im then return end
    local okPos, pos = pcall(im.GetWindowPos)
    if not okPos or not pos then return end
    local px, py = tonumber(pos.x) or 0, tonumber(pos.y) or 0
    local dl = im.GetWindowDrawList()
    if not dl then return end

    -- Защита от «побитого» конфига: если в файле окажется не таблица (ручная
    -- правка, обрыв записи), панель падала в середине отрисовки — часть
    -- содержимого исчезала, а сверху висело сообщение об ошибке.
    if type(MP.form) ~= "table" then MP.form = {} end
    if type(MP.form.messages) ~= "table" then MP.form.messages = { "" } end
    if type(MP.give) ~= "table" then MP.give = {} end
    if type(MP.take) ~= "table" then MP.take = {} end
    if type(MP.presets) ~= "table" then MP.presets = {} end
    if type(MP.fields) ~= "table" then MP.fields = {} end
    for i = 1, #GIVE_CATS do
        local G = MP.give[GIVE_CATS[i].key]
        if type(G) ~= "table" then G = {} MP.give[GIVE_CATS[i].key] = G end
        if type(G.rows) ~= "table" then G.rows = { "" } end
        G.on = G.on and true or false
    end
    for i = 1, #TAKE_CATS do
        MP.take[TAKE_CATS[i].key] = MP.take[TAKE_CATS[i].key] and true or false
    end

    -- причина сбоя ТЕКУЩЕГО кадра: собираем в одном месте, чтобы удачный
    -- блок не затирал ошибку соседнего
    local frameErr = nil

    local TH = theme()
    -- rawget, а не _G.x: значение может быть и не функцией (заглушка)
    local fnText = rawget(_G, "grndUiText")
    if type(fnText) ~= "function" then fnText = nil end
    local baseText = fnText or uiTextFallback(im)
    local ctx = {
        im = im, dl = dl, dt = 0.016, x = px, y = py,
        -- ВНИМАНИЕ, две разные системы координат:
        --   at()  — список отрисовки (dl.*): ОКОННЫЕ координаты;
        --   pos() — im.SetCursorPos: ЛОКАЛЬНЫЕ (как отдаёт меню).
        -- Перепутать — блок уедет на ширину окна вбок.
        at = function(x, y) return im.ImVec2(px + x, py + y) end,
        pos = function(x, y) return im.ImVec2(x, y) end,
        col32 = col32, rgba = rgba,
        c4 = function(t)
            if type(t) == "table" then
                return rgba(t[1] or 200, t[2] or 200, t[3] or 200, t[4] or 255)
            end
            if type(t) == "number" then return col32(t) end
            return rgba(160, 156, 175, 255)
        end,
        roundRect = roundRect, gradRect = gradRect,
        uiText = function(x, y, s, col, sc)
            local ok, w, h = pcall(baseText, x, y, s, col, sc)
            if ok then return w, h end
            return 0, 14
        end,
        tsize = function(s) return tsizeOf(im, s) end,
    }

    -- угол карточки раздела и полезная ширина — в локальных координатах
    -- Поля ввода должны быть шире самой внутренней сетки: уменьшаем
    -- боковой отступ слева, а справа оставляем место под скролл.
    local cx = (raw and raw.x or 0) + 8
    local cy = (raw and raw.y or 0) + 14
    local cw = math.max(280, (raw and raw.w or 640) + 20)
    local ch = math.max(160, (raw and raw.h or 480))

    -- диагностика (/mp diag): где панель, сколько кадров её рисовали и как
    -- давно. Координаты — экранные, в той же системе, что и мышь.
    MP.drawFrames = (MP.drawFrames or 0) + 1
    MP.diag = { x = px + cx, y = py + cy, cw = cw, ch = ch, at = now() }

    local maxScroll = math.max(0, (MP.totalH or 0) - ch)
    MP.scroll = math.max(0, math.min(maxScroll, MP.scroll or 0))

    -- колесо мыши листает панель, когда курсор над ней
    local mx, my, wheel
    if im.GetIO then
        local okIo, io = pcall(im.GetIO)
        if okIo and io then
            if io.MousePos then mx, my = tonumber(io.MousePos.x), tonumber(io.MousePos.y) end
            wheel = tonumber(io.MouseWheel) or 0
        end
    end
    if not mx and _G.GRND_MOUSE then
        mx, my = tonumber(_G.GRND_MOUSE.x), tonumber(_G.GRND_MOUSE.y)
    end
    if wheel and wheel ~= 0 and mx then
        local inside = mx >= px + cx and mx <= px + cx + cw
            and my >= py + cy and my <= py + cy + ch
        if inside and (now() - (MP.wheelAt or 0)) > 0.05 then
            MP.wheelAt = now()
            MP.scroll = math.max(0, math.min(maxScroll, MP.scroll - wheel * 42))
        end
    end

    local clipPushed = false
    if dl.PushClipRect then
        clipPushed = pcall(dl.PushClipRect, dl, ctx.at(cx, cy), ctx.at(cx + cw, cy + ch), true)
    end

    local y = cy - (MP.scroll or 0)
    local y0 = y

    -- =================================================================
    --  СОЗДАТЬ МП + ВЫДАЧА В РАДИУСЕ
    -- =================================================================
    local function drawTopButtons(y)
        -- Две верхние кнопки — равные по ширине: правая не должна
        -- выглядеть узкой относительно «Создать МП».
        local mw = math.floor((cw - 8) / 2)
        local rw = cw - mw - 8
        local radiusView = MP.view == "radius"
        -- Подсветка всегда показывает текущий экран, а не состояние МП.
        if button(ctx, "create", cx, y, mw, M_ROW, "Создать МП",
            { selected = not radiusView }) then
            MP.view = "mp"
            MP.scroll = 0
            if openTab("mppanel") then
                flash("Панель МП открыта", "info")
            end
        end
        if button(ctx, "giverad", cx + mw + 8, y, rw, M_ROW,
            "Выдача в радиусе", { selected = radiusView }) then
            MP.view = "radius"
            MP.givePopup = nil
            MP.scroll = 0
            flash("Выдача в радиусе (в разработке)", "info")
        end
        return y + M_ROW + 16
    end
    -- верхние кнопки — тоже в песочнице: их сбой не должен лишать панель
    -- содержимого и кнопки «Начать»
    local okT, resT = pcall(drawTopButtons, y)
    if okT and tonumber(resT) then
        y = tonumber(resT)
    else
        frameErr = frameErr or tostring(resT)
        y = y + M_ROW + 16
    end

    if MP.view == "radius" then
        y = drawRadiusView(ctx, cx, y, cw)
        MP.totalH = y - y0 + 12
        if clipPushed and dl.PopClipRect then pcall(dl.PopClipRect, dl) end
        return
    end

    -- -----------------------------------------------------------------
    --  Содержимое панели рисуется в отдельной «песочнице» (pcall).
    --  Раньше сбой в середине формы уносил с собой ВСЁ, что ниже, — а в
    --  самом низу рисуется кнопка «Начать». Отсюда и жалоба «кнопка
    --  пропадает, потом появляется». Теперь причина ошибки пишется
    --  строкой на месте содержимого, а кнопка «Начать» рисуется ПОСЛЕ
    --  песочницы и видна всегда.
    -- -----------------------------------------------------------------
    local contentStart = y
    local function drawContent(y)
        -- =================================================================
        --  ОБЪЯВЛЕНИЯ
        -- =================================================================
        y = section(ctx, cx, y, cw, "ОБЪЯВЛЕНИЯ В /MSG")
        local msgDel                                   -- индекс удаляемой строки
        local msgW = math.min(cw - 30, MP_FIELD_MAX_W)
        for i = 1, #MP.form.messages do
            textInput(ctx, "msg:" .. i, "##mp_msg_" .. i, 140, MP.form.messages[i] or "",
                cx, y, msgW, BIG_ROW, "текст объявления",
                function(v) MP.form.messages[i] = v end)
            iconButton(ctx, "msgdel_" .. i, cx + msgW + 4, y, trashIcon,
                function() msgDel = i end, BIG_ROW)
            y = y + BIG_ROW + 6
        end
        if button(ctx, "msgadd", cx, y, msgW, M_ROW, "+ Добавить", {}) then
            if #MP.form.messages < MAX_MSG then
                table.insert(MP.form.messages, "")
                MP.touch()
            end
        end
        -- список правим только после того, как он весь отрисован
        if msgDel and MP.form.messages[msgDel] ~= nil then
            table.remove(MP.form.messages, msgDel)
            dropFields("msg:")
            MP.touch()
        end
        y = y + M_ROW + 10

        -- =================================================================
        --  ТРИГГЕР И УСЛОВИЯ
        -- =================================================================
        y = section(ctx, cx, y, cw, "ТРИГГЕР И УСЛОВИЯ")
        local formW = math.min(cw, MP_FIELD_MAX_W)
        textInput(ctx, "trigger", "##mp_trigger", 40, MP.form.trigger,
            cx, y, formW, BIG_ROW, "триггер в репорте, например: дигла",
            function(v) MP.form.trigger = v end)
        y = y + BIG_ROW + M_GAP + 4

        -- =================================================================
        --  ВЫДАТЬ ИГРОКУ ПОСЛЕ ТЕЛЕПОРТА
        -- =================================================================
        y = section(ctx, cx, y, cw, "ВЫДАТЬ ИГРОКУ ПОСЛЕ ТЕЛЕПОРТА")
        for i = 1, #GIVE_CATS do
            local cat = GIVE_CATS[i]
            local G = MP.give[cat.key]
            local headerY = y
            -- Тумблер слева, название рядом, шестерёнка — сразу за названием
            -- (v1.19.05: раньше она стояла у правого края карточки, далеко от
            -- той выдачи, к которой относится).
            if switchRow(ctx, "sw_" .. cat.key, cx + 4, headerY + 5, G.on) then
                G.on = not G.on
                if G.on and #G.rows == 0 then G.rows[1] = "" end
                MP.touch()
            end
            ctx.uiText(cx + 62, headerY + 8, string.upper(cat.title),
                ctx.c4(G.on and theme().textHi or theme().textDim), 0.92)
            if gearButton(ctx, cat.key,
                cx + 62 + mpTextW(ctx, string.upper(cat.title), 0.92) + 18,
                headerY + 17, G.on or MP.givePopup == cat.key) then
                MP.givePopup = (MP.givePopup == cat.key) and nil or cat.key
            end
            y = headerY + M_ROW

            -- Строки выдачи редактируются только в компактном окне шестерёнки,
            -- поэтому основная форма остаётся чистой и не перегруженной.
            if MP.givePopup == cat.key then
                y = drawGivePopup(ctx, cx, y, cw, cat.key)
            end

            if i < #GIVE_CATS then
                y = y + 12      -- v1.19.03: без разделительной черты внутри блока
            end
        end
        y = y + 4

        -- =================================================================
        --  ЗАБРАТЬ
        -- =================================================================
        y = section(ctx, cx, y, cw, "ЗАБРАТЬ")
        for i, t in ipairs(TAKE_CATS) do
            local rowY = y
            if switchRow(ctx, "take_" .. t.key, cx + 4, rowY + 5, MP.take[t.key]) then
                MP.take[t.key] = not MP.take[t.key]
                MP.touch()
            end
            ctx.uiText(cx + 62, rowY + 8, t.title,
                ctx.c4(MP.take[t.key] and TH.textHi or TH.textDim), 0.95)
            y = rowY + M_ROW
            if i < #TAKE_CATS then
                y = y + 11      -- v1.19.03: без разделительной черты внутри блока
            end
        end
        y = y + 6

        -- =================================================================
        --  ЗАГОТОВКИ
        -- =================================================================
        y = section(ctx, cx, y, cw, "ЗАГОТОВКИ")
        y = fieldAt(ctx, cx, y, formW, "НАЗВАНИЕ", "presetName", "##mp_preset_name",
            48, MP.presetName, "например: дигла | ночь",
            function(v) MP.presetName = v end, BIG_ROW)
        y = y + 4
        if button(ctx, "psave", cx, y, cw, M_ROW, "Сохранить заготовку", {}) then
            local ok, msg = MP.savePreset(MP.presetName)
            MP.flash = { text = msg, at = now(), kind = ok and "ok" or "err" }
        end
        y = y + M_ROW + 8
        if #(MP.presets or {}) == 0 then
            ctx.uiText(cx + 2, y + 4, "заготовок пока нет", ctx.c4(TH.textMuted), 0.9)
            y = y + 22
        else
            local pw = math.floor((cw - 6) / 2)
            for i = 1, #(MP.presets or {}) do
                local p = MP.presets[i]
                local col = (i - 1) % 2
                local rowi = math.floor((i - 1) / 2)
                local x = cx + col * (pw + 6)
                local yy = y + rowi * (M_ROW + 6)
                if button(ctx, "pload_" .. i, x, yy, pw - M_ROW - 4, M_ROW,
                    string.format("%d.  %s", i, tostring(p.name or "")),
                    { align = "left" }) then
                    local ok, msg = MP.usePreset(p.name)
                    MP.flash = { text = msg, at = now(), kind = ok and "ok" or "err" }
                end
                iconButton(ctx, "pdel_" .. i, x + pw - M_ROW, yy, trashIcon,
                    function()
                        local ok, msg = MP.deletePreset(p.name)
                        flash(msg or "Заготовка не найдена", ok and "ok" or "error")
                    end)
            end
            y = y + math.ceil(#(MP.presets or {}) / 2) * (M_ROW + 6) + 4
        end

        return y
    end
    local okC, resC = pcall(drawContent, y)
    if okC and tonumber(resC) then
        MP.contentH = tonumber(resC) - contentStart
        y = tonumber(resC)
    else
        -- содержимое не нарисовалось: сообщаем причину и оставляем столько
        -- места, сколько оно занимало в последнем удачном кадре
        frameErr = frameErr or tostring(resC)
        local h = tonumber(MP.contentH) or 160
        pcall(ctx.uiText, cx + 2, contentStart + 6,
            "ошибка в содержимом панели: " .. tostring(MP.blockError):sub(1, 80),
            ctx.c4({ 255, 120, 120, 255 }), 0.85)
        y = contentStart + math.max(80, h)
    end

    y = y + 6

    -- =================================================================
    --  НАЧАТЬ / ОСТАНОВИТЬ
    -- =================================================================
    y = y + 4
    -- Тоже в песочнице: сбой при запуске/остановке МП (например, внутри
    -- обработчика кнопки) не должен оставлять панель без этой кнопки.
    local function drawStartStop(yy)
        if MP.active then
            if button(ctx, "stop", cx, yy, cw, M_ROW + 4, "Остановить", { danger = true }) then
                MP.stop("кнопкой в панели")
            end
        else
            if button(ctx, "start_mp", cx, yy, cw, M_ROW + 4, "Начать", { selected = true }) then
                local started = MP.start()
                if not started then
                    -- Ошибка запуска раньше оставалась только во внутреннем
                    -- flash и выглядела как «кнопка ничего не сделала».
                    local f = MP.flash
                    say("запуск не выполнен: " .. tostring(f and f.text or "проверьте форму"), "error")
                end
            end
        end
        return yy
    end
    local okSS, resSS = pcall(drawStartStop, y)
    if okSS and tonumber(resSS) then y = tonumber(resSS)
    else frameErr = frameErr or tostring(resSS) end

    -- Итог кадра: если какой-то блок не нарисовался — сохраняем причину
    -- для диагностики (/mp diag). Кнопка «Начать» при этом всё равно
    -- нарисована: она идёт после «песочницы» содержимого.
    if frameErr then
        MP.blockError = frameErr
        MP.blockErrN = (MP.blockErrN or 0) + 1
    else
        MP.blockError = nil
    end

    MP.totalH = y - y0 + M_ROW + 12

    -- Выходим из клипа до рисования полосы: она вынесена чуть правее
    -- содержимого и не должна обрезаться правой границей карточки.
    if clipPushed and dl.PopClipRect then pcall(dl.PopClipRect, dl) end

    -- полоса прокрутки
    local maxS = math.max(0, (MP.totalH or 0) - ch)
    if maxS > 1 then
        local frac = math.min(1, ch / math.max(1, MP.totalH))
        local barH = math.max(30, ch * frac)
        local barY = cy + (ch - barH) * math.min(1, math.max(0, (MP.scroll or 0) / maxS))
        local sx = cx + cw + 4
        roundRect(ctx.dl, ctx.at(sx, cy), ctx.at(sx + 4, cy + ch),
            col32(255, 255, 255, 14), 2)
        roundRect(ctx.dl, ctx.at(sx, barY), ctx.at(sx + 4, barY + barH),
            col32(255, 255, 255, 72), 2)
    end
end

-- вкладка «Панель МП» в меню GRND
local tabBound = false
local function bindTab()
    if tabBound then return true end
    local tabs = _G.GRND_MENU_TABS
    if type(tabs) ~= "table" then return false end
    for i = 1, #tabs do
        if type(tabs[i]) == "table" and tabs[i].id == "mppanel" then
            -- pcall: у вкладки не должно быть ЛЮБОЙ возможности показать
            -- «Ошибка отрисовки раздела» ВМЕСТО панели. MP.draw сам ловит
            -- свои ошибки и рисует строку с причиной прямо в карточке.
            tabs[i].draw = function(ctx) pcall(MP.draw, ctx) end
            tabBound = true
            return true
        end
    end
    return false
end

-- ---------------------------------------------------------------------
--  10. СОСТОЯНИЕ ПЛАНШЕТА И ЖУРНАЛА
-- ---------------------------------------------------------------------
local hookOkAt = 0
local chainAt = 0

function MP.tick()
    if not MP.loaded then pcall(MP.load) end
    if not tabBound then pcall(bindTab) end

    -- Не продолжаем сценарий на экране входа/при потере спавна.
    if MP.active and type(grndUiBlocked) == "function" and grndUiBlocked() then
        MP.stop("МП остановлено: открыт экран авторизации")
        return
    end

    -- Основная цепочка sampev.onServerMessage помечает chainReady при
    -- инициализации. Запасной хук нужен только если её действительно нет.
    if not MP.chainReady and not MP.chainSeen and (now() - (chainAt or 0)) > 10 then
        chainAt = now()
        local okCall, hooked = pcall(installHook)
        MP.hookOk = okCall and hooked == true
    end

    pcall(MP.pump)

    local t = now()
    if t - (MP.coolAt or 0) > 15 then
        MP.coolAt = t
        for id, untilAt in pairs(MP.cool) do
            if t > untilAt + 30 then MP.cool[id] = nil end
        end
    end

    if MP.dirtyAt and (t - MP.dirtyAt) > 1.2 then
        MP.dirtyAt = nil
        pcall(MP.save)
    end
end

function MP.reset()
    local was = MP.active
    MP.active = false
    MP.watch = false
    MP.jobs, MP.cur, MP.cool, MP.lock = {}, nil, {}, {}
    MP.announce = nil
    MP.givePopup = nil
    MP.runtimeForm = nil
    MP.log = {}
    MP.players, MP.sent, MP.done = 0, 0, 0
    MP.lastCmd = ""
    MP.nextAt = 0
    MP.lastMessageText, MP.lastMessageAt = nil, -math.huge
    MP.stat = { parsed = 0, matched = 0, skipped = 0, dropped = 0 }
    MP.preview = nil
    if was then
        flash("Состояние МП сброшено", "warn")
        say("состояние сброшено", "warn")
    end
end

-- классический цикл MoonLoader (если хочется крутить модуль самому)

-- =====================================================================
--  ПАНЕЛЬ МП: вкладка меню, команда /mp, старт конфига
-- =====================================================================
do
    local bound = false
    for i = 1, #MENU_TABS do
        if type(MENU_TABS[i]) == "table" and MENU_TABS[i].id == "mppanel" then
            MENU_TABS[i].draw = function(ctx) pcall(MP.draw, ctx) end
            bound = true
            break
        end
    end
    if not bound then
        MENU_TABS[#MENU_TABS + 1] = { id = "mppanel", name = "Панель МП" }
        MENU_TABS[#MENU_TABS].draw = function(ctx) pcall(MP.draw, ctx) end
    end
end

-- ---------------------------------------------------------------------
--  /mp diag — диагностика панели БЕЗ файлов.
--  Лог resource/grnd/logs/grnd_err.log не всегда получается прислать,
--  поэтому всё нужное печатается прямо в чат короткими строками: версия,
--  ошибка отрисовки панели, возможности сборки ImGui и координаты мыши
--  (ImGui против WM — по ним видно, почему кнопки ведут себя странно).
-- ---------------------------------------------------------------------
local function mpDiag()
    local im = _G.GRND_IM
    local function yn(v) return v and "да" or "нет" end
    -- «нет» — возможности в сборке нет, «ошибка» — есть, но вызов падает
    local function apiState(has, fn)
        if not has then return "нет" end
        local ok, res = pcall(fn)
        if not ok or res == false then return "ошибка" end
        if res == nil then return "нет" end
        return "да"
    end
    -- Каждая строка идёт и в чат, и в файл: из чата текст не скопировать,
    -- поэтому тот же отчёт кладётся в logs/grnd_diag.log — его можно
    -- прислать файлом, как grnd_err.log.
    local L = {}
    local function emit(text, kind)
        L[#L + 1] = tostring(text)
        pcall(say, text, kind)
    end
    emit("=== Панель МП: диагностика ===", "info")
    emit("версия " .. tostring(GRND_SCRIPT_VERSION or _G.GRND_SCRIPT_VERSION or "?")
        .. " · кадров ImGui: " .. tostring(_G.GRND_UIFRAME or 0)
        .. " · кадров панели: " .. tostring(MP.drawFrames or 0), "info")
    if MP.diag and MP.diag.at then
        say(("панель: x=%s y=%s ш=%s в=%s · кадр %.1f с назад")
            :format(tostring(math.floor(MP.diag.x or 0)), tostring(math.floor(MP.diag.y or 0)),
                tostring(math.floor(MP.diag.cw or 0)), tostring(math.floor(MP.diag.ch or 0)),
                math.max(0, now() - (MP.diag.at or 0))), "info")
    else
        say("панель ещё ни разу не рисовалась (вкладка не открывалась?)", "warn")
    end
    if MP.drawError then
        say("ОШИБКА ОТРИСОВКИ: " .. tostring(MP.drawError):sub(1, 200), "error")
    else
        say("ошибок отрисовки панели нет", "ok")
    end
    if im then
        local mx, my = nil, nil
        if type(im.GetIO) == "function" then
            local okIO, io = pcall(im.GetIO)
            if okIO and io and io.MousePos then
                mx, my = tonumber(io.MousePos.x), tonumber(io.MousePos.y)
            end
        end
        say("мышь ImGui: " .. (mx and (tostring(math.floor(mx)) .. "," .. tostring(math.floor(my))) or "нет")
            .. " · мышь WM: " .. (function()
                local m = _G.GRND_MOUSE
                if type(m) ~= "table" or not tonumber(m.x) then return "нет" end
                return tostring(math.floor(tonumber(m.x))) .. "," .. tostring(math.floor(tonumber(m.y)))
            end)(), "info")
        -- проверяем push/pop цвета парой: заодно видно, что стек снимается
        local pushOk
        if im.PushStyleColor and im.ImVec4 and im.Col and im.Col.Text then
            pushOk = mpPushCol(im, im.Col.Text, 255, 255, 255, 255) and true or false
            if pushOk then mpPopCols(im, 1) end
        end
        say("ImVec2=" .. apiState(im.ImVec2 ~= nil, function() return pcall(im.ImVec2, 0, 0) end)
            .. " ImVec4=" .. apiState(im.ImVec4 ~= nil, function() return pcall(im.ImVec4, 0, 0, 0, 1) end)
            .. " Push/PopStyleColor=" .. (pushOk == nil and "нет" or (pushOk and "да" or "ошибка"))
            .. " IsWindowHovered=" .. yn(im.IsWindowHovered ~= nil)
            .. " InputTextWithHint=" .. yn(im.InputTextWithHint ~= nil)
            .. " InputTextMultiline=" .. yn(im.InputTextMultiline ~= nil), "info")
    else
        say("ImGui недоступен (_G.GRND_IM = nil)", "error")
    end
    -- хвост журнала ошибок отрисовки (первые строки файла: where/error)
    local n = 0
    if type(grndUiErrLogPath) == "function" then
        local okF, f = pcall(io.open, grndUiErrLogPath(), "r")
        if okF and f then
            for _ = 1, 4 do
                local line = f:read("*l")
                if not line then break end
                if line ~= "" then
                    n = n + 1
                    say("лог: " .. tostring(line):sub(1, 180), "warn")
                end
            end
            pcall(f.close, f)
        end
    end
    if n == 0 then emit("журнал ошибок пуст", "ok") end
    if MP.blockError then
        emit("содержимое панели падало (" .. tostring(MP.blockErrN or 0) .. " раз): "
            .. tostring(MP.blockError):sub(1, 160), "error")
    end
    -- файл: тот же ресурсный каталог, что и у grnd_err.log
    local path
    if type(grndStoragePath) == "function" then
        path = grndStoragePath("logs", "grnd_diag.log")
    end
    if path then
        local ok, f = pcall(io.open, path, "w")
        if ok and f then
            pcall(f.write, f, "\239\187\191")          -- BOM: читается как UTF-8
            pcall(f.write, f, table.concat(L, "\r\n") .. "\r\n")
            pcall(f.close, f)
            emit("отчёт записан: " .. tostring(path), "ok")
        else
            emit("отчёт НЕ записался: " .. tostring(path), "warn")
        end
    end
    emit("пришлите эти строки (или файл grnd_diag.log) — по ним видно причину", "info")
end

-- Команда /mp: состояние, старт/стоп, заготовки, список команд.
-- Тестовых команд здесь нет: проверка идёт настоящим репортом
-- "Nik_Name[ID]: текст [К-во репорта: N]".
if type(sampRegisterChatCommand) == "function" then
    pcall(sampRegisterChatCommand, "mp", function(arg)
        local raw = tostring(arg or ""):gsub("^%s+", ""):gsub("%s+$", "")
        local a, rest = raw:match("^(%S+)%s*(.*)$")
        a = tostring(a or ""):lower()
        if a == "start" then
            local okStart = MP.start()
            if not okStart then say("запуск отменён — проверьте сообщение в панели", "warn") end
        elseif a == "stop" then
            if not MP.stop("Остановлено командой /mp stop") then say("МП уже остановлено", "info") end
        elseif a == "reset" then
            local wasActive = MP.active
            MP.reset()
            if not wasActive then say("состояние сброшено", "info") end
        elseif a == "show" then
            local good, msg, lines = MP.dryRun()
            say(msg, good and "ok" or "warn")
            if good and lines then
                for _, c in ipairs(lines) do say("  " .. c, "info") end
            end
        elseif a == "hook" then
            local okCall, hooked = pcall(installHook)
            local okHook = okCall and hooked == true
            MP.hookOk = okHook
            say("перехват чата: " .. (okHook and "установлен" or "НЕ установлен"),
                okHook and "ok" or "error")
        elseif a == "diag" or a == "лог" or a == "log" then
            pcall(mpDiag)
        elseif a == "save" then
            local good, msg = MP.savePreset(rest)
            say(msg, good and "ok" or "warn")
        elseif a == "load" then
            local good, msg = MP.usePreset(rest)
            say(msg, good and "ok" or "warn")
        elseif a == "del" then
            local good = MP.deletePreset(rest)
            say(good and "Заготовка удалена" or "Заготовка не найдена",
                good and "ok" or "warn")
        else
            say((MP.active and "активно" or "выключено")
                .. " · в очереди: " .. #MP.jobs
                .. " · команд: " .. tostring(MP.sent)
                .. " · заготовок: " .. #MP.presets, "info")
        end
        return true
    end)
end

pcall(MP.load)
return MP
-- <<< ПАНЕЛЬ МП: КОНЕЦ БЛОКА
end)()

-- наружу: grndMainBody зовёт MP.tick из своего цикла,
-- перехват репорта — MP.onServerMessage(text) в хуке чата

-- =====================================================================
--  МОДУЛЬ «БЫСТРЫЕ ОТВЕТЫ», ШАБЛОНЫ НАКАЗАНИЙ И АВТОПИЛОТ (v1.19.36)
-- =====================================================================
--  Что делает модуль:
--    * хранит набор шаблонов ответа (название + текст) в config.json
--      (секция reportTemplates, кодировка — UTF-8);
--    * кнопка «Быстрые ответы» в окне репорта открывает окно со списком:
--      клик по шаблону отвечает игроку боевой /ans ID текст и закрывает окно
--      (режим «в поле ответа» — вставляет текст в поле и окно не закрывает);
--    * редактор шаблонов — в меню: «Репорт» → вкладка «Ответы на репорт»;
--    * список шаблонов НЕ предзаполняется: пользователь создаёт свои сам
--      (демо-набор прошлых сборок один раз вычищается при загрузке).
--
--  ШРИФТ. В сборке шрифт может не содержать часть символов (▲ ▼ ↵ ＋ →) —
--  на экране они превращались в «?» или не рисовались вовсе. Поэтому
--  стрелки и «плюс» рисуются фигурами (AddTriangleFilled/AddLine), а в
--  подписях используются только те знаки, что уже есть в интерфейсе
--  скрипта: «…» «—» «·» «×» ««»».
--
--  КОДИРОВКИ. Файл и ImGui — UTF-8; в чат SA-MP текст уходит через
--  grndChatSend → grndAnsiText (UTF-8 → CP1251), поэтому кириллица не
--  превращается в «закорючки». Старые CP1251-значения при чтении чинятся
--  grndUtf8Text/grndToUtf.
--
--  ЛИМИТ ЛОКАЛЬНЫХ ПЕРЕМЕННЫХ. Скрипт — один Lua-чанк, а активных
--  локальных переменных в функции у Lua не больше 200: модуль обёрнут в
--  (function() … end)() и НИ ОДНОЙ локальной переменной на верхнем уровне
--  не создаёт (как панель МП). Наружу — только _G.GRND_QR,
--  _G.grndQrPickerDraw, _G.grndQrSettingsDraw, _G.grndQrPunPickerDraw,
--  _G.grndQrPunishDraw и _G.grndQrOnEsc.
-- =====================================================================

_G.GRND_QR = (function()
local QR = {
    loaded = false,        -- конфиг прочитан
    items = nil,           -- массив шаблонов { id, name, text }
    nextId = 1,            -- генератор id
    mode = "ans",          -- ans (боевой /ans игроку) | input (в поле ответа)
    selId = nil,           -- выбранный шаблон в редакторе
    isNew = false,         -- редактор создаёт новый шаблон
    delArm = nil,          -- id, для которого удаление ждёт подтверждения
    note = nil,            -- текст статуса редактора
    noteKind = nil,        -- ok | warn
    noteAt = 0,
    filter = "",           -- поиск в редакторе
    formKey = nil,         -- что сейчас в форме: none | new | id:N
    pickOpen = false,      -- полоса быстрых ответов открыта (v1.19.03)
    pickScroll = 0,
    pickFocus = false,     -- запросить фокус окну при открытии
    listScroll = 0,        -- прокрутка списка в настройках
    wheelAt = 0,           -- отсечка прокрутки колесом
    bufs = {},             -- буферы ввода: key -> { buf, cap, im, pending }
    drawErr = nil,         -- последняя ошибка отрисовки (диагностика)
    left = 0,              -- сколько раз рисовали окно выбора
    chats = 0,             -- сколько раз уходило в чат
    -- v1.19.16: шаблоны наказаний (вкладка «Репорт» → «Наказания»)
    pun = {
        loaded = false,    -- файл наказаний прочитан
        items = nil,       -- { id, name, text, cmd, time, reason }
        nextId = 1,
        selId = nil, isNew = false, delArm = nil,
        filter = "",       -- поиск в списке наказаний
        formKey = nil,     -- что открыто в редакторе: none | new | id:N
        cmdSync = nil,     -- какому formKey соответствует буфер команды
        listScroll = 0,
        comboOpen = false, -- открыт выпадающий список команд
        comboScroll = 0,
        pickOpen = false,  -- полоса наказаний в окне репорта
        pickScroll = 0,
        pickFocus = false,
        left = 0,          -- сколько раз рисовали полосу
    },
    -- v1.19.21: автопилот ответов на репорт (вкладка «Репорт» → «Автопилот»).
    -- v1.19.22: во вкладках — в каждой свой триггер, ответ и команда.
    auto = {
        loaded = false,    -- конфиг автопилота прочитан
        on = false,        -- включён ли
        tabs = nil,        -- вкладки: { {trigger=, answer=, command=}, … }
        sel = 1,           -- выбранная вкладка
        listOpen = false,  -- открыт выпадающий список команд
        paused = nil,      -- причина паузы: «слежка» | «мероприятие» | nil
        fired = 0,         -- сколько раз сработал
        lastAt = 0,        -- время последнего срабатывания
        lastCheck = nil,   -- чем закончилась последняя проверка
        dirtyAt = nil,     -- есть несохранённые правки (пишем с задержкой)
        err = nil,         -- последняя ошибка (диагностика)
    },
}

local MAX_TEXT = 512       -- символов в тексте шаблона
local MAX_NAME = 48        -- символов в названии
local MAX_CHAT = 118       -- символов на одну строку чата: у SA-MP лимит 128
local MAX_BUF  = 244       -- байт для поля ответа окна репорта (буфер char[256])
local MAX_PTIME = 8        -- символов в поле «Время» шаблона наказания
local MAX_PREASON = 96     -- символов в «Причине» шаблона наказания

-- КООРДИНАТЫ. В этом скрипте есть два пространства:
--   * ctx.at(x, y) — ЭКРАННЫЕ координаты (pos окна + локальные) — только
--     для вызовов draw-list (dl.AddRectFilled и т.п.);
--   * локальные координаты окна — для ВИДЖЕТОВ (im.SetCursorPos(ImVec2…)),
--     именно так делает сам скрипт: roundRect(dl, at(bx, by), …) и рядом
--     im.SetCursorPos(im.ImVec2(bx, by)).
-- Мы получаем x/y/w/h уже в локальном пространстве (card-local или дельта
-- окна быстрых ответов), поэтому виджеты ставим по ImVec2, а at() берегём
-- для рисования.

local function theme() return (GRND_UIKIT and GRND_UIKIT.TH) or {} end

-- ---------- утилиты текста ----------

local function utf(s)
    s = tostring(s or "")
    if type(grndUtf8Text) == "function" then
        local ok, v = pcall(grndUtf8Text, s)
        if ok and type(v) == "string" and v ~= "" then return v end
    end
    return s
end

local function lower(s)
    s = tostring(s or "")
    if type(grndLowerUtf) == "function" then
        local ok, v = pcall(grndLowerUtf, s)
        if ok and type(v) == "string" then return v end
    end
    return s:lower()
end

local function trim(s)
    return (tostring(s or ""):gsub("^%s+", ""):gsub("%s+$", ""))
end

-- Всё в одну строку (для чата, поиска и подписей в списке).
local function oneLine(s)
    s = tostring(s or ""):gsub("\r\n", "\n"):gsub("\r", "\n")
    s = s:gsub("[ \t]*\n[ \t]*", " ")
    return trim(s:gsub("%s+", " "))
end

-- Чистка многострочного текста: без \r и нулевых байтов, без хвостов пробелов.
local function cleanText(s)
    s = tostring(s or ""):gsub("\r\n", "\n"):gsub("\r", "\n"):gsub("%z", "")
    local out = {}
    for line in (s .. "\n"):gmatch("([^\n]*)\n") do out[#out + 1] = (line:gsub("[ \t]+$", "")) end
    while #out > 0 and out[#out] == "" do out[#out] = nil end
    while #out > 0 and out[1] == "" do table.remove(out, 1) end
    return table.concat(out, "\n")
end

-- Сколько СИМВОЛОВ (не байт) в строке.
local function utf8Len(s)
    s = tostring(s or "")
    if type(grndUtf8Len) == "function" then
        local ok, n = pcall(grndUtf8Len, s)
        if ok and type(n) == "number" then return n end
    end
    local n = 0
    for _ in s:gmatch("[\0-\127\194-\244][\128-\191]*") do n = n + 1 end
    return n
end

-- Обрезка до целого числа БАЙТ (хвостовой многобайтный символ не рвём).
local function byteCut(s, maxBytes)
    s = tostring(s or "")
    if #s <= maxBytes then return s end
    local i, last = 1, 0
    while i <= #s do
        local b = s:byte(i)
        local step = (b >= 240 and 4) or (b >= 224 and 3) or (b >= 192 and 2) or 1
        if i + step - 1 > maxBytes then break end
        last = i + step - 1
        i = i + step
    end
    return s:sub(1, last)
end

-- Обрезка по СИМВОЛАМ (UTF-8-безопасно).
local function utf8Cut(s, maxChars)
    s = tostring(s or "")
    maxChars = math.max(0, math.floor(tonumber(maxChars) or 0))
    if maxChars <= 0 then return "" end
    if type(grndBinderUtf8Cut) == "function" then
        local ok, cut = pcall(grndBinderUtf8Cut, s, maxChars)
        if ok and type(cut) == "string" then return cut end
    end
    local i, n = 1, 0
    while i <= #s and n < maxChars do
        local b = s:byte(i)
        local step = (b >= 240 and 4) or (b >= 224 and 3) or (b >= 192 and 2) or 1
        i = i + step
        n = n + 1
    end
    return s:sub(1, i - 1)
end

-- Экранирование значений конфига — ровно как у биндера (grndBinderEscape/
-- grndBinderUnescape): переводы строк живут в .cfg как \n, обратный слэш —
-- как \\. Если глобальных функций нет, работаем своими.
local function esc(s)
    if type(grndBinderEscape) == "function" then
        local ok, v = pcall(grndBinderEscape, s)
        if ok and type(v) == "string" then return v end
    end
    return (tostring(s or ""):gsub("\r", ""):gsub("\\", "\\\\"):gsub("\n", "\\n"))
end

local function unesc(s)
    s = tostring(s or "")
    if type(grndBinderUnescape) == "function" then
        local ok, v = pcall(grndBinderUnescape, s)
        if ok and type(v) == "string" then return v end
    end
    local out, i, n = {}, 1, #s
    while i <= n do
        local c = s:sub(i, i)
        if c == "\\" and i < n then
            local n1 = s:sub(i + 1, i + 1)
            if n1 == "n" then out[#out + 1] = "\n"
            elseif n1 == "\\" then out[#out + 1] = "\\"
            else out[#out + 1] = n1 end
            i = i + 2
        else
            out[#out + 1] = c
            i = i + 1
        end
    end
    return table.concat(out)
end

local function clampText(s, cap)
    s = tostring(s or "")
    if #s > cap then s = utf8Cut(s, cap) end
    return s
end

-- Обрезка по ширине с «…». Возвращает СРАЗУ строку и её ширину, поэтому
-- кнопкам и строкам списка хватает одного-двух замеров: раньше цикл мерил
-- текст посимвольно (на длинных шаблонах это било по кадру).
local function fitW(s, maxW, measure, scale)
    s = tostring(s or "")
    if s == "" or type(measure) ~= "function" then return s, 0 end
    scale = scale or 1
    local ok, w = pcall(measure, s, scale)
    w = (ok and tonumber(w)) or 0
    if not maxW or maxW <= 6 or w <= maxW then return s, w end
    local chars = {}
    for ch in s:gmatch("[%z\1-\127\194-\244][\128-\191]*") do chars[#chars + 1] = ch end
    local keep = math.floor(#chars * (maxW - 10) / math.max(1, w))
    if keep < 1 then keep = 1 end
    if keep > #chars - 1 then keep = #chars - 1 end
    local shown = table.concat(chars, "", 1, keep) .. "…"
    for _ = 1, 8 do
        local ok2, w2 = pcall(measure, shown, scale)
        w2 = (ok2 and tonumber(w2)) or w
        if w2 <= maxW or keep <= 1 then return shown, w2 end
        keep = keep - 1
        shown = table.concat(chars, "", 1, keep) .. "…"
    end
    return shown, w
end

local function fit(s, maxW, measure, scale)
    local shown = fitW(s, maxW, measure, scale)
    return shown
end

-- v1.19.33: перенос длинного текста по словам под ширину — для подсказки под
-- полем «Триггер» (одной строкой длинная фраза не помещается). Каждая строка
-- не шире maxW; слишком длинное одиночное слово подрезается, как во fitW.
local function wrapW(s, maxW, measure, scale)
    s = tostring(s or "")
    scale = tonumber(scale) or 1
    local out, line = {}, ""
    local function width(t)
        if type(measure) == "function" then
            local ok, w = pcall(measure, t, scale)
            if ok and type(w) == "number" then return w end
        end
        return #tostring(t) * 7 * scale
    end
    for word in s:gmatch("%S+") do
        if line == "" then
            line = word
        else
            local cand = line .. " " .. word
            if width(cand) <= maxW then
                line = cand
            else
                out[#out + 1] = line
                line = word
            end
        end
        if width(line) > maxW then line = fitW(line, maxW, measure, scale) end
    end
    if line ~= "" then out[#out + 1] = line end
    return out
end

-- Высота строки текста в этой сборке ImGui.
local function lineH(ctx, scale)
    scale = tonumber(scale) or 1
    local h = 14 * scale
    if ctx and type(ctx.tsize) == "function" then
        local ok, _, hh = pcall(ctx.tsize, "X")
        if ok and type(hh) == "number" and hh > 0 then h = hh * scale end
    end
    return h
end

-- ---------- буферы ввода ----------
-- Буфер — единственный источник правды, пока форма открыта: модель
-- переписывается в него ТОЛЬКО по запросу (pending) — при смене шаблона,
-- создании нового или сбросе. Иначе набор текста терялся бы на каждом кадре.

local function bufGet(im, key, cap)
    local f = QR.bufs[key]
    if f and (f.cap ~= cap or f.im ~= im) then f = nil; QR.bufs[key] = nil end
    if not f then
        if not (im and im.new and im.new.char) then return nil end
        local ok, b = pcall(function() return im.new.char[cap]() end)
        if not (ok and b) then return nil end
        f = { buf = b, cap = cap, im = im, pending = true }
        QR.bufs[key] = f
    end
    return f
end

local function bufWrite(key, value)
    local f = QR.bufs[key]
    if not f then return end
    -- режем и по символам, и по БАЙТАМ: ffi.copy не должен выйти за char[cap]
    local text = byteCut(clampText(value, f.cap - 1), f.cap - 1)
    if type(grndBinderWriteCBuf) == "function" then
        pcall(grndBinderWriteCBuf, f.buf, f.cap, text)
    end
    f.pending = false
end

local function bufText(key)
    local f = QR.bufs[key]
    if not f then return "" end
    if type(grndBinderReadCBuf) == "function" then
        local ok, v = pcall(grndBinderReadCBuf, f.buf)
        if ok and type(v) == "string" then return (v:gsub("%z", "")) end
    end
    return ""
end

local function bufReload(key)
    local f = QR.bufs[key]
    if f then f.pending = true end
end

-- ---------- мышь и колесо ----------

local function wheelDelta(im)
    local w = 0
    if im and im.GetIO then
        local ok, io = pcall(im.GetIO)
        if ok and io then w = tonumber(io.MouseWheel) or 0 end
    end
    return w
end

local function mouse(im)
    local mx, my
    if im and im.GetIO then
        local ok, io = pcall(im.GetIO)
        if ok and io and io.MousePos then
            mx, my = tonumber(io.MousePos.x), tonumber(io.MousePos.y)
        end
    end
    if not mx and _G.GRND_MOUSE then
        mx, my = tonumber(_G.GRND_MOUSE.x), tonumber(_G.GRND_MOUSE.y)
    end
    return mx, my
end

-- Прокрутка колесом, если курсор внутри прямоугольника (экранные координаты).
local function scrollWheel(im, mx, my, x, y, w, h, cur, maxScroll, step)
    if not (mx and my) or maxScroll <= 0 then return cur end
    if mx < x or mx > x + w or my < y or my > y + h then return cur end
    local dw = wheelDelta(im)
    if dw == 0 then return cur end
    local now = os.clock()
    if now - (QR.wheelAt or 0) < 0.05 then return cur end
    QR.wheelAt = now
    return math.max(0, math.min(maxScroll, cur - dw * (step or 44)))
end

-- =====================================================================
--  Конфиг: GRND_CONFIG.open("…grnd_repquick.cfg") → секция reportTemplates
-- =====================================================================

function QR.path()
    if type(this_script_dir) == "function" then
        local okd, sd = pcall(this_script_dir)
        if okd and sd and tostring(sd) ~= "" then
            local pp = tostring(sd)
            while pp:sub(-1) == "/" or pp:sub(-1) == "\\" do pp = pp:sub(1, -2) end
            local sep = "\\"
            local okc, cf = pcall(function() return package.config end)
            if okc and type(cf) == "string" and #cf > 0 then sep = cf:sub(1, 1) end
            return pp .. sep .. "grnd_repquick.cfg"
        end
    end
    return "grnd_repquick.cfg"
end

function QR.modeOk(v)
    v = tostring(v or "")
    if v == "input" then return "input" end
    -- v1.19.56: канала /n больше нет — старое значение «test» читается как
    -- боевой ответ игроку
    return "ans"
end

-- Демо-набор прошлых сборок. Сам он больше НЕ создаётся: список шаблонов
-- должен начинаться пустым. Таблица нужна ровно для одного — вычистить из
-- конфига уже сохранённые демо-шаблоны (совпадение имени И текста, чтобы
-- не тронуть ничего своего).
local DEMOS = {
    { name = "Приветствие", text = "Приветствую, чем могу помочь?" },
    { name = "Принято в работу", text = "Приветствую, ваше обращение принято. Ожидайте ответа." },
    { name = "Нарушитель наказан", text = "Приветствую, нарушитель будет наказан. Спасибо за обращение!" },
    { name = "Нарушения нет", text = "Приветствую, в данной ситуации нарушения правил нет." },
    { name = "Нужны доказательства", text = "Приветствую, доказательств недостаточно. Прикрепите скриншот или видео." },
}

-- Убирает из списка ровно демо-шаблоны. Возвращает, сколько удалили.
local function dropDemos()
    if type(QR.items) ~= "table" or #QR.items == 0 then return 0 end
    local keep, removed = {}, 0
    for i = 1, #QR.items do
        local it = QR.items[i]
        local demo = false
        for d = 1, #DEMOS do
            if it.name == DEMOS[d].name and it.text == DEMOS[d].text then demo = true; break end
        end
        if demo then removed = removed + 1 else keep[#keep + 1] = it end
    end
    if removed > 0 then
        QR.items = keep
        if QR.selId and not QR.byId(QR.selId) then QR.selId, QR.formKey = nil, nil end
    end
    return removed
end

-- Приведение списка к рабочему виду: id, порядок, границы текста.
function QR.normalize()
    if type(QR.items) ~= "table" then QR.items = {} end
    local seen, out, maxId = {}, {}, 0
    for i = 1, #QR.items do
        local it = QR.items[i]
        if type(it) == "table" then
            local id = math.floor(tonumber(it.id) or 0)
            if id <= 0 or seen[id] then
                id = 0
                repeat id = id + 1 until not seen[id]
            end
            local name = clampText(trim(utf(it.name or "")), MAX_NAME)
            local text = clampText(cleanText(utf(it.text or "")), MAX_TEXT)
            if name == "" and text ~= "" then name = utf8Cut(oneLine(text), 28) end
            if name ~= "" or text ~= "" then
                if name == "" then name = "Шаблон " .. tostring(id) end
                seen[id] = true
                if id > maxId then maxId = id end
                out[#out + 1] = { id = id, name = name, text = text }
            end
        end
    end
    QR.items = out
    QR.nextId = math.max(math.floor(tonumber(QR.nextId) or 1), maxId + 1)
    QR.mode = QR.modeOk(QR.mode)
    if QR.selId and not seen[math.floor(tonumber(QR.selId) or 0)] then QR.selId = nil end
    return out
end

function QR.load()
    if QR.loaded then return true end
    QR.loaded = true
    local items, mode, nextId = {}, nil, nil
    local demoMark = nil     -- конфиг уже проходил чистку демо-набора
    local hadRows = false    -- в конфиге уже что-то было (пустой список не «оживляем»)
    local ok, f = pcall(GRND_CONFIG.open, QR.path(), "r")
    if ok and f then
        local cur = nil
        for line in f:lines() do
            line = tostring(line or "")
            if line == "---" then
                hadRows = true
                cur = {}
                items[#items + 1] = cur
            else
                local k, v = line:match("^([%w_]+)=(.*)$")
                if k then
                    hadRows = true
                    if cur then
                        if k == "id" then cur.id = tonumber(v)
                        elseif k == "name" then cur.name = unesc(v)
                        elseif k == "text" then cur.text = unesc(v) end
                    else
                        if k == "mode" then mode = v
                        elseif k == "nextId" then nextId = tonumber(v)
                        elseif k == "demo" then demoMark = tonumber(v) end
                    end
                end
            end
        end
        pcall(f.close, f)
    end
    QR.items = items
    if mode then QR.mode = QR.modeOk(mode) end
    if nextId then QR.nextId = nextId end
    QR.normalize()
    -- v1.19.01: предзаполнения больше нет. Если в конфиге остался демо-набор
    -- прошлых сборок — убираем его один раз и запоминаем это маркером demo=1.
    if hadRows and not demoMark then
        dropDemos()
        pcall(QR.save)
    end
    return true
end

function QR.ensure()
    if not QR.loaded then pcall(QR.load) end
    if type(QR.items) ~= "table" then pcall(QR.normalize) end
    return QR
end

function QR.save()
    QR.normalize()
    local ok, f = pcall(GRND_CONFIG.open, QR.path(), "w")
    if not ok or not f then return false end
    local escv = esc   -- grndBinderEscape, если он есть в сборке
    f:write("mode=" .. tostring(QR.mode or "test") .. "\n")
    f:write("nextId=" .. tostring(QR.nextId or 1) .. "\n")
    f:write("demo=1\n")   -- чистка демо-набора уже выполнена
    for i = 1, #QR.items do
        local it = QR.items[i]
        f:write("---\n")
        f:write("id=" .. tostring(it.id or 0) .. "\n")
        f:write("name=" .. escv(tostring(it.name or "")) .. "\n")
        f:write("text=" .. escv(tostring(it.text or "")) .. "\n")
    end
    pcall(f.close, f)
    if GRND_CONFIG and type(GRND_CONFIG.flush) == "function" then
        pcall(GRND_CONFIG.flush)
    end
    return true
end

-- ---------- операции со списком ----------

function QR.byId(id)
    id = math.floor(tonumber(id) or 0)
    if type(QR.items) ~= "table" then return nil, nil end
    for i = 1, #QR.items do
        if QR.items[i].id == id then return QR.items[i], i end
    end
    return nil, nil
end

function QR.count()
    return (type(QR.items) == "table") and #QR.items or 0
end

function QR.noteShow(text, kind)
    QR.note, QR.noteKind, QR.noteAt = tostring(text or ""), kind or "ok", os.clock()
end

function QR.add(name, text)
    QR.ensure()
    local id = math.max(1, math.floor(tonumber(QR.nextId) or 1))
    QR.nextId = id + 1
    local it = {
        id = id,
        name = clampText(trim(utf(name or "")), MAX_NAME),
        text = clampText(cleanText(utf(text or "")), MAX_TEXT),
    }
    if it.name == "" and it.text ~= "" then it.name = utf8Cut(oneLine(it.text), 28) end
    QR.items[#QR.items + 1] = it
    return it
end

function QR.update(id, name, text)
    local it = QR.byId(id)
    if not it then return false end
    it.name = clampText(trim(utf(name or "")), MAX_NAME)
    it.text = clampText(cleanText(utf(text or "")), MAX_TEXT)
    if it.name == "" and it.text ~= "" then it.name = utf8Cut(oneLine(it.text), 28) end
    return true
end

function QR.remove(id)
    id = math.floor(tonumber(id) or 0)
    if type(QR.items) ~= "table" then return false end
    for i = 1, #QR.items do
        if QR.items[i].id == id then
            table.remove(QR.items, i)
            if QR.selId == id then QR.selId, QR.formKey = nil, nil end
            return true
        end
    end
    return false
end

function QR.move(id, dir)
    local it, idx = QR.byId(id)
    if not it then return false end
    local other = idx + ((dir or 0) < 0 and -1 or 1)
    if other < 1 or other > #QR.items then return false end
    QR.items[idx], QR.items[other] = QR.items[other], QR.items[idx]
    return true
end

-- ---------- подстановки, отправка, выбор шаблона ----------

function QR.myNick()
    local id
    if type(sampGetLocalPlayerId) == "function" then
        local ok, v = pcall(sampGetLocalPlayerId)
        if ok and type(v) == "number" then id = math.floor(v) end
    end
    if id and type(sampGetPlayerNickname) == "function" then
        local ok, v = pcall(sampGetPlayerNickname, id)
        if ok and type(v) == "string" and v ~= "" then return utf(v) end
    end
    return "?"
end

-- Подстановки: {ник}/{nick} — автор репорта, {ид}/{id} — его ID,
-- {время}/{time} — часы:минуты, {мой_ник}/{mynick} — мой ник в игре.
function QR.apply(text, rep)
    local s = tostring(text or "")
    rep = (type(rep) == "table") and rep or {}
    local nick = tostring(rep.nick or rep.author or "")
    local author = tostring(rep.author or rep.nick or "")
    local pid = tostring(rep.id or rep.playerId or "")
    -- v1.19.36: {ID} — ID из текста репорта («дм 234»), если он там был.
    -- v1.19.45: {ник}/{ID}/{ид} — тот, НА КОГО пожаловались (нарушитель), а не
    -- автор строки репорта; автор доступен как {автор}/{reporter}.
    local target = tostring(rep.foundId or "") ~= "" and tostring(rep.foundId) or pid
    local map = {
        ["{ник}"] = nick, ["{nick}"] = nick,
        ["{автор}"] = author, ["{reporter}"] = author,
        ["{ид}"] = target, ["{id}"] = target,
        ["{ID}"] = target,
        ["{время}"] = os.date("%H:%M"), ["{time}"] = os.date("%H:%M"),
        ["{мой_ник}"] = QR.myNick(), ["{mynick}"] = QR.myNick(),
    }
    for k, v in pairs(map) do
        if v ~= "" then
            local safe = tostring(v):gsub("%%", "%%%%")
            s = s:gsub(k, safe)
        end
    end
    return s
end

function QR.repInfo()
    local R = _G.GRND_REP
    if type(R) ~= "table" then return { nick = "", id = "" } end
    return { nick = tostring(R.author or ""), id = tostring(R.playerId or "") }
end

function QR.toast(text, kind, life)
    if type(notify) == "table" and type(notify.add) == "function" then
        pcall(notify.add, tostring(text or ""), kind or "ok", life or 3.2)
    end
end

function QR.sendChat(cmd)
    if type(cmd) ~= "string" or cmd == "" then return false end
    QR.chats = (QR.chats or 0) + 1
    if type(grndChatSend) == "function" then
        local ok, res = pcall(grndChatSend, cmd)
        if ok and res ~= false then return true end
    end
    if type(sampSendChat) == "function" then
        local text = cmd
        if type(grndAnsiText) == "function" then
            local okA, ansi = pcall(grndAnsiText, cmd)
            if okA and type(ansi) == "string" and ansi ~= "" then text = ansi end
        end
        return pcall(sampSendChat, text) and true or false
    end
    return false
end

-- Команда в чат «мимо» QR.sendChat: UTF-8 → CP1251 и в ту же очередь
-- репорта, что и ответ игроку (grndRepQueue отправляет по одной строке за тик).
-- Нужна там, где в команде есть русский текст — например причина наказания:
-- без конвертации в чат уходили «закорючки».
function QR.queueCmd(cmd)
    cmd = tostring(cmd or "")
    if cmd == "" then return false end
    if type(grndRepQueue) == "function" then
        local out = cmd
        if type(grndAnsiText) == "function" then
            local okA, ansi = pcall(grndAnsiText, cmd)
            if okA and type(ansi) == "string" and ansi ~= "" then out = ansi end
        end
        if pcall(grndRepQueue, out) then
            QR.chats = (QR.chats or 0) + 1
            return true
        end
    end
    return QR.sendChat(cmd)
end

-- Выбор шаблона: ответить игроку (боевая /ans) / вставить в поле ответа.
-- Закрыть окно репорта вместе с полосой шаблонов: ответ отправлен, держать
-- окно на экране незачем (v1.19.10).
function QR.closeReport()
    local R = _G.GRND_REP
    if type(R) == "table" then
        R.open = false
        R.focused = false
    end
    QR.pickOpen, QR.pickFocus = false, false
    if type(QR.pun) == "table" then QR.pun.pickOpen, QR.pun.pickFocus = false, false end
    return true
end

function QR.choose(it)
    if type(it) ~= "table" then return false end
    local rep = QR.repInfo()
    local text = trim(QR.apply(it.text or "", rep))
    QR.pickOpen, QR.pickFocus = false, false
    local label = tostring(it.name or "шаблон")
    if oneLine(text) == "" then
        QR.toast("Шаблон «" .. label .. "» пуст", "warn", 2.5)
        return false
    end
    local mode = QR.modeOk(QR.mode)

    if mode == "input" then
        local R = _G.GRND_REP
        local buf = R and R.answer
        if buf and type(grndBinderWriteCBuf) == "function" then
            local body = text
            if lower(body):find("^приветствую") then
                body = body:gsub("^[Пп]риветствую[,!]?%s*", "")
            end
            local fit256 = byteCut(oneLine(body), MAX_BUF)
            if fit256 ~= oneLine(body) then
                QR.toast("Текст шаблона обрезан под поле ответа", "warn", 3)
            end
            if pcall(grndBinderWriteCBuf, buf, 256, fit256) then
                if R then R.focused = false end
                QR.toast("Шаблон «" .. label .. "» вставлен в поле ответа", "ok", 2.6)
                return true
            end
        end
        mode = "ans"       -- нет буфера — отвечаем игроку
    end

    -- v1.19.19: ответ игроку уходит штатной командой /ans ID текст — вместо
    -- прежнего /n. Так работают и «быстрые ответы», и «наказания»: сначала
    -- человек получает ответ, потом (в наказаниях) прилетает команда.
    do
        local pid = tostring(rep.id or "")
        if pid:match("^%d+$") and type(grndRepAnswer) == "function" then
            local okA, res = pcall(grndRepAnswer, pid, text)
            if okA and res ~= false then
                QR.toast("Ответ игроку /ans " .. pid .. ": «" .. utf8Cut(label, 20) .. "»", "ok", 2.8)
                QR.closeReport()      -- ответ ушёл: окно репорта тоже закрываем
                return true
            end
        end
    end
    mode = "ans"

    -- Нет ID игрока (ответить некому): в боевом режиме в чат НИЧЕГО не уходит —
    -- служебного канала /n больше нет (v1.19.56). Чтобы текст не потерялся,
    -- кладём его в поле ответа открытого окна репорта; поля нет — предупреждаем.
    local R = _G.GRND_REP
    local buf = R and R.answer
    if buf and type(grndBinderWriteCBuf) == "function" then
        local line = byteCut(oneLine(text), MAX_BUF)
        pcall(grndBinderWriteCBuf, buf, 256, line)
        if R then R.focused = false end
        QR.toast("В репорте нет ID игрока — текст шаблона вставлен в поле ответа", "warn", 3.4)
        return true
    end
    QR.toast("В репорте нет ID игрока — отвечать некому", "warn", 3)
    return false
end

function QR.openPicker()
    QR.ensure()
    -- v1.19.03: шаблонов нет — полоса НЕ открывается, вылезает тост
    if QR.count() == 0 then
        QR.pickOpen, QR.pickFocus = false, false
        QR.toast("Шаблонов пока нет — создайте их в меню «Репорт», вкладка «Ответы на репорт»", "warn", 3.5)
        return false
    end
    if type(QR.pun) == "table" then QR.pun.pickOpen, QR.pun.pickFocus = false, false end
    QR.pickOpen, QR.pickFocus = true, true
    QR.pickScroll = 0
    return true
end

-- Повторный клик по кнопке «Быстрые ответы» прячет окно (как тумблер).
function QR.togglePicker()
    if QR.pickOpen then
        QR.closePicker()
    else
        QR.openPicker()
    end
end

function QR.closePicker()
    QR.pickOpen, QR.pickFocus = false, false
end

-- ESC (общий grndEscAction): закрывает окно быстрых ответов.
function _G.grndQrOnEsc()
    local Q = _G.GRND_QR
    if type(Q) ~= "table" then return false end
    if type(Q.auto) == "table" and Q.auto.listOpen then
        Q.auto.listOpen = false              -- открыт список команд автопилота
        return true
    end
    local P = Q.pun
    if type(P) == "table" then
        if P.comboOpen then            -- открыт список команд — закрываем его
            P.comboOpen = false
            return true
        end
        if P.pickOpen then             -- открыта полоса наказаний
            P.pickOpen, P.pickFocus = false, false
            return true
        end
    end
    if Q.pickOpen then
        Q.pickOpen, Q.pickFocus = false, false
        return true
    end
    return false
end

-- =====================================================================
--  Помощники отрисовки (ctx: im, at, dl, uiText, col32, rgba, roundRect,
--  drawnW, tsize, pushCol/popCol, pushVarF/pushVarV2/popVar)
-- =====================================================================

-- Поле ввода в стиле окна. Возвращает «изменено в этом кадре».
local function field(ctx, id, key, cap, x, y, w, h, hint, multiline, initial)
    local im = ctx.im
    local TH = theme()
    local f = bufGet(im, key, cap)
    if not f then
        ctx.roundRect(ctx.dl, ctx.at(x, y), ctx.at(x + w, y + h), ctx.col32(255, 255, 255, 8), 6)
        ctx.uiText(x + 8, y + math.floor(h / 2) - 8, "поле ввода недоступно",
            ctx.rgba(230, 150, 150, 255), 0.85)
        return false
    end
    if f.pending then bufWrite(key, initial or "") end

    local nCol, nVar = 0, 0
    if ctx.pushCol and im.Col then
        local push = ctx.pushCol
        if im.Col.FrameBg and push(im.Col.FrameBg, ctx.rgba(12, 15, 22, 255)) then nCol = nCol + 1 end
        if im.Col.FrameBgHovered and push(im.Col.FrameBgHovered, ctx.rgba(18, 22, 31, 255)) then nCol = nCol + 1 end
        if im.Col.FrameBgActive and push(im.Col.FrameBgActive, ctx.rgba(21, 26, 36, 255)) then nCol = nCol + 1 end
        if im.Col.Text and push(im.Col.Text, ctx.rgba(233, 237, 246, 255)) then nCol = nCol + 1 end
        if im.Col.Border and push(im.Col.Border, ctx.rgba(255, 255, 255, 36)) then nCol = nCol + 1 end
    end
    if ctx.pushVarF and im.StyleVar and im.StyleVar.FrameBorderSize then
        if ctx.pushVarF(im.StyleVar.FrameBorderSize, 1) then nVar = nVar + 1 end
    end
    if ctx.pushVarV2 and im.StyleVar and im.StyleVar.FramePadding and not multiline then
        if ctx.pushVarV2(im.StyleVar.FramePadding, 9, math.max(2, math.floor((h - 14) / 2))) then
            nVar = nVar + 1
        end
    end

    im.SetCursorPos(im.ImVec2(x, y))   -- локальные координаты окна (см. шапку модуля)
    if im.SetNextItemWidth then pcall(im.SetNextItemWidth, w) end
    local changed, okCall = false, false
    if multiline and type(im.InputTextMultiline) == "function" then
        local sz = im.ImVec2(w, h)
        -- у разных сборок mimgui порядок аргументов разный (ffi-буфер обычно
        -- требует capacity, ImBuffer — только размер); удачную сигнатуру
        -- запоминаем в самом буфере, чтобы не гадать каждый кадр
        local function invokeMulti(sig)
            if sig == 1 then return im.InputTextMultiline(id, f.buf, cap, sz, 0) end
            if sig == 2 then return im.InputTextMultiline(id, f.buf, cap, sz) end
            if sig == 3 then return im.InputTextMultiline(id, f.buf, sz, 0) end
            return im.InputTextMultiline(id, f.buf, sz)
        end
        local order = f.multiSig and { f.multiSig } or { 1, 2, 3, 4 }
        for _, sig in ipairs(order) do
            local okM, res = pcall(invokeMulti, sig)
            if okM then
                f.multiSig = sig
                changed, okCall = (res == true), true
                break
            end
        end
        if not okCall and f.multiSig then
            -- сохранённая сигнатура перестала работать (другое окно/сборка)
            f.multiSig = nil
            for _, sig in ipairs({ 1, 2, 3, 4 }) do
                local okM, res = pcall(invokeMulti, sig)
                if okM then
                    f.multiSig = sig
                    changed, okCall = (res == true), true
                    break
                end
            end
        end
        if okCall and hint and trim(bufText(key)) == "" then
            ctx.uiText(x + 9, y + 7, hint, ctx.rgba(128, 135, 154, 255), 0.9)
        end
    else
        local function call(withHint, sig)
            if withHint and type(im.InputTextWithHint) == "function" then
                local ok, r = pcall(im.InputTextWithHint, id, hint or "", f.buf, cap)
                if ok then return true, r end
                return false
            end
            if sig == 1 then
                local ok, r = pcall(im.InputText, id, f.buf, cap)
                return ok, r
            end
            local ok, r = pcall(im.InputText, id, f.buf)
            return ok, r
        end
        local okM, res = call(true, 1)
        if not okM then okM, res = call(false, 1) end
        if not okM then okM, res = call(false, 2) end
        if okM then okCall, changed = true, (res == true) end
    end

    -- v1.19.24: своей рамки поверх поля больше нет. Она рисовалась по
    -- габаритам и при наведении становилась ярче — поверх поля появлялся
    -- полупрозрачный прямоугольник («квадратик»). Теперь наведение видно
    -- только по родному фону поля, рамка задаётся цветом Border выше.

    if ctx.popVar and nVar > 0 then ctx.popVar(nVar) end
    if ctx.popCol and nCol > 0 then ctx.popCol(nCol) end
    return changed
end

-- Треугольник средствами draw-list: символы ▲ ▼ ↵ есть не во всех шрифтах
-- (показывались как «?» или пустое место), поэтому рисуем фигуру сами.
-- dir: "up" | "down" | "right". Возвращает true, если что-то нарисовали.
local function tri(dl, at, cx, cy, size, dir, col)
    local s = tonumber(size) or 4
    local pts
    if dir == "up" then
        pts = { { cx, cy - s }, { cx - s, cy + s }, { cx + s, cy + s } }
    elseif dir == "down" then
        pts = { { cx, cy + s }, { cx - s, cy - s }, { cx + s, cy - s } }
    else
        pts = { { cx + s, cy }, { cx - s, cy - s }, { cx - s, cy + s } }
    end
    local p1, p2, p3 = at(pts[1][1], pts[1][2]), at(pts[2][1], pts[2][2]), at(pts[3][1], pts[3][2])
    if dl.AddTriangleFilled then
        if pcall(dl.AddTriangleFilled, dl, p1, p2, p3, col) then return true end
    end
    if dl.AddTriangle then
        if pcall(dl.AddTriangle, dl, p1, p2, p3, col, 1) then return true end
    end
    if dl.AddLine then
        local a = pcall(dl.AddLine, dl, p1, p2, col, 1)
        local b = pcall(dl.AddLine, dl, p2, p3, col, 1)
        local c = pcall(dl.AddLine, dl, p3, p1, col, 1)
        if a and b and c then return true end
    end
    return false
end

-- Кнопка в стиле окна. opts: primary | selected | danger | muted | tri = up/down/right
local function button(ctx, id, x, y, w, h, label, opts)
    opts = opts or {}
    local im, dl, at = ctx.im, ctx.dl, ctx.at
    local TH = theme()
    local ac = TH.accent or { 164, 112, 224, 255 }
    im.SetCursorPos(im.ImVec2(x, y))   -- локальные координаты окна
    local clicked = im.InvisibleButton(id, im.ImVec2(w, h)) and true or false
    local hov = (im.IsItemHovered and im.IsItemHovered()) or false
    local act = (im.IsItemActive and im.IsItemActive()) or false
    local bg, bd, fg
    if opts.danger then
        bg = (hov or act) and ctx.col32(255, 96, 96, 56) or ctx.col32(255, 96, 96, 32)
        bd = ctx.col32(255, 96, 96, (hov or act) and 130 or 84)
        fg = ctx.col32(255, 190, 190, 255)
    elseif opts.primary then
        bg = (hov or act) and ctx.col32(TH.accent2[1], TH.accent2[2], TH.accent2[3], 255)
            or ctx.col32(ac[1], ac[2], ac[3], 235)
        bd = ctx.col32(255, 255, 255, 45)
        fg = ctx.col32(18, 15, 24, 255)
    elseif opts.selected then
        bg = ctx.col32(ac[1], ac[2], ac[3], 40)
        bd = ctx.col32(ac[1], ac[2], ac[3], 125)
        fg = ctx.col32(250, 248, 255, 255)
    elseif act then
        bg, bd, fg = ctx.col32(255, 255, 255, 38), ctx.col32(255, 255, 255, 72), ctx.col32(250, 248, 255, 255)
    elseif hov then
        bg, bd, fg = ctx.col32(255, 255, 255, 32), ctx.col32(255, 255, 255, 64), ctx.col32(250, 248, 255, 255)
    else
        -- v1.19.06: спокойная кнопка видна (было 10/20 — «пропадала»)
        bg, bd = ctx.col32(255, 255, 255, 22), ctx.col32(255, 255, 255, 40)
        -- v1.19.03: подписи кнопок ярче (просили «поярче»)
        fg = opts.muted and ctx.col32(208, 202, 226, 255) or ctx.col32(240, 236, 250, 255)
    end
    ctx.roundRect(dl, at(x, y), at(x + w, y + h), bg, 6)
    if dl.AddRect then
        pcall(dl.AddRect, dl, at(x + 0.5, y + 0.5), at(x + w - 0.5, y + h - 0.5), bd, 6, 0, 1)
    end
    if opts.tri then
        local tc = (hov or act) and fg or bd
        tri(dl, at, x + w / 2, y + h / 2, opts.tri == "right" and 3.6 or 4, opts.tri, tc)
        return clicked, hov
    end
    local shown, tw = fitW(label, w - 12, ctx.drawnW, 0.92)
    if not tw or tw <= 0 then
        -- замер недоступен: грубая прикидка по числу символов
        tw = utf8Len(shown) * 7 * 0.92
    end
    ctx.uiText(x + math.max(5, (w - tw) / 2), y + (h - lineH(ctx, 0.92)) / 2, shown, fg, 0.92)
    return clicked, hov
end

-- Чип-бейдж (счётчик шаблонов).
local function chip(ctx, x, y, label)
    local TH = theme()
    local w = 24
    if type(ctx.drawnW) == "function" then
        local ok, v = pcall(ctx.drawnW, label, 0.85)
        if ok and type(v) == "number" then w = v end
    end
    w = w + 18
    local h = 22
    ctx.roundRect(ctx.dl, ctx.at(x, y), ctx.at(x + w, y + h),
        ctx.col32(TH.accent[1], TH.accent[2], TH.accent[3], 34), 11)
    ctx.uiText(x + 9, y + (h - lineH(ctx, 0.85)) / 2 + 1, label,
        ctx.col32(TH.accent[1], TH.accent[2], TH.accent[3], 255), 0.85)
    return w
end

-- =====================================================================
--  ОКНО «БЫСТРЫЕ ОТВЕТЫ» (открывается кнопкой в окне репорта)
-- =====================================================================

-- =====================================================================
--  ПОЛОСА «БЫСТРЫЕ ОТВЕТЫ» (v1.19.03)
--
--  Было большое окно: шапка с заголовком, поиск, список строк по 56 px и
--  подвал. Стало — компактная ГОРИЗОНТАЛЬНАЯ полоса, в которой только
--  кнопки шаблонов: клик отправляет ответ и закрывает полосу. Ничего
--  лишнего — без шапки, поиска, списка и строки-подсказки внизу. Полный текст
--  шаблона — во всплывающей подсказке при наведении (v1.19.12).
--  Ширина полосы — не больше окна репорта: что не влезло в ряд, переносится
--  на следующий, и полоса растёт ВНИЗ новыми рядами кнопок (до нижнего края
--  экрана, дальше — прокрутка колесом), а не разъезжается вширь.
--  Шаблонов нет — полоса не открывается вовсе, QR.openPicker даёт тост.
-- =====================================================================
local PICK_BH, PICK_GAP = 30, 6       -- высота кнопки и зазор между кнопками
local PICK_PADX, PICK_PADY = 10, 9    -- поля карточки
local PICK_MIN_W, PICK_MAX_W = 108, 240
local PICK_ATTACH = 10                -- зазор до нижней кромки окна репорта (v1.19.11)
local PICK_SCREEN_GAP = 10            -- зазор до нижнего края экрана (v1.19.12)

-- Раскладка: ширина кнопки — по длине названия, перенос по строкам.
-- Возвращает строки кнопок и ширину самой широкой строки.
local function pickerLayoutItems(ctx, availW, items)
    local measure = ctx.drawnW
    local function mw(str)
        if type(measure) == "function" then
            local ok, v = pcall(measure, str, 0.94)
            if ok and type(v) == "number" and v > 0 then return v end
        end
        return utf8Len(str) * 7 * 0.94
    end
    items = (type(items) == "table") and items or QR.items
    local rows, cur, curW = {}, {}, 0
    for i = 1, #items do
        local item = items[i]
        local label = trim(tostring(item.name or ""))
        if label == "" then label = "шаблон" end
        local bw = math.floor(mw(label) + 28)
        if bw < PICK_MIN_W then bw = PICK_MIN_W end
        if bw > PICK_MAX_W then bw = PICK_MAX_W end
        if bw > availW then bw = math.max(60, availW) end
        if #cur > 0 and curW + PICK_GAP + bw > availW then
            rows[#rows + 1] = cur
            cur, curW = {}, 0
        end
        cur[#cur + 1] = { it = item, w = bw, label = label }
        curW = curW + bw + (#cur > 1 and PICK_GAP or 0)
    end
    if #cur > 0 then rows[#rows + 1] = cur end
    local winW = 0
    for r = 1, #rows do
        local sum = 0
        for i = 1, #rows[r] do sum = sum + rows[r][i].w + (i > 1 and PICK_GAP or 0) end
        if sum > winW then winW = sum end
    end
    return rows, winW
end

local function pickerLayout(ctx, availW)
    return pickerLayoutItems(ctx, availW, QR.items)
end

local function pickerDraw(ctx)
    if type(ctx) ~= "table" then return false end
    local im = ctx.im
    if not (im and ctx.begin and ctx.uiText and ctx.roundRect and ctx.col32 and ctx.rgba) then
        return false
    end
    if not QR.pickOpen then return false end
    -- окно репорта закрылось (ESC, ответ, действие) — полосу убираем
    if not (_G.GRND_REP and _G.GRND_REP.open) then
        QR.pickOpen, QR.pickFocus = false, false
        return false
    end
    QR.ensure()
    -- Пустой список: полосы нет вовсе (тост показывает openPicker, здесь —
    -- страховка, если шаблоны удалили уже с открытой полосой)
    if QR.count() == 0 then
        QR.pickOpen, QR.pickFocus = false, false
        QR.toast("Шаблонов пока нет — создайте их в меню «Репорт», вкладка «Ответы на репорт»", "warn", 3.5)
        return false
    end
    QR.left = (QR.left or 0) + 1
    local TH = theme()
    local acC = TH.accent or { 164, 112, 224, 255 }

    local resX, resY = getScreenResolution()
    resX, resY = tonumber(resX) or 1920, tonumber(resY) or 1080
    local rowH = PICK_BH + PICK_GAP
    -- v1.19.10…v1.19.13: полоса приклеена к окну репорта — левый край ровно по
    -- его левому краю, верхняя кромка сразу под его нижней кромкой. Габариты
    -- отдаёт само окно репорта (GRND_REP.winX/winW/winY/winH), поэтому полоса
    -- едет за ним; если окно ещё ни разу не рисовалось — берём его штатные
    -- размеры (ширина 600, по центру экрана).
    local R = _G.GRND_REP
    local repX, repW, repBottom
    if type(R) == "table" then
        repX = tonumber(R.winX)
        repW = tonumber(R.winW)
        local repY, repH = tonumber(R.winY), tonumber(R.winH)
        if repY and repH and repH > 0 then repBottom = repY + repH end
    end
    if not repW or repW <= 0 then repW = 600 end
    repW = math.max(240, math.min(repW, resX - 40))
    if not repX then repX = math.floor((resX - repW) / 2) end

    -- v1.19.13: ширина полосы — НЕ БОЛЬШЕ окна репорта. Раньше она разъезжалась
    -- вширь (до 920 px) и вылезала за края окна; теперь всё, что не влезло в ряд,
    -- переносится на следующий — полоса растёт ВНИЗ новыми рядами кнопок.
    local maxW = math.min(920, math.max(240, resX - 80), repW)
    local rows, contentW = pickerLayout(ctx, maxW - PICK_PADX * 2)
    local rowsH = math.max(rowH, #rows * rowH - PICK_GAP)

    -- v1.19.12: высота НЕ ограничена габаритами окна репорта: предел один —
    -- нижний край экрана, дальше строки уходят в прокрутку колесом.
    local minH = PICK_PADY * 2 + rowH      -- ниже одного ряда полоса не сжимается
    local y
    if repBottom then
        y = repBottom + PICK_ATTACH        -- сразу под нижней кромкой окна репорта
    else
        y = math.floor(resY * 0.62)        -- окно репорта ещё не рисовалось
    end
    y = math.max(16, math.min(resY - minH - PICK_SCREEN_GAP, y))

    -- ряды кнопок: от верхней кромки до нижнего края экрана помещается всё, что влезло
    local maxViewH = math.max(rowH, math.floor(resY - y - PICK_SCREEN_GAP) - PICK_PADY * 2)
    local viewH = math.min(rowsH, maxViewH)
    -- v1.19.18: ширина — ровно по кнопкам (плюс поля карточки). Раньше снизу
    -- держался минимум 184 px, и у полосы с одним-двумя шаблонами справа
    -- оставалась пустая полоса.
    local W = math.max(96, math.min(maxW, contentW + PICK_PADX * 2))
    local H = PICK_PADY + viewH + PICK_PADY
    local x = math.max(10, math.min(math.max(10, resX - W - 10), repX))

    pcall(im.SetNextWindowPos, im.ImVec2(x, y), ctx.always or 2)
    pcall(im.SetNextWindowSize, im.ImVec2(W, H), ctx.always or 2)
    if QR.pickFocus and im.SetNextWindowFocus then pcall(im.SetNextWindowFocus) end

    local flags = ctx.wf("NoTitleBar", "NoResize", "NoMove", "NoScrollbar",
        "NoCollapse", "NoScrollWithMouse", "NoSavedSettings")
    local nStyle, nCol = 0, 0
    if ctx.pushVarF and im.StyleVar and im.StyleVar.WindowRounding then
        if ctx.pushVarF(im.StyleVar.WindowRounding, 12) then nStyle = nStyle + 1 end
    end
    if ctx.pushVarV2 and im.StyleVar and im.StyleVar.WindowPadding then
        if ctx.pushVarV2(im.StyleVar.WindowPadding, 0, 0) then nStyle = nStyle + 1 end
    end
    if ctx.pushCol and im.Col then
        if im.Col.WindowBg and ctx.pushCol(im.Col.WindowBg, ctx.rgba(0, 0, 0, 0)) then nCol = nCol + 1 end
        if im.Col.Border and ctx.pushCol(im.Col.Border, ctx.rgba(0, 0, 0, 0)) then nCol = nCol + 1 end
    end

    local drawn = false
    if ctx.begin("##grnd_qr_picker", flags) then
        drawn = true
        QR.pickFocus = false
        local pos = im.GetWindowPos()
        local dl = im.GetWindowDrawList()
        local function at(dx, dy) return im.ImVec2(pos.x + dx, pos.y + dy) end
        local function box(bx, by, bw, bh, col, r)
            ctx.roundRect(dl, at(bx, by), at(bx + bw, by + bh), col, r or 0)
        end
        local function frame(bx, by, bw, bh, col, r)
            if dl.AddRect then
                pcall(dl.AddRect, dl, at(bx + 0.5, by + 0.5),
                    at(bx + bw - 0.5, by + bh - 0.5), col, r or 0, 0, 1)
            end
        end
        local function text(tx, ty, str, col, sc)
            ctx.uiText(tx, ty, str, col, sc)
        end

        -- карточка: тень, фон, рамка, акцентная полоска сверху
        box(4, 5, W - 4, H - 5, ctx.col32(0, 0, 0, 90), 12)
        box(0, 0, W, H, ctx.col32(12, 13, 19, 250), 12)
        frame(0, 0, W, H, ctx.col32(255, 255, 255, 30), 12)
        -- # v1.19.09: акцентная полоска у верхней кромки убрана (просьба заказчика)

        -- колесо мыши: шаблонов может быть много, полоса остаётся низкой
        local mx, my = mouse(im)
        local maxScroll = math.max(0, rowsH - viewH)
        QR.pickScroll = scrollWheel(im, mx, my, x + PICK_PADX, y + PICK_PADY,
            W - PICK_PADX * 2, viewH, tonumber(QR.pickScroll) or 0, maxScroll, 42)
        local scroll = math.max(0, math.min(maxScroll, tonumber(QR.pickScroll) or 0))

        local clip = false
        if dl.PushClipRect then
            clip = pcall(dl.PushClipRect, dl, at(PICK_PADX - 4, PICK_PADY - 3),
                at(W - PICK_PADX + 4, PICK_PADY + viewH + 3), true)
        end

        local hoverIt, chooseIt = nil, nil
        local firstRow = math.max(1, math.floor(scroll / rowH))
        for r = firstRow, #rows do
            local ry = PICK_PADY + (r - 1) * rowH - scroll
            if ry >= PICK_PADY + viewH then break end
            local bx = PICK_PADX
            for i = 1, #rows[r] do
                local cell = rows[r][i]
                -- клик только по ВИДИМОЙ части кнопки: виджеты ImGui клипом
                -- не режем (im-клип ломал текст — см. v1.19.02)
                local top = math.max(ry, PICK_PADY)
                local bottom = math.min(ry + PICK_BH, PICK_PADY + viewH)
                if bottom - top > 8 then
                    im.SetCursorPos(im.ImVec2(bx, top))
                    local clicked = im.InvisibleButton("##grnd_qr_q_" .. tostring(cell.it.id),
                        im.ImVec2(cell.w, bottom - top)) and true or false
                    local hov = (im.IsItemHovered and im.IsItemHovered()) or false
                    local act = (im.IsItemActive and im.IsItemActive()) or false
                    -- v1.19.06: спокойная кнопка видна и без наведения
                    local bg = act and ctx.col32(acC[1], acC[2], acC[3], 62)
                        or (hov and ctx.col32(acC[1], acC[2], acC[3], 38)
                            or ctx.col32(255, 255, 255, 24))
                    local bd = (hov or act) and ctx.col32(acC[1], acC[2], acC[3], 155)
                        or ctx.col32(255, 255, 255, 46)
                    box(bx, ry, cell.w, PICK_BH, bg, 7)
                    frame(bx, ry, cell.w, PICK_BH, bd, 7)
                    if hov or act then
                        box(bx, ry + 5, 2, PICK_BH - 10, ctx.col32(acC[1], acC[2], acC[3], 255), 1)
                    end
                    local shown, lw = fitW(cell.label, cell.w - 18, ctx.drawnW, 0.94)
                    if not lw or lw <= 0 then lw = utf8Len(shown) * 7 * 0.94 end
                    text(bx + math.max(7, (cell.w - lw) / 2),
                        ry + (PICK_BH - lineH(ctx, 0.94)) / 2, shown,
                        ctx.col32(250, 248, 255, 255), 0.94)
                    if hov then hoverIt = cell.it end
                    if clicked then chooseIt = cell.it end
                end
                bx = bx + cell.w + PICK_GAP
            end
        end
        if clip and dl.PopClipRect then pcall(dl.PopClipRect, dl) end

        -- тонкая полоса прокрутки у правого края
        if maxScroll > 0.5 then
            box(W - 6, PICK_PADY, 3, viewH, ctx.col32(255, 255, 255, 18), 2)
            local barH = math.max(16, viewH * (viewH / rowsH))
            local barY = PICK_PADY + (scroll / maxScroll) * (viewH - barH)
            box(W - 6, barY, 3, barH, ctx.col32(acC[1], acC[2], acC[3], 200), 2)
        end

        -- v1.19.12: строки-подсказки под кнопками ("клик — отправить ·
        -- ESC — закрыть") больше нет — полоса держит только кнопки.
        -- Полный текст шаблона под курсором показываем всплывающей подсказкой:
        -- высота полосы от наведения не меняется.
        if hoverIt and type(im.SetTooltip) == "function" then
            pcall(im.SetTooltip, oneLine(hoverIt.text or ""))
        end

        if chooseIt then QR.choose(chooseIt) end
    end

    if ctx.popCol and nCol > 0 then ctx.popCol(nCol) end
    if ctx.popVar and nStyle > 0 then ctx.popVar(nStyle) end
    return drawn
end

_G.grndQrPickerDraw = function(ctx)
    local ok, res = pcall(pickerDraw, ctx)
    if ok then return res end
    QR.drawErr = tostring(res)
    print("{FF6666}[GRND]{FFFFFF} быстрые ответы: " .. tostring(res))
    return false
end
-- =====================================================================
--  ШАБЛОНЫ НАКАЗАНИЙ (v1.19.16) — вкладка «Репорт» → «Наказания»
-- =====================================================================
--  Настройка — как у шаблонов ответа, плюс своё:
--    * селектор команды наказания (/ban, /mute, /rmute, /jail, /kick, /warn)
--      с выпадающим списком;
--    * «Время» появляется только у команд со сроком (бан — дни, мут — минуты),
--      «Причина» — у команд, которым она нужна;
--    * кнопка «Наказание» в окне репорта открывает ТАКУЮ ЖЕ полосу, как
--      «Быстрые ответы», только по центру окна репорта;
--    * боевой режим: игроку уходит «Ответ на репорт», следом — команда
--      наказания как есть.
--  Локальные имена живут в do-блоке: у Lua в функции не больше 200 активных
--  локальных переменных, а модуль и без того большой (см. шапку модуля).
-- =====================================================================
do
    -- Команды наказаний для селектора. time — нужен срок, reason — причина,
    -- unit — как подписывать поле «Время».
    -- v1.19.17: список сокращён до команд со сроком — /jail, /warn и /kick
    -- убраны по просьбе заказчика. У всех трёх есть и время, и причина.
    local punCmds = {
        { id = "ban",   time = true,  unit = "дней",  reason = true },
        { id = "mute",  time = true,  unit = "минут", reason = true },
        { id = "rmute", time = true,  unit = "минут", reason = true },
    }
    local punById = {}
    for i = 1, #punCmds do punById[punCmds[i].id] = punCmds[i] end
    QR.punCmds = punCmds          -- список для интерфейса и стендов

    function QR.punDef(id)
        return punById[tostring(id or ""):lower()]
    end

    -- Файл шаблонов наказаний лежит рядом с файлом шаблонов ответов
    -- (секция reportPunish в config.json — см. GRND_CONFIG.sources).
    function QR.punPath()
        local base = tostring(QR.path() or "")
        local replaced = base:gsub("grnd_repquick%.cfg$", "grnd_reppunish.cfg")
        if replaced ~= base then return replaced end
        local dir = base:match("^(.*[/\\])")
        if dir then return dir .. "grnd_reppunish.cfg" end
        return "grnd_reppunish.cfg"
    end

    local unitShort = { ["дней"] = "д", ["минут"] = "мин" }

    -- Строка-подпись для списка: «/mute · 60 мин · флуд».
    function QR.punPreview(it)
        if type(it) ~= "table" then return "" end
        local def = QR.punDef(it.cmd)
        if not def then return "команда не выбрана" end
        local out = "/" .. def.id
        if def.time and trim(it.time or "") ~= "" then
            out = out .. " · " .. trim(it.time) .. " " .. (unitShort[def.unit or ""] or (def.unit or ""))
        end
        if def.reason and trim(it.reason or "") ~= "" then
            out = out .. " · " .. oneLine(it.reason)
        end
        return out
    end

    -- ---------- список наказаний: хранение ----------

    function QR.punNormalize()
        local P = QR.pun
        if type(P.items) ~= "table" then P.items = {} end
        local seen, out, maxId = {}, {}, 0
        for i = 1, #P.items do
            local it = P.items[i]
            if type(it) == "table" then
                local id = math.floor(tonumber(it.id) or 0)
                if id <= 0 or seen[id] then
                    id = 0
                    repeat id = id + 1 until not seen[id]
                end
                local cmd = tostring(it.cmd or ""):lower():gsub("[^%a]", "")
                if punById[cmd] then           -- чужая команда в шаблон не попадает
                    local name = clampText(trim(utf(it.name or "")), MAX_NAME)
                    local text = clampText(cleanText(utf(it.text or "")), MAX_TEXT)
                    local time = clampText((trim(utf(it.time or "")):gsub("%D", "")), MAX_PTIME)
                    local reason = clampText(oneLine(utf(it.reason or "")), MAX_PREASON)
                    if name == "" then name = utf8Cut(QR.punPreview({ cmd = cmd, time = time, reason = reason }), 28) end
                    if name == "" then name = "/" .. cmd end
                    seen[id] = true
                    if id > maxId then maxId = id end
                    out[#out + 1] = { id = id, name = name, text = text,
                                      cmd = cmd, time = time, reason = reason }
                end
            end
        end
        P.items = out
        P.nextId = math.max(math.floor(tonumber(P.nextId) or 1), maxId + 1)
        if P.selId and not seen[math.floor(tonumber(P.selId) or 0)] then P.selId = nil end
        return out
    end

    function QR.punLoad()
        local P = QR.pun
        if P.loaded then return true end
        P.loaded = true
        local items, nextId = {}, nil
        local ok, f = pcall(GRND_CONFIG.open, QR.punPath(), "r")
        if ok and f then
            local cur = nil
            for line in f:lines() do
                line = tostring(line or "")
                if line == "---" then
                    cur = {}
                    items[#items + 1] = cur
                else
                    local k, v = line:match("^([%w_]+)=(.*)$")
                    if k then
                        if cur then
                            if k == "id" then cur.id = tonumber(v)
                            elseif k == "name" then cur.name = unesc(v)
                            elseif k == "text" then cur.text = unesc(v)
                            elseif k == "cmd" then cur.cmd = v
                            elseif k == "time" then cur.time = v
                            elseif k == "reason" then cur.reason = v end
                        elseif k == "nextId" then nextId = tonumber(v) end
                    end
                end
            end
            pcall(f.close, f)
        end
        P.items = items
        if nextId then P.nextId = nextId end
        QR.punNormalize()
        return true
    end

    function QR.punEnsure()
        local P = QR.pun
        if not P.loaded then pcall(QR.punLoad) end
        if type(P.items) ~= "table" then pcall(QR.punNormalize) end
        return P
    end

    function QR.punSave()
        local P = QR.pun
        QR.punNormalize()
        local ok, f = pcall(GRND_CONFIG.open, QR.punPath(), "w")
        if not ok or not f then return false end
        local escv = esc
        f:write("nextId=" .. tostring(P.nextId or 1) .. "\n")
        for i = 1, #P.items do
            local it = P.items[i]
            f:write("---\n")
            f:write("id=" .. tostring(it.id or 0) .. "\n")
            f:write("name=" .. escv(tostring(it.name or "")) .. "\n")
            f:write("text=" .. escv(tostring(it.text or "")) .. "\n")
            f:write("cmd=" .. tostring(it.cmd or "") .. "\n")
            f:write("time=" .. tostring(it.time or "") .. "\n")
            f:write("reason=" .. tostring(it.reason or "") .. "\n")
        end
        pcall(f.close, f)
        if GRND_CONFIG and type(GRND_CONFIG.flush) == "function" then
            pcall(GRND_CONFIG.flush)
        end
        return true
    end

    -- ---------- список наказаний: операции ----------

    function QR.punById(id)
        local P = QR.pun
        id = math.floor(tonumber(id) or 0)
        if type(P.items) ~= "table" then return nil, nil end
        for i = 1, #P.items do
            if P.items[i].id == id then return P.items[i], i end
        end
        return nil, nil
    end

    function QR.punCount()
        local P = QR.pun
        return (type(P.items) == "table") and #P.items or 0
    end

    function QR.punAdd(name, text, cmd, time, reason)
        local P = QR.pun
        QR.punEnsure()
        local id = math.max(1, math.floor(tonumber(P.nextId) or 1))
        P.nextId = id + 1
        local it = { id = id, cmd = tostring(cmd or ""):lower(), time = tostring(time or ""),
                     reason = tostring(reason or ""), name = name, text = text }
        P.items[#P.items + 1] = it
        QR.punNormalize()
        return QR.punById(id)
    end

    function QR.punUpdate(id, name, text, cmd, time, reason)
        local it = QR.punById(id)
        if not it then return false end
        it.name, it.text = name, text
        it.cmd, it.time, it.reason = tostring(cmd or ""):lower(), tostring(time or ""), tostring(reason or "")
        QR.punNormalize()
        return true
    end

    function QR.punRemove(id)
        local P = QR.pun
        id = math.floor(tonumber(id) or 0)
        if type(P.items) ~= "table" then return false end
        for i = 1, #P.items do
            if P.items[i].id == id then
                table.remove(P.items, i)
                if P.selId == id then P.selId, P.formKey = nil, nil end
                return true
            end
        end
        return false
    end

    function QR.punMove(id, dir)
        local P = QR.pun
        local it, idx = QR.punById(id)
        if not it then return false end
        local other = idx + ((dir or 0) < 0 and -1 or 1)
        if other < 1 or other > #P.items then return false end
        P.items[idx], P.items[other] = P.items[other], P.items[idx]
        return true
    end

    -- ---------- команда и отправка ----------

    -- «/mute 25 60 флуд» — с теми же подстановками, что и текст шаблона.
    function QR.punCommand(it, rep)
        if type(it) ~= "table" then return "" end
        local def = QR.punDef(it.cmd)
        if not def then return "" end
        rep = (type(rep) == "table") and rep or {}
        local pid = tostring(rep.id or rep.playerId or "")
        local out = "/" .. def.id .. " " .. pid
        if def.time then
            local t = tostring(it.time or ""):gsub("%D", "")
            if t ~= "" then out = out .. " " .. t end
        end
        if def.reason then
            local r = oneLine(QR.apply(it.reason or "", rep))
            if r ~= "" then out = out .. " " .. r end
        end
        return out
    end

    -- Выбор наказания из полосы: игроку уходит ответ, затем команда наказания.
    function QR.punChoose(it)
        if type(it) ~= "table" then return false end
        QR.punEnsure()
        local P = QR.pun
        local rep = QR.repInfo()
        local pid = tostring(rep.id or "")
        local label = tostring(it.name or ("/" .. tostring(it.cmd or "")))
        if pid:match("^%d+$") == nil then
            QR.toast("ID игрока не распознан — наказание не отправлено", "warn", 3)
            return false
        end
        local cmd = QR.punCommand(it, rep)
        if cmd == "" then
            QR.toast("В шаблоне не выбрана команда наказания", "warn", 3)
            return false
        end
        if utf8Len(cmd) > MAX_CHAT then
            cmd = utf8Cut(cmd, MAX_CHAT - 1) .. "…"
            QR.toast("Команда обрезана под лимит строки чата", "warn", 3)
        end
        local text = trim(QR.apply(it.text or "", rep))
        local mode = QR.modeOk(QR.mode)
        P.pickOpen, P.pickFocus = false, false

        local line = oneLine(text)

        -- «в поле ответа»: текст уходит в поле, команда наказания — ЖИВАЯ
        -- (v1.19.19: /n перед наказанием больше не подставляется)
        if mode == "input" then
            local R = _G.GRND_REP
            local buf = R and R.answer
            if buf and type(grndBinderWriteCBuf) == "function" and line ~= "" then
                pcall(grndBinderWriteCBuf, buf, 256, byteCut(line, MAX_BUF))
                if R then R.focused = false end
            end
            if QR.sendChat(cmd) then
                QR.toast("Наказание отправлено, текст — в поле ответа", "ok", 3.4)
                return true
            end
            QR.toast("Не удалось отправить команду наказания", "warn", 3)
            return false
        end

        -- v1.19.19: сначала игроку уходит ОТВЕТ штатной командой /ans ID текст,
        -- и только следом — сама команда наказания, уже БЕЗ /n. Обе строки
        -- ставим в одну очередь репорта (grndRepQueue): она отправляет по одной
        -- с паузой, поэтому ответ гарантированно уходит ПЕРВЫМ, а сервер не
        -- проглатывает вторую команду, пришедшую в том же кадре.
        if line ~= "" and type(grndRepAnswer) == "function" then
            pcall(grndRepAnswer, pid, line)
        end
        -- v1.19.21: та же очередь, что у ответа игроку, и конвертация в CP1251
        -- (в причине наказания русский текст — уходил «закорючками»)
        local sent = QR.queueCmd(cmd)
        if sent then
            if line ~= "" then
                QR.toast("Ответ игроку /ans " .. pid .. " и наказание «"
                    .. utf8Cut(label, 20) .. "»", "ok", 3.4)
            else
                QR.toast("Наказание «" .. utf8Cut(label, 20) .. "» по ID " .. pid, "ok", 3)
            end
            QR.closeReport()
            return true
        end
        QR.toast("Не удалось отправить команду наказания", "warn", 3)
        return false
    end

    -- ---------- полоса выбора наказания (окно репорта) ----------

    function QR.openPunPicker()
        QR.punEnsure()
        local P = QR.pun
        if QR.punCount() == 0 then
            P.pickOpen, P.pickFocus = false, false
            QR.toast("Шаблонов наказаний нет — создайте их в меню «Репорт», вкладка «Наказания»", "warn", 3.6)
            return false
        end
        QR.pickOpen, QR.pickFocus = false, false    -- полосы не показываем вместе
        P.pickOpen, P.pickFocus = true, true
        P.pickScroll = 0
        return true
    end

    function QR.togglePunPicker()
        if QR.pun.pickOpen then
            QR.closePunPicker()
        else
            QR.openPunPicker()
        end
    end

    function QR.closePunPicker()
        QR.pun.pickOpen, QR.pun.pickFocus = false, false
    end

    local function punPickerDraw(ctx)
        if type(ctx) ~= "table" then return false end
        local im = ctx.im
        if not (im and ctx.begin and ctx.uiText and ctx.roundRect and ctx.col32 and ctx.rgba) then
            return false
        end
        local P = QR.pun
        if not P.pickOpen then return false end
        -- окно репорта закрылось (ESC, ответ, действие) — полосу убираем
        if not (_G.GRND_REP and _G.GRND_REP.open) then
            P.pickOpen, P.pickFocus = false, false
            return false
        end
        QR.punEnsure()
        if QR.punCount() == 0 then
            P.pickOpen, P.pickFocus = false, false
            QR.toast("Шаблонов наказаний нет — создайте их в меню «Репорт», вкладка «Наказания»", "warn", 3.6)
            return false
        end
        P.left = (P.left or 0) + 1
        local TH = theme()
        local acC = TH.accent or { 164, 112, 224, 255 }

        local resX, resY = getScreenResolution()
        resX, resY = tonumber(resX) or 1920, tonumber(resY) or 1080
        local rowH = PICK_BH + PICK_GAP
        local R = _G.GRND_REP
        local repX, repW, repBottom
        if type(R) == "table" then
            repX, repW = tonumber(R.winX), tonumber(R.winW)
            local repY, repH = tonumber(R.winY), tonumber(R.winH)
            if repY and repH and repH > 0 then repBottom = repY + repH end
        end
        if not repW or repW <= 0 then repW = 600 end
        repW = math.max(240, math.min(repW, resX - 40))
        if not repX then repX = math.floor((resX - repW) / 2) end

        -- ширина — не больше окна репорта: лишние кнопки переносятся вниз
        local maxW = math.min(920, math.max(240, resX - 80), repW)
        local rows, contentW = pickerLayoutItems(ctx, maxW - PICK_PADX * 2, P.items)
        local rowsH = math.max(rowH, #rows * rowH - PICK_GAP)
        local minH = PICK_PADY * 2 + rowH
        local y
        if repBottom then
            y = repBottom + PICK_ATTACH
        else
            y = math.floor(resY * 0.62)
        end
        y = math.max(16, math.min(resY - minH - PICK_SCREEN_GAP, y))
        local maxViewH = math.max(rowH, math.floor(resY - y - PICK_SCREEN_GAP) - PICK_PADY * 2)
        local viewH = math.min(rowsH, maxViewH)
        -- v1.19.18: как и у быстрых ответов — ширина ровно по кнопкам
        local W = math.max(96, math.min(maxW, contentW + PICK_PADX * 2))
        local H = PICK_PADY + viewH + PICK_PADY
        -- v1.19.16: полоса наказаний — ПОСРЕДИНЕ окна репорта (быстрые ответы
        -- прижаты к его левому краю, а эта центрируется).
        local x = repX + math.floor((repW - W) / 2)
        x = math.max(10, math.min(math.max(10, resX - W - 10), x))

        pcall(im.SetNextWindowPos, im.ImVec2(x, y), ctx.always or 2)
        pcall(im.SetNextWindowSize, im.ImVec2(W, H), ctx.always or 2)
        if P.pickFocus and im.SetNextWindowFocus then pcall(im.SetNextWindowFocus) end

        local flags = ctx.wf("NoTitleBar", "NoResize", "NoMove", "NoScrollbar",
            "NoCollapse", "NoScrollWithMouse", "NoSavedSettings")
        local nStyle, nCol = 0, 0
        if ctx.pushVarF and im.StyleVar and im.StyleVar.WindowRounding then
            if ctx.pushVarF(im.StyleVar.WindowRounding, 12) then nStyle = nStyle + 1 end
        end
        if ctx.pushVarV2 and im.StyleVar and im.StyleVar.WindowPadding then
            if ctx.pushVarV2(im.StyleVar.WindowPadding, 0, 0) then nStyle = nStyle + 1 end
        end
        if ctx.pushCol and im.Col then
            if im.Col.WindowBg and ctx.pushCol(im.Col.WindowBg, ctx.rgba(0, 0, 0, 0)) then nCol = nCol + 1 end
            if im.Col.Border and ctx.pushCol(im.Col.Border, ctx.rgba(0, 0, 0, 0)) then nCol = nCol + 1 end
        end

        local drawn = false
        if ctx.begin("##grnd_qr_pun_picker", flags) then
            drawn = true
            P.pickFocus = false
            local pos = im.GetWindowPos()
            local dl = im.GetWindowDrawList()
            local function at(dx, dy) return im.ImVec2(pos.x + dx, pos.y + dy) end
            local function box(bx, by, bw, bh, col, r)
                ctx.roundRect(dl, at(bx, by), at(bx + bw, by + bh), col, r or 0)
            end
            local function frame(bx, by, bw, bh, col, r)
                if dl.AddRect then
                    pcall(dl.AddRect, dl, at(bx + 0.5, by + 0.5),
                        at(bx + bw - 0.5, by + bh - 0.5), col, r or 0, 0, 1)
                end
            end
            local function text(tx, ty, str, col, sc)
                ctx.uiText(tx, ty, str, col, sc)
            end

            -- карточка: тень, фон, рамка (акцентной полоски сверху нет — v1.19.09)
            box(4, 5, W - 4, H - 5, ctx.col32(0, 0, 0, 90), 12)
            box(0, 0, W, H, ctx.col32(12, 13, 19, 250), 12)
            frame(0, 0, W, H, ctx.col32(255, 255, 255, 30), 12)

            local mx, my = mouse(im)
            local maxScroll = math.max(0, rowsH - viewH)
            P.pickScroll = scrollWheel(im, mx, my, x + PICK_PADX, y + PICK_PADY,
                W - PICK_PADX * 2, viewH, tonumber(P.pickScroll) or 0, maxScroll, 42)
            local scroll = math.max(0, math.min(maxScroll, tonumber(P.pickScroll) or 0))

            local clip = false
            if dl.PushClipRect then
                clip = pcall(dl.PushClipRect, dl, at(PICK_PADX - 4, PICK_PADY - 3),
                    at(W - PICK_PADX + 4, PICK_PADY + viewH + 3), true)
            end

            local hoverIt, chooseIt = nil, nil
            local firstRow = math.max(1, math.floor(scroll / rowH))
            for r = firstRow, #rows do
                local ry = PICK_PADY + (r - 1) * rowH - scroll
                if ry >= PICK_PADY + viewH then break end
                local bx = PICK_PADX
                for i = 1, #rows[r] do
                    local cell = rows[r][i]
                    local top = math.max(ry, PICK_PADY)
                    local bottom = math.min(ry + PICK_BH, PICK_PADY + viewH)
                    if bottom - top > 8 then
                        im.SetCursorPos(im.ImVec2(bx, top))
                        local clicked = im.InvisibleButton("##grnd_qr_pun_q_" .. tostring(cell.it.id),
                            im.ImVec2(cell.w, bottom - top)) and true or false
                        local hov = (im.IsItemHovered and im.IsItemHovered()) or false
                        local act = (im.IsItemActive and im.IsItemActive()) or false
                        local bg = act and ctx.col32(acC[1], acC[2], acC[3], 62)
                            or (hov and ctx.col32(acC[1], acC[2], acC[3], 38)
                                or ctx.col32(255, 255, 255, 24))
                        local bd = (hov or act) and ctx.col32(acC[1], acC[2], acC[3], 155)
                            or ctx.col32(255, 255, 255, 46)
                        box(bx, ry, cell.w, PICK_BH, bg, 7)
                        frame(bx, ry, cell.w, PICK_BH, bd, 7)
                        if hov or act then
                            box(bx, ry + 5, 2, PICK_BH - 10, ctx.col32(acC[1], acC[2], acC[3], 255), 1)
                        end
                        local shown, lw = fitW(cell.label, cell.w - 18, ctx.drawnW, 0.94)
                        if not lw or lw <= 0 then lw = utf8Len(shown) * 7 * 0.94 end
                        text(bx + math.max(7, (cell.w - lw) / 2),
                            ry + (PICK_BH - lineH(ctx, 0.94)) / 2, shown,
                            ctx.col32(250, 248, 255, 255), 0.94)
                        if hov then hoverIt = cell.it end
                        if clicked then chooseIt = cell.it end
                    end
                    bx = bx + cell.w + PICK_GAP
                end
            end
            if clip and dl.PopClipRect then pcall(dl.PopClipRect, dl) end

            if maxScroll > 0.5 then
                box(W - 6, PICK_PADY, 3, viewH, ctx.col32(255, 255, 255, 18), 2)
                local barH = math.max(16, viewH * (viewH / rowsH))
                local barY = PICK_PADY + (scroll / maxScroll) * (viewH - barH)
                box(W - 6, barY, 3, barH, ctx.col32(acC[1], acC[2], acC[3], 200), 2)
            end

            -- под кнопками строк нет (как у быстрых ответов): готовая команда
            -- показывается всплывающей подсказкой — её и проверяем в стенде
            if hoverIt and type(im.SetTooltip) == "function" then
                local line = QR.punCommand(hoverIt, QR.repInfo())
                local body = oneLine(hoverIt.text or "")
                if body ~= "" then line = line .. " · " .. utf8Cut(body, 40) end
                pcall(im.SetTooltip, line)
            end

            if chooseIt then QR.punChoose(chooseIt) end
        end

        if ctx.popCol and nCol > 0 then ctx.popCol(nCol) end
        if ctx.popVar and nStyle > 0 then ctx.popVar(nStyle) end
        return drawn
    end

    _G.grndQrPunPickerDraw = function(ctx)
        local ok, res = pcall(punPickerDraw, ctx)
        if ok then return res end
        QR.punDrawErr = tostring(res)
        print("{FF6666}[GRND]{FFFFFF} шаблоны наказаний: " .. tostring(res))
        return false
    end
end

-- =====================================================================
--  РАЗДЕЛ НАСТРОЕК: меню → «Репорт» → «Ответы на репорт»
-- =====================================================================

-- Смена источника формы (выбран другой шаблон / создание нового) —
-- переписываем буферы полей из модели.
local function formSync()
    local it = (not QR.isNew) and QR.selId and QR.byId(QR.selId) or nil
    local key = QR.isNew and "new" or (it and ("id:" .. tostring(it.id)) or "none")
    if QR.formKey ~= key then
        QR.formKey = key
        bufReload("editName")
        bufReload("editText")
    end
    return it
end

local function settingsList(ctx, x, y, w, h)
    local TH = theme()
    local im = ctx.im
    ctx.roundRect(ctx.dl, ctx.at(x, y), ctx.at(x + w, y + h), ctx.col32(255, 255, 255, 10), 10)
    if ctx.dl.AddRect then
        pcall(ctx.dl.AddRect, ctx.dl, ctx.at(x + 0.5, y + 0.5), ctx.at(x + w - 0.5, y + h - 0.5),
            ctx.col32(255, 255, 255, 22), 10, 0, 1)
    end
    local headH = 32
    ctx.uiText(x + 12, y + 9, "Список шаблонов",
        ctx.col32(TH.textHi[1], TH.textHi[2], TH.textHi[3], 255), 0.9)
    local q = trim(lower(QR.filter))
    local list = {}
    for i = 1, #QR.items do
        local it = QR.items[i]
        if q == "" or lower(it.name):find(q, 1, true) or lower(it.text):find(q, 1, true) then
            list[#list + 1] = it
        end
    end
    local cnt = tostring(#list)
    if q ~= "" then cnt = cnt .. " / " .. tostring(QR.count()) end
    local cw = 30
    if type(ctx.drawnW) == "function" then
        local ok, v = pcall(ctx.drawnW, cnt, 0.82)
        if ok and type(v) == "number" then cw = v end
    end
    ctx.roundRect(ctx.dl, ctx.at(x + w - 14 - cw - 8, y + 8), ctx.at(x + w - 14, y + 26),
        ctx.col32(TH.accent[1], TH.accent[2], TH.accent[3], 34), 9)
    ctx.uiText(x + w - 14 - cw - 4, y + 10, cnt,
        ctx.col32(TH.accent[1], TH.accent[2], TH.accent[3], 255), 0.82)

    local listY = y + headH
    local listH = h - headH - 6
    if listH < 40 then return end
    local rowH = 48
    local maxScroll = math.max(0, #list * rowH - listH)
    local mx, my = mouse(im)
    local wp = im.GetWindowPos()
    if wp and wp.x then
        QR.listScroll = scrollWheel(im, mx, my, wp.x + x + 2, wp.y + listY, w - 4, listH,
            tonumber(QR.listScroll) or 0, maxScroll, 42)
    end
    QR.listScroll = math.max(0, math.min(maxScroll, tonumber(QR.listScroll) or 0))
    local clip = false
    if ctx.dl.PushClipRect then
        clip = pcall(ctx.dl.PushClipRect, ctx.dl, ctx.at(x + 2, listY), ctx.at(x + w - 2, listY + listH), true)
    end
    -- Клип только у списка отрисовки (см. комментарий в модуле): im-клип
    -- сдвигает window->ClipRect и «съедает» ВЕСЬ текст после него — именно
    -- так пропал редактор шаблона (v1.19.01), см. v1.19.02.
    if #list == 0 then
        ctx.uiText(x + 14, listY + 10,
            (QR.count() == 0) and "Пока пусто — нажмите «+ Новый шаблон»" or "Ничего не найдено",
            ctx.col32(TH.textDim[1], TH.textDim[2], TH.textDim[3], 255), 0.86)
    end
    local ac = TH.accent
    local first = math.floor((QR.listScroll or 0) / rowH)
    for i = first + 1, math.min(#list, first + math.ceil(listH / rowH) + 1) do
        local it = list[i]
        local iy = listY + (i - 1) * rowH - (QR.listScroll or 0)
        if iy + rowH >= listY and iy <= listY + listH then
            local sel = (QR.selId == it.id) and not QR.isNew
            local fully = (iy >= listY - 0.5) and (iy + rowH <= listY + listH + 0.5)
            -- «тело» строки — кнопка только на видимой части (в список
            -- отрисовки мы упираемся клипом, а виджеты ImGui клипом не режем)
            local wy = math.max(iy + 2, listY + 1)
            local wh = math.min(iy + rowH - 4, listY + listH - 1) - wy
            local clicked = false
            if wh > 6 then
                im.SetCursorPos(im.ImVec2(x + 6, wy))
                clicked = im.InvisibleButton("##grnd_qr_row_" .. tostring(it.id),
                    im.ImVec2(w - 70, wh)) and true or false
            end
            local hov = (im.IsItemHovered and im.IsItemHovered()) or false
            ctx.roundRect(ctx.dl, ctx.at(x + 6, iy + 2), ctx.at(x + w - 6, iy + rowH - 4),
                sel and ctx.col32(ac[1], ac[2], ac[3], 32)
                    or (hov and ctx.col32(255, 255, 255, 13) or ctx.col32(255, 255, 255, 5)), 8)
            if sel then
                ctx.roundRect(ctx.dl, ctx.at(x + 6, iy + 9), ctx.at(x + 9, iy + rowH - 11),
                    ctx.col32(ac[1], ac[2], ac[3], 255), 2)
            end
            local tW = w - 12 - 52 - 18
            ctx.uiText(x + 18, iy + 7, fit(it.name or "", tW, ctx.drawnW, 0.94),
                ctx.col32(TH.textHi[1], TH.textHi[2], TH.textHi[3], 255), 0.94)
            ctx.uiText(x + 18, iy + 25, fit(oneLine(it.text or ""), tW, ctx.drawnW, 0.78),
                ctx.col32(TH.textMuted[1], TH.textMuted[2], TH.textMuted[3], 255), 0.78)
            if clicked then
                QR.selId, QR.isNew, QR.delArm = it.id, false, nil
                QR.note = nil
            end
            -- Только порядок (стрелки фигурами: ▲▼ в шрифте нет). Кнопки
            -- «Удалить» в списке НЕТ: удаление — единственное место, редактор
            -- справа (иначе у одного шаблона было два разных «удалить»).
            -- Кнопки создаём лишь для полностью видимой строки.
            local bx = x + w - 12 - 48
            local by = iy + math.floor((rowH - 6 - 24) / 2) + 3
            if fully and button(ctx, "##grnd_qr_up_" .. tostring(it.id), bx, by, 22, 24, "",
                { muted = true, tri = "up" }) then
                QR.move(it.id, -1)
                pcall(QR.save)
            elseif not fully then
                tri(ctx.dl, ctx.at, bx + 11, iy + 20, 4, "up", ctx.col32(255, 255, 255, 60))
            end
            if fully and button(ctx, "##grnd_qr_dn_" .. tostring(it.id), bx + 26, by, 22, 24, "",
                { muted = true, tri = "down" }) then
                QR.move(it.id, 1)
                pcall(QR.save)
            elseif not fully then
                tri(ctx.dl, ctx.at, bx + 37, iy + 20, 4, "down", ctx.col32(255, 255, 255, 60))
            end
        end
    end
    if clip and ctx.dl.PopClipRect then pcall(ctx.dl.PopClipRect, ctx.dl) end
    if maxScroll > 0.5 then
        local trackX = x + w - 5
        ctx.roundRect(ctx.dl, ctx.at(trackX, listY), ctx.at(trackX + 3, listY + listH),
            ctx.col32(255, 255, 255, 18), 2)
        local barH = math.max(18, listH * (listH / (#list * rowH)))
        local barY = listY + ((QR.listScroll or 0) / maxScroll) * (listH - barH)
        ctx.roundRect(ctx.dl, ctx.at(trackX, barY), ctx.at(trackX + 3, barY + barH),
            ctx.col32(ac[1], ac[2], ac[3], 200), 2)
    end
end

local function settingsEditor(ctx, x, y, w, h)
    local TH = theme()
    local it = formSync()
    ctx.roundRect(ctx.dl, ctx.at(x, y), ctx.at(x + w, y + h), ctx.col32(255, 255, 255, 10), 10)
    if ctx.dl.AddRect then
        pcall(ctx.dl.AddRect, ctx.dl, ctx.at(x + 0.5, y + 0.5), ctx.at(x + w - 0.5, y + h - 0.5),
            ctx.col32(255, 255, 255, 22), 10, 0, 1)
    end
    local title = QR.isNew and "Новый шаблон" or "Редактор шаблона"
    ctx.uiText(x + 12, y + 9, title, ctx.col32(TH.textHi[1], TH.textHi[2], TH.textHi[3], 255), 0.9)
    if not it and not QR.isNew then
        local muted = ctx.col32(TH.textMuted[1], TH.textMuted[2], TH.textMuted[3], 255)
        local dim = ctx.col32(TH.textDim[1], TH.textDim[2], TH.textDim[3], 255)
        ctx.uiText(x + 12, y + 38, "Выберите шаблон слева", muted, 0.92)
        ctx.uiText(x + 12, y + 58, "или нажмите «+ Новый шаблон».", muted, 0.92)
        ctx.uiText(x + 12, y + 92, "Кнопка «Быстрые ответы» в окне репорта", dim, 0.82)
        ctx.uiText(x + 12, y + 108, "откроет этот список с поиском,", dim, 0.82)
        ctx.uiText(x + 12, y + 124, "клик по шаблону отправит текст.", dim, 0.82)
        return
    end
    local pad = 12
    local ix, iw = x + pad, w - pad * 2
    local yy = y + 32
    ctx.uiText(ix, yy, "Название", ctx.col32(TH.textDim[1], TH.textDim[2], TH.textDim[3], 255), 0.82)
    yy = yy + 17
    field(ctx, "##grnd_qr_edit_name", "editName", 64,
        ix, yy, iw, 28, "Например: Приветствие", false, it and it.name or "")
    yy = yy + 36
    ctx.uiText(ix, yy, "Текст ответа", ctx.col32(TH.textDim[1], TH.textDim[2], TH.textDim[3], 255), 0.82)
    yy = yy + 17
    local btnH, footH = 32, 12
    local textH = (y + h) - yy - btnH - footH - 10
    if textH < 56 then textH = 56 end
    field(ctx, "##grnd_qr_edit_text", "editText", 2048,
        ix, yy, iw, textH, "Текст, который уйдёт игроку…", true, it and it.text or "")
    yy = yy + textH + 5
    -- v1.19.14: строки «Переменные: {ник} · …» и внутренней заметки-подсказки
    -- («Нажмите «Точно удалить?»…» и пр.) внизу редактора больше нет — по
    -- просьбе заказчика. Все сообщения уходят обычными уведомлениями (тостами),
    -- а освободившееся место отдано полю «Текст ответа».

    local by = y + h - btnH - 6
    local bw1 = math.min(146, math.floor(iw * 0.4))
    if button(ctx, "##grnd_qr_save", ix, by, bw1, btnH, "Сохранить", { primary = true }) then
        local name = trim(bufText("editName"))
        local text = cleanText(bufText("editText"))
        if text == "" then
            QR.toast("Введите текст ответа", "warn", 2.6)
        else
            if QR.isNew then
                local created = QR.add(name, text)
                QR.isNew = false
                QR.selId = created and created.id or nil
                QR.formKey = nil
                formSync()
            else
                QR.update(QR.selId, name, text)
            end
            bufReload("editName")
            bufReload("editText")
            pcall(QR.save)
            QR.toast("Шаблон сохранён", "ok", 2.2)
        end
    end
    local bx = ix + bw1 + 8
    local bw2 = math.min(112, math.floor(iw * 0.28))
    if button(ctx, "##grnd_qr_cancel", bx, by, bw2, btnH, "Отмена", {}) then
        QR.isNew, QR.delArm, QR.formKey = false, nil, nil
        formSync()
        QR.toast("Изменения отменены", "ok", 2.0)
    end
    if not QR.isNew and it then
        local bx2 = bx + bw2 + 8
        local bw3 = iw - (bx2 - ix)
        if bw3 >= 90 then
            local label = (QR.delArm == it.id) and "Точно удалить?" or "Удалить"
            if button(ctx, "##grnd_qr_remove", bx2, by, bw3, btnH, label, { danger = true }) then
                if QR.delArm == it.id then
                    QR.remove(it.id)
                    QR.delArm, QR.formKey = nil, nil
                    formSync()
                    pcall(QR.save)
                    QR.toast("Шаблон удалён", "ok", 2.2)
                else
                    -- v1.19.14: подтверждение спрашивает сама кнопка («Точно
                    -- удалить?»), отдельной строки-подсказки в окне нет.
                    QR.delArm = it.id
                end
            end
        end
    end
end

local function settingsDraw(ctx)
    if type(ctx) ~= "table" then return false end
    local im = ctx.im
    if not (im and ctx.uiText and ctx.roundRect and ctx.col32 and ctx.rgba and ctx.at) then
        return false
    end
    local TH = theme()
    QR.ensure()
    local x, y, w, h = ctx.x, ctx.y, ctx.w, ctx.h
    if not (x and y and w and h) or w < 240 or h < 140 then return false end

    -- шапка: заголовок, счётчик, поиск, «Новый шаблон»
    ctx.uiText(x, y + 1, "Шаблоны быстрых ответов",
        ctx.col32(TH.textHi[1], TH.textHi[2], TH.textHi[3], 255), 1.0)
    local tw = 220
    if type(ctx.drawnW) == "function" then
        local ok, v = pcall(ctx.drawnW, "Шаблоны быстрых ответов", 1.0)
        if ok and type(v) == "number" then tw = v end
    end
    chip(ctx, x + tw + 10, y - 2, "шаблонов: " .. tostring(QR.count()))

    local newW = 148
    local searchW = math.min(190, math.max(118, math.floor(w * 0.24)))
    local searchX = x + w - newW - searchW - 10
    if searchX > x + tw + 110 then
        field(ctx, "##grnd_qr_search", "settingsSearch", 64,
            searchX, y - 3, searchW, 28, "Поиск…", false, QR.filter)
        QR.filter = bufText("settingsSearch")
    end
    if button(ctx, "##grnd_qr_new", x + w - newW, y - 4, newW, 30, "+ Новый шаблон",
        { primary = not QR.isNew }) then
        QR.isNew, QR.selId, QR.delArm = true, nil, nil
        QR.formKey = nil
        formSync()
        QR.toast("Заполните название и текст", "ok", 2.4)
    end

    -- (v1.19.01: строка «Отправка шаблона» убрана — режим хранится в конфиге,
    --  сейчас это боевой /ans игроку; «mode=input» вставляет текст в поле)

    -- список + редактор
    local yy = y + 34
    local gap = 14
    local listW = math.floor((w - gap) * 0.36)
    if listW < 200 then listW = 200 end
    if listW > 300 then listW = 300 end
    local contentH = (y + h) - yy
    if contentH < 120 then contentH = 120 end
    settingsList(ctx, x, yy, listW, contentH)
    settingsEditor(ctx, x + listW + gap, yy, w - listW - gap, contentH)
    return true
end

_G.grndQrSettingsDraw = function(ctx)
    local ok, res = pcall(settingsDraw, ctx)
    if ok then return res end
    QR.drawErr = tostring(res)
    print("{FF6666}[GRND]{FFFFFF} шаблоны ответов: " .. tostring(res))
    return false
end

-- =====================================================================
--  НАСТРОЙКА НАКАЗАНИЙ (v1.19.16): список слева, редактор справа
--  Редактор — как у шаблонов ответа, только «Ответ на репорт» ниже, есть
--  селектор команды наказания с выпадающим списком и, по команде, поля
--  «Время» и «Причина». Локальные имена — в do-блоке (лимит 200 локальных).
-- =====================================================================
do
    local PUN_TEXT_H = 68      -- «Ответ на репорт» — намеренно ниже, чем в ответах
    local PUN_ROW_H = 28       -- строка выпадающего списка команд
    local PUN_SEL_H = 28       -- высота селектора команды

    -- Пере-заполнение буферов формы при смене шаблона (аналог formSync).
    local function punFormSync()
        local P = QR.pun
        local it = (not P.isNew) and P.selId and QR.punById(P.selId) or nil
        local key = P.isNew and "new" or (it and ("id:" .. tostring(it.id)) or "none")
        if P.formKey ~= key then
            P.formKey = key
            bufReload("punName")
            bufReload("punText")
            bufReload("punTime")
            bufReload("punReason")
        end
        return it
    end

    -- Закрыть выпадающий список, если кликнули вне него (в игре есть «сырой»
    -- клик и позиция мыши; в стендах этих глобальных нет — тогда не закрываем).
    local function punOutsideClick(ddX, ddY, ddW, ddH, selY, selH)
        local alive = _G and _G.grndClickAlive
        if type(alive) ~= "function" then return false end
        local ok, hit = pcall(alive)
        if not (ok and hit) then return false end
        local M = _G and _G.GRND_MOUSE
        if type(M) ~= "table" then return false end
        local mx, my = tonumber(M.x) or -1, tonumber(M.y) or -1
        if mx >= ddX and mx <= ddX + ddW and my >= ddY and my <= ddY + ddH then return false end
        if mx >= ddX and mx <= ddX + ddW and my >= selY and my <= selY + selH then return false end
        return true
    end

    -- Список наказаний (левая колонка) — как список шаблонов ответа.
    local function punListDraw(ctx, x, y, w, h)
        local TH = theme()
        local im = ctx.im
        local P = QR.pun
        ctx.roundRect(ctx.dl, ctx.at(x, y), ctx.at(x + w, y + h), ctx.col32(255, 255, 255, 10), 10)
        if ctx.dl.AddRect then
            pcall(ctx.dl.AddRect, ctx.dl, ctx.at(x + 0.5, y + 0.5), ctx.at(x + w - 0.5, y + h - 0.5),
                ctx.col32(255, 255, 255, 22), 10, 0, 1)
        end
        local headH = 32
        ctx.uiText(x + 12, y + 9, "Список наказаний",
            ctx.col32(TH.textHi[1], TH.textHi[2], TH.textHi[3], 255), 0.9)
        local q = trim(lower(P.filter))
        local list = {}
        for i = 1, #P.items do
            local it = P.items[i]
            local hay = lower(tostring(it.name or "") .. " " .. tostring(it.cmd or "") .. " "
                .. tostring(it.reason or "") .. " " .. tostring(it.text or ""))
            if q == "" or hay:find(q, 1, true) then list[#list + 1] = it end
        end
        local cnt = tostring(#list)
        if q ~= "" then cnt = cnt .. " / " .. tostring(QR.punCount()) end
        local cw = 30
        if type(ctx.drawnW) == "function" then
            local ok, v = pcall(ctx.drawnW, cnt, 0.82)
            if ok and type(v) == "number" then cw = v end
        end
        ctx.roundRect(ctx.dl, ctx.at(x + w - 14 - cw - 8, y + 8), ctx.at(x + w - 14, y + 26),
            ctx.col32(TH.accent[1], TH.accent[2], TH.accent[3], 34), 9)
        ctx.uiText(x + w - 14 - cw - 4, y + 10, cnt,
            ctx.col32(TH.accent[1], TH.accent[2], TH.accent[3], 255), 0.82)

        local listY = y + headH
        local listH = h - headH - 6
        if listH < 40 then return end
        local rowH = 48
        local maxScroll = math.max(0, #list * rowH - listH)
        local mx, my = mouse(im)
        local wp = im.GetWindowPos()
        if wp and wp.x then
            P.listScroll = scrollWheel(im, mx, my, wp.x + x + 2, wp.y + listY, w - 4, listH,
                tonumber(P.listScroll) or 0, maxScroll, 42)
        end
        P.listScroll = math.max(0, math.min(maxScroll, tonumber(P.listScroll) or 0))
        local clip = false
        if ctx.dl.PushClipRect then
            clip = pcall(ctx.dl.PushClipRect, ctx.dl, ctx.at(x + 2, listY), ctx.at(x + w - 2, listY + listH), true)
        end
        if #list == 0 then
            ctx.uiText(x + 14, listY + 10,
                (QR.punCount() == 0) and "Пока пусто — нажмите «+ Новый шаблон»" or "Ничего не найдено",
                ctx.col32(TH.textDim[1], TH.textDim[2], TH.textDim[3], 255), 0.86)
        end
        local ac = TH.accent or { 164, 112, 224, 255 }
        for i = 1, #list do
            local it = list[i]
            local iy = listY + (i - 1) * rowH - (P.listScroll or 0)
            -- v1.19.19: раньше у ПЕРВОЙ строки (scroll = 0) условие
            -- iy >= listY + 1 не выполнялось — кнопки «вверх/вниз» рисовались,
            -- но не нажимались. Теперь полная видимость считается как у списка
            -- шаблонов ответа.
            local fully = (iy >= listY - 0.5) and (iy + rowH <= listY + listH + 0.5)
            if iy + rowH >= listY and iy <= listY + listH then
                local sel = (P.selId == it.id)
                -- клик — только по видимой части строки
                local wy = math.max(iy + 2, listY + 1)
                local wh = math.min(iy + rowH - 4, listY + listH - 1) - wy
                local clicked = false
                if wh > 6 then
                    im.SetCursorPos(im.ImVec2(x + 6, wy))
                    clicked = im.InvisibleButton("##grnd_qr_pun_row_" .. tostring(it.id),
                        im.ImVec2(w - 70, wh)) and true or false
                end
                local hov = (im.IsItemHovered and im.IsItemHovered()) or false
                ctx.roundRect(ctx.dl, ctx.at(x + 6, iy + 2), ctx.at(x + w - 6, iy + rowH - 4),
                    sel and ctx.col32(ac[1], ac[2], ac[3], 32)
                        or (hov and ctx.col32(255, 255, 255, 13) or ctx.col32(255, 255, 255, 5)), 8)
                if sel then
                    ctx.roundRect(ctx.dl, ctx.at(x + 6, iy + 9), ctx.at(x + 9, iy + rowH - 11),
                        ctx.col32(ac[1], ac[2], ac[3], 255), 2)
                end
                local tW = w - 12 - 52 - 18
                ctx.uiText(x + 18, iy + 7, fit(it.name or "", tW, ctx.drawnW, 0.94),
                    ctx.col32(TH.textHi[1], TH.textHi[2], TH.textHi[3], 255), 0.94)
                ctx.uiText(x + 18, iy + 25, fit(QR.punPreview(it), tW, ctx.drawnW, 0.78),
                    ctx.col32(TH.textMuted[1], TH.textMuted[2], TH.textMuted[3], 255), 0.78)
                if clicked then
                    P.selId, P.isNew, P.delArm = it.id, false, nil
                    P.comboOpen = false
                end
                -- порядок задаётся стрелками (фигурами: ▲▼ в шрифте может не быть).
                -- У первого шаблона «вверх» и у последнего «вниз» — неактивные
                -- стрелки (мёртвых кнопок нет).
                local _, pidx = QR.punById(it.id)
                local canUp = (pidx or 1) > 1
                local canDn = pidx ~= nil and pidx < QR.punCount()
                local bx = x + w - 12 - 48
                local by = iy + math.floor((rowH - 6 - 24) / 2) + 3
                if fully and canUp then
                    if button(ctx, "##grnd_qr_pun_up_" .. tostring(it.id), bx, by, 22, 24, "",
                        { muted = true, tri = "up" }) then
                        QR.punMove(it.id, -1)
                        pcall(QR.punSave)
                    end
                else
                    tri(ctx.dl, ctx.at, bx + 11, iy + 20, 4, "up",
                        ctx.col32(255, 255, 255, fully and 34 or 60))
                end
                if fully and canDn then
                    if button(ctx, "##grnd_qr_pun_dn_" .. tostring(it.id), bx + 26, by, 22, 24, "",
                        { muted = true, tri = "down" }) then
                        QR.punMove(it.id, 1)
                        pcall(QR.punSave)
                    end
                else
                    tri(ctx.dl, ctx.at, bx + 37, iy + 20, 4, "down",
                        ctx.col32(255, 255, 255, fully and 34 or 60))
                end
            end
        end
        if clip and ctx.dl.PopClipRect then pcall(ctx.dl.PopClipRect, ctx.dl) end
        if maxScroll > 0.5 then
            local trackX = x + w - 5
            ctx.roundRect(ctx.dl, ctx.at(trackX, listY), ctx.at(trackX + 3, listY + listH),
                ctx.col32(255, 255, 255, 18), 2)
            local barH = math.max(18, listH * (listH / (#list * rowH)))
            local barY = listY + ((P.listScroll or 0) / maxScroll) * (listH - barH)
            ctx.roundRect(ctx.dl, ctx.at(trackX, barY), ctx.at(trackX + 3, barY + barH),
                ctx.col32(ac[1], ac[2], ac[3], 200), 2)
        end
    end

    -- Редактор наказания (правая колонка).
    local function punEditorDraw(ctx, x, y, w, h)
        local TH = theme()
        local im = ctx.im
        local P = QR.pun
        local it = punFormSync()
        ctx.roundRect(ctx.dl, ctx.at(x, y), ctx.at(x + w, y + h), ctx.col32(255, 255, 255, 10), 10)
        if ctx.dl.AddRect then
            pcall(ctx.dl.AddRect, ctx.dl, ctx.at(x + 0.5, y + 0.5), ctx.at(x + w - 0.5, y + h - 0.5),
                ctx.col32(255, 255, 255, 22), 10, 0, 1)
        end
        local title = P.isNew and "Новое наказание" or "Редактор наказания"
        ctx.uiText(x + 12, y + 9, title, ctx.col32(TH.textHi[1], TH.textHi[2], TH.textHi[3], 255), 0.9)
        local dim = ctx.col32(TH.textDim[1], TH.textDim[2], TH.textDim[3], 255)
        local muted = ctx.col32(TH.textMuted[1], TH.textMuted[2], TH.textMuted[3], 255)
        if not it and not P.isNew then
            ctx.uiText(x + 12, y + 38, "Выберите наказание слева", muted, 0.92)
            ctx.uiText(x + 12, y + 58, "или нажмите «+ Новый шаблон».", muted, 0.92)
            ctx.uiText(x + 12, y + 92, "Кнопка «Наказание» в окне репорта", dim, 0.82)
            ctx.uiText(x + 12, y + 108, "откроет этот список по центру окна,", dim, 0.82)
            ctx.uiText(x + 12, y + 124, "клик по шаблону отправит наказание.", dim, 0.82)
            return
        end
        local pad = 12
        local ix, iw = x + pad, w - pad * 2
        local btnH, footH = 32, 12
        local by = y + h - btnH - 6          -- ряд кнопок (нужен и выпадающему списку)
        local yy = y + 32
        ctx.uiText(ix, yy, "Название", dim, 0.82)
        yy = yy + 17
        field(ctx, "##grnd_qr_pun_name", "punName", 64,
            ix, yy, iw, 28, "Например: Мут 60 минут", false, it and it.name or "")
        yy = yy + 36
        ctx.uiText(ix, yy, "Ответ на репорт", dim, 0.82)
        yy = yy + 17
        field(ctx, "##grnd_qr_pun_text", "punText", 2048,
            ix, yy, iw, PUN_TEXT_H, "Текст, который уйдёт игроку…", true, it and it.text or "")
        yy = yy + PUN_TEXT_H + 10

        -- ---------- селектор команды наказания ----------
        local cmdBuf = bufGet(im, "punCmd", 16)
        if not cmdBuf then
            ctx.uiText(ix, yy, "Команда наказания: поле недоступно", dim, 0.85)
            return
        end
        -- при смене шаблона подставляем его команду в буфер селектора
        if P.cmdSync ~= P.formKey then
            P.cmdSync = P.formKey
            bufWrite("punCmd", it and it.cmd or "")
        end
        local curCmd = trim(bufText("punCmd")):lower()
        local def = QR.punDef(curCmd)
        ctx.uiText(ix, yy, "Команда наказания", dim, 0.82)
        yy = yy + 17
        local selY = yy
        local ac = TH.accent or { 164, 112, 224, 255 }
        im.SetCursorPos(im.ImVec2(ix, selY))
        local selClicked = im.InvisibleButton("##grnd_qr_pun_cmd", im.ImVec2(iw, PUN_SEL_H)) and true or false
        local selHov = (im.IsItemHovered and im.IsItemHovered()) or false
        ctx.roundRect(ctx.dl, ctx.at(ix, selY), ctx.at(ix + iw, selY + PUN_SEL_H),
            (selHov or P.comboOpen) and ctx.col32(255, 255, 255, 26) or ctx.col32(255, 255, 255, 12), 6)
        if ctx.dl.AddRect then
            pcall(ctx.dl.AddRect, ctx.dl, ctx.at(ix + 0.5, selY + 0.5), ctx.at(ix + iw - 0.5, selY + PUN_SEL_H - 0.5),
                (selHov or P.comboOpen) and ctx.col32(ac[1], ac[2], ac[3], 150)
                    or ctx.col32(255, 255, 255, 46), 6, 0, 1)
        end
        local curLabel = def and ("/" .. def.id) or "Выберите команду"
        ctx.uiText(ix + 10, selY + (PUN_SEL_H - lineH(ctx, 0.9)) / 2, curLabel,
            def and ctx.col32(240, 236, 250, 255) or muted, 0.9)
        tri(ctx.dl, ctx.at, ix + iw - 14, selY + PUN_SEL_H / 2, 4, "down",
            (selHov or P.comboOpen) and ctx.col32(ac[1], ac[2], ac[3], 235) or muted)
        if selClicked and QR.punCmds then
            P.comboOpen = not P.comboOpen
            P.comboScroll = 0
        end

        if P.comboOpen and QR.punCmds then
            -- Выпадающий список рисуем ВМЕСТО полей «Время» и «Причина» (они и
            -- оказались бы под ним): так нет наложения виджетов и клики
            -- всегда попадают туда, куда нацелены.
            local ddX, ddY, ddW = ix, selY + PUN_SEL_H + 4, iw
            local ddAvail = math.max(PUN_ROW_H, (by - 8) - ddY)
            local step = PUN_ROW_H + 2
            local maxRows = math.max(1, math.floor((ddAvail - 8) / step))
            local rowsN = math.min(#QR.punCmds, maxRows)
            local viewH = rowsN * step - 2
            local maxScroll = math.max(0, #QR.punCmds * step - 2 - viewH)
            local mx2, my2 = mouse(im)
            local winPos = im.GetWindowPos()
            local scx, scy = (winPos and winPos.x or 0) + ddX, (winPos and winPos.y or 0) + ddY
            P.comboScroll = scrollWheel(im, mx2, my2, scx, scy, ddW, viewH,
                tonumber(P.comboScroll) or 0, maxScroll, step)
            local scroll = math.max(0, math.min(maxScroll, tonumber(P.comboScroll) or 0))
            ctx.roundRect(ctx.dl, ctx.at(ddX - 2, ddY - 2), ctx.at(ddX + ddW + 2, ddY + viewH + 2),
                ctx.col32(16, 17, 24, 252), 8)
            if ctx.dl.AddRect then
                pcall(ctx.dl.AddRect, ctx.dl, ctx.at(ddX - 1.5, ddY - 1.5), ctx.at(ddX + ddW + 1.5, ddY + viewH + 1.5),
                    ctx.col32(255, 255, 255, 34), 8, 0, 1)
            end
            local clipDD = false
            if ctx.dl.PushClipRect then
                clipDD = pcall(ctx.dl.PushClipRect, ctx.dl, ctx.at(ddX, ddY), ctx.at(ddX + ddW, ddY + viewH), true)
            end
            local firstRow = math.max(1, math.floor(scroll / step) + 1)
            for i = firstRow, #QR.punCmds do
                local d = QR.punCmds[i]
                local ry = ddY + (i - 1) * step - scroll
                if ry >= ddY + viewH then break end
                local top = math.max(ry, ddY)
                local bottom = math.min(ry + PUN_ROW_H, ddY + viewH)
                if bottom - top > 6 then
                    im.SetCursorPos(im.ImVec2(ddX, top))
                    local clicked = im.InvisibleButton("##grnd_qr_pun_cmd_" .. d.id,
                        im.ImVec2(ddW, bottom - top)) and true or false
                    local hov = (im.IsItemHovered and im.IsItemHovered()) or false
                    local sel = (d.id == curCmd)
                    ctx.roundRect(ctx.dl, ctx.at(ddX, ry), ctx.at(ddX + ddW, ry + PUN_ROW_H),
                        sel and ctx.col32(ac[1], ac[2], ac[3], 46)
                            or (hov and ctx.col32(255, 255, 255, 20) or ctx.col32(255, 255, 255, 0)), 6)
                    if sel then
                        ctx.roundRect(ctx.dl, ctx.at(ddX + 4, ry + 7), ctx.at(ddX + 7, ry + PUN_ROW_H - 7),
                            ctx.col32(ac[1], ac[2], ac[3], 255), 2)
                    end
                    ctx.uiText(ddX + 14, ry + (PUN_ROW_H - lineH(ctx, 0.9)) / 2, "/" .. d.id,
                        sel and ctx.col32(250, 248, 255, 255)
                            or (hov and ctx.col32(240, 236, 250, 255) or ctx.col32(206, 200, 226, 255)), 0.9)
                    -- подсказка про поля этой команды — справа в строке
                    local hint = d.time and (d.unit or "") or "без срока"
                    if d.reason and d.time then hint = hint .. " · причина"
                    elseif d.reason then hint = "причина" end
                    local hw = 0
                    if type(ctx.drawnW) == "function" then
                        local ok, v = pcall(ctx.drawnW, hint, 0.78)
                        if ok and type(v) == "number" then hw = v end
                    end
                    ctx.uiText(ddX + ddW - 12 - hw, ry + (PUN_ROW_H - lineH(ctx, 0.78)) / 2, hint,
                        ctx.col32(150, 145, 172, 255), 0.78)
                    if clicked then
                        bufWrite("punCmd", d.id)
                        P.comboOpen = false
                    end
                end
            end
            if clipDD and ctx.dl.PopClipRect then pcall(ctx.dl.PopClipRect, ctx.dl) end
            if maxScroll > 0.5 then
                ctx.roundRect(ctx.dl, ctx.at(ddX + ddW - 4, ddY + 2), ctx.at(ddX + ddW - 2, ddY + viewH - 2),
                    ctx.col32(255, 255, 255, 18), 2)
                local barH = math.max(14, (viewH - 4) * viewH / (#QR.punCmds * step - 2))
                local barY = ddY + 2 + (scroll / maxScroll) * (viewH - 4 - barH)
                ctx.roundRect(ctx.dl, ctx.at(ddX + ddW - 4, barY), ctx.at(ddX + ddW - 2, barY + barH),
                    ctx.col32(ac[1], ac[2], ac[3], 200), 2)
            end
            -- клик мимо списка — просто закрываем его
            local winP = im.GetWindowPos()
            if punOutsideClick((winP and winP.x or 0) + ddX, (winP and winP.y or 0) + ddY, ddW, viewH,
                    (winP and winP.x or 0) + ix, (winP and winP.y or 0) + selY, PUN_SEL_H) then
                P.comboOpen = false
            end
        else
            -- поля, зависящие от команды: «Время» и «Причина»
            yy = selY + PUN_SEL_H + 8
            if def and def.time then
                ctx.uiText(ix, yy, "Время, " .. tostring(def.unit or ""), dim, 0.82)
                yy = yy + 17
                field(ctx, "##grnd_qr_pun_time", "punTime", 16,
                    ix, yy, math.min(160, iw), 28, "Только число", false, it and it.time or "")
                yy = yy + 36
            end
            if def and def.reason then
                ctx.uiText(ix, yy, "Причина", dim, 0.82)
                yy = yy + 17
                field(ctx, "##grnd_qr_pun_reason", "punReason", 256,
                    ix, yy, iw, 28, "Например: флуд в чате", false, it and it.reason or "")
                yy = yy + 36
            end
        end

        -- ---------- кнопки ----------
        local bw1 = math.min(146, math.floor(iw * 0.4))
        if button(ctx, "##grnd_qr_pun_save", ix, by, bw1, btnH, "Сохранить", { primary = true }) then
            local name = trim(bufText("punName"))
            local text = cleanText(bufText("punText"))
            local cmd = trim(bufText("punCmd")):lower()
            local tdef = QR.punDef(cmd)
            local time = (trim(bufText("punTime")):gsub("%D", ""))
            local reason = oneLine(bufText("punReason"))
            if not tdef then
                QR.toast("Выберите команду наказания", "warn", 2.8)
            elseif tdef.time and time == "" then
                QR.toast("Введите время наказания (только число)", "warn", 2.8)
            elseif tdef.reason and reason == "" then
                QR.toast("Введите причину наказания", "warn", 2.8)
            else
                if P.isNew then
                    local created = QR.punAdd(name, text, cmd, time, reason)
                    P.isNew = false
                    P.selId = created and created.id or nil
                else
                    QR.punUpdate(P.selId, name, text, cmd, time, reason)
                end
                P.formKey, P.cmdSync = nil, nil
                punFormSync()
                bufReload("punName")
                bufReload("punText")
                bufReload("punTime")
                bufReload("punReason")
                pcall(QR.punSave)
                QR.toast("Наказание сохранено", "ok", 2.2)
            end
        end
        local bx = ix + bw1 + 8
        local bw2 = math.min(112, math.floor(iw * 0.28))
        if button(ctx, "##grnd_qr_pun_cancel", bx, by, bw2, btnH, "Отмена", {}) then
            P.isNew, P.delArm, P.formKey, P.cmdSync = false, nil, nil, nil
            P.comboOpen = false
            punFormSync()
            QR.toast("Изменения отменены", "ok", 2.0)
        end
        if not P.isNew and it then
            local bx2 = bx + bw2 + 8
            local bw3 = iw - (bx2 - ix)
            if bw3 >= 90 then
                local label = (P.delArm == it.id) and "Точно удалить?" or "Удалить"
                if button(ctx, "##grnd_qr_pun_remove", bx2, by, bw3, btnH, label, { danger = true }) then
                    if P.delArm == it.id then
                        QR.punRemove(it.id)
                        P.delArm, P.formKey, P.cmdSync = nil, nil, nil
                        punFormSync()
                        pcall(QR.punSave)
                        QR.toast("Наказание удалено", "ok", 2.2)
                    else
                        P.delArm = it.id
                    end
                end
            end
        end
    end

    local function punSettingsDraw(ctx)
        if type(ctx) ~= "table" then return false end
        local im = ctx.im
        if not (im and ctx.uiText and ctx.roundRect and ctx.col32 and ctx.rgba and ctx.at) then
            return false
        end
        local TH = theme()
        QR.punEnsure()
        local P = QR.pun
        local x, y, w, h = ctx.x, ctx.y, ctx.w, ctx.h
        if not (x and y and w and h) or w < 240 or h < 140 then return false end

        -- шапка: заголовок, счётчик, поиск, «Новый шаблон»
        ctx.uiText(x, y + 1, "Шаблоны наказаний",
            ctx.col32(TH.textHi[1], TH.textHi[2], TH.textHi[3], 255), 1.0)
        local tw = 220
        if type(ctx.drawnW) == "function" then
            local ok, v = pcall(ctx.drawnW, "Шаблоны наказаний", 1.0)
            if ok and type(v) == "number" then tw = v end
        end
        chip(ctx, x + tw + 10, y - 2, "шаблонов: " .. tostring(QR.punCount()))

        local newW = 148
        local searchW = math.min(190, math.max(118, math.floor(w * 0.24)))
        local searchX = x + w - newW - searchW - 10
        if searchX > x + tw + 110 then
            field(ctx, "##grnd_qr_pun_search", "punSearch", 64,
                searchX, y - 3, searchW, 28, "Поиск…", false, P.filter)
            P.filter = bufText("punSearch")
        end
        if button(ctx, "##grnd_qr_pun_new", x + w - newW, y - 4, newW, 30, "+ Новый шаблон",
            { primary = P.isNew }) then
            P.isNew, P.selId, P.delArm = true, nil, nil
            P.formKey, P.cmdSync, P.comboOpen = nil, nil, false
            punFormSync()
            QR.toast("Выберите команду наказания и заполните поля", "ok", 2.6)
        end

        -- список + редактор (пропорции — как в шаблонах ответов)
        local yy = y + 34
        local gap = 14
        local listW = math.floor((w - gap) * 0.36)
        if listW < 200 then listW = 200 end
        if listW > 300 then listW = 300 end
        local contentH = (y + h) - yy
        if contentH < 120 then contentH = 120 end
        punListDraw(ctx, x, yy, listW, contentH)
        punEditorDraw(ctx, x + listW + gap, yy, w - listW - gap, contentH)
        return true
    end

    _G.grndQrPunishDraw = function(ctx)
        local ok, res = pcall(punSettingsDraw, ctx)
        if ok then return res end
        QR.punDrawErr = tostring(res)
        print("{FF6666}[GRND]{FFFFFF} шаблоны наказаний: " .. tostring(res))
        return false
    end
end

-- =====================================================================
--  АВТОПИЛОТ ОТВЕТОВ НА РЕПОРТ (v1.19.36) — «Репорт» → «Автопилот»
-- =====================================================================
--  Вкладки (до 15): в каждой — ОДИН триггер, свой текст ответа и своя команда
--  после ответа. Пришёл репорт — ищем триггер по всем вкладкам; как искать,
--  решает САМ ТЕКСТ ОТВЕТА вкладки:
--    * обычный ответ — репорт должен совпасть с триггером ЦЕЛИКОМ:
--      «дм» — да, «дм 234» — нет;
--    * в ответе есть {all} (или {ID}) — триггер ищется ЦЕЛЫМ СЛОВОМ в любом
--      месте репорта: «234 дм», «дм 234», «спек 234» для триггера «дм»/«спек» —
--      да, «дмх 234» — нет (слово приклеено). Из ответа {all} убирается — он
--      только включает этот режим;
--    * в ответе есть {ID} — из репорта берётся ID игрока (первое число:
--      «дм 234» → 234) и подставляется вместо {ID}; если числа нет — остаётся
--      штатный ID из репорта. После ответа автопилот сам заходит в слежку за
--      найденным игроком (/sp ID) — даже если у вкладки выбрана команда /goto.
--  Совпасть может не одна вкладка — тогда срабатывают ВСЕ, по порядку вкладок —
--  каждая отвечает игроку штатной /ans ID текст (в CP1251, без «закорючек») и
--  сразу отправляет свою команду (/sp ID или /goto ID).
--
--  Чтобы поведение было предсказуемым:
--    * слежка и мероприятие — пауза: автопилот молчит, но настройку не
--      выключает, тумблер остаётся включённым и ответы возвращаются сами,
--      как только причина уходит (телепорт посреди наблюдения сломал бы и
--      слежку, и ответы; на мероприятии ответы админам-МП не нужны);
--    * идёт ввод текста (чат, диалог, поле ImGui) — пропускаем, не мешаем;
--    * темп: пауза 0.5 с между срабатываниями; никаких других лимитов нет.
--      Ответ игроку — НЕ повод пропускать его следующий репорт: сколько раз
--      написал, столько раз и отвечаем (в рамках паузы);
--    * репорт без числового ID не трогаем — отвечать некому;
--    * ответ и команда идут в ОДНУ очередь репорта: ответ уходит первым,
--      сервер не получает две команды в одном кадре;
--    * репорт должен быть настоящим: в строке обязан быть маркер
--      «… [К-во репорта: N]» (написание «К-во»/«Кол-во» и пустой номер тоже
--      понимаем). Без маркера строка репортом не считается — обычный чат
--      «Ник[ID]: текст» ни окно «Репорты», ни автопилот не трогают;
--    * слово триггера ищется по правилу САМОГО слова: написали переменную на
--      слове («дм{ID}») — слово ищется в любом месте репорта, обычное слово —
--      только точное совпадение; переменная действует ровно на одно слово;
--    * {ID} на слове в триггере — ответ собирается САМ («Приветствую, слежу
--      за игроком Ник[ID]»), поле «Ответ игроку» у такой вкладки не нужно;
--    * {ник} и {ID} — это тот, НА КОГО пожаловались: ник берётся по найденному
--      ID из игры, а если числа в репорте не было — по нику, написанному в
--      тексте (если такой игрок на сервере). Автор репорта доступен как
--      {автор} — ему и уходит /ans;
--    * если в репорте НЕТ ни номера, ни имени, называть некого: у вкладки с
--      {ID} на слове уходит СВОЙ текст из «Ответ игроку» — без ника и ID;
--    * несколько разных слов-триггеров в одном репорте — отвечает только
--      ПЕРВОЕ (то, что раньше в тексте), остальные слова молчат;
--
--  Конфиг — общий config.json, секция reportAuto (домен grnd_repauto в
--  GRND_CONFIG.sources): on / sel / t1_trigger / t1_answer / t1_command / …
--  Вкладки пишутся по порядку, ключи читаются по одному — лишнего счётчика
--  в файле нет. Секция старого формата (один trigger=…) читается как первая
--  вкладка, ничего не теряется.
--
--  Локальные имена живут в do-блоке: у Lua в функции не больше 200 локальных.
--  Отладка: QR.auto.lastCheck и QR.auto.err; ошибки отрисовки — в /mp diag.
-- =====================================================================
do
    -- v1.19.54: триггеров в строке — сколько угодно (список через запятую),
    -- поэтому лимит чисто технический и очень большой
    local MAX_ATRIG = 2048     -- символов в строке триггеров
    local TRIG_CAP = MAX_ATRIG * 2 + 1   -- буфер поля: байты (кириллица — 2 байта)
    local MAX_TABS = 15        -- сколько вкладок можно завести
    local AUTO_GAP = 0.5       -- пауза между срабатываниями (сек)

    -- Команды после ответа. «Без команды» — только ответ игроку.
    local AUTO_CMDS = {
        { id = "sp",   label = "/sp",         hint = "слежка за игроком" },
        { id = "goto", label = "/goto",       hint = "телепорт к игроку" },
        { id = "none", label = "Без команды", hint = "только ответ" },
    }
    QR.autoCmds = AUTO_CMDS

    -- Кириллица в нижний регистр. string.lower() работает побайтно и русские
    -- буквы не трогает: «Помогите» и «помогите» иначе не совпали бы.
    local AUTO_LOW = {
        ["А"]="а",["Б"]="б",["В"]="в",["Г"]="г",["Д"]="д",["Е"]="е",["Ё"]="ё",["Ж"]="ж",
        ["З"]="з",["И"]="и",["Й"]="й",["К"]="к",["Л"]="л",["М"]="м",["Н"]="н",["О"]="о",
        ["П"]="п",["Р"]="р",["С"]="с",["Т"]="т",["У"]="у",["Ф"]="ф",["Х"]="х",["Ц"]="ц",
        ["Ч"]="ч",["Ш"]="ш",["Щ"]="щ",["Ъ"]="ъ",["Ы"]="ы",["Ь"]="ь",["Э"]="э",["Ю"]="ю",
        ["Я"]="я",
    }

    local function autoLower(str)
        str = tostring(str or ""):lower()
        if str == "" then return str end
        local out = {}
        for ch in str:gmatch("[%z\1-\127\194-\244][\128-\191]*") do
            out[#out + 1] = AUTO_LOW[ch] or ch
        end
        return table.concat(out)
    end

    -- Текст репорта «как его видит игрок»: без кодов цвета, в одну строку.
    local function autoPlain(str)
        str = tostring(str or "")
        str = str:gsub("{%x%x%x%x%x%x%x%x}", ""):gsub("{%x%x%x%x%x%x}", "")
        -- хвост «[К-во репорта: N]» (если строка дошла целиком) не мешает словам
        str = str:gsub("%[К%-во репорта:%s*%d+%]", " ")
        str = str:gsub("[%c]", " ")
        return trim(str:gsub("%s+", " "))
    end

    -- ---------- распознавание строки репорта (v1.19.41) ----------

    -- Маркер репорта — ЕДИНСТВЕННЫЙ признак настоящей жалобы (v1.19.47).
    -- Серверы пишут его по-разному: «[К-во репорта: 25]», «[Кол-во репорта:
    -- 25]», «[К-во репорта:25]», иногда с пустым номером («[К-во репорта: ]»).
    -- Написание терпим, но маркер обязан быть: строка «Ник[ID]: текст» без
    -- него — обычная реплика чата, её не берут ни окно «Репорты», ни
    -- автопилот, ни панель МП.
    function QR.repCountOf(msg)
        local pat = "%[[^%]]*[Рр]епорта%s*:%s*(%d*)%s*%]"
        local low = autoLower(tostring(msg or ""))
        local n = low:match(pat)
        if n == nil then return nil end
        return tonumber(n) or 1
    end

    -- ---------- конфиг автопилота ----------

    function QR.autoPath()
        local base = tostring(QR.path() or "")
        local replaced = base:gsub("grnd_repquick%.cfg$", "grnd_repauto.cfg")
        if replaced ~= base then return replaced end
        local dir = base:match("^(.*[/\\])")
        if dir then return dir .. "grnd_repauto.cfg" end
        return "grnd_repauto.cfg"
    end

    function QR.autoCmdId(v)
        v = tostring(v or ""):lower():gsub("[^%a]", "")
        if v == "goto" or v == "none" then return v end
        return "sp"
    end

    function QR.autoCmdLabel(id)
        id = QR.autoCmdId(id)
        for i = 1, #AUTO_CMDS do
            if AUTO_CMDS[i].id == id then return AUTO_CMDS[i].label end
        end
        return "/sp"
    end

    -- ---------- вкладки ----------

    -- Пустая вкладка: триггер, ответ, команда. Триггер — ОДИН на вкладку.
    function QR.autoNewTab()
        return { trigger = "", answer = "", command = "sp" }
    end

    -- Вкладки всегда есть: минимум одна. Возвращает массив.
    function QR.autoTabs()
        local A = QR.auto
        if type(A.tabs) ~= "table" then A.tabs = {} end
        local out = {}
        for i = 1, #A.tabs do
            local t = A.tabs[i]
            if type(t) == "table" then out[#out + 1] = t end
        end
        if #out == 0 then out[1] = QR.autoNewTab() end
        while #out > MAX_TABS do table.remove(out) end
        A.tabs = out
        A.sel = math.max(1, math.min(#out, math.floor(tonumber(A.sel) or 1)))
        return out
    end

    function QR.autoTab(i)
        local tabs = QR.autoTabs()
        i = math.floor(tonumber(i) or QR.auto.sel or 1)
        if i < 1 then i = 1 end
        if i > #tabs then i = #tabs end
        return tabs[i], i
    end

    -- Подпись вкладки — её триггер; без триггера — «Вкладка N».
    function QR.autoLabel(i)
        local t = QR.auto.tabs and QR.auto.tabs[i]
        local trg = t and tostring(t.trigger or "") or ""
        if trim(trg) ~= "" then return trim(trg) end
        return "Вкладка " .. tostring(i)
    end

    function QR.autoAdd()
        local tabs = QR.autoTabs()
        if #tabs >= MAX_TABS then
            QR.toast("Больше " .. tostring(MAX_TABS) .. " вкладок не нужно", "warn", 2.6)
            return nil
        end
        tabs[#tabs + 1] = QR.autoNewTab()
        QR.auto.sel = #tabs
        QR.auto.listOpen = false
        pcall(QR.autoSave)
        return QR.auto.sel
    end

    -- Удаление вкладки. Последнюю не удаляем — очищаем: пустая вкладка честно
    -- показана как «Вкладка N», и автопилот просто молчит.
    function QR.autoDel(i)
        local tabs = QR.autoTabs()
        i = math.floor(tonumber(i) or QR.auto.sel or 1)
        if i < 1 or i > #tabs then return false end
        if #tabs <= 1 then
            tabs[1] = QR.autoNewTab()
            QR.auto.sel = 1
        else
            table.remove(tabs, i)
            if QR.auto.sel > #tabs then QR.auto.sel = #tabs end
        end
        QR.auto.listOpen = false
        -- буферы полей привязаны к номеру вкладки — после сдвига их надо
        -- перечитать из модели
        if type(QR.bufs) == "table" then
            for k in pairs(QR.bufs) do
                if tostring(k):find("^auto") then QR.bufs[k] = nil end
            end
        end
        pcall(QR.autoSave)
        return true
    end

    -- Триггеры вкладки (в одной вкладке триггер один, но в поле можно
    -- перечислить синонимы через запятую).
    -- v1.19.40: служебные {…} из триггера вычищаются при разборе — «дм{ID}»,
    -- «спек{all}», «наказ{punishments}» читаются как «дм», «спек», «наказ»,
    -- а сами переменные включают режим вкладки (см. autoVarFlags).
    -- Триггеры вкладки: { { word = "дм", wide = true }, … }.
    -- wide — переменная написана ПРЯМО НА ЭТОМ слове («дм{ID}»): только тогда
    -- слово ищется как отдельное слово в ЛЮБОМ месте репорта. Соседние слова
    -- без переменной («дм{ID}, dm») ищутся как обычно — репорт должен
    -- совпасть с ними целиком. Переменная в поле «Ответ» поиск НЕ расширяет:
    -- она только подставляет значение в текст ответа.
    function QR.autoTrigList(tab)
        tab = tab or QR.autoTab()
        local raw = tostring(tab and tab.trigger or "")
        local out = {}
        for piece in (raw .. ","):gmatch("([^,;\n]*)[,;\n]") do
            local wide = piece:find("%b{}") ~= nil
            local lowPiece = autoLower(piece)
            -- v1.19.55: переменные действуют на СВОЁ слово: у слова с
            -- {punishments} ответ собирается списком наказаний (и команда не
            -- уходит), у слова с {ID} — авто-приветствие; остальные слова
            -- вкладки работают как обычно — свой текст и своя команда
            local pun = lowPiece:find("{punishments}", 1, true) ~= nil
            local idv = lowPiece:find("{id}", 1, true) ~= nil
            local w = trim(autoLower(autoPlain((piece:gsub("%b{}", " ")))))
            if w ~= "" then
                out[#out + 1] = { word = w, wide = wide, pun = pun, idv = idv }
            end
        end
        return out
    end

    -- v1.19.55: сколько слов в триггере БЕЗ переменных — им нужен текст из
    -- «Ответ игроку» (и команда). Слова с {punishments}/{ID} отвечают сами.
    function QR.autoPlainWords(tab)
        local list, n = QR.autoTrigList(tab), 0
        for i = 1, #list do
            if not list[i].pun and not list[i].idv then n = n + 1 end
        end
        return n
    end

    -- Только слова (для счётчиков и проверок).
    function QR.autoTriggers(tab)
        local list, out = QR.autoTrigList(tab), {}
        for i = 1, #list do out[i] = list[i].word end
        return out
    end

    -- Первый символ остатка — буква или цифра («словесный»)? Нужно, чтобы
    -- триггер совпадал именно со СЛОВОМ: «помогитеплиз» для «помогите» и
    -- «дмитрий…» для «дм» — нет (приклеенное слово), «, дм», «!!!» — да.
    -- Кириллица в UTF-8 начинается с байтов 0xD0/0xD1.
    -- Первый символ — буква/цифра? (границы слова: «дм 234» — да, «дмх» — нет).
    -- Кириллица в UTF-8 начинается с байтов 0xD0/0xD1.
    local function autoWordStart(rest)
        if rest == "" then return false end
        local b = rest:byte(1)
        if b == nil then return false end
        if b < 0x80 then return rest:sub(1, 1):match("[%w_]") ~= nil end
        return b == 0xD0 or b == 0xD1
    end

    -- Последний символ строки (для проверки границы СЛЕВА: «xдм» — приклеено).
    local function autoLastChar(t)
        return tostring(t or ""):match("([%z\1-\127\194-\244][\128-\191]*)$") or ""
    end

    -- Триггер — ЦЕЛОЕ слово в любом месте текста (режим {all}/{ID}).
    -- Возвращает позицию первого такого слова (nil — не нашлось): по ней
    -- выбирается, какое слово репорта «первое» (v1.19.46).
    local function autoWordAt(low, trig)
        if trig == "" then return nil end
        local from = 1
        while true do
            local s1, s2 = low:find(trig, from, true)
            if not s1 then return nil end
            local before = autoLastChar(low:sub(1, s1 - 1))
            if not autoWordStart(before) and not autoWordStart(low:sub(s2 + 1)) then
                return s1
            end
            from = s1 + 1
        end
    end

    local function autoWordHit(low, trig)
        return autoWordAt(low, trig) ~= nil
    end

    -- Строка ответа в куски по лимиту чата: длинный список наказаний в одно
    -- сообщение не влезет. Короткие ответы уходят как есть, одним куском.
    local function autoChunks(line)
        line = tostring(line or "")
        if #line <= 100 then return { line } end
        if type(QR.punChunks) == "function" then
            local ok, out = pcall(QR.punChunks, line, 100)
            if ok and type(out) == "table" and #out > 0 then return out end
        end
        return { line }
    end

    -- ID игрока из текста репорта: первое число («дм 234», «234 дм» → 234).
    -- Число должно быть отдельным: «234дм» и «12abc» не годятся.
    function QR.autoFindReportId(text)
        text = tostring(text or "")
        local init = 1
        while true do
            local s1, s2 = text:find("%d+", init)
            if not s1 then return nil end
            local num = text:sub(s1, s2)
            if #num <= 5 and not autoWordStart(autoLastChar(text:sub(1, s1 - 1)))
                and not autoWordStart(text:sub(s2 + 1)) then
                return num
            end
            init = s2 + 1
        end
    end

    -- Ник игрока по ID — спрашиваем игру (единственный надёжный источник).
    function QR.autoNickById(id)
        local num = tonumber(id)
        if not num or num < 0 or num > 1003 then return nil end
        if type(_G.sampGetPlayerNickname) ~= "function" then return nil end
        local ok, n = pcall(_G.sampGetPlayerNickname, num)
        if ok and type(n) == "string" and n ~= "" then return n, num end
        return nil
    end

    -- Ник, написанный в САМОМ тексте репорта, — но только если такой игрок
    -- сейчас на сервере (иначе «обман», «чит» и любое слово из жалобы
    -- посчитались бы ником). Возвращает ник и его ID.
    function QR.autoNickInText(text)
        text = tostring(text or "")
        if text == "" then return nil end
        if type(_G.sampIsPlayerConnected) ~= "function"
            or type(_G.sampGetPlayerNickname) ~= "function" then return nil end
        local maxid = 1003
        if type(_G.sampGetMaxPlayerId) == "function" then
            local ok, n = pcall(_G.sampGetMaxPlayerId)
            if ok and tonumber(n) then
                maxid = math.max(0, math.min(1003, math.floor(tonumber(n))))
            end
        end
        local players = {}
        for id = 0, maxid do
            local okC, on = pcall(_G.sampIsPlayerConnected, id)
            if okC and on then
                local okN, nick = pcall(_G.sampGetPlayerNickname, id)
                if okN and type(nick) == "string" and nick ~= "" then
                    players[autoLower(nick)] = { nick = nick, id = id }
                end
            end
        end
        local low = autoLower(text)
        for w in low:gmatch("[%w_%.%-]+") do
            -- ники латиницей: буквы/цифры/«_»/«.»/«-», 3–24 знака, есть буква
            if #w >= 3 and #w <= 24 and w:find("%a") then
                local hit = players[w]
                if hit then return hit.nick, hit.id end
            end
        end
        return nil
    end

    -- Кто в репорте «на кого пожаловались»: сначала ID из текста («дм 234») →
    -- ник из игры; если числа не было — ник, написанный в тексте. Автор строки
    -- репорта (тот, кому отвечает /ans) здесь не участвует — он приходит
    -- отдельно и остаётся в {автор}.
    function QR.autoTargetOf(text, foundId)
        local n, id = QR.autoNickById(foundId)
        if n then return n, id end
        return QR.autoNickInText(text)
    end

    -- Переменные вкладки — их можно писать И В ТРИГГЕРЕ, И В ОТВЕТЕ:
    --   {ID}          — ID из репорта («дм 234»), иначе штатный ID, + слежка за ним;
    --   {all}         — триггер ищется словом в ЛЮБОМ месте репорта;
    --   {punishments} — активные наказания игрока из окна /getinfo.
    -- Хотя бы одна переменная — вкладка не требует полного совпадения репорта.
    function QR.autoVarFlags(tab)
        local low = autoLower(tostring((tab and tab.trigger) or "")) .. " "
            .. autoLower(tostring((tab and tab.answer) or ""))
        return low:find("{id}", 1, true) ~= nil, low:find("{all}", 1, true) ~= nil,
            low:find("{punishments}", 1, true) ~= nil
    end

    -- Как искать — решает САМО СЛОВО (v1.19.43): у слова с переменной
    -- («дм{ID}») — целое слово в любом месте репорта («234 дм», «дм 234» —
    -- да, «дмх 234» — нет), у обычного слова — репорт совпадает с ним
    -- ЦЕЛИКОМ («дм» — да, «дм 234» — нет). Переменная действует ТОЛЬКО на то
    -- слово, на которое написана: в «дм{ID}, dm» широко ищется «дм», а «dm» —
    -- как обычно.
    --
    -- v1.19.46: если в репорте подошло НЕСКОЛЬКО РАЗНЫХ слов, отвечает только
    -- ПЕРВОЕ из них — то, что раньше в тексте: на «дм спек 234» ответит «дм», а
    -- «спек» промолчит. Одно и то же слово в нескольких вкладках — по-прежнему
    -- срабатывают все (v1.19.25), по порядку вкладок.
    -- Возвращает { {idx=, trig=}, … } и строку с пропущенными словами.
    function QR.autoMatchAll(text)
        local low = trim(autoLower(autoPlain(text)))
        local out = {}
        if low == "" then return out, "" end
        local tabs = QR.autoTabs()
        local found, best, dropped = {}, nil, {}
        for i = 1, #tabs do
            local list = QR.autoTrigList(tabs[i])
            -- своё ЛУЧШЕЕ (самое раннее) слово этой вкладки
            local mine = nil
            for k = 1, #list do
                local it = list[k]
                local pos
                if it.wide then
                    pos = autoWordAt(low, it.word)
                elseif low == it.word then
                    pos = 1          -- репорт совпал целиком: это начало строки
                end
                if pos and (not mine or pos < mine.pos) then
                    -- v1.19.55: запоминаем и переменные этого слова — по ним
                    -- решается, что уйдёт игроку (список наказаний, авто-ответ
                    -- или свой текст с командой)
                    mine = { pos = pos, word = it.word, pun = it.pun, idv = it.idv }
                end
            end
            if mine then
                found[#found + 1] = { idx = i, trig = mine.word, pos = mine.pos,
                    pun = mine.pun, idv = mine.idv }
                if not best or mine.pos < best then best = mine.pos end
            end
        end
        if #found > 0 then
            for k = 1, #found do
                if found[k].pos == best then
                    out[#out + 1] = { idx = found[k].idx, trig = found[k].trig,
                        pun = found[k].pun, idv = found[k].idv }
                elseif not dropped[found[k].trig] then
                    dropped[found[k].trig] = true
                end
            end
            local names = {}
            for w in pairs(dropped) do names[#names + 1] = w end
            return out, table.concat(names, ", ")
        end
        -- слов не нашлось: работает вкладка с голой {punishments}
        for i = 1, #tabs do
            if QR.autoBarePun(tabs[i]) then
                -- вкладка-наказания без слов: ответ собирается списком
                out[#out + 1] = { idx = i, trig = QR.autoTrigLabel(tabs[i]), pun = true }
            end
        end
        return out, ""
    end

    -- Первая подошедшая вкладка (номер и триггер) — для подсказок и отладки.
    function QR.autoMatchTab(text)
        local hits = QR.autoMatchAll(text)
        if #hits == 0 then return nil end
        return hits[1].idx, hits[1].trig
    end

    -- Сводка по вкладкам: сколько готовых (с триггером и ответом).
    function QR.autoReady()
        local tabs, ready = QR.autoTabs(), 0
        for i = 1, #tabs do
            local tab = tabs[i]
            local hasWord = #QR.autoTriggers(tab) > 0
            local hasAns = trim(tostring(tab.answer or "")) ~= ""
                or QR.autoPunInTrigger(tab) or QR.autoIDInTrigger(tab)
            if (hasWord or QR.autoBarePun(tab)) and hasAns then ready = ready + 1 end
        end
        return ready, #tabs
    end

    -- Что уйдёт после ответа: «/sp 25», «/goto 25» или nil.
    function QR.autoCmdFor(pid, tab)
        pid = tostring(pid or "")
        if pid:match("^%d+$") == nil then return nil end
        tab = tab or QR.autoTab()
        local id = QR.autoCmdId(tab and tab.command)
        if id == "none" then return nil end
        return "/" .. id .. " " .. pid
    end

    -- В триггере ТОЛЬКО переменная {punishments} — без слов («{punishments}»,
    -- «, {punishments},»)? Тогда вкладка отвечает на ЛЮБОЙ репорт: слово ей не
    -- нужно, ответ про наказания собирается сам. Голые «{ID}» и «{all}» так НЕ
    -- работают — переменная действует только на то слово, на которое написана.
    function QR.autoBarePun(tab)
        local raw = autoLower(tostring((tab and tab.trigger) or ""))
        if raw:find("{punishments}", 1, true) == nil then return false end
        return trim((raw:gsub("%b{}", " ")):gsub("[,;]", " ")) == ""
    end

    -- Вкладка-«наказания»: {punishments} написан в триггере (и на слове, и
    -- голым) — поле «Ответ игроку» ей не нужно.
    function QR.autoVarsOnly(tab)
        return #QR.autoTriggers(tab) == 0 and QR.autoBarePun(tab)
    end

    -- {punishments} прямо в триггере: поле «Ответ игроку» не нужно — ответ
    -- собирается сам, слово в слово как у кнопки «Наказания игрока».
    function QR.autoPunInTrigger(tab)
        local raw = autoLower(tostring((tab and tab.trigger) or ""))
        return raw:find("{punishments}", 1, true) ~= nil
    end

    -- v1.19.44: {ID} на слове в ТРИГГЕРЕ — ответ тоже собирается САМ, что бы
    -- ни лежало в поле «Ответ игроку»: админ пишет только «дм{ID}», а игрок
    -- получает «Приветствую, слежу за игроком Ник[ID]» (ID из репорта, если он
    -- там был, иначе штатный) и следом /sp с этим ID.
    QR.AUTO_GREET = "Приветствую, слежу за игроком {ник}[{ID}]"

    function QR.autoIDInTrigger(tab)
        local raw = autoLower(tostring((tab and tab.trigger) or ""))
        return raw:find("{id}", 1, true) ~= nil
    end

    -- Готовый текст приветствия. Собираем из частей: пустых «[]» и
    -- незаменённых «{ник}» в чат не попадёт. Некого называть — вернётся "".
    function QR.autoGreet(rep)
        rep = (type(rep) == "table") and rep or {}
        local nick = tostring(rep.nick or "")
        local id = tostring(rep.foundId or "")
        if id == "" then id = tostring(rep.id or "") end
        if nick == "" and id == "" then return "" end
        local who = nick
        if nick ~= "" and id ~= "" then who = nick .. "[" .. id .. "]"
        elseif nick == "" then who = "[" .. id .. "]" end
        return "Приветствую, слежу за игроком " .. who
    end

    -- v1.19.46: вычистить из готовой строки не подставившихся «кто»-переменных
    -- ({ник}/{ID}/{ид}) и следы от них — цвета {RRGGBB} не трогаем.
    function QR.autoWhoStrip(line)
        line = tostring(line or "")
        line = line:gsub("{ник}", ""):gsub("{nick}", "")
        line = line:gsub("{ид}", ""):gsub("{id}", ""):gsub("{ID}", "")
        line = line:gsub("%[%s*%]", "")
        line = line:gsub("%s+", " ")
        line = line:gsub("%s+([,%.!%?:;])", "%1")
        line = line:gsub(",%s*([%.!%?:;])", "%1")
        return trim(line)
    end

    -- Как назвать такую вкладку в тостах и подсказке.
    function QR.autoTrigLabel(tab)
        local low = autoLower(tostring((tab and tab.trigger) or ""))
        local v = low:match("{(%a+)}")
        if v == "punishments" then return "наказания" end
        if v == "id" then return "ID из репорта" end
        return "любой репорт"
    end

    -- Строка ответа игроку так, как её отправил бы grndRepAnswer: та же
    -- команда, тот же ID (у ботов-репортов ответ идёт не /ans, а /pm).
    function QR.autoAnsCmd(pid, text)
        pid = tostring(pid or "")
        local R = _G.GRND_REP
        local rc = R and R.replyCmd
        if type(rc) == "string" and rc ~= "" and tostring(R.replyPid or "") == pid then
            return (rc:gsub("%d+", pid)) .. " " .. tostring(text)
        end
        return "/ans " .. pid .. " " .. tostring(text)
    end

    -- Строка ответа игроку, которая уйдёт в чат: боевая — «/ans ID текст», а для
    -- репорта от бота его команда «/pm ID текст». Этим пользуются и автопилот,
    -- и ручной ответ из окна репорта — формат один. Служебного канала /n больше
    -- нет (v1.19.56: слой проверки убран целиком).
    function QR.answerCmd(pid, text)
        return QR.autoAnsCmd(pid, text)
    end

    -- Итоговая команда вкладки после ответа: найденный в репорте ID важнее
    -- своей команды — за таким игроком автопилот идёт в СЛЕЖКУ (/sp),
    -- даже если у вкладки выбрано /goto. Иначе — команда вкладки.
    function QR.autoTabCmd(pid, tab, foundId)
        -- v1.19.52–55: команда не выполняется, когда сработало слово с
        -- {punishments} — это решает отправитель (он знает, какое слово
        -- подошло); здесь команда собирается как обычно
        local hasID = QR.autoVarFlags(tab)
        if hasID and tostring(foundId or "") ~= "" then
            return "/sp " .. tostring(foundId)
        end
        return QR.autoCmdFor(pid, tab)
    end

    function QR.autoNormalize()
        local A = QR.auto
        if type(A) ~= "table" then A = {} QR.auto = A end
        A.on = A.on and true or false
        A.fired = math.max(0, math.floor(tonumber(A.fired) or 0))
        local tabs = QR.autoTabs()
        for i = 1, #tabs do
            local t = tabs[i]
            t.trigger = clampText(oneLine(utf(t.trigger or "")), MAX_ATRIG)
            t.answer = clampText(cleanText(utf(t.answer or "")), MAX_TEXT)
            t.command = QR.autoCmdId(t.command)
        end
        return A
    end

    function QR.autoLoad()
        local A = QR.auto
        if A.loaded then return true end
        A.loaded = true
        local on, sel, legacy = nil, nil, nil
        local tabs = {}
        local ok, f = pcall(GRND_CONFIG.open, QR.autoPath(), "r")
        if ok and f then
            for line in f:lines() do
                local k, v = tostring(line or ""):match("^([%w_]+)=(.*)$")
                -- k может быть nil: сначала строка, потом разбор — «k and
                -- k:match()» вернул бы только первый захват
                local idx, field = tostring(k or ""):match("^t(%d+)_(%a+)$")
                -- в config.json числа хранятся числами (scalar() превращает
                -- «1» в 1), поэтому всё сравниваем как строки
                if v ~= nil then v = tostring(v) end
                if idx then
                    local n = tonumber(idx)
                    if n and n >= 1 and n <= MAX_TABS then
                        tabs[n] = tabs[n] or QR.autoNewTab()
                        if field == "trigger" then tabs[n].trigger = unesc(v)
                        elseif field == "answer" then tabs[n].answer = unesc(v)
                        elseif field == "command" then tabs[n].command = v end
                    end
                elseif k == "on" then on = (v == "1" or v == "true")
                elseif k == "sel" then sel = tonumber(v)
                elseif k == "fired" then A.fired = tonumber(v)
                elseif k == "trigger" or k == "answer" or k == "command" then
                    legacy = legacy or QR.autoNewTab()
                    legacy[k] = unesc(v)
                end
            end
            pcall(f.close, f)
        end
        if #tabs == 0 and legacy then tabs[1] = legacy end   -- файл старого формата
        if #tabs == 0 then tabs[1] = QR.autoNewTab() end
        A.tabs, A.sel = tabs, sel
        if on ~= nil then A.on = on end
        QR.autoNormalize()
        return true
    end

    function QR.autoEnsure()
        local A = QR.auto
        if type(A) ~= "table" then A = {} QR.auto = A end
        if not A.loaded then pcall(QR.autoLoad) end
        return QR.autoNormalize()
    end

    function QR.autoSave()
        local A = QR.autoNormalize()
        A.dirtyAt = nil
        local ok, f = pcall(GRND_CONFIG.open, QR.autoPath(), "w")
        if not ok or not f then return false end
        f:write("on=" .. (A.on and "1" or "0") .. "\n")
        f:write("sel=" .. tostring(A.sel or 1) .. "\n")
        for i = 1, #A.tabs do
            local t = A.tabs[i]
            f:write("t" .. i .. "_trigger=" .. esc(t.trigger or "") .. "\n")
            f:write("t" .. i .. "_answer=" .. esc(t.answer or "") .. "\n")
            f:write("t" .. i .. "_command=" .. tostring(t.command or "sp") .. "\n")
        end
        pcall(f.close, f)
        if GRND_CONFIG and type(GRND_CONFIG.flush) == "function" then
            pcall(GRND_CONFIG.flush)
        end
        return true
    end

    -- =================================================================
    --  АКТИВНЫЕ НАКАЗАНИЯ ИГРОКА (/getinfo ID): окно читается и прячется.
    --
    --  Одна механика на два случая:
    --    * mode = "manual" — кнопка «Наказания игрока» в окне репорта:
    --      ответ игроку — фиксированный текст, как было;
    --    * mode = "auto" — переменная {punishments} в ответе автопилота:
    --      список подставляется вместо переменной, а план вкладки уходит
    --      сразу после чтения окна (и даже если окно не пришло).
    --
    --  Живёт тут, в модуле быстрых ответов, а не в grndMainBody: автопилот
    --  отвечает и с закрытым окном репорта, поэтому механика обязана быть
    --  доступна всегда (в grndMainBody она появлялась только после первой
    --  отрисовки окна).
    -- =================================================================
    QR.punReq = QR.punReq or { on = false, at = 0, pid = nil, nick = "", mode = "manual" }

    -- Диагностика ТОЛЬКО в консоль MoonLoader: в игре никаких уведомлений
    -- на действия этой механики быть не должно.
    QR.punLog = function(msg)
        pcall(print, "[GRND] наказания: " .. tostring(msg))
    end

    -- Снять ожидание окна (таймаут, сбой).
    QR.punCancel = function()
        local P = QR.punReq
        P.on, P.at, P.pid, P.nick, P.mode = false, 0, nil, "", nil
        P.seenTitle, P.seenText = nil, nil
    end

    -- Начать ожидание окна /getinfo ID. false — уже кого-то ждём.
    QR.punBegin = function(pid, nick, mode)
        local P = QR.punReq
        if P.on then return false end
        local pidS = tostring(pid or "")
        if pidS:match("^%d+$") == nil then return false end
        P.on, P.at, P.pid, P.nick = true, os.clock(), pidS, tostring(nick or "")
        P.mode = (mode == "auto") and "auto" or "manual"
        P.seenTitle, P.seenText = nil, nil
        return true
    end

    -- Кнопка «Наказания игрока»: начать ожидание и сразу спросить сервер.
    -- Возвращает true, если запрос ушёл (иначе уже ждём окно другого игрока).
    QR.punBeginManual = function(pid, nick)
        if not QR.punBegin(pid, nick, "manual") then
            QR.toast("Наказания: уже ждём окно другого игрока", "warn", 3)
            return false
        end
        if type(sampSendChat) == "function" then
            pcall(sampSendChat, "/getinfo " .. tostring(pid))
        else
            grndRepQueue("/getinfo " .. tostring(pid))
        end
        return true
    end

    -- Нормализация текста окна сервера: кодировка может быть CP1251
    -- (её и отдаёт этот сервер) — иначе русские подстроки не находятся.
    QR.punNorm = function(str)
        local t = grndToUtf(tostring(str or ""))
        t = t:gsub("{%x%x%x%x%x%x}", "")
        return t
    end

    -- Поиск подстроки в тексте окна без учёта регистра (UTF-8, после
    -- приведения кодировки). Сравнение посимвольное в нижнем регистре.
    QR.punFind = function(str, needle)
        local t = QR.punNorm(str)
        if type(_G.grndLowerUtf) == "function" then
            local ok, low = pcall(_G.grndLowerUtf, t)
            if ok and type(low) == "string" then t = low end
        else
            t = t:lower()
        end
        return t:find(needle, 1, true) ~= nil
    end

    -- Похоже ли окно на «Активные наказания игрока».
    -- Признак №1 — заголовок окна; признак №2 — строка «Аккаунт Ник[ID] …»,
    -- которую отдаёт именно /getinfo.
    QR.punLooksDialog = function(caption, text)
        if QR.punFind(caption, "наказани") then return true end
        if QR.punFind(caption, "наказан") then return true end
        return QR.punFind(text, "ккаунт")
    end

    -- Разбор содержимого окна: массив строк-наказаний.
    -- Первая значимая строка («Аккаунт Ник[ID] …») игнорируется,
    -- пустые строки и цветовые коды выбрасываются.
    QR.punParse = function(raw)
        local t = grndToUtf(tostring(raw or ""))
        t = t:gsub("{%x%x%x%x%x%x}", "")
        local out, head = {}, false
        for ln in (t .. "\n"):gmatch("([^\n]*)\n") do
            ln = ln:gsub("^%s+", ""):gsub("%s+$", "")
            if ln ~= "" then
                if not head then
                    head = true        -- первая значимая строка — «Аккаунт …»
                    if not ln:find("ккаунт", 1, true) then
                        out[#out + 1] = ln
                    end
                else
                    out[#out + 1] = ln
                end
            end
        end
        return out
    end

    -- Нарезка длинного текста на части по лимиту символов: в чат нельзя
    -- отправить слишком длинную строку, а список наказаний бывает длинным.
    -- Режем по границам UTF-8-символов, стараясь по пробелам.
    QR.punChunks = function(text, limit)
        limit = tonumber(limit) or 100
        local str = tostring(text or "")
        str = str:gsub("%s*\n%s*", " | ")
        str = str:gsub("%s+", " "):gsub("^%s+", ""):gsub("%s+$", "")
        local out = {}
        local function charCut(v, n)
            local i, k = 1, 0
            while i <= #v and k < n do
                local b = v:byte(i)
                local step = (b >= 240 and 4) or (b >= 224 and 3) or (b >= 192 and 2) or 1
                i = i + step
                k = k + 1
            end
            return i - 1
        end
        while str ~= "" do
            local cut = charCut(str, limit)
            if cut >= #str then
                out[#out + 1] = str
                break
            end
            local head = str:sub(1, cut)
            local lastSp
            for p in head:gmatch("()%s") do lastSp = p end
            if lastSp and lastSp > #head * 0.5 then
                out[#out + 1] = str:sub(1, lastSp - 1)
                str = str:sub(lastSp + 1)
            else
                out[#out + 1] = head
                str = str:sub(cut + 1)
            end
            str = str:gsub("^%s+", "")
        end
        return out
    end

    -- Ответ игроку (режим "manual"): /ans ID текст.
    -- Первое сообщение уходит СРАЗУ (ответ приходит пока админ ещё смотрит
    -- в окно репорта), но только если очередь пуста и пауза после прошлой
    -- отправки выдержана — иначе, как обычно, через очередь: два
    -- чат-сообщения в одном кадре сервер может проглотить.
    QR.punSay = function(pid, text)
        local chunks = QR.punChunks(text, 100)
        local pidS = tostring(pid or "")
        local pidOk = pidS:match("^%d+$") ~= nil
        local q = GRND_REP.queue
        local canJump = pidOk
            and (type(sampSendChat) == "function")
            and (type(q) ~= "table" or #q == 0)
            and ((os.clock() or 0) - (GRND_REP.queueAt or 0) >= 0.35)
        for i, c in ipairs(chunks) do
            if i == 1 and canJump then
                pcall(sampSendChat, "/ans " .. pidS .. " " .. grndRepToAnsi(c))
                pcall(grndRepHudRemove, pidS)   -- как делает grndRepAnswer
                -- держим общий интервал очереди: следующая команда
                -- не должна уйти в тот же кадр
                GRND_REP.queueAt = os.clock()
                canJump = false
            else
                grndRepAnswer(pid, c)
            end
        end
        return #chunks
    end

    -- Окно прочитано (raw — текст окна) или не пришло (raw = nil).
    QR.punFinish = function(raw)
        local P = QR.punReq
        if not P.on then return end
        local mode, pid, nick = P.mode, P.pid, P.nick
        local seen = P.seenTitle and ("последний диалог: " .. tostring(P.seenTitle)
            .. " | " .. tostring(P.seenText or ""):gsub("%s+", " ")) or "диалогов не было"
        local who = tostring(nick or ("ID " .. tostring(pid)))
        QR.punCancel()
        local lines = (type(raw) == "string") and QR.punParse(raw) or nil
        if mode == "auto" then
            -- {punishments}: список уходит в ответ, план вкладки — сразу после
            pcall(QR.autoPunAbsorb, lines)
            if not lines then QR.punLog(who .. ": окно /getinfo не распознано. " .. seen) end
            return
        end
        if not lines then
            QR.punLog("окно /getinfo не распознано. " .. seen)
        elseif #lines == 0 then
            QR.punSay(pid, "Приветствую, активных наказаний у вас нет.")
            QR.punLog(who .. ": активных наказаний нет")
        else
            QR.punSay(pid,
                "Приветствую, ваши активные наказания >> " .. table.concat(lines, " | "))
            QR.punLog(who .. ": строк наказаний " .. tostring(#lines))
        end
    end

    -- Хук sampev.onShowDialog: ловим окно /getinfo и прячем его.
    -- true = окно обработано, игроку его показывать не нужно.
    _G.grndQrPunOnDialog = function(dialogId, style, title, b1, b2, text)
        local P = QR.punReq
        if not P.on then return nil end
        local age = (os.clock() or 0) - (P.at or 0)
        if age > 8 then return nil end
        local body = (type(text) == "string" and text) or ""
        if body == "" then
            -- некоторые обёртки кладут содержимое не последним аргументом
            for _, v in ipairs({ b1, b2 }) do
                if type(v) == "string" and #v > #body then body = v end
            end
        end
        local looks = QR.punLooksDialog(title, body)
        -- Подстраховка: /getinfo отвечает почти сразу. Если окно пришло в
        -- первые секунды после запроса и это НЕ окно репорта — считаем его
        -- ответом, даже если формулировки сервера разошлись с ожиданием
        -- (админ сам нажал кнопку или автопилот сам спросил — окно наше).
        if not looks and age <= 3.0 and #body >= 5 then
            local foreign = false
            if type(_G.grndRepAcceptDialog) == "function" then
                local okR, r = pcall(_G.grndRepAcceptDialog, dialogId, title, body)
                if okR and r then foreign = true end
            end
            if not foreign and type(_G.grndStatsShouldHide) == "function" then
                local okS, r = pcall(_G.grndStatsShouldHide, title, body)
                if okS and r then foreign = true end
            end
            if not foreign then looks = true end
        end
        if not looks then
            -- чужой диалог во время ожидания: запомним для диагностики
            P.seenTitle, P.seenText = tostring(title or ""), tostring(body or ""):sub(1, 300)
            return nil
        end
        pcall(QR.punFinish, body)
        return true
    end

    -- Тик: запасной путь (если хук не сработал — окно уже на экране)
    -- и снятие «зависшего» ожидания по таймауту.
    QR.punPoll = function()
        local P = QR.punReq
        if not P.on then return end
        local now = os.clock() or 0
        local age = now - (P.at or 0)
        -- автопилоту ответ нужен быстрее: игрок ждёт ответа
        local limit = (P.mode == "auto") and 5 or 8
        if age > limit then
            pcall(QR.punFinish)          -- raw = nil: окно не пришло
            return
        end
        -- запасной путь: реакция не позже ~0.1 с после запроса
        if age < 0.1 then return end
        if type(grndSessionReady) == "function" and not grndSessionReady() then return end
        if type(sampIsDialogActive) ~= "function" then return end
        local okA, active = pcall(sampIsDialogActive)
        if not (okA and active) then return end
        local caption, text = "", ""
        if type(sampGetDialogCaption) == "function" then
            local ok, v = pcall(sampGetDialogCaption)
            if ok and type(v) == "string" then caption = v end
        end
        if type(sampGetDialogText) == "function" then
            local ok, v = pcall(sampGetDialogText)
            if ok and type(v) == "string" then text = v end
        end
        if not QR.punLooksDialog(caption, text) then return end
        local dlgId = nil
        if type(sampGetCurrentDialogId) == "function" then
            local ok, v = pcall(sampGetCurrentDialogId)
            if ok then dlgId = tonumber(v) end
        end
        pcall(QR.punFinish, text)
        -- окно уже было показано игроку (хук не сработал) — закрываем
        if dlgId then
            if type(sampSendDialogResponse) == "function" then
                pcall(sampSendDialogResponse, dlgId, 1, -1, "")
            elseif type(sampCloseCurrentDialogWithButton) == "function" then
                pcall(sampCloseCurrentDialogWithButton, 1)
            end
        end
    end

    -- ---------- {punishments}: наказания в ответе автопилота ----------

    -- Текст вместо {punishments}: строки окна через « | », а если активных
    -- наказаний нет — короткая фраза (своё предложение админ пишет сам).
    QR.autoPunText = function(lines)
        if type(lines) ~= "table" or #lines == 0 then return "нет активных наказаний" end
        return table.concat(lines, " | ")
    end

    -- «Ответ только про наказания»: тот же текст, что у кнопки
    -- «Наказания игрока» — «Приветствую, ваши активные наказания >> …».
    QR.autoPunWrap = function(txt)
        local str = tostring(txt or "")
        if str == "" or str == "нет активных наказаний" then
            return "Приветствую, активных наказаний у вас нет."
        end
        return "Приветствую, ваши активные наказания >> " .. str
    end

    -- Подстановка вместо {punishments}. Список приходит из окна сервера,
    -- поэтому заменяем через функцию: в нём могут быть «%».
    QR.autoPunFill = function(line, txt)
        local str = tostring(line or "")
        if trim(str) == "{punishments}" then return QR.autoPunWrap(txt) end
        str = str:gsub("{punishments}", function() return tostring(txt or "") end)
        return oneLine(trim(str))
    end

    -- Окно /getinfo пришло (или не пришло): подставляем наказания в ответы
    -- вкладок и отправляем план. Возвращает true, если ожидание было нашим.
    QR.autoPunAbsorb = function(lines)
        local A = QR.auto
        local P = A and A.pend
        if not (P and P.on) then return false end
        A.pend = nil
        local txt = lines and QR.autoPunText(lines) or "нет данных о наказаниях"
        local plan = P.plan or {}
        local wrote = false
        for k = 1, #plan do
            local it = plan[k]
            if it.pun then
                it.line = QR.autoPunFill(it.line, txt)
                wrote = true
            end
        end
        if not wrote then return false end
        pcall(QR.autoDeliver, P.id, P.hit, P.tabs, plan)
        if not lines then
            QR.toast("Автопилот: наказания не получены — ответ без списка", "warn", 3.2)
        end
        return true
    end

    -- ---------- слежка: автопилот в ней не работает ----------

    -- Идёт ли сейчас наблюдение. Спрашиваем ИГРУ (тот же опрос, которым
    -- гасится протухший трекинг слежки), а не только свои отметки: если игра
    -- говорит «не в слежке» — паузы нет, и наоборот.
    function QR.autoSpectating()
        local P = _G.grndSpecProbeState
        if type(P) == "function" then
            local ok, st = pcall(P)
            if ok and st == true then return true end
            if ok and st == false then return false end
        end
        -- игра ответить не смогла — смотрим свои отметки
        local S = _G.GRND_SPEC
        if type(S) == "table" and S.active and S.id then return true end
        local N = _G.grndSpecNative
        if type(N) == "table" and N.camOn then return true end
        if type(grndCamSpectating) == "function" then
            local ok, v = pcall(grndCamSpectating)
            if ok and v then return true end
        end
        return false
    end

    -- Почему автопилот сейчас НА ПАУЗЕ (или nil). Слежка и мероприятие — не
    -- повод выключать настройку: тумблер остаётся включённым, ответы просто
    -- ждут. В слежке телепорт сломал бы наблюдение, на мероприятии ответы
    -- админам-МП не нужны — автопилот молчит и возвращается сам, когда
    -- причина уходит.
    function QR.autoPauseReason()
        if QR.autoSpectating() then return "слежка" end
        local M = _G.GRND_MP
        if type(M) == "table" and M.active then return "мероприятие" end
        return nil
    end

    -- Обновляет состояние паузы и сообщает о переходах тостами.
    -- Возвращает причину паузы или nil.
    function QR.autoPauseTick()
        QR.autoEnsure()
        local A = QR.auto
        local reason = QR.autoPauseReason()
        if reason ~= A.paused then
            A.paused = reason
            if A.on then
                if reason == "слежка" then
                    QR.toast("Автопилот на паузе: слежка", "warn", 3.2)
                elseif reason == "мероприятие" then
                    QR.toast("Автопилот на паузе: идёт мероприятие", "warn", 3.2)
                else
                    QR.toast("Автопилот снова работает", "ok", 2.6)
                end
            end
        end
        return reason
    end

    -- Включение/выключение автопилота тумблером.
    function QR.autoSet(on)
        QR.autoEnsure()
        local A = QR.auto
        on = on and true or false
        if A.on == on then return A.on end
        A.on = on
        A.paused = on and QR.autoPauseReason() or nil
        pcall(QR.autoSave)
        if on then
            if A.paused == "слежка" then
                QR.toast("Автопилот включён · пауза: слежка", "ok", 2.8)
            elseif A.paused == "мероприятие" then
                QR.toast("Автопилот включён · пауза: мероприятие", "ok", 2.8)
            else
                QR.toast("Автопилот включён", "ok", 2.6)
            end
        else
            QR.toast("Автопилот выключен", "info", 2.4)
        end
        return A.on
    end

    -- Пауза и предохранители. Возвращает причину пропуска или nil.
    function QR.autoGuard(now)
        local A = QR.auto
        now = tonumber(now) or os.clock()
        -- ждём окно /getinfo по {punishments}: второй репорт подождёт,
        -- иначе два запроса наказаний перепутаются
        local W = A.pend
        if W and W.on then
            if now - (W.at or 0) > 12 then
                A.pend = nil                 -- окно потерялось: снимаем ожидание
                pcall(QR.punCancel)
            else
                return "ждём ответ на /getinfo"
            end
        end
        if now - (A.lastAt or 0) < AUTO_GAP then return "слишком часто" end
        -- v1.19.42: антидубля «этому игроку уже отвечали» больше НЕТ. Если
        -- игрок написал ещё раз — он ждёт ответа, и пропускать его нельзя:
        -- ответ на прошлый репорт не делает следующий лишний.
        -- v1.19.49: лимит «12 ответов в минуту» убран — темп держит только
        -- пауза между срабатываниями, число ответов не ограничено.
        return nil
    end

    -- ---------- само срабатывание ----------

    -- Вызывается разбором репортов на каждый пришедший репорт.
    -- Возвращает: сработал ли (bool) и пояснение (что ушло или почему нет).
    function QR.autoOnReport(nick, pid, msg)
        QR.autoEnsure()
        local A = QR.auto
        nick, pid = tostring(nick or ""), tostring(pid or "")
        local text = autoPlain(msg)
        A.lastReport = utf8Cut(tostring(nick) .. ": " .. text, 60)
        if not A.on then
            A.lastCheck = "выключен"
            return false, "выключен"
        end
        -- слежка / мероприятие: молчим, но настройку не трогаем — пауза.
        -- v1.19.35: решение принимается после поиска триггера: вкладка «без
        -- команды» отвечает даже в слежке — /ans наблюдению не мешает,
        -- а телепорт (/sp или /goto) слежку бы сломал.
        local pause = QR.autoPauseTick()
        local id = pid:match("^%d+$")
        if not id then
            A.lastCheck = "в репорте нет ID игрока"
            return false, "нет ID"
        end
        if text == "" then
            A.lastCheck = "пустой текст репорта"
            return false, "пусто"
        end
        local hits, droppedTrig = QR.autoMatchAll(text)
        A.lastDropped = droppedTrig or ""
        if #hits == 0 then
            if pause then
                A.lastCheck = "пауза: " .. pause
                return false, pause
            end
            A.lastCheck = "триггер не найден в «" .. utf8Cut(text, 40) .. "»"
            return false, "нет триггера"
        end
        -- v1.19.36: {ID} — ID из текста репорта («дм 234» → 234); если он
        -- найден, вкладка уходит в слежку (/sp ID) даже при команде /goto.
        local foundId = QR.autoFindReportId(text)
        -- v1.19.45: ник и ID — того, НА КОГО пожаловались, а не автора строки
        -- (раньше в «слежу за игроком Ник[ID]» подставлялся ник автора репорта
        -- и получалась смесь: ник репортёра + ID нарушителя).
        local tNick, tId = QR.autoTargetOf(text, foundId)
        if tId and not foundId then foundId = tId end
        if pause then
            -- слежка: молчат вкладки, которые после ответа что-то делают
            -- (своя команда /sp|/goto или автослежка /sp по {ID}) — телепорт
            -- сломал бы наблюдение; вкладки совсем без команды отвечают,
            -- /ans наблюдению не мешает. Мероприятие — полная пауза.
            if pause == "слежка" then
                local keep = {}
                for k = 1, #hits do
                    local tab = QR.autoTab(hits[k].idx)
                    -- слово с {punishments} команды не шлёт — наблюдению оно
                    -- не мешает и отвечать может
                    local wouldCmd = (not hits[k].pun) and QR.autoTabCmd(id, tab, foundId)
                    if not wouldCmd then
                        keep[#keep + 1] = hits[k]
                    end
                end
                if #keep == 0 then
                    A.lastCheck = "пауза: слежка"
                    return false, "слежка"
                end
                hits = keep
            else
                A.lastCheck = "пауза: " .. pause
                return false, pause
            end
        end
        local hit = hits[1].trig
        local hitTabs = {}
        for k = 1, #hits do hitTabs[k] = tostring(hits[k].idx) end
        local hitTabsTxt = table.concat(hitTabs, ", ")
        -- v1.19.25: срабатывают все вкладки с этим триггером, по порядку
        A.lastCheck = "триггер «" .. hit .. "» найден: вкладки " .. hitTabsTxt
            .. (droppedTrig ~= "" and (" · позже «" .. droppedTrig .. "» (пропущено)") or "")
        if type(grndIsTyping) == "function" then
            local okT, typing = pcall(grndIsTyping)
            if okT and typing then
                A.lastCheck = "идёт ввод текста — пропуск"
                QR.toast("Автопилот: пропуск — открыт чат или ввод", "warn", 2.8)
                return false, "ввод"
            end
        end
        local guard = QR.autoGuard(os.clock())
        if guard then
            A.lastCheck = "пропуск: " .. guard
            return false, guard
        end

        -- Что уйдёт игроку и на сервер: сначала собираем план по всем
        -- совпавшим вкладкам (пустые вкладки в план не попадают).
        -- v1.19.46: удалось ли назвать того, на кого пожаловались? Если в
        -- репорте нет ни номера, ни имени — называть некого: в ответе не
        -- должно быть ни ника, ни ID (ушёл бы ник автора или его ID).
        -- кто-то назван, если в репорте есть номер («дм 234») или ник, который
        -- нашёлся среди подключённых; иначе называть некого
        local hasTarget = (foundId ~= nil and foundId ~= "") or (tNick ~= nil and tNick ~= "")
        local rep = { nick = tNick or "", author = nick, id = id, foundId = foundId }
        local repNone = { nick = "", author = nick, id = "", foundId = "" }
        local repAns = hasTarget and rep or repNone
        local plan = {}
        for k = 1, #hits do
            local tab = QR.autoTab(hits[k].idx)
            local hasAll = select(2, QR.autoVarFlags(tab))
            -- {punishments} в ОТВЕТЕ — в текст подставляется список наказаний;
            -- в триггере {punishments} живёт на своём слове (см. punOnly выше)
            local ansHasPun = autoLower(tostring(tab.answer or "")):find("{punishments}", 1, true) ~= nil
            -- v1.19.41: {punishments} в ТРИГГЕРЕ — поле ответа не нужно,
            -- отвечаем ровно как кнопка «Наказания игрока». Текст соберётся,
            -- когда окно /getinfo придёт (маркер ниже).
            -- v1.19.55: переменные считаем по ПОДОШЕДШЕМУ слову, а не по всей
            -- строке триггеров: «…{punishments}, помогите» — слово «помогите»
            -- отвечает своим текстом и выполняет свою команду
            local punOnly = hits[k].pun and true or false
            -- v1.19.44: {ID} на слове в ТРИГГЕРЕ — ответ собирается сам:
            -- «Приветствую, слежу за игроком Ник[ID]», что бы ни было в поле
            local idAuto = (not punOnly) and (hits[k].idv and true or false)
            local line, pun
            if punOnly then
                line = "{punishments}"
                pun = true
            elseif idAuto and hasTarget then
                line = QR.autoGreet(rep)
                -- поле ответа не используется — и его {punishments} тоже
                pun = false
            elseif idAuto then
                -- в репорте нет ни номера, ни имени: отвечаем своим текстом из
                -- настроек, а {ник}/{ID} вычищаем — указывать некого
                line = QR.autoWhoStrip(oneLine(QR.apply(tab.answer, repNone)))
                pun = false
            else
                -- v1.19.46: нет ни номера, ни имени — ник и ID не подставляем
                line = QR.autoWhoStrip(oneLine(QR.apply(tab.answer, repAns)))
                if hasAll then
                    -- {all} — служебный: из текста ответа убираем
                    line = trim((line:gsub("{all}", "", 1)))
                    line = trim((line:gsub("%s+", " ")))
                end
                pun = ansHasPun
            end
            -- слово с {punishments} команду не выполняет (v1.19.52)
            local cmd = nil
            if not punOnly then cmd = QR.autoTabCmd(id, tab, foundId) end
            if line ~= "" or cmd then
                plan[#plan + 1] = { idx = hits[k].idx, line = line, cmd = cmd, pun = pun }
            end
        end
        if #plan == 0 then
            A.lastCheck = "вкладки " .. hitTabsTxt .. ": не заполнены ответ и команда"
            return false, "пусто"
        end

        -- {punishments}: сначала спрашиваем сервер (/getinfo ID) и ждём окно
        -- «Активные наказания игрока» — ответ уйдёт, когда список придёт.
        local needPun = false
        for k = 1, #plan do
            if plan[k].pun then needPun = true end
        end
        if needPun then
            if QR.punBegin(id, nick, "auto") then
                A.pend = { on = true, at = os.clock(), id = id, hit = hit,
                    tabs = hitTabsTxt, plan = plan }
                A.lastCheck = "ждём окно /getinfo: «" .. hit .. "»"
                -- запрос наказаний всегда настоящий (окно перехватывается и
                -- игроку не показывается) — иначе списка не получить
                QR.queueCmd("/getinfo " .. id)
                QR.toast("Автопилот: читаю активные наказания игрока " .. id, "info", 2.6)
                return true, "наказания"
            end
            -- окно уже смотрит кнопка «Наказания игрока»: отвечаем без списка
            for k = 1, #plan do
                local it = plan[k]
                if it.pun then it.line = QR.autoPunFill(it.line, "нет данных о наказаниях") end
            end
            QR.toast("Автопилот: список наказаний уже запрашивается — ответ без него",
                "warn", 3.2)
        end

        -- Отправляем строго по порядку вкладок — так «/ans ID текст» каждой
        -- вкладки встаёт в очередь перед её же командой.
        return QR.autoDeliver(id, hit, hitTabsTxt, plan)
    end

    -- v1.19.56: БОЕВОЙ РЕЖИМ. Слоя проверки (/n) больше нет: автопилот и
    -- ручной ответ из окна репорта уходят настоящими строками — «/ans ID текст»
    -- (для репорта от бота — «/pm ID текст»), команды вкладок («/sp», «/goto»)
    -- и запрос наказаний (/getinfo) выполняются как есть, игроки получают ответ.

    -- Отправка готового плана: /ans каждой вкладки и её команда, по порядку
    -- вкладок. Сюда же — предохранители (после отправки) и тост.
    function QR.autoDeliver(id, hit, tabsTxt, plan)
        local A = QR.auto
        local sentAns, sentCmd, cmdTxt, planTabs = 0, 0, {}, {}
        for k = 1, #plan do
            local it = plan[k]
            if it.line ~= "" then
                -- длинный список наказаний уходит несколькими сообщениями
                -- (у строки чата есть лимит длины)
                local chunks = autoChunks(it.line)
                for ci = 1, #chunks do
                    local sent = false
                    if type(grndRepAnswer) == "function" then
                        -- grndRepAnswer сам переводит текст в CP1251 и ставит
                        -- «/ans ID …» (для репорта от бота — его «/pm ID …»)
                        -- в очередь репорта
                        local okA, res = pcall(grndRepAnswer, id, chunks[ci])
                        sent = okA and res ~= false
                    end
                    -- запасной путь, если grndRepAnswer недоступен: та же
                    -- боевая строка через очередь репорта
                    if not sent and QR.queueCmd(QR.autoAnsCmd(id, chunks[ci])) then
                        sent = true
                    end
                    if sent then sentAns = sentAns + 1 end
                end
            end
            if it.cmd then
                -- команда вкладки уходит настоящей: «/sp ID», «/goto ID» и т.п.
                if QR.queueCmd(it.cmd) then sentCmd = sentCmd + 1 end
                cmdTxt[#cmdTxt + 1] = it.cmd
            end
            planTabs[#planTabs + 1] = tostring(it.idx)
        end

        local now = os.clock()
        A.lastAt = now
        A.fired = (A.fired or 0) + 1
        local planTabsTxt = table.concat(planTabs, ", ")
        local sentOk = (sentAns + sentCmd) > 0
        A.lastCheck = sentOk
            and ("отправлено (вкладки " .. planTabsTxt
                .. "), триггер «" .. tostring(hit) .. "»"
                .. (tabsTxt ~= planTabsTxt and (" · план " .. tostring(tabsTxt)) or "")
                .. (A.lastDropped ~= "" and (" · позже «" .. A.lastDropped .. "»") or ""))
            or "не удалось отправить"
        if sentOk then
            local cmds = table.concat(cmdTxt, " + ")
            -- тост короткий и всегда одинаковый: «Автопилот: /ans 25 + /sp 25 · «дм»»
            QR.toast("Автопилот: /ans " .. id .. (cmds ~= "" and (" + " .. cmds) or "")
                    .. " · «" .. tostring(hit) .. "»"
                    .. (#plan > 1 and (" · вкладок " .. tostring(#plan)) or ""),
                "ok", 3.6)
        else
            QR.toast("Автопилот: отправить не удалось", "warn", 3)
        end
        return sentOk, hit
    end

    -- Тик из основного цикла: задержанное сохранение и слежение за паузой
    -- (слежка, мероприятие). Как только причина уходит — автопилот сам
    -- продолжает работать, тумблер не трогаем.
    function QR.autoTick()
        QR.autoEnsure()
        local A = QR.auto
        local now = os.clock()
        if A.dirtyAt and (now - A.dirtyAt) > 0.6 then
            pcall(QR.autoSave)
        end
        if not A.on then
            A.paused = nil
            return false
        end
        local reason = QR.autoPauseTick()
        return reason ~= nil
    end

    -- ---------- отрисовка вкладки ----------

    -- «Сырая» мышь над прямоугольником в локальных координатах окна.
    local function autoMouseOver(im, x, y, w, h)
        local M = _G and _G.GRND_MOUSE
        if type(M) ~= "table" then return false end
        local mx, my = tonumber(M.x) or -1, tonumber(M.y) or -1
        local wp = nil
        if type(im.GetWindowPos) == "function" then
            local okP, p = pcall(im.GetWindowPos)
            if okP then wp = p end
        end
        local px, py = (wp and wp.x or 0), (wp and wp.y or 0)
        local sx, sy = px + x, py + y
        return mx >= sx and mx <= sx + w and my >= sy and my <= sy + h
    end

    -- Клик «мимо» списка команд — закрыть список (координаты локальные).
    local function autoOutsideClick(im, x, y, w, h)
        local alive = _G and _G.grndClickAlive
        if type(alive) ~= "function" then return false end
        local ok, hit = pcall(alive)
        if not (ok and hit) then return false end
        return not autoMouseOver(im, x, y, w, h)
    end

    -- Тумблер: родная «пилюля» скрипта (grndUiSwitchPaint), а если её нет
    -- (стенды, урезанные сборки) — своя простая.
    local function autoSwitch(ctx, x, y, on, id)
        local im = ctx.im
        im.SetCursorPos(im.ImVec2(x, y))
        local clicked = im.InvisibleButton(id, im.ImVec2(46, 24)) and true or false
        local hov = (im.IsItemHovered and im.IsItemHovered()) or false
        local TH = theme()
        local ac = TH.accent or { 164, 112, 224, 255 }
        local paint = _G.grndUiSwitchPaint
        if type(paint) == "function" then
            pcall(paint, { dl = ctx.dl, at = ctx.at, col32 = ctx.col32,
                           roundRect = ctx.roundRect }, x, y, on, hov, id, 0.05)
        else
            ctx.roundRect(ctx.dl, ctx.at(x + 1, y + 7), ctx.at(x + 45, y + 17),
                ctx.col32(255, 255, 255, on and 40 or 16), 8)
            local kx = on and (x + 29) or (x + 17)
            ctx.roundRect(ctx.dl, ctx.at(kx - 8, y + 7), ctx.at(kx + 8, y + 17),
                ctx.col32(ac[1], ac[2], ac[3], on and 235 or 120), 8)
        end
        return clicked
    end

    _G.grndQrAutoDraw = function(ctx)
        if type(ctx) ~= "table" then return false end
        local im = ctx.im
        if not (im and ctx.uiText and ctx.roundRect and ctx.col32 and ctx.rgba and ctx.at) then
            return false
        end
        local TH = theme()
        QR.autoEnsure()
        local A = QR.auto
        local tabs = QR.autoTabs()
        local x, y, w, h = ctx.x, ctx.y, ctx.w, ctx.h
        if not (x and y and w and h) or w < 320 or h < 200 then return false end

        -- v1.19.51: y — абсолютная координата раздела в окне, h — его высота,
        -- поэтому низ раздела — это (y + h). Раньше в проверках снизу
        -- использовалась одна h, из-за чего блок внизу «не помещался» и
        -- подсказки про переменные пропадали вовсе.
        local bottomY = y + h - 6
        local hi  = ctx.col32(TH.textHi[1], TH.textHi[2], TH.textHi[3], 255)
        local dim = ctx.col32(TH.textDim[1], TH.textDim[2], TH.textDim[3], 255)
        local mut = ctx.col32(TH.textMuted[1], TH.textMuted[2], TH.textMuted[3], 255)
        local ac  = TH.accent or { 164, 112, 224, 255 }
        local acC = ctx.col32(ac[1], ac[2], ac[3], 255)
        local warnC = ctx.col32(255, 176, 96, 255)
        local okC   = ctx.col32(120, 220, 160, 255)

        -- ---------- шапка: название и состояние, справа тумблер ----------
        -- v1.19.50: в невысоком окне шапка компактнее (состояние — в строке с
        -- названием): место внизу нужно подсказкам про переменные
        local compact = h < 540
        ctx.uiText(x, y + 1, "Автопилот", hi, 1.0)

        local on = A.on and true or false
        local paused = on and (A.paused or QR.autoPauseReason()) or nil
        -- v1.19.55: надписи «включён/выключен» больше нет — состояние видно по
        -- тумблеру; текст показываем только когда автопилот НА ПАУЗЕ
        local stateTxt
        if paused == "слежка" then
            stateTxt = "на паузе — слежка, вернётся сам"
        elseif paused == "мероприятие" then
            stateTxt = "на паузе — идёт мероприятие, вернётся сам"
        elseif paused then
            stateTxt = "на паузе — " .. tostring(paused)
        end
        -- без строки состояния полоса вкладок поднимается на её место
        local tabsTop = y + 30
        if stateTxt then
            ctx.dl:AddCircleFilled(ctx.at(x + 8, y + 42), 5, warnC)
            ctx.uiText(x + 22, y + 32,
                fit(stateTxt, math.max(70, w - 84), ctx.drawnW, 0.95), warnC, 0.95)
            tabsTop = y + 62
        end
        if autoSwitch(ctx, x + w - 56, y + 3, on, "##grnd_qr_auto_on") then
            QR.autoSet(not on)
        end

        -- ---------- полоса вкладок ----------
        -- Каждая вкладка — один триггер со своим ответом и командой. Вкладок
        -- может быть много, поэтому полоса переносится на след. строку, а не
        -- вылезает за окно.
        -- Крестик и плюс рисуем линиями: символы «×» и «＋» есть не во всех
        -- шрифтах (показывались как «?» либо пустое место).
        local function autoCross(cx, cy, r, col)
            if not ctx.dl.AddLine then return false end
            local a = pcall(ctx.dl.AddLine, ctx.dl, ctx.at(cx - r, cy - r), ctx.at(cx + r, cy + r), col, 1.4)
            local b = pcall(ctx.dl.AddLine, ctx.dl, ctx.at(cx + r, cy - r), ctx.at(cx - r, cy + r), col, 1.4)
            return a and b
        end
        local function autoPlus(cx, cy, r, col)
            if not ctx.dl.AddLine then return false end
            local a = pcall(ctx.dl.AddLine, ctx.dl, ctx.at(cx - r, cy), ctx.at(cx + r, cy), col, 1.6)
            local b = pcall(ctx.dl.AddLine, ctx.dl, ctx.at(cx, cy - r), ctx.at(cx, cy + r), col, 1.6)
            return a and b
        end

        local tabH, tgap, tcw = 30, 6, 26     -- tcw — полоска крестика справа
        local tabW = math.floor((w - tgap * (#tabs - 1)) / #tabs)
        if tabW > 190 then tabW = 190 end
        if tabW < 96 then tabW = 96 end
        local tx, ty = x, tabsTop
        local pendingDel = nil
        for i = 1, #tabs do
            if tx + tabW > x + w + 0.5 then tx, ty = x, ty + tabH + tgap end
            local sel = (i == A.sel)
            -- вкладка и крестик — две отдельные зоны, поэтому «удалить» не
            -- срабатывает при выборе вкладки (и наоборот)
            im.SetCursorPos(im.ImVec2(tx, ty))
            local tabClick = im.InvisibleButton("##grnd_qr_auto_tab_" .. i,
                im.ImVec2(tabW - tcw, tabH)) and true or false
            local tabHov = (im.IsItemHovered and im.IsItemHovered()) or false
            im.SetCursorPos(im.ImVec2(tx + tabW - tcw, ty))
            local crossClick = im.InvisibleButton("##grnd_qr_auto_tabc_" .. i,
                im.ImVec2(tcw, tabH)) and true or false
            local crossHov = (im.IsItemHovered and im.IsItemHovered()) or false
            local hov = tabHov or crossHov
            ctx.roundRect(ctx.dl, ctx.at(tx, ty), ctx.at(tx + tabW, ty + tabH),
                sel and ctx.col32(ac[1], ac[2], ac[3], 52)
                    or (hov and ctx.col32(255, 255, 255, 22) or ctx.col32(255, 255, 255, 12)), 6)
            if ctx.dl.AddRect then
                pcall(ctx.dl.AddRect, ctx.dl, ctx.at(tx + 0.5, ty + 0.5),
                    ctx.at(tx + tabW - 0.5, ty + tabH - 0.5),
                    sel and ctx.col32(ac[1], ac[2], ac[3], 170) or ctx.col32(255, 255, 255, 46),
                    6, 0, 1)
            end
            local lbl = fit(QR.autoLabel(i), tabW - tcw - 12, ctx.drawnW, 0.88)
            local lw = 0
            if type(ctx.drawnW) == "function" then
                local okM, v = pcall(ctx.drawnW, lbl, 0.88)
                if okM and type(v) == "number" then lw = v end
            end
            ctx.uiText(tx + math.floor((tabW - tcw - lw) / 2), ty + (tabH - lineH(ctx, 0.88)) / 2,
                lbl, sel and hi or dim, 0.88)
            local crossCol = crossHov and ctx.col32(255, 140, 140, 255) or ctx.col32(255, 255, 255, 110)
            if not autoCross(tx + tabW - tcw / 2, ty + tabH / 2, 4, crossCol) then
                ctx.uiText(tx + tabW - tcw / 2 - 3, ty + (tabH - lineH(ctx, 0.8)) / 2, "x",
                    crossCol, 0.8)
            end
            if crossClick then
                pendingDel = i
            elseif tabClick and not sel then
                A.sel = i
                A.listOpen = false
            end
            tx = tx + tabW + tgap
        end
        -- плюс в круглом фоне — сразу после последней вкладки
        local plusD = tabH
        if tx + plusD > x + w + 0.5 then tx, ty = x, ty + tabH + tgap end
        im.SetCursorPos(im.ImVec2(tx, ty))
        local plusClick = im.InvisibleButton("##grnd_qr_auto_add", im.ImVec2(plusD, plusD)) and true or false
        local plusHov = (im.IsItemHovered and im.IsItemHovered()) or false
        local pcx, pcy = tx + plusD / 2, ty + plusD / 2
        ctx.dl:AddCircleFilled(ctx.at(pcx, pcy), plusD / 2,
            ctx.col32(ac[1], ac[2], ac[3], plusHov and 90 or 46))
        -- светлое кольцо: два круга (AddCircle есть не во всех сборках)
        ctx.dl:AddCircleFilled(ctx.at(pcx, pcy), plusD / 2 - 1.5,
            ctx.col32(18, 17, 23, plusHov and 150 or 90))
        if not autoPlus(pcx, pcy, 6,
            plusHov and ctx.col32(255, 255, 255, 255) or ctx.col32(ac[1], ac[2], ac[3], 235)) then
            ctx.uiText(pcx - 4, pcy - lineH(ctx, 1.0) / 2, "+",
                plusHov and hi or acC, 1.0)
        end
        -- действие применяем после отрисовки: список вкладок в этом кадре
        -- остаётся целым, а на следующем кадре рисуется уже новый
        if plusClick then QR.autoAdd() end
        if pendingDel then QR.autoDel(pendingDel) end

        -- ---------- поля выбранной вкладки ----------
        local yy = ty + tabH + 14
        local iw = w
        -- v1.19.50: если места мало, строка-предпросмотр не рисуется — её
        -- высота уходит подсказкам про переменные
        local dropPreview = false
        -- v1.19.51–53: если и этого мало, убираем оранжевое пояснение под
        -- полем ответа (внизу про переменные всё равно написано)
        local hideAnsNote = false
        -- v1.19.50: внизу раздела — подсказки ТОЛЬКО про переменные.
        -- v1.19.53: каждая переменная объяснена своей строкой — понятно и тем,
        -- кто запустил скрипт впервые
        local varHints = {
            "Переменные — в ответе или на слове триггера: «дм{ID}», «спек{all}»",
            "{ID} — игрок из репорта: номер из жалобы или ник из текста",
            "{all} — слово сработает, даже если репорт из нескольких слов",
            "{punishments} — вместо ответа придёт список наказаний игрока (команда не выполнится)",
        }
        -- v1.19.51: запасной вариант одной строкой — для очень тесного окна,
        -- когда строки не помещаются (подсказка всё равно должна быть видна)
        local varHintsShort = {
            "Переменные: {ID} — игрок из репорта; {all} — слово в любом месте репорта; "
                .. "{punishments} — наказания игрока (команда не выполнится)",
        }
        -- v1.19.53: сперва расшифровка раздела — что вообще делает вкладка
        local tHintSc = 0.72
        local tHintStep = lineH(ctx, tHintSc) + 2
        local intro = wrapW(
            "Вкладка — это слово из репорта: нашлось в жалобе — игроку уходит ответ, затем команда.",
            iw, ctx.drawnW, tHintSc)
        for li = 1, #intro do
            ctx.uiText(x, yy + (li - 1) * tHintStep, intro[li], mut, tHintSc)
        end
        yy = yy + math.max(1, #intro) * tHintStep + 8
        -- v1.19.26: у поля «Триггер» нет подписи про длину — короткий триггер
        -- разрешён. v1.19.34: подсказка про синонимы стоит СРАЗУ ПОСЛЕ названия
        -- «Триггер» (над полем ввода), длинная фраза переносится по словам,
        -- поэтому помещается целиком.
        ctx.uiText(x, yy, "Триггер", dim, 0.84)
        local sel2 = QR.autoTab()
        yy = yy + 17
        -- сперва что такое триггер, затем — подсказка про похожие слова
        -- (каноническая строка идёт отдельным блоком, чтобы не рвалась)
        local trigHint = wrapW("Слово, по которому вкладка узнаёт свой репорт.",
            iw, ctx.drawnW, tHintSc)
        local trigHint2 = wrapW(
            "Можно ввести триггер и похожие слова к триггеру (через запятую), "
                .. "на которые скрипт тоже так будет реагировать",
            iw, ctx.drawnW, tHintSc)
        local ky = yy
        for li = 1, #trigHint do
            ctx.uiText(x, ky, trigHint[li], mut, tHintSc)
            ky = ky + tHintStep
        end
        for li = 1, #trigHint2 do
            ctx.uiText(x, ky, trigHint2[li], mut, tHintSc)
            ky = ky + tHintStep
        end
        yy = ky + 4
        -- v1.19.54: строка триггеров — во всю ширину раздела (была 360 px),
        -- в неё помещается сколько угодно слов через запятую
        local trigW = iw
        local tkey, tid = "autoTrigger" .. A.sel, "##grnd_qr_auto_trigger"
        field(ctx, tid, tkey, TRIG_CAP, x, yy, trigW, 28, "", false, sel2.trigger)
        local trigVal = trim(bufText(tkey))
        if trigVal ~= sel2.trigger then
            sel2.trigger = trigVal
            A.dirtyAt = os.clock()
        end
        yy = yy + 40

        -- v1.19.55: переменные действуют на своё слово, поэтому в подсказках
        -- смотрим и на слова без переменных («остальные слова»)
        local selPun = QR.autoPunInTrigger(sel2)
        local selID = QR.autoIDInTrigger(sel2)
        local selFree = QR.autoPlainWords(sel2) > 0
        -- текст из «Ответ игроку» вообще не используется только когда все
        -- слова с {punishments} (и нет слов с {ID})
        local punHard = selPun and not selFree and not selID
        -- высота селектора команды и подсказки к нему — нужны, чтобы заранее
        -- посчитать, сколько места займёт низ раздела
        local selW, selH = math.min(280, iw), 30
        local cmdHintSc = 0.72
        -- v1.19.53: подсказка говорит о выбранном варианте, а не обо всех сразу
        local cmdHintNone = (QR.autoCmdId(sel2.command) == "none")
        local cmdHintText = cmdHintNone
            and "«Без команды»: вкладка ответит даже в слежке"
            or "Выполнится сразу после ответа"
        local cmdHintW = iw - selW - 12
        local cmdHintX = x + selW + 12
        -- v1.19.51: узкая колонка справа от селектора растягивает подсказку в
        -- длинный «столбик» коротких строк и съедает низ раздела — тогда она
        -- уходит под селектор и переносится по всей ширине
        if cmdHintW < 120
            or #wrapW(cmdHintText, cmdHintW, ctx.drawnW, cmdHintSc) > 2 then
            cmdHintX, cmdHintW = x, iw
        end
        local cmdHintLines = wrapW(cmdHintText, cmdHintW, ctx.drawnW, cmdHintSc)
        local cmdHintStep = lineH(ctx, cmdHintSc) + 2

        -- v1.19.53: пояснение под полем. Поле «Ответ игроку» видно ВСЕГДА —
        -- даже когда его текст не пригодится ({punishments} в триггере или {ID})
        local ansNote, ansNoteCol
        if punHard then
            ansNote = "Этот текст не используется: в триггере {punishments} — игрок получит "
                .. "список своих наказаний, а команда не выполнится."
            ansNoteCol = warnC
        elseif selPun then
            ansNote = "Слова с {punishments} отвечают списком наказаний (без команды); "
                .. "остальные слова — этот текст и команда."
            ansNoteCol = warnC
        elseif selID and not selFree then
            ansNote = "Ответ собирается сам: «Приветствую, слежу за игроком Ник[234]» — "
                .. "этот текст уйдёт, только если в репорте нет ни номера, ни имени."
            ansNoteCol = warnC
        elseif selID then
            ansNote = "Слова с {ID} отвечают авто-приветствием и /sp; "
                .. "остальные слова — этот текст и команда."
            ansNoteCol = warnC
        end
        local ansNoteLines = ansNote and wrapW(ansNote, iw, ctx.drawnW, tHintSc) or nil

        ctx.uiText(x, yy, "Ответ игроку", dim, 0.84)
        yy = yy + 17
        -- у вкладки с {punishments} поле всё равно не используется, поэтому
        -- ему хватает половины высоты — место уходит пояснению и подсказкам
        local ansCap = punHard and 64 or 92
        local ansH = ansCap
        do
            local noteH0 = ansNoteLines and (#ansNoteLines * tHintStep) or 0
            local chH0 = math.max(selH,
                ((cmdHintX == x) and (selH + 6) or 0)
                    + math.max(1, #cmdHintLines) * cmdHintStep) + 10
            local minSc = 0.36
            local minStep = lineH(ctx, minSc) + 3
            -- запас снизу — по полному набору подсказок: он важнее, а короткая
            -- однострочная версия остаётся запасным вариантом для тесного окна
            local minRows = 0
            for hi = 1, #varHints do
                minRows = minRows + #wrapW(varHints[hi], iw, ctx.drawnW, minSc)
            end
            local minBlock = math.max(lineH(ctx, minSc),
                (minRows - 1) * minStep + lineH(ctx, minSc))
            local prevH0 = lineH(ctx, 0.86)
            local reserve = 6 + noteH0 + 12 + 17 + chH0 + prevH0 + 6 + minBlock + 6
            ansH = math.max(40, math.min(ansCap, math.floor(bottomY - yy - reserve)))
            if yy + ansH + reserve > bottomY and not dropPreview then
                -- совсем мало места: строку-предпросмотр убираем целиком
                dropPreview = true
                reserve = reserve - prevH0
                ansH = math.max(40, math.min(ansCap, math.floor(bottomY - yy - reserve)))
            end
            if yy + ansH + reserve > bottomY and ansNoteLines then
                -- и пояснение под полем: про переменные рассказано в подсказках внизу
                hideAnsNote = true
                reserve = reserve - noteH0
                ansH = math.max(40, math.min(ansCap, math.floor(bottomY - yy - reserve)))
            end
        end
        local akey, aid = "autoAnswer" .. A.sel, "##grnd_qr_auto_answer"
        field(ctx, aid, akey, 1024, x, yy, iw, ansH, "Приветствую, уже смотрю…", true, sel2.answer)
        local ansVal = clampText(cleanText(bufText(akey)), MAX_TEXT)
        if ansVal ~= sel2.answer then
            sel2.answer = ansVal
            A.dirtyAt = os.clock()
        end
        yy = yy + ansH + 6
        if ansNoteLines and not hideAnsNote then
            for li = 1, #ansNoteLines do
                ctx.uiText(x, yy + (li - 1) * tHintStep, ansNoteLines[li], ansNoteCol, tHintSc)
            end
            yy = yy + #ansNoteLines * tHintStep
        end
        yy = yy + 12

        ctx.uiText(x, yy, "Команда после ответа", dim, 0.84)
        yy = yy + 17
        local selY = yy
        im.SetCursorPos(im.ImVec2(x, selY))
        local selClick = im.InvisibleButton("##grnd_qr_auto_cmd", im.ImVec2(selW, selH)) and true or false
        local selHov = (im.IsItemHovered and im.IsItemHovered()) or false
        ctx.roundRect(ctx.dl, ctx.at(x, selY), ctx.at(x + selW, selY + selH),
            (selHov or A.listOpen) and ctx.col32(255, 255, 255, 26) or ctx.col32(255, 255, 255, 12), 6)
        if ctx.dl.AddRect then
            pcall(ctx.dl.AddRect, ctx.dl, ctx.at(x + 0.5, selY + 0.5),
                ctx.at(x + selW - 0.5, selY + selH - 0.5),
                (selHov or A.listOpen) and ctx.col32(ac[1], ac[2], ac[3], 150)
                    or ctx.col32(255, 255, 255, 46), 6, 0, 1)
        end
        ctx.uiText(x + 10, selY + (selH - lineH(ctx, 0.9)) / 2, QR.autoCmdLabel(sel2.command), hi, 0.9)
        tri(ctx.dl, ctx.at, x + selW - 14, selY + selH / 2, 4, "down",
            (selHov or A.listOpen) and acC or mut)
        if selClick then A.listOpen = not A.listOpen end
        -- v1.19.35: оранжевая подсказка правее селектора — вкладка «без
        -- команды» отвечает даже в слежке. Если справа места мало, подсказка
        -- уходит под селектор.
        local cmdHintTop = (cmdHintX == x) and (selY + selH + 6) or selY
        for li = 1, #cmdHintLines do
            ctx.uiText(cmdHintX, cmdHintTop + (li - 1) * cmdHintStep,
                cmdHintLines[li], cmdHintNone and warnC or mut, cmdHintSc)
        end
        yy = math.max(selY + selH, cmdHintTop + math.max(1, #cmdHintLines) * cmdHintStep) + 10

        -- одна строка-предпросмотр вместо отдельной карточки
        local repId = ""
        if type(_G.GRND_REP) == "table" then repId = tostring(_G.GRND_REP.playerId or "") end
        local sampleId = repId:match("^%d+$") or "25"
        local sampleLine
        if punHard then
            sampleLine = QR.autoPunWrap("Мут 60 минут")
        elseif selID and not selFree then
            sampleLine = QR.autoGreet({ nick = "Ник", id = sampleId })
        else
            sampleLine = oneLine(QR.apply(sel2.answer, { nick = "Ник", id = sampleId }))
        end
        -- v1.19.52–55: команда не уйдёт, когда ВСЕ слова триггера с
        -- {punishments} (тогда вкладка только показывает наказания) —
        -- предпросмотр об этом говорит
        local punNoCmd = punHard
        local cmdLine = (not punNoCmd) and QR.autoCmdFor(sampleId, sel2) or nil
        local prev
        if sampleLine == "" then
            prev = cmdLine and ("ответ пуст — уйдёт только " .. cmdLine) or "пусто: не заполнены ответ и команда"
        else
            -- при {punishments} в триггере текст ответа длинный, поэтому
            -- хвост «команды не будет» важнее — режем пример ответа короче
            prev = "/ans " .. sampleId .. " · " .. utf8Cut(sampleLine, punNoCmd and 24 or 40)
                .. (punNoCmd and " · команды не будет"
                    or (cmdLine and (" · затем " .. cmdLine) or " · команды нет"))
        end
        if not dropPreview then
            ctx.uiText(x, yy, fit(prev, iw, ctx.drawnW, 0.86), sampleLine == "" and warnC or mut, 0.86)
        end

        -- v1.19.36: внизу — подсказки про переменные {ID} и {all}. Текст
        -- постоянный (не зависит от полей вкладки), длинные строки переносятся.
        -- v1.19.50: высота поля ответа подобрана заранее, поэтому блок
        -- помещается; без предпросмотра подсказки начинаются сразу под ним.
        -- v1.19.53: строка диагностики («Репорт: … → …») убрана целиком —
        -- состояние по-прежнему в QR.auto.lastReport/lastCheck (тосты и /mp diag)
        local hintY = yy + (dropPreview and 6 or (lineH(ctx, 0.86) + 6))
        -- Подбираем кегль блока: подсказки (с переносами)
        local hintSc, hintStep, hintLines = nil, 0, nil
        local scales = { 0.72, 0.68, 0.64, 0.60, 0.56, 0.52, 0.48, 0.44, 0.40, 0.36 }
        local hintSets = { varHints, varHintsShort }
        for ss = 1, #hintSets do
            local src = hintSets[ss]
            for si = 1, #scales do
                local sc = scales[si]
                -- шаг с запасом (+3): строки не должны налипать друг на друга
                local step = lineH(ctx, sc) + 3
                local rows, packed = 0, {}
                for hi = 1, #src do
                    local ls = wrapW(src[hi], iw, ctx.drawnW, sc)
                    packed[#packed + 1] = ls
                    rows = rows + #ls
                end
                -- Высота блока — не «rows шагов», а шаги между строками плюс
                -- высота последней: иначе нижняя строка упиралась в край окна.
                local blockH = math.max(lineH(ctx, sc), (rows - 1) * step + lineH(ctx, sc))
                if hintY + blockH <= bottomY then
                    hintSc, hintStep, hintLines = sc, step, packed
                    break
                end
            end
            if hintLines then break end
        end
        -- v1.19.50: подсказки рисуем, только если блок помещается целиком —
        -- в слишком низком окне лучше не показать их вовсе, чем наложить
        -- строки друг на друга или выпустить их за край окна
        if hintLines then
            local hy = hintY
            for hi = 1, #hintLines do
                local ls = hintLines[hi]
                for li = 1, #ls do
                    ctx.uiText(x, hy, ls[li], mut, hintSc)
                    hy = hy + hintStep
                end
            end
        end

        -- Список команд рисуем ПОСЛЕДНИМ: он ложится поверх полей и клики
        -- попадают в него, а не в поле под ним.
        if A.listOpen then
            local ddH = 30
            local ddX, ddY, ddW = x, selY + selH + 4, selW
            local viewH = #AUTO_CMDS * (ddH + 2) - 2
            ctx.roundRect(ctx.dl, ctx.at(ddX - 2, ddY - 2), ctx.at(ddX + ddW + 2, ddY + viewH + 2),
                ctx.col32(16, 17, 24, 252), 8)
            if ctx.dl.AddRect then
                pcall(ctx.dl.AddRect, ctx.dl, ctx.at(ddX - 1.5, ddY - 1.5),
                    ctx.at(ddX + ddW + 1.5, ddY + viewH + 1.5), ctx.col32(255, 255, 255, 34), 8, 0, 1)
            end
            for i = 1, #AUTO_CMDS do
                local d = AUTO_CMDS[i]
                local ryr = ddY + (i - 1) * (ddH + 2)
                im.SetCursorPos(im.ImVec2(ddX, ryr))
                local clicked = im.InvisibleButton("##grnd_qr_auto_cmd_" .. d.id,
                    im.ImVec2(ddW, ddH)) and true or false
                local hov = (im.IsItemHovered and im.IsItemHovered()) or false
                local sel3 = (d.id == QR.autoCmdId(sel2.command))
                ctx.roundRect(ctx.dl, ctx.at(ddX, ryr), ctx.at(ddX + ddW, ryr + ddH),
                    sel3 and ctx.col32(ac[1], ac[2], ac[3], 46)
                        or (hov and ctx.col32(255, 255, 255, 20) or ctx.col32(255, 255, 255, 0)), 6)
                ctx.uiText(ddX + 12, ryr + (ddH - lineH(ctx, 0.9)) / 2, d.label,
                    sel3 and hi or dim, 0.9)
                local hw = 0
                if type(ctx.drawnW) == "function" then
                    local okM, v = pcall(ctx.drawnW, d.hint, 0.78)
                    if okM and type(v) == "number" then hw = v end
                end
                ctx.uiText(ddX + ddW - 12 - hw, ryr + (ddH - lineH(ctx, 0.78)) / 2, d.hint, mut, 0.78)
                if clicked then
                    sel2.command = d.id
                    A.listOpen = false
                    pcall(QR.autoSave)
                end
            end
            -- v1.19.35: клик по самому селектору закрывает список через
            -- selClick; если считать его «кликом мимо», список на нажатии
            -- закрывался, а на отпускании открывался заново («мигал»).
            if autoOutsideClick(im, ddX, ddY, ddW, viewH)
                and not autoMouseOver(im, x, selY, selW, selH) then
                A.listOpen = false
            end
        end
        return true
    end

    -- Разбор строки репорта — вне модуля (там свои локальные лимиты), поэтому
    -- отдаём обе функции наружу под именами скрипта.
    _G.grndRepCountOf = QR.repCountOf
    _G.grndQrAnswerCmd = QR.answerCmd

    -- Глобальные обёртки: их зовут разбор репортов и основной цикл скрипта.
    _G.grndQrAutoOnReport = function(nick, pid, msg)
        local ok, res = pcall(QR.autoOnReport, nick, pid, msg)
        if ok then return res end
        QR.auto.err = tostring(res)
        print("{FF6666}[GRND]{FFFFFF} автопилот: " .. tostring(res))
        return false
    end
    _G.grndQrAutoTick = function()
        local ok, res = pcall(QR.autoTick)
        if ok then return res end
        QR.auto.err = tostring(res)
        return false
    end
end

-- ---------- самопроверка логики (без файлов и ImGui) ----------
function QR.selfTest()
    local fails = {}
    local function eq(name, got, exp)
        if tostring(got) ~= tostring(exp) then
            fails[#fails + 1] = name .. " got=" .. tostring(got) .. " exp=" .. tostring(exp)
        end
    end
    eq("oneLine", oneLine("а\nб\r\nв"), "а б в")
    eq("trim", trim("  тест  "), "тест")
    eq("cleanText", cleanText("а  \r\n\r\nб\r\n"), "а\n\nб")
    eq("apply", QR.apply("Привет, {ник}[{id}]!", { nick = "Игрок", id = "5" }),
        "Привет, Игрок[5]!")
    eq("applyEmpty", QR.apply("Привет, {ник}!", {}), "Привет, {ник}!")
    eq("cut", utf8Cut("привет", 3), "при")
    eq("utf8Len", utf8Len("привет"), 6)
    eq("byteCut", byteCut("привет", 7), "при")   -- 2 байта на букву: 7 -> 3 буквы
    local sample = "строка 1\nстрока 2 \\ назад"
    eq("esc", unesc(esc(sample)), sample)
    local msg
    if #fails == 0 then
        msg = "Шаблоны ответов: проверка пройдена"
        print("{00FFAA}[GRND]{FFFFFF} " .. msg)
    else
        msg = "Шаблоны ответов: ошибок " .. tostring(#fails)
        print("{FF6666}[GRND]{FFFFFF} " .. msg .. " | " .. table.concat(fails, " | "))
    end
    return #fails == 0
end

return QR
end)()

function grndMainBody()
    local okList = {}
    for k, _ in pairs(libs) do okList[#okList + 1] = k end
    -- версия сборки в консоль: по ней видно, что MoonLoader читает НОВЫЙ файл
    do
        local sv = "1.19.36"
        pcall(function() sv = tostring(thisScript().version or sv) end)
        print("{00FFAA}[GRND]{FFFFFF} GRND TOOLS v" .. sv .. ": кнопка репорта, слежка, формы, «Размер окна»")
    end
    print("{00FFAA}[GRND]{FFFFFF} скрипт загружен. Подключено либ: "
        .. (#okList > 0 and table.concat(okList, ", ") or "нет"))
    if #failed > 0 then
        print("{FF6666}[GRND]{FFFFFF} не найдено: " .. table.concat(failed, ", "))
    end
    function grndIsSpawned()
        if not sampIsLocalPlayerSpawned then return false end
        local ok, res = pcall(sampIsLocalPlayerSpawned)
        if ok and res then return true end
        return false
    end
    -- =================================================================
    --  CLICKWARP
    -- =================================================================
    local clw = {
        enabled = true,
        mode = "click",
        keyToggle = 0x04,
        keyApply = 0x01,
        keyVehicle = 0x02,
        aiming = false,
        marker = nil,
        markerColor = 3,
        maxDist = 700.0,
        tx = nil, ty = nil, tz = nil,
        tdist = 0,
        lastX = 0, lastY = 0, lastZ = 0,
        savedX = nil, savedY = nil, savedZ = nil,
    }
    GRND_CONFIG.bindClickwarp(clw)
    clw.activationKeys = { clw.keyToggle }
    -- =============================================================
    --  МОДУЛЬ 8 (v1.2): мышиные кнопки ClickWarp.
    --  keyToggle/keyApply/keyVehicle = 0x04/0x01/0x02 совпадают с VK-кодами
    --  мыши (MBUTTON/LBUTTON/RBUTTON), так что isKeyDown() их видит. Проблемы
    --  были в другом: (1) опрос «фронта нажатия» терялся, если за кадр main()
    --  не успел, (2) при showing-курсоре ImGui тоже съедал ЛКМ, (3) ВКМ-«удер-
    --  жание» не работало вовсе, т.к. никто не отслеживал удержание.
    --  Читаем мышь по цепочке: getMouseState()/isMouseButtonDown() (если их дал
    --  SAMPFUNCS) -> isKeyDown(VK) с фронтом по lastDown -> собственный
    --  перехват WM_LBUTTONDOWN/RBUTTONDOWN.
    -- =============================================================
    local lastMouseBtn = { [1] = false, [2] = false, vk = {} }
    local function clwVkTapped(vk)
        if not wasKeyTapped(vk) then return false end
        -- общая защёлка с onWindowMessage: одно нажатие = одно срабатывание
        return grndPollTap(vk)
    end
    local function clwMouseRaw(btn)
        if type(getMouseState) == "function" then
            local ok, ms = pcall(getMouseState)
            if ok and type(ms) == "number" then
                if btn == 1 then return (ms % 2) == 1 end
                if btn == 2 then return (math.floor(ms / 2) % 2) == 1 end
            end
        end
        if type(isMouseButtonDown) == "function" then
            local ok, d = pcall(isMouseButtonDown, btn)
            if ok then return d and true or false end
        end
        return nil
    end
    local function clwMouseClicked(btn)
        local cur = clwMouseRaw(btn)
        if cur == nil then
            -- SAMPFUNCS-хелперов нет — берём VK-опрос, а затем перехват сообщений
            if type(isKeyDown) == "function" then
                local ok, d = pcall(isKeyDown, btn == 1 and 0x01 or 0x02)
                if ok then
                    local prev = lastMouseBtn[btn]
                    lastMouseBtn[btn] = d and true or false
                    if d and not prev then return true end
                    if not d then return false end
                end
            end
            if btn == 1 then return GRND_MOUSE.clicked end
            return GRND_MOUSE.rclicked
        end
        local prev = lastMouseBtn[btn]
        lastMouseBtn[btn] = cur
        return cur and not prev
    end
    local function clwMouseHeld(btn)
        local cur = clwMouseRaw(btn)
        if cur ~= nil then return cur end
        local vk = (btn == 1) and 0x01 or 0x02
        if type(isKeyDown) == "function" then
            local ok, d = pcall(isKeyDown, vk)
            if ok then return d and true or false end
        end
        return false
    end
    local function clwBtnTapped(code)
        if code == 1 or code == 2 then return clwMouseClicked(code) end
        -- средняя кнопка (VK_MBUTTON = 0x04): НЕ через GRND_TAP — защёлка
        -- никогда не сбрасывалась (KEYUP 0x04 не обрабатывался) и ClickWarp
        -- срабатывал ровно один раз.
        if code == 4 or code == 0x04 then
            local cur = GRND_MOUSE.mdown and true or false
            if type(isKeyDown) == "function" then
                local ok, d = pcall(isKeyDown, 0x04)
                if ok then cur = d and true or false end
            end
            local prev = lastMouseBtn.mmb
            lastMouseBtn.mmb = cur
            if cur and not prev then
                GRND_MOUSE.mclicked = false
                return true
            end
            return false
        end
        return clwVkTapped(code)
    end
    local plainCursorOn = false
    -- v1.12: Авто-GM по умолчанию ВЫКЛЮЧЕН. Раньше после авторизации скрипт
    -- сам включал GM и отправлял серверу /gm — это выглядело как «скрипт
    -- делает что-то при заходе без спроса». Теперь включается тумблером
    -- в меню (Читы → Авто-GM) или командой /cgmauto; состояние — в конфиге.
    local GRND_GM = { on = false, lastHp = 100, car = nil, cmdReg = false,
        srv = false, srvKnown = false,
        autoClient = false, autoServer = false, autoFired = false }
    _G.GRND_GM = GRND_GM
    local function clwGetGroundZ(x, y)
        if type(getGroundZForCoord) == "function" then
            local ok, z = pcall(getGroundZForCoord, x, y)
            if ok and type(z) == "number" then return z end
        end
        if type(getGroundZFor3dCoord) == "function" then
            local ok, z = pcall(getGroundZFor3dCoord, x, y, 50.0, 0, 1)
            if ok and type(z) == "number" then return z end
            local ok2, z2 = pcall(getGroundZFor3dCoord, x, y, 50.0)
            if ok2 and type(z2) == "number" then return z2 end
        end
        return nil
    end
    local function clwCam()
        if not (libs.memory and type(libs.memory.readfloat) == "function") then return nil end
        local m = libs.memory
        local function rf(a)
            local ok, v = pcall(m.readfloat, a)
            if ok and type(v) == "number" then return v end
            return nil
        end
        local cx, cy, cz = rf(0xB6F028), rf(0xB6F02C), rf(0xB6F030)
        local tx, ty, tz = rf(0xB6F038), rf(0xB6F03C), rf(0xB6F040)
        if not (cx and cy and cz and tx and ty and tz) then return nil end
        return cx, cy, cz, tx, ty, tz
    end
    local function clwScreenToWorld(sx, sy)
        local cam = clwCam()
        if not cam then return nil end
        local cx, cy, cz, tx, ty, tz = cam
        local fx, fy, fz = tx - cx, ty - cy, tz - cz
        local fl = math.sqrt(fx*fx + fy*fy + fz*fz)
        if fl < 1e-5 then return nil end
        fx, fy, fz = fx/fl, fy/fl, fz/fl
        local rx, ry, rz = fy, -fx, 0
        local rl = math.sqrt(rx*rx + ry*ry + rz*rz)
        if rl < 1e-5 then return nil end
        rx, ry, rz = rx/rl, ry/rl, rz/rl
        local ux, uy, uz = ry*fz - rz*fy, rz*fx - rx*fz, rx*fy - ry*fx
        local resX, resY = getScreenResolution()
        if resX <= 0 or resY <= 0 then return nil end
        local aspect = resX / resY
        local vFov = 70 * math.pi / 180
        local hFov = 2 * math.atan(math.tan(vFov/2) * aspect)
        local ndcX = (sx / resX) * 2 - 1
        local ndcY = 1 - (sy / resY) * 2
        local dirX = fx + rx * ndcX * math.tan(hFov/2) + ux * ndcY * math.tan(vFov/2)
        local dirY = fy + ry * ndcX * math.tan(hFov/2) + uy * ndcY * math.tan(vFov/2)
        local dirZ = fz + rz * ndcX * math.tan(hFov/2) + uz * ndcY * math.tan(vFov/2)
        local dl = math.sqrt(dirX*dirX + dirY*dirY + dirZ*dirZ)
        dirX, dirY, dirZ = dirX/dl, dirY/dl, dirZ/dl
        local step, maxD = 4.0, 600.0
        for t = step, maxD, step do
            local px, py, pz = cx + dirX*t, cy + dirY*t, cz + dirZ*t
            local gz = clwGetGroundZ(px, py)
            if gz and gz <= pz + 0.8 then
                return px, py, gz
            end
        end
        return cx + dirX*40, cy + dirY*40, cz + dirZ*40
    end
    local function clwGetMousePos()
        if type(getCursorPos) == "function" then
            local ok, x, y = pcall(getCursorPos)
            if ok and type(x) == "number" then return x, y end
        end
        if type(getPcMousePosition) == "function" then
            local ok, x, y = pcall(getPcMousePosition)
            if ok and type(x) == "number" then return x, y end
        end
        return nil
    end
    -- v1.7.1: точная поверхность под точкой. Луч сверху вниз через
    -- processLineOfSight ловит крыши/этажи/мосты (getGroundZ их часто не
    -- видит и даёт землю под зданием). Возвращает Z поверхности.
    local function clwSurfaceZ(x, y, zHint)
        zHint = tonumber(zHint) or 0
        if type(processLineOfSight) == "function" then
            local top = zHint + 60.0
            local okL, hit, col = pcall(processLineOfSight,
                x, y, top, x, y, zHint - 60.0,
                true, true, false, true, false, false, false, false)
            if okL and hit and type(col) == "table" and type(col.pos) == "table"
               and type(col.pos[3]) == "number" then
                return col.pos[3]
            end
        end
        local gz = clwGetGroundZ(x, y)
        if gz then return gz end
        return nil
    end
    -- Крыша здания: луч с большой высоты строго вниз в точке (x,y).
    -- Используется, когда прицел упёрся в стену.
    local function clwRoofZ(x, y, zMin)
        if type(processLineOfSight) ~= "function" then return nil end
        local okL, hit, col = pcall(processLineOfSight,
            x, y, 1200.0, x, y, (tonumber(zMin) or -100) - 1.0,
            true, false, false, true, false, false, false, false)
        if okL and hit and type(col) == "table" and type(col.pos) == "table"
           and type(col.pos[3]) == "number" then
            return col.pos[3]
        end
        return nil
    end
    local function clwStopMotion()
        if type(setCharVelocity) == "function" then pcall(setCharVelocity, PLAYER_PED, 0, 0, 0) end
        if type(isCharInAnyCar) == "function" and type(getCarCharIsUsing) == "function" then
            local okIn, inCar = pcall(isCharInAnyCar, PLAYER_PED)
            if okIn and inCar then
                local okC, car = pcall(getCarCharIsUsing, PLAYER_PED)
                if okC and car and car ~= 0 then
                    if type(setCarSpeedInstantly) == "function" then pcall(setCarSpeedInstantly, car, 0) end
                    if type(setCarVelocity) == "function" then pcall(setCarVelocity, car, 0, 0, 0) end
                end
            end
        end
    end
    local function clwStopAirBreakFlightForWarp()
        local A = GRND_ABRK
        if not A or not A.fly then return false end

        -- Match the configured AirBreak activation key (usually Right Shift):
        -- stop flight only, keep A.on unchanged so Shift can resume it later.
        local held = false
        if type(grndAbrkKeyHeld) == "function" then
            local ok, down = pcall(grndAbrkKeyHeld, A.key or 0xA1)
            held = ok and down and true or false
        end
        A.fly, A.prevKey = false, held
        A.z, A.zOff, A.hx, A.hy = nil, nil, nil, nil
        A.camDir = false
        A.lastT = 0
        if notify and type(notify.add) == "function" then
            pcall(notify.add, "AirBreak: полёт ВЫКЛ (ClickWarp)", "warn", 2)
        end
        return true
    end

    local function clwWarpTo(x, y, z)
        if not grndIsSpawned() then
            notify.add("ClickWarp: вы ещё не заспавнены", "warn", 3)
            return
        end
        if type(isCharInAnyCar) == "function" and type(getCarCharIsUsing) == "function"
        and type(setCarCoordinates) == "function" then
            local okIn, inCar = pcall(isCharInAnyCar, PLAYER_PED)
            if okIn and inCar then
                local okC, car = pcall(getCarCharIsUsing, PLAYER_PED)
                if okC and car and car ~= 0 then
                    -- машину ставим колёсами на поверхность (+0.5 — половина
                    -- клиренса, иначе физика выталкивает и подкидывает)
                    local sz = clwSurfaceZ(x, y, z) or z
                    clwStopAirBreakFlightForWarp()
                    local okW = pcall(setCarCoordinates, car, x, y, sz + 0.5)
                    if okW then
                        clwStopMotion()
                        clw.lastX, clw.lastY, clw.lastZ = x, y, sz
                        notify.add(("ClickWarp -> %.1f, %.1f, %.1f"):format(x, y, z), "ok", 4)
                        return
                    end
                end
            end
        end
        if type(setCharCoordinates) == "function" then
            -- setCharCoordinates ставит педа ЦЕНТРОМ (≈1 м над стопами) в
            -- указанную точку, поэтому раньше «+1.0» давало падение с высоты
            -- и подброс. Теперь: точная поверхность + 0.05 без запаса, и
            -- обнуляем скорость.
            local sz = clwSurfaceZ(x, y, z) or z
            clwStopAirBreakFlightForWarp()
            local ok = pcall(setCharCoordinates, PLAYER_PED, x, y, sz + 0.05)
            if ok then
                clwStopMotion()
                clw.lastX, clw.lastY, clw.lastZ = x, y, sz
                notify.add(("ClickWarp -> %.1f, %.1f, %.1f"):format(x, y, z), "ok", 4)
                return
            end
        end
        notify.add("ClickWarp: функция телепорта недоступна", "error", 4)
    end
    local function clwDoWarp()
        local x, y, z
        if clw.mode == "blip" then
            if type(getTargetBlipCoordinates) == "function" then
                local ok, bx, by, bz = pcall(getTargetBlipCoordinates)
                if ok and type(bx) == "number" and (bx ~= 0 or by ~= 0 or bz ~= 0) then
                    x, y, z = bx, by, bz
                end
            end
            if not x then
                notify.add("ClickWarp: нет метки (правая кнопка по карте)", "warn", 3)
                return
            end
            do
                local gz = clwGetGroundZ(x, y)
                if gz then z = gz end
            end
        elseif clw.mode == "aim" then
            local resX, resY = getScreenResolution()
            x, y, z = clwScreenToWorld(resX/2, resY/2)
            if not x then
                notify.add("ClickWarp: не удалось вычислить точку", "error", 3)
                return
            end
        else
            local sx, sy = clwGetMousePos()
            if not sx then
                local resX, resY = getScreenResolution()
                sx, sy = resX/2, resY/2
            end
            x, y, z = clwScreenToWorld(sx, sy)
            if not x then
                notify.add("ClickWarp: не удалось вычислить точку", "error", 3)
                return
            end
        end
        clwWarpTo(x, y, z)
    end
    local clwFont = nil
    do
        if type(renderCreateFont) == "function" then
            local ok, f = pcall(renderCreateFont, "Verdana", 10, 5)
            if ok and f then clwFont = f end
        end
    end
    local function clwRemoveMarker()
        if clw.marker ~= nil then
            pcall(removeUser3dMarker, clw.marker)
            clw.marker = nil
        end
    end
    local function clwPlaceMarker(x, y, z)
        if type(createUser3dMarker) ~= "function" then return end
        clwRemoveMarker()
        local ok, m = pcall(createUser3dMarker, x, y, z + 1.2, clw.markerColor)
        if ok and m then clw.marker = m end
    end
    local function clwShowCursor(on)
        if type(showCursor) == "function" then
            if on then pcall(showCursor, true, true)
            else pcall(showCursor, false) end
        elseif type(sampSetCursorMode) == "function" then
            pcall(sampSetCursorMode, on and 3 or 0)
        end
    end
    local function clwGetAimTarget()
        if type(getCursorPos) ~= "function" then return nil end
        if type(convertScreenCoordsToWorld3D) ~= "function" then return nil end
        if type(getActiveCameraCoordinates) ~= "function" then return nil end
        local okC, sx, sy = pcall(getCursorPos)
        if not okC or type(sx) ~= "number" or type(sy) ~= "number" then return nil end
        local okCam, camX, camY, camZ = pcall(getActiveCameraCoordinates)
        if not okCam or type(camX) ~= "number" then return nil end
        local okW, farX, farY, farZ = pcall(convertScreenCoordsToWorld3D, sx, sy, clw.maxDist)
        if not okW or type(farX) ~= "number" then return nil end
        if type(processLineOfSight) == "function" then
            local okL, hit, col = pcall(processLineOfSight,
                camX, camY, camZ, farX, farY, farZ,
                true, true, false, true, false, false, false, false)
            if okL and hit and type(col) == "table" and type(col.pos) == "table" then
                local hx, hy, hz = col.pos[1], col.pos[2], col.pos[3]
                if type(hx) == "number" and type(hy) == "number" and type(hz) == "number" then
                    -- v1.7.1: если попали в СТЕНУ (нормаль почти горизонтальная),
                    -- переносим точку на крышу этого здания: чуть заглубляемся
                    -- внутрь по нормали и бьём лучом строго вниз с высоты.
                    local nz = nil
                    if type(col.normal) == "table" and type(col.normal[3]) == "number" then
                        nz = col.normal[3]
                    end
                    local isWall = (nz ~= nil) and (math.abs(nz) < 0.45)
                    if nz == nil then
                        -- нормали обёртка не отдала: пробуем «крышу» по факту —
                        -- если строго над точкой (чуть внутрь по лучу) есть
                        -- поверхность выше, значит это стена здания
                        local fdx, fdy = farX - camX, farY - camY
                        local fl = math.sqrt(fdx*fdx + fdy*fdy)
                        if fl > 1e-3 then
                            local ix, iy = hx + fdx / fl * 0.6, hy + fdy / fl * 0.6
                            local rz = clwRoofZ(ix, iy, hz)
                            if rz and rz > hz + 1.0 then hx, hy, hz = ix, iy, rz end
                        end
                        isWall = false
                    end
                    if isWall then
                        local nx, ny = col.normal[1] or 0, col.normal[2] or 0
                        local ix, iy = hx - nx * 0.6, hy - ny * 0.6
                        local rz = clwRoofZ(ix, iy, hz)
                        if rz and rz >= hz - 0.5 then
                            hx, hy, hz = ix, iy, rz
                        end
                    end
                    local dx, dy, dz = hx - camX, hy - camY, hz - camZ
                    return hx, hy, hz, math.sqrt(dx*dx + dy*dy + dz*dz), sx, sy
                end
            end
        end
        local gz = clwGetGroundZ(farX, farY)
        if gz then
            return farX, farY, gz, clw.maxDist, sx, sy
        end
        return nil
    end
    local SPEC_VEH_HANDLE_FNAMES = {
        "sampGetCarHandleBySampVehicleId",
        "getCarHandleBySampVehicleId",
        "sampGetVehicleHandleBySampVehicleId",
    }
    local specVehHandleFnCache = nil
    local specVehHandleFnName = nil
    local function specVehHandleFn()
        if specVehHandleFnCache ~= nil then
            return specVehHandleFnCache or nil
        end
        for i = 1, #SPEC_VEH_HANDLE_FNAMES do
            local f = _G[SPEC_VEH_HANDLE_FNAMES[i]]
            if type(f) == "function" then
                specVehHandleFnCache = f
                specVehHandleFnName = SPEC_VEH_HANDLE_FNAMES[i]
                return f
            end
        end
        specVehHandleFnCache = false
        return nil
    end
    local function specSampVehHandle(vid)
        local fn = specVehHandleFn()
        if not fn then return nil end
        local res = { pcall(fn, vid) }
        if not res[1] then return nil end
        local h = nil
        for i = 2, #res do
            if type(res[i]) == "number" and res[i] ~= 0 then h = res[i]; break end
        end
        if not h then return nil end
        if type(doesVehicleExist) == "function" then
            local okE, ex = pcall(doesVehicleExist, h)
            if okE and ex == false then return nil end
        end
        return h
    end
    local function clwFindCarNear(x, y, z, radius)
        radius = radius or 7.0
        if type(getCarCoordinates) == "function" then
            local best, bestD, scanned = nil, radius, 0
            for id = 0, 2000 do
                local h = specSampVehHandle(id)
                if h then
                    scanned = scanned + 1
                    local okC, cx, cy, cz = pcall(getCarCoordinates, h)
                    if okC and type(cx) == "number" then
                        local dx, dy, dz = cx - x, cy - y, cz - z
                        local d = math.sqrt(dx*dx + dy*dy + dz*dz)
                        if d < bestD then best, bestD = h, d end
                    end
                end
            end
            clw.lastScanCount = scanned
            if best then return best end
        end
        if type(getClosestCar) == "function" then
            local res = { pcall(getClosestCar, x, y, z, radius, false, false) }
            if res[1] then
                for i = 2, #res do
                    if type(res[i]) == "number" and res[i] ~= 0 then return res[i] end
                end
            end
        end
        return nil
    end
    local function clwSetAiming(on)
        if on == clw.aiming then return end
        if on then
            if not grndIsSpawned() then
                notify.add("ClickWarp: вы ещё не заспавнены", "warn", 3)
                return
            end
            plainCursorOn = false
            clw.aiming = true
            clw.tx, clw.ty, clw.tz = nil, nil, nil
            clwShowCursor(true)
            if type(setPlayerControl) == "function" then
                pcall(setPlayerControl, PLAYER_HANDLE, false)
            end
        else
            plainCursorOn = false
            clw.aiming = false
            clw.tx, clw.ty, clw.tz = nil, nil, nil
            clwRemoveMarker()
            clwShowCursor(false)
            if type(setPlayerControl) == "function" then
                pcall(setPlayerControl, PLAYER_HANDLE, true)
            end
        end
    end
    local function grndPlainCursorShow(on)
        if type(showCursor) == "function" then
            if on then pcall(showCursor, true)
            else pcall(showCursor, false) end
        elseif type(sampSetCursorMode) == "function" then
            pcall(sampSetCursorMode, on and 3 or 0)
        end
    end
    local function grndF1Toast(on)
        if GRND_F1.toast == false then return end
        if notify and type(notify.add) == "function" then
            pcall(notify.add, on and "Курсор включён" or "Курсор выключен",
                on and "ok" or "info", 2)
        end
    end
    function grndTogglePlainCursor()
        if clw and clw.aiming then
            clwSetAiming(false)
            grndF1Toast(false)
            return
        end
        plainCursorOn = not plainCursorOn
        grndPlainCursorShow(plainCursorOn)
        grndF1Toast(plainCursorOn)
    end
    -- v1.11.15: слежка полностью владеет курсором. Если плоский курсор F1
    -- остался включён ДО входа в слежку, он держал курсор всегда видимым
    -- («курсор постоянно активен»), а F1 в слежке заблокирован — снять его
    -- было нельзя. Теперь рекон может принудительно гасить плоский курсор
    -- и сам управляет нативным курсором через showCursor.
    _G.grndPlainCursorForceOff = function()
        plainCursorOn = false
        grndPlainCursorShow(false)
    end
    _G.grndPlainCursorIsOn = function() return plainCursorOn and true or false end
    _G.grndNativeCursorShow = function(on)
        grndPlainCursorShow(on and true or false)
    end
    -- =================================================================
    --  GM (бессмертие)
    -- =================================================================
    local function grndGMApply(on)
        if type(setCharProofs) == "function" then
            pcall(setCharProofs, PLAYER_PED, on, on, on, on, on)
        end
    end
    local function grndGMToast(on)
        if notify and type(notify.add) == "function" then
            pcall(notify.add, on and "GM включён" or "GM выключен",
                on and "ok" or "info", 2)
        end
    end
    local function grndGMCarProof()
        local cur = nil
        if type(isCharInAnyCar) == "function" and type(storeCarCharIsIn) == "function" then
            local okC, inCar = pcall(isCharInAnyCar, PLAYER_PED)
            if okC and inCar then
                local okH, car = pcall(storeCarCharIsIn, PLAYER_PED)
                if okH and type(car) == "number" and car ~= 0 then cur = car end
            end
        end
        if type(setCarProofs) ~= "function" then return end
        local prev = GRND_GM.car
        if prev and prev ~= cur then
            local okV = true
            if type(doesVehicleExist) == "function" then
                local okE, ex = pcall(doesVehicleExist, prev)
                if okE then okV = ex end
            end
            if okV then pcall(setCarProofs, prev, false, false, false, false, false) end
            GRND_GM.car = nil
        end
        if cur then
            pcall(setCarProofs, cur, true, true, true, true, true)
            GRND_GM.car = cur
        end
    end
    local function grndGMClientSet(on)
        on = on and true or false
        if GRND_GM.on == on then return end
        GRND_GM.on = on
        if on then
            if type(getCharHealth) == "function" then
                local okH, hp = pcall(getCharHealth, PLAYER_PED)
                if okH and type(hp) == "number" then
                    GRND_GM.lastHp = math.min(hp, 100)
                end
            end
            grndGMCarProof()
        else
            if GRND_GM.car and type(setCarProofs) == "function" then
                pcall(setCarProofs, GRND_GM.car, false, false, false, false, false)
                GRND_GM.car = nil
            end
        end
        grndGMApply(on)
    end
    local function grndGMSrvSet(on)
        on = on and true or false
        if GRND_GM.srv == on then return end
        if type(sampSendChat) ~= "function" then return end
        pcall(sampSendChat, "/gm")
        GRND_GM.srv, GRND_GM.srvKnown = on, false
    end
    function grndGMToggle()
        local target = not GRND_GM.on
        grndGMClientSet(target)
        grndGMSrvSet(target)
        grndGMToast(target)
    end
    local function grndGMFrame()
        if not GRND_GM.on then return end
        grndGMApply(true)
        grndGMCarProof()
        if type(getCharHealth) == "function" and type(setCharHealth) == "function" then
            local okH, hp = pcall(getCharHealth, PLAYER_PED)
            if okH and type(hp) == "number" then
                local last = GRND_GM.lastHp or hp
                if hp > 0 and hp < last then
                    pcall(setCharHealth, PLAYER_PED, math.min(last, 100))
                elseif hp >= last then
                    GRND_GM.lastHp = math.min(hp, 100)
                end
            end
        end
    end
    local GM_SRV_ON = {
        "godmode enabled", "god mode enabled", "godmode on", "god mode on",
        "gm enabled", "gm on", "бессмертие включ", "годмод включ",
        "неуязвимость включ",
    }
    local GM_SRV_OFF = {
        "godmode disabled", "god mode disabled", "godmode off", "god mode off",
        "gm disabled", "gm off", "бессмертие выключ", "годмод выключ",
        "неуязвимость выключ",
    }
    local function gmSniffServerMsg(text)
        local t = tostring(text or ""):lower()
        if t == "" then return end
        for _, p in ipairs(GM_SRV_OFF) do
            if t:find(p, 1, true) then
                GRND_GM.srv, GRND_GM.srvKnown = false, true
                return
            end
        end
        for _, p in ipairs(GM_SRV_ON) do
            if t:find(p, 1, true) then
                GRND_GM.srv, GRND_GM.srvKnown = true, true
                return
            end
        end
    end
    local function clwAimFrame()
        if not clw.aiming then return end
        local x, y, z, d, sx, sy = clwGetAimTarget()
        if x then
            clw.tx, clw.ty, clw.tz, clw.tdist = x, y, z, d or 0
            clw.lastAimX, clw.lastAimY, clw.lastAimZ = x, y, z
            clwPlaceMarker(x, y, z)
            if clwFont and sx and type(renderFontDrawText) == "function" then
                local txt = ("%.1f m  TELEPORT"):format(d or 0)
                pcall(renderFontDrawText, clwFont, txt, sx + 18, sy + 8, 0xFFFFFFFF)
            end
        else
            clw.tx, clw.ty, clw.tz = nil, nil, nil
            clwRemoveMarker()
        end
    end
    -- =================================================================
    --  SPECTATE WARP
    -- =================================================================
    local function specSendChat(text)
        if type(sampSendChat) == "function" and type(text) == "string" and text ~= "" then
            pcall(sampSendChat, text)
            return true
        end
        return false
    end
    local function specSendPlayer(pid, x, y, z)
        local ok, cmd = pcall(string.format, GRND_SPEC_PLAYER_CMD, pid, x, y, z + 1.0)
        if ok and type(cmd) == "string" and cmd ~= "" then specSendChat(cmd) end
    end
    local function specSendVeh(vid, x, y, z)
        local ok, cmd = pcall(string.format, GRND_SPEC_VEH_CMD, vid, x, y, z + 1.0)
        if ok and type(cmd) == "string" and cmd ~= "" then specSendChat(cmd) end
    end
    local function specResolveVehId(handle)
        if not handle or handle == 0 then return nil end
        for _, fname in ipairs({ "sampGetVehicleIdByCarHandle", "sampGetSampVehicleIdByCarHandle" }) do
            local f = _G[fname]
            if type(f) == "function" then
                local res = { pcall(f, handle) }
                if res[1] then
                    for i = 2, #res do
                        if type(res[i]) == "number" and res[i] >= 0 and res[i] <= 2000 then
                            return res[i]
                        end
                    end
                end
            end
        end
        for id = 0, 2000 do
            if specSampVehHandle(id) == handle then return id end
        end
        return nil
    end
    local function specGetSpecPed()
        if not (grndSpecInSpec()) then return nil end
        if type(sampGetCharHandleBySampPlayerId) ~= "function" then return nil end
        local res = { pcall(sampGetCharHandleBySampPlayerId, GRND_SPEC.id) }
        if not res[1] then return nil end
        local ped = nil
        for i = 2, #res do
            if type(res[i]) == "number" and res[i] ~= 0 then ped = res[i]; break end
        end
        if not ped then return nil end
        if type(doesCharExist) == "function" then
            local okE, ex = pcall(doesCharExist, ped)
            if not (okE and ex) then return nil end
        end
        return ped
    end
    local function specGetSpecPos()
        if not (grndSpecInSpec()) then return nil end
        if type(sampGetCharHandleBySampPlayerId) ~= "function" then return nil end
        if type(getCharCoordinates) ~= "function" then return nil end
        local res = { pcall(sampGetCharHandleBySampPlayerId, GRND_SPEC.id) }
        if not res[1] then return nil end
        local ped = nil
        for i = 2, #res do
            if type(res[i]) == "number" and res[i] ~= 0 then ped = res[i]; break end
        end
        if not ped then return nil end
        if type(doesCharExist) == "function" then
            local okE, ex = pcall(doesCharExist, ped)
            if not (okE and ex) then return nil end
        end
        local okC, x, y, z = pcall(getCharCoordinates, ped)
        if okC and type(x) == "number" then return x, y, z end
        return nil
    end
    local function specFindSpecCarId()
        local ped = specGetSpecPed()
        if not ped then return nil end
        if type(isCharInAnyCar) == "function" then
            local okI, inCar = pcall(isCharInAnyCar, ped)
            if not (okI and inCar) then return nil end
        else
            return nil
        end
        if type(getCarCharIsUsing) ~= "function" then return nil end
        local okC, car = pcall(getCarCharIsUsing, ped)
        if not (okC and car and car ~= 0) then return nil end
        local vid = nil
        local okR, rid = pcall(specResolveVehId, car)
        if okR then vid = rid end
        return vid
    end
    local specArmId, specArmT = nil, 0
    local function specWarpAim()
        if not (grndSpecInSpec()) then
            if GRND_SPEC.active and GRND_SPEC.id then
                notify.add(("Слежка #%d: трек протух — /cwsp %d чтобы продолжить"):format(
                    GRND_SPEC.id, GRND_SPEC.id), "warn", 3)
            end
            return
        end
        local okV, stV = pcall(specProbeState)
        if okV and stV == false then
            grndSpecForget("state")
            notify.add("ТП отменён: ты уже не в слежке", "warn", 3)
            return
        end
        local x, y, z = clw.tx, clw.ty, clw.tz
        if not x then
            x, y, z = clwGetAimTarget()
        end
        if not x then
            notify.add("ClickWarp: нет точки — наведите на землю или здание", "warn", 2)
            return
        end
        do
            local age = os.clock() - (GRND_SPEC.confirmT or 0)
            local freshLimit = GRND_SPEC_EVENTS and 180 or GRND_SPEC_CONFIRM_SEC
            if age > freshLimit then
                if specArmId == GRND_SPEC.id and os.clock() - specArmT < 4 then
                    specArmId, specArmT = nil, 0
                else
                    specArmId, specArmT = GRND_SPEC.id, os.clock()
                    notify.add(("Слежка: точно ТП #%d? Нажми X/ЛКМ ещё раз"):format(GRND_SPEC.id), "warn", 4)
                    return
                end
            end
        end
        local pid = GRND_SPEC.id
        local carId = nil
        local okC, found = pcall(specFindSpecCarId)
        if okC then carId = found end
        if carId then
            specSendVeh(carId, x, y, z)
            notify.add(("Слежка: #%d [авто #%d] -> %.0f, %.0f"):format(pid, carId, x, y), "ok", 3)
        else
            specSendPlayer(pid, x, y, z)
            notify.add(("Слежка: #%d -> %.0f, %.0f, %.0f"):format(pid, x, y, z), "ok", 3)
        end
        clwSetAiming(false)
    end
    local function specRememberCar()
        local x, y, z = clw.tx, clw.ty, clw.tz
        if not x then
            x, y, z = clwGetAimTarget()
        end
        if not x then
            notify.add("Нет точки — наведите маркер на машину", "warn", 2)
            return
        end
        local car = nil
        local okF, found = pcall(clwFindCarNear, x, y, z, 8.0)
        if okF then car = found end
        if not car then
            notify.add(("Рядом нет машины (в стриме: %d)"):format(clw.lastScanCount or 0), "warn", 3)
            return
        end
        local vid = nil
        local okR, rid = pcall(specResolveVehId, car)
        if okR then vid = rid end
        if not vid then
            notify.add(("ID не найден (h=%s). Диагностика: /grnd keys"):format(tostring(car)), "error", 5)
            return
        end
        GRND_SPEC.carId, GRND_SPEC.carHandle = vid, car
        notify.add(("Машина #%d запомнена — наведите маркер и жмите V"):format(vid), "ok", 4)
    end
    local function specWarpCarAim()
        if not GRND_SPEC.carId then
            notify.add("Сначала запомните машину: наведите маркер и жмите C", "warn", 3)
            return
        end
        if GRND_SPEC.carHandle and type(doesVehicleExist) == "function" then
            local okE, ex = pcall(doesVehicleExist, GRND_SPEC.carHandle)
            if okE and ex then
                local curId = specResolveVehId(GRND_SPEC.carHandle)
                if curId and curId ~= GRND_SPEC.carId then
                    GRND_SPEC.carId, GRND_SPEC.carHandle = nil, nil
                    notify.add("Авто сменилось — запомните заново (C)", "warn", 4)
                    return
                end
            end
        end
        local x, y, z = clw.tx, clw.ty, clw.tz
        if not x then
            x, y, z = clwGetAimTarget()
        end
        if not x then
            notify.add("ClickWarp: нет точки — наведите на землю или здание", "warn", 2)
            return
        end
        specSendVeh(GRND_SPEC.carId, x, y, z)
        notify.add(("Авто #%d -> %.0f, %.0f, %.0f"):format(GRND_SPEC.carId, x, y, z), "ok", 3)
        clwSetAiming(false)
    end
    local function clwAntiShot()
        if type(setPlayerControl) ~= "function" then return end
        if lua_thread == nil or type(lua_thread.create) ~= "function" then return end
        pcall(setPlayerControl, PLAYER_HANDLE, false)
        lua_thread.create(function()
            wait(150)
            if not clw.aiming then
                pcall(setPlayerControl, PLAYER_HANDLE, true)
            end
        end)
    end
    local function clwApplyAim()
        if not clw.aiming then return end
        if grndSpecInSpec() then
            specWarpAim()
            clwAntiShot()
            return
        end
        local x, y, z = clw.tx, clw.ty, clw.tz
        if not x then
            x, y, z = clwGetAimTarget()
        end
        if not x then
            notify.add("ClickWarp: нет точки — наведите на землю или здание", "warn", 2)
            return
        end
        do
            local okP, pst = pcall(specProbeState)
            if okP and pst == true then
                notify.add("Ты в слежке, но цель неизвестна — /cwsp <id>, потом X", "warn", 4)
                clwSetAiming(false)
                return
            end
        end
        local wantCar = false
        -- ФИКС v1.2: clw.keyVehicle = 0x02 — это КНОПОЧНЫЙ код GTA (ВКМ),
        -- isKeyDown(0x02) = VK_CANCEL, к мыши отношения не имеет.
        if clw.keyVehicle == 1 or clw.keyVehicle == 2 then
            wantCar = clwMouseHeld(clw.keyVehicle)
        elseif type(isKeyDown) == "function" then
            local ok, down = pcall(isKeyDown, clw.keyVehicle)
            wantCar = (ok and down) or false
        end
        clwSetAiming(false)
        clwAntiShot()
        if wantCar then
            local car = nil
            local okF, found = pcall(clwFindCarNear, x, y, z, 7.0)
            if okF then car = found end
            if car and type(warpCharIntoCarAsPassenger) == "function" then
                clwStopAirBreakFlightForWarp()
                local okW = pcall(warpCharIntoCarAsPassenger, PLAYER_PED, car, 0)
                if okW then
                    clw.lastX, clw.lastY, clw.lastZ = x, y, z
                    notify.add("ClickWarp: сели в машину", "ok", 3)
                    return
                end
            end
        end
        clwWarpTo(x, y, z)
    end
    grndOnTerm(function(scr)
        local ok, me = pcall(thisScript)
        if (not ok) or scr == me or scr == nil then
            pcall(clwRemoveMarker)
            pcall(clwShowCursor, false)
            if type(setPlayerControl) == "function" then
                pcall(setPlayerControl, PLAYER_HANDLE, true)
            end
        end
    end)
    local renderedOnce = false
    local menu = nil
    -- Объявляем ImGui-upvalue до функций report, чтобы буфер ответа
    -- замыкался на тот же объект, который использует основной рендер.
    local im = nil
    local imKind = nil

    -- =====================================================================
    --  МОДУЛЬ REPORT (v0.1): кастомное окно жалобы/вопроса.
    --  Важно: это окно живёт внутри уже существующего ImGui-рендера GRND,
    --  а не в отдельном Lua-скрипте. Отдельный второй mimgui-хук на этой
    --  сборке клиента приводил к вылету GTA.
    --
    --  Системный диалог ловится по onShowDialog в момент его фактического
    --  появления. Поэтому задержка после /arep не имеет значения.
    --  Пока кнопки только рисуются и запоминают нажатие: серверные команды
    --  намеренно не угадываются.
    -- =====================================================================
    GRND_REP = {
        open = false,
        dialogId = -1,
        author = "Игрок",
        playerId = "?",
        question = "текст репорта",
        sourceCaption = "",
        sourceText = "",
        answer = nil,
        lastAction = "",
        seenKey = nil,
        pollAt = 0,
        -- v1.12: какой dialogId считается диалогом репорта (на сервере GRAND — 10)
        -- и до какого времени мы ЖДЁМ этот диалог (ставится при отправке /arep).
        dialogIdHint = 10,
        await = 0,
        -- v1.12 (ФИКС «окно репорта всплывало на заходе»): мало совпадения по
        -- номеру диалога — сервер использует id 10 и для своих окон (меню,
        -- авторизация). Окно открывается только если диалог ПОХОЖ на репорт
        -- либо мы сами только что запросили /arep. Выключается в конфиге
        -- (repStrict=0) — тогда работает старое поведение «любой диалог 10».
        strict = true,
        -- Команда телепорта к игроку для кнопки «Телепорт» (человечек).
        -- Формат: "/goto %d" (или без %d — ID допишется через пробел).
        -- Пока пусто — кнопка только уведомляет, привязка команд позже.
        tpCommand = "/goto %d",
    }

    local function grndRepEnsureBuffer()
        if GRND_REP.answer then return true end
        if not (im and im.new and im.new.char) then return false end
        local ok, buf = pcall(function() return im.new.char[256]() end)
        if ok and buf then
            GRND_REP.answer = buf
            return true
        end
        return false
    end

    local function grndRepClean(s)
        s = tostring(s or "")
        s = s:gsub("{%x%x%x%x%x%x}", "")
        s = s:gsub("\r", "")
        s = s:gsub("^%s+", ""):gsub("%s+$", "")
        return s
    end

    -- В этой сборке sampGetDialogText уже отдаёт UTF-8 (это видно по
    -- диагностическому логу). Старый cp1251_to_utf8 нельзя применять к нему
    -- повторно — иначе кириллица портится. Для старых сборок оставлен
    -- fallback на CP1251.
    -- Полная проверка валидности UTF-8 (а не «есть ли похожая пара байт»):
    -- CP1251-текст типа "Игрок" легко даёт ложную пару и оставался
    -- нераскодированным -> в окне были «??».
    local function grndRepIsUtf8(s)
        local i, n = 1, #s
        while i <= n do
            local b = s:byte(i)
            local len
            if b < 0x80 then len = 1
            elseif b >= 0xC2 and b <= 0xDF then len = 2
            elseif b >= 0xE0 and b <= 0xEF then len = 3
            elseif b >= 0xF0 and b <= 0xF4 then len = 4
            else return false end
            for k = 1, len - 1 do
                local c = s:byte(i + k)
                if not c or c < 0x80 or c > 0xBF then return false end
            end
            i = i + len
        end
        return true
    end
    local function grndRepUtf(s)
        s = tostring(s or "")
        if s:find("[\128-\255]") == nil then return s end
        if grndRepIsUtf8(s) then return s end
        return cp1251_to_utf8(s)
    end

    -- =================================================================
    --  v1.12: РАСПОЗНАВАНИЕ ДИАЛОГА РЕПОРТА
    --  Раньше «диалог 10 = репорт» — из-за этого на заходе (сервер использует
    --  id 10 для окна авторизации/меню) само открывалось окно репорта.
    --  Теперь решаем по СОДЕРЖИМОМУ, а номер диалога — лишь дополнительный
    --  фильтр (и то настраиваемый).
    -- =================================================================
    local REP_MARKERS = {
        "жалоб", "репорт", "report", "обращение", "вопрос игрока",
    }
    function _G.grndRepLooksReport(caption, text)
        local s = grndLowerUtf(grndRepUtf(tostring(caption or "")) .. " "
            .. grndRepUtf(tostring(text or "")))
        for i = 1, #REP_MARKERS do
            if s:find(REP_MARKERS[i], 1, true) then return true end
        end
        -- «Ник[12]» + слово «вопрос» в любом порядке
        if s:find("%[%d+%]") and s:find("вопрос", 1, true) then return true end
        return false
    end

    -- Готов ли игрок принимать репорт: на экране авторизации/меню окно
    -- репорта показывать нельзя (иначе оно «всплывает на заходе»).
    function _G.grndRepSpawnReady()
        if (GRND_REP.await or 0) > (os.clock() or 0) then return true end
        if type(sampIsLocalPlayerSpawned) ~= "function" then return true end
        local ok, sp = pcall(sampIsLocalPlayerSpawned)
        return (ok and sp) and true or false
    end

    -- Единое решение «этот диалог — репорт?», используется и хуком
    -- samp.events.onShowDialog, и опросом grndRepPoll.
    function _G.grndRepAcceptDialog(dialogId, caption, text)
        local id = tonumber(dialogId)
        if not id then return false end
        if GRND_REP.strict then
            if id ~= (GRND_REP.dialogIdHint or 10)
               and not _G.grndRepLooksReport(caption, text) then
                return false
            end
            if _G.grndRepLooksReport(caption, text) then
                return _G.grndRepSpawnReady()
            end
            -- ждём именно свой /arep — тогда id обязателен
            if (GRND_REP.await or 0) > (os.clock() or 0) then
                return id == (GRND_REP.dialogIdHint or 10)
            end
            return false
        end
        return id == (GRND_REP.dialogIdHint or 10)
    end

    -- Кнопка/клавиша «быстрый /arep»: помечаем окно ожидания, чтобы сервер,
    -- который не подписывает свой диалог, всё равно открыл окно репорта.
    function _G.grndRepMarkAwait(sec)
        GRND_REP.await = (os.clock() or 0) + (tonumber(sec) or 20)
        return GRND_REP.await
    end

    -- Дамп сырого диалога для отладки: moonloader/resource/grnd/logs/grnd_report_dump.txt
    local function grndRepDump(dialogId, caption, text)
        pcall(function()
            local dir = getWorkingDirectory and getWorkingDirectory() or "moonloader"
            local f = io.open(grndStoragePath("logs","grnd_report_dump.txt"), "a")
            if not f then return end
            local function hex(str)
                return (tostring(str or ""):gsub(".", function(c) return string.format("%02X ", c:byte()) end))
            end
            f:write(os.date("[%Y-%m-%d %H:%M:%S] "), "dialog=", tostring(dialogId), "\n")
            f:write("caption: ", tostring(caption or ""), "\n")
            f:write("text:    ", tostring(text or ""), "\n")
            f:write("hex:     ", hex(text), "\n\n")
            f:close()
        end)
    end

    -- Последние строки чата с репортами: если в диалоге нет текста жалобы,
    -- берём его отсюда по ID игрока ("...Nick[226]: текст").
    local GRND_REP_CHAT = {}
    local function grndRepRememberChat(text)
        local t = grndRepUtf(text)
        t = t:gsub("{%x%x%x%x%x%x}", "")
        local pid, msg = t:match("%[(%d+)%]%s*:%s*(.+)$")
        if not (pid and msg and msg ~= "") then return end
        -- v1.19.47: копим только НАСТОЯЩИЕ репорты — строки с маркером
        -- «[К-во репорта: N]». Из обычной реплики игрока текст жалобы не
        -- берём: иначе в окне репорта оказывалась его болтовня из чата.
        if not _G.grndRepCountOf or not _G.grndRepCountOf(msg) then return end
        msg = msg:gsub("%[[^%]]*[Рр]епорта%s*:%s*%d*%s*%]", "")
        msg = grndRepClean(msg:gsub("%[%s*%]", ""))
        if msg ~= "" then
            GRND_REP_CHAT[pid] = { text = msg, at = os.clock() }
        end
    end
    -- Разбор строки репорта из чата:
    --   "Artyr_stalbekov[261]: {FFCD00}помогите  [К-во репорта: 25]"
    -- v1.19.47: маркер «[К-во репорта: N]» обязателен — строка без него не
    -- репорт. Проверка маркера живёт в модуле (QR.repCountOf — там же, где
    -- автопилот, и её видно стендам: в этой части скрипта лимит локалов).
    local function grndCatchParse(text)
        local t = grndRepUtf(text)
        t = t:gsub("{%x%x%x%x%x%x}", "")
        local nick, pid, msg = t:match("([%w_%.%-]+)%[(%d+)%]%s*:%s*(.+)$")
        if not nick then return nil end
        local cnt = _G.grndRepCountOf(msg)
        if not cnt then return nil end -- не репорт, а обычная реплика
        msg = msg:gsub("%[[^%]]*[Рр]епорта%s*:%s*%d*%s*%]", "")
        msg = msg:gsub("%[%s*%]", "")
        msg = grndRepClean(msg)
        if msg == "" then msg = "текст репорта" end
        return nick, pid, msg, cnt
    end

    -- Все сообщения репорта теперь также отображаются в родном чате
    function grndRepShouldHideChat(text)
        return false
    end
    function grndRepHudRemove(pid)
        pid = tostring(pid or "")
        if pid == "" then return end
        local H = GRND_REPHUD
        if not H or not H.items then return end
        for i = #H.items, 1, -1 do
            if tostring(H.items[i].pid) == pid then
                table.remove(H.items, i)
            end
        end
    end
    function grndRepHudAdd(nick, pid, msg, cnt)
        if not GRND_REPHUD.enabled then return end
        pid = tostring(pid or "")
        nick = tostring(nick or "Игрок")
        msg = tostring(msg or "")
        if pid == "" then return end
        local H = GRND_REPHUD
        H.items = H.items or {}
        for i = 1, #H.items do
            if tostring(H.items[i].pid) == pid then
                H.items[i].nick = nick
                H.items[i].msg = msg
                H.items[i].cnt = cnt
                H.items[i].time = os.date("%H:%M:%S")
                H.items[i].at = os.clock()
                local it = table.remove(H.items, i)
                table.insert(H.items, 1, it)
                return
            end
        end
        table.insert(H.items, 1, {
            pid = pid, nick = nick, msg = msg, cnt = cnt,
            time = os.date("%H:%M:%S"), at = os.clock(),
        })
        while #H.items > (H.max or 12) do
            H.items[#H.items] = nil
        end
        if type(_G.ensureRender) == "function" then pcall(_G.ensureRender, true) end
    end
    local function grndRepHudTaken(text)
        if GRND_LOG.response(text) then GRND_LOG.resolve(text);return end
        local t = tostring(text or "")
        t = grndRepUtf(t)
        t = t:gsub("{%x%x%x%x%x%x}", "")
        t = t:gsub("<ADM>", "")
        -- "<ADM> Admin[287] ответил Player[113]: текст"
        local pos = t:find("ответил", 1, true)
        if not pos then
            pos = t:find("\xEE\xF2\xE2\xE5\xF2\xE8\xEB", 1, true) -- CP1251 «ответил»
        end
        if pos then
            local rest = t:sub(pos)
            -- v1.18.00: ID в квадратных скобках — родной формат жалобы,
            -- в круглых — формат админ-бота («ответил Mixa_Grozz(25)»)
            local pid = rest:match("%[(%d+)%]") or rest:match("%((%d+)%)")
            if pid then
                grndRepHudRemove(pid)
                return
            end
        end
        local low = grndLowerUtf(t)
        if low:find("взял", 1, true) and (low:find("репорт", 1, true) or low:find("жалоб", 1, true)) then
            local pid = t:match("%[(%d+)%]") or t:match(".*%((%d+)%)")
            if pid then grndRepHudRemove(pid) end
        end
    end
    local function grndCatchOnChat(text)
        if not GRND_CATCH.active then return end
        if GRND_REP.open then return end
        -- v1.12.1: на экране входа жалобы не ловим (и не показываем окно)
        if type(grndUiBlocked) == "function" and grndUiBlocked() then return end
        local nick, pid, msg, cnt = grndCatchParse(text)
        if not nick then return end
        GRND_CATCH.caught = (GRND_CATCH.caught or 0) + 1
        GRND_REP.dialogId = -1
        GRND_REP.author = nick
        GRND_REP.playerId = pid
        GRND_REP.question = msg
        GRND_REP.reportCount = cnt
        GRND_REP.sourceCaption = "catch"
        GRND_REP.sourceText = tostring(text or "")
        GRND_REP.lastAction = ""
        GRND_REP.seenKey = "catch|" .. tostring(text)
        GRND_REP.answer = nil
        GRND_REP.open = true
        GRND_CATCH.active = false
        pcall(grndRepHudAdd, nick, pid, msg, cnt)
        if type(_G.ensureRender) == "function" then pcall(_G.ensureRender, true) end
    end
    -- =============================================================
    --  v1.18.00: РЕПОРТЫ ОТ АДМИН-БОТА (формат «<ADM> … >>>»)
    -- =============================================================
    --  Бот пишет в админ-чат тремя строками:
    --    <ADM> (7) Nik_Name[261]: >>> НА РЕПОРТ НЕ ОТВЕТИЛИ ЗА 60 СЕКУНД!
    --    <ADM> (7) Nik_Name[261]: >>> Mixa_Grozz(25): дм
    --    <ADM> (7) Nik_Name[261]: >>> Ответить игроку: /pm 25 текст
    --  Что делает разбор:
    --    * вторая строка — САМ РЕПОРТ: ник, ID в КРУГЛЫХ скобках и текст
    --      жалобы. Добавляем его в окно «Репорты на экране»; клик по строке
    --      открывает окно репорта с этим текстом (как и для обычных жалоб);
    --    * первая строка — «не ответили за N секунд»: репорт, пришедший
    --      следом, помечается просроченным (красная точка + красное время);
    --    * третья — команда ответа («/pm ID …»): сохраняем её у записи,
    --      чтобы окно репорта знало адрес ответа, даже если строка с ником
    --      не пришла.
    --  Обычный формат жалобы («Nick[ID]: текст [К-во репорта: N]») этот
    --  разбор не трогает: он проверяется ПОСЛЕ и только если строку не
    --  опознали как сообщение бота.
    -- ВАЖНО: у grndMainBody почти исчерпан лимит локальных переменных Lua 5.1
    -- (200), поэтому здесь НЕ добавляем ни одного local: настройка живёт полем
    -- на таблице оверлея, а разбор — глобальной функцией (как _G.grndFormsOnChat).
    GRND_REPHUD.botWin = 12          -- сколько секунд живут пометки бота
    -- Разбор одной строки чата. true — строка распознана как сообщение
    -- админ-бота (тогда обычный разбор жалобы её уже не смотрит).
    -- =====================================================================
    --  РАЗБОР СООБЩЕНИЙ АДМИН-БОТА О ПРОСРОЧЕННЫХ РЕПОРТАХ (v1.19.04)
    --
    --  Бот пишет ТРИ строки строго в таком порядке:
    --    1) <ADM> (уровень) Ник[ID]: >>> НА РЕПОРТ НЕ ОТВЕТИЛИ ЗА 60 СЕКУНД!
    --    2) <ADM> (уровень) Ник[ID]: >>> Mixa_Grozz(25): дм
    --    3) <ADM> (уровень) Ник[ID]: >>> Ответить игроку: /pm 25 текст
    --  Порядок разбора:
    --    * строка 1 — ПОМЕТКА «просрочен»: она копится (b.lateAt) и
    --      накладывается на репорт, который придёт СЛЕДУЮЩИМ (строка 2),
    --      как бот и задумал. Раньше пометка липла к «любому свежему»
    --      репорту (< 3 c) — красная метка попадала на ЧУЖОЙ, уже отвеченный
    --      репорт, а настоящий оставался без метки;
    --    * строка 2 — САМ РЕПОРТ: разбираем его ЗДЕСЬ и возвращаем true.
    --      Если отдать строку обычному разбору жалобы, тот возьмёт ник и ID
    --      из ПРЕФИКСА админ-чата («<ADM> Ник[ID]:») — и в окне появится
    --      ЛОЖНЫЙ репорт от имени администратора вместо игрока. Теперь
    --      ложным репортам взяться неоткуда: строки с префиксом бота
    --      обычный разбор вообще не смотрит;
    --    * строка 3 — команда ответа («/pm ID»): вешается на запись игрока,
    --      а если запись ещё не пришла — на первый репорт этого ID.
    --  Репорт внутри «>>>» принимается в ДВУХ видах: «Ник(ID): текст» и
    --  родной «Ник[ID]: текст [К-во репорта: N]».
    --  Строка БЕЗ префикса админ-чата берётся только сразу после пометки
    --  «не ответили» (< 3 c) — на случай переноса длинной строки сервером.
    -- =====================================================================
    function grndRepHudBotOnChat(text)
        local H = GRND_REPHUD
        if not H then return false end
        local t = tostring(text or "")
        if t == "" then return false end
        local WIN = tonumber(H.botWin) or 12
        local tNow = os.clock()
        local b = H.bot
        if type(b) ~= "table" then b = {} H.bot = b end
        if b.lateAt and (tNow - b.lateAt) > WIN then b.lateAt, b.lateSec = nil, nil end
        if b.pmAt and (tNow - b.pmAt) > WIN then b.pmId, b.pmCmd, b.pmAt = nil, nil, nil end

        local raw = grndRepUtf(t)
        raw = raw:gsub("{%x%x%x%x%x%x}", ""):gsub("\194\160", " "):gsub("\239\187\191", "")

        local function markLate(pid)
            if type(H.items) ~= "table" then return end
            for i = 1, #H.items do
                local it = H.items[i]
                if tostring(it.pid) == tostring(pid) then
                    it.late, it.lateSec, it.bot = true, b.lateSec, true
                end
            end
        end
        local function applyPm(pid)
            if not b.pmCmd or type(H.items) ~= "table" then return end
            for i = 1, #H.items do
                local it = H.items[i]
                if tostring(it.pid) == tostring(pid) then it.pmCmd = b.pmCmd end
            end
        end
        -- добавить репорт бота и сразу наложить на него накопленные пометки
        local function addReport(nick, pid, msg, cnt)
            -- v1.19.21: автопилот — ответ /ans и команда по триггеру вкладки
            if type(_G.grndQrAutoOnReport) == "function" then
                pcall(_G.grndQrAutoOnReport, nick, pid, msg)
            end
            grndRepHudAdd(nick, pid, msg, cnt)
            if b.lateAt then
                markLate(pid)
                b.lateAt, b.lateSec = nil, nil
            end
            applyPm(pid)
        end

        local handled = false
        local blockPid = nil     -- репорт, добавленный в ЭТОМ ЖЕ сообщении

        for line in (raw .. "\n"):gmatch("([^\n]*)\n") do
            local text = line:gsub("^%s+", ""):gsub("%s+$", "")
            if text ~= "" then
                local body, hasPrefix = nil, false
                if type(grndFormAdminLine) == "function" then
                    local okL, lNick, lId, lBody = pcall(grndFormAdminLine, text)
                    if okL and type(lBody) == "string" then
                        hasPrefix = true      -- строка админ-чата, но без «>>>»
                        body = lBody:match("^%s*>+%s*(.*)$")
                        if body == "" then body = nil end
                    end
                end
                if (not hasPrefix) and b.lateAt and (tNow - b.lateAt) <= 3 then
                    body = text
                end
                if body then
                    local cNick, cId, cMsg, cCnt = nil, nil, nil, nil
                    if type(grndCatchParse) == "function" then
                        cNick, cId, cMsg, cCnt = grndCatchParse(body)
                    end
                    local low = grndLowerUtf(body)
                    local clean = grndRepClean(body)
                    local nick, pid, msg
                    if not cNick then
                        nick, pid, msg = clean:match("^([^%(%):]+)%s*%((%d+)%)%s*:%s*(.*)$")
                    end
                    if cNick then
                        -- 2) родной формат жалобы внутри «>>>» — обрабатываем
                        --    сами, чтобы строка не досталась обычному разбору
                        addReport(cNick, cId, cMsg, cCnt)
                        blockPid, handled = tostring(cId), true
                    elseif nick and pid then
                        -- 2) «Ник(ID): текст» — сам репорт
                        nick = nick:gsub("^%s+", ""):gsub("%s+$", "")
                        msg = grndRepClean(msg or "")
                        if msg == "" then msg = "текст репорта" end
                        if nick ~= "" then
                            addReport(nick, pid, msg, nil)
                            blockPid, handled = tostring(pid), true
                        end
                    else
                        local secs = low:match("не ответили за%s*(%d+)")
                        if secs then
                            -- 1) «НА РЕПОРТ НЕ ОТВЕТИЛИ ЗА N СЕКУНД!» — пометка
                            --    для СЛЕДУЮЩЕГО репорта
                            local seconds = tonumber(secs) or 60
                            local fresh = nil
                            if type(H.items) == "table" then
                                local it0 = H.items[1]
                                -- репорт только что (меньше секунды) — значит,
                                -- строки блока пришли в обратном порядке
                                if it0 and not it0.late and (os.clock() - (it0.at or 0)) < 1 then
                                    fresh = it0.pid
                                end
                            end
                            if blockPid then
                                -- репорт пришёл раньше в ЭТОМ же сообщении
                                b.lateSec = seconds
                                markLate(blockPid)
                            elseif fresh then
                                -- ...или отдельным сообщением доли секунды назад
                                b.lateSec = seconds
                                markLate(fresh)
                            else
                                -- штатный порядок: пометка ждёт следующий репорт
                                b.lateAt, b.lateSec = os.clock(), seconds
                            end
                            handled = true
                        else
                            local pmCmd, pmId = low:match("ответить игроку:%s*(/%a+)%s*(%d+)")
                            if pmCmd then
                                -- 3) «Ответить игроку: /pm ID …»
                                b.pmId = tostring(pmId)
                                b.pmCmd = tostring(pmCmd) .. " " .. tostring(pmId)
                                b.pmAt = os.clock()
                                applyPm(b.pmId)
                                handled = true
                            end
                        end
                    end
                end
            end
        end
        return handled
    end
    local function grndRepHudOnChat(text)
        grndRepHudTaken(text)
        -- v1.18.00: сначала новый формат админ-бота; если строка «наша» —
        -- обычный разбор жалобы её не смотрит
        local okBot, botHit = pcall(grndRepHudBotOnChat, text)
        if okBot and botHit then return end
        local nick, pid, msg, cnt = grndCatchParse(text)
        -- v1.19.22: автопилот работает и при выключенном оверлее «Репорты»:
        -- строка жалобы распознана — отдаём её автопилоту.
        if nick and type(_G.grndQrAutoOnReport) == "function" then
            pcall(_G.grndQrAutoOnReport, nick, pid, msg)
        end
        -- v1.19.47: репорт — ТОЛЬКО строка с маркером «[К-во репорта: N]».
        -- Обычная реплика чата («Ник[ID]: текст» без маркера) не репорт: она
        -- не открывает окно «Репорты» и не доходит до автопилота. Строки без
        -- маркера отдавались автопилоту из-за послабления v1.19.41 — из-за
        -- него скрипт отвечал на обычный чат, послабление убрано.
        if not GRND_REPHUD.enabled then return end
        if not nick then return end
        grndRepHudAdd(nick, pid, msg, cnt)
    end
    local function grndFormsOnChat(text)
        if type(grndUiBlocked) == "function" and grndUiBlocked() then return end
        if not text or text == "" then return end
        if GRND_ADMIN_CFG and GRND_ADMIN_CFG.autoForms == false then return end

        local nick,adminId,msg=grndFormAdminLine(text)
        if not nick or not adminId or not msg then return end
        local idStr=tostring(adminId)

        local myId = nil
        if type(sampGetLocalPlayerId) == "function" then
            local okI, mid = pcall(sampGetLocalPlayerId)
            if okI and type(mid) == "number" then myId = mid end
        end
        if myId and tonumber(idStr) == myId then return end

        -- v1.14.15: форма ищется ТОЛЬКО в админ-чате. Всё, что не <ADM>/[ADM],
        -- отсеяно выше и сюда не доходит — обычный чат не проверяется.
        local cmd = msg:match("(/%a[%w_]*.*)")
        if cmd then
            cmd = cmd:gsub("^%s+", ""):gsub("%s+$", "")
            if #cmd < 2 or cmd:sub(1, 1) ~= "/" then cmd = nil end
        end
        -- v1.15.0: формы без слэша отключены — строку без «/команды»
        -- (даже похожую на команду) игнорируем полностью.
        if not cmd then return end
        local commandName = grndFormCommandName(cmd)
        if not grndFormIsAllowed(commandName) then return end

        local now = os.clock()
        local newForm = {
            adminNick = nick,
            adminId = tonumber(idStr) or 0,
            cmd = cmd,
            time = now,
            openedAt = nil,
        }

        _G.GRND_FORMS = _G.GRND_FORMS or { active = nil, queue = {} }
        local forms = _G.GRND_FORMS
        if type(forms.queue) ~= "table" then forms.queue = {} end
        if not forms.active then
            newForm.openedAt = now
            forms.active = newForm
        else
            table.insert(forms.queue, newForm)
        end
        if type(_G.ensureRender) == "function" then pcall(_G.ensureRender, true) end
    end
    _G.grndFormsOnChat = grndFormsOnChat
    local function grndRepHudOpenItem(it)
        if not it then return end
        if type(grndUiBlocked) == "function" and grndUiBlocked() then return end
        GRND_REP.dialogId = -1
        GRND_REP.author = it.nick
        GRND_REP.playerId = tostring(it.pid)
        GRND_REP.question = it.msg or "текст репорта"
        GRND_REP.reportCount = it.cnt
        GRND_REP.sourceCaption = "hud"
        GRND_REP.sourceText = ""
        GRND_REP.lastAction = ""
        GRND_REP.seenKey = "hud|" .. tostring(it.pid)
        GRND_REP.answer = nil
        -- v1.18.00: репорт от админ-бота отвечается ЕГО командой (/pm ID …),
        -- а не /ans: команду бот присылает строкой «Ответить игроку: …».
        GRND_REP.replyCmd = it.pmCmd
        GRND_REP.replyPid = it.pmCmd and tostring(it.pid) or nil
        GRND_REP.late = it.late and true or nil
        GRND_REP.open = true
        if type(_G.ensureRender) == "function" then pcall(_G.ensureRender, true) end
    end
    function _G.grndCatchToggle()
        GRND_CATCH.active = not GRND_CATCH.active
        if GRND_CATCH.active then
            GRND_CATCH.startedAt = os.clock()
            GRND_CATCH.caught = 0
            if type(_G.ensureRender) == "function" then pcall(_G.ensureRender, true) end
            if notify and notify.add then pcall(notify.add, "Автоловля репорта: включена", "ok", 2) end
        else
            if notify and notify.add then pcall(notify.add, "Автоловля репорта: выключена", "info", 2) end
        end
    end
    local function grndRepChatQuestion(pid)
        local e = GRND_REP_CHAT[tostring(pid)]
        if e and os.clock() - e.at < 600 then return e.text end
        return nil
    end

    local function grndRepExtractQuestion(raw)
        local text = grndRepUtf(raw)
        text = text:gsub("{%x%x%x%x%x%x}", "")
        local a = text:find("Жалоба/Вопрос:", 1, true)
        local b = a and text:find("Введите ответ:", a + 1, true) or nil
        if a then
            local q = text:sub(a + #"Жалоба/Вопрос:", (b and b - 1) or #text)
            q = grndRepClean(q)
            if q ~= "" then return q end
        end
        for line in (text .. "\n"):gmatch("([^\n]*)\n") do
            line = grndRepClean(line)
            if line ~= "" and not line:find("Игрок:", 1, true)
               and not line:find("Введите ответ", 1, true)
               and not line:find("Жалоба/Вопрос", 1, true) then
                return line
            end
        end
        return "текст репорта"
    end

    local function grndRepSet(dialogId, caption, text)
        -- v1.12.1: до входа в игру окно репорта не открываем (см. grndUiBlocked)
        if type(grndUiBlocked) == "function" and grndUiBlocked() then
            GRND_REP.blockedAt = os.clock()
            return false
        end
        local cap = grndRepUtf(caption)
        local body = grndRepUtf(text)
        local full = cap .. "\n" .. body
        grndRepDump(dialogId, caption, text)
        local nick, pid = full:match("([%w_%.%-]+)%s*%[(%d+)%]")
        if not nick or nick == "" then nick = grndRepClean(cap) end
        if nick == "" then nick = "Игрок" end
        if not pid or pid == "" then pid = "?" end

        GRND_REP.dialogId = tonumber(dialogId) or -1
        GRND_REP.author = nick
        GRND_REP.playerId = pid
        GRND_REP.question = grndRepExtractQuestion(text)
        -- Если в диалоге самого обращения нет (или это просто "Nick[ID]"),
        -- пробуем взять текст из чата по ID игрока.
        do
            local q = GRND_REP.question or ""
            local looksEmpty = (q == "текст репорта") or q:find("^%??%s*[%w_%.%-]*%s*%[%d+%]%s*$") ~= nil
            if looksEmpty then
                local fromChat = grndRepChatQuestion(pid)
                if fromChat then GRND_REP.question = fromChat end
            end
        end
        GRND_REP.sourceCaption = tostring(caption or "")
        GRND_REP.sourceText = tostring(text or "")
        GRND_REP.lastAction = ""
        GRND_REP.seenKey = tostring(dialogId) .. "|" .. tostring(caption) .. "|" .. tostring(text)
        GRND_REP.answer = nil
        GRND_REP.open = true
        if type(_G.ensureRender) == "function" then pcall(_G.ensureRender, true) end
    end

    -- UTF-8 -> CP1251 для отправки в чат SA-MP.
    local function grndRepToAnsi(str)
        str = tostring(str or "")
        local enc = encoding or (libs and libs.encoding)
        if not enc or not enc.UTF8 then return str end
        local ok, out = pcall(function()
            local prev = enc.default
            enc.default = "CP1251"
            local r = enc.UTF8:decode(str)
            enc.default = prev
            return r
        end)
        if ok and type(out) == "string" and out ~= "" then return out end
        return str
    end
    -- Очередь команд репорта: /ans и /goto нельзя слать в одном кадре —
    -- сервер часто глотает вторую. Отправляем по одной с интервалом.
    GRND_REP.queue = GRND_REP.queue or {}
    function grndRepQueue(cmd)
        if type(cmd) ~= "string" or cmd == "" then return end
        GRND_REP.queue[#GRND_REP.queue + 1] = cmd
    end
    function grndRepQueueTick()
        local q = GRND_REP.queue
        if not q or #q == 0 then return end
        local now = os.clock()
        if now - (GRND_REP.queueAt or 0) < 0.35 then return end
        GRND_REP.queueAt = now
        local cmd = table.remove(q, 1)
        if type(sampSendChat) == "function" then pcall(sampSendChat, cmd) end
    end
    -- Ответ игроку на репорт: /ans ID текст
    function grndRepAnswer(pid, text)
        pid = tostring(pid or "")
        if not pid:match("^%d+$") then return false end
        local enc = grndRepToAnsi(text)
        -- v1.19.56: ручной ответ уходит ровно так же, как ответ автопилота —
        -- боевой строкой «/ans ID текст» (для репорта от бота «/pm ID текст»),
        -- через ту же очередь репорта.
        if type(_G.grndQrAnswerCmd) == "function" then
            grndRepQueue(_G.grndQrAnswerCmd(pid, enc))
            pcall(grndRepHudRemove, pid)
            return true
        end
        -- v1.18.00: если бот сообщил свою команду ответа («/pm ID»), отвечаем
        -- ею. Для всех остальных репортов путь прежний — /ans ID текст.
        local rc = GRND_REP.replyCmd
        if type(rc) == "string" and rc ~= "" and tostring(GRND_REP.replyPid or "") == pid then
            grndRepQueue(rc:gsub("%d+", pid) .. " " .. enc)
        else
            grndRepQueue("/ans " .. pid .. " " .. enc)
        end
        pcall(grndRepHudRemove, pid)
        return true
    end


    -- Резервный путь: если сервер показал диалог до регистрации samp.events,
    -- проверяем его состояние в основном цикле. Проверяется только dialogId 10.
    local function grndRepPoll()
        if not grndSessionReady() then return end
        if GRND_REP.open then return end
        local now = os.clock()
        if now - (GRND_REP.pollAt or 0) < 0.10 then return end
        GRND_REP.pollAt = now
        if type(sampIsDialogActive) ~= "function"
           or type(sampGetCurrentDialogId) ~= "function" then return end
        local okA, active = pcall(sampIsDialogActive)
        if not (okA and active) then return end
        local okId, id = pcall(sampGetCurrentDialogId)
        if not okId then return end
        local caption, text = "", ""
        if type(sampGetDialogCaption) == "function" then
            local ok, v = pcall(sampGetDialogCaption)
            if ok and type(v) == "string" then caption = v end
        end
        if type(sampGetDialogText) == "function" then
            local ok, v = pcall(sampGetDialogText)
            if ok and type(v) == "string" then text = v end
        end
        -- v1.12: тот же критерий, что и в хуке onShowDialog — иначе опрос
        -- открывал окно репорта на любом диалоге 10 (авторизация, меню).
        if not grndRepAcceptDialog(id, caption, text) then return end
        grndRepSet(id, caption, text)
    end

    -- =================================================================
    -- ПОДКЛЮЧАЕМ ImGui
    -- =================================================================
    local AUTH = {
        showedLoaded = false,
        showedAuthOk = false,
        windowSeen = false,
        closedAt = nil,
        attemptFailed = false,
        failCountBase = 0,
        okDelay = 2.5,
        panelOpen = false,
        ok = false,
        dialog = false,
        spawned = false,
        failScanAt = 0,
    }
    _G.GRND_AUTH_STATE = AUTH
    do
        local function detect(mod)
            if type(mod) ~= "table" then return nil end
            if type(mod.OnFrame) == "function"
               and type(mod.OnInitialize) == "function" then
                return "mimgui"
            end
            return "moonimgui"
        end
        local ok, mod = pcall(require, "mimgui")
        if ok then
            imKind = detect(mod)
            if imKind then im = mod end
        end
        if not im then
            ok, mod = pcall(require, "imgui")
            if ok then
                local k = detect(mod)
                if k then im, imKind = mod, k end
            end
        end
        -- v1.11.72b: публикуем обёртку. Функции, объявленные ВНЕ этого
        -- замыкания (панель действий grndDrawActSubPopup), иначе не могли
        -- получить im: они читали _G.imgui, которого никто не выставлял ->
        -- молчаливый return -> панель расширялась пустой, без ошибок.
        if im then
            _G.imgui = im
            _G.grndImgui = im
        end
    end
    function grndUtf8Len(s)
        s = tostring(s or "")
        local n, i, len = 0, 1, #s
        while i <= len do
            local b = s:byte(i)
            if b >= 0xF0 then i = i + 4
            elseif b >= 0xE0 then i = i + 3
            elseif b >= 0xC0 then i = i + 2
            else i = i + 1 end
            n = n + 1
        end
        return n
    end
    function grndTextW(s)
        s = tostring(s or "")
        s = (string.gsub(s, "{%x%x%x%x%x%x}", ""))
        local chars = grndUtf8Len(s)
        local per = GRND_FONT.glyphW or (GRND_FONT.fontSize or 14) * 0.52
        local est = math.max(1, math.floor(chars * per + 0.5))
        if GRND_FONT.noMeasure then return est end
        if type(im) ~= "table" or type(im.CalcTextSize) ~= "function" then
            GRND_FONT.noMeasure = true
            pcall(grndTrace, "measure", "im.CalcTextSize нет — ширина на оценке")
            return est
        end
        local ok, a, b2 = pcall(im.CalcTextSize, s)
        local w
        if ok then
            local ta = type(a)
            if ta == "table" or ta == "cdata" then
                w = tonumber(a.x)
            elseif ta == "number" then
                w = a
            end
        end
        if w and w > 0 then
            GRND_FONT.glyphW = w / math.max(1, chars)
            return w
        end
        GRND_FONT.noMeasure = true
        pcall(grndTrace, "measure", "im.CalcTextSize недоступен — перенос по оценке")
        return est
    end
    if im then
        -- Shim: у некоторых обёрток нет конструкторов ImVec2/ImVec4 в том же
        -- виде — а их вызывают ДЕСЯТКИ мест, и без них падает весь кадр.
        -- Дописываем их прямо в таблицу обёртки (только если их реально нет).
        if type(rawget(im, "ImVec2")) ~= "function" then
            im.ImVec2 = function(x, y) return { x = tonumber(x) or 0, y = tonumber(y) or 0 } end
        end
        if type(rawget(im, "ImVec4")) ~= "function" then
            im.ImVec4 = function(r, g, b, a)
                return { x = r or 0, y = g or 0, z = b or 0, w = a or 1 }
            end
        end
        local queue = {}
        local nextId = 0
        local TYPES = {
            info = { accent = {45, 156, 219} },
            ok = { accent = {76, 209, 79} },
            warn = { accent = {247, 146, 72} },
            error = { accent = {255, 100, 100} },
        }
        local function rgba(r, g, b, a)
            return im.ImVec4(r / 255, g / 255, b / 255, (a or 255) / 255)
        end
        local function col32(r, g, b, a)
            a = a or 255
            r = math.floor(tonumber(r) or 0) % 256
            g = math.floor(tonumber(g) or 0) % 256
            b = math.floor(tonumber(b) or 0) % 256
            a = math.floor(tonumber(a) or 0) % 256
            if bit and bit.bor and bit.lshift then
                return bit.bor(r, bit.lshift(g, 8), bit.lshift(b, 16), bit.lshift(a, 24))
            end
            return r + g * 0x100 + b * 0x10000 + a * 0x1000000
        end
        -- =============================================================
        --  МОДУЛЬ 10 (v1.2): константы ImGui через безопасный резолвер.
        --  В v1.1 флаги складывались напрямую: «im.WindowFlags.NoMove + ...».
        --  Если у обёртки нет какого-то поля (moonimgui/Star: другие имена,
        --  либо нет im.Cond / im.MouseCursor вовсе) — «attempt to perform
        --  arithmetic on a nil value» в ПЕРВОЙ строке окна, т.е. меню и таблица
        --  не рисуются вообще, а pcall снаружи это даже не покажет.
        -- =============================================================
        local function wflag(name)
            local t = rawget(im, "WindowFlags") or rawget(im, "ImGuiWindowFlags")
            local v = (type(t) == "table" or type(t) == "cdata") and t[name] or nil
            if v == nil then v = rawget(im, "ImGuiWindowFlags_" .. name) end
            if v == nil then v = rawget(im, name) end
            return tonumber(v) or 0
        end
        local function wf(...)
            local f = 0
            for i = 1, select("#", ...) do f = f + wflag(select(i, ...)) end
            return f
        end
        local function iflag(tblNames, name)
            for _, tn in ipairs(tblNames) do
                local t = rawget(im, tn)
                if t ~= nil then
                    local v = (type(t) == "table" or type(t) == "cdata") and t[name] or nil
                    if v ~= nil then return v end
                end
            end
            local v = rawget(im, name)
            if v ~= nil then return v end
            return nil
        end
        local COND_ALWAYS = iflag({ "Cond", "ImGuiCond" }, "Always")
            or iflag({ "Cond", "ImGuiCond" }, "Always") or 0
        local WIN_FLAGS = wf("NoTitleBar", "NoResize", "NoMove", "NoScrollbar",
            "NoCollapse", "NoInputs")
        local function cornerFlags(left, right, top, bottom)
            local f = 0
            local function pick(newName, oldName)
                if im[newName] ~= nil then return im[newName] end
                if im[oldName] ~= nil then return im[oldName] end
                return nil
            end
            if left then
                local v = pick("ImDrawFlags_RoundCornersLeft", "ImDrawCornerFlags_Left")
                if v then f = f + v end
            end
            if right then
                local v = pick("ImDrawFlags_RoundCornersRight", "ImDrawCornerFlags_Right")
                if v then f = f + v end
            end
            if top then
                local v = pick("ImDrawFlags_RoundCornersTop", "ImDrawCornerFlags_Top")
                if v then f = f + v end
            end
            if bottom then
                local v = pick("ImDrawFlags_RoundCornersBottom", "ImDrawCornerFlags_Bot")
                if v then f = f + v end
            end
            return f
        end
        local function roundRect(dl, p1, p2, col, rounding, flags)
            if rounding and rounding > 0 then
                local ok = pcall(dl.AddRectFilled, dl, p1, p2, col, rounding, flags or 0)
                if ok then return end
            end
            dl:AddRectFilled(p1, p2, col)
        end
        local function gradRect(dl, p1, p2, c1, c2, rounding)
            if im.ImDrawList_AddRectFilledMultiColor then
                local ok = pcall(im.ImDrawList_AddRectFilledMultiColor, dl, p1, p2, c1, c2, c2, c1)
                if ok then return end
            end
            local ok = pcall(dl.AddRectFilledMultiColor, dl, p1, p2, c1, c2, c2, c1)
            if ok then return end
            dl:AddRectFilled(p1, p2, c1, rounding or 0)
        end
        local pushStyleVec2, pushStyleFloat
        -- =============================================================
        --  МОДУЛЬ 2b (v1.2): учёт стека ImGui.
        --  В v1.1 push/pop не были сбалансированы: pcall(PushStyleVar) мог
        --  молча вернуть false (нет PushStyleVarVec2/Float в обёртке), а
        --  PopStyleVar() вызывался безусловно -> ImGui-стек уезжал, и дальше
        --  ЛЮБОЕ окно рисовалось с мусорным Alpha/цветом или не рисовалось.
        --  Отсюда и «меню маргнуло», и «TAB не открывается», и «мёртвые»
        --  кнопки (их окно Begin() начинало возвращать false).
        --  Теперь: пушим только если реально пушнули, и в конце кадра
        --  закрываем все незакрытые Begin.
        -- =============================================================
        local styleDepth, endDepth, colorDepth = 0, 0, 0
        local function grndPushStyleF(var, val)
            if var == nil then return false end
            local ok = false
            if im.PushStyleVarFloat then ok = pcall(im.PushStyleVarFloat, var, val) end
            if not ok then ok = pcall(im.PushStyleVar, var, val) end
            if ok then styleDepth = styleDepth + 1 end
            return ok
        end
        local function grndPushStyleV2(var, x, y)
            if var == nil then return false end
            local v = im.ImVec2(x, y)
            local ok = false
            if im.PushStyleVarVec2 then ok = pcall(im.PushStyleVarVec2, var, v) end
            if not ok then ok = pcall(im.PushStyleVar, var, v) end
            if ok then styleDepth = styleDepth + 1 end
            return ok
        end
        local function grndPushCol(var, col)
            if var == nil or col == nil then return false end
            local ok = pcall(im.PushStyleColor, var, col)
            if ok then colorDepth = colorDepth + 1 end
            return ok
        end
        local function grndPopStyle(n)
            n = n or 1
            n = math.min(n, styleDepth)
            if n <= 0 then return end
            styleDepth = styleDepth - n
            pcall(im.PopStyleVar, n)
        end
        local function grndPopCol(n)
            n = n or 1
            n = math.min(n, colorDepth)
            if n <= 0 then return end
            colorDepth = colorDepth - n
            pcall(im.PopStyleColor, n)
        end
        -- закрывает все незакрытые Begin этого окна/кадра
        local function grndEnds()
            while endDepth > 0 do
                endDepth = endDepth - 1
                pcall(im.End)
            end
            grndPopStyle(styleDepth)
            grndPopCol(colorDepth)
        end
        local function grndBegin(name, flags)
            local ok, res = pcall(im.Begin, name, nil, flags)
            if not ok then return false end
            endDepth = endDepth + 1
            return res and true or false
        end
        -- v1.4 (п.5): непрозрачность фона/рамки окна, не зависящая от обёртки.
        -- SetNextWindowBgAlpha есть не везде, а стиль WindowBg иначе рисует
        -- полупрозрачный прямоугольник окна. Фон и рамка окна
        -- рисуются ВНУТРИ Begin, поэтому push стилевых цветов с alpha 0 до
        -- Begin и pop сразу после — безопасны и не ломают баланс стилей.
        local function grndBeginTransparent(name, flags)
            local npush = 0
            if grndPushCol(im.Col and im.Col.WindowBg, rgba(0, 0, 0, 0)) then
                npush = npush + 1
            end
            if grndPushCol(im.Col and im.Col.Border, rgba(0, 0, 0, 0)) then
                npush = npush + 1
            end
            local ok = grndBegin(name, flags)
            grndPopCol(npush)
            return ok
        end
        -- =============================================================
        --  МОДУЛЬ 2: drawToasts — ИСПРАВЛЕНО: im.CalcTextSize(n.text).x
        --  заменён на grndTextW(n.text) (краш на moonimgui).
        -- =============================================================
        local function drawToasts()
            local resX, resY = getScreenResolution()
            local marginX, marginBottom, gap = 22, 42, 8
            local maxVisible = math.max(1, math.min(5, math.floor((resY - marginBottom - 22) / 98)))
            local maxWidth = math.min(430, math.max(210, resX - marginX * 2))
            local now = os.clock()

            -- Expire in reverse order so removals do not skip entries.
            for i = #queue, 1, -1 do
                local item = queue[i]
                if now - item.start >= item.life then table.remove(queue, i) end
            end
            if #queue == 0 then return end

            local function drawToastIcon(dl, kind, cx, cy, style, alpha)
                local r, g, b = style.accent[1], style.accent[2], style.accent[3]
                local a = math.floor(255 * math.max(0, math.min(1, alpha or 1)))
                local stroke = col32(r, g, b, a)
                local fill = col32(r, g, b, math.floor(34 * math.max(0, math.min(1, alpha or 1))))
                pcall(function()
                    local center = im.ImVec2(cx, cy)
                    if dl.AddCircleFilled then dl:AddCircleFilled(center, 9.5, fill, 24) end
                    if dl.AddCircle then dl:AddCircle(center, 9.5, stroke, 24, 1.45) end
                    if kind == "ok" then
                        dl:AddLine(im.ImVec2(cx - 4.3, cy), im.ImVec2(cx - 1.2, cy + 3.1), stroke, 1.8)
                        dl:AddLine(im.ImVec2(cx - 1.2, cy + 3.1), im.ImVec2(cx + 4.5, cy - 3.4), stroke, 1.8)
                    elseif kind == "warn" then
                        dl:AddLine(im.ImVec2(cx, cy - 4.4), im.ImVec2(cx, cy + 1.3), stroke, 1.8)
                        if dl.AddCircleFilled then
                            dl:AddCircleFilled(im.ImVec2(cx, cy + 4.4), 1.05, stroke, 8)
                        end
                    elseif kind == "error" then
                        dl:AddLine(im.ImVec2(cx - 3.1, cy - 3.1), im.ImVec2(cx + 3.1, cy + 3.1), stroke, 1.7)
                        dl:AddLine(im.ImVec2(cx + 3.1, cy - 3.1), im.ImVec2(cx - 3.1, cy + 3.1), stroke, 1.7)
                    else
                        if dl.AddRectFilled then
                            dl:AddRectFilled(im.ImVec2(cx - 0.9, cy - 2.7),
                                im.ImVec2(cx + 0.9, cy + 4.5), stroke)
                        else
                            dl:AddLine(im.ImVec2(cx, cy - 2.7), im.ImVec2(cx, cy + 4.5), stroke, 1.8)
                        end
                        if dl.AddCircleFilled then
                            dl:AddCircleFilled(im.ImVec2(cx, cy - 5.1), 1.2, stroke, 12)
                        end
                    end
                end)
            end
            local first = math.max(1, #queue - maxVisible + 1)
            local y = resY - marginBottom
            for i = #queue, first, -1 do
                local item = queue[i]
                local age = math.max(0, now - item.start)
                if age < 0.30 then item.alpha = age / 0.30
                elseif age > item.life - 0.30 then item.alpha = math.max(0, (item.life - age) / 0.30)
                else item.alpha = 1 end

                local style = TYPES[item.kind] or TYPES.info
                local measured = grndTextW(item.text)
                local minWidth = math.min(280, maxWidth)
                local width = math.min(maxWidth, math.max(minWidth, measured + 60))
                local textWidth = math.max(120, width - 58)
                local lines = math.max(1, math.min(3, math.ceil(measured / textWidth)))
                local height = math.max(42, 16 + lines * 18)
                local textY = math.max(7, (height - lines * 18) / 2)
                y = y - height

                im.SetNextWindowPos(im.ImVec2(math.max(4, resX - marginX - width), math.max(4, y)), COND_ALWAYS)
                im.SetNextWindowSize(im.ImVec2(width, height), COND_ALWAYS)
                grndPushStyleF(im.StyleVar and im.StyleVar.Alpha, item.alpha)
                grndPushCol(im.Col and im.Col.WindowBg, rgba(24, 23, 30, 248))
                grndPushCol(im.Col and im.Col.Border, rgba(80, 76, 91, 220))
                grndPushCol(im.Col and im.Col.Text, rgba(244, 241, 249, 255))
                if grndBegin("grnd_toast_" .. item.id, WIN_FLAGS) then
                    local dl = im.GetWindowDrawList()
                    local pos = im.GetWindowPos()
                    local accentAlpha = math.floor(255 * math.max(0, math.min(1, item.alpha or 1)))
                    roundRect(dl, im.ImVec2(pos.x, pos.y), im.ImVec2(pos.x + 4, pos.y + height),
                        col32(style.accent[1], style.accent[2], style.accent[3], accentAlpha), 8,
                        cornerFlags(true, false, true, true))
                    drawToastIcon(dl, item.kind, pos.x + 23, pos.y + height / 2, style, item.alpha)
                    im.SetCursorPos(im.ImVec2(42, textY))
                    if type(im.TextWrapped) == "function" then im.TextWrapped(item.text)
                    elseif im.TextUnformatted then im.TextUnformatted(item.text)
                    else im.Text(item.text) end
                    endDepth = endDepth - 1
                    pcall(im.End)
                end
                grndPopCol(3)
                grndPopStyle(1)
                y = y - gap
            end
        end
        -- v1.8.0: палитра «современное тёмное стекло» — глубже фон, чище линии.
        -- Текстовые тона НЕ тронуты (читаемость килл-листа и чекеров прежняя).
        -- v1.12: палитра — из дизайн-системы (GRND_UIKIT), а не локальная копия:
        -- тема переключается внизу левой панели и меняется во ВСЕХ окнах.
        local TH = GRND_UIKIT.TH
        local function c32(t) return col32(t[1], t[2], t[3], t[4] or 255) end
        local function c4(t) return rgba(t[1], t[2], t[3], t[4] or 255) end
        pushStyleVec2 = function(var, x, y)
            local v = im.ImVec2(x, y)
            if im.PushStyleVarVec2 then
                local ok = pcall(im.PushStyleVarVec2, var, v)
                if ok then return true end
            end
            local ok = pcall(im.PushStyleVar, var, v)
            return ok
        end
        pushStyleFloat = function(var, val)
            if im.PushStyleVarFloat then
                local ok = pcall(im.PushStyleVarFloat, var, val)
                if ok then return true end
            end
            local ok = pcall(im.PushStyleVar, var, val)
            return ok
        end
        local function uiText(x, y, str, col, scale)
            scale = scale or 1
            local pushed = grndPushCol(im.Col and im.Col.Text, col)
            -- ФИКС v1.2: SetWindowFontScale есть не во всех обёртках (mimgui
            -- 1.7x, moonimgui) -> был краш ЛЮБОГО окна, рисующего текст.
            local scaled = false
            if scale ~= 1 and type(im.SetWindowFontScale) == "function" then
                scaled = pcall(im.SetWindowFontScale, scale)
            end
            im.SetCursorPos(im.ImVec2(x, y))
            local tx = tostring(str)
            local okS, a, b2 = pcall(im.CalcTextSize, tx)
            local sx, sy
            if okS then
                local ta = type(a)
                if ta == "table" or ta == "cdata" then
                    sx, sy = tonumber(a.x), tonumber(a.y)
                elseif ta == "number" then
                    sx, sy = a, tonumber(b2)
                end
            end
            local size = { x = sx or (grndUtf8Len(tx) * 7), y = sy or (GRND_FONT.fontSize or 14) }
            if im.TextUnformatted then im.TextUnformatted(str) else im.Text(str) end
            if scaled then pcall(im.SetWindowFontScale, 1) end
            if pushed then grndPopCol(1) end
            return size.x, size.y
        end

        -- v1.11.72: измеритель ширины текста с масштабом. РАНЬШЕ он был
        -- локальной функцией внутри drawRecon, поэтому drawFormPopup и
        -- панель «Действия» (grndDrawActSubPopup) обращались к nil и
        -- падали — окна только «разъезжались» по размеру, без содержимого.
        local function drawnWb(s, scale)
            scale = scale or 1
            if type(im.SetWindowFontScale) == "function" then
                if scale ~= 1 then
                    pcall(im.SetWindowFontScale, scale)
                    local okM, aM = pcall(im.CalcTextSize, tostring(s))
                    pcall(im.SetWindowFontScale, 1)
                    if okM then
                        local ta = type(aM)
                        local w = (ta == "table" or ta == "cdata")
                            and tonumber(aM.x) or tonumber(aM)
                        if w and w > 0 then return w end
                    end
                end
                return grndTextW(s) * scale
            end
            return grndTextW(s)
        end

        -- v1.11.72: эти примитивы нужны функциям, объявленным ВНЕ замыкания
        -- grndMainBody (grndDrawActSubPopup, drawFormPopup) — отдаём их по _G.
        -- grndDrawActSubPopup получает их ещё и параметром, это подстраховка.
        _G.grndUiText   = uiText
        _G.grndC4       = c4
        _G.grndCol32    = col32
        _G.grndDrawnWb  = drawnWb
        -- v1.5.4: «снять жирность» с имени файла шрифта.
        --   arialbd.ttf -> arial.ttf, tahomabd.ttf -> tahoma.ttf,
        --   *Bold.ttf   -> *.ttf   (если такой файл есть на диске).
        -- Нужно, потому что имитация жирного (tahoma bd / simhei и пр.)
        -- хуже читается; обычное начертание — как просил заказчик.
        local function klNormalFontPath(path)
            path = tostring(path or "")
            if path == "" then return path end
            local dir, name = path:match("^(.*[\\/])([^\\/]+)$")
            dir, name = dir or "", name or path
            local low = name:lower()
            local cands = {}
            local stem = low:match("^(.*)bd(%.ttf)$")
            if stem then cands[#cands + 1] = stem .. ".ttf" end
            local stem2 = low:match("^(.*)bold(%.ttf)$")
            if stem2 then cands[#cands + 1] = stem2 .. ".ttf" end
            local stem3 = low:match("^(.*)%-bold(%.otf)$")
            if stem3 then cands[#cands + 1] = stem3 .. ".otf" end
            for _, c in ipairs(cands) do
                local try = dir .. c
                local f = io.open(try, "rb")
                if f then
                    f:close()
                    pcall(grndTrace, "font", "жирный шрифт заменён на обычный: " .. try)
                    return try
                end
            end
            return path
        end
        local UI_FONT_BASE = 16
        -- v1.5.7: где ищем шрифты интерфейса (меню и килл-лист):
        --   <папка скрипта>\fonts — свои шрифты (достаточно положить .ttf),
        --   C:\Windows\Fonts      — системные.
        local function uiJoin(dir, name)
            dir = tostring(dir or "")
            local sep = "\\"
            if dir:find("/", 1, true) and not dir:find("\\", 1, true) then
                sep = "/"
            elseif not dir:find("\\", 1, true) then
                local okc, cf = pcall(function() return package.config end)
                if okc and type(cf) == "string" and #cf > 0 then sep = cf:sub(1, 1) end
            end
            return dir .. sep .. tostring(name)
        end
        local function uiFontDirs()
            local out = {}
            if type(this_script_dir) == "function" then
                local okd, sd = pcall(this_script_dir)
                if okd and sd and tostring(sd) ~= "" then
                    local pp = tostring(sd)
                    while pp:sub(-1) == "/" or pp:sub(-1) == "\\" do pp = pp:sub(1, -2) end
                    out[#out + 1] = uiJoin(pp, "fonts")
                end
            end
            out[#out + 1] = uiJoin(GRND_CONFIG.base(), "fonts")
            out[#out + 1] = "C:\\Windows\\Fonts"
            return out
        end
        -- Порядок «обычных» (не жирных) шрифтов: первый найденный файл станет
        -- шрифтом меню и килл-листа.
        -- v1.7.8: первым — SEGOE UI (просьба заказчика: «нормальный шрифт»).
        -- У Segoe UI крупная строчная высота, открытые просветы и чистые
        -- контуры при мелком кегле: растровый рендер ImGui (stb) читается
        -- заметно легче, чем у Arial. Arial остался запасным; вернуться к
        -- любому шрифту можно кнопками < > в настройках чекера.
        -- «Чистота» строки — по-прежнему отрисовкой: обычное начертание +
        -- МЯГКАЯ тень (KL.textShadow), без псевдожирности.
        local UI_FONT_ORDER = { "segoeui.ttf", "tahoma.ttf", "arial.ttf",
                                "verdana.ttf", "calibri.ttf", "trebuc.ttf" }
        local function uiFontCandidates()
            local out = {}
            local function add(p)
                p = tostring(p or "")
                if p == "" then return end
                local f = io.open(p, "rb")
                if f then f:close(); out[#out + 1] = p end
            end
            if GRND_FONT.fontPath and GRND_FONT.fontPath ~= "" then
                add(klNormalFontPath(GRND_FONT.fontPath))
                local file=tostring(GRND_FONT.fontPath):match("[^/\\]+$")
                for _,dir in ipairs(uiFontDirs()) do add(klNormalFontPath(uiJoin(dir,file))) end
            end
            -- v1.5.4: начертание ОБЫЧНОЕ. Раньше первым в списке стоял
            -- arialbd.ttf (жирный) — из-за него меню и ники в
            -- килл-листе выглядели «псевдожирными» и хуже читались.
            -- Если пользователь сам выбрал жирный файл (кнопки < > в чекере),
            -- берётся обычный вариант того же шрифта (см. klNormalFontPath).
            -- v1.5.7: обычные (не жирные) шрифты по порядку UI_FONT_ORDER,
            -- сначала из папки «fonts» рядом со скриптом, потом системные.
            for _, fn in ipairs(UI_FONT_ORDER) do
                for _, d in ipairs(uiFontDirs()) do add(uiJoin(d, fn)) end
            end
            return out
        end

        -- v1.5.7: список шрифтов для выбора в настройках чекера (кнопки < >):
        -- свои шрифты из папки fonts рядом со скриптом, затем известные
        -- системные обычного начертания, затем текущий выбранный.
        function grndUiFontList()
            local out, seen = {}, {}
            local function addP(p)
                p = tostring(p or "")
                if p == "" then return end
                local f = io.open(p, "rb")
                if not f then return end
                f:close()
                local key = p:lower()
                if seen[key] then return end
                seen[key] = true
                local nm = p:match("([^\\/]+)$") or p
                out[#out + 1] = { name = nm, path = p,
                                  title = (nm:gsub("%.[%w]+$", "")) }
            end
            local dirs = uiFontDirs()
            -- 1) свои шрифты: <папка скрипта>\fonts
            local lfs = (type(libs) == "table" and libs.lfs) or nil
            if lfs and lfs.dir and dirs[1] then
                pcall(function()
                    for nm in lfs.dir(dirs[1]) do
                        local low = tostring(nm):lower()
                        local e = low:match("%.([%w]+)$")
                        if e == "ttf" or e == "otf" then
                            addP(uiJoin(dirs[1], tostring(nm)))
                        end
                    end
                end)
            end
            -- 2) известные системные (обычного начертания)
            for _, fn in ipairs(UI_FONT_ORDER) do
                for _, d in ipairs(dirs) do addP(uiJoin(d, fn)) end
            end
            -- 3) текущий выбранный (если он не из списка)
            addP(GRND_FONT.fontPath)
            return out
        end

        -- v1.5.7: применить выбранный шрифт. Пишется в grnd_ui.cfg и вступает в
        -- силу после перезагрузки скрипта: шрифт (и «лестница» кеглей)
        -- строится при его запуске.
        function grndUiFontApply(item)
            if type(item) ~= "table" then return false end
            GRND_FONT.fontPath = item.path
            GRND_FONT.fontName = item.title or item.name
            GRND_FONT.fontUserChosen = true      -- v1.7.8: выбор осознанный
            GRND_FONT.cfgDirty = true
            GRND_FONT.fontStatus = "шрифт выбран: " .. tostring(item.name)
                .. " — применится после перезагрузки скрипта"
            return true
        end
        local function uiFontAdoptShared()
            local f = im and im.__grndUiFont
            if f then
                GRND_FONT.fontObj = f
                GRND_FONT.fontBase = im.__grndUiFontBase or UI_FONT_BASE
                GRND_FONT.fontLoadedPath = im.__grndUiFontPath
                GRND_FONT.fontInitDone = true
                return true
            end
            return false
        end
        -- v1.7.8: конфиг растеризации шрифта. Если обёртка не умеет
        -- ImFontConfig — работает прежний способ (nil-конфиг).
        -- v1.7.9: ГЛАВНАЯ причина «мутности» — оверсэмплинг атласа. По
        -- умолчанию ImGui растеризует глиф с трёхкратным запасом (OversampleH
        -- = 3) и усредняет обратно в 1x: края букв получают широкую серую
        -- кайму. Для отрисовки 1:1 это чистый вред — усреднение и есть «мыло».
        -- Oversample 1/1 растеризует глиф ровно в экранных пикселях: стволы
        -- букв резкие, кайма узкая — текст читается как растровый, как чат
        -- SA-MP. Плюс PixelSnapH (шаг букв по целым пикселям — так же
        -- выравнивает текст GDI) и RasterizerMultiply 1.30 — плотный
        -- «чернильный» штрих вместо блёклого серого.
        local UI_RASTER_MULT = 1.30
        local function uiFontRasterCfg()
            if type(im) ~= "table" or type(im.ImFontConfig) ~= "function" then
                return nil
            end
            local okc, cfg = pcall(im.ImFontConfig)
            if not okc or not cfg then return nil end
            local okm = pcall(function()
                cfg.RasterizerMultiply = UI_RASTER_MULT
                cfg.OversampleH = 1
                cfg.OversampleV = 1
                cfg.PixelSnapH = true
                if tonumber(cfg.RasterizerMultiply) ~= UI_RASTER_MULT then
                    error("RasterizerMultiply не применился")
                end
            end)
            if not okm then return nil end
            return cfg
        end
        local function uiFontBuild(rebuild)
            if GRND_FONT.fontInitDone then return end
            if uiFontAdoptShared() then return end
            GRND_FONT.fontInitDone = true
            GRND_FONT.fontObj = false
            -- v1.7.0: конфиг шрифта (grnd_ui.cfg, перенос из grnd_chat.cfg)
            -- читается здесь: окна «Настройки чата» больше нет.
            pcall(grndUiCfgLoad)
            -- v1.7.8: миграция старого умолчания. Arial попадал в grnd_ui.cfg
            -- как шрифт ПО УМОЛЧАНИЮ и пережил бы смену умолчания на Segoe UI.
            -- Сохранённый arial.ttf (без признака ручного выбора) считается
            -- старым умолчанием и заменяется шрифтом из нового списка; вернуться
            -- к Arial можно кнопками < > в настройках чекера.
            if type(GRND_FONT.fontPath) == "string"
               and GRND_FONT.fontPath:lower():match("arial%.ttf$")
               and not GRND_FONT.fontUserChosen then
                pcall(grndTrace, "font",
                    "в конфиге старое умолчание arial.ttf — заменяю шрифтом нового списка")
                GRND_FONT.fontPath, GRND_FONT.fontName = nil, nil
                GRND_FONT.cfgDirty = true
            end
            local path = klNormalFontPath(uiFontCandidates()[1])
            if not path then
                pcall(grndTrace, "font", "шрифт интерфейса: файл не найден — системный")
                return
            end
            local ok, err = pcall(function()
                local io3 = im.GetIO()
                local fonts = io3.Fonts
                local ranges
                if fonts.GetGlyphRangesCyrillic then
                    ranges = fonts:GetGlyphRangesCyrillic()
                end
                local fcfg = uiFontRasterCfg()
                -- v1.7.9: лог в moonloader.log — применился ли растер-конфиг.
                -- Если написано «НЕ поддержан», обёртка строит атлас по
                -- умолчанию (оверсэмплинг 3x) — и текст остаётся мягким.
                pcall(grndTrace, "font", fcfg
                    and ("растер-конфиг применён: Oversample 1/1, PixelSnapH, Multiply "
                         .. tostring(UI_RASTER_MULT))
                    or "растер-конфиг НЕ поддержан обёрткой — стандартная растеризация stb")
                -- v1.7.8: добавление шрифта с безопасным откатом:
                --   1) растер-конфиг + кириллица (желаемый вариант);
                --   2) кириллица без растер-конфига;
                --   3) что получится (только для основного шрифта).
                -- Для «лестницы» вариант 3 запрещён: кегль без кириллицы
                -- не должен попадать в оверлеи.
                local function addTTF(sz, cyrOnly)
                    if ranges then
                        if fcfg then
                            local oka, ra = pcall(fonts.AddFontFromFileTTF,
                                                  fonts, path, sz, fcfg, ranges)
                            if oka and ra then return ra end
                        end
                        local okb, rb = pcall(fonts.AddFontFromFileTTF,
                                              fonts, path, sz, nil, ranges)
                        if okb and rb then return rb end
                    end
                    if cyrOnly then return nil end
                    local okc2, rc = pcall(fonts.AddFontFromFileTTF, fonts, path, sz)
                    if okc2 and rc then return rc end
                    return nil
                end
                local f = addTTF(UI_FONT_BASE)
                if not f and im.AddFontFromFileTTF then
                    local okd, rd = pcall(im.AddFontFromFileTTF, path, UI_FONT_BASE)
                    if okd then f = rd end
                end
                -- v1.5.2: «лестница» размеров. Оверлеи (килл-лист) берут
                -- шрифт, УЖЕ отрисованный под нужный кегль, — текст не
                -- растягивается через SetWindowFontScale и не мылится.
                -- v1.5.4: шаг «лестницы» стал плотнее (11,13,16,19,23,28,34
                -- -> 9..40 через ~2 px). Из-за крупного шага ближайший кегль
                -- отличался от нужного на 8-9 %, и панель «не увеличивалась»
                -- так, как ожидалось. Теперь отклонение <= 6 %.
                -- v1.7.8: добавлены кегли 16, 20, 24, 28, 34, 38 — при базе 16
                -- это масштабы 1.0 / 1.25 / 1.5 / 1.75 и соседние: чаще всего
                -- панель попадает в кегль ТОЧНО. (Раньше 16 не было вовсе —
                -- даже масштаб 1.0 рисовал 17-й кегль с растяжкой 16/17.)
                local ladder = im.__grndFontLadder or {}
                if ranges then
                    for _, lsz in ipairs({ 9, 11, 13, 15, 16, 17, 19, 20, 21,
                                           23, 24, 26, 28, 29, 32, 34, 36,
                                           38, 40 }) do
                        if not ladder[lsz] then
                            local lf = addTTF(lsz, true)
                            if lf then ladder[lsz] = lf end
                        end
                    end
                end
                if next(ladder) then im.__grndFontLadder = ladder end
                -- v1.5.7: список кеглей «лестницы» — для карточки и дампа
                local szl = {}
                for sz in pairs(ladder) do szl[#szl + 1] = tonumber(sz) or 0 end
                table.sort(szl)
                GRND_FONT.ladderSizes = szl
                if f then
                    if rebuild and im.RebuildFonts then
                        im.RebuildFonts()
                    end
                    GRND_FONT.fontObj = f
                    GRND_FONT.fontBase = UI_FONT_BASE
                    GRND_FONT.fontLoadedPath = path
                    im.__grndUiFont = f
                    im.__grndUiFontBase = UI_FONT_BASE
                    im.__grndUiFontPath = path
                    pcall(grndTrace, "font", "шрифт интерфейса загружен: " .. path)
                end
            end)
            if not ok then
                pcall(grndTrace, "font", "шрифт интерфейса не загрузился: " .. tostring(err))
            end
        end
        local function uiFontRegister()
            if GRND_FONT.fontHooked then return end
            GRND_FONT.fontHooked = true
            pcall(grndUiCfgLoad)
            pcall(uiFontAdoptShared)
            if imKind == "mimgui" and type(im.OnInitialize) == "function" then
                im.OnInitialize(function() uiFontBuild(false) end)
            else
                im.__grndFontHooks = im.__grndFontHooks or {}
                im.__grndFontHooks[#im.__grndFontHooks + 1] = function()
                    pcall(uiFontBuild, true)
                end
                if not im.__grndFontWrapped then
                    im.__grndFontWrapped = true
                    local prev = im.BeforeDrawFrame
                    im.BeforeDrawFrame = function(...)
                        if type(prev) == "function" then
                            local okp, e = pcall(prev, ...)
                            if not okp then pcall(grndTrace, "font", "чужой BeforeDrawFrame упал: " .. tostring(e)) end
                        end
                        for _, h in ipairs(im.__grndFontHooks) do
                            local okh, eh = pcall(h, ...)
                            if not okh then pcall(grndTrace, "font", "font-хук упал: " .. tostring(eh)) end
                        end
                    end
                end
            end
        end
        local function uiFontGet()
            return GRND_FONT.fontObj
        end
        local function uiPushFont()
            local f = uiFontGet()
            if type(f) == "number" or type(f) == "cdata" or type(f) == "table" then
                local ok = pcall(im.PushFont, f)
                if ok then return true end
            end
            return false
        end
        local function uiPopFont(pushed)
            if pushed then pcall(im.PopFont) end
        end
        -- v1.5.2: ближайший по кеглю шрифт из «лестницы» (см. uiFontBuild).
        -- nil = лестницы нет, вызывающий код рисует старым способом.
        -- v1.6.3: при РАВНОМ удалении (запросили 16, а в «лестнице» 15 и 17)
        -- берём КРУПНЕЙШИЙ кегль: порядок перебора pairs() непредсказуем, и
        -- панель то оставляла старый размер, то прыгала вниз. Заодно возвращаем
        -- сам размер. v1.7.8: вызывающий код рисует этим кеглем как НАТИВНЫМ
        -- (без остаточной растяжки SetWindowFontScale) — текст резкий всегда.
        function grndUiFontPick(px)
            local L = im and im.__grndFontLadder
            if type(L) ~= "table" then return nil end
            local best, bsz, bd
            px = tonumber(px) or 16
            for sz, f in pairs(L) do
                local n = tonumber(sz) or 0
                local d = math.abs(n - px)
                if bd == nil or d < bd or (d == bd and n > (bsz or 0)) then
                    best, bsz, bd = f, n, d
                end
            end
            return best, bsz
        end
        local MENU_WIN_FLAGS = wf("NoTitleBar", "NoResize", "NoCollapse",
            "NoScrollbar", "NoScrollWithMouse")
        menu = {
            open = false,
            tab = 1,
            settingsTab = "main",
            anim = 0,
            indY = nil,
            posInit = false,
        }
        _G.GRND_MENU = menu   -- для диагностики (/grnd) и автотестов
        do
            local saved=GRND_CONFIG.ensure().layout.menu or {}
            menu.tab=math.max(1,math.min(#MENU_TABS,math.floor(tonumber(saved.tab) or 1)))
            menu.settingsTab=saved.settingsTab=="admin" and "admin" or "main"
            menu.adminPanel=(saved.adminPanel=="ring" or saved.adminPanel=="tracer") and saved.adminPanel or "general"
        end
        local scoreboard = {
            anim = 0,
            streamOnly = false,
            search = "",
            buf = nil,
            bufKind = nil,
            cacheT = 0,
            players = {},
            total = 0,
            server = "",
            localId = -1,
        }
        -- =============================================================
        --  МОДУЛЬ 3: drawMenu (M) и drawScoreboard (Tab).
        --  Раньше эти функции вызывались, но не существовали ->
        --  pcall(nil) -> краш кадра -> мёртвые меню/Tab/F1-курсор.
        -- =============================================================
        -- =============================================================
        --  МОДУЛЬ 11 (v1.5.3): ОТРИСОВКА КИЛЛ-ЛИСТА (чекер №1) + ПЕРЕМЕЩЕНИЕ.
        --  Оверлей живёт независимо от меню и таблицы: вызывается из drawAll
        --  каждый кадр, пока чекер включён (данные — из GRND_KL, см. МОДУЛЬ
        --  11 в начале файла: чтение stKillInfo из памяти samp.dll).
        --
        --  Раскладка строки — как в родном списке (эталон от заказчика):
        --      ………Ник_Убийцы[счёт]  [значок оружия]  Ник_Жертвы[счёт]………
        --  ник убийцы стоит в СВОЕЙ колонке (v1.6.1 — всегда по ЛЕВОМУ краю:
--  все строки начинаются с одной линии, левый столбец ровный),
        --  ник жертвы — ОТ ЗНАЧКА вправо; счёт в квадратных скобках того же
        --  цвета, что и ник; значки оружия — в середине строки.
        --
        --  Что нового в v1.5.3:
        --    * ЗНАЧОК ОРУЖИЯ в середине строки вместо текста: тёмный
        --      квадратик со светлым силуэтом. Силуэт выбирается по byteType
        --      записи (id оружия GTA SA / SA-MP): пистолет, дробовик, ПП,
        --      автомат, снайперка, РПГ, граната, холодное, машина, вертолёт,
        --      взрыв, вода, падение, суицид… Тумблер «Название оружия» рядом
        --      со значком выводит ещё и подпись текстом;
        --    * выравнивание строк как на эталоне (убийца — по правому краю
        --      к значку, жертва — по левому от значка); ширина панели держится
        --      по самому длинному нику и не «дёргается» на новых записях;
        --    * ПОДЧЁРКИВАНИЕ — только под одним игроком: под тем ником, на
        --      который наведён курсор (слева от значка — убийца, справа —
        --      жертва). Клик по тому же нику отправляет в слежку за ним же;
        --    * текст рисуется шрифтом ровно в том кегле, в котором он
        --      отрисован в атласе («лестница» im.__grndFontLadder, см.
        --      grndUiFontPick; с v1.7.8 — БЕЗ остаточной растяжки
        --      SetWindowFontScale): глифы не мылятся на любом масштабе;
        --    * имена и оружие берутся из истории чекера, подхват из чата —
        --      страховка, когда структура ещё не найдена.
        -- =============================================================
        local KL_WIN_FLAGS = wf("NoTitleBar", "NoResize", "NoMove", "NoScrollbar",
            "NoCollapse", "NoInputs", "NoSavedSettings")
        local function klMousePos()
            if type(getCursorPos) == "function" then
                local ok, x, y = pcall(getCursorPos)
                if ok and type(x) == "number" and type(y) == "number" then return x, y end
            end
            if im.GetIO then
                local ok, io2 = pcall(im.GetIO)
                if ok and io2 and io2.MousePos and tonumber(io2.MousePos.x) then
                    return tonumber(io2.MousePos.x), tonumber(io2.MousePos.y)
                end
            end
            if GRND_MOUSE and GRND_MOUSE.x then return GRND_MOUSE.x, GRND_MOUSE.y end
            return nil
        end
        local klPrevLmb = false
        local function klLmbTapped()
            local KL = GRND_KL
            if KL and KL.click then
                KL.click = false
                return true
            end
            local down = false
            if type(isKeyDown) == "function" then
                local ok, d = pcall(isKeyDown, 0x01)
                if ok then down = d and true or false end
            elseif GRND_MOUSE then
                down = GRND_MOUSE.down and true or false
            end
            local tapped = down and not klPrevLmb
            klPrevLmb = down
            return tapped
        end
        -- включение/выключение режима «прилип к курсору»
        local function klSetMoving(on, cancelMove)
            local KL = GRND_KL
            if not KL then return end
            if on then
                if KL.moving then return end
                KL.moving = true
                KL.armed = false
                KL.armAt = os.clock() + 0.35
                KL.click = false
                KL.cancel = false
                KL.moveOldX, KL.moveOldY = KL.x, KL.y
                local mx, my = klMousePos()
                if mx and KL.x and KL.y and KL.w and KL.h
                   and mx >= KL.x and mx <= KL.x + KL.w
                   and my >= KL.y and my <= KL.y + KL.h then
                    KL.grabX, KL.grabY = mx - KL.x, my - KL.y
                else
                    KL.grabX = (KL.w or 160) / 2
                    KL.grabY = (KL.h or 60) / 2
                end
                if not KL.enabled then
                    -- размещать выключенную панель бессмысленно: включаем
                    KL.enabled = true
                    KL.cfgDirty = true
                end
                local mn = _G.GRND_MENU
                if mn then mn.open = false end          -- меню закрывается
                pcall(clwShowCursor, true)
                if type(grndUiControls) == "function" then pcall(grndUiControls, true) end
                if type(notify.add) == "function" then
                    pcall(notify.add, "Kill List: двигайте мышью, ЛКМ — закрепить, ESC — отмена", "info", 4)
                end
            else
                if not KL.moving then return end
                KL.moving = false
                KL.click = false
                KL.armed = false
                if cancelMove and KL.moveOldX ~= nil then
                    KL.x, KL.y = KL.moveOldX, KL.moveOldY
                end
                pcall(clwShowCursor, false)
                if type(grndUiControls) == "function" then
                    local mn2=_G.GRND_MENU
                    pcall(grndUiControls,(mn2 and mn2.open) or GRND_TAB.open
                        or (_G.GRND_REP and _G.GRND_REP.open)
                        or (_G.GRND_RC and _G.GRND_RC.show)
                        or (_G.GRND_KL and _G.GRND_KL.moving)
                        or (_G.GRND_AO and _G.GRND_AO.moving))
                end
                KL.cfgDirty = true
                pcall(grndKlCfgSave)
                if type(notify.add) == "function" then
                    pcall(notify.add, cancelMove and "Kill List: перемещение отменено"
                        or "Kill List: позиция закреплена",
                        cancelMove and "warn" or "ok", 3)
                end
            end
        end
        function grndKlStartMoving()
            pcall(klSetMoving, true)
        end

        local function klArgbCol(c)
            if type(c) ~= "number" or c == 0 then return 235, 240, 245 end
            local u = math.floor(c) % 0x100000000
            local r = math.floor(u / 0x10000) % 256
            local g = math.floor(u / 0x100) % 256
            local b = u % 256
            if r + g + b == 0 then return 235, 240, 245 end
            return r, g, b
        end

        -- ПРИМЕЧАНИЕ (v1.5.4): таблица подписей KL_WNAME теперь живёт в блоке
        -- значков ниже — вместе со спрайтами, потому что она описывает ровно
        -- те же id, что и ячейки атласа (см. «ЗНАЧКИ «ЧЕМ УБИТ»»).

        -- =============================================================
        --  ЗНАЧКИ «ЧЕМ УБИТ» — ОРИГИНАЛЬНЫЕ СПРАЙТЫ КИЛЛ-ЛИСТА (v1.5.4+)
        -- =============================================================
        --  Раньше силуэт рисовался вручную (палочки/квадратики) — это был
        --  НЕ тот значок, что в родном списке, и он «не совпадал» с игрой.
        --  Теперь берутся РОВНО ТЕ ЖЕ спрайты, которые клиент SA-MP
        --  показывает в родном килл-листе (набор CSprite2d у CDeathWindow,
        --  textures\killicons.txd): тёмный скруглённый квадратик 23x24 +
        --  светлый силуэт оружия, пиксель-в-пиксель, без перерисовки.
        --
        --  Как это работает:
        --    * атлас — PNG в base64 в начале файла (GRND_KL_ATLAS_PNG):
        --      ячейка 24x24, 8 колонок, канва 256x256 (степень двойки —
        --      так надёжнее для D3D9), порядок значков = GRND_KL_ATLAS_IDS;
        --    * атлас один раз распаковывается в текстуру ImGui:
        --      mimgui  — CreateTextureFromFileInMemory(данные, размер);
        --      moonimgui — CreateTextureFromMemory(указатель, размер);
        --    * рисуется AddImage по UV, поэтому значок аккуратный и чёткий
        --      на любом размере панели (в клиенте спрайт тянулся до 100x100,
        --      здесь он ровно по кеглю строки и пропорций 23:24);
        --    * если сборка ImGui текстуры не умеет — включается прежний
        --      рисованный силуэт (klGlyphProc), чтобы значок не пропадал.
        --
        --  Особенности набора (ровно как в клиенте):
        --    44 (ПНВ)      — своего спрайта нет, берётся 45 (тепловизор);
        --    255 (суицид)  — своего спрайта нет, берётся 53 (утопление,
        --                    «череп с костями»);
        --    47/48/52      — в клиенте отсутствуют;
        --    неизвестный id — клиент рисует общий «череп с костями»
        --                    (SA-MP wiki, SendDeathMessage: «If 'reason' is
        --                    invalid, a generic skull-and-crossbones icon is
        --                    shown») — так же поступаем и мы;
        --    запись из чата без id — общий силуэт оружия, совсем без
        --                    подписи — «череп с костями» (как «неизвестно»).
        local ATL = GRND_KL_ATLAS or {}
        GRND_KL_ATLAS = ATL
        ATL.cell = ATL.cell or 24
        ATL.cols = ATL.cols or 8

        local function klAtlasSync()
            ATL.ids = ATL.ids or {}
            if #ATL.ids == 0 then
                for i, v in ipairs(GRND_KL_ATLAS_IDS or {}) do ATL.ids[i] = v end
            end
            ATL.cell = ATL.cell or GRND_KL_ATLAS_CELL or 24
            ATL.cols = ATL.cols or GRND_KL_ATLAS_COLS or 8
            ATL.tw = ATL.tw or GRND_KL_ATLAS_W or 256
            ATL.th = ATL.th or GRND_KL_ATLAS_H or 256
            ATL.rows = math.max(1, math.ceil(#ATL.ids / math.max(1, ATL.cols)))
        end

        -- id оружия -> номер ячейки в атласе
        local function klAtlasIndex(id)
            klAtlasSync()
            id = tonumber(id) or 0
            if id == 255 then id = 53 end      -- суицид = спрайт утопления
            if id == 44  then id = 45 end      -- ПНВ = спрайт тепловизора
            for i = 1, #ATL.ids do
                if ATL.ids[i] == id then return i end
            end
            if id > 0 then
                for i = 1, #ATL.ids do            -- неизвестное -> «череп»
                    if ATL.ids[i] == 53 then return i end
                end
            end
            return nil
        end

        -- подписи для тумблера «Название оружия» (по умолчанию выключен:
        -- в родном списке подписи нет, там только значок)
        local KL_WNAME = {
            [1] = "кастет", [2] = "клюшка", [3] = "дубинка", [4] = "нож",
            [5] = "бита", [6] = "лопата", [7] = "кий", [8] = "катана",
            [9] = "пила", [10] = "предмет", [11] = "предмет", [12] = "предмет",
            [13] = "предмет", [14] = "цветы", [15] = "трость",
            [16] = "граната", [17] = "газ", [18] = "коктейль",
            [22] = "кольт", [23] = "пистолет", [24] = "дигл",
            [25] = "дробовик", [26] = "обрез", [27] = "комбат",
            [28] = "узи", [29] = "мп5", [30] = "ак-47", [31] = "м4",
            [32] = "тек-9", [33] = "винтовка", [34] = "снайперка",
            [35] = "рпг", [36] = "ракета", [37] = "огнемёт", [38] = "миниган",
            [39] = "с4", [40] = "детонатор", [41] = "баллон",
            [42] = "огнетушитель", [43] = "фотик", [44] = "пнв",
            [45] = "тепловизор", [46] = "парашют",
            [49] = "машина", [50] = "винт", [51] = "взрыв",
            [53] = "утонул", [54] = "падение", [255] = "суицид",
            [200] = "подключился", [201] = "вышел",
        }

        -- Подпись «чем убит» для записи истории. Пусто = подписи нет.
        local function klWeaponLabel(r)
            if not r then return "" end
            if type(r.wnameu) == "string" and r.wnameu ~= "" then return r.wnameu end
            if r.src == "chat" then return "" end          -- из чата id оружия нет
            local id = tonumber(r.typ)
            if not id then return "" end
            return KL_WNAME[id] or ""
        end

        -- id оружия для значка: у подхваченных из чата записей своего id нет,
        -- поэтому берём общий силуэт оружия либо «неизвестно» (череп).
        local function klIconIdOf(r)
            if not r then return nil end
            local id = tonumber(r.typ)
            -- 0 — это тоже валидный «повод»: кастет (WEAPON_FIST), у клиента
            -- для него свой спрайт (ячейка 1 атласа).
            if id and r.src ~= "chat" then return id end
            if r.src == "chat" then
                if type(r.wnameu) == "string" and r.wnameu ~= "" then return 30 end
                return 53
            end
            return nil
        end

        -- ---------- распаковка атласа в текстуру (один раз) ----------
        local function klB64Decode(s)
            local A = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
            local lut = {}
            for i = 1, #A do lut[A:sub(i, i)] = i - 1 end
            local out, acc, nbits = {}, 0, 0
            for i = 1, #s do
                local ch = s:sub(i, i)
                if ch == "=" then break end
                local v = lut[ch]
                if v then
                    acc = acc * 64 + v
                    nbits = nbits + 6
                    while nbits >= 8 do
                        nbits = nbits - 8
                        out[#out + 1] = string.char(math.floor(acc / 2 ^ nbits) % 256)
                    end
                    acc = acc % 2 ^ nbits
                end
            end
            return table.concat(out)
        end

        -- Создание текстуры: у каждой обёртки ImGui свой способ. Пробуем все
        -- известные по очереди, первый удачный и запоминаем (ATL.how — для
        -- диагностики /grndkl и карточки состояния чекера).
        -- ---------- файл атласа: нужен для CreateTextureFromFile ----------
        --  Некоторые обёртки ImGui умеют грузить текстуру ТОЛЬКО из файла
        --  (D3DXCreateTextureFromFile). Поэтому атлас пишется рядом со
        --  скриптом в resource/grnd/cache/grnd_kl_atlas.png — при первом удачном создании
        --  текстуры и по команде /grndkl tex.
        local function klAtlasFilePath()
            if not ATL.filePath then
                ATL.filePath=grndStoragePath("cache","grnd_kl_atlas.png")
            end
            return ATL.filePath
        end

        local function klAtlasWriteFile(png)
            if ATL.fileOk then return ATL.filePath end
            local path = klAtlasFilePath()
            if not path then ATL.fileWhy = "не нашёл каталог для файла" return nil end
            local ok, f = pcall(io.open, path, "wb")
            if not ok or not f then
                ATL.fileWhy = "файл не записался: " .. tostring(path)
                return nil
            end
            local okw = pcall(f.write, f, png)
            pcall(f.close, f)
            if not okw then ATL.fileWhy = "ошибка записи: " .. tostring(path) return nil end
            ATL.fileOk = true
            return path
        end

        -- буфер ffi с PNG (нужен для способов, принимающих АДРЕС памяти)
        local function klAtlasBuffer()
            if ATL.ptr then return ATL.ptr end
            if ATL.ptrTried then return nil end
            ATL.ptrTried = true
            local okf, ffi = pcall(require, "ffi")
            if not okf or type(ffi) ~= "table" then ATL.ptrWhy = "нет ffi" return nil end
            local okb, buf = pcall(function()
                local b = ffi.new("char[?]", #ATL.png)
                ffi.copy(b, ATL.png, #ATL.png)
                return b
            end)
            if okb and buf then ATL.ptr, ATL.ffi = buf, ffi
            else ATL.ptrWhy = "буфер не создался" end
            return ATL.ptr
        end

        -- Способы создания текстуры: у каждой обёртки ImGui свой. Порядок —
        -- от самого надёжного к самому «древнему».
        local function klAtlasAttempts()
            local list = {}
            local function add(name, fn) list[#list + 1] = { name = name, fn = fn } end
            if type(im.CreateTextureFromFileInMemory) == "function" then
                add("CreateTextureFromFileInMemory(данные, размер)", function()
                    return im.CreateTextureFromFileInMemory(ATL.png, #ATL.png)
                end)
            end
            if type(im.CreateTextureFromFile) == "function" then
                add("CreateTextureFromFile(grnd_kl_atlas.png)", function()
                    local path = klAtlasWriteFile(ATL.png)
                    if not path then return nil, ATL.fileWhy or "файл недоступен" end
                    return im.CreateTextureFromFile(path)
                end)
            end
            if type(im.CreateTextureFromMemory) == "function" then
                add("CreateTextureFromMemory(адрес, размер)", function()
                    local buf = klAtlasBuffer()
                    if not buf then return nil, ATL.ptrWhy or "нет буфера" end
                    local addr = buf
                    if ATL.ffi then
                        local okn, n = pcall(function()
                            return tonumber(ATL.ffi.cast("uintptr_t", buf))
                        end)
                        if okn and type(n) == "number" then addr = n end
                    end
                    return im.CreateTextureFromMemory(addr, #ATL.png)
                end)
            end
            if type(im.CreateTextureFromMemoryRaw) == "function" then
                add("CreateTextureFromMemoryRaw(адрес, размер)", function()
                    local buf = klAtlasBuffer()
                    if not buf then return nil, ATL.ptrWhy or "нет буфера" end
                    local addr = buf
                    if ATL.ffi then
                        local okn, n = pcall(function()
                            return tonumber(ATL.ffi.cast("uintptr_t", buf))
                        end)
                        if okn and type(n) == "number" then addr = n end
                    end
                    return im.CreateTextureFromMemoryRaw(addr, #ATL.png)
                end)
            end
            if type(im.LoadTextureFromFile) == "function" then
                add("LoadTextureFromFile(grnd_kl_atlas.png)", function()
                    local path = klAtlasWriteFile(ATL.png)
                    if not path then return nil, ATL.fileWhy or "файл недоступен" end
                    return im.LoadTextureFromFile(path)
                end)
            end
            return list
        end

        -- Создание текстуры атласа. Каждая попытка попадает в ATL.tries
        -- (её печатает /grndkl и /grndkl tex) — по ней видно, что именно
        -- не получилось на конкретной сборке.
        function grndKlAtlasEnsure(force)
            if force then ATL.tried, ATL.tex, ATL.how = false, nil, nil end
            if ATL.tried then return ATL.tex ~= nil end
            ATL.tried = true
            klAtlasSync()                      -- размеры/список ячеек атласа
            ATL.tries = {}
            if type(im) ~= "table" then ATL.why = "нет ImGui" return false end
            local okd, png = pcall(klB64Decode, GRND_KL_ATLAS_PNG or "")
            if not okd or type(png) ~= "string" or #png < 64 then
                ATL.why = "атлас не распаковался"
                pcall(grndTrace, "killlist", "значки: base64 атласа не декодировался")
                return false
            end
            ATL.png = png
            -- какие функции текстур вообще есть в обёртке (для диагностики)
            local have = {}
            for _, n in ipairs({ "CreateTextureFromFile", "CreateTextureFromFileInMemory",
                                 "CreateTextureFromMemory", "CreateTextureFromMemoryRaw",
                                 "LoadTextureFromFile" }) do
                if type(im[n]) == "function" then have[#have + 1] = n end
            end
            ATL.have = have
            if #have == 0 then
                ATL.why = "у обёртки ImGui нет функций для текстур"
                pcall(grndTrace, "killlist", "значки килл-листа: " .. ATL.why)
                return false
            end
            for _, att in ipairs(klAtlasAttempts()) do
                local ok, t, err = pcall(att.fn)
                local rec = { name = att.name, ok = false, err = nil }
                if not ok then
                    rec.err = tostring(t)
                elseif t then
                    rec.ok = true
                    ATL.tex, ATL.how = t, att.name
                else
                    rec.err = tostring(err or "функция вернула nil")
                end
                ATL.tries[#ATL.tries + 1] = rec
                if rec.ok then break end
            end
            if ATL.tex then
                pcall(grndTrace, "killlist", "значки килл-листа: оригинальный атлас загружен ("
                    .. tostring(ATL.how) .. ", " .. tostring(ATL.tw) .. "x" .. tostring(ATL.th) .. ")")
                return true
            end
            local firstErr
            for _, tr in ipairs(ATL.tries) do
                if not tr.ok and tr.err then firstErr = tr.err break end
            end
            ATL.why = "ни один способ не подошёл" .. (firstErr and (" (" .. firstErr .. ")") or "")
            pcall(grndTrace, "killlist", "значки килл-листа: атлас не загрузился — запасной рисованный силуэт")
            return false
        end

        -- Повторить загрузку атласа и напечатать журнал попыток (/grndkl tex).
        function grndKlAtlasDiag()
            grndKlSay("— значки килл-листа —")
            grndKlSay(("обёртка ImGui: %s"):format(tostring(IMGUI_WRAP or "не определена")))
            grndKlSay(("файл атласа: %s%s"):format(
                tostring(ATL.filePath or klAtlasFilePath() or "—"),
                ATL.fileOk and " (записан)" or ""))
            if not ATL.tex then pcall(grndKlAtlasEnsure, true) end
            if ATL.tex then
                grndKlSay(("атлас ЗАГРУЖЕН: способ «%s», текстура %sx%s"):format(
                    tostring(ATL.how), tostring(ATL.tw), tostring(ATL.th)))
                return true
            end
            grndKlSay("атлас НЕ загружен — рисуется запасной силуэт")
            grndKlSay(("функции обёртки: %s"):format(
                (#(ATL.have or {}) > 0) and table.concat(ATL.have, ", ")
                or "НИ ОДНОЙ (текстуры этой сборкой не поддерживаются)"))
            for i, tr in ipairs(ATL.tries or {}) do
                grndKlSay(("  %d) %s -> %s"):format(i, tr.name,
                    tr.ok and "ок" or ("не вышло: " .. tostring(tr.err))))
            end
            if ATL.fileWhy then grndKlSay("  про файл: " .. tostring(ATL.fileWhy)) end
            if ATL.ptrWhy then grndKlSay("  про буфер: " .. tostring(ATL.ptrWhy)) end
            grndKlSay("  пришли эти строки — добавим способ под твою сборку")
            return false
        end

        -- Нарисовать значок из атласа. false = текстуры нет, нужен запасной путь.
        local function klIconBlit(dl, at, x, y, sz, id, a)
            if not (dl and id and sz and sz >= 6) then return false end
            if not grndKlAtlasEnsure() then return false end
            local idx = klAtlasIndex(id)
            if not idx then return false end
            klAtlasSync()
            local cell, cols, rows = ATL.cell, ATL.cols, ATL.rows
            local tw, th = ATL.tw, ATL.th
            local col = (idx - 1) % cols
            local row = math.floor((idx - 1) / cols)
            local iw, ih = 23, 24                       -- область спрайта в ячейке
            local W = math.max(1, math.floor(sz + 0.5))
            local H = math.max(1, math.floor(sz * (ih / iw) + 0.5))
            local u0, v0 = (col * cell) / tw, (row * cell) / th
            local u1, v1 = (col * cell + iw) / tw, (row * cell + ih) / th
            local p1, p2 = at(x, y), at(x + W, y + H)
            local uv0, uv1 = im.ImVec2(u0, v0), im.ImVec2(u1, v1)
            -- цвета спрайта родные (тёмный квадратик + светлый силуэт):
            -- множитель белый, меняется только прозрачность панели
            local tint = col32(255, 255, 255,
                math.max(0, math.min(255, math.floor(255 * (a or 1)))))
            if type(dl.AddImage) == "function" then
                if pcall(dl.AddImage, dl, ATL.tex, p1, p2, uv0, uv1, tint) then return true end
                if pcall(dl.AddImage, dl, ATL.tex, p1, p2, uv0, uv1) then return true end
                if pcall(dl.AddImage, dl, ATL.tex, p1, p2) then return true end
                if type(dl.Image) == "function"
                   and pcall(dl.Image, dl, ATL.tex, p1, p2, uv0, uv1, tint) then return true end
            end
            return false
        end

        -- ---------- ЗАГРУЗКА ТЕКСТУРЫ — ТОЛЬКО ВНЕ КАДРА ----------
        --  Обёртки ImGui создают текстуру в видео-памяти, и делать это
        --  ВНУТРИ кадра нельзя (в документации mimgui/moonimgui: загрузка
        --  текстур — «обязательно вне OnDrawFrame», иначе рендер может
        --  упасть). Поэтому просим загрузку у хуков инициализации:
        --    mimgui   — im.OnInitialize(fn)  (вызывается один раз);
        --    moonimgui — свой BeforeDrawFrame (покадровый, но ДО кадра,
        --                как уже сделано для шрифта интерфейса).
        --  Ленивый вызов при первой отрисовке остаётся последним шансом
        --  (если хуков в сборке нет вовсе).
        function grndKlAtlasPreload()
            pcall(grndBrandLogoLoad,im)
            pcall(grndKlRunsBuild)                 -- прогоны значков: доступны всегда
            if ATL.tried and ATL.tex then return true end
            return pcall(grndKlAtlasEnsure)    -- текстура: как повезёт с обёрткой
        end
        if not ATL.hooked then
            ATL.hooked = true
            local hooked = false
            if type(im.OnInitialize) == "function" then
                hooked = pcall(im.OnInitialize, function()
                    GRND_BRAND_LOGO.retryAt=nil
                    pcall(grndKlAtlasPreload)
                end)
            end
            if not hooked then
                im.__grndTexHooks = im.__grndTexHooks or {}
                im.__grndTexHooks[#im.__grndTexHooks + 1] = function() pcall(grndKlAtlasPreload) end
                if not im.__grndTexWrapped then
                    im.__grndTexWrapped = true
                    local prevTex = im.BeforeDrawFrame
                    im.BeforeDrawFrame = function(...)
                        if type(prevTex) == "function" then
                            local okp, ep = pcall(prevTex, ...)
                            if not okp then pcall(grndTrace, "killlist", "чужой BeforeDrawFrame упал: " .. tostring(ep)) end
                        end
                        for _, h in ipairs(im.__grndTexHooks) do
                            local okh, eh = pcall(h, ...)
                            if not okh then pcall(grndTrace, "killlist", "хук текстуры упал: " .. tostring(eh)) end
                        end
                    end
                end
            end
            -- ImGui мог быть уже инициализирован (например, скрипт
            -- перезапущен) — тогда грузим сразу, мы всё равно вне кадра.
            pcall(grndKlAtlasPreload)
        end
        -- Сброс D3D-устройства забирает текстуры вместе с собой: помечаем
        -- атлас недействительным, он перезагрузится перед следующим кадром.
        if type(addEventHandler) == "function" and not ATL.resetHooked then
            ATL.resetHooked = true
            pcall(addEventHandler, "onD3DDeviceReset", function()
                ATL.tex, ATL.tried, ATL.how = nil, false, nil
                GRND_BRAND_LOGO.tex,GRND_BRAND_LOGO.retryAt=nil,nil
                ATL.needReload = true
                pcall(grndKlAtlasPreload)
            end)
        end

        -- =============================================================
        --  ОТРИСОВКА ЗНАЧКОВ БЕЗ ТЕКСТУРЫ (v1.5.6)
        -- =============================================================
        --  У некоторых сборок ImGui функций CreateTexture* нет вообще, и
        --  значок раньше подменялся самодельной геометрией (палочки) — это и
        --  было «не тот значок». Теперь так: в скрипт вшиты «прогоны» —
        --  горизонтальные полоски пикселей КАЖДОГО спрайта, разложенные по
        --  5 тонам (тёмный тайл + 3 оттенка силуэта + цветной акцент).
        --  Значок собирается обычными AddRectFilled — те же 23x24 пикселя и
        --  те же цвета, что в родном списке, только собранные по полоскам.
        --  Средняя точность сборки — 97.4 % пикселей (проверено сверкой с
        --  исходными спрайтами, см. build_atlas.py рядом со сборкой).
        local KL_RUN_COL = {
            [1] = {    8,   8,   9 },   -- тёмный скруглённый квадратик
            [2] = {  111, 111, 111 },
            [3] = {  174, 174, 174 },
            [4] = {  248, 247, 248 },
        }

        function grndKlRunsBuild()
            if ATL.runs ~= nil then return ATL.runs end
            ATL.runs = false
            local data = klB64Decode(GRND_KL_ICON_RUNS or "")
            if type(data) ~= "string" or #data < 128 then
                ATL.runsWhy = "данные значков не распаковались"
                return false
            end
            local icons, i, n = {}, 1, #data
            while i + 6 <= n do
                local x0, y0, x1, y1 = data:byte(i, i + 3)
                local ar, ag, ab = data:byte(i + 4, i + 6)
                i = i + 7
                local runs = {}
                while i <= n do
                    local b = data:byte(i)
                    if not b or b == 0xFF then i = i + 1 break end
                    runs[#runs + 1] = { t = math.floor(b / 32), y = b % 32,
                                        x0 = data:byte(i + 1), x1 = data:byte(i + 2) }
                    i = i + 3
                end
                icons[#icons + 1] = { x0 = x0, y0 = y0, x1 = x1, y1 = y1,
                                      ar = ar, ag = ag, ab = ab, runs = runs }
            end
            if #icons == 0 then
                ATL.runsWhy = "в данных значков нет ни одной записи"
                return false
            end
            ATL.runs = icons
            ATL.runsCount = #icons
            return icons
        end

        -- Нарисовать значок из прогонов. false = нет данных/нет DrawList.
        local function klRunsDraw(dl, at, x, y, bs, id, a)
            if not (dl and dl.AddRectFilled and bs and bs >= 6) then return false end
            local icons = grndKlRunsBuild()
            if not icons then return false end
            local idx = klAtlasIndex(id)
            if not idx then return false end
            local ic = icons[idx]
            if not ic then return false end
            local k = (bs / 23)                    -- спрайт 23 px по ширине
            local A = math.max(0, math.min(255, math.floor(255 * (a or 1))))
            local tile = KL_RUN_COL[1]
            pcall(dl.AddRectFilled, dl, at(x + ic.x0 * k, y + ic.y0 * k),
                at(x + (ic.x1 + 1) * k, y + (ic.y1 + 1) * k),
                col32(tile[1], tile[2], tile[3], A),
                math.min(6, math.max(1, 5 * k)))    -- скругление как в спрайте
            for i = 1, #ic.runs do
                local r = ic.runs[i]
                local c = KL_RUN_COL[r.t]
                if not c and r.t == 5 then c = { ic.ar, ic.ag, ic.ab } end
                if c then
                    pcall(dl.AddRectFilled, dl, at(x + r.x0 * k, y + r.y * k),
                        at(x + (r.x1 + 1) * k, y + (r.y + 1) * k),
                        col32(c[1], c[2], c[3], A))
                end
            end
            return true
        end

        -- Единая точка входа. Порядок:
        --   1) текстура атласа (быстрее и точнее всего);
        --   2) сборка значка из вшитых прогонов пикселей (работает всегда,
        --      даже если обёртка ImGui не умеет текстуры);
        --   3) ничего — строка просто без значка (крайний случай).
        -- Никаких «рисованных от руки» силуэтов: значок либо оригинальный,
        -- либо его нет. DrawList трогаем только AddRectFilled/AddImage —
        -- AddLine в этом блоке занят подчёркиванием никf (и по нему идут тесты).
        local function klWeaponGlyph(dl, at, x, y, bs, rec, a, us, col, hole)
            local id = klIconIdOf(rec)
            if not id then return false end
            if klIconBlit(dl, at, x, y, bs, id, a) then return true end
            return klRunsDraw(dl, at, x, y, bs, id, a)
        end

        -- Слежка по клику: тот же путь, что и у строки табло —
        -- GRND_TAB.specId = ID, дальше основной цикл отправит «/sp ID».
        local function klSpecGo(nick, id)
            if not id and type(grndKlFindId) == "function" then
                local ok, r = pcall(grndKlFindId, nick)
                if ok then id = r end
            end
            if not id then
                if type(notify.add) == "function" then
                    pcall(notify.add, "Kill List: " .. tostring(nick) .. " — не в сети", "warn", 3)
                end
                return false
            end
            if type(GRND_TAB) ~= "table" then return false end
            GRND_TAB.specId = id
            GRND_TAB.open = false            -- как при клике по строке табло
            if type(notify.add) == "function" then
                pcall(notify.add, "Слежка: " .. tostring(nick) .. " (#" .. tostring(id) .. ")", "info", 3)
            end
            return true
        end

        -- =================================================================
        --  v1.8.1: DX-ТЕКСТ КИЛ-ЛИСТА — рендер как у чата SA-MP (ID3DXFont).
        --  Атлас ImGui (stb_truetype) при любой настройке остаётся «мягким»
        --  рядом с чатом SA-MP: чат рисует текст GDI-шрифтом — с хинтингом,
        --  чёткими стволами букв, пиксель-в-пиксель. Присланный пользователем
        --  образец («как на изображении») — именно такой рендер. Поэтому
        --  надписи кил-листа рисует renderFontDrawText (lib.moonloader), а
        --  геометрия панели, значки «чем убит», подчёркивание и рамка
        --  остаются ImGui. Нет render-библиотеки (старый MoonLoader) —
        --  автоматический откат на прежний ImGui-текст.
        -- =================================================================
        local klDx = { fonts = {}, dead = false, fam = nil }
        local function klDxFamily()
            if klDx.fam then return klDx.fam end
            -- fontName в конфиге — имя файла без расширения («segoeui»);
            -- GDI нужен титул семейства: известные переводим, прочие
            -- пробуем как есть (GDI сам подставит замену, если не знает)
            local known = {
                segoeui = "Segoe UI", tahoma = "Tahoma", arial = "Arial",
                verdana = "Verdana", calibri = "Calibri", trebuc = "Trebuchet MS",
            }
            local nm = tostring(GRND_FONT and GRND_FONT.fontName or "")
            if nm == "" then nm = "Segoe UI" end
            local key = nm:lower():gsub("%s+", "")
            klDx.fam = known[key] or nm
            return klDx.fam
        end
        -- цвет для render-функций: 0xAARRGGBB (у ImGui порядок байтов иной)
        local function klDxCol(r, g, b, al)
            local function cc(v)
                v = math.floor(tonumber(v) or 0)
                if v < 0 then v = 0 elseif v > 255 then v = 255 end
                return v
            end
            return cc(al) * 0x1000000 + cc(r) * 0x10000 + cc(g) * 0x100 + cc(b)
        end
        -- шрифт под кегль (кэш по «кегль|семейство»). Высота с «минусом»:
        -- GDI считает её высотой эм-квадрата, кегль совпадает с ImGui-шрифтом
        -- той же цифры. 1 = FCR_BOLD — плотный штрих, как на образце.
        local function klDxFont(px)
            if GRND_KL and GRND_KL.dxReset then
                klDx.fonts, klDx.fam, klDx.dead = {}, nil, false
                GRND_KL.dxReset = false
            end
            if klDx.dead then return nil end
            if type(renderCreateFont) ~= "function"
                or type(renderFontDrawText) ~= "function"
                or type(renderGetFontDrawTextLength) ~= "function" then
                klDx.dead = true
                pcall(grndTrace, "killlist",
                    "render-библиотека недоступна — текст кил-листа через ImGui")
                return nil
            end
            px = math.floor(tonumber(px) or 16)
            if px < 7 then px = 7 end
            local key = tostring(px) .. "|" .. klDxFamily()
            local f = klDx.fonts[key]
            if f then return f end
            -- v1.8.2: RUSSIAN_CHARSET (204) — иначе GDI рисует кириллицу
            -- «закорчками», даже если строка уже в CP1251.
            local fam = klDxFamily()
            local font
            local ok4, f4 = pcall(renderCreateFont, fam, -px, 1, 204)
            if ok4 and f4 then font = f4 end
            if not font then
                local ok, f = pcall(renderCreateFont, fam, -px, 1)
                if ok and f then font = f end
            end
            if font then
                klDx.fonts[key] = font
                pcall(grndTrace, "killlist", "DX-шрифт кил-листа: "
                    .. fam .. " " .. tostring(px) .. " px, жирный, charset 204")
                return font
            end
            klDx.dead = true
            pcall(grndTrace, "killlist",
                "renderCreateFont не удался — текст кил-листа через ImGui")
            return nil
        end

        -- чекер админов: Tahoma, целый кегль, жирный+обводка — без мыла Segoe UI
        local aoDxFonts, aoDxBordered = {}, {}
        local function aoDxFont(px)
            px = math.floor(tonumber(px) or 14)
            if px < 7 then px = 7 elseif px > 32 then px = 32 end
            local f = aoDxFonts[px]
            if f then return f, aoDxBordered[px] end
            if type(renderCreateFont) ~= "function" then
                return klDxFont(px), false
            end
            local font, bordered = nil, false
            local ok, r = pcall(renderCreateFont, "Tahoma", -px, 5, 204)
            if ok and r then font, bordered = r, true end
            if not font then
                ok, r = pcall(renderCreateFont, "Tahoma", -px, 1, 204)
                if ok and r then font = r end
            end
            if not font then
                ok, r = pcall(renderCreateFont, "Tahoma", -px, 1)
                if ok and r then font = r end
            end
            if not font then return klDxFont(px), false end
            aoDxFonts[px] = font
            aoDxBordered[px] = bordered
            return font, bordered
        end

        local function drawKillList(dt)
            local KL = GRND_KL
            if not KL then return false end
            dt = dt or 0.016
            -- плавное появление/исчезание оверлея
            local target = KL.enabled and 1 or 0
            KL.anim = KL.anim or 0
            if KL.anim < target then KL.anim = math.min(target, KL.anim + dt * 8.0)
            elseif KL.anim > target then KL.anim = math.max(target, KL.anim - dt * 8.0) end
            if KL.anim <= 0 and not KL.moving then
                -- панель скрыта: ширины ников запоминать дальше не нужно
                KL.hwK, KL.hwV, KL.hwKAt, KL.hwVAt = nil, nil, nil, nil
                return false
            end
            local a = 1 - (1 - KL.anim) * (1 - KL.anim)
            if KL.moving then
                a = 1
                pcall(clwShowCursor, true)          -- курсор держим видимым
            end

            local resX, resY = getScreenResolution()
            -- v1.6.3: верхняя граница та же, что у ползунка в чекере (2.5x):
            -- при базовом кегле 16 это ровно 40 px — предел «лестницы» кеглей.
            local sc   = math.max(0.5, math.min(2.5, tonumber(KL.scale) or 1.0))
            local rows = math.max(1, math.min(24, math.floor(tonumber(KL.rows) or 6)))

            -- -------- шрифт: РОДНОЙ кегль «лестницы» (v1.7.8) --------
            -- Панель увеличивается вместе с ползунком «Размер килл-листа»:
            -- растут буквы, значки и шаг строки. v1.6.3 брал ближайший кегль
            -- «лестницы» и доводил его до точного wantPx ОСТАТКОМ
            -- SetWindowFontScale (до ~6 %): глифы сэмплировались мимо своей
            -- сетки, текст был мягким/мыльным на ЛЮБОМ положении ползунка,
            -- кроме точных кеглей (16 в «лестнице» не было вовсе — мылил даже
            -- масштаб 1.0). Теперь растяжки НЕТ:
            --   * запрошенный кегль считается как раньше: baseSize * масштаб;
            --   * берём ближайший шрифт «лестницы» (при равенстве — КРУПНЕЕ)
            --     и рисуем им БЕЗ SetWindowFontScale — ровно в том кегле, в
            --     котором шрифт отрисован в атласе: буквы всегда резкие;
            --   * fpx = этот нативный кегль: от него считаются значки,
            --     отступы и шаг строки, поэтому панель растёт одним куском
            --     и монотонно следует за ползунком (шаг 1-4 px не заметен).
            local baseSize = tonumber(GRND_FONT and GRND_FONT.fontBase) or 16
            local wantPx = math.floor(baseSize * sc + 0.5)
            if wantPx < 9 then wantPx = 9 elseif wantPx > 40 then wantPx = 40 end
            local fobj, fsz
            if type(grndUiFontPick) == "function" then
                local okf, rf, rs = pcall(grndUiFontPick, wantPx)
                if okf then fobj, fsz = rf, tonumber(rs) end
            end
            local fontPushed, fontViaLadder, fsc = false, false, 1
            if fobj and type(im.PushFont) == "function" then
                fontViaLadder = pcall(im.PushFont, fobj) and true or false
            end
            if fontViaLadder then
                fontPushed = true
                -- v1.7.8: остаток до wantPx НЕ доводим (fsc = 1) — рисуем
                -- нативным кеглем, растяжка мылила текст (см. выше)
            else
                fontPushed = uiPushFont()
                fsc = wantPx / baseSize              -- «лестницы» нет: тянем базовый
            end
            if math.abs(fsc - 1) < 0.01 then fsc = 1 end
            local fpx = wantPx                       -- рисуемый кегль
            if fontViaLadder then
                fpx = tonumber(fsz) or wantPx        -- v1.7.8: НАТИВНЫЙ кегль
                if fpx < 9 then fpx = wantPx end
            end
            local us  = fpx / baseSize               -- все размеры панели — от него

            -- v1.8.1: DX-шрифт под текущий кегль (nil -> прежний ImGui-путь)
            local dxf = klDxFont(fpx)
            -- ширина текста: в DX-режиме меряет сам GDI-шрифт (им и рисуем),
            -- в фолбэке — прежняя оценка по ImGui.
            -- v1.8.2: GDI ждёт CP1251, ImGui — UTF-8. Без перевода кириллица
            -- в никах и подписях («пока нет убийств») шла «закорчками».
            local function dxStr(s)
                s = tostring(s or "")
                if dxf and type(grndToAnsi) == "function" then
                    local ok, r = pcall(grndToAnsi, s)
                    if ok and type(r) == "string" then return r end
                end
                return s
            end
            local function dxW(s)
                local raw = tostring(s or "")
                if dxf then
                    local okw, w = pcall(renderGetFontDrawTextLength, dxf, dxStr(raw))
                    if okw and type(w) == "number" and w > 0 then return w end
                end
                return grndTextW(raw) * fsc
            end

            -- -------- метрики строки (v1.6.3: считаем ДО выбора строк) --------
            -- Нужны раньше выбора строк: при крупном масштабе панель может не
            -- влезть в экран, и число строк ограничивается экраном (ниже).
            local padX  = math.floor(10 * us)
            local padY  = math.floor(6 * us)
            -- значок — оригинальный спрайт 23x24, тянем пропорционально кеглю
            local iconW = math.max(10, math.floor(fpx * 1.15 + 0.5))
            local iconH = math.max(11, math.floor(iconW * (24 / 23) + 0.5))
            -- v1.6.5: 4 -> 3 px — ники стоят ещё плотнее к колонке значков
            local gapK  = math.floor(3 * us)                  -- ник убийцы -> колонка
            local gapV  = math.floor(7 * us)                  -- колонка -> ник жертвы
            -- v1.8.3: запас снизу под ЧЕРТУ подчёркивания (не зачёркивание)
            local rowH  = math.max(iconH + 4, math.floor(fpx * 1.30 + 2) + 6)
            -- v1.5.8: ТЕНЬ ТЕКСТА. Раньше под каждой надписью рисовалась
            -- чёрная копия alpha 175 со сдвигом +1/+1: на мелком кегле это
            -- «утолщало» буквы, и нормальный шрифт выглядел псевдожирным.
            -- Тень мягкая и выключается тумблером «Тень».
            -- v1.7.8: 105 -> 88 — при резком нативном кегле и плотном штрихе
            -- (RasterizerMultiply) более лёгкая тень меньше «утяжеляет»
            -- буквы, силуэт глифа остаётся чистым.
            -- v1.8.1: у DX-текста (GDI) штрих плотный, как у чата SA-MP, —
            -- тень заметнее, как на образце пользователя (120); прежний
            -- ImGui-путь остаётся с мягкой тенью 88.
            local shA = (KL.textShadow == false) and 0 or (dxf and 120 or 88)

            -- -------- записи к показу --------
            local hist = KL.hist or {}
            -- v1.6.3: строк берём по настройке «Строк» (она задаётся отдельно),
            -- но не больше, чем влезает в экран при текущем масштабе: крупная
            -- панель иначе уезжала за нижний край. Лишние записи остаются
            -- в истории — они вернутся, если масштаб уменьшить.
            local yDef  = math.floor(resY * 0.30)
            local fitN  = math.floor((resY - (tonumber(KL.y) or yDef) - padY * 2) / rowH)
            if fitN < 1 then fitN = 1 end
            local n = math.min(rows, #hist, fitN)
            local list = {}
            for i = 1, n do list[i] = hist[#hist - n + i] end          -- старые -> новые
            if KL.newestTop then
                local rev = {}
                for i = 1, n do rev[i] = list[n - i + 1] end
                list = rev
            end

            -- -------- замер строк (шрифт уже выбран) --------
            -- «Ник[счёт]» — один текстовый кусок того же цвета, что и ник:
            -- ровно так это выглядит в родном списке.
            local kStr, vStr, wK, wV = {}, {}, {}, {}
            local maxK, maxV, maxN, maxT = 0, 0, 0, 0
            for i = 1, n do
                local r = list[i]
                local ks, vs = tostring(r.ku or r.k or "?"), tostring(r.vu or r.v or "?")
                -- v1.6.1: чистка краёв. Из подхвата из чата ник приходил с
                -- невидимым пробелом впереди (в том числе «мягким» 0xA0/NBSP,
                -- он в UTF-8 — два байта). Из-за него строка начиналась на
                -- несколько пикселей правее соседних, и левый столбец выглядел
                -- неровным, хотя x у всех строк одинаковый.
                ks = ks:gsub("^[%s\194\160]+", ""):gsub("[%s\194\160]+$", "")
                vs = vs:gsub("^[%s\194\160]+", ""):gsub("[%s\194\160]+$", "")
                if ks == "" then ks = "?" end
                if vs == "" then vs = "?" end
                -- v1.8.3: в скобках всегда ID (замороженный при появлении строки)
                local kb, vb = r.kidF, r.vidF
                if kb ~= nil then ks = ks .. "[" .. tostring(kb) .. "]" end
                if vb ~= nil then vs = vs .. "[" .. tostring(vb) .. "]" end
                kStr[i], vStr[i] = ks, vs
                wK[i] = dxW(ks)
                wV[i] = dxW(vs)
                if wK[i] > maxK then maxK = wK[i] end
                if wV[i] > maxV then maxV = wV[i] end
                if KL.showWName then
                    local wn = dxW(klWeaponLabel(r))
                    if wn > maxN then maxN = wn end
                end
                if KL.showTime then
                    local tw = dxW(tostring(r.time or "00:00:00"))
                    if tw > maxT then maxT = tw end
                end
            end
            if n == 0 then
                maxK = dxW("Ник_Игрока[999]")
                maxV = maxK
            end
            -- ШИРИНА КОЛОНОК — по самому длинному нику ИЗ ВИДИМЫХ строк.
            -- v1.6.2: раньше запоминался максимум за всё время, пока панель
            -- видна, и после одного длинного ника в колонке навсегда оставалось
            -- пустое место.
            -- v1.6.4: «минимальное уменьшение — 1 px»:
            --   * ширина считается с точностью 1 px (никаких кратных 4 px —
            --     от такого округления оставалось до 3 px пустого места
            --     между ником и колонкой значков);
            --   * растём сразу — длинный ник никогда не обрезается;
            --   * уменьшаемся РОВНО на 1 px за кадр и уже через 0.25 с после
            --     ухода длинного ника (раньше ждали 1.2 с — пустое место
            --     висело почти всё время, пока список на экране);
            --   * ширины ЦЕЛЫЕ (дробный x — «дрожание» букв).
            -- Если в настройках чекера что-то переключили (счёт, подписи),
            -- запомненное сбрасываем, чтобы панель сразу пересчиталась.
            local clockNow = os.clock()
            local SHRINK_HOLD = 0.25      -- сек: держим прежнюю ширину, потом шагаем
            local function klFitCol(w, key, atKey)
                local target = math.ceil(w)                   -- v1.6.4: точность 1 px
                local prev = tonumber(KL[key]) or 0
                if target >= prev then
                    KL[key], KL[atKey] = target, clockNow     -- выросли сразу
                    return target
                end
                local seen = tonumber(KL[atKey]) or clockNow
                if (clockNow - seen) < SHRINK_HOLD then return prev end
                local step = prev - 1                         -- уменьшение ровно 1 px
                if step < target then step = target end
                KL[key] = step        -- штамп не трогаем: гаснет по 1 px каждый кадр
                return step
            end
            if KL.cfgDirty then KL.hwK, KL.hwV, KL.hwKAt, KL.hwVAt = nil, nil, nil, nil end
            maxK = klFitCol(maxK, "hwK", "hwKAt")
            maxV = klFitCol(maxV, "hwV", "hwVAt")
            maxK, maxV = math.ceil(maxK), math.ceil(maxV)

            -- -------- СЕТКА СТРОКИ (v1.5.7) --------
            -- Левая часть панели должна быть РОВНОЙ, поэтому все опорные
            -- линии считаются один раз на кадр и по ЦЕЛЫМ координатам
            -- (дробный x/y — это «дрожание» букв):
            --   padX | колонка ников убийц | колонка значков |
            --        (подпись оружия) | колонка ников жертв
            -- НИКИ УБИЙЦ ВСЕГДА идут по ЛЕВОМУ краю своей колонки (v1.6.1):
            -- все строки начинаются с одной вертикальной линии, и ровность не
            -- зависит ни от ширины ников, ни от того, насколько точно обёртка
            -- меряет текст, ни от настроек. Режим «прижать каждый ник к значку»
            -- убран — именно он делал левый край колонки ступенькой.
            -- padX, padY, iconW, iconH, gapK, gapV и rowH посчитаны выше —
            -- сразу после выбора кегля (v1.6.3): от них зависит и число строк.
            local wName = 0
            if KL.showWName and maxN > 0 then wName = math.floor(maxN) + gapV end
            -- колонки общие для ВСЕХ строк; их ширина — по самому длинному
            -- нику из видимых строк (KL.hwK/KL.hwV, см. выше), поэтому пустого
            -- места между короткими никами и колонкой значков почти нет
            local colK   = maxK                               -- ширина колонки ников убийц
            local iconX  = padX + colK + gapK                 -- колонка значков
            local vx0    = iconX + iconW + wName + gapV       -- ники жертвы — от колонки
            local hintH  = KL.moving and (math.floor(14 * us) + 8) or 0
            local hint   = "ЛКМ — закрепить   ·   ESC — отмена"
            local W = math.floor(vx0 + maxV + padX)
            local minW = math.floor(150 * us)
            if KL.moving then
                local hw = math.floor(dxW(hint) + padX * 2)
                if hw > minW then minW = hw end
            end
            if W < minW then W = minW end
            local H = math.floor(padY * 2 + math.max(1, n) * rowH + hintH)
            -- для карточки состояния, /grndkl и дампа: чем и как рисуем строку
            KL.dbgAlign = KL.alignK
                and (("ники убийц — вплотную к значку (зазор %d px)"):format(gapK))
                or  (("ники убийц — ровный столбец по левому краю (x=%d)"):format(padX))
            KL.dbgColK, KL.dbgColV = colK, maxV
            KL.dbgIconX, KL.dbgVx0 = iconX, vx0
            KL.dbgFpx  = fpx
            KL.dbgRowH = rowH
            -- v1.6.3: каким остатком доводили кегль и сколько строк влезло
            KL.dbgFsc, KL.dbgFitN = fsc, fitN
            KL.dbgFontViaLadder = fontViaLadder
            -- v1.8.1: сведения о DX-рендере для /grndkl
            KL.dbgDx    = dxf and true or false
            KL.dbgDxFam = dxf and klDxFamily() or nil
            KL.dbgDxPx  = dxf and fpx or nil
            KL.dbgShA   = shA

            -- -------- позиция --------
            if KL.x == nil then KL.x = math.floor(resX - W - 24) end
            if KL.y == nil then KL.y = math.floor(resY * 0.30) end
            -- v1.6.3: панель растёт вместе с масштабом. Если она перестала
            -- влезать в экран, сдвигаем её ВЛЕВО/ВВЕРХ; вправо и вниз сами
            -- не двигаем — положение, выбранное игроком, не сбивается.
            if KL.x + W > resX - 4 then KL.x = resX - 4 - W end
            if KL.y + H > resY - 4 then KL.y = resY - 4 - H end
            if KL.x < 0 then KL.x = 0 end
            if KL.y < 0 then KL.y = 0 end

            -- -------- перемещение мышью --------
            if KL.moving then
                if not KL.armed and os.clock() > (KL.armAt or 0)
                   and not (GRND_MOUSE and GRND_MOUSE.down) then
                    KL.armed = true
                end
                local mx, my = klMousePos()
                if mx then
                    KL.x = math.floor(mx - (KL.grabX or W / 2))
                    KL.y = math.floor(my - (KL.grabY or H / 2))
                end
                KL.x = math.max(0, math.min(math.max(0, resX - 40), KL.x))
                KL.y = math.max(0, math.min(math.max(0, resY - 20), KL.y))
                if KL.cancel then
                    KL.cancel = false
                    klSetMoving(false, true)
                elseif KL.armed and klLmbTapped() then
                    klSetMoving(false, false)      -- ЛКМ закрепляет
                end
            end
            KL.w, KL.h = W, H

            -- -------- наведение и клик по строке (слежка) --------
            -- Интерактив разрешаем только когда курсор игры реально показан
            -- (GRND_KEYS.cursorOn выставляет кадр ImGui: табло TAB, меню,
            -- плоский курсор F1, прицел ClickWarp, перемещение). Иначе клик по
            -- строке мог бы сработать от выстрела — этого быть не должно.
            -- Сторона: слева от значка — УБИЙЦА, справа — ЖЕРТВА; подчёркивается
            -- ровно один ник — тот, на который наведён курсор.
            local hoverRow, hoverSide = nil, nil
            local cursorOn = (type(GRND_KEYS) == "table") and (GRND_KEYS.cursorOn == true)
            local doInteract = cursorOn and (not KL.moving) and n > 0
                and not (menu and menu.open)
            local mx, my
            if doInteract then
                mx, my = klMousePos()
                if mx and tonumber(my) and KL.x and KL.y
                   and mx >= KL.x and mx <= KL.x + W
                   and my >= KL.y and my <= KL.y + H then
                    local idx = math.floor((my - KL.y - padY) / rowH) + 1
                    if idx >= 1 and idx <= n then
                        hoverRow = idx
                        hoverSide = ((mx - KL.x) > (iconX + iconW * 0.5)) and "v" or "k"
                    end
                end
            end
            if hoverRow and type(GRND_MOUSE) == "table" and GRND_MOUSE.clicked
               and (type(grndClickAlive) ~= "function" or grndClickAlive()) then
                local r = list[hoverRow]
                if r then
                    GRND_MOUSE.clicked = false          -- клик наш, другим окнам не отдаём
                    local onVictim = (hoverSide == "v")
                    local nick = onVictim and (r.vu or r.v) or (r.ku or r.k)
                    local pid  = onVictim and r.vid or r.kid
                    pcall(klSpecGo, nick, pid)
                end
            end

            -- -------- рисуем --------
            -- v1.8.1: в DX-режиме ПОДЛОЖКУ тоже рисует render-библиотека:
            -- ImGui-слой ложится поверх DX-текста, и фон, нарисованный
            -- ImGui, закрыл бы надписи. Скругления в DX-режиме нет — фон
            -- по умолчанию выключен, включённый становится прямым.
            if dxf and KL.bg then
                pcall(renderDrawBox, KL.x, KL.y, W, H,
                    klDxCol(9, 11, 15, (KL.bgAlpha or 120) * a))
            end
            im.SetNextWindowPos(im.ImVec2(KL.x, KL.y), COND_ALWAYS)
            im.SetNextWindowSize(im.ImVec2(W, H), COND_ALWAYS)
            local nStyle = 0
            if grndPushStyleF(im.StyleVar and im.StyleVar.Alpha, a) then nStyle = nStyle + 1 end
            if grndPushStyleV2(im.StyleVar and im.StyleVar.WindowPadding, 0, 0) then nStyle = nStyle + 1 end
            if grndBeginTransparent("##grnd_killlist", KL_WIN_FLAGS) then
                local dl = im.GetWindowDrawList()
                local pos = im.GetWindowPos()
                local function at(dx, dy) return im.ImVec2(pos.x + dx, pos.y + dy) end
                local function col(r, g, b, al)
                    return col32(r, g, b, math.max(0, math.min(255, math.floor(al))))
                end
                local holeCol = col(0, 0, 0, 160 * a)
                -- v1.8.1: единый вывод надписи. DX-режим — renderFontDrawText
                -- (GDI), тень — чёрная копия со сдвигом +1/+1; иначе прежний
                -- uiText с той же тенью. shMul — доля силы тени (у подписи
                -- оружия она была слабее).
                local function outText(x, y, txt, r, g, b, al, shMul)
                    shMul = (shMul == nil) and 1 or shMul
                    x, y = math.floor(x), math.floor(y)
                    txt = dxStr(txt)
                    local sal = (shA > 0) and math.floor(shA * shMul) or 0
                    if dxf then
                        local ax, ay = KL.x + x, KL.y + y
                        if sal > 0 then
                            pcall(renderFontDrawText, dxf, txt, ax + 1, ay + 1,
                                klDxCol(0, 0, 0, sal * a))
                        end
                        pcall(renderFontDrawText, dxf, txt, ax, ay,
                            klDxCol(r, g, b, al * a))
                    else
                        if sal > 0 then
                            uiText(x + 1, y + 1, txt, col(0, 0, 0, sal * a), fsc)
                        end
                        uiText(x, y, txt, col(r, g, b, al * a), fsc)
                    end
                end
                -- подложка панели (необязательна — по умолчанию как в игре,
                -- без неё; в DX-режиме рисуется render-библиотекой выше)
                if KL.bg and not dxf then
                    roundRect(dl, at(0, 0), at(W, H), col(9, 11, 15, (KL.bgAlpha or 120) * a), 6 * us)
                end
                if n == 0 then
                    outText(padX, padY + 2, "пока нет убийств", 150, 155, 165, 200)
                end
                for i = 1, n do
                    local r = list[i]
                    local y  = padY + (i - 1) * rowH
                    -- текст центрируем по строке и прижимаем к целым пикселям
                    -- текст чуть выше центра: снизу место под черту подчёркивания
                    local ty = y + math.max(0, math.floor((rowH - fpx - 6) / 2))
                    local kr, kg, kb = klArgbCol(r.kc)
                    local vr, vg, vb = klArgbCol(r.vc)
                    -- УБИЙЦА: x ОДИН И ТОТ ЖЕ у всех строк — левый край
                    -- колонки (v1.6.1: колонка не может «поехать» ни от
                    -- длины ника, ни от настроек)
                    local kw = math.ceil(wK[i] or 0)
                    -- v1.6.5: по умолчанию (тумблер «Ники к значку» включён) ник
                    -- стоит ВПЛОТНУЮ к колонке значков: пустого места между ником
                    -- и значком нет ни в одной строке, все строки заканчиваются
                    -- на одной линии у значка. Правый край считаем от ТОЧНОЙ
                    -- ширины текста (а не от округлённой вверх) и округляем уже
                    -- координату — тогда правые края совпадают, строки не
                    -- «дрожат» (в v1.6.0 x был дробным, и выравнивание выглядело
                    -- неровным). Тумблер выключен — ровный левый столбец (v1.6.1).
                    local kx = padX
                    if KL.alignK then
                        kx = math.floor(iconX - gapK - (wK[i] or 0) + 0.5)
                        if kx < padX then kx = padX end
                    end
                    outText(kx, ty, kStr[i], kr, kg, kb, 255)
                    -- ЧЕМ УБИТ — оригинальный значок оружия в своей колонке
                    local gy = y + math.floor((rowH - iconH) / 2)
                    local hasIcon = klWeaponGlyph(dl, at, iconX, gy, iconW, r, a, us,
                        col, holeCol)
                    if KL.showWName and hasIcon then
                        local nm = klWeaponLabel(r)
                        if nm ~= "" then
                            outText(iconX + iconW + gapV, ty, nm, 206, 213, 226, 235, 0.85)
                        end
                    end
                    -- жертва: от колонки значков вправо
                    outText(vx0, ty, vStr[i], vr, vg, vb, 255)
                    if KL.showTime and r.time then
                        outText(vx0 + math.ceil(wV[i] or 0) + math.floor(8 * us), ty,
                            tostring(r.time), 150, 155, 165, 210)
                    end
                    -- ПОДЧЁРКИВАНИЕ — черта ПОД ником, не через буквы
                    if hoverRow == i then
                        local ux, uw
                        if hoverSide == "v" then
                            ux, uw = vx0, math.ceil(wV[i] or 0)
                        else
                            ux, uw = kx, kw
                        end
                        -- тонкая черта в зазоре под строкой, не пересекает глифы
                        local uy = math.floor(y + rowH - 2)
                        if uy < ty + fpx + 3 then uy = math.floor(ty + fpx + 3) end
                        pcall(dl.AddLine, dl, at(ux, uy), at(ux + uw, uy),
                            col(255, 255, 255, 210 * a), 1.0)
                    end
                end
                -- подсказка в режиме перемещения
                if KL.moving then
                    if dl.AddRect then
                        pcall(dl.AddRect, dl, at(0, 0), at(W, H), c32(TH.accent), 6 * us, 0, 1.5)
                    end
                    local hw = dxW(hint)
                    local hx = math.floor((W - hw) / 2)     -- целые координаты:
                    if hx < 4 then hx = 4 end               -- текст не «мылится»
                    outText(hx, math.floor(H - hintH + 4 * us), hint,
                        TH.accent[1], TH.accent[2], TH.accent[3], 255)
                end
            end
            if endDepth > 0 then endDepth = endDepth - 1; pcall(im.End) end
            grndPopStyle(nStyle)
            if fontPushed then
                -- v1.6.3: fontViaIm -> fontViaLadder (что именно нажали, то и снимаем)
                if fontViaLadder then pcall(im.PopFont) else pcall(uiPopFont, true) end
            end
            return KL.moving
        end
        local function aoSetMoving(on, cancelMove)
            local AO = GRND_AO
            if not AO then return end
            if on then
                if AO.moving then return end
                AO.moving = true
                AO.armed = false
                AO.armAt = os.clock() + 0.35
                AO.cancel = false
                AO.moveOldX, AO.moveOldY = AO.x, AO.y
                local mx, my = klMousePos()
                if mx and AO.x and AO.y and AO.w and AO.h
                   and mx >= AO.x and mx <= AO.x + AO.w
                   and my >= AO.y and my <= AO.y + AO.h then
                    AO.grabX, AO.grabY = mx - AO.x, my - AO.y
                else
                    AO.grabX = (AO.w or 160) / 2
                    AO.grabY = (AO.h or 60) / 2
                end
                if not AO.enabled then
                    AO.enabled = true
                    AO.cfgDirty = true
                end
                local mn = _G.GRND_MENU
                if mn then mn.open = false end
                pcall(clwShowCursor, true)
                if type(grndUiControls) == "function" then pcall(grndUiControls, true) end
                if notify and type(notify.add) == "function" then
                    pcall(notify.add, "Админы в сети: двигайте мышью, ЛКМ — закрепить, ESC — отмена", "info", 4)
                end
            else
                if not AO.moving then return end
                AO.moving = false
                AO.armed = false
                if cancelMove and AO.moveOldX ~= nil then
                    AO.x, AO.y = AO.moveOldX, AO.moveOldY
                end
                pcall(clwShowCursor, false)
                if type(grndUiControls) == "function" then
                    local mn2=_G.GRND_MENU
                    pcall(grndUiControls,(mn2 and mn2.open) or GRND_TAB.open
                        or (_G.GRND_REP and _G.GRND_REP.open)
                        or (_G.GRND_RC and _G.GRND_RC.show)
                        or (_G.GRND_KL and _G.GRND_KL.moving)
                        or (_G.GRND_AO and _G.GRND_AO.moving))
                end
                AO.cfgDirty = true
                pcall(grndAoCfgSave)
                if notify and type(notify.add) == "function" then
                    pcall(notify.add, cancelMove and "Админы в сети: перемещение отменено"
                        or "Админы в сети: позиция закреплена",
                        cancelMove and "warn" or "ok", 3)
                end
            end
        end

        local function drawAdminsOnline(dt)
            local AO = GRND_AO
            if not AO then return false end
            dt = dt or 0.016
            if AO.wantMove then
                AO.wantMove = false
                pcall(aoSetMoving, true)
            end
            local target = AO.enabled and 1 or 0
            AO.anim = AO.anim or 0
            if AO.anim < target then AO.anim = math.min(target, AO.anim + dt * 8.0)
            elseif AO.anim > target then AO.anim = math.max(target, AO.anim - dt * 8.0) end
            if AO.anim <= 0 and not AO.moving then return false end
            local a = 1 - (1 - AO.anim) * (1 - AO.anim)
            if AO.moving then
                a = 1
                pcall(clwShowCursor, true)
            end

            local resX, resY = getScreenResolution()
            local sc = math.max(0.35, math.min(2.5, tonumber(AO.scale) or 1.0))
            local baseSize = tonumber(GRND_FONT and GRND_FONT.fontBase) or 16
            local wantPx = math.floor(baseSize * sc + 0.5)
            if wantPx < 7 then wantPx = 7 elseif wantPx > 40 then wantPx = 40 end
            local fobj, fsz
            if type(grndUiFontPick) == "function" then
                local okf, rf, rs = pcall(grndUiFontPick, wantPx)
                if okf then fobj, fsz = rf, tonumber(rs) end
            end
            local fontPushed, fontViaLadder, fsc = false, false, 1
            if fobj and type(im.PushFont) == "function" then
                fontViaLadder = pcall(im.PushFont, fobj) and true or false
            end
            if fontViaLadder then
                fontPushed = true
            else
                fontPushed = uiPushFont()
                fsc = wantPx / baseSize
            end
            if math.abs(fsc - 1) < 0.01 then fsc = 1 end
            local fpx = wantPx
            if fontViaLadder then
                fpx = tonumber(fsz) or wantPx
                if fpx < 9 then fpx = wantPx end
            end
            local dxf, dxBorder = aoDxFont(fpx)
            local function dxStr(s)
                s = tostring(s or "")
                if dxf and type(grndToAnsi) == "function" then
                    local ok, r = pcall(grndToAnsi, s)
                    if ok and type(r) == "string" then return r end
                end
                return s
            end
            local function dxW(s)
                local raw = tostring(s or "")
                if dxf then
                    local okw, w = pcall(renderGetFontDrawTextLength, dxf, dxStr(raw))
                    if okw and type(w) == "number" and w > 0 then return w end
                end
                return grndTextW(raw) * fsc
            end

            local function rgbOf(id)
                if type(id) ~= "number" or id < 0 or id == 65535 then return nil end
                if type(sampGetPlayerColor) ~= "function" then return nil end
                local ok, c = pcall(sampGetPlayerColor, id)
                if not ok or type(c) ~= "number" then return nil end
                if c < 0 then c = c + 0x100000000 end
                local r = math.floor(c / 0x10000) % 256
                local g = math.floor(c / 0x100) % 256
                local b = c % 256
                if r + g + b == 0 then return nil end
                return r, g, b
            end
            local function pausedOf(id)
                if type(id) ~= "number" or type(sampIsPlayerPaused) ~= "function" then
                    return false
                end
                local ok, p = pcall(sampIsPlayerPaused, id)
                return ok and p and true or false
            end

            local list = AO.list or {}
            local rows = {}
            local afkN = 0
            for i = 1, #list do
                local e = list[i]
                local id = e.id
                if (not id) and e.nick and type(sampGetPlayerIdByNickname) == "function" then
                    local ok, nid = pcall(sampGetPlayerIdByNickname, e.nick)
                    if ok and type(nid) == "number" and nid >= 0 and nid ~= 65535 then
                        id = nid
                        e.id = nid
                    end
                end
                local afk = e.afk or pausedOf(id)
                if afk then afkN = afkN + 1 end
                local r, g, b = rgbOf(id)
                rows[#rows + 1] = {
                    nick = e.nick or "?",
                    id = id,
                    lvl = e.lvl,
                    afk = afk,
                    afkSec = e.afkSec,
                    r = r, g = g, b = b,
                }
            end
            -- живой таймер AFK: запоминаем момент входа, не сбрасываем на /admins
            AO.afkSince = AO.afkSince or {}
            local nowClk = os.clock()
            local seenAfk = {}
            local function aoFmtAfk(sec)
                sec = math.max(0, math.floor(tonumber(sec) or 0))
                local h = math.floor(sec / 3600)
                local m = math.floor((sec % 3600) / 60)
                local s = sec % 60
                if h > 0 then
                    return string.format("[%d:%02d:%02d]", h, m, s)
                end
                return string.format("[%02d:%02d]", m, s)
            end
            for i = 1, #rows do
                local e = rows[i]
                local key = e.nick
                seenAfk[key] = true
                if e.afk then
                    if not AO.afkSince[key] then
                        AO.afkSince[key] = nowClk - (tonumber(e.afkSec) or 0)
                    end
                    e.afkStr = " AFK " .. aoFmtAfk(nowClk - AO.afkSince[key])
                else
                    AO.afkSince[key] = nil
                    e.afkStr = nil
                end
            end
            for k, _ in pairs(AO.afkSince) do
                if not seenAfk[k] then AO.afkSince[k] = nil end
            end

            local left = 0
            if AO.enabled then
                left = math.max(0, math.ceil((AO.nextAt or 0) - os.clock()))
            end
            local playMin = math.floor((tonumber(AO.playSec) or 0) / 60)
            -- шапка: подпись / значение — две колонки, числа стоят столбиком
            local head = {
                { l = "Обновление",          v = tostring(left) .. " сек.",     r = 230, g = 232, b = 236 },
                { l = "Админов онлайн",      v = tostring(#rows),               r = 70,  g = 230, b = 90  },
                { l = "Админов AFK",         v = tostring(afkN),                r = 255, g = 70,  b = 70  },
                { l = "Ваш онлайн сегодня",  v = tostring(playMin) .. " мин.",  r = 80,  g = 220, b = 255 },
            }

            local us = fpx / 16
            local padX = math.max(4, math.floor(10 * us))
            local padY = math.max(3, math.floor(6 * us))
            -- высота строки: реальный кегль DX + крошечный зазор (иначе с обводкой
            -- глифы наезжают друг на друга)
            local rowH = math.max(18, math.floor(fpx + 5.5))
            if dxf and type(renderGetFontDrawHeight) == "function" then
                local okH, fh = pcall(renderGetFontDrawHeight, dxf)
                if okH and type(fh) == "number" and fh > 8 then
                    rowH = math.floor(fh + 3)
                end
            end
            local gapH = math.max(6, math.floor(8 * us))       -- воздух между шапкой и списком
            local colGap = math.max(10, math.floor(14 * us))   -- зазор подпись/цифра в шапке
            -- обводка GDI уже даёт контур: ручная тень только если её нет
            local shA = 0
            if dxf and not dxBorder then shA = 55
            elseif not dxf then shA = 70 end
            local hint = "ЛКМ — закрепить   ·   ESC — отмена"
            local hintH = AO.moving and (rowH + 6) or 0

            local labW, valW = 0, 0
            for i = 1, #head do
                local lw, vw = dxW(head[i].l), dxW(head[i].v)
                if lw > labW then labW = lw end
                if vw > valW then valW = vw end
            end
            local headW = labW + colGap + valW

            -- список: ник[ID] одним куском, уровень сразу за ним (не колонкой).
            local listW = 0
            for i = 1, #rows do
                local e = rows[i]
                local idPart = e.id and ("[" .. tostring(e.id) .. "]") or ""
                e.idPart = idPart
                e.nw = dxW(e.nick)
                e.idw = idPart ~= "" and dxW(idPart) or 0
                e.lvlStr = e.lvl and ("  " .. tostring(e.lvl) .. " Уровень") or ""
                e.lw = e.lvlStr ~= "" and dxW(e.lvlStr) or 0
                e.aw = (e.afkStr and dxW(e.afkStr)) or 0
                local w = e.nw + e.idw + e.lw + e.aw
                e.rowW = w
                if w > listW then listW = w end
            end
            if #rows == 0 then
                listW = math.max(listW, dxW("ожидание ответа /admins…"))
            end
            local maxW = math.max(headW, listW)
            if AO.moving then
                local hw = dxW(hint)
                if hw > maxW then maxW = hw end
            end

            local W = math.floor(maxW + padX * 2)
            if W < 180 then W = 180 end
            local sepH = math.max(1, math.floor(1 * us + 0.5))
            local H = math.floor(padY * 2 + #head * rowH + gapH + sepH + gapH
                + math.max(1, #rows) * rowH + hintH)
            if H < rowH * 3 then H = rowH * 3 end

            if AO.x == nil then AO.x = 18 end
            if AO.y == nil then AO.y = math.floor(resY * 0.10) end
            if AO.x + W > resX - 4 then AO.x = resX - 4 - W end
            if AO.y + H > resY - 4 then AO.y = resY - 4 - H end
            if AO.x < 0 then AO.x = 0 end
            if AO.y < 0 then AO.y = 0 end

            if AO.moving then
                if not AO.armed and os.clock() > (AO.armAt or 0)
                   and not (GRND_MOUSE and GRND_MOUSE.down) then
                    AO.armed = true
                end
                local mx, my = klMousePos()
                if mx then
                    AO.x = math.floor(mx - (AO.grabX or W / 2))
                    AO.y = math.floor(my - (AO.grabY or H / 2))
                end
                AO.x = math.max(0, math.min(math.max(0, resX - 40), AO.x))
                AO.y = math.max(0, math.min(math.max(0, resY - 20), AO.y))
                if AO.cancel then
                    AO.cancel = false
                    aoSetMoving(false, true)
                elseif AO.armed and klLmbTapped() then
                    aoSetMoving(false, false)
                end
            end
            AO.w, AO.h = W, H

            local listY0 = padY + #head * rowH + math.floor(gapH * 0.45) + sepH + gapH
            local hoverI = nil
            local cursorOn = (type(GRND_KEYS) == "table") and (GRND_KEYS.cursorOn == true)
            local doInteract = cursorOn and (not AO.moving) and #rows > 0
                and not (menu and menu.open)
            if doInteract then
                local mx, my
                if im.GetIO then
                    local ok, io2 = pcall(im.GetIO)
                    if ok and io2 and io2.MousePos then
                        mx = tonumber(io2.MousePos.x)
                        my = tonumber(io2.MousePos.y)
                        if not mx then
                            pcall(function()
                                mx = io2.MousePos.x + 0
                                my = io2.MousePos.y + 0
                            end)
                        end
                    end
                end
                if not mx then mx, my = klMousePos() end
                if mx and tonumber(my) and AO.x and AO.y
                   and mx >= AO.x and mx <= AO.x + W
                   and my >= AO.y + listY0 and my <= AO.y + H then
                    local idx = math.floor((my - (AO.y + listY0)) / rowH) + 1
                    if idx >= 1 and idx <= #rows then hoverI = idx end
                end
            end
            if hoverI and type(GRND_MOUSE) == "table" and GRND_MOUSE.clicked
               and (type(grndClickAlive) ~= "function" or grndClickAlive()) then
                local e = rows[hoverI]
                if e then
                    GRND_MOUSE.clicked = false
                    if type(klSpecGo) == "function" then
                        pcall(klSpecGo, e.nick, e.id)
                    end
                end
            end

            local function outText(x, y, txt, r, g, b, al)
                x, y = math.floor(x + 0.5), math.floor(y + 0.5)
                txt = dxStr(txt)
                al = al or 255
                local sal = shA
                if dxf then
                    local ax, ay = AO.x + x, AO.y + y
                    if sal > 0 then
                        pcall(renderFontDrawText, dxf, txt, ax + 1, ay + 1,
                            klDxCol(0, 0, 0, sal * a))
                    end
                    pcall(renderFontDrawText, dxf, txt, ax, ay,
                        klDxCol(r, g, b, al * a))
                else
                    if sal > 0 then
                        uiText(x + 1, y + 1, txt, col32(0, 0, 0, math.floor(sal * a)), fsc)
                    end
                    uiText(x, y, txt, col32(r, g, b, math.floor(al * a)), fsc)
                end
            end
            local function fillRect(x, y, w, h, r, g, b, al)
                x, y, w, h = math.floor(x), math.floor(y), math.floor(w), math.floor(h)
                if w < 1 or h < 1 then return end
                if type(renderDrawBox) == "function" then
                    pcall(renderDrawBox, AO.x + x, AO.y + y, w, h,
                        klDxCol(r, g, b, al * a))
                elseif not dxf then
                    local dl = im.GetWindowDrawList()
                    local pos = im.GetWindowPos()
                    dl:AddRectFilled(
                        im.ImVec2(pos.x + x, pos.y + y),
                        im.ImVec2(pos.x + x + w, pos.y + y + h),
                        col32(r, g, b, math.floor(al * a)))
                end
            end

            local nStyle = 0
            im.SetNextWindowPos(im.ImVec2(AO.x, AO.y), COND_ALWAYS)
            im.SetNextWindowSize(im.ImVec2(W, H), COND_ALWAYS)
            if grndPushStyleF(im.StyleVar and im.StyleVar.Alpha, a) then nStyle = nStyle + 1 end
            if grndPushStyleV2(im.StyleVar and im.StyleVar.WindowPadding, 0, 0) then nStyle = nStyle + 1 end
            local opened = grndBeginTransparent("##grnd_admins", KL_WIN_FLAGS)
            local dlA, atA
            if opened then
                dlA = im.GetWindowDrawList()
                local posA = im.GetWindowPos()
                atA = function(dx, dy)
                    return im.ImVec2(posA.x + dx, posA.y + dy)
                end
                -- v1.16: подложка ВЫКЛЮЧЕНА по умолчанию (тумблер «Фон» в
                -- настройках чекера). Список читается прямо на картинке, как
                -- родной оверлей игры. Если фон включён, в режиме
                -- перемещения он плотнее — панель видно на любом фоне.
                if AO.bg then
                    local bgA = AO.moving and 130 or (tonumber(AO.bgAlpha) or 88)
                    fillRect(0, 0, W, H, 8, 10, 14, bgA)
                end
                local y = padY
                local valX = padX + labW + colGap
                for i = 1, #head do
                    local h = head[i]
                    outText(padX, y, h.l, 200, 204, 212, 255)
                    outText(valX, y, h.v, h.r, h.g, h.b, 255)
                    y = y + rowH
                end
                y = y + math.floor(gapH * 0.45)
                fillRect(padX, y, W - padX * 2, sepH, 255, 255, 255, 38)
                y = y + sepH + gapH

                if #rows == 0 then
                    outText(padX, y, "ожидание ответа /admins…", 140, 145, 155, 220)
                else
                    for i = 1, #rows do
                        local e = rows[i]
                        local nr, ng, nb = e.r, e.g, e.b
                        local lv = tonumber(e.lvl)
                        if lv and lv >= 1 and lv <= 8 and AO.lvlCol and AO.lvlCol[lv] then
                            local cc = AO.lvlCol[lv]
                            nr, ng, nb = tonumber(cc[1]), tonumber(cc[2]), tonumber(cc[3])
                        end
                        if not nr then nr, ng, nb = 235, 240, 245 end
                        local x = padX
                        outText(x, y, e.nick, nr, ng, nb, 255)
                        x = x + e.nw
                        if e.idPart and e.idPart ~= "" then
                            outText(x, y, e.idPart, nr, ng, nb, 255)
                            x = x + e.idw
                        end
                        if e.lvlStr and e.lvlStr ~= "" then
                            outText(x, y, e.lvlStr, 168, 174, 184, 255)
                            x = x + e.lw
                        end
                        if e.afkStr then
                            outText(x, y, e.afkStr, 255, 70, 70, 255)
                        end
                        if hoverI == i then
                            local uw = (e.nw or 0) + (e.idw or 0)
                            if uw < 8 then uw = 8 end
                            local uy = math.floor(y + rowH - 2)
                            if uy < y + fpx + 3 then uy = math.floor(y + fpx + 3) end
                            if dlA and dlA.AddLine and atA then
                                pcall(dlA.AddLine, dlA, atA(padX, uy), atA(padX + uw, uy),
                                    col32(255, 255, 255, 220), 1.0)
                            end
                        end
                        y = y + rowH
                    end
                end
                if AO.moving then
                    outText(padX, y + 4, hint, 200, 205, 215, 230)
                end
                pcall(im.End)
            else
                pcall(im.End)
            end
            if nStyle > 0 and type(im.PopStyleVar) == "function" then
                pcall(im.PopStyleVar, nStyle)
            end
            if fontPushed then
                if fontViaLadder then pcall(im.PopFont) else pcall(uiPopFont, true) end
            end
            return AO.moving
        end

        -- =============================================================
        --  МОДУЛЬ 3a: drawMenu (M) — v1.8.0 «современное тёмное стекло»:
        --  окно 900x620+, сайдбар 232 px с бликом и виньеткой, line-иконки
        --  разделов, градиентный логотип со свечением, чип версии,
        --  «бегунок» активного пункта, карточка контента с бликом,
        --  круглый крестик закрытия, плавное появление.
        --  Посаджен на текущие хелперы файла (grndBegin/grndPush*/uiText).
        -- =============================================================
        local function drawMenu(dt)
            dt = dt or 0.016
            if not menu.open and GRND_UIKIT.styleDirty then
                local ok,result=pcall(grndCamCfgSave)
                GRND_UIKIT.styleSaveError=not (ok and result ~= false)
                GRND_UIKIT.styleDirty=false
            end
            -- плавное появление / исчезание (~0.15 c)
            local speed = 7.0
            if menu.open then
                menu.anim = math.min(1, (menu.anim or 0) + dt * speed)
            else
                menu.anim = math.max(0, (menu.anim or 0) - dt * speed)
            end
            if menu.anim <= 0 then return false end   -- меню полностью скрыто

            local a = 1 - (1 - menu.anim) * (1 - menu.anim)   -- easeOutQuad
            local resX, resY = getScreenResolution()

            -- геометрия: кнопка 200x40, зазор 8, отступы 16 (v1.8.0 — воздух)
            local BW, BH, BGAP, BPAD = 208, 38, 4, 8
            -- высота окна подгоняется под число вкладок (все должны влезать)
            local tabsContent = #MENU_TABS * BH + (#MENU_TABS - 1) * BGAP
            local W = math.min(980, math.max(520, resX - 40))
            local H = math.min(math.max(360, resY - 40),
                               math.max(720, tabsContent + 254))
            local SB = math.min(224, math.floor(W * 0.42))   -- ширина левой панели
            BW=SB-BPAD*2

            -- безопасный замер текста (без отрисовки).
            -- ВАЖНО: в mimgui CalcTextSize возвращает cdata (ImVec2),
            -- в moonimgui — таблицу; раньше cdata не распознавался и ширина
            -- считалась по БАЙТАМ строки -> бейдж/подписи уезжали в сторону.
            local function tsize(s)
                local ok, r = pcall(im.CalcTextSize, s)
                if ok then
                    local t = type(r)
                    if t == "table" or t == "cdata" then
                        local xx, yy = tonumber(r and r.x), tonumber(r and r.y)
                        if xx then return xx, yy or 14 end
                    elseif t == "number" then
                        return r, 14
                    end
                end
                local n = ((type(grndUtf8Len) == "function")
                    and grndUtf8Len(tostring(s)))
                    or (utf8 and utf8.len and utf8.len(tostring(s)))
                    or #tostring(s)
                return n * 7, 14
            end

            -- при первом открытии — по центру экрана, дальше позицию не трогаем
            -- (окно можно перетаскивать мышью)
            if not menu.posInit then
                local saved=GRND_CONFIG.ensure().layout.menu or {}
                local mx=tonumber(saved.x) or math.floor((resX-W)/2)
                local my=tonumber(saved.y) or math.floor((resY-H)/2)
                mx=math.max(0,math.min(math.max(0,resX-W),mx))
                my=math.max(0,math.min(math.max(0,resY-H),my))
                im.SetNextWindowPos(im.ImVec2(mx,my),COND_ALWAYS)
                menu.posInit = true
            end
            im.SetNextWindowSize(im.ImVec2(W, H), COND_ALWAYS)

            grndPushStyleF(im.StyleVar and im.StyleVar.Alpha, a)
            grndPushStyleF(im.StyleVar and im.StyleVar.WindowRounding, 8)
            grndPushStyleV2(im.StyleVar and im.StyleVar.WindowPadding, 0, 0)
            grndPushCol(im.Col and im.Col.WindowBg, c4(TH.bg))
            grndPushCol(im.Col and im.Col.Border,   c4(TH.line))

            local violetColors, violetVars = 0, 0
            for _, entry in ipairs({
                {"Text", TH.text}, {"TextDisabled", TH.textMuted},
                {"FrameBg", {255,255,255,9}}, {"FrameBgHovered", {255,255,255,17}},
                {"FrameBgActive", {255,255,255,23}},
                {"Button", TH.itemHover}, {"ButtonHovered", TH.itemSel},
                {"ButtonActive", TH.itemPress}, {"CheckMark", TH.accent},
                {"SliderGrab", TH.accent}, {"SliderGrabActive", TH.textHi},
                {"Header", TH.itemSel}, {"HeaderHovered", TH.itemHover},
                {"HeaderActive", TH.itemPress}, {"Separator", TH.line},
                {"ScrollbarBg", {0,0,0,0}}, {"ScrollbarGrab", {255,255,255,30}},
                {"ScrollbarGrabHovered", {255,255,255,50}},
                {"ScrollbarGrabActive", TH.accent},
                {"TextSelectedBg", {TH.accent[1],TH.accent[2],TH.accent[3],65}},
            }) do
                if grndPushCol(im.Col and im.Col[entry[1]], c4(entry[2])) then
                    violetColors = violetColors + 1
                end
            end
            for _, entry in ipairs({{"FrameRounding",5},{"GrabRounding",3},
                {"ScrollbarRounding",4},{"ScrollbarSize",5}}) do
                if grndPushStyleF(im.StyleVar and im.StyleVar[entry[1]],entry[2]) then
                    violetVars = violetVars + 1
                end
            end
            local wantCursor = false

            -- =====================================================
            --  v1.12: окно «Наказание: ID» — редактирование причин и
            --  времён. Рисуется ПОВЕРХ меню (своим окном, после End меню),
            --  живёт пока открыто меню; ESC закрывает его (grndEscAction).
            -- =====================================================
            local function drawPunishEditor(dt)
                local PUN = GRND_PUN
                if not PUN or not PUN.editId then return false end
                if not PUN.loaded then pcall(PUN.load) end
                local it = PUN.entry(PUN.editId)
                if not it or it.locked then
                    PUN.editId, PUN.addCol = nil, nil
                    return false
                end
                local d = PUN.data[it.id] or { reasons = {}, times = {} }
                PUN.data[it.id] = d
                d.reasons = type(d.reasons) == "table" and d.reasons or {}
                d.times = type(d.times) == "table" and d.times or {}

                local resX, resY = getScreenResolution()
                local W = 470
                local PADX, PADY = 16, 14
                local HEAD = 42
                local colGap = 12
                local colW = math.floor((W - PADX * 2 - colGap) / 2)
                local rowH, rowGap = 26, 6
                local addBtnH = 30
                local addModeH = 30 + 6 + 26        -- поле + кнопки «Добавить/Отмена»
                local rowsTop = HEAD + 10 + 22

                local function colBottom(kind)
                    local items = (kind == "r") and d.reasons or d.times
                    local extra = (PUN.addCol == kind) and addModeH or addBtnH
                    return rowsTop + #items * (rowH + rowGap) + 4 + extra
                end
                local leftBottom = colBottom("r")
                local rightBottom = it.time and colBottom("t") or (rowsTop + 60)
                local H = math.max(leftBottom, rightBottom) + PADY
                H = math.max(240, math.min(H, math.max(240, resY - 60)))

                -- точный замер текста с учётом масштаба (как в карточке рекона)
                local function drawnW(s, scale)
                    scale = scale or 1
                    if type(im.SetWindowFontScale) == "function" then
                        if scale ~= 1 then
                            pcall(im.SetWindowFontScale, scale)
                            local okM, aM = pcall(im.CalcTextSize, tostring(s))
                            pcall(im.SetWindowFontScale, 1)
                            if okM then
                                local ta = type(aM)
                                local w = (ta == "table" or ta == "cdata")
                                    and tonumber(aM.x) or tonumber(aM)
                                if w and w > 0 then return w end
                            end
                        end
                        return grndTextW(s) * scale
                    end
                    return grndTextW(s)
                end
                local function fitText(s, maxW, scale)
                    s = tostring(s)
                    if drawnW(s, scale) <= maxW then return s end
                    local out, chars = {}, 0
                    for ch in s:gmatch("[%z\1-\127\194-\244][\128-\191]*") do
                        chars = chars + 1
                        if chars > 2 and drawnW(table.concat(out) .. "…", scale) > maxW then break end
                        out[#out + 1] = ch
                    end
                    return table.concat(out) .. "…"
                end

                local COND_FIRST = iflag({ "Cond", "ImGuiCond" }, "FirstUseEver")
                    or iflag({ "Cond", "ImGuiCond" }, "Once") or COND_ALWAYS
                im.SetNextWindowPos(im.ImVec2(math.floor((resX - W) / 2),
                    math.floor((resY - H) / 2)), COND_FIRST)
                im.SetNextWindowSize(im.ImVec2(W, H), COND_ALWAYS)
                local styleN, colorN = 0, 0
                if grndPushStyleF(im.StyleVar and im.StyleVar.WindowRounding, 12) then styleN = styleN + 1 end
                if grndPushStyleV2(im.StyleVar and im.StyleVar.WindowPadding, 0, 0) then styleN = styleN + 1 end
                if grndPushCol(im.Col and im.Col.WindowBg, rgba(0, 0, 0, 0)) then colorN = colorN + 1 end
                -- Без NoMove/NoFocusOnAppearing/NoBringToFrontOnFocus: окно
                -- поднимается ПОВЕРХ меню и перетаскивается за «фон»
                -- (шапка, поля, межстрочные зазоры) при отжатом MoveFromTitleBarOnly.
                local flags = wf("NoTitleBar", "NoResize", "NoCollapse", "NoScrollbar")
                local pendingClose = false
                if grndBegin("##grnd_pun_editor", flags) then
                    local pos = im.GetWindowPos()
                    local dl2 = im.GetWindowDrawList()
                    local function eat(x, y) return im.ImVec2(pos.x + x, pos.y + y) end
                    local function box(x, y, w, h, col, r)
                        roundRect(dl2, eat(x, y), eat(x + w, y + h), col, r or 6)
                    end
                    local function frame(x, y, w, h, col, r)
                        if dl2.AddRect then
                            pcall(dl2.AddRect, dl2, eat(x, y), eat(x + w, y + h), col, r or 6, 0, 1.0)
                        end
                    end

                    -- фон, градиентная полоса, шапка
                    box(0, 0, W, H, c32(TH.bg), 12)
                    frame(0, 0, W, H, col32(255, 255, 255, 16), 12)
                    -- # v1.19.09: акцентная полоска у верхней кромки убрана (просьба заказчика)
                    local title = "Наказание: " .. it.id
                    uiText((W - drawnW(title, 1.05)) / 2, 13, title, c4(TH.textHi), 1.05)

                    -- крестик закрытия (стиль меню)
                    local cbS, cbX, cbY = 24, W - 34, 9
                    im.SetCursorPos(im.ImVec2(cbX, cbY))
                    if im.InvisibleButton("##grnd_pun_close", im.ImVec2(cbS, cbS)) then
                        pendingClose = true
                    end
                    local chov = (im.IsItemHovered and im.IsItemHovered()) or false
                    if chov then box(cbX, cbY, cbS, cbS, col32(255, 96, 96, 34), 12) end
                    local lc = chov and col32(255, 128, 128, 245) or col32(255, 255, 255, 140)
                    local m = 8
                    dl2:AddLine(eat(cbX + m, cbY + m), eat(cbX + cbS - m, cbY + cbS - m), lc, 1.4)
                    dl2:AddLine(eat(cbX + cbS - m, cbY + m), eat(cbX + m, cbY + cbS - m), lc, 1.4)
                    dl2:AddRectFilled(eat(PADX, HEAD - 1), eat(W - PADX, HEAD), c32(TH.line))

                    -- ---------- колонка (причины / времена) ----------
                    local colY = HEAD + 10
                    local function column(cx, kind)
                        local isR = (kind == "r")
                        local items = isR and d.reasons or d.times
                        local headTxt = isR and "Причины" or ("Время в " .. tostring(it.unit or "мин") .. ".")
                        uiText(cx + (colW - drawnW(headTxt, 0.92)) / 2, colY, headTxt,
                            c4(TH.textHi), 0.92)
                        local iy = colY + 22

                        -- строки списка: корзина + значение
                        for i = 1, #items do
                            local ry = iy + (i - 1) * (rowH + rowGap)
                            im.SetCursorPos(im.ImVec2(cx, ry))
                            if im.InvisibleButton("##pun_del_" .. kind .. "_" .. i,
                                im.ImVec2(24, rowH)) then
                                table.remove(items, i)
                                PUN.cfgDirty = true
                                pcall(PUN.save)
                                return -- перерисуемся следующим кадром
                            end
                            local thov = (im.IsItemHovered and im.IsItemHovered()) or false
                            box(cx, ry, 24, rowH,
                                thov and col32(255, 96, 96, 30) or col32(255, 255, 255, 8), 5)
                            -- иконка корзины
                            local tIc = thov and col32(255, 120, 120, 240)
                                or col32(255, 255, 255, 120)
                            local tx0, ty0 = cx + 7, ry + 6
                            dl2:AddRectFilled(eat(tx0 - 2, ty0), eat(tx0 + 8, ty0 + 2), tIc)
                            dl2:AddRectFilled(eat(tx0 + 1, ty0 - 2), eat(tx0 + 5, ty0), tIc)
                            if dl2.AddRect then
                                pcall(dl2.AddRect, dl2, eat(tx0 - 2, ty0 + 2),
                                    eat(tx0 + 8, ty0 + 13), tIc, 1, 0, 1.2)
                            else
                                dl2:AddRectFilled(eat(tx0 - 2, ty0 + 2), eat(tx0 + 8, ty0 + 13), tIc)
                            end
                            -- бокс значения
                            local vx, vw = cx + 30, colW - 30
                            box(vx, ry, vw, rowH, col32(255, 255, 255, 8), 5)
                            frame(vx + 0.5, ry + 0.5, vw - 1, rowH - 1, col32(255, 255, 255, 14), 5)
                            local s = tostring(items[i])
                            s = fitText(s, vw - 14, 0.88)
                            uiText(vx + 8, ry + (rowH - 14) / 2 + 1, s, c4(TH.text), 0.88)
                        end

                        -- ---------- «Добавить» / поле ввода ----------
                        local addY = iy + #items * (rowH + rowGap) + 4
                        if PUN.addCol == kind then
                            if not PUN.ensureBuf(im) then
                                PUN.addCol = nil
                                -- не молчим: иначе «Добавить» выглядит мёртвой кнопкой
                                pcall(notify.add,
                                    "Ввод текста недоступен в этой сборке ImGui", "warn", 3)
                                return
                            end
                            local inCol, inSty = 0, 0
                            if grndPushCol(im.Col and im.Col.FrameBg, rgba(10, 13, 20, 255)) then inCol = inCol + 1 end
                            if grndPushCol(im.Col and im.Col.FrameBgHovered, rgba(16, 24, 34, 255)) then inCol = inCol + 1 end
                            if grndPushCol(im.Col and im.Col.FrameBgActive, rgba(18, 33, 43, 255)) then inCol = inCol + 1 end
                            if grndPushCol(im.Col and im.Col.Text, rgba(225, 232, 242, 255)) then inCol = inCol + 1 end
                            if grndPushCol(im.Col and im.Col.Border, rgba(255, 255, 255, 18)) then inCol = inCol + 1 end
                            if grndPushStyleV2(im.StyleVar and im.StyleVar.FramePadding, 8, 7) then inSty = inSty + 1 end
                            if grndPushStyleF(im.StyleVar and im.StyleVar.FrameBorderSize, 1) then inSty = inSty + 1 end
                            local fl = 0
                            if im.InputTextFlags and im.InputTextFlags.EnterReturnsTrue then
                                fl = im.InputTextFlags.EnterReturnsTrue
                            elseif rawget(im, "ImGuiInputTextFlags_EnterReturnsTrue") then
                                fl = rawget(im, "ImGuiInputTextFlags_EnterReturnsTrue")
                            end
                            im.SetCursorPos(im.ImVec2(cx, addY))
                            if im.PushItemWidth then pcall(im.PushItemWidth, colW) end
                            local okI, retI
                            if im.InputTextWithHint then
                                okI, retI = pcall(im.InputTextWithHint, "##pun_inp_" .. kind,
                                    isR and "причина…" or "число…", PUN.buf, 64, fl)
                            elseif im.InputText then
                                okI, retI = pcall(im.InputText, "##pun_inp_" .. kind, PUN.buf, 64, fl)
                            end
                            if not PUN.focused and im.SetKeyboardFocusHere then
                                pcall(im.SetKeyboardFocusHere, -1)
                                PUN.focused = true
                            end
                            if im.PopItemWidth then pcall(im.PopItemWidth) end
                            grndPopStyle(inSty)
                            grndPopCol(inCol)
                            frame(cx, addY, colW, 30,
                                col32(TH.accent[1], TH.accent[2], TH.accent[3], 90), 6)

                            -- кнопки «Добавить» / «Отмена»
                            local okClicked, cancelClicked = false, false
                            local bY = addY + 30 + 6
                            local halfW = math.floor((colW - 6) / 2)
                            im.SetCursorPos(im.ImVec2(cx, bY))
                            if im.InvisibleButton("##pun_ok_" .. kind, im.ImVec2(halfW, 26)) then okClicked = true end
                            local okHov = (im.IsItemHovered and im.IsItemHovered()) or false
                            box(cx, bY, halfW, 26,
                                okHov and c32(TH.accent2) or c32(TH.accent), 6)
                            uiText(cx + (halfW - drawnW("Добавить", 0.85)) / 2, bY + 6, "Добавить",
                                c4(TH.bg), 0.85)
                            im.SetCursorPos(im.ImVec2(cx + halfW + 6, bY))
                            if im.InvisibleButton("##pun_cn_" .. kind, im.ImVec2(colW - halfW - 6, 26)) then cancelClicked = true end
                            local cnHov = (im.IsItemHovered and im.IsItemHovered()) or false
                            box(cx + halfW + 6, bY, colW - halfW - 6, 26,
                                cnHov and col32(255, 255, 255, 18) or col32(255, 255, 255, 8), 6)
                            frame(cx + halfW + 6, bY, colW - halfW - 6, 26,
                                cnHov and col32(255, 255, 255, 32) or col32(255, 255, 255, 16), 6)
                            uiText(cx + halfW + 6 + (colW - halfW - 6 - drawnW("Отмена", 0.85)) / 2,
                                bY + 6, "Отмена", cnHov and c4(TH.textHi) or c4(TH.textDim), 0.85)

                            if cancelClicked then
                                PUN.addCol = nil
                                PUN.focused = false
                                pcall(PUN.clearBuf)
                                return
                            end
                            -- Enter (где поддерживается) либо кнопка «Добавить»
                            if (okI and retI == true and fl ~= 0) or okClicked then
                                local txt = PUN.readBuf()
                                pcall(PUN.clearBuf)
                                if txt:gsub("%s+", "") == "" then
                                    -- пустой ввод закрывает режим добавления
                                    PUN.addCol = nil
                                    PUN.focused = false
                                else
                                    PUN.commit(it.id, kind, txt)
                                    PUN.focused = false -- автофокус снова, поле осталось открытым
                                end
                                return
                            end
                        else
                            -- акцентная кнопка «Добавить» (как в эталоне)
                            im.SetCursorPos(im.ImVec2(cx, addY))
                            local aClk = im.InvisibleButton("##pun_addbtn_" .. kind,
                                im.ImVec2(colW, addBtnH))
                            local aHov = (im.IsItemHovered and im.IsItemHovered()) or false
                            local aAct = (im.IsItemActive and im.IsItemActive()) or false
                            gradRect(dl2, eat(cx, addY), eat(cx + colW, addY + addBtnH),
                                (aHov or aAct) and c32(TH.accent2) or c32(TH.accent),
                                c32(TH.accent), 8)
                            uiText(cx + (colW - drawnW("Добавить", 0.92)) / 2,
                                addY + (addBtnH - 14) / 2, "Добавить", c4(TH.bg), 0.92)
                            if aClk then
                                PUN.addCol = kind
                                PUN.focused = false
                                pcall(PUN.clearBuf)
                                return
                            end
                        end
                    end

                    -- левая колонка — причины (всегда)
                    column(PADX, "r")
                    -- правая: времена или «Недоступно»
                    if it.time then
                        column(PADX + colW + colGap, "t")
                    else
                        local cx = PADX + colW + colGap
                        uiText(cx + (colW - drawnW("Время", 0.92)) / 2, colY, "Время",
                            c4(TH.textHi), 0.92)
                        local ny = colY + 22
                        box(cx, ny, colW, 60, col32(255, 255, 255, 5), 8)
                        frame(cx + 0.5, ny + 0.5, colW - 1, 59, col32(255, 255, 255, 12), 8)
                        uiText(cx + (colW - drawnW("Недоступно", 0.92)) / 2, ny + 23,
                            "Недоступно", c4(TH.textMuted), 0.92)
                    end
                end
                if endDepth > 0 then endDepth = endDepth - 1; pcall(im.End) end
                grndPopCol(colorN)
                grndPopStyle(styleN)
                if pendingClose then
                    PUN.editId, PUN.addCol, PUN.focused = nil, nil, false
                    pcall(PUN.clearBuf)
                end
                return true
            end

            -- пока открыт редактор наказания, клик по меню НЕ должен
            -- поднимать его поверх окна редактора (NoBringToFrontOnFocus)
            local menuWinFlags = MENU_WIN_FLAGS
            if GRND_PUN and GRND_PUN.editId then
                menuWinFlags = menuWinFlags + wflag("NoBringToFrontOnFocus")
            end
            if grndBegin("##grnd_menu", menuWinFlags) then
                wantCursor = menu.open
                local pos = im.GetWindowPos()
                GRND_CONFIG.setLayout("menu",{x=math.floor(pos.x),y=math.floor(pos.y),
                    tab=menu.tab,settingsTab=menu.settingsTab,adminPanel=menu.adminPanel or "general"})
                local dl  = im.GetWindowDrawList()
                local function at(dx, dy) return im.ImVec2(pos.x + dx, pos.y + dy) end

                local function menuMousePos()
                    if im.GetIO then
                        local ok, io2 = pcall(im.GetIO)
                        if ok and io2 and io2.MousePos and tonumber(io2.MousePos.x) then
                            return io2.MousePos
                        end
                    end
                    if GRND_MOUSE and GRND_MOUSE.x and GRND_MOUSE.y then
                        return { x = GRND_MOUSE.x, y = GRND_MOUSE.y }
                    end
                    return nil
                end

                local function menuSlider(x, y, w, val, vmin, vmax, step, tag)
                    roundRect(dl, at(x, y + 7), at(x + w, y + 14), col32(255, 255, 255, 30), 3.5)
                    local frac = 0
                    if vmax > vmin then frac = (val - vmin) / (vmax - vmin) end
                    frac = math.min(1, math.max(0, frac))
                    if w * frac >= 3.5 then
                        roundRect(dl, at(x, y + 7), at(x + w * frac, y + 14),
                            col32(TH.accent[1], TH.accent[2], TH.accent[3], 235), 3.5)
                    end
                    im.SetCursorPos(im.ImVec2(x - 5, y))
                    im.InvisibleButton("##ms_" .. (tag or tostring(y)), im.ImVec2(w + 10, 22))
                    local nv = val
                    local active = (im.IsItemActive and im.IsItemActive()) or false
                    if not active and GRND_MOUSE and GRND_MOUSE.down then
                        local mp = menuMousePos()
                        if mp then
                            local wp = im.GetWindowPos()
                            local sx = wp.x + x - 5
                            local sy = wp.y + y
                            if mp.x >= sx and mp.x <= sx + w + 10 and mp.y >= sy and mp.y <= sy + 22 then
                                active = true
                            end
                        end
                    end
                    if active then
                        local mp = menuMousePos()
                        if mp then
                            local wp = im.GetWindowPos()
                            local f = (mp.x - (wp.x + x)) / math.max(1, w)
                            f = math.min(1, math.max(0, f))
                            nv = vmin + f * (vmax - vmin)
                            if step and step > 0 then
                                nv = math.floor((nv - vmin) / step + 0.5) * step + vmin
                            end
                        end
                    end
                    local kx = x + w * frac
                    roundRect(dl,at(kx-5,y+4),at(kx+5,y+17),c32(TH.accent),3)
                    return nv, (nv ~= val)
                end

                local function menuToggle(x, y, on, tag)
                    im.SetCursorPos(im.ImVec2(x, y))
                    local id = "##mt_" .. (tag or tostring(x) .. "_" .. tostring(y))
                    local clicked = im.InvisibleButton(id, im.ImVec2(46, 24))
                    local hovered = (im.IsItemHovered and im.IsItemHovered()) or false
                    grndUiSwitchPaint({dl=dl, at=at, col32=col32, roundRect=roundRect},
                        x,y,on,hovered,id,dt)
                    return clicked
                end

                local function menuBtn(x, y, w, h, text, isSelected, tag)
                    im.SetCursorPos(im.ImVec2(x, y))
                    local clicked = im.InvisibleButton("##mb_" .. (tag or text .. tostring(x)), im.ImVec2(w, h))
                    local hov = (im.IsItemHovered and im.IsItemHovered()) or false
                    local bg = isSelected
                        and col32(TH.accent[1], TH.accent[2], TH.accent[3], 52)
                        or (hov and col32(255, 255, 255, 26) or col32(255, 255, 255, 12))
                    roundRect(dl, at(x, y), at(x + w, y + h), bg, 8)
                    if isSelected and dl.AddRect then
                        pcall(dl.AddRect, dl, at(x + 0.5, y + 0.5),
                            at(x + w - 0.5, y + h - 0.5),
                            col32(TH.accent[1], TH.accent[2], TH.accent[3], 150), 8, 0, 1)
                    end
                    local tw, th = tsize(text)
                    uiText(x + (w - tw) / 2, y + (h - th) / 2, text,
                        isSelected and c4(TH.accent) or (hov and c4(TH.textHi) or c4(TH.textDim)))
                    return clicked
                end

                -- Transparent GRND TOOLS artwork replaces all three text marks.
                roundRect(dl,at(0,0),at(SB,H),c32(TH.sidebar),8,
                    cornerFlags(true,false,true,true))
                if not grndBrandLogoDraw({im=im,dl=dl,at=at,col32=col32,
                    x=16,y=8,w=SB-32,h=84,alpha=a}) then
                    -- A missing asset never hides or breaks navigation.
                    local brand="GRND TOOLS"
                    local brandW=tsize(brand)
                    uiText((SB-brandW)/2,42,brand,c4(TH.textHi))
                end
                -- Native text stays sharp instead of shrinking with the PNG.
                do
                    local caption={"Способный сделать","работу лучше"}
                    for i,line in ipairs(caption) do
                        local width=tsize(line)
                        local scale=math.min(1,(SB-32)/math.max(1,width))
                        local measured=drawnWb(line,scale)
                        uiText(math.max(12,(SB-measured)/2),98+(i-1)*20,
                            line,c4(TH.textHi),scale)
                    end
                end
                dl:AddRectFilled(at(16,142),at(SB-16,143),c32(TH.line))

                -- ---------- КНОПКИ РАЗДЕЛОВ ----------
                local tabsY = 154
                local styleHeight = GRND_UIKIT.pickerOpen and 256 or 88
                local tabsH = H - tabsY - styleHeight - 12
                if tabsH < BH then tabsH = BH end
                -- Fill the available height. On short screens or while editing
                -- RGB, keep a usable minimum row size and allow scrolling.
                BH=math.max(38,(tabsH-math.max(0,#MENU_TABS-1)*BGAP)/math.max(1,#MENU_TABS))

                -- список живёт в дочернем окне (клип + скролл колесом на
                -- маленьких экранах); если обёртка его не умеет — рисуем прямо
                local useChild = type(im.BeginChild) == "function"
                local contX, contY = pos.x + BPAD, pos.y + tabsY
                if useChild then
                    im.SetCursorPos(im.ImVec2(BPAD, tabsY))
                    local cf = (im.WindowFlags and im.WindowFlags.NoScrollbar) or 0
                    local ok, res = pcall(im.BeginChild,
                        "##grnd_tabs", im.ImVec2(BW, tabsH), false, cf)
                    useChild = ok and (res ~= false)
                    if useChild then
                        local cp = im.GetWindowPos()
                        contX, contY = cp.x, cp.y
                    end
                end
                local bdl = useChild and im.GetWindowDrawList() or dl

                -- координаты внутри контейнера (child или основное окно)
                local function cur(x, y)
                    if useChild then im.SetCursorPos(im.ImVec2(x, y))
                    else im.SetCursorPos(im.ImVec2(BPAD + x, tabsY + y)) end
                end
                local function txt(x, y, s, col, sc)
                    if useChild then uiText(x, y, s, col, sc)
                    else uiText(BPAD + x, tabsY + y, s, col, sc) end
                end
                local function cat(dx, dy) return im.ImVec2(contX + dx, contY + dy) end

                -- v1.8.0: line-иконки разделов (16 px, тонкие штрихи)
                -- Reference-style sidebar: white outline glyphs, no coloured badges.
                local ICX, ICS = 10, 20
                local TAB_ICONS = {
                    character="profile", cheats="feather", checkers="checker",
                    binder="edit", logs="copies", notes="notebook", mppanel="flag",
                    punish="clipboard", report="report", recon="eye", settings="gear",
                }
                local function tabIcon(icdl, kind, ox, oy, col)
                    local scale=ICS/20
                    local function V(x,y) return im.ImVec2(ox+x*scale,oy+y*scale) end
                    local function L(x1,y1,x2,y2)
                        pcall(icdl.AddLine,icdl,V(x1,y1),V(x2,y2),col,1.45*scale)
                    end
                    local function P(points,closed)
                        for j=2,#points do L(points[j-1][1],points[j-1][2],points[j][1],points[j][2]) end
                        if closed then L(points[#points][1],points[#points][2],points[1][1],points[1][2]) end
                    end
                    local function C(x,y,r)
                        pcall(icdl.AddCircle,icdl,V(x,y),r*scale,col,24,1.45*scale)
                    end
                    local function R(x1,y1,x2,y2,r)
                        pcall(icdl.AddRect,icdl,V(x1,y1),V(x2,y2),col,(r or 1.5)*scale,0,1.45*scale)
                    end
                    if kind=="profile" then
                        C(10,10,7.1); C(10,7.6,2.25)
                        P({{5.7,15.1},{6.2,12.8},{8.1,11.9},{11.9,11.9},{13.8,12.8},{14.3,15.1}})
                    elseif kind=="feather" then
                        P({{4,16.8},{5,8.6},{7.1,5.1},{10.6,3.2},{16.8,3.2},{16.1,8.6},{13.5,12},{9.6,13.2},{5,13.2}})
                        P({{3.4,17},{8.8,10.4},{13,7}})
                        L(7.5,12,12.8,12)
                    elseif kind=="checker" then
                        L(3,4,16,4); L(3,8.5,6,8.5); L(3,13,5.5,13)
                        C(11,11.5,3.7); L(13.7,14.2,17,17.2)
                        L(4,2.7,4,5.3)
                    elseif kind=="edit" then
                        P({{8,5},{4,5},{3,6},{3,16},{4,17},{14,17},{15,16},{15,12}})
                        P({{7,12},{8,8.8},{14.7,2.3},{17.4,5},{10.7,11.7},{7,12}},true)
                        L(12.9,4.1,15.6,6.8)
                    elseif kind=="copies" then
                        R(3,6,13,17,1.5); R(7,3,17,14,1.5)
                    elseif kind=="notebook" then
                        R(4.5,3,15.5,17,1.6)
                        L(7.5,6.5,12.5,6.5); L(7.5,10,12.5,10); L(7.5,13.5,11,13.5)
                        L(3,6,5.5,6); L(3,10,5.5,10); L(3,14,5.5,14)
                    elseif kind=="flag" then
                        L(4,3,4,17)
                        P({{4,4},{10,3.5},{11,5},{17,4.5},{16,11},{10,11.5},{9,10},{4,10.5}})
                    elseif kind=="clipboard" or kind=="report" then
                        if kind=="clipboard" then
                            R(4,4,16,17,1.5)
                        else
                            P({{16,9},{16,5},{15,4},{5,4},{4,5},{4,16},{5,17},{9,17}})
                        end
                        R(7,2.5,13,6,1)
                        L(7,9,12,9); L(7,12,kind=="report" and 9 or 12,12)
                        if kind=="report" then
                            C(14.2,14.3,3.8); L(14.2,12.4,14.2,14.5); L(14.2,14.5,15.7,15.3)
                        end
                    elseif kind=="eye" then
                        P({{2,10},{4,7.4},{7,5.6},{10,5},{13,5.6},{16,7.4},{18,10},
                            {16,12.6},{13,14.4},{10,15},{7,14.4},{4,12.6}},true)
                        C(10,10,2.6)
                    elseif kind=="gear" then
                        local points={}
                        for j=0,31 do
                            local angle=-math.pi/2+j*math.pi/16
                            local r=(j%4==1 or j%4==2) and 8 or 6.3
                            points[#points+1]={10+math.cos(angle)*r,10+math.sin(angle)*r}
                        end
                        P(points,true); C(10,10,2.7)
                    end
                end

                for i, t in ipairs(MENU_TABS) do
                    local rowY = (i - 1) * (BH + BGAP)
                    cur(0, rowY)
                    if im.InvisibleButton("##tab_" .. t.id, im.ImVec2(BW, BH)) then
                        menu.tab = i
                    end
                    local p1 = im.GetItemRectMin()
                    local p2 = im.GetItemRectMax()
                    local hovered  = (im.IsItemHovered and im.IsItemHovered()) or false
                    local pressed  = (im.IsItemActive  and im.IsItemActive())  or false
                    local selected = (menu.tab == i)

                    if selected then
                        roundRect(bdl, p1, p2, c32(TH.itemSel), 9)
                        if bdl.AddRect then
                            pcall(bdl.AddRect, bdl, p1, p2,
                                col32(TH.accent[1], TH.accent[2], TH.accent[3], 70), 9, 0, 1)
                        end
                    elseif pressed then
                        roundRect(bdl, p1, p2, c32(TH.itemPress), 9)
                    elseif hovered then
                        roundRect(bdl, p1, p2, c32(TH.itemHover), 9)
                    end

                    -- Single white outline pass; no tile, glow or cast shadow.
                    tabIcon(bdl,TAB_ICONS[t.id] or "notebook",
                        contX+ICX,contY+rowY+(BH-ICS)/2,
                        (selected or hovered) and col32(255,255,255,255)
                            or col32(233,230,240,245))

                    -- подпись пункта (вертикально по центру кнопки)
                    local th = select(2, tsize(t.name))
                    txt(ICX + ICS + 14, rowY + (BH - th) / 2, t.name,
                        selected and c4(TH.textHi)
                            or (hovered and c4(TH.text) or c4(TH.textDim)))

                end

                -- «бегунок» активного раздела — плавно переезжает между пунктами
                -- v1.12: menu.tab — ИНДЕКС раздела. Раньше любое чужое значение
                -- (строка/мусор — например, от другого скрипта или старого
                -- конфига) валило арифметику и ронял кадр ВСЕГО меню.
                local tabIdx = tonumber(menu.tab) or 1
                if tabIdx < 1 or tabIdx > #MENU_TABS then tabIdx = 1 end
                local targetY = (tabIdx - 1) * (BH + BGAP)
                if menu.indY == nil then menu.indY = targetY end
                menu.indY = menu.indY + (targetY - menu.indY) * math.min(1, dt * 14)
                gradRect(bdl, cat(0, menu.indY + 10), cat(3.5, menu.indY + BH - 10),
                    c32(TH.accent), c32(TH.accent2), 2)

                if useChild then
                    if type(im.EndChild) == "function" then pcall(im.EndChild)
                    else pcall(im.End) end
                end

                -- Fixed footer outside the scrolling navigation child.
                grndUiStylePanel({im=im,dl=dl,at=at,col32=col32,rgba=rgba,
                    roundRect=roundRect,uiText=uiText,tsize=tsize,slider=menuSlider,
                    x=BPAD,y=H-styleHeight,w=SB-BPAD*2,h=styleHeight})

                -- ---------- ПРАВАЯ ЧАСТЬ (КОНТЕНТ) ----------
                local tab = MENU_TABS[tabIdx] or MENU_TABS[1]
                local CX, px, py = SB, SB + 26, 26

                -- тонкая граница между панелями
                dl:AddRectFilled(at(CX, 16), at(CX + 1, H - 16), c32(TH.line))

                -- заголовок раздела + подпись
                local _, th2 = uiText(px, py, tab.name, c4(TH.textHi), 1.35)
                local subTitle = "Рабочие инструменты администратора"
                if tab.id == "settings" then
                    subTitle = (menu.settingsTab == "admin") and "настройки администратора" or "основные параметры скрипта"
                elseif tab.id == "cheats" then
                    subTitle = "управление чит-функциями"
                elseif tab.id == "checkers" then
                    subTitle = "визуальные чекеры и оверлеи"
                elseif tab.id == "recon" then
                    subTitle = "панель слежки и редактирование кнопок наказаний"
                elseif tab.id == "binder" then
                    subTitle = "Сообщения, горячие клавиши и последовательности команд"
                elseif tab.id == "punish" then
                    subTitle = "список наказаний · проверка онлайна · отправка с задержкой"
                elseif tab.id == "logs" then
                    subTitle = "История событий и действий"
                elseif tab.id == "notes" then
                    subTitle = "Заметки и важная информация"
                elseif tab.id == "mppanel" then
                    subTitle = "Управление мероприятиями"
                elseif tab.id == "report" then
                    subTitle = "Обращения игроков, быстрые ответы и автопилот"
                elseif tab.id == "character" then
                    subTitle = "погода и время · выдача себе · телепорты"
                end
                uiText(px, py + th2 + 6, subTitle, c4(TH.textMuted))
                -- кнопка закрытия (крестик) в правом верхнем углу
                local cbS, cbX, cbY = 26, W - 52, 18
                im.SetCursorPos(im.ImVec2(cbX, cbY))
                if im.InvisibleButton("##grnd_close", im.ImVec2(cbS, cbS)) then
                    menu.open = false
                end
                local chov = (im.IsItemHovered and im.IsItemHovered()) or false
                local q1, q2 = im.GetItemRectMin(), im.GetItemRectMax()
                if chov then roundRect(dl, q1, q2, col32(255, 96, 96, 34), 13) end
                local lc = chov and col32(255, 128, 128, 245) or col32(255, 255, 255, 110)
                local m = 8
                dl:AddLine(im.ImVec2(q1.x + m, q1.y + m), im.ImVec2(q2.x - m, q2.y - m), lc, 1.4)
                dl:AddLine(im.ImVec2(q2.x - m, q1.y + m), im.ImVec2(q1.x + m, q2.y - m), lc, 1.4)

                -- «карточка» под содержимое раздела
                local cardX, cardY = px, py + th2 + 44
                local cardW, cardH = W - 26 - cardX, H - 26 - cardY
                if cardW > 40 and cardH > 40 then
                    roundRect(dl, at(cardX, cardY),
                        at(cardX + cardW, cardY + cardH), c32(TH.contentBg), 12)
                    pcall(dl.AddRect, dl, at(cardX + 0.5, cardY + 0.5),
                        at(cardX + cardW - 0.5, cardY + cardH - 0.5),
                        c32(TH.contentEdge), 12, 0, 1)
                    -- СОДЕРЖИМОЕ РАЗДЕЛА: если у вкладки есть draw() — зовём её,
                    -- иначе заглушка «СКОРО» (как в прежнем виде)
                    if type(tab.draw) == "function" then
                        im.SetCursorPos(im.ImVec2(cardX + 16, cardY + 14))
                        local ok, err = pcall(tab.draw, {
                            w = cardW - 32, h = cardH - 28, pad = 16,
                            x = cardX, y = cardY,
                        })
                        if not ok then
                            uiText(cardX + 16, cardY + 14,
                                "Ошибка отрисовки раздела: " .. tostring(err),
                                c4({ 255, 110, 110, 255 }))
                        end
                    elseif tab.id == "logs" then
                        GRND_LOG.init()
                        for i,entry in ipairs(GRND_LOG.types) do
                            local y=cardY+22+(i-1)*56
                            if menuToggle(cardX+18,y,GRND_LOG.flags[entry[1]],'log_'..entry[1]) then GRND_LOG.toggle(entry[1]) end
                            uiText(cardX+76,y+2,entry[2],c4(TH.textHi),0.95)
                            im.SetCursorPos(im.ImVec2(cardX+cardW-136,y-3))
                            if im.Button('Посмотреть##log_'..entry[1],im.ImVec2(116,28)) then GRND_LOG.openDates(entry[1]) end
                            dl:AddLine(at(cardX+18,y+39),at(cardX+cardW-18,y+39),c32(TH.line),1)
                        end
                        if GRND_LOG.writeError then
                            uiText(cardX+18,cardY+310,'Не удалось сохранить лог',c4(TH.accent),0.85)
                        end
                        if GRND_LOG.uiError then
                            uiText(cardX+18,cardY+338,'Ошибка просмотра: подробности в moonloader.log',c4(TH.accent),0.85)
                        end
                    elseif tab.id == "settings" then
                        -- =====================================================
                        --  НАСТРОЙКИ: две кнопки вверху — «Основные» и «Админ»
                        -- =====================================================
                        menu.settingsTab = menu.settingsTab or "main"
                        local isMain = (menu.settingsTab == "main")

                        -- Две кнопки вверху раздела
                        local topY = cardY + 16
                        local topBtnW = 150
                        local topBtnH = 34
                        local b1X = cardX + 20
                        local b2X = b1X + topBtnW + 10

                        -- Кнопка 1: «Основные»
                        im.SetCursorPos(im.ImVec2(b1X, topY))
                        if im.InvisibleButton("##grnd_set_tab_main", im.ImVec2(topBtnW, topBtnH)) then
                            menu.settingsTab = "main"
                        end
                        local hov1 = (im.IsItemHovered and im.IsItemHovered()) or false
                        local bg1 = isMain and c32(TH.itemSel) or (hov1 and c32(TH.itemHover) or col32(255, 255, 255, 10))
                        roundRect(dl, at(b1X, topY), at(b1X + topBtnW, topY + topBtnH), bg1, 8)
                        if isMain then
                            roundRect(dl, at(b1X + 18, topY + topBtnH - 3), at(b1X + topBtnW - 18, topY + topBtnH - 1), c32(TH.accent), 2)
                        end
                        local tw1, th1 = tsize("Основные")
                        uiText(b1X + (topBtnW - tw1) / 2, topY + (topBtnH - th1) / 2, "Основные",
                            isMain and c4(TH.textHi) or (hov1 and c4(TH.text) or c4(TH.textDim)))

                        -- Кнопка 2: «Админ»
                        im.SetCursorPos(im.ImVec2(b2X, topY))
                        if im.InvisibleButton("##grnd_set_tab_admin", im.ImVec2(topBtnW, topBtnH)) then
                            menu.settingsTab = "admin"
                        end
                        local hov2 = (im.IsItemHovered and im.IsItemHovered()) or false
                        local bg2 = (not isMain) and c32(TH.itemSel) or (hov2 and c32(TH.itemHover) or col32(255, 255, 255, 10))
                        roundRect(dl, at(b2X, topY), at(b2X + topBtnW, topY + topBtnH), bg2, 8)
                        if not isMain then
                            roundRect(dl, at(b2X + 18, topY + topBtnH - 3), at(b2X + topBtnW - 18, topY + topBtnH - 1), c32(TH.accent), 2)
                        end
                        local tw2, th2 = tsize("Админ")
                        uiText(b2X + (topBtnW - tw2) / 2, topY + (topBtnH - th2) / 2, "Админ",
                            (not isMain) and c4(TH.textHi) or (hov2 and c4(TH.text) or c4(TH.textDim)))

                        -- Тонкий разделитель под кнопками
                        local sepY = topY + topBtnH + 14
                        dl:AddRectFilled(at(cardX + 20, sepY), at(cardX + cardW - 20, sepY + 1), c32(TH.line))

                        local secY = sepY + 14

                        if isMain then
                            -- =========================================================
                            --  ВКЛАДКА «ОСНОВНЫЕ»: ВЫДВИЖНАЯ ДИСТАНЦИЯ КАМЕРЫ (СЛАЙДЕР)
                            -- =========================================================
                            local cBoxX = cardX + 20
                            local cBoxY = secY
                            local cBoxW = cardW - 40

                            -- Плавное выдвижение / складывание (easeOutQuad)
                            local targetAnim = (GRND_CAM.expanded and 1.0 or 0.0)
                            GRND_CAM.anim = GRND_CAM.anim or targetAnim
                            if GRND_CAM.anim < targetAnim then
                                GRND_CAM.anim = math.min(targetAnim, GRND_CAM.anim + dt * 9.0)
                            elseif GRND_CAM.anim > targetAnim then
                                GRND_CAM.anim = math.max(targetAnim, GRND_CAM.anim - dt * 9.0)
                            end
                            local ease = 1 - (1 - GRND_CAM.anim) * (1 - GRND_CAM.anim)

                            local hHeader = 48
                            local hDrawer = 150
                            local boxH = hHeader + math.floor(hDrawer * ease)

                            -- Фоновая карточка
                            roundRect(dl, at(cBoxX, cBoxY), at(cBoxX + cBoxW, cBoxY + boxH),
                                col32(255, 255, 255, 10), 10)
                            if dl.AddRect then
                                pcall(dl.AddRect, dl, at(cBoxX, cBoxY), at(cBoxX + cBoxW, cBoxY + boxH),
                                    col32(255, 255, 255, 18), 10)
                            end

                            -- Индикатор состояния (зелёный/серый кружок)
                            local isCamOn = (GRND_CAM.enabled == true)
                            dl:AddCircleFilled(at(cBoxX + 22, cBoxY + 24), 4.5,
                                isCamOn and c32(TH.accent) or col32(255, 255, 255, 55))

                            -- Заголовок пункта
                            uiText(cBoxX + 38, cBoxY + 15, "Дистанция камеры", c4(TH.textHi), 1.05)

                            -- Правая часть: стрелочка раскрытия + тумблер + текущее значение
                            local arrW = 28
                            local arrX = cBoxX + cBoxW - arrW - 12
                            local tW, tH = 46, 24
                            local tX = arrX - tW - 14
                            local tY = cBoxY + (hHeader - tH) / 2

                            -- Кнопка-стрелочка [ v / > ]
                            im.SetCursorPos(im.ImVec2(arrX, cBoxY + (hHeader - 24) / 2))
                            if im.InvisibleButton("##cam_arr_btn", im.ImVec2(arrW, 24)) then
                                GRND_CAM.expanded = not GRND_CAM.expanded
                            end
                            local arrHov = (im.IsItemHovered and im.IsItemHovered()) or false
                            if arrHov then
                                roundRect(dl, at(arrX, cBoxY + (hHeader - 24) / 2),
                                    at(arrX + arrW, cBoxY + (hHeader + 24) / 2),
                                    col32(255, 255, 255, 16), 6)
                            end
                            local arrSym = (GRND_CAM.anim > 0.4) and "v" or ">"
                            local aw, ah = tsize(arrSym)
                            uiText(arrX + (arrW - aw) / 2, cBoxY + (hHeader - ah) / 2, arrSym,
                                arrHov and c4(TH.textHi) or c4(TH.textDim), 0.95)

                            -- Тумблер ВКЛ / ВЫКЛ
                            if menuToggle(tX, tY, isCamOn, "cam_toggle_main") then
                                GRND_CAM.enabled = not GRND_CAM.enabled
                                if GRND_CAM.enabled then
                                    GRND_CAM.expanded = true
                                end
                                GRND_CAM.cfgDirty = true
                                pcall(grndCamCfgSave)
                            end

                            -- Значение дистанции текстом (например, 12.0 м)
                            local distStr = string.format("%.1f м", GRND_CAM.dist or 12.0)
                            local dw = tsize(distStr)
                            uiText(tX - 14 - dw, cBoxY + 15, distStr,
                                isCamOn and c4(TH.accent) or c4(TH.textMuted))

                            -- Клик по строке заголовка также выдвигает/складывает ползунок
                            im.SetCursorPos(im.ImVec2(cBoxX, cBoxY))
                            if im.InvisibleButton("##cam_head_click", im.ImVec2(tX - 16 - cBoxX, hHeader)) then
                                GRND_CAM.expanded = not GRND_CAM.expanded
                            end

                            -- ВЫДВИЖНАЯ ЧАСТЬ: ДИСТАНЦИЯ + FOV-РЕЖИМ ПЕРСОНАЖА (v1.15.0)
                            if ease > 0.02 then
                                local drawerY = cBoxY + hHeader
                                local function dy(n) return math.floor(n * ease) end

                                -- Разделительная линия
                                dl:AddRectFilled(at(cBoxX + 16, drawerY), at(cBoxX + cBoxW - 16, drawerY + 1),
                                    col32(255, 255, 255, math.floor(14 * ease)))

                                -- Ползунок (слайдер) дистанции
                                local sX = cBoxX + 22
                                local sW = cBoxW - 44
                                local sY = drawerY + dy(12)

                                local newDist, chDist = menuSlider(sX, sY, sW, GRND_CAM.dist or 12.0, 2.0, 50.0, 0.5, "cam_dist_slider")
                                if chDist then
                                    GRND_CAM.dist = newDist
                                    GRND_CAM.cfgDirty = true
                                end

                                -- Подписи под слайдером
                                local lblY = drawerY + dy(36)
                                uiText(sX, lblY, "2.0 м", c4(TH.textMuted), 0.8)
                                local hint = "отдаление камеры над персонажем"
                                local hw = tsize(hint)
                                uiText(sX + (sW - hw) / 2, lblY, hint, c4(TH.textMuted), 0.8)
                                local maxLbl = "50.0 м"
                                local mw = tsize(maxLbl)
                                uiText(sX + sW - mw, lblY, maxLbl, c4(TH.textMuted), 0.8)

                                -- ---------- FOV-режим: тумблер + ползунок ----------
                                local fovY = drawerY + dy(62)
                                uiText(sX, fovY, "Режим FOV", c4(TH.textHi), 0.98)
                                uiText(sX, fovY + 18, "угол обзора камеры для моего персонажа",
                                    c4(TH.textMuted), 0.82)
                                local fovOn = (GRND_CAM.fovOn == true)
                                local ftW, ftH = 46, 24
                                local ftX = sX + sW - ftW
                                if menuToggle(ftX, fovY - 2, fovOn, "cam_fov_toggle") then
                                    GRND_CAM.fovOn = not fovOn
                                    if GRND_CAM.fovOn then
                                        GRND_CAM.fovApplied = nil -- мягкий переход к своему углу
                                    end
                                    -- при выключении apply сам плавно вернёт 70°
                                    -- Applied smoothly by grndCamTick.
                                    GRND_CAM.cfgDirty = true
                                end
                                local fovVal = string.format("%.0f°", GRND_CAM.fov or 80.0)
                                uiText(ftX - 14 - tsize(fovVal), fovY, fovVal,
                                    fovOn and c4(TH.accent) or c4(TH.textMuted), 0.92)

                                -- Ползунок FOV
                                local fovSY = drawerY + dy(106)
                                local newFov, chFov = menuSlider(sX, fovSY, sW,
                                    GRND_CAM.fov or 80.0, 45.0, 110.0, 1.0, "cam_fov_slider")
                                if chFov then
                                    GRND_CAM.fov = newFov
                                    if GRND_CAM.fovOn then
                                        -- значение доедет записью памяти, без
                                        -- перезапусков лерпа (без дёрганья)
                                        -- Applied smoothly by grndCamTick.
                                    end
                                    GRND_CAM.cfgDirty = true
                                end
                                local flblY = drawerY + dy(130)
                                uiText(sX, flblY, "45°", c4(TH.textMuted), 0.8)
                                local fhint = fovOn and "применяется к вашей камере" or "включите режим FOV"
                                uiText(sX + (sW - tsize(fhint)) / 2, flblY, fhint, c4(TH.textMuted), 0.8)
                                uiText(sX + sW - tsize("110°"), flblY, "110°", c4(TH.textMuted), 0.8)
                            end

                            if GRND_CAM.cfgDirty then
                                pcall(grndCamCfgSave)
                            end

                            -- =========================================================
                            --  «НАСТРОЙКА ЧАТА»: выпадающий список, первый пункт —
                            --  «Открытие чата» с выбором клавиши (по умолчанию T)
                            -- =========================================================
                            local CH = GRND_CHAT
                            local chX = cBoxX
                            local chY = cBoxY + boxH + 14
                            local chW = cBoxW
                            local chTarget = CH.expanded and 1.0 or 0.0
                            CH.anim = CH.anim or 0
                            if CH.anim < chTarget then CH.anim = math.min(chTarget, CH.anim + dt * 9.0)
                            elseif CH.anim > chTarget then CH.anim = math.max(chTarget, CH.anim - dt * 9.0) end
                            local chEase = 1 - (1 - CH.anim) * (1 - CH.anim)
                            local chHead = 48
                            local chDrawer = (CH.binding and 78 or 56) + 154
                            local chBoxH = chHead + math.floor(chDrawer * chEase)

                            roundRect(dl, at(chX, chY), at(chX + chW, chY + chBoxH), col32(255, 255, 255, 10), 10)
                            if dl.AddRect then
                                pcall(dl.AddRect, dl, at(chX, chY), at(chX + chW, chY + chBoxH), col32(255, 255, 255, 18), 10)
                            end
                            dl:AddCircleFilled(at(chX + 22, chY + 24), 4.5, c32(TH.accent))
                            uiText(chX + 38, chY + 15, "Настройка чата", c4(TH.textHi), 1.05)

                            local chArrX = chX + chW - arrW - 12
                            im.SetCursorPos(im.ImVec2(chArrX, chY + (chHead - 24) / 2))
                            if im.InvisibleButton("##chat_arr_btn", im.ImVec2(arrW, 24)) then
                                CH.expanded = not CH.expanded
                            end
                            local chArrHov = (im.IsItemHovered and im.IsItemHovered()) or false
                            if chArrHov then
                                roundRect(dl, at(chArrX, chY + (chHead - 24) / 2),
                                    at(chArrX + arrW, chY + (chHead + 24) / 2), col32(255, 255, 255, 16), 6)
                            end
                            local chSym = (CH.anim > 0.4) and "v" or ">"
                            local caw, cah = tsize(chSym)
                            uiText(chArrX + (arrW - caw) / 2, chY + (chHead - cah) / 2, chSym,
                                chArrHov and c4(TH.textHi) or c4(TH.textDim), 0.95)
                            -- текущая клавиша справа в шапке
                            local chKeyStr = "чат: " .. grndKeyName(CH.key or 0x54)
                            local ckw = tsize(chKeyStr)
                            uiText(chArrX - 14 - ckw, chY + 15, chKeyStr, c4(TH.accent))

                            im.SetCursorPos(im.ImVec2(chX, chY))
                            if im.InvisibleButton("##chat_head_click", im.ImVec2(chArrX - 14 - ckw - 16 - chX, chHead)) then
                                CH.expanded = not CH.expanded
                            end

                            if chEase > 0.02 then
                                local dY = chY + chHead
                                dl:AddRectFilled(at(chX + 16, dY), at(chX + chW - 16, dY + 1),
                                    col32(255, 255, 255, math.floor(14 * chEase)))
                                local rY = dY + math.floor(10 * chEase)
                                -- (1) ОТКРЫТИЕ ЧАТА
                                uiText(chX + 22, rY + 6, "Открытие чата", c4(TH.textHi), 0.98)
                                uiText(chX + 22, rY + 24, "клавиша, которая открывает строку ввода чата",
                                    c4(TH.textMuted), 0.82)
                                local kb = CH.binding and true or false
                                local kLabel = kb and "Нажмите клавишу..." or ("[ " .. grndKeyName(CH.key or 0x54) .. " ]")
                                local kw, kh = tsize(kLabel)
                                local kbW = math.max(124, kw + 24)
                                local kbH = 26
                                local kbX = chX + chW - 16 - kbW
                                local kbY = rY + 9
                                im.SetCursorPos(im.ImVec2(kbX, kbY))
                                if im.InvisibleButton("##grnd_chat_keybind", im.ImVec2(kbW, kbH)) then
                                    CH.binding = not CH.binding
                                    if CH.binding then
                                        if GRND_INVIS then GRND_INVIS.binding = false end
                                        if GRND_AREP then GRND_AREP.binding = false end
                                        if GRND_CATCH then GRND_CATCH.binding = false end
                                        if GRND_ABRK then GRND_ABRK.binding = false end
                                    end
                                end
                                local kHov = (im.IsItemHovered and im.IsItemHovered()) or false
                                local kBg = kb and col32(TH.accent[1], TH.accent[2], TH.accent[3], 45)
                                    or (kHov and col32(255, 255, 255, 22) or col32(255, 255, 255, 12))
                                roundRect(dl, at(kbX, kbY), at(kbX + kbW, kbY + kbH), kBg, 6)
                                if dl.AddRect then
                                    pcall(dl.AddRect, dl, at(kbX, kbY), at(kbX + kbW, kbY + kbH),
                                        kb and c32(TH.accent) or (kHov and col32(255, 255, 255, 45) or col32(255, 255, 255, 20)), 6)
                                end
                                uiText(kbX + (kbW - kw) / 2, kbY + (kbH - kh) / 2, kLabel,
                                    kb and c4(TH.accent) or (kHov and c4(TH.textHi) or c4(TH.textDim)), 0.92)
                                if kb then
                                    uiText(chX + 22, rY + 48,
                                        "Нажмите любую клавишу (ESC — отмена, Backspace/DEL — вернуть T)",
                                        c4(TH.accent), 0.85)
                                end
                                -- (2) ВРЕМЯ В ЧАТЕ
                                local r2Y = rY + (kb and 74 or 52)
                                uiText(chX + 22, r2Y + 6, "Время в чате", c4(TH.textHi), 0.98)
                                uiText(chX + 22, r2Y + 24, "показывать [ЧЧ:ММ:СС] слева от сообщений",
                                    c4(TH.textMuted), 0.82)
                                local tsOn = CH.timestamps and true or false
                                local tW2, tH2 = 46, 24
                                local tX2 = chX + chW - 16 - tW2
                                local tY2 = r2Y + 9
                                if menuToggle(tX2, tY2, tsOn, "chat_timestamps") then
                                    CH.timestamps = not tsOn
                                    pcall(grndChatStampApply)
                                    pcall(grndCamCfgSave)
                                end
                                local st2 = tsOn and "вкл" or "выкл"
                                local st2w = tsize(st2)
                                uiText(tX2 - 10 - st2w, tY2 + (tH2 - 14) / 2, st2,
                                    tsOn and c4(TH.accent) or c4(TH.textMuted))
                                -- (3) КОЛИЧЕСТВО СТРОК
                                local idY = r2Y + 48
                                uiText(chX + 22, idY + 6, "ID игроков в чате", c4(TH.textHi), 0.98)
                                uiText(chX + 22, idY + 24, "добавлять [ID] к никам игроков онлайн", c4(TH.textMuted), 0.82)
                                if menuToggle(tX2, idY + 9, CH.ids ~= false, "chat_player_ids") then
                                    GRND_CHATID.setEnabled(CH.ids == false)
                                end
                                local r3Y = idY + 56
                                uiText(chX + 22, r3Y + 4, "Строк в чате", c4(TH.textHi), 0.98)
                                local slX = chX + 22
                                local slW = chW - 80
                                local nl, chL = menuSlider(slX, r3Y + 24, slW, CH.lines or 10, 10, 20, 1, "chat_lines")
                                if chL then
                                    CH.lines = math.max(10, math.min(20, math.floor(nl + 0.5)))
                                    pcall(grndChatStampApply)
                                    pcall(grndCamCfgSave)
                                end
                                local lStr = tostring(math.floor(CH.lines or 10))
                                uiText(chX + chW - 16 - tsize(lStr), r3Y + 4, lStr, c4(TH.accent), 0.95)
                            end
                        else
                            grndAdminSettingsDraw({im=im,uiText=uiText,tsize=tsize,
                                roundRect=roundRect,col32=col32,rgba=rgba,dt=dt,
                                x=cardX+16,y=secY,w=cardW-32,
                                h=math.max(80,cardY+cardH-secY-12)})
                        end
                    elseif tab.id == "cheats" then
                        -- =========================================
                        --  ЧИТЫ: строка «GM» с ползунком вкл/выкл
                        -- =========================================
                        local rowX, rowY = cardX + 20, cardY + 20
                        local rowW, rowH = cardW - 40, 46
                        roundRect(dl, at(rowX, rowY), at(rowX + rowW, rowY + rowH),
                            col32(255, 255, 255, 10), 9)

                        -- подпись + описание
                        uiText(rowX + 14, rowY + 7,  "GM", c4(TH.textHi), 1.05)
                        uiText(rowX + 14, rowY + 26, "God Mode: клиент + сервер (/gm)",
                            c4(TH.textMuted), 0.9)

                        -- ползунок (тумблер) справа
                        local tW, tH = 46, 24
                        local tX = rowX + rowW - tW - 12
                        local tY = rowY + (rowH - tH) / 2
                        im.SetCursorPos(im.ImVec2(tX, tY))
                        if im.InvisibleButton("##grnd_gm_toggle", im.ImVec2(tW, tH)) then
                            if type(grndGMToggle) == "function" then
                                pcall(grndGMToggle)
                            elseif GRND_GM then
                                GRND_GM.on = not GRND_GM.on
                            end
                        end
                        local tHov = (im.IsItemHovered and im.IsItemHovered()) or false
                        local gmOn = (GRND_GM and GRND_GM.on) and true or false

                        grndUiSwitchPaint({dl=dl,at=at,col32=col32,roundRect=roundRect},
                            tX,tY,gmOn,tHov,"gm",dt)

                        -- v1.12: вторая строка — «Авто-GM при заходе»
                        local row2Y = rowY + rowH + 10
                        roundRect(dl, at(rowX, row2Y), at(rowX + rowW, row2Y + rowH),
                            col32(255, 255, 255, 10), 9)
                        uiText(rowX + 14, row2Y + 7, "Авто-GM при заходе", c4(TH.textHi), 1.05)
                        uiText(rowX + 14, row2Y + 26,
                            "После авторизации сам включает клиент+сервер (/gm)",
                            c4(TH.textMuted), 0.9)
                        do
                            local aW, aH = 46, 24
                            local aX = rowX + rowW - aW - 12
                            local aY = row2Y + (rowH - aH) / 2
                            im.SetCursorPos(im.ImVec2(aX, aY))
                            if im.InvisibleButton("##grnd_gmauto_toggle", im.ImVec2(aW, aH)) then
                                local v = not (GRND_GM.autoClient and GRND_GM.autoServer)
                                GRND_GM.autoClient, GRND_GM.autoServer = v, v
                                pcall(grndCamCfgSave)
                                notify.add("Авто-GM: " .. (v and "ВКЛ" or "ВЫКЛ"), "info", 3)
                            end
                            local aHov = (im.IsItemHovered and im.IsItemHovered()) or false
                            local aOn = (GRND_GM.autoClient and GRND_GM.autoServer) and true or false
                            grndUiSwitchPaint({dl=dl,at=at,col32=col32,roundRect=roundRect},
                                aX,aY,aOn,aHov,"gm_auto",dt)
                            uiText(aX - 34, aY + 4, aOn and "вкл" or "выкл",
                                aOn and c4(TH.accent) or c4(TH.textMuted), 0.9)
                        end

                        -- состояние текстом слева от тумблера
                        local st  = gmOn and "вкл" or "выкл"
                        local stW = tsize(st)
                        uiText(tX - 10 - stW, tY + (tH - 14) / 2, st,
                            gmOn and c4(TH.accent) or c4(TH.textMuted))

                        -- =========================================
                        --  НЕВИДИМОСТЬ (INVIS)
                        -- =========================================
                        -- v1.14.18: ФИКС — строка раньше стояла там же, где
                        -- «Авто-GM» (rowY + rowH + 12): две карточки рисовались
                        -- друг на друге. Теперь каждая следующая карточка идёт
                        -- ПОСЛЕ предыдущей.
                        local r2Y = row2Y + rowH + 12
                        local r2H = 48
                        roundRect(dl, at(rowX, r2Y), at(rowX + rowW, r2Y + r2H),
                            col32(255, 255, 255, 10), 9)
                        if dl.AddRect then
                            pcall(dl.AddRect, dl, at(rowX, r2Y), at(rowX + rowW, r2Y + r2H), col32(255, 255, 255, 16), 9)
                        end

                        local invOn = (GRND_INVIS and GRND_INVIS.on) and true or false
                        dl:AddCircleFilled(at(rowX + 20, r2Y + 24), 4.5,
                            invOn and c32(TH.accent) or col32(255, 255, 255, 55))

                        uiText(rowX + 34, r2Y + 7, "Невидимость", c4(TH.textHi), 1.05)
                        uiText(rowX + 34, r2Y + 26, "Скрытие персонажа от игроков и админов (/invis)",
                            c4(TH.textMuted), 0.88)

                        -- Тумблер вкл/выкл справа
                        local invTX = rowX + rowW - tW - 12
                        local invTY = r2Y + (r2H - tH) / 2
                        if menuToggle(invTX, invTY, invOn, "invis_toggle_cheats") then
                            pcall(grndInvisToggle)
                        end

                        local invSt = invOn and "вкл" or "выкл"
                        local invStW = tsize(invSt)
                        uiText(invTX - 10 - invStW, invTY + (tH - 14) / 2, invSt,
                            invOn and c4(TH.accent) or c4(TH.textMuted))

                        -- Кнопка назначения клавиши (бинд)
                        local bnd = (GRND_INVIS and GRND_INVIS.binding) and true or false
                        local keyLabel = bnd and "Нажмите клавишу..."
                            or (GRND_INVIS.key and ("[ " .. grndKeyName(GRND_INVIS.key) .. " ]") or "[ Назначить клавишу ]")
                        local klW, klH = tsize(keyLabel)
                        local btnW = math.max(124, klW + 24)
                        local btnH = 26
                        local btnX = invTX - 10 - invStW - 14 - btnW
                        local btnY = r2Y + (r2H - btnH) / 2

                        im.SetCursorPos(im.ImVec2(btnX, btnY))
                        if im.InvisibleButton("##grnd_invis_keybind", im.ImVec2(btnW, btnH)) then
                            GRND_INVIS.binding = not GRND_INVIS.binding
                            if GRND_INVIS.binding and GRND_ABRK then
                                GRND_ABRK.binding = false
                            end
                        end
                        local bHov = (im.IsItemHovered and im.IsItemHovered()) or false

                        local btnBg = bnd
                            and col32(TH.accent[1], TH.accent[2], TH.accent[3], 45)
                            or (bHov and col32(255, 255, 255, 22) or col32(255, 255, 255, 12))
                        roundRect(dl, at(btnX, btnY), at(btnX + btnW, btnY + btnH), btnBg, 6)
                        if dl.AddRect then
                            local bBord = bnd and c32(TH.accent)
                                or (bHov and col32(255, 255, 255, 45) or col32(255, 255, 255, 20))
                            pcall(dl.AddRect, dl, at(btnX, btnY), at(btnX + btnW, btnY + btnH), bBord, 6)
                        end

                        uiText(btnX + (btnW - klW) / 2, btnY + (btnH - klH) / 2, keyLabel,
                            bnd and c4(TH.accent) or (bHov and c4(TH.textHi) or c4(TH.textDim)), 0.92)

                        -- Подсказка в режиме ожидания клавиши
                        if bnd then
                            local hint = "Нажмите любую клавишу для бинда (ESC — отмена, Backspace/DEL — очистить)"
                            uiText(rowX + 14, r2Y + r2H + 8, hint, c4(TH.accent), 0.85)
                        end

                        -- =========================================
                        --  AIRBREAK: полёт на удержании клавиши
                        -- =========================================
                        local r3Y = r2Y + r2H + (bnd and 30 or 0) + 12
                        local r3H = 48
                        roundRect(dl, at(rowX, r3Y), at(rowX + rowW, r3Y + r3H),
                            col32(255, 255, 255, 10), 9)
                        if dl.AddRect then
                            pcall(dl.AddRect, dl, at(rowX, r3Y), at(rowX + rowW, r3Y + r3H), col32(255, 255, 255, 16), 9)
                        end

                        local abOn = (GRND_ABRK and GRND_ABRK.on) and true or false
                        dl:AddCircleFilled(at(rowX + 20, r3Y + 24), 4.5,
                            abOn and c32(TH.accent) or col32(255, 255, 255, 55))

                        uiText(rowX + 34, r3Y + 7, "AirBreak", c4(TH.textHi), 1.05)
                        uiText(rowX + 34, r3Y + 26, "Полёт по взгляду камеры: клавиша вкл/выкл, движение W/S, A/D, стрелки вверх/вниз",
                            c4(TH.textMuted), 0.88)

                        -- Тумблер вкл/выкл справа
                        local abTX = rowX + rowW - tW - 12
                        local abTY = r3Y + (r3H - tH) / 2
                        if menuToggle(abTX, abTY, abOn, "airbreak_toggle") then
                            pcall(grndAbrkToggle)
                        end
                        local abFly = (GRND_ABRK and GRND_ABRK.fly) and true or false
                        local abSt = abFly and "полёт" or (abOn and "вкл" or "выкл")
                        local abStW = tsize(abSt)
                        uiText(abTX - 10 - abStW, abTY + (tH - 14) / 2, abSt,
                            (abFly or abOn) and c4(TH.accent) or c4(TH.textMuted))

                        -- Кнопка назначения клавиши (по умолчанию правый Shift)
                        local abBnd = (GRND_ABRK and GRND_ABRK.binding) and true or false
                        local abKeyLabel = abBnd and "Нажмите клавишу..."
                            or ("[ " .. grndKeyName(GRND_ABRK.key or 0xA1) .. " ]")
                        local abkW, abkH = tsize(abKeyLabel)
                        local abBtnW = math.max(124, abkW + 24)
                        local abBtnH = 26
                        local abBtnX = abTX - 10 - abStW - 14 - abBtnW
                        local abBtnY = r3Y + (r3H - abBtnH) / 2

                        im.SetCursorPos(im.ImVec2(abBtnX, abBtnY))
                        if im.InvisibleButton("##grnd_airbreak_keybind", im.ImVec2(abBtnW, abBtnH)) then
                            GRND_ABRK.binding = not GRND_ABRK.binding
                            if GRND_ABRK.binding then
                                if GRND_INVIS then GRND_INVIS.binding = false end
                                if GRND_AREP then GRND_AREP.binding = false end
                                if GRND_CATCH then GRND_CATCH.binding = false end
                                if GRND_CHAT then GRND_CHAT.binding = false end
                            end
                        end
                        local abBHov = (im.IsItemHovered and im.IsItemHovered()) or false
                        local abBtnBg = abBnd
                            and col32(TH.accent[1], TH.accent[2], TH.accent[3], 45)
                            or (abBHov and col32(255, 255, 255, 22) or col32(255, 255, 255, 12))
                        roundRect(dl, at(abBtnX, abBtnY), at(abBtnX + abBtnW, abBtnY + abBtnH), abBtnBg, 6)
                        if dl.AddRect then
                            local abBord = abBnd and c32(TH.accent)
                                or (abBHov and col32(255, 255, 255, 45) or col32(255, 255, 255, 20))
                            pcall(dl.AddRect, dl, at(abBtnX, abBtnY), at(abBtnX + abBtnW, abBtnY + abBtnH), abBord, 6)
                        end
                        uiText(abBtnX + (abBtnW - abkW) / 2, abBtnY + (abBtnH - abkH) / 2, abKeyLabel,
                            abBnd and c4(TH.accent) or (abBHov and c4(TH.textHi) or c4(TH.textDim)), 0.92)

                        if abBnd then
                            local abHint = "Нажмите любую клавишу для бинда (ESC — отмена, Backspace/DEL — правый Shift)"
                            uiText(rowX + 14, r3Y + r3H + 8, abHint, c4(TH.accent), 0.85)
                        end

                        -- Скорость полёта
                        local r4Y = r3Y + r3H + (abBnd and 30 or 0) + 10
                        local r4H = 44
                        roundRect(dl, at(rowX, r4Y), at(rowX + rowW, r4Y + r4H),
                            col32(255, 255, 255, 8), 9)
                        uiText(rowX + 14, r4Y + 6, "Скорость полёта", c4(TH.textHi), 0.98)
                        local abSlW = rowW - 120
                        local abSpeed = GRND_ABRK and GRND_ABRK.speed or 15
                        local abNS, abCh = menuSlider(rowX + 14, r4Y + 24, abSlW, abSpeed, 1, 200, 1, "airbreak_speed")
                        if abCh and GRND_ABRK then
                            GRND_ABRK.speed = math.max(1, math.min(200, math.floor(abNS + 0.5)))
                            pcall(grndCamCfgSave)
                        end
                        local abSStr = tostring(math.floor((GRND_ABRK and GRND_ABRK.speed) or 15))
                        uiText(rowX + rowW - 16 - tsize(abSStr), r4Y + 6, abSStr, c4(TH.accent), 0.95)

                        -- (настройка полупрозрачности убрана из меню по просьбе
                        --  заказчика; ghost-эффект работает со значениями из cfg)
                    elseif tab.id == "checkers" then
                        -- =================================================
                        --  ЧЕКЕРЫ. №1 «Новый Kill List», №2 «Админы в сети».
                        --  У каждого: тумблер вкл/выкл + стрелочка настроек.
                        --  Скролл вручную: одно смещение и клип — и кнопки,
                        --  и roundRect едут вместе (BeginChild рассинхронил).
                        -- =================================================
                        local ckViewX = cardX + 8
                        local ckViewY = cardY + 8
                        local ckViewW = cardW - 16
                        local ckViewH = cardH - 16
                        menu.ckScrollY = menu.ckScrollY or 0
                        menu.ckContentH = menu.ckContentH or (ckViewH + 1)
                        local function ckNum(v)
                            if v == nil then return nil end
                            if type(v) == "number" then return v end
                            local n = tonumber(v)
                            if n then return n end
                            local ok, r = pcall(function() return v + 0 end)
                            if ok and type(r) == "number" then return r end
                            return nil
                        end
                        local function ckMouseWin()
                            local mx, my
                            if type(im.GetIO) == "function" then
                                local ok, io = pcall(im.GetIO)
                                if ok and io and io.MousePos then
                                    mx, my = ckNum(io.MousePos.x), ckNum(io.MousePos.y)
                                end
                            end
                            if (not mx) and type(im.GetMousePos) == "function" then
                                local ok, a, b = pcall(im.GetMousePos)
                                if ok then
                                    if type(a) == "number" then mx, my = a, ckNum(b)
                                    elseif a then mx, my = ckNum(a.x), ckNum(a.y) end
                                end
                            end
                            if not mx then return nil, nil end
                            local px, py = ckNum(pos.x) or 0, ckNum(pos.y) or 0
                            return mx - px, my - py
                        end
                        local ckWheel = 0
                        pcall(function()
                            local io = im.GetIO()
                            ckWheel = ckNum(io.MouseWheel) or 0
                        end)
                        local lx, ly = ckMouseWin()
                        local ckOver = lx and lx >= ckViewX and lx <= ckViewX + ckViewW
                            and ly >= ckViewY and ly <= ckViewY + ckViewH
                        local ckMaxSc = math.max(0, (menu.ckContentH or 0) - ckViewH)
                        if ckOver and ckWheel ~= 0 then
                            menu.ckScrollY = menu.ckScrollY - ckWheel * 48
                        end
                        if menu.ckDragBar and type(im.IsMouseDown) == "function" then
                            local okD, down = pcall(im.IsMouseDown, 0)
                            if okD and down and ly then
                                local t = (ly - ckViewY) / math.max(1, ckViewH)
                                if t < 0 then t = 0 elseif t > 1 then t = 1 end
                                menu.ckScrollY = t * ckMaxSc
                            else
                                menu.ckDragBar = false
                            end
                        end
                        if menu.ckScrollY < 0 then menu.ckScrollY = 0 end
                        if menu.ckScrollY > ckMaxSc then menu.ckScrollY = ckMaxSc end
                        local ckX = ckViewX + 10
                        local ckW = math.max(40, ckViewW - 28)
                        local ckY = ckViewY + 8 - menu.ckScrollY
                        local hHeader = 56
                        local KL = GRND_KL
                        pcall(im.PushClipRect, at(ckViewX, ckViewY),
                            at(ckViewX + ckViewW, ckViewY + ckViewH), true)
                        if dl.PushClipRect then
                            pcall(dl.PushClipRect, dl, at(ckViewX, ckViewY),
                                at(ckViewX + ckViewW, ckViewY + ckViewH), true)
                        end
                        local klOn = (KL and KL.enabled) and true or false

                        -- плавное раскрытие настроек чекера (easeOutQuad)
                        local tAnim = (KL and KL.expanded) and 1.0 or 0.0
                        local anim = (KL and KL.animSet) or 0
                        if anim < tAnim then anim = math.min(tAnim, anim + dt * 9.0)
                        elseif anim > tAnim then anim = math.max(tAnim, anim - dt * 9.0) end
                        if KL then KL.animSet = anim end
                        local ease = 1 - (1 - anim) * (1 - anim)

                        -- v1.16: +30 к высоте выдвижной части — добавлен ряд
                        -- тумблера «Фон панели»
                        local hDrawer = 36 + 34 + 34 + 30 + 30 + 10
                        local boxH = hHeader + math.floor(hDrawer * ease)

                        -- ---------- КАРТОЧКА 1: KILL LIST ----------
                        roundRect(dl, at(ckX, ckY), at(ckX + ckW, ckY + boxH),
                            col32(255, 255, 255, 10), 10)
                        if dl.AddRect then
                            pcall(dl.AddRect, dl, at(ckX, ckY), at(ckX + ckW, ckY + boxH),
                                col32(255, 255, 255, 18), 10)
                        end
                        -- индикатор состояния
                        dl:AddCircleFilled(at(ckX + 22, ckY + 26), 4.5,
                            klOn and c32(TH.accent) or col32(255, 255, 255, 55))
                        uiText(ckX + 38, ckY + 13, "Новый Kill List", c4(TH.textHi), 1.06)
                        uiText(ckX + 38, ckY + 32,
                            "кастомный килл-лист вместо системного: ник[ID] · значок оружия · ник",
                            c4(TH.textMuted), 0.86)

                        -- стрелочка раскрытия настроек
                        local arrW, arrH = 30, 26
                        local arrX = ckX + ckW - arrW - 14
                        local arrY = ckY + (hHeader - arrH) / 2
                        im.SetCursorPos(im.ImVec2(arrX, arrY))
                        if im.InvisibleButton("##ck_kl_arr", im.ImVec2(arrW, arrH)) then
                            if KL then KL.expanded = not KL.expanded; KL.cfgDirty = true end
                        end
                        local arrHov = (im.IsItemHovered and im.IsItemHovered()) or false
                        if arrHov then
                            roundRect(dl, at(arrX, arrY), at(arrX + arrW, arrY + arrH),
                                col32(255, 255, 255, 16), 6)
                        end
                        local arrSym = (anim > 0.4) and "v" or ">"
                        local aw, ah = tsize(arrSym)
                        uiText(arrX + (arrW - aw) / 2, arrY + (arrH - ah) / 2, arrSym,
                            arrHov and c4(TH.textHi) or c4(TH.textDim), 0.95)

                        -- тумблер ВКЛ/ВЫКЛ чекера
                        local tW, tH = 46, 24
                        local tX = arrX - tW - 14
                        local tY = ckY + (hHeader - tH) / 2
                        if menuToggle(tX, tY, klOn, "ck_kl_toggle") then
                            if KL then
                                KL.enabled = not klOn
                                if KL.enabled then KL.expanded = true; ensureRender() end
                                KL.cfgDirty = true
                                pcall(grndKlCfgSave)
                            end
                        end
                        local stTxt = klOn and "вкл" or "выкл"
                        local stW2 = tsize(stTxt)
                        uiText(tX - 12 - stW2, ckY + (hHeader - 14) / 2, stTxt,
                            klOn and c4(TH.accent) or c4(TH.textMuted))

                        -- клик по заголовку тоже раскрывает настройки
                        im.SetCursorPos(im.ImVec2(ckX, ckY))
                        if im.InvisibleButton("##ck_kl_head", im.ImVec2(tX - ckX - 12, hHeader)) then
                            if KL then KL.expanded = not KL.expanded; KL.cfgDirty = true end
                        end

                        -- ---------- ВЫДВИЖНАЯ ЧАСТЬ: НАСТРОЙКИ ЧЕКЕРА ----------
                        if ease > 0.03 then
                            local dY = ckY + hHeader
                            dl:AddRectFilled(at(ckX + 16, dY), at(ckX + ckW - 16, dY + 1),
                                col32(255, 255, 255, math.floor(14 * ease)))
                            local rX = ckX + 18
                            local rW = ckW - 36
                            local y = dY + math.floor(10 * ease) + 4

                            local function ckDirty()
                                if KL then KL.cfgDirty = true end
                            end
                            local function ckBtn(x, yb, w, h, label, tag)
                                return menuBtn(x, yb, w, h, label, false, tag)
                            end
                            local function ckOpt(x, yb, w, label, key, tag)
                                local on = (KL and KL[key]) and true or false
                                uiText(x, yb + 4, label, c4(TH.textHi), 0.90)
                                if menuToggle(x + w - 46, yb, on, tag) then
                                    if KL then
                                        KL[key] = not on
                                        KL.cfgDirty = true
                                    end
                                    return true
                                end
                                return false
                            end

                            -- позиция + очистка
                            local b1w = math.min(220, math.floor(rW * 0.58))
                            local b2w = math.min(130, rW - b1w - 10)
                            if ckBtn(rX, y, b1w, 28, "Изменить местоположение", "ck_kl_move") then
                                if type(grndKlStartMoving) == "function" then
                                    pcall(grndKlStartMoving)
                                end
                            end
                            if ckBtn(rX + b1w + 10, y, b2w, 28, "Очистить", "ck_kl_clear") then
                                if type(grndKlClear) == "function" then pcall(grndKlClear) end
                            end
                            y = y + 36

                            -- количество строк
                            uiText(rX, y + 2, "Количество строк", c4(TH.textHi), 0.95)
                            local slW = math.floor(rW * 0.42)
                            local slX = rX + math.floor(rW * 0.50)
                            local valRows = (KL and KL.rows) or 6
                            local nr, chR = menuSlider(slX, y - 2, slW, valRows, 1, 24, 1, "ck_kl_rows")
                            if chR and KL then
                                KL.rows = math.max(1, math.min(24, math.floor(nr + 0.5)))
                                ckDirty()
                            end
                            uiText(rX + rW - tsize(tostring(math.floor(valRows))),
                                y + 2, tostring(math.floor(valRows)),
                                klOn and c4(TH.accent) or c4(TH.textDim), 0.92)
                            y = y + 34

                            -- размер
                            uiText(rX, y + 2, "Размер килл-листа", c4(TH.textHi), 0.95)
                            local valScale = (KL and KL.scale) or 1.0
                            local scStep = 1 / (tonumber(GRND_FONT and GRND_FONT.fontBase) or 16)
                            local ns, chS = menuSlider(slX, y - 2, slW, valScale, 0.5, 2.5,
                                                       scStep, "ck_kl_scale")
                            if chS and KL then
                                KL.scale = math.max(0.5, math.min(2.5, ns))
                                ckDirty()
                            end
                            local scBase = tonumber(GRND_FONT and GRND_FONT.fontBase) or 16
                            local scPx = math.max(9, math.min(40, math.floor(scBase * valScale + 0.5)))
                            local scStr = string.format("%.2fx · %dpx", valScale, scPx)
                            uiText(rX + rW - tsize(scStr), y + 2, scStr,
                                klOn and c4(TH.accent) or c4(TH.textDim), 0.92)
                            y = y + 34

                            -- два оставшихся тумблера
                            local gap = 12
                            local colW = math.floor((rW - gap) / 2)
                            ckOpt(rX, y, colW, "Название оружия", "showWName", "ck_kl_wn")
                            ckOpt(rX + colW + gap, y, colW, "Время убийства", "showTime", "ck_kl_time")
                            y = y + 30

                            -- v1.16: ПОДЛОЖКА панели. По умолчанию ВЫКЛЮЧЕНА —
                            -- чекер рисуется прямо на картинке игры, как родной
                            -- килл-лист. Включите, если нужен тёмный фон для
                            -- читаемости (значение хранится в конфиге).
                            ckOpt(rX, y, colW, "Фон панели", "bg", "ck_kl_bg")
                        end
                        -- ---------- КАРТОЧКА 2: АДМИНЫ В СЕТИ ----------
                        local AO = GRND_AO or {}
                        local aoOn = AO.enabled and true or false
                        local aoY = ckY + boxH + 12
                        local tAnimA = AO.expanded and 1.0 or 0.0
                        local animA = AO.animSet or 0
                        if animA < tAnimA then animA = math.min(tAnimA, animA + dt * 9.0)
                        elseif animA > tAnimA then animA = math.max(tAnimA, animA - dt * 9.0) end
                        AO.animSet = animA
                        local easeA = 1 - (1 - animA) * (1 - animA)
                        -- v1.16: +30 к высоте выдвижной части — ряд «Фон панели»
                        local hDrawerA = 36 + 34 + 34 + 30 + 22 + 8 * 24 + 12
                        local boxHA = hHeader + math.floor(hDrawerA * easeA)
                        do
                            roundRect(dl, at(ckX, aoY), at(ckX + ckW, aoY + boxHA),
                                col32(255, 255, 255, 10), 10)
                            if dl.AddRect then
                                pcall(dl.AddRect, dl, at(ckX, aoY), at(ckX + ckW, aoY + boxHA),
                                    col32(255, 255, 255, 18), 10)
                            end
                            dl:AddCircleFilled(at(ckX + 22, aoY + 26), 4.5,
                                aoOn and c32(TH.accent) or col32(255, 255, 255, 55))
                            uiText(ckX + 38, aoY + 13, "Админы в сети", c4(TH.textHi), 1.06)
                            uiText(ckX + 38, aoY + 32,
                                "список администрации, автообновление командой /admins",
                                c4(TH.textMuted), 0.86)

                            local arrWA, arrHA = 30, 26
                            local arrXA = ckX + ckW - arrWA - 14
                            local arrYA = aoY + (hHeader - arrHA) / 2
                            im.SetCursorPos(im.ImVec2(arrXA, arrYA))
                            if im.InvisibleButton("##ck_ao_arr", im.ImVec2(arrWA, arrHA)) then
                                AO.expanded = not AO.expanded; AO.cfgDirty = true
                            end
                            local arrHovA = (im.IsItemHovered and im.IsItemHovered()) or false
                            if arrHovA then
                                roundRect(dl, at(arrXA, arrYA), at(arrXA + arrWA, arrYA + arrHA),
                                    col32(255, 255, 255, 16), 6)
                            end
                            local arrSymA = (animA > 0.4) and "v" or ">"
                            local awA, ahA = tsize(arrSymA)
                            uiText(arrXA + (arrWA - awA) / 2, arrYA + (arrHA - ahA) / 2, arrSymA,
                                arrHovA and c4(TH.textHi) or c4(TH.textDim), 0.95)

                            local tWA, tHA = 46, 24
                            local tXA = arrXA - tWA - 14
                            local tYA = aoY + (hHeader - tHA) / 2
                            if menuToggle(tXA, tYA, aoOn, "ck_ao_toggle") then
                                AO.enabled = not aoOn
                                if AO.enabled then
                                    AO.expanded = true
                                    AO.nextAt = 0
                                    ensureRender()
                                end
                                AO.cfgDirty = true
                                pcall(grndAoCfgSave)
                            end
                            local stA = aoOn and "вкл" or "выкл"
                            local stWA2 = tsize(stA)
                            uiText(tXA - 12 - stWA2, aoY + (hHeader - 14) / 2, stA,
                                aoOn and c4(TH.accent) or c4(TH.textMuted))

                            im.SetCursorPos(im.ImVec2(ckX, aoY))
                            if im.InvisibleButton("##ck_ao_head", im.ImVec2(tXA - ckX - 12, hHeader)) then
                                AO.expanded = not AO.expanded; AO.cfgDirty = true
                            end

                            if easeA > 0.03 then
                                local dYA = aoY + hHeader
                                dl:AddRectFilled(at(ckX + 16, dYA), at(ckX + ckW - 16, dYA + 1),
                                    col32(255, 255, 255, math.floor(14 * easeA)))
                                local rXA = ckX + 18
                                local rWA = ckW - 36
                                local yA = dYA + math.floor(10 * easeA) + 4
                                local b1wA = math.min(220, math.floor(rWA * 0.58))
                                local b2wA = math.min(130, rWA - b1wA - 10)
                                if menuBtn(rXA, yA, b1wA, 28, "Изменить местоположение", false, "ck_ao_move") then
                                    if type(grndAoStartMoving) == "function" then
                                        pcall(grndAoStartMoving)
                                    end
                                end
                                if menuBtn(rXA + b1wA + 10, yA, b2wA, 28, "Обновить", false, "ck_ao_now") then
                                    AO.nextAt = 0
                                    if not AO.enabled then
                                        AO.enabled = true
                                        AO.cfgDirty = true
                                    end
                                end
                                yA = yA + 36
                                uiText(rXA, yA + 2, "Интервал обновления", c4(TH.textHi), 0.95)
                                local slWA = math.floor(rWA * 0.42)
                                local slXA = rXA + math.floor(rWA * 0.50)
                                local valInt = math.floor(tonumber(AO.interval) or 8)
                                local ni, chI = menuSlider(slXA, yA - 2, slWA, valInt, 3, 30, 1, "ck_ao_int")
                                if chI then
                                    AO.interval = math.max(3, math.min(30, math.floor(ni + 0.5)))
                                    AO.cfgDirty = true
                                end
                                local intStr = tostring(math.floor(tonumber(AO.interval) or 8)) .. " сек"
                                uiText(rXA + rWA - tsize(intStr), yA + 2, intStr,
                                    aoOn and c4(TH.accent) or c4(TH.textDim), 0.92)
                                yA = yA + 34
                                uiText(rXA, yA + 2, "Размер списка", c4(TH.textHi), 0.95)
                                local valScA = tonumber(AO.scale) or 1.0
                                local scStepA = 1 / (tonumber(GRND_FONT and GRND_FONT.fontBase) or 16)
                                local nsA, chSA = menuSlider(slXA, yA - 2, slWA, valScA, 0.35, 2.5,
                                                           scStepA, "ck_ao_scale")
                                if chSA then
                                    AO.scale = math.max(0.35, math.min(2.5, nsA))
                                    AO.cfgDirty = true
                                end
                                local scBaseA = tonumber(GRND_FONT and GRND_FONT.fontBase) or 16
                                local scPxA = math.max(9, math.min(40, math.floor(scBaseA * valScA + 0.5)))
                                local scStrA = string.format("%.2fx · %dpx", valScA, scPxA)
                                uiText(rXA + rWA - tsize(scStrA), yA + 2, scStrA,
                                    aoOn and c4(TH.accent) or c4(TH.textDim), 0.92)
                                yA = yA + 34
                                -- v1.16: ПОДЛОЖКА списка (по умолчанию ВЫКЛ).
                                -- Тумблер живёт рядом с остальными настройками
                                -- чекера и сохраняется в конфиг.
                                local onBgA = AO.bg and true or false
                                uiText(rXA, yA + 4, "Фон панели", c4(TH.textHi), 0.90)
                                if menuToggle(rXA + rWA - 46, yA, onBgA, "ck_ao_bg") then
                                    AO.bg = not onBgA
                                    AO.cfgDirty = true
                                end
                                yA = yA + 30
                                uiText(rXA, yA + 2, "Цвета по уровню", c4(TH.textHi), 0.95)
                                yA = yA + 22
                                AO.lvlCol = AO.lvlCol or {}
                                local pal = {
                                    { 255, 255, 255 }, { 190, 195, 205 },
                                    { 90, 210, 110 },  { 80, 220, 255 },
                                    { 80, 170, 255 },  { 175, 110, 255 },
                                    { 255, 90, 170 },  { 255, 175, 60 },
                                    { 255, 85, 85 },   { 255, 220, 70 },
                                }
                                local sq, sg = 16, 4
                                for lv = 1, 8 do
                                    local lab = tostring(lv) .. " уровень"
                                    uiText(rXA, yA + 2, lab, c4(TH.text), 0.90)
                                    local col = AO.lvlCol[lv]
                                    if type(col) ~= "table" then
                                        col = pal[lv] or pal[1]
                                        AO.lvlCol[lv] = { col[1], col[2], col[3] }
                                        col = AO.lvlCol[lv]
                                    end
                                    local sx = rXA + math.max(96, tsize(lab) + 12)
                                    for pi = 1, #pal do
                                        local pc = pal[pi]
                                        local bx = sx + (pi - 1) * (sq + sg)
                                        if bx + sq <= rXA + rWA then
                                            im.SetCursorPos(im.ImVec2(bx, yA + 1))
                                            if im.InvisibleButton("##ao_c" .. lv .. "_" .. pi,
                                                im.ImVec2(sq, sq)) then
                                                AO.lvlCol[lv] = { pc[1], pc[2], pc[3] }
                                                AO.cfgDirty = true
                                            end
                                            local hovC = (im.IsItemHovered and im.IsItemHovered()) or false
                                            roundRect(dl, at(bx, yA + 2), at(bx + sq, yA + 2 + sq),
                                                col32(pc[1], pc[2], pc[3], 255), 3)
                                            local sel = col and col[1] == pc[1]
                                                and col[2] == pc[2] and col[3] == pc[3]
                                            if sel or hovC then
                                                local bc = sel and col32(255, 255, 255, 240)
                                                    or col32(255, 255, 255, 120)
                                                if dl.AddRect then
                                                    pcall(dl.AddRect, dl, at(bx, yA + 2),
                                                        at(bx + sq, yA + 2 + sq), bc, 3, 0,
                                                        sel and 1.8 or 1.1)
                                                end
                                            end
                                        end
                                    end
                                    yA = yA + 24
                                end
                            end
                        end
                        if dl.PopClipRect then pcall(dl.PopClipRect, dl) end
                        pcall(im.PopClipRect)
                        do
                            local contentH = 24 + (tonumber(boxH) or hHeader) + 12 + (tonumber(boxHA) or 0)
                            if aoY and boxHA then
                                contentH = (aoY + boxHA) - (ckViewY + 8 - (menu.ckScrollY or 0)) + 16
                            end
                            menu.ckContentH = contentH
                            local maxSc = math.max(0, contentH - ckViewH)
                            if maxSc > 2 then
                                local barW = 5
                                local bx = ckViewX + ckViewW - 8
                                roundRect(dl, at(bx, ckViewY + 6),
                                    at(bx + barW, ckViewY + ckViewH - 6),
                                    col32(255, 255, 255, 28), 2)
                                local th = math.max(20, (ckViewH - 12) * ckViewH / contentH)
                                local ty = ckViewY + 6
                                    + (ckViewH - 12 - th) * ((menu.ckScrollY or 0) / maxSc)
                                roundRect(dl, at(bx, ty), at(bx + barW, ty + th),
                                    col32(255, 255, 255, 140), 2)
                                im.SetCursorPos(im.ImVec2(bx - 2, ckViewY))
                                pcall(im.InvisibleButton, "##ck_sbar",
                                    im.ImVec2(barW + 8, ckViewH))
                                local active = false
                                if im.IsItemActive then
                                    local okA, rA = pcall(im.IsItemActive)
                                    active = okA and rA and true or false
                                end
                                if active then menu.ckDragBar = true end
                            end
                        end

                    elseif tab.id == "report" then
                        -- =====================================================
                        --  РЕПОРТ: две кнопки вверху — «Инструменты» и
                        --  «Ответы на репорт» (как в «Настройках»)
                        -- =====================================================
                        menu.reportTab = menu.reportTab or "tools"
                        -- v1.19.15: под-вкладок стало четыре — «Инструменты»,
                        -- «Ответы на репорт», «Наказания» и «Автопилот».
                        -- v1.19.21: «Автопилот» — вкладки, в каждой свой
                        -- триггер, ответ /ans ID и команда /sp или /goto.
                        -- v1.19.22: вкладок может быть сколько нужно.
                        -- v1.19.23: у вкладки крестик удаления, добавление — «+».
                        -- v1.19.24: триггер сравнивается с репортом.
                        -- v1.19.36: режим сопоставления задаёт ответ
                        -- вкладки — {ID}/{all} ищут триггер словом в любом
                        -- месте репорта, обычный ответ — полное совпадение.
                        -- v1.19.25: вкладок до 15, срабатывают все совпавшие.
                        -- v1.19.26: слежка и мероприятие — пауза, а не выключение.
                        -- v1.19.27: настройки автопилота реально пишутся в config.json.
                        local topY = cardY + 16
                        local topBtnH = 34
                        local b1X = cardX + 20
                        local RTABS = {
                            { id = "tools",   label = "Инструменты" },
                            { id = "answers", label = "Ответы на репорт" },
                            { id = "punish",  label = "Наказания" },
                            { id = "auto",    label = "Автопилот" },
                        }
                        local rtGap = 10
                        local rtSum = rtGap * (#RTABS - 1)
                        for i = 1, #RTABS do
                            local lw = tsize(RTABS[i].label)
                            RTABS[i].w = math.max(120, lw + 34)
                            rtSum = rtSum + RTABS[i].w
                        end
                        -- узкое окно: поджимаем кнопки, чтобы все четыре влезли в ряд
                        local rtAvail = cardW - 40
                        if rtSum > rtAvail then
                            local k = rtAvail / rtSum
                            for i = 1, #RTABS do RTABS[i].w = math.max(84, math.floor(RTABS[i].w * k)) end
                        end
                        local rx = b1X
                        for i = 1, #RTABS do
                            local tb = RTABS[i]
                            local on = (menu.reportTab == tb.id)
                            im.SetCursorPos(im.ImVec2(rx, topY))
                            if im.InvisibleButton("##grnd_rep_tab_" .. tb.id, im.ImVec2(tb.w, topBtnH)) then
                                menu.reportTab = tb.id
                                on = true
                            end
                            local rhov = (im.IsItemHovered and im.IsItemHovered()) or false
                            roundRect(dl, at(rx, topY), at(rx + tb.w, topY + topBtnH),
                                on and c32(TH.itemSel) or (rhov and c32(TH.itemHover) or col32(255, 255, 255, 10)), 8)
                            if on then
                                roundRect(dl, at(rx + 18, topY + topBtnH - 3), at(rx + tb.w - 18, topY + topBtnH - 1),
                                    c32(TH.accent), 2)
                            end
                            local lw, lh = tsize(tb.label)
                            uiText(rx + (tb.w - lw) / 2, topY + (topBtnH - lh) / 2, tb.label,
                                on and c4(TH.textHi) or (rhov and c4(TH.text) or c4(TH.textDim)))
                            rx = rx + tb.w + rtGap
                        end

                        local sepY = topY + topBtnH + 14
                        dl:AddRectFilled(at(cardX + 20, sepY), at(cardX + cardW - 20, sepY + 1), c32(TH.line))
                        local secY = sepY + 14

                        if menu.reportTab == "tools" then
                        -- =========================================
                        --  ИНСТРУМЕНТЫ: «Быстрый /arep»
                        -- =========================================
                        local AR = GRND_AREP
                        local rowX, rowY = cardX + 20, secY
                        local rowW, rowH = cardW - 40, 50
                        roundRect(dl, at(rowX, rowY), at(rowX + rowW, rowY + rowH),
                            col32(255, 255, 255, 10), 9)
                        if dl.AddRect then
                            pcall(dl.AddRect, dl, at(rowX, rowY), at(rowX + rowW, rowY + rowH), col32(255, 255, 255, 14), 9)
                        end
                        local arOn = (AR and AR.enabled) and true or false
                        dl:AddCircleFilled(at(rowX + 20, rowY + 25), 4.5,
                            arOn and c32(TH.accent) or col32(255, 255, 255, 55))
                        uiText(rowX + 34, rowY + 8, "Быстрый /arep", c4(TH.textHi), 1.05)
                        uiText(rowX + 34, rowY + 27, "Нажатие клавиши отправляет команду /arep в чат",
                            c4(TH.textMuted), 0.88)

                        local tW, tH = 46, 24
                        local arTX = rowX + rowW - tW - 12
                        local arTY = rowY + (rowH - tH) / 2
                        if menuToggle(arTX, arTY, arOn, "arep_toggle") then
                            AR.enabled = not arOn
                            pcall(grndCamCfgSave)
                        end
                        local arSt = arOn and "вкл" or "выкл"
                        local arStW = tsize(arSt)
                        uiText(arTX - 10 - arStW, arTY + (tH - 14) / 2, arSt,
                            arOn and c4(TH.accent) or c4(TH.textMuted))

                        -- кнопка выбора клавиши
                        local bnd = (AR and AR.binding) and true or false
                        local keyLabel = bnd and "Нажмите клавишу..."
                            or (AR.key and ("[ " .. grndKeyName(AR.key) .. " ]") or "[ Назначить клавишу ]")
                        local klW, klH = tsize(keyLabel)
                        local btnW = math.max(124, klW + 24)
                        local btnH = 26
                        local btnX = arTX - 10 - arStW - 14 - btnW
                        local btnY = rowY + (rowH - btnH) / 2
                        im.SetCursorPos(im.ImVec2(btnX, btnY))
                        if im.InvisibleButton("##grnd_arep_keybind", im.ImVec2(btnW, btnH)) then
                            AR.binding = not AR.binding
                            if AR.binding then
                                if GRND_INVIS then GRND_INVIS.binding = false end
                                if GRND_CATCH then GRND_CATCH.binding = false end
                            end
                        end
                        local bHov = (im.IsItemHovered and im.IsItemHovered()) or false
                        local btnBg = bnd
                            and col32(TH.accent[1], TH.accent[2], TH.accent[3], 45)
                            or (bHov and col32(255, 255, 255, 22) or col32(255, 255, 255, 12))
                        roundRect(dl, at(btnX, btnY), at(btnX + btnW, btnY + btnH), btnBg, 6)
                        if dl.AddRect then
                            local bBord = bnd and c32(TH.accent)
                                or (bHov and col32(255, 255, 255, 45) or col32(255, 255, 255, 20))
                            pcall(dl.AddRect, dl, at(btnX, btnY), at(btnX + btnW, btnY + btnH), bBord, 6)
                        end
                        uiText(btnX + (btnW - klW) / 2, btnY + (btnH - klH) / 2, keyLabel,
                            bnd and c4(TH.accent) or (bHov and c4(TH.textHi) or c4(TH.textDim)), 0.92)
                        if bnd then
                            uiText(rowX + 14, rowY + rowH + 8,
                                "Нажмите любую клавишу для бинда (ESC — отмена, Backspace/DEL — очистить)",
                                c4(TH.accent), 0.85)
                        end

                        -- =========================================
                        --  РЕПОРТ: «Автоловля репорта»
                        -- =========================================
                        local CT = GRND_CATCH
                        local c2Y = rowY + rowH + (bnd and 30 or 12)
                        roundRect(dl, at(rowX, c2Y), at(rowX + rowW, c2Y + rowH),
                            col32(255, 255, 255, 10), 9)
                        if dl.AddRect then
                            pcall(dl.AddRect, dl, at(rowX, c2Y), at(rowX + rowW, c2Y + rowH), col32(255, 255, 255, 14), 9)
                        end
                        local ctOn = (CT and CT.enabled) and true or false
                        dl:AddCircleFilled(at(rowX + 20, c2Y + 25), 4.5,
                            (CT.active and ctOn) and c32(TH.accent2) or (ctOn and c32(TH.accent) or col32(255, 255, 255, 55)))
                        uiText(rowX + 34, c2Y + 8, "Автоловля репорта", c4(TH.textHi), 1.05)
                        uiText(rowX + 34, c2Y + 27,
                            CT.active and "идёт ловля — первый репорт из чата откроет окно"
                                       or "клавиша включает ожидание: репорт из чата сразу открывает окно",
                            CT.active and c4(TH.accent) or c4(TH.textMuted), 0.88)

                        local ctTX = rowX + rowW - tW - 12
                        local ctTY = c2Y + (rowH - tH) / 2
                        if menuToggle(ctTX, ctTY, ctOn, "catch_toggle") then
                            CT.enabled = not ctOn
                            if not CT.enabled then CT.active = false end
                            pcall(grndCamCfgSave)
                        end
                        local ctSt = ctOn and "вкл" or "выкл"
                        local ctStW = tsize(ctSt)
                        uiText(ctTX - 10 - ctStW, ctTY + (tH - 14) / 2, ctSt,
                            ctOn and c4(TH.accent) or c4(TH.textMuted))

                        local cbnd = (CT and CT.binding) and true or false
                        local ckLabel = cbnd and "Нажмите клавишу..."
                            or (CT.key and ("[ " .. grndKeyName(CT.key) .. " ]") or "[ Назначить клавишу ]")
                        local cklW, cklH = tsize(ckLabel)
                        local cbW = math.max(124, cklW + 24)
                        local cbH = 26
                        local cbX = ctTX - 10 - ctStW - 14 - cbW
                        local cbY = c2Y + (rowH - cbH) / 2
                        im.SetCursorPos(im.ImVec2(cbX, cbY))
                        if im.InvisibleButton("##grnd_catch_keybind", im.ImVec2(cbW, cbH)) then
                            CT.binding = not CT.binding
                            if CT.binding then
                                AR.binding = false
                                if GRND_INVIS then GRND_INVIS.binding = false end
                            end
                        end
                        local cbHov = (im.IsItemHovered and im.IsItemHovered()) or false
                        local cbBg = cbnd
                            and col32(TH.accent[1], TH.accent[2], TH.accent[3], 45)
                            or (cbHov and col32(255, 255, 255, 22) or col32(255, 255, 255, 12))
                        roundRect(dl, at(cbX, cbY), at(cbX + cbW, cbY + cbH), cbBg, 6)
                        if dl.AddRect then
                            local cbBord = cbnd and c32(TH.accent)
                                or (cbHov and col32(255, 255, 255, 45) or col32(255, 255, 255, 20))
                            pcall(dl.AddRect, dl, at(cbX, cbY), at(cbX + cbW, cbY + cbH), cbBord, 6)
                        end
                        uiText(cbX + (cbW - cklW) / 2, cbY + (cbH - cklH) / 2, ckLabel,
                            cbnd and c4(TH.accent) or (cbHov and c4(TH.textHi) or c4(TH.textDim)), 0.92)
                        if cbnd then
                            uiText(rowX + 14, c2Y + rowH + 8,
                                "Нажмите любую клавишу для бинда (ESC — отмена, Backspace/DEL — очистить)",
                                c4(TH.accent), 0.85)
                        end

                        -- =========================================
                        --  РЕПОРТ: «Репорты на экране»
                        -- =========================================
                        local RH = GRND_REPHUD
                        local c3Y = c2Y + rowH + (cbnd and 30 or 12)
                        local rhOn = (RH and RH.enabled) and true or false
                        local extraH = rhOn and 40 or 0   -- v1.15.1: один ползунок «Размер окна»
                        local c3H = rowH + extraH
                        roundRect(dl, at(rowX, c3Y), at(rowX + rowW, c3Y + c3H),
                            col32(255, 255, 255, 10), 9)
                        if dl.AddRect then
                            pcall(dl.AddRect, dl, at(rowX, c3Y), at(rowX + rowW, c3Y + c3H), col32(255, 255, 255, 14), 9)
                        end
                        dl:AddCircleFilled(at(rowX + 20, c3Y + 25), 4.5,
                            rhOn and c32(TH.accent) or col32(255, 255, 255, 55))
                        uiText(rowX + 34, c3Y + 8, "Репорты на экране", c4(TH.textHi), 1.05)
                        uiText(rowX + 34, c3Y + 27, "клик по строке открывает окно · шапку можно тащить",
                            c4(TH.textMuted), 0.88)
                        local rhTX = rowX + rowW - tW - 12
                        local rhTY = c3Y + (rowH - tH) / 2
                        if menuToggle(rhTX, rhTY, rhOn, "rephud_toggle") then
                            RH.enabled = not rhOn
                            if not RH.enabled then RH.items = {} end
                            pcall(grndCamCfgSave)
                            if RH.enabled and type(_G.ensureRender) == "function" then
                                pcall(_G.ensureRender, true)
                            end
                        end
                        local rhSt = rhOn and "вкл" or "выкл"
                        local rhStW = tsize(rhSt)
                        uiText(rhTX - 10 - rhStW, rhTY + (tH - 14) / 2, rhSt,
                            rhOn and c4(TH.accent) or c4(TH.textMuted))
                        if extraH > 0 then
                            dl:AddRectFilled(at(rowX + 16, c3Y + rowH), at(rowX + rowW - 16, c3Y + rowH + 1),
                                col32(255, 255, 255, 14))
                            -- v1.15.1: ОДНА настройка размера оверлея — «Размер окна».
                            -- Ползунок идёт ШАГАМИ КЕГЛЯ: каждое положение — на 1 px
                            -- крупнее шрифт, а окно пересчитывается от него один к
                            -- одному (расчёт — GRND_REPHUD.metrics): окно и всё
                            -- содержимое растут вместе с буквами, вёрстка не едет.
                            uiText(rowX + 20, c3Y + rowH + 10, "Размер окна", c4(TH.textHi), 0.92)
                            local fBase = tonumber(GRND_FONT and GRND_FONT.fontBase) or 16
                            local pxMin = math.max(9, math.floor(fBase * 0.70 + 0.5))
                            local pxMax = math.min(40, math.floor(fBase * 1.60 + 0.5))
                            local pxCur = math.max(pxMin, math.min(pxMax,
                                math.floor(fBase * RH.clampScale(RH.scale) + 0.5)))
                            local pxStop = pxCur
                            local winW = RH.metrics(pxStop / fBase, fBase, 0).W
                            -- подпись: кегль и получившаяся ширина окна; если окно
                            -- меню узкое — короткий вариант, чтобы не наезжать
                            local valTxt = string.format("%d px · окно %d px", pxStop, winW)
                            local valW = tsize(valTxt)
                            if 116 + 90 + valW + 34 > rowW then
                                valTxt = string.format("окно %d px", winW)
                                valW = tsize(valTxt)
                            end
                            local slW = math.max(90, rowW - 116 - valW - 34)
                            -- ползунок идёт по кеглю: одно движение = 1 px шрифта,
                            -- и окно пересчитывается ровно на ту же величину
                            local ns, chS = menuSlider(rowX + 116, c3Y + rowH + 6, slW,
                                                       pxCur, pxMin, pxMax, 1, "rephud_s")
                            if chS then
                                local pxNew = math.max(pxMin, math.min(pxMax, math.floor(ns + 0.5)))
                                RH.scale = RH.clampScale(pxNew / fBase)   -- применяем сразу
                                RH.cfgDirty = true
                            end
                            -- а в файл пишем ОДИН раз, когда ползунок отпустили:
                            -- запись настроек на каждом кадре перетаскивания
                            -- подтормаживала кадр и «дёргала» масштабирование
                            if RH.cfgDirty and not (GRND_MOUSE and GRND_MOUSE.down) then
                                RH.cfgDirty = false
                                pcall(grndCamCfgSave)
                            end
                            uiText(rowX + rowW - 20 - valW, c3Y + rowH + 10, valTxt,
                                c4(TH.accent), 0.9)
                        end
                        elseif menu.reportTab == "answers" then
                            -- =========================================
                            --  ОТВЕТЫ НА РЕПОРТ: шаблоны быстрых ответов
                            --  (редактор живёт в модуле GRND_QR: список слева,
                            --   форма справа, поиск, порядок, удаление)
                            -- =========================================
                            if type(_G.grndQrSettingsDraw) == "function" then
                                local okQr = pcall(_G.grndQrSettingsDraw, {
                                    im = im, dl = dl, at = at,
                                    x = cardX + 20, y = secY,
                                    w = cardW - 40,
                                    h = (cardY + cardH) - secY - 14,
                                    uiText = uiText, roundRect = roundRect,
                                    col32 = col32, c4 = c4, rgba = rgba,
                                    gradRect = gradRect, tsize = tsize,
                                    drawnW = drawnWb, menuToggle = menuToggle,
                                    pushCol = grndPushCol, popCol = grndPopCol,
                                    pushVarF = grndPushStyleF,
                                    pushVarV2 = grndPushStyleV2,
                                    popVar = grndPopStyle,
                                })
                                if not okQr then
                                    uiText(cardX + 20, secY + 6,
                                        "Шаблоны: ошибка отрисовки раздела",
                                        c4({ 255, 120, 120, 255 }), 0.95)
                                end
                            else
                                uiText(cardX + 20, secY + 6,
                                    "Модуль шаблонов не загружен", c4(TH.textDim), 0.95)
                            end
                        else
                            -- =========================================
                            --  ПОД-ВКЛАДКИ «РЕПОРТА» (v1.19.27): «Ответы на
                            --  репорт», «Наказания» и «Автопилот» — все три
                            --  рисуются своими модулями внутри GRND_QR.
                            -- =========================================
                            local rt = menu.reportTab
                            if rt == "punish" then
                                -- v1.19.16: шаблоны наказаний — та же настройка,
                                -- что у ответов (список слева, редактор справа),
                                -- плюс селектор команды и поля «Время»/«Причина»
                                if type(_G.grndQrPunishDraw) == "function" then
                                    local okPn = pcall(_G.grndQrPunishDraw, {
                                        im = im, dl = dl, at = at,
                                        x = cardX + 20, y = secY,
                                        w = cardW - 40,
                                        h = (cardY + cardH) - secY - 14,
                                        uiText = uiText, roundRect = roundRect,
                                        col32 = col32, c4 = c4, rgba = rgba,
                                        gradRect = gradRect, tsize = tsize,
                                        drawnW = drawnWb, menuToggle = menuToggle,
                                        pushCol = grndPushCol, popCol = grndPopCol,
                                        pushVarF = grndPushStyleF,
                                        pushVarV2 = grndPushStyleV2,
                                        popVar = grndPopStyle,
                                    })
                                    if not okPn then
                                        uiText(cardX + 20, secY + 6,
                                            "Наказания: ошибка отрисовки раздела",
                                            c4({ 255, 120, 120, 255 }), 0.95)
                                    end
                                else
                                    uiText(cardX + 20, secY + 6,
                                        "Модуль наказаний не загружен", c4(TH.textDim), 0.95)
                                end
                            elseif rt == "auto" then
                                -- v1.19.21: настройка автопилота — свой модуль в
                                -- GRND_QR. v1.19.22: вкладки, в каждой свой
                                -- триггер, ответ /ans ID и команда после него.
                                -- v1.19.23: добавление «+», удаление — крестик
                                -- вкладки; подписи раздела — без лишнего.
                                -- v1.19.24: триггер сравнивается с репортом.
                                -- v1.19.36: {ID} (ID из репорта + /sp ID
                                -- даже вместо /goto) и {all} — слово в любом
                                -- месте; обычный ответ — полное совпадение.
                                -- v1.19.25: вкладок до 15, срабатывают все,
                                -- у кого триггер совпал.
                                -- v1.19.26: слежка/мероприятие — авто-пауза.
                                -- v1.19.27: секция reportAuto в config.json.
                                if type(_G.grndQrAutoDraw) == "function" then
                                    local okAu = pcall(_G.grndQrAutoDraw, {
                                        im = im, dl = dl, at = at,
                                        x = cardX + 20, y = secY,
                                        w = cardW - 40,
                                        h = (cardY + cardH) - secY - 14,
                                        uiText = uiText, roundRect = roundRect,
                                        col32 = col32, c4 = c4, rgba = rgba,
                                        gradRect = gradRect, tsize = tsize,
                                        drawnW = drawnWb, menuToggle = menuToggle,
                                        pushCol = grndPushCol, popCol = grndPopCol,
                                        pushVarF = grndPushStyleF,
                                        pushVarV2 = grndPushStyleV2,
                                        popVar = grndPopStyle,
                                    })
                                    if not okAu then
                                        uiText(cardX + 20, secY + 6,
                                            "Автопилот: ошибка отрисовки раздела",
                                            c4({ 255, 120, 120, 255 }), 0.95)
                                    end
                                else
                                    uiText(cardX + 20, secY + 6,
                                        "Модуль автопилота не загружен", c4(TH.textDim), 0.95)
                                end
                            else
                                uiText(cardX + 20, secY + 6,
                                    "Выберите под-вкладку слева", c4(TH.textDim), 0.95)
                            end
                        end
                    elseif tab.id == "recon" then
                        -- =====================================================
                        --  РЕКОН (v1.12): тумблер панели слежки +
                        --  РЕДАКТИРОВАНИЕ кнопок наказаний (JAIL…SBAN, без IBAN).
                        -- =====================================================
                        local PUN = GRND_PUN
                        if PUN and not PUN.loaded then pcall(PUN.load) end
                        -- v1.14.58: nastroiki kamery slezhki ne zavisiat ot modulia
                        -- nakazanii, poetomy obshchii blok vypnuty iz "if PUN".
                        do
                            -- точная ширина текста с учётом масштаба (как в карточке рекона)
                            local function drawnW0(s, scale)
                                scale = scale or 1
                                if type(im.SetWindowFontScale) == "function" then
                                    if scale ~= 1 then
                                        pcall(im.SetWindowFontScale, scale)
                                        local okM, aM = pcall(im.CalcTextSize, tostring(s))
                                        pcall(im.SetWindowFontScale, 1)
                                        if okM then
                                            local ta = type(aM)
                                            local w = (ta == "table" or ta == "cdata")
                                                and tonumber(aM.x) or tonumber(aM)
                                            if w and w > 0 then return w end
                                        end
                                    end
                                    return grndTextW(s) * scale
                                end
                                return grndTextW(s)
                            end

                            local rcX = cardX + 20
                            local rcW = cardW - 40
                            -- ---------- строка-тумблер «Кнопки наказаний» ----------
                            local rowY = cardY + 16
                            local rowH = 50
                            roundRect(dl, at(rcX, rowY), at(rcX + rcW, rowY + rowH),
                                col32(255, 255, 255, 10), 9)
                            if dl.AddRect then
                                pcall(dl.AddRect, dl, at(rcX, rowY), at(rcX + rcW, rowY + rowH),
                                    col32(255, 255, 255, 14), 9)
                            end
                            local barOn = (PUN and PUN.barOn ~= false)
                            dl:AddCircleFilled(at(rcX + 20, rowY + 25), 4.5,
                                barOn and c32(TH.accent) or col32(255, 255, 255, 55))
                            uiText(rcX + 34, rowY + 8, "Кнопки наказаний в карточке", c4(TH.textHi), 1.05)
                            uiText(rcX + 34, rowY + 27,
                                "JAIL · BAN · KICK · MUTE — столбиком под аватаром · курсор — ПКМ",
                                c4(TH.textMuted), 0.88)
                            local tgX = rcX + rcW - 46 - 12
                            local tgY = rowY + (rowH - 24) / 2
                            if menuToggle(tgX, tgY, barOn, "rc_bar_toggle") then
                                if PUN then
                                    PUN.barOn = not barOn
                                    PUN.cfgDirty = true
                                    pcall(PUN.save)
                                end
                            end

                            -- ---------- строка-тумблер «Авто-обновление слежки» ----------
                            local row2Y = rowY + rowH + 10
                            local row2H = 50
                            roundRect(dl, at(rcX, row2Y), at(rcX + rcW, row2Y + row2H),
                                col32(255, 255, 255, 10), 9)
                            if dl.AddRect then
                                pcall(dl.AddRect, dl, at(rcX, row2Y), at(rcX + rcW, row2Y + row2H),
                                    col32(255, 255, 255, 14), 9)
                            end
                            local autoSpOn = (GRND_ADMIN_CFG and GRND_ADMIN_CFG.spAutoRefresh ~= false)
                            dl:AddCircleFilled(at(rcX + 20, row2Y + 25), 4.5,
                                autoSpOn and c32(TH.accent) or col32(255, 255, 255, 55))
                            uiText(rcX + 34, row2Y + 8, "Авто-обновление слежки (/sp)", c4(TH.textHi), 1.05)
                            uiText(rcX + 34, row2Y + 27,
                                "Авто-рекон при потере игрока, смене интерьера или респавне",
                                c4(TH.textMuted), 0.88)
                            local tg2X = rcX + rcW - 46 - 12
                            local tg2Y = row2Y + (row2H - 24) / 2
                            if menuToggle(tg2X, tg2Y, autoSpOn, "rc_autosp_toggle") then
                                if GRND_ADMIN_CFG then
                                    GRND_ADMIN_CFG.spAutoRefresh = not autoSpOn
                                end
                                if grndCamCfgSave then pcall(grndCamCfgSave) end
                            end

                            -- ---------- КАМЕРА СЛЕЖКИ (v1.14.59) ----------
                            -- Раскрывающаяся карточка (как WH в админ-настройках):
                            -- клик по шапке сворачивает/разворачивает. В свёрнутом
                            -- виде в шапке видны текущие значения. Обход стен
                            -- включён ВСЕГДА (тумблер убран v1.14.59). Строки
                            -- поджимаются по высоте — ничего не выходит за карточку.
                            local camExpand = menu.reconCamExpand
                            if camExpand == nil then
                                camExpand = (cardH >= 560)
                                menu.reconCamExpand = camExpand
                            end
                            local camY = row2Y + row2H + 8
                            local camH = camExpand and 80 or 46
                            -- v1.14.58 (фикс бага «пустой блок / пропал курсор /
                            -- окна без надписей»): весь блок оборачиваем в pcall.
                            -- Любая ошибка внутри рвалась наружу, и меню
                            -- оставалось с незакрытым окном ImGui — с этого
                            -- момента ломался весь кадр отрисовки.
                            local camOk, camErr = pcall(function()
                                local SN = _G.grndSpecNative or {}
                                roundRect(dl, at(rcX, camY), at(rcX + rcW, camY + camH),
                                    col32(255, 255, 255, 10), 9)
                                if dl.AddRect then
                                    pcall(dl.AddRect, dl, at(rcX + 0.5, camY + 0.5),
                                        at(rcX + rcW - 0.5, camY + camH - 0.5),
                                        col32(255, 255, 255, 14), 9)
                                end
                                -- шапка карточки = кнопка раскрытия
                                im.SetCursorPos(im.ImVec2(rcX, camY))
                                if im.InvisibleButton("##rc_cam_expand", im.ImVec2(rcW, 34)) then
                                    menu.reconCamExpand = not camExpand
                                end
                                local camHov = (im.IsItemHovered and im.IsItemHovered()) or false
                                if camHov then
                                    roundRect(dl, at(rcX + 1, camY + 1),
                                        at(rcX + rcW - 1, camY + 33), col32(255, 255, 255, 12), 8)
                                end
                                uiText(rcX + 16, camY + 8, "Камера слежки", c4(TH.textHi), 1.02)
                                -- сводка: дистанция (FOV из слежки убран v1.15.0)
                                local camSum = string.format("дист. %.1f м",
                                    tonumber(SN.camStartDist) or 7.0)
                                local sumW = drawnW0(camSum, 0.78)
                                if 16 + drawnW0("Камера слежки", 1.02) + 16 + sumW + 34 < rcW then
                                    uiText(rcX + rcW - 30 - sumW, camY + 11,
                                        camSum, c4(TH.textMuted), 0.78)
                                end
                                uiText(rcX + rcW - 22, camY + 9,
                                    camExpand and "v" or ">", c4(TH.textMuted), 0.95)
                                if camExpand then
                                    dl:AddRectFilled(at(rcX + 16, camY + 34),
                                        at(rcX + rcW - 16, camY + 35), col32(255, 255, 255, 10))

                                    -- строка: подпись | ползунок | значение.
                                    -- Ширины меряются по реальному тексту, поэтому
                                    -- элементы не наезжают друг на друга и никогда
                                    -- не вылезают за край карточки.
                                    local function camRow(y, label, value, vmin, vmax, step, tag, fmt, apply)
                                        uiText(rcX + 16, y + 2, label, c4(TH.textHi), 0.9)
                                        local sx = rcX + 16 + drawnW0(label, 0.9) + 12
                                        local vstr = string.format(fmt, tonumber(value) or value)
                                        local ex = rcX + rcW - 16 - drawnW0(vstr, 0.9) - 12
                                        if ex - sx < 50 then
                                            sx = math.max(rcX + 16, ex - 50)
                                        end
                                        local sw = math.max(50, ex - sx)
                                        local v, ch = menuSlider(sx, y, sw,
                                            value, vmin, vmax, step, tag)
                                        if ch and apply then apply(v) end
                                        vstr = string.format(fmt, tonumber(v) or value)
                                        uiText(rcX + rcW - 16 - drawnW0(vstr, 0.9), y + 2,
                                            vstr, c4(TH.accent), 0.9)
                                    end
                                    camRow(camY + 42, "Дистанция при входе",
                                        tonumber(SN.camStartDist) or 7.0, 2.0, 30.0, 0.5,
                                        "rc_cam_dist", "%.1f м",
                                        function(v)
                                            SN.camStartDist = v
                                            if grndCamCfgSave then pcall(grndCamCfgSave) end
                                        end)
                                end -- конец раскрытой части "Камера слежки"
                            end)
                            if not camOk then
                                -- не молчим: причина видна и в чате, и в самой
                                -- карточке, и остальной интерфейс продолжает жить.
                                -- Сам вызов тоже под pcall — иначе сообщение об
                                -- ошибке снова уронит меню.
                                logRenderErr("recon-cam", tostring(camErr))
                                pcall(uiText, rcX + 16, camY + 38,
                                    "Ошибка блока камеры: " .. tostring(camErr),
                                    c4(TH.accent2), 0.78)
                            end

                            if PUN then
                            -- ---------- заголовок секции ----------
                            local hY = camY + camH + 8
                            uiText(rcX, hY, "Редактирование наказаний", c4(TH.textHi), 1.08)
                            uiText(rcX + drawnW0("Редактирование наказаний", 1.08) + 12, hY + 3,
                                "нажмите на наказание, чтобы настроить причины и время",
                                c4(TH.textMuted), 0.84)
                            gradRect(dl, at(rcX, hY + 22), at(rcX + 36, hY + 25),
                                c32(TH.accent), c32(TH.accent2), 2)

                            -- ---------- список наказаний ----------
                            local listY = hY + 30
                            -- v1.14.58: высота строк списка считается от
                            -- свободного места, поэтому настройки камеры
                            -- никогда не выдавливают наказания за карточку.
                            -- v1.14.59: в тесноте строки сжимаются до 16 px и
                            -- зазор до 1 px — список всегда целиком в карточке.
                            local prowN   = math.max(1, #PUN.list)
                            local prowFree = math.max(0, cardH - 16 - listY)
                            local prowSlot = prowFree / prowN
                            local bh  = math.max(16, math.min(36, math.floor(prowSlot) - 6))
                            local bgap = math.max(1, math.min(6, math.floor(prowSlot - bh)))
                            if bh * prowN + bgap * (prowN - 1) > prowFree then
                                bgap = 1
                                bh = math.max(16, math.floor((prowFree - (prowN - 1)) / prowN))
                            end
                            for i, it in ipairs(PUN.list) do
                                local byY = listY + (i - 1) * (bh + bgap)
                                -- v1.14.59: за пределы карточки ничего не рисуем
                                if byY + bh > cardY + cardH - 8 then break end
                                im.SetCursorPos(im.ImVec2(rcX, byY))
                                local clicked = im.InvisibleButton("##rc_pun_" .. it.id,
                                    im.ImVec2(rcW, bh))
                                local hov = (im.IsItemHovered and im.IsItemHovered()) or false
                                roundRect(dl, at(rcX, byY), at(rcX + rcW, byY + bh),
                                    hov and c32(TH.itemHover) or col32(255, 255, 255, 7), 8)
                                if dl.AddRect then
                                    pcall(dl.AddRect, dl, at(rcX + 0.5, byY + 0.5),
                                        at(rcX + rcW - 0.5, byY + bh - 0.5),
                                        hov and col32(TH.accent[1], TH.accent[2], TH.accent[3], 90)
                                            or col32(255, 255, 255, 16), 8, 0, 1)
                                end
                                -- цветной маркер слева (у SKICK — серый: не настраивается)
                                roundRect(dl, at(rcX + 13, byY + 9), at(rcX + 15, byY + bh - 9),
                                    it.locked and col32(255, 255, 255, 40) or c32(TH.accent), 1)
                                uiText(rcX + 26, byY + (bh - 15) / 2, it.id,
                                    hov and c4(TH.textHi) or c4(TH.text), 0.98)
                                -- сводка справа: «4 причины · 4 времени»
                                local rc, tc = PUN.counts(it.id)
                                local summary
                                if it.locked then
                                    summary = "не настраивается"
                                else
                                    summary = tostring(rc) .. " "
                                        .. PUN.plural(rc, "причина", "причины", "причин")
                                    if it.time then
                                        summary = summary .. " · " .. tostring(tc) .. " "
                                            .. PUN.plural(tc, "время", "времени", "времён")
                                    else
                                        summary = summary .. " · время недоступно"
                                    end
                                end
                                local sumW = drawnW0(summary, 0.8)
                                uiText(rcX + rcW - 36 - sumW, byY + (bh - 14) / 2 + 1, summary,
                                    c4(TH.textMuted), 0.8)
                                -- двойной шеврон справа (как в эталоне)
                                local cxI = rcX + rcW - 22
                                local cyI = byY + bh / 2 - 5
                                local chC = hov and c32(TH.accent) or col32(255, 255, 255, 110)
                                dl:AddLine(at(cxI - 4, cyI + 2), at(cxI, cyI - 2), chC, 1.5)
                                dl:AddLine(at(cxI, cyI - 2), at(cxI + 4, cyI + 2), chC, 1.5)
                                dl:AddLine(at(cxI - 4, cyI + 8), at(cxI, cyI + 12), chC, 1.5)
                                dl:AddLine(at(cxI, cyI + 12), at(cxI + 4, cyI + 8), chC, 1.5)
                                if clicked then
                                    if it.locked then
                                        pcall(notify.add,
                                            "SKICK нельзя настроить. Отсутствуют время и причина",
                                            "warn", 3.5)
                                    else
                                        PUN.editId = it.id
                                        PUN.addCol = nil
                                        PUN.focused = false
                                        pcall(PUN.clearBuf)
                                    end
                                end
                            end
                        else
                            uiText(cardX + 20, cardY + 18, "Модуль наказаний не загружен",
                                c4(TH.textDim))
                        end
                        end -- v1.14.58: конец общего блока раздела Рекон
                    elseif tab.id == "punish" then
                        GRND_BULK.draw({im=im,dl=dl,at=at,
                            x=cardX+8,y=cardY+8,w=cardW-16,h=cardH-16,dt=dt,
                            uiText=uiText,tsize=tsize,roundRect=roundRect,
                            col32=col32,rgba=rgba,slider=menuSlider})
                    elseif tab.id == "binder" then
                        if type(_G.grndBinderDraw) == "function" then
                            _G.grndBinderDraw({
                                im = im, dl = dl, at = at,
                                cardX = cardX, cardY = cardY,
                                cardW = cardW, cardH = cardH,
                                uiText = uiText, tsize = tsize,
                                roundRect = roundRect, col32 = col32,
                                rgba = rgba, c4 = c4, gradRect = gradRect,
                            })
                        end
                    elseif tab.id == "character" then
                        -- v1.14.17: погода/время, выдача себе, телепорты
                        if type(_G.grndCharDraw) == "function" then
                            _G.grndCharDraw({
                                im = im, dl = dl, at = at,
                                cardX = cardX, cardY = cardY,
                                cardW = cardW, cardH = cardH,
                                uiText = uiText, tsize = tsize,
                                roundRect = roundRect, col32 = col32,
                                rgba = rgba, c4 = c4, gradRect = gradRect,
                            })
                        end
                    else
                        -- Honest, quiet empty state; no promotional badges.
                        local label = "Раздел пока не реализован"
                        local tw = tsize(label)
                        uiText(cardX + math.max(16,(cardW-tw)/2),cardY+cardH/2-18,
                            label,c4(TH.textDim))
                        local hint = "Выберите другой пункт в меню слева"
                        local hw = tsize(hint)
                        uiText(cardX + math.max(16,(cardW-hw)/2),cardY+cardH/2+8,
                            hint,c4(TH.textMuted),0.9)
                    end
                end
            end
            if endDepth > 0 then endDepth = endDepth - 1; pcall(im.End) end
            grndPopStyle(violetVars)
            grndPopCol(violetColors)
            grndPopStyle(3)
            grndPopCol(2)
            -- редактор наказания рисуется ПОСЛЕ меню -> окно поверх меню;
            -- живёт только пока открыто меню (ESC/M закрывают его первым).
            if menu.open and GRND_PUN and GRND_PUN.editId then
                local okEd, edRes = pcall(drawPunishEditor, dt)
                if not okEd then
                    -- громко: красное сообщение в чат/консоль + тост с ТЕКСТОМ
                    -- ошибки и строкой (traceback), иначе баг невидим
                    local tb = ""
                    if type(debug) == "table" and type(debug.traceback) == "function" then
                        local okT, t = pcall(debug.traceback, tostring(edRes), 2)
                        if okT and type(t) == "string" then
                            -- только первая значимая строка (где упало)
                            tb = t:match("\n%s*(.-)\n") or ""
                        end
                    end
                    logRenderErr("punish editor", tostring(edRes) .. " @" .. tostring(tb))
                    pcall(notify.add, "Ошибка окна наказаний: " .. tostring(edRes),
                        "error", 6)
                    GRND_PUN.editId, GRND_PUN.addCol = nil, nil
                elseif edRes then
                    wantCursor = true
                end
            end
            if (not menu.open) and GRND_PUN and GRND_PUN.editId then
                GRND_PUN.editId, GRND_PUN.addCol, GRND_PUN.focused = nil, nil, false
            end
            return wantCursor
        end
        local function argbToRgba(c)
            if type(c) ~= "number" or c == 0 then
                return rgba(220, 228, 220, 255)
            end
            c = math.floor(c) % 0x100000000
            local a = math.floor(c / 0x1000000) % 256
            local r = math.floor(c / 0x10000) % 256
            local g = math.floor(c / 0x100) % 256
            local b = c % 256
            if a == 0 then
                r = math.floor(c / 0x10000) % 256
                g = math.floor(c / 0x100) % 256
                b = c % 256
            end
            return rgba(r, g, b, 255)
        end
        local function getLocalSampId()
            if type(sampGetPlayerIdByCharHandle) == "function" then
                local ok, a, b = pcall(sampGetPlayerIdByCharHandle, PLAYER_PED)
                if ok then
                    if type(a) == "number" then return a end
                    if a and type(b) == "number" then return b end
                end
            end
            if type(sampGetLocalPlayerId) == "function" then
                local ok, lid = pcall(sampGetLocalPlayerId)
                if ok and type(lid) == "number" then return lid end
            end
            return nil
        end
        local function refreshScoreboard()
            local list, total = {}, 0
            local maxId = 999
            if type(sampGetMaxPlayerId) == "function" then
                local ok, m = pcall(sampGetMaxPlayerId)
                if ok and type(m) == "number" and m > 0 then maxId = m end
            end
            local loc = getLocalSampId()
            scoreboard.localId = loc or -1
            for id = 0, maxId do
                local connected = (loc ~= nil and id == loc)
                if not connected and type(sampIsPlayerConnected) == "function" then
                    local ok, r = pcall(sampIsPlayerConnected, id)
                    connected = ok and r
                elseif not connected and type(sampGetPlayerNickname) == "function" then
                    local ok, n = pcall(sampGetPlayerNickname, id)
                    connected = ok and type(n) == "string" and n ~= ""
                end
                if connected then
                    total = total + 1
                    local nick, score, ping, color, streamed = "?", 0, 0, 0, false
                    if type(sampGetPlayerNickname) == "function" then
                        local ok, n = pcall(sampGetPlayerNickname, id)
                        if ok and type(n) == "string" and n ~= "" then nick = n end
                    end
                    if type(sampGetPlayerScore) == "function" then
                        local ok, s = pcall(sampGetPlayerScore, id)
                        if ok and type(s) == "number" then score = s end
                    end
                    if type(sampGetPlayerPing) == "function" then
                        local ok, pg = pcall(sampGetPlayerPing, id)
                        if ok and type(pg) == "number" then ping = pg end
                    end
                    if type(sampGetPlayerColor) == "function" then
                        local ok, c = pcall(sampGetPlayerColor, id)
                        if ok and type(c) == "number" then color = c end
                    end
                    if type(sampGetCharHandleBySampPlayerId) == "function" then
                        local ok, found = pcall(function()
                            local f = sampGetCharHandleBySampPlayerId(id)
                            return f and true or false
                        end)
                        if ok and found then streamed = true end
                    elseif id == loc then
                        streamed = true
                    end
                    list[#list + 1] = {
                        id = id, nick = nick, utf = cp1251_to_utf8(nick),
                        score = score, ping = ping, color = color,
                        streamed = streamed, localp = (id == loc),
                    }
                end
            end
            table.sort(list, function(a, b)
                if a.localp ~= b.localp then return a.localp end
                return a.id < b.id
            end)
            local srv = ""
            if type(sampGetCurrentServerName) == "function" then
                local ok, n = pcall(sampGetCurrentServerName)
                if ok and type(n) == "string" then srv = cp1251_to_utf8(n) end
            end
            if srv == "" then srv = "GRND" end
            scoreboard.players = list
            scoreboard.total   = total
            scoreboard.server  = srv
            scoreboard.cacheT  = os.clock()
        end
        -- Прочитать именно ID ПЕРВОЙ строки нашего TAB, а не угадать ID
        -- по порядку подключения. Список пересобирается в момент клика,
        -- даже если TAB сейчас закрыт, поэтому ID не устаревает при релоге.
        function grndTabFirstLocalId()
            local ok = pcall(refreshScoreboard)
            if not ok then return nil end
            local first = scoreboard.players[1]
            local id = scoreboard.localId
            if not first or first.localp ~= true or type(id) ~= "number"
                or type(first.id) ~= "number" or first.id ~= id
                or id < 0 or id >= 1004 or id ~= math.floor(id) then
                return nil
            end
            -- Если клиент даёт оба источника ID, они должны совпасть:
            -- ошибка одного из них не должна выдать броню чужому игроку.
            if type(sampGetLocalPlayerId) == "function" then
                local okId, lid = pcall(sampGetLocalPlayerId)
                if okId and type(lid) == "number" and math.floor(lid) ~= id then
                    return nil
                end
            end
            return id
        end
        local function ensureSearchBuf()
            if scoreboard.buf then return end
            if im.new and im.new.char then
                local ok, buf = pcall(function() return im.new.char[128]() end)
                if ok and buf then
                    scoreboard.buf = buf
                    scoreboard.bufKind = "ffi"
                    return
                end
            end
            if im.ImBuffer then
                local ok, buf = pcall(im.ImBuffer, 128)
                if ok and buf then
                    scoreboard.buf = buf
                    scoreboard.bufKind = "imbuf"
                    return
                end
            end
            scoreboard.bufKind = "none"
        end
        local function readSearchBuf()
            if scoreboard.bufKind == "ffi" and scoreboard.buf then
                local ok, s = pcall(function()
                    local ffi = require "ffi"
                    return ffi.string(scoreboard.buf)
                end)
                if ok and type(s) == "string" then return s end
            elseif scoreboard.bufKind == "imbuf" and scoreboard.buf then
                local v = scoreboard.buf.v or scoreboard.buf
                if type(v) == "string" then return v end
                return tostring(v or "")
            end
            return scoreboard.search or ""
        end
        local function nickMatches(utf, q)
            if not q or q == "" then return true end
            utf = tostring(utf or "")
            q = tostring(q)
            local a, b = utf:lower(), q:lower()
            if a:find(b, 1, true) then return true end
            if utf:find(q, 1, true) then return true end
            return false
        end
        local SB_WIN_FLAGS = wf("NoTitleBar", "NoResize", "NoCollapse",
            "NoScrollbar", "NoMove", "NoScrollWithMouse")
        if wflag("NoNav") ~= 0 then
            SB_WIN_FLAGS = SB_WIN_FLAGS + wflag("NoNav")
        elseif wflag("NoNavInputs") ~= 0 then
            SB_WIN_FLAGS = SB_WIN_FLAGS + wflag("NoNavInputs")
        end
        local function drawScoreboard(dt)
            dt = dt or 0.016
            local speed = 14.0
            if GRND_TAB.open then
                scoreboard.anim = math.min(1, (scoreboard.anim or 0) + dt * speed)
            else
                scoreboard.anim = math.max(0, (scoreboard.anim or 0) - dt * speed)
            end
            if scoreboard.anim <= 0 then return false end

            if os.clock() - (scoreboard.cacheT or 0) > 0.35
               or #(scoreboard.players or {}) == 0 then
                pcall(refreshScoreboard)
            end

            local a = scoreboard.anim
            local resX, resY = getScreenResolution()
            local W = math.min(680, math.max(520, math.floor(resX * 0.48)))
            local H = math.min(640, math.max(380, math.floor(resY * 0.72)))
            local ROW = 22

            im.SetNextWindowPos(im.ImVec2(math.floor((resX - W) / 2),
                math.floor((resY - H) / 2)), COND_ALWAYS)
            im.SetNextWindowSize(im.ImVec2(W, H), COND_ALWAYS)

            grndPushStyleF(im.StyleVar and im.StyleVar.Alpha, a)
            grndPushStyleF(im.StyleVar and im.StyleVar.WindowRounding, 10)
            grndPushStyleV2(im.StyleVar and im.StyleVar.WindowPadding, 0, 0)
            grndPushCol(im.Col and im.Col.WindowBg, c4(TH.bg))
            grndPushCol(im.Col and im.Col.Border,   c4(TH.line))
            grndPushCol(im.Col and im.Col.Text,     c4(TH.textHi))

            local wantCursor = false
            if grndBegin("GRND Scoreboard##grnd_tab", SB_WIN_FLAGS) then
                wantCursor = GRND_TAB.open
                local pos = im.GetWindowPos()
                local dl  = im.GetWindowDrawList()
                local function at(dx, dy) return im.ImVec2(pos.x + dx, pos.y + dy) end

                pcall(dl.AddRect, dl, at(0.5, 0.5), at(W - 0.5, H - 0.5),
                    c32(TH.line), 10, 0, 1.4)
                -- # v1.19.09: акцентная полоска у верхней кромки убрана (просьба заказчика)

                local title = (scoreboard.server ~= "" and scoreboard.server) or "GRND"
                local tw = grndTextW(title)
                uiText((W - tw) / 2, 14, title, c4(TH.textHi))

                local countStr = "Игроков: " .. tostring(scoreboard.total or 0)
                uiText(18, 38, countStr, c4(TH.text))

                local sw, sh = 168, 24
                local sx, sy = W - 18 - sw, 34
                roundRect(dl, at(sx, sy), at(sx + sw, sy + sh), c32(TH.sidebar), 8)
                pcall(dl.AddRect, dl, at(sx, sy), at(sx + sw, sy + sh), c32(TH.line), 8)

                ensureSearchBuf()
                im.SetCursorPos(im.ImVec2(sx + 8, sy + 3))
                if im.PushItemWidth then pcall(im.PushItemWidth, sw - 16) end
                grndPushCol(im.Col and im.Col.FrameBg, rgba(0, 0, 0, 0))
                grndPushCol(im.Col and im.Col.FrameBgHovered, rgba(0, 0, 0, 0))
                grndPushCol(im.Col and im.Col.FrameBgActive, rgba(0, 0, 0, 0))
                grndPushCol(im.Col and im.Col.Text, rgba(230, 236, 230, 255))
                grndPushCol(im.Col and im.Col.Border, rgba(0, 0, 0, 0))
                if scoreboard.bufKind == "ffi" and scoreboard.buf then
                    if im.InputTextWithHint then
                        pcall(im.InputTextWithHint, "##grnd_sb_q", "Поиск", scoreboard.buf, 128)
                    elseif im.InputText then
                        pcall(im.InputText, "##grnd_sb_q", scoreboard.buf, 128)
                    end
                elseif scoreboard.bufKind == "imbuf" and scoreboard.buf then
                    if im.InputTextWithHint then
                        pcall(im.InputTextWithHint, "##grnd_sb_q", "Поиск", scoreboard.buf)
                    elseif im.InputText then
                        pcall(im.InputText, "##grnd_sb_q", scoreboard.buf)
                    end
                end
                grndPopCol(5)
                if im.PopItemWidth then pcall(im.PopItemWidth) end
                scoreboard.search = readSearchBuf()
                if (not scoreboard.search or scoreboard.search == "") then
                    if not im.InputTextWithHint or scoreboard.bufKind == "none" then
                        uiText(sx + 10, sy + 4, "Поиск", c4(TH.textMuted))
                    end
                end

                dl:AddRectFilled(at(14, 66), at(W - 14, 67), c32(TH.line))

                local colY = 72
                local xId, xNick = 18, 96
                local xLvl, xPing = W - 18 - 70 - 86, W - 18 - 70
                uiText(xId, colY, "ID", c4(TH.textMuted))
                uiText(xNick, colY, "Никнейм", c4(TH.textMuted))
                uiText(xLvl, colY, "Уровень", c4(TH.textMuted))
                uiText(xPing, colY, "Пинг", c4(TH.textMuted))

                local cb = 13
                local idw = grndTextW("ID")
                local cbx, cby = xId + idw + 6, colY + 2
                im.SetCursorPos(im.ImVec2(cbx, cby))
                if im.InvisibleButton("##grnd_sb_stream", im.ImVec2(cb, cb)) then
                    scoreboard.streamOnly = not scoreboard.streamOnly
                end
                local chov = (im.IsItemHovered and im.IsItemHovered()) or false
                local c1, c2 = at(cbx, cby), at(cbx + cb, cby + cb)
                local bcol = chov and c32(TH.text) or c32(TH.textMuted)
                pcall(dl.AddRect, dl, c1, c2, bcol, 2)
                if scoreboard.streamOnly then
                    roundRect(dl, at(cbx + 3, cby + 3), at(cbx + cb - 3, cby + cb - 3),
                        c32(TH.accent), 1)
                end

                dl:AddRectFilled(at(14, colY + 20), at(W - 14, colY + 21), c32(TH.line))

                local listY = colY + 26
                local footH = 22
                local listH = H - listY - footH - 8
                if listH < 40 then listH = 40 end
                im.SetCursorPos(im.ImVec2(8, listY))
                grndPushCol(im.Col and im.Col.ChildBg, rgba(0, 0, 0, 0))
                grndPushCol(im.Col and im.Col.ScrollbarBg,
                    rgba(TH.sidebar[1], TH.sidebar[2], TH.sidebar[3], 80))
                grndPushCol(im.Col and im.Col.ScrollbarGrab,
                    rgba(TH.accent[1], TH.accent[2], TH.accent[3], 160))
                local useChild = type(im.BeginChild) == "function"
                if useChild then
                    local ok, res = pcall(im.BeginChild, "##grnd_sb_list",
                        im.ImVec2(W - 16, listH), false)
                    useChild = ok and (res ~= false)
                end
                do
                    local q = scoreboard.search or ""
                    local row = 0
                    local cdl = useChild and im.GetWindowDrawList() or dl
                    for i = 1, #(scoreboard.players or {}) do
                        local pl = scoreboard.players[i]
                        if (not scoreboard.streamOnly or pl.streamed or pl.localp)
                            and nickMatches(pl.utf, q)
                        then
                            local ry = row * ROW
                            if useChild then im.SetCursorPos(im.ImVec2(0, ry))
                            else im.SetCursorPos(im.ImVec2(8, listY + ry)) end
                            if im.InvisibleButton("##grnd_sb_row_" .. pl.id,
                                im.ImVec2(W - 24, ROW)) then
                                if not pl.localp then
                                    GRND_TAB.specId = pl.id
                                    GRND_TAB.open = false
                                end
                            end
                            local hovered = (im.IsItemHovered and im.IsItemHovered()) or false
                            if hovered then
                                local p1, p2 = im.GetItemRectMin(), im.GetItemRectMax()
                                cdl:AddRectFilled(p1, p2, pl.localp
                                    and col32(255, 255, 255, 10)
                                    or col32(TH.accent[1], TH.accent[2], TH.accent[3], 28))
                            end
                            local tx = useChild and (xId - 8) or xId
                            local nx = useChild and (xNick - 8) or xNick
                            local lx = useChild and (xLvl - 8) or xLvl
                            local px = useChild and (xPing - 8) or xPing
                            local ty = useChild and (ry + 3) or (listY + ry + 3)
                            uiText(tx, ty, tostring(pl.id), c4(TH.text))
                            uiText(nx, ty, pl.utf, argbToRgba(pl.color))
                            uiText(lx, ty, tostring(pl.score), c4(TH.text))
                            uiText(px, ty, tostring(pl.ping), c4(TH.text))
                            row = row + 1
                        end
                    end
                    if row == 0 then
                        local empty = "Нет игроков"
                        local ew = grndTextW(empty)
                        local ey = useChild and 20 or (listY + 20)
                        uiText((W - 16 - ew) / 2, ey, empty, c4(TH.textMuted))
                    end
                    if useChild then
                        if type(im.EndChild) == "function" then pcall(im.EndChild)
                        else pcall(im.End) end
                    end
                end
                grndPopCol(3)

                local hint = "ЛКМ — слежка (/sp)   TAB / ESC — закрыть"
                local hw = grndTextW(hint)
                uiText((W - hw) / 2, H - 20, hint, c4(TH.textMuted))
            end
            if endDepth > 0 then endDepth = endDepth - 1; pcall(im.End) end
            grndPopCol(3)
            grndPopStyle(3)
            return wantCursor
        end

        -- =================================================================
        --  v1.7.0: ЗДЕСЬ БЫЛ КАСТОМНЫЙ ЧАТ — окно сообщений (история, цвета
        --  строк, префиксы, намотка, время, скроллбар), своя строка ввода,
        --  окно «Настройки чата» и шестерёнка. Модуль удалён ЦЕЛИКОМ: чат
        --  снова рисует сам клиент SA-MP, а скрипт не перехватывает ни T/F6,
        --  ни колесо мыши, ни PgUp/PgDn.
        --  Общий шрифт интерфейса переехал в GRND_FONT (см. начало файла),
        --  его конфиг — grnd_ui.cfg (grndUiCfgLoad / grndUiCfgSave), выбор
        --  шрифта — кнопками < > в чекере «Новый Kill List».
        -- =================================================================
        -- =================================================================
        --  ОКНО СТАТУСА АВТОРИЗАЦИИ (оставлено, но не вызывается)
        -- =================================================================
        local function authPanel()
            if not (AUTH.panelOpen and not AUTH.spawned) then return end
            local W = 330
            local H = 76
            if im.SetNextWindowBgAlpha then im.SetNextWindowBgAlpha(0) end
            im.SetNextWindowPos(im.ImVec2(8, 8), COND_ALWAYS)
            im.SetNextWindowSize(im.ImVec2(W, H), COND_ALWAYS)
            local flags = wf("NoTitleBar", "NoResize", "NoMove", "NoScrollbar",
                "NoCollapse", "NoInputs")
            if not grndBeginTransparent("##grnd_auth_panel", flags) then return end
            local dl = im.GetWindowDrawList()
            local wp = im.GetWindowPos()
            roundRect(dl, wp, im.ImVec2(wp.x + W, wp.y + H), col32(14, 17, 22, 214), 8)
            roundRect(dl, wp, im.ImVec2(wp.x + 3, wp.y + H),
                AUTH.showedAuthOk and col32(76, 209, 79, 255) or col32(45, 156, 219, 255), 8)
            local s1 = "GRND TOOLS 1.1"
            local s2 = AUTH.showedAuthOk and "Авторизация: успешна"
                or (AUTH.dialog and "Окно авторизации открыто — введите пароль"
                    or (AUTH.attemptFailed and "Пароль неверный — ждём новое окно"
                        or "Ждём окно авторизации (диалог не пойман)"))
            local s3 = "ImGui: " .. (IMGUI_WRAP or "?")
                .. "   рендер: " .. (renderedOnce and "идёт" or "СТОП")
            uiText(14, 8, s1, c4(TH.accent), 1.05)
            uiText(14, 30, s2, c4(AUTH.showedAuthOk and TH.textHi or TH.text))
            uiText(14, 50, s3, c4(TH.textMuted), 0.9)
            if endDepth > 0 then endDepth = endDepth - 1; pcall(im.End) end
        end
        -- =============================================================
        --  REPORT v0.2 — вариант «Мессенджер»: аватар + ник + ID, справа
        --  иконки «Слежка» (глаз) и «Телепорт» (бегущий человечек),
        --  поле ответа с приклеенной кнопкой «Ответить», шаблоны — чипы.
        --  Иконки рисуются DrawList'ом (линии/круги), без шрифтов-иконок.
        -- =============================================================
        local function grndRepSplitLines(s, maxW, maxLines)
            local lines, cur = {}, ""
            for word in tostring(s or ""):gmatch("%S+") do
                local try = (cur == "") and word or (cur .. " " .. word)
                if grndTextW(try) <= maxW or cur == "" then
                    cur = try
                else
                    lines[#lines + 1] = cur
                    cur = word
                    if #lines >= maxLines then break end
                end
            end
            if #lines < maxLines and cur ~= "" then lines[#lines + 1] = cur end
            if #lines >= maxLines then
                -- обрезаем последнюю строку с многоточием, если текст длиннее
                local last = lines[maxLines]
                local full = table.concat(lines, " ")
                if #full < #tostring(s or "") then
                    while #last > 1 and grndTextW(last .. "…") > maxW do
                        last = last:sub(1, -2)
                    end
                    lines[maxLines] = last .. "…"
                end
            end
            if #lines == 0 then lines[1] = "" end
            return lines
        end

        -- Иконка «глаз» (слежка). cx,cy — центр в экранных координатах.
        local function grndRepIconEye(dl, cx, cy, col)
            local w, h = 8, 4.5
            local seg = 8
            local pts = {}
            -- верхняя дуга
            for i = 0, seg do
                local t = i / seg
                local x = cx - w + 2 * w * t
                local y = cy - h * math.sin(t * math.pi)
                dl:AddLine(im.ImVec2(pts.x or x, pts.y or y), im.ImVec2(x, y), col, 1.6)
                pts.x, pts.y = x, y
            end
            pts = {}
            for i = 0, seg do
                local t = i / seg
                local x = cx - w + 2 * w * t
                local y = cy + h * math.sin(t * math.pi)
                dl:AddLine(im.ImVec2(pts.x or x, pts.y or y), im.ImVec2(x, y), col, 1.6)
                pts.x, pts.y = x, y
            end
            dl:AddCircleFilled(im.ImVec2(cx, cy), 2.4, col, 12)
        end

        -- Иконка «бегущий человечек» (телепорт).
        local function grndRepIconRun(dl, cx, cy, col)
            local function L(x1, y1, x2, y2)
                dl:AddLine(im.ImVec2(cx + x1, cy + y1), im.ImVec2(cx + x2, cy + y2), col, 1.7)
            end
            dl:AddCircleFilled(im.ImVec2(cx + 3, cy - 7), 2.0, col, 12) -- голова
            L(1, -4, -1, 1)          -- туловище
            L(1, -4, 5, -2)          -- рука вперёд
            L(5, -2, 7, 1)
            L(1, -4, -3, -5)         -- рука назад
            L(-3, -5, -6, -3)
            L(-1, 1, 3, 3)           -- нога вперёд
            L(3, 3, 3, 7)
            L(-1, 1, -4, 4)          -- нога назад
            L(-4, 4, -7, 3)
        end

        -- Иконка «судейский молоток» (наказания).
        local function grndRepIconGavel(dl, cx, cy, col)
            local function L(x1, y1, x2, y2, th)
                dl:AddLine(im.ImVec2(cx + x1, cy + y1), im.ImVec2(cx + x2, cy + y2), col, th)
            end
            -- головка молотка (под углом 45°, перпендикулярно рукоятке)
            L(-5.5, 1.5, 3.0, -6.0, 3.4)
            -- рукоятка
            L(0.0, 0.0, 5.0, 5.0, 2.0)
            -- звуковая подставка (наковаленка)
            L(-6.5, 7.0, 4.5, 7.0, 1.8)
        end

        -- =================================================================
        --  КНОПКА «Наказания игрока» — /getinfo ID без показа окна.
        --
        --  По нажатию скрипт шлёт /getinfo ID: сервер открывает окно
        --  «Активные наказания игрока». Окно перехватывается в
        --  sampev.onShowDialog и НЕ показывается игроку (return false),
        --  а его содержимое уходит ответом игроку:
        --    * пусто  -> «Приветствую, активных наказаний у вас нет.»
        --    * список -> «Приветствую, ваши активные наказания >> …»
        --  Первая строка окна («Аккаунт Ник[ID] …») отбрасывается.
        --
        --  Сама механика живёт в модуле быстрых ответов (QR.punBegin /
        --  QR.punFinish): её же использует переменная {punishments} у
        --  автопилота, который работает и с закрытым окном репорта.
        -- =================================================================

        -- Ширина текста ТЕМ ЖЕ масштабом, каким uiText его нарисует.
        -- Тонкость: uiText применяет масштаб только через SetWindowFontScale —
        -- если его в обёртке нет, текст рисуется в полный кегль, и измерять
        -- надо так же, иначе подпись вылезает за кнопку.
        -- Возвращает: ширину, ФАКТИЧЕСКИЙ масштаб (его же надо передать в отрисовку).
        GRND_REP.measureW = function(s, scale)
            local canScale = (type(im.SetWindowFontScale) == "function")
            local use = (canScale and scale) or 1
            if type(im.CalcTextSize) == "function" then
                if canScale and use ~= 1 then pcall(im.SetWindowFontScale, use) end
                local ok, a = pcall(im.CalcTextSize, tostring(s))
                if canScale and use ~= 1 then pcall(im.SetWindowFontScale, 1) end
                if ok then
                    local ta = type(a)
                    local w = (ta == "table" or ta == "cdata") and tonumber(a.x) or tonumber(a)
                    if w and w > 0 then return w, use end
                end
            end
            return grndTextW(s) * use, use
        end

        -- =================================================================
        --  КНОПКА «Следить за Nick» под текстом репорта.
        --
        --  Если в содержимом репорта распознан игрок (ник и/или ID 0..1000),
        --  под блоком сообщения появляется кнопка слежки.
        --
        --  Правила выбора цели:
        --    * в тексте есть ник и ID («Ник[ID]») — цель НИК, ID запасной;
        --    * в тексте только ник — цель ник;
        --    * в тексте только ID — цель ID.
        --
        --  Ответы уходят игроку через /ans ID текст (grndRepAnswer).
        --
        --  Всё оформлено полями таблицы GRND_REP (а не локальными
        --  переменными): grndMainBody уже близок к лимиту Lua в 200
        --  локальных переменных на функцию.
        -- =================================================================

        -- Ник игрока по ID (UTF-8). fallback — если прочитать не удалось.
        GRND_REP.nickOf = function(id, fallback)
            if type(sampGetPlayerNickname) == "function" then
                local ok, nm = pcall(sampGetPlayerNickname, id)
                if ok and type(nm) == "string" and nm ~= "" then
                    return grndToUtf(nm)
                end
            end
            return tostring(fallback or ("ID " .. tostring(id)))
        end

        -- Подпись «Ник[ID]» — для текста ответа игроку.
        GRND_REP.labelOf = function(id, nick)
            return tostring(nick) .. "[" .. tostring(id) .. "]"
        end

        -- Карта онлайн-игроков: «ник в нижнем регистре» -> ID.
        -- Строится ОДНИМ проходом по списку игроков и живёт 1 секунду,
        -- чтобы окно репорта (перерисовка каждый кадр) не сканировало
        -- список игроков постоянно.
        GRND_REP.onlineMap = function()
            local now = os.clock()
            local C = GRND_REP.onlineCache
            if C and C.at and (now - C.at) < 1.0 then return C.map end
            local map = {}
            if type(sampIsPlayerConnected) == "function"
                and type(sampGetPlayerNickname) == "function" then
                for id = 0, 1003 do
                    local okC, on = pcall(sampIsPlayerConnected, id)
                    if okC and (on == true or on == 1) then
                        local okN, nm = pcall(sampGetPlayerNickname, id)
                        if okN and type(nm) == "string" and nm ~= "" then
                            map[string.lower(grndToUtf(nm))] = id
                        end
                    end
                end
            end
            GRND_REP.onlineCache = { at = now, map = map }
            return map
        end

        -- Разбор цели БЕЗ кэша. Возвращает таблицу:
        --   { id = ID|nil, label = "Ник"|"ID 5"|nil, source = "nick"|"id"|nil }
        -- id не nil только если игрок реально в сети (слежка возможна).
        -- Если id == nil, но label ~= nil — цель распознана, но игрока
        -- нет в сети (кнопка всё равно показывается: уйдёт ответ игроку).
        GRND_REP.parseTargetRaw = function(text)
            local s = tostring(text or "")
            -- Токен, похожий на ник: латиница/цифры/подчёркивание/точка/дефис
            -- (плюс квадратные скобки — бывают теги вида Nick[GP]).
            local NICK_TOK = "[A-Za-z0-9_%.%-%[%]]+"
            -- Частые английские словечки из текста репорта — не ники.
            local STOP = {
                admin = true, admins = true, adminka = true, help = true, ping = true,
                afk = true, lag = true, cheat = true, cheater = true, dm = true,
                deathmatch = true, pvp = true, rp = true, gm = true, vip = true,
                http = true, https = true, www = true, com = true, net = true,
                samp = true, grand = true, mob = true, car = true, bike = true,
            }

            -- 1) «Ник[ID]» или «Ник (ID)»: цель — НИК, ID — запасной вариант
            --    (если ник не нашёлся в онлайне, но игрок с таким ID в сети).
            local nick, idStr = s:match("(" .. NICK_TOK .. ")%s*%[(%d+)%]")
            if not nick then
                nick, idStr = s:match("(%a[%w_%.%-]+)%s*%((%d+)%)")
            end
            if nick and idStr then
                local nid = tonumber(idStr)
                if nid and nid >= 0 and nid <= 1000 then
                    local byNick = GRND_REP.onlineMap()[string.lower(nick)]
                    if byNick and specConnected(byNick) then
                        return { id = byNick, label = GRND_REP.nickOf(byNick, nick), source = "nick" }
                    end
                    if specConnected(nid) then
                        return { id = nid, label = GRND_REP.nickOf(nid, nick), source = "nick" }
                    end
                    return { id = nil, label = nick, source = "nick" }
                end
            end

            -- 2) Отдельно стоящее число (ID). Числа из «Ник[ID]» исключаем.
            local s2 = s:gsub(NICK_TOK .. "%s*%[%d+%]", " ")
            for num in s2:gmatch("%d+") do
                local nid = tonumber(num)
                if nid and nid >= 0 and nid <= 1000 then
                    if specConnected(nid) then
                        return { id = nid, label = GRND_REP.nickOf(nid), source = "id" }
                    end
                    return { id = nil, label = "ID " .. tostring(nid), source = "id" }
                end
            end

            -- 3) Только ник. Сначала — совпадение с игроком в сети,
            --    затем «сильный» кандидат (с подчёркиванием), затем
            --    единственный кандидат в тексте.
            local cands, seen = {}, {}
            for tok in s:gmatch(NICK_TOK) do
                local t = tok
                -- Снимаем ТОЛЬКО внешние скобки-обёртку: «[GP]Nick» -> «Nick».
                -- Внутренние скобки не трогаем — это часть ника с тегом.
                if t:sub(1, 1) == "[" and t:sub(-1) == "]" then t = t:sub(2, -2) end
                if #t >= 3 and #t <= 24 and not tonumber(t) then
                    local key = string.lower(t)
                    if not seen[key] and not STOP[key] then
                        seen[key] = true
                        cands[#cands + 1] = t
                    end
                end
            end
            if #cands > 0 then
                local map = GRND_REP.onlineMap()
                table.sort(cands, function(a, b) return #a > #b end)
                for _, t in ipairs(cands) do
                    -- Сначала полный токен, затем — имя без тега («Nick» из «Nick[GP]»).
                    local base = t:match("^([^%[]+)%[")
                    local variants = (base and base ~= t) and { t, base } or { t }
                    for _, v in ipairs(variants) do
                        local fid = map[string.lower(v)]
                        if fid and specConnected(fid) then
                            return { id = fid, label = GRND_REP.nickOf(fid, v), source = "nick" }
                        end
                    end
                end
                for _, t in ipairs(cands) do
                    if t:find("_", 1, true) then
                        return { id = nil, label = t, source = "nick" }
                    end
                end
                if #cands == 1 and #cands[1] >= 4 then
                    return { id = nil, label = cands[1], source = "nick" }
                end
            end

            return { id = nil, label = nil, source = nil }
        end

        -- Кэш разбора цели: окно перерисовывается каждый кадр, а разбор
        -- (для ников) сканирует список игроков. Ключ — текст репорта.
        GRND_REP.parseTarget = function(text)
            local key = tostring(text or "")
            local now = os.clock()
            local C = GRND_REP.tgtCache
            if C and C.key == key and (now - C.at) < 0.5 then return C end
            local res = GRND_REP.parseTargetRaw(key)
            res.key, res.at = key, now
            GRND_REP.tgtCache = res
            return res
        end

        local function drawReportWindow()
            if not GRND_REP.open then return false end
            grndRepEnsureBuffer()

            local resX, resY = getScreenResolution()
            local W = 600
            local PAD = 16
            -- вычисляем высоту под кол-во строк сообщения (1..2)
            local question = tostring(GRND_REP.question or "текст репорта")
            local qLines = grndRepSplitLines(question, W - PAD * 2 - 24, 2)
            local lineH = 17
            local msgH = 14 + #qLines * lineH
            local yWho, yMsg = 44, 44 + 38

            -- Цель из текста репорта — для кнопки «Следить за Ник[ID]».
            -- Разбор кэшируется (окно рисуется каждый кадр).
            local tgt = GRND_REP.parseTarget(question)
            local followRow = 0    -- высота строки кнопки слежки (0 — её нет)
            if tgt.label then followRow = 30 + 9 end
            local yFollow = yMsg + msgH + 9
            local yInput = yFollow + followRow
            local yChips = yInput + 30 + 9
            local H = yChips + 28 + 12
            local winX = math.floor((resX - W) / 2)
            local winY = math.floor((resY - H) / 2)
            im.SetNextWindowPos(im.ImVec2(winX, winY), COND_ALWAYS)
            im.SetNextWindowSize(im.ImVec2(W, H), COND_ALWAYS)
            -- v1.19.10/v1.19.11: запоминаем габариты окна — по ним выравнивается
            -- полоса шаблонов («Быстрые ответы»): открывается вровень с окном
            -- репорта (левый край по левому краю, верхняя кромка сразу под
            -- нижней кромкой), а не «сама по себе» по центру экрана.
            GRND_REP.winX, GRND_REP.winW = winX, W
            GRND_REP.winY, GRND_REP.winH = winY, H

            local styleN, colorN = 0, 0
            if grndPushStyleF(im.StyleVar and im.StyleVar.WindowRounding, 10) then styleN = styleN + 1 end
            if grndPushStyleF(im.StyleVar and im.StyleVar.FrameRounding, 6) then styleN = styleN + 1 end
            if grndPushStyleV2(im.StyleVar and im.StyleVar.WindowPadding, 0, 0) then styleN = styleN + 1 end
            if grndPushCol(im.Col and im.Col.WindowBg, rgba(0, 0, 0, 0)) then colorN = colorN + 1 end

            local flags = wf("NoTitleBar", "NoResize", "NoMove", "NoCollapse",
                "NoScrollbar", "NoScrollWithMouse")
            local wantCursor = false
            local pendingClose = false
            if grndBegin("##grnd_report", flags) then
                wantCursor = true
                local pos = im.GetWindowPos()
                local dl = im.GetWindowDrawList()
                local function at(x, y) return im.ImVec2(pos.x + x, pos.y + y) end
                local function text(x, y, value, col, scale)
                    uiText(x, y, value, col or c4(TH.textHi), scale)
                end
                local function box(x, y, w, h, col, rounding)
                    roundRect(dl, at(x, y), at(x + w, y + h), col, rounding or 3)
                end
                local function frame(x, y, w, h, col, rounding)
                    if dl.AddRect then
                        pcall(dl.AddRect, dl, at(x, y), at(x + w, y + h), col, rounding or 3, 0, 1.0)
                    end
                end
                local function tooltip(label)
                    if type(im.SetTooltip) == "function" then pcall(im.SetTooltip, label) end
                end

                local pid = tostring(GRND_REP.playerId or "?")
                local hasId = pid:match("^%d+$") ~= nil

                -- фон, градиентная полоса, шапка
                box(0, 0, W, H, c32(TH.bg), 10)
                frame(0, 0, W, H, col32(255, 255, 255, 14), 10)
                -- # v1.19.09: акцентная полоска у верхней кромки убрана (просьба заказчика)
                box(0, 3, W, 31, c32(TH.sidebar), 0)
                box(0, 34, W, 1, c32(TH.line), 0)
                text(PAD, 10, "Репорт", c4(TH.textHi), 1.06)
                local sub
                if GRND_REP.sourceCaption == "catch" then
                    sub = "автоловля · обращение игрока"
                    if GRND_REP.reportCount then sub = sub .. " · репортов: " .. tostring(GRND_REP.reportCount) end
                elseif GRND_REP.dialogId and GRND_REP.dialogId >= 0 then
                    sub = "обращение игрока · окно сервера #" .. tostring(GRND_REP.dialogId)
                elseif GRND_REP.sourceCaption == "hud" then
                    sub = "из оверлея репортов"
                else
                    sub = "обращение игрока"
                end
                text(PAD + 66, 12, sub, c4(TH.textMuted), 0.8)

                -- закрыть
                im.SetCursorPos(im.ImVec2(W - 38, 8))
                local closeClicked = im.InvisibleButton("##grnd_rep_close", im.ImVec2(26, 22))
                local closeHovered = im.IsItemHovered and im.IsItemHovered() or false
                if closeHovered then box(W - 38, 8, 26, 22, col32(255, 255, 255, 14), 5) end
                text(W - 31, 9, "×", closeHovered and c4(TH.textHi) or c4(TH.textDim), 1.05)
                if closeClicked then pendingClose = true end

                -- ---------- строка «кто» ----------
                local author = tostring(GRND_REP.author or "Игрок")
                -- аватар с инициалами
                local ini = ""
                for part in author:gmatch("[^_%s%.%-]+") do
                    local ch = part:match("^[%z\1-\127\194-\244][\128-\191]*")
                    if ch then ini = ini .. ch:upper() end
                    if grndUtf8Len(ini) >= 2 then break end
                end
                if ini == "" then ini = "?" end
                box(PAD, yWho, 30, 30, col32(TH.accent[1], TH.accent[2], TH.accent[3], 34), 8)
                frame(PAD, yWho, 30, 30, col32(TH.accent[1], TH.accent[2], TH.accent[3], 90), 8)
                local iniW = grndTextW(ini) * 0.82
                text(PAD + math.max(2, (30 - iniW) / 2), yWho + 7, ini, c4(TH.accent), 0.82)

                text(PAD + 40, yWho - 1, author, c4(TH.textHi), 1.0)
                text(PAD + 40, yWho + 16, "ID " .. pid .. "  ·  игрок", c4(TH.textMuted), 0.78)

                -- иконки действий (справа): слежка и телепорт
                local function iconBtn(id, x, w, label, accent, drawIcon, enabled, lscale)
                    im.SetCursorPos(im.ImVec2(x, yWho + 2))
                    local clicked = im.InvisibleButton(id, im.ImVec2(w, 26))
                    local hovered = im.IsItemHovered and im.IsItemHovered() or false
                    local active = im.IsItemActive and im.IsItemActive() or false
                    local a = accent
                    local bg, bd, fg
                    if not enabled then
                        bg, bd = col32(255, 255, 255, 5), col32(255, 255, 255, 10)
                        fg = col32(TH.textMuted[1], TH.textMuted[2], TH.textMuted[3], 255)
                    elseif active then
                        bg, bd, fg = col32(a[1], a[2], a[3], 70), col32(a[1], a[2], a[3], 220), c32(a)
                    elseif hovered then
                        bg, bd, fg = col32(a[1], a[2], a[3], 40), col32(a[1], a[2], a[3], 160), c32(a)
                    else
                        bg, bd = col32(255, 255, 255, 11), col32(255, 255, 255, 22)
                        fg = c32(TH.text)
                    end
                    box(x, yWho + 2, w, 26, bg, 6)
                    frame(x, yWho + 2, w, 26, bd, 6)
                    drawIcon(dl, pos.x + x + 16, pos.y + yWho + 15, fg)
                    local tcol = enabled and ((hovered or active) and c4(a) or c4(TH.text)) or c4(TH.textMuted)
                    text(x + 30, yWho + 6, label, tcol, lscale or 0.84)
                    return clicked and enabled, hovered
                end
                local wTp = 30 + grndTextW("Телепорт") * 0.84 + 12
                local wSp = 30 + grndTextW("Слежка") * 0.84 + 12
                local xTp = W - PAD - wTp
                local xSp = xTp - 6 - wSp
                -- Кнопка «Наказания игрока» — первая в ряду действий: шлёт
                -- /getinfo ID, читает окно «Активные наказания игрока» и
                -- отвечает игроку (окно игроку не показывается).
                local punLabel, punScale = "Наказания игрока", 0.84
                -- ширина считается ТЕМ ЖЕ масштабом, каким подпись рисуется
                -- (если обёртка не умеет SetWindowFontScale — в полный кегль)
                local punW, punDrawScale = 30 + select(1, GRND_REP.measureW(punLabel, punScale)) + 12,
                    select(2, GRND_REP.measureW(punLabel, punScale))
                -- не даём ряду кнопок наехать на имя игрока слева
                local punMinX = PAD + 40 + GRND_REP.measureW(author, 1) + 6
                local xPn = xSp - 6 - punW
                if xPn < punMinX then
                    punLabel = "Наказания"
                    local w1, sc1 = GRND_REP.measureW(punLabel, punScale)
                    punW, punDrawScale = 30 + w1 + 12, sc1
                    xPn = xSp - 6 - punW
                end
                if xPn < punMinX then
                    punScale = 0.72
                    local w2, sc2 = GRND_REP.measureW(punLabel, punScale)
                    punW, punDrawScale = 30 + w2 + 12, sc2
                    xPn = xSp - 6 - punW
                end
                if xPn < punMinX then
                    -- мало места — оставляем только молоток (подпись в тултипе)
                    punLabel = ""
                    local w3, sc3 = GRND_REP.measureW(punLabel, 1)
                    punW, punDrawScale = 30 + w3 + 12, sc3
                    xPn = xSp - 6 - punW
                end
                local punShow = true
                if xPn < punMinX then
                    -- места не хватает даже для иконки: не рисуем кнопку,
                    -- чтобы не наехать на «Слежку» и на имя игрока
                    punShow = false
                end
                local wPn = punShow and math.max(42, xSp - 6 - xPn) or 0
                if not punShow then xPn = xSp end
                local pnClick, pnHover = false, false
                if punShow then
                    pnClick, pnHover = iconBtn("##grnd_rep_pun", xPn, wPn, punLabel,
                        TH.accent, grndRepIconGavel, hasId, punDrawScale)
                end
                if pnHover then
                    tooltip(hasId and ("Активные наказания игрока (/getinfo " .. pid .. ")")
                        or "ID игрока не распознан")
                end
                if pnClick then
                    GRND_REP.lastAction = "punish"
                    -- Запоминаем, кого спрашиваем: окно придёт асинхронно, а
                    -- запрос уходит сразу, минуя очередь (других команд в
                    -- этом кадре нет). Окно репорта закрываем в конце этого
                    -- же кадра: ответ игроку уйдёт после чтения /getinfo.
                    if QR.punBeginManual(pid, author) then pendingClose = true end
                end
                local spClick, spHover = iconBtn("##grnd_rep_spec", xSp, wSp, "Слежка", TH.accent, grndRepIconEye, hasId)
                local tpClick, tpHover = iconBtn("##grnd_rep_tp", xTp, wTp, "Телепорт", TH.accent2, grndRepIconRun, hasId)
                if spHover then tooltip(hasId and ("Слежка за игроком (/sp " .. pid .. ")") or "ID игрока не распознан") end
                if tpHover then tooltip(hasId and ("Телепорт к игроку ID " .. pid) or "ID игрока не распознан") end
                if spClick then
                    GRND_REP.lastAction = "spectate"
                    -- 1) ответ игроку, 2) слежка (тот же путь, что клик по
                    -- нику в TAB: основной цикл отправит «/sp ID» и подключит
                    -- трекер слежки).
                    grndRepAnswer(pid, "Приветствую, слежу за вами.")
                    if GRND_TAB then GRND_TAB.specId = tonumber(pid) end
                    pendingClose = true
                end
                if tpClick then
                    GRND_REP.lastAction = "teleport"
                    -- 1) ответ игроку, 2) телепорт /goto ID
                    grndRepAnswer(pid, "Приветствую, лечу на помощь!")
                    local cmd = GRND_REP.tpCommand
                    if type(cmd) ~= "string" or cmd == "" then cmd = "/goto %d" end
                    local full = cmd:find("%%d") and string.format(cmd, tonumber(pid)) or (cmd .. " " .. pid)
                    grndRepQueue(full)
                    pendingClose = true
                end

                -- ---------- сообщение ----------
                box(PAD, yMsg, W - PAD * 2, msgH, col32(10, 13, 20, 255), 7)
                frame(PAD, yMsg, W - PAD * 2, msgH, col32(255, 255, 255, 16), 7)
                box(PAD, yMsg + 6, 2, msgH - 12, c32(TH.accent), 1)
                for i, ln in ipairs(qLines) do
                    text(PAD + 12, yMsg + 7 + (i - 1) * lineH, ln, c4(TH.text), 0.92)
                end

                -- ---------- кнопка «Следить за Ник» ----------
                -- Показывается, только если в тексте репорта распознан игрок
                -- (ник и/или ID). Компактная — по ширине надписи.
                local followClicked, followHover = false, false
                if tgt.label then
                    local fbLabel = "Следить за " .. tostring(tgt.label)
                    local fbX, fbY, fbH = PAD, yFollow, 30

                    -- Ширина надписи ТЕМ ЖЕ масштабом, каким она будет
                    -- нарисована. Тонкость: uiText применяет масштаб только
                    -- через SetWindowFontScale — если его в обёртке нет,
                    -- текст рисуется в полный кегль, и тогда измерять надо
                    -- без масштаба, иначе подпись вылезает за кнопку.
                    local function fbTextW(s, scale) return GRND_REP.measureW(s, scale) end
                    -- Обрезка надписи по ширине (без разрыва UTF-8-символов).
                    local function fbFit(s, maxW, scale)
                        if fbTextW(s, scale) <= maxW then return s end
                        local out = ""
                        for ch in s:gmatch("[%z\1-\127\194-\244][\128-\191]*") do
                            if fbTextW(out .. ch .. "…", scale) > maxW then break end
                            out = out .. ch
                        end
                        if out == "" then return "…" end
                        return out .. "…"
                    end

                    local fbPadL, fbPadR = 32, 16   -- слева место под иконку, справа отступ
                    local fbMaxW = W - PAD * 2
                    local fbScale = 0.9
                    local fbTw, fbDrawScale = fbTextW(fbLabel, fbScale)
                    -- ceil, а не floor: дробная часть не должна съедать правый отступ
                    local fbW = math.ceil(fbPadL + fbTw + fbPadR)
                    if fbW < 132 then fbW = 132 end        -- не меньше 132 px
                    if fbW > fbMaxW then
                        -- надпись длиннее окна: сначала уменьшаем кегль
                        local avail = fbMaxW - fbPadL - fbPadR
                        fbScale = fbScale * (avail / math.max(1, fbTw))
                        if fbScale < 0.7 then fbScale = 0.7 end
                        fbTw, fbDrawScale = fbTextW(fbLabel, fbScale)
                        if fbPadL + fbTw + fbPadR > fbMaxW then
                            -- и только в крайнем случае обрезаем с «…»
                            fbLabel = fbFit(fbLabel, avail, fbDrawScale)
                            fbTw, fbDrawScale = fbTextW(fbLabel, fbScale)
                        end
                        fbW = math.min(fbMaxW, math.ceil(fbPadL + fbTw + fbPadR))
                    end

                    local online = (tgt.id ~= nil) and specConnected(tgt.id)
                    im.SetCursorPos(im.ImVec2(fbX, fbY))
                    followClicked = im.InvisibleButton("##grnd_rep_follow", im.ImVec2(fbW, fbH))
                    followHover = im.IsItemHovered and im.IsItemHovered() or false
                    local fbAct = im.IsItemActive and im.IsItemActive() or false
                    -- Цвет кнопки: акцент — игрок в сети, приглушённый — офлайн.
                    local aR, aG, aB = TH.accent[1], TH.accent[2], TH.accent[3]
                    if not online then aR, aG, aB = TH.textMuted[1], TH.textMuted[2], TH.textMuted[3] end
                    local bg, bd
                    if fbAct then
                        bg, bd = col32(aR, aG, aB, 60), col32(aR, aG, aB, 220)
                    elseif followHover then
                        bg, bd = col32(aR, aG, aB, 34), col32(aR, aG, aB, 160)
                    else
                        bg, bd = col32(aR, aG, aB, 14), col32(aR, aG, aB, 70)
                    end
                    box(fbX, fbY, fbW, fbH, bg, 6)
                    frame(fbX, fbY, fbW, fbH, bd, 6)
                    -- иконка «глаз» слева
                    grndRepIconEye(dl, pos.x + fbX + 16, pos.y + fbY + fbH / 2,
                        c32({ aR, aG, aB }))
                    text(fbX + fbPadL, fbY + math.floor((fbH - 14 * fbDrawScale) / 2), fbLabel,
                        c4(online and TH.textHi or TH.text), fbDrawScale)
                    if followHover then
                        if online then
                            tooltip("Следить за " .. tostring(tgt.label)
                                .. ": ответ игроку и запуск слежки (/sp " .. tostring(tgt.id) .. ")")
                        else
                            tooltip("Игрок не в сети: игроку уйдёт ответ "
                                .. (tgt.source == "nick" and "о проверке никнейма" or "о проверке ID"))
                        end
                    end
                end
                if followClicked then
                    if tgt.id and specConnected(tgt.id) then
                        -- Игрок в сети: 1) ответ игроку, 2) слежка.
                        local msg = "Приветствую, слежу за игроком >> "
                            .. GRND_REP.labelOf(tgt.id, tgt.label)
                        if not grndRepAnswer(pid, msg) then
                            if notify and notify.add then
                                pcall(notify.add, "Не удалось ответить: неизвестен ID в репорте", "warn", 3)
                            end
                        end
                        grndRepQueue("/sp " .. tostring(tgt.id))
                        -- Страховка на случай, если событие отправки чата не
                        -- сработает: основной трекер слежки подключаем вручную.
                        -- Повторный вызов из sampev.onSendChat отсекается
                        -- защитой от дублей внутри grndSpecTrackCommand (1 c).
                        if type(grndSpecTrackCommand) == "function" then
                            pcall(grndSpecTrackCommand, "/sp " .. tostring(tgt.id))
                        end
                        GRND_REP.lastAction = "follow_" .. tostring(tgt.source or "id")
                    else
                        -- Игрок не в сети: игроку уходит ответ, слежки нет.
                        local msg
                        if tgt.source == "nick" then
                            msg = "Приветствую, возможно, игрок вышел из игры, "
                                .. "или проверьте правильность написания никнейма."
                        else
                            msg = "Приветствую, возможно, игрок вышел из игры, "
                                .. "или проверьте правильность написания ID."
                        end
                        if not grndRepAnswer(pid, msg) then
                            if notify and notify.add then
                                pcall(notify.add, "Не удалось ответить: неизвестен ID в репорте", "warn", 3)
                            end
                        end
                        if notify and notify.add then
                            pcall(notify.add, "Слежка: " .. tostring(tgt.label)
                                .. " — игрок не в сети", "warn", 3)
                        end
                        GRND_REP.lastAction = "follow_offline"
                    end
                    -- Окно закрывается в обоих случаях: действие выполнено.
                    pendingClose = true
                end
                -- ---------- поле ответа + «Ответить» ----------
                local sendW = 104
                local inputW = W - PAD * 2 - sendW - 6
                local inputColors = 0
                if grndPushCol(im.Col and im.Col.FrameBg, rgba(10, 13, 20, 255)) then inputColors = inputColors + 1 end
                if grndPushCol(im.Col and im.Col.FrameBgHovered, rgba(16, 24, 34, 255)) then inputColors = inputColors + 1 end
                if grndPushCol(im.Col and im.Col.FrameBgActive, rgba(18, 33, 43, 255)) then inputColors = inputColors + 1 end
                if grndPushCol(im.Col and im.Col.Text, rgba(225, 232, 242, 255)) then inputColors = inputColors + 1 end
                if grndPushCol(im.Col and im.Col.Border, rgba(255, 255, 255, 18)) then inputColors = inputColors + 1 end
                local stIn = 0
                if grndPushStyleV2(im.StyleVar and im.StyleVar.FramePadding, 9, 7) then stIn = stIn + 1 end
                if grndPushStyleF(im.StyleVar and im.StyleVar.FrameBorderSize, 1) then stIn = stIn + 1 end
                -- Фиксированный префикс «Приветствую,» рисуется слева внутри
                -- поля; пользователь дописывает только продолжение.
                local prefix = "Приветствую,"
                local prefW = math.floor(grndTextW(prefix)) + 8
                box(PAD, yInput, prefW + 10, 30, col32(10, 13, 20, 255), 6)
                local enterPressed = false
                im.SetCursorPos(im.ImVec2(PAD + prefW + 4, yInput))
                if im.PushItemWidth then pcall(im.PushItemWidth, inputW - prefW - 4) end
                if GRND_REP.answer then
                    local fl = 0
                    if im.InputTextFlags and im.InputTextFlags.EnterReturnsTrue then
                        fl = im.InputTextFlags.EnterReturnsTrue
                    elseif rawget(im, "ImGuiInputTextFlags_EnterReturnsTrue") then
                        fl = rawget(im, "ImGuiInputTextFlags_EnterReturnsTrue")
                    end
                    local okI, r
                    if im.InputTextWithHint then
                        okI, r = pcall(im.InputTextWithHint, "##grnd_rep_answer", "продолжите ответ…", GRND_REP.answer, 256, fl)
                    elseif im.InputText then
                        okI, r = pcall(im.InputText, "##grnd_rep_answer", GRND_REP.answer, 256, fl)
                    end
                    if okI and r == true and fl ~= 0 then enterPressed = true end
                    -- автофокус на поле при открытии окна
                    if not GRND_REP.focused and im.SetKeyboardFocusHere then
                        pcall(im.SetKeyboardFocusHere, -1)
                        GRND_REP.focused = true
                    end
                end
                if im.PopItemWidth then pcall(im.PopItemWidth) end
                grndPopStyle(stIn)
                grndPopCol(inputColors)
                -- рамка вокруг всего поля (префикс + ввод) как единого элемента
                frame(PAD, yInput, inputW, 30, col32(255, 255, 255, 18), 6)
                text(PAD + 9, yInput + 8, prefix, c4(TH.accent), 0.95)

                local function repButton(x, y, w, h, label, id, primary, scale)
                    scale = scale or 0.84
                    im.SetCursorPos(im.ImVec2(x, y))
                    local clicked = im.InvisibleButton(id, im.ImVec2(w, h))
                    local hovered = im.IsItemHovered and im.IsItemHovered() or false
                    local active = im.IsItemActive and im.IsItemActive() or false
                    local bg, fg, bd
                    if primary then
                        bg = (active or hovered) and c32(TH.accent2) or c32(TH.accent)
                        bd = bg
                        fg = c4(TH.bg)
                    else
                        -- v1.19.06: спокойная кнопка видна и без наведения
                        bg = active and col32(TH.accent[1], TH.accent[2], TH.accent[3], 58)
                            or (hovered and col32(TH.accent[1], TH.accent[2], TH.accent[3], 36)
                                or col32(255, 255, 255, 22))
                        bd = hovered and col32(TH.accent[1], TH.accent[2], TH.accent[3], 120)
                            or col32(255, 255, 255, 40)
                        -- v1.19.04: подписи кнопок окна репорта — заметно ярче
                        -- (прежний TH.text 207,202,217 читался блёкло)
                        fg = hovered and c4({ 252, 250, 255, 255 })
                            or c4({ 238, 234, 250, 255 })
                    end
                    local r = (h >= 28) and 6 or math.floor(h / 2)
                    box(x, y, w, h, bg, r)
                    frame(x, y, w, h, bd, r)
                    local fs = (GRND_FONT and GRND_FONT.fontSize) or 14
                    local maxW = w - 10
                    local lbl = label
                    local tw = grndTextW(lbl) * scale
                    if tw > maxW then
                        -- надпись шире кнопки: укорачиваем с многоточием
                        local cut = lbl
                        while grndUtf8Len(cut) > 1 and grndTextW(cut .. "…") * scale > maxW do
                            cut = cut:gsub("[%z\1-\127\194-\244][\128-\191]*$", "")
                        end
                        lbl = cut .. "…"
                        tw = grndTextW(lbl) * scale
                    end
                    local th = fs * scale
                    text(x + math.floor((w - tw) / 2), y + math.floor((h - th) / 2), lbl, fg, scale)
                    return clicked
                end

                if repButton(PAD + inputW + 6, yInput, sendW, 30, "Ответить", "##grnd_rep_answer_btn", true, 1.0) or enterPressed then
                    GRND_REP.lastAction = "Ответить"
                    local txt = ""
                    if GRND_REP.answer then
                        local okS, v = pcall(function()
                            local okF, ffi = pcall(require, "ffi")
                            if okF and ffi then return ffi.string(GRND_REP.answer) end
                            return tostring(GRND_REP.answer)
                        end)
                        if okS and type(v) == "string" then txt = v end
                    end
                    txt = txt:gsub("^%s+", ""):gsub("%s+$", "")
                    -- если пользователь сам начал с «Приветствую» — не дублируем
                    if grndLowerUtf(txt):find("^приветствую") then
                        txt = txt:gsub("^[Пп]риветствую[,!]?%s*", "")
                    end
                    if txt ~= "" and hasId then
                        grndRepAnswer(pid, prefix .. " " .. txt)
                        pendingClose = true
                    elseif notify and notify.add then
                        pcall(notify.add, txt == "" and "Введите текст ответа" or "ID игрока не распознан", "warn", 2)
                    end
                end

                -- ---------- кнопки действий ----------
                -- Три кнопки в один ряд, одинаковой ширины.
                local chips = {
                    { "Быстрые ответы", "##grnd_rep_quick_btn" },
                    { "Наказание", "##grnd_rep_punish_btn" },
                    { "Передать в /a", "##grnd_rep_admin_btn" },
                }
                local gap = 6
                local cw = math.floor((W - PAD * 2 - gap * (#chips - 1)) / #chips)
                local ch = 28
                for i = 1, #chips do
                    local cx = PAD + (i - 1) * (cw + gap)
                    if repButton(cx, yChips, cw, ch, chips[i][1], chips[i][2], false, 1.0) then
                        GRND_REP.lastAction = chips[i][1]
                        -- v1.19.01: «Быстрые ответы» — окно шаблонов поверх окна репорта
                        if i == 1 then
                            if type(_G.GRND_QR) == "table" then
                                if type(_G.GRND_QR.togglePicker) == "function" then
                                    pcall(_G.GRND_QR.togglePicker)
                                elseif type(_G.GRND_QR.openPicker) == "function" then
                                    pcall(_G.GRND_QR.openPicker)
                                end
                            end
                        elseif i == 2 then
                            -- v1.19.16: «Наказание» — такая же полоса, как
                            -- «Быстрые ответы», только по центру окна репорта
                            if type(_G.GRND_QR) == "table" then
                                if type(_G.GRND_QR.togglePunPicker) == "function" then
                                    pcall(_G.GRND_QR.togglePunPicker)
                                elseif type(_G.GRND_QR.openPunPicker) == "function" then
                                    pcall(_G.GRND_QR.openPunPicker)
                                end
                            end
                        elseif i == 3 then
                            local qtxt = tostring(GRND_REP.question or "")
                            qtxt = qtxt:gsub("^%s+", ""):gsub("%s+$", "")
                            if qtxt == "" then qtxt = "без текста" end
                            local nick = tostring(GRND_REP.author or "Игрок")
                            local who = hasId and (nick .. "[" .. pid .. "]") or nick
                            local cmd = "/a " .. grndRepToAnsi("Обращение игрока " .. who .. ": " .. qtxt)
                            if type(sampSendChat) == "function" then
                                pcall(sampSendChat, cmd)
                            else
                                grndRepQueue(cmd)
                            end
                            if hasId then
                                grndRepAnswer(pid, "Приветствую, ваш вопрос/жалобу передал, ожидайте")
                            end
                            if notify and notify.add then
                                pcall(notify.add, "Передал в /a", "ok", 3)
                            end
                            pendingClose = true
                        end
                    end
                end
            end
            if endDepth > 0 then endDepth = endDepth - 1; pcall(im.End) end
            grndPopCol(colorN)
            grndPopStyle(styleN)
            if pendingClose then
                GRND_REP.open = false
                GRND_REP.focused = false
                if type(_G.GRND_QR) == "table" then
                    _G.GRND_QR.pickOpen = false
                    local P = _G.GRND_QR.pun
                    if type(P) == "table" then P.pickOpen = false end
                end
            end
            return wantCursor
        end

        -- Окно «Автоловля репорта»: спиннер + таймер, правый верх экрана.
        local function drawCatchWindow()
            if not GRND_CATCH.active then return false end
            local resX = getScreenResolution()
            local W, H = 232, 58
            im.SetNextWindowPos(im.ImVec2(resX - W - 24, 120), COND_ALWAYS)
            im.SetNextWindowSize(im.ImVec2(W, H), COND_ALWAYS)
            local styleN, colorN = 0, 0
            if grndPushStyleF(im.StyleVar and im.StyleVar.WindowRounding, 10) then styleN = styleN + 1 end
            if grndPushStyleV2(im.StyleVar and im.StyleVar.WindowPadding, 0, 0) then styleN = styleN + 1 end
            if grndPushCol(im.Col and im.Col.WindowBg, rgba(0, 0, 0, 0)) then colorN = colorN + 1 end
            local flags = wf("NoTitleBar", "NoResize", "NoMove", "NoCollapse",
                "NoScrollbar", "NoScrollWithMouse", "NoInputs", "NoFocusOnAppearing", "NoBringToFrontOnFocus")
            if grndBegin("##grnd_catch", flags) then
                local pos = im.GetWindowPos()
                local dl = im.GetWindowDrawList()
                local function at(x, y) return im.ImVec2(pos.x + x, pos.y + y) end
                roundRect(dl, at(0, 0), at(W, H), c32(TH.bg), 10)
                if dl.AddRect then pcall(dl.AddRect, dl, at(0, 0), at(W, H), col32(255, 255, 255, 16), 10, 0, 1.0) end
                -- # v1.19.09: акцентная полоска у верхней кромки убрана (просьба заказчика)

                -- спиннер: дуга из отрезков, вращается по времени
                local cx, cy, r = 26, 31, 11
                local t = os.clock()
                local a0 = (t * 4.2) % (2 * math.pi)
                local segs = 14
                local sweep = math.pi * 1.35
                if dl.AddCircle then pcall(dl.AddCircle, dl, at(cx, cy), r, col32(255, 255, 255, 22), 24, 2.4) end
                local px, py
                for i = 0, segs do
                    local a = a0 + sweep * (i / segs)
                    local x, y = cx + math.cos(a) * r, cy + math.sin(a) * r
                    if px then
                        local al = math.floor(60 + 195 * (i / segs))
                        dl:AddLine(at(px, py), at(x, y), col32(TH.accent[1], TH.accent[2], TH.accent[3], al), 2.6)
                    end
                    px, py = x, y
                end
                -- пульсирующая точка в центре
                local pulse = 0.5 + 0.5 * math.sin(t * 5)
                dl:AddCircleFilled(at(cx, cy), 2.2 + pulse * 1.2, col32(TH.accent[1], TH.accent[2], TH.accent[3], 120 + pulse * 135), 12)

                uiText(48, 11, "Ловля репорта", c4(TH.textHi), 1.0)
                local el = math.max(0, os.clock() - (GRND_CATCH.startedAt or 0))
                local mm, ss = math.floor(el / 60), math.floor(el % 60)
                local tm = string.format("%02d:%02d", mm, ss)
                uiText(48, 31, "ожидание · " .. tm, c4(TH.textMuted), 0.86)
                uiText(W - 14 - grndTextW(tm), 20, tm, c4(TH.accent), 1.02)
                if (GRND_CATCH.caught or 0) > 0 then
                    local ct = "поймано: " .. tostring(GRND_CATCH.caught)
                    uiText(W - 14 - grndTextW(ct) * 0.78, 40, ct, c4(TH.textDim), 0.78)
                end
            end
            if endDepth > 0 then endDepth = endDepth - 1; pcall(im.End) end
            grndPopCol(colorN)
            grndPopStyle(styleN)
            -- снять нажатый шрифт «лестницы» и глобальный масштаб: следующие
            -- окна кадра должны рисоваться как обычно
            if fontPushed then pcall(im.PopFont) end
            if ioObj then pcall(function() ioObj.FontGlobalScale = ioOld end) end
            return false
        end

        -- =============================================================
        --  АВТОПРИЕМ ФОРМ: модальное окно на экране с кнопками [Y]/[N]
        -- =============================================================
        function drawFormPopup()
            if not _G.GRND_FORMS or not _G.GRND_FORMS.active then return false end
            local form = _G.GRND_FORMS.active

            -- Пять секунд с момента показа. Тайм-аут только закрывает форму:
            -- он не принимает её и не отправляет команду/отчёт.
            local now = os.clock()
            local timeout = tonumber(_G.GRND_FORM_POPUP_TIMEOUT_SEC) or 5.0
            local openedAt = tonumber(form.openedAt) or tonumber(form.time) or now
            local elapsed = math.max(0, now - openedAt)
            local remaining = math.max(0, timeout - elapsed)
            if elapsed >= timeout then
                if type(_G.grndFormsResolve) == "function" then
                    pcall(_G.grndFormsResolve, "timeout")
                end
                return false
            end

            local wantAccept = false
            local wantReject = false

            -- v1.13.0: [Y]/[N] здесь БОЛЬШЕ не читаются. Их опрашивает
            -- основной цикл каждый тик (grndFormsKeyTick) — нажатие не
            -- теряется, если кадр в этот момент не рисуется, и не
            -- перехватывается другими окнами (wasKeyTapped был общий).

            local resX, resY = getScreenResolution()
            local L = _G.GRND_FORM_UI_LAYOUT or { w = 400, h = 124 }
            local FW, FH = L.w or 400, L.h or 124
            -- v1.14.13: позиция своя и ЗАПОМИНАЕТСЯ — окно открывается там,
            -- куда его передвинули, а не по центру сверху. Тащить за шапку
            -- при включённом курсоре (ПКМ), кнопка «×» из захвата исключена.
            local fx, fy = grndFormUiPos(resX, resY, FW, FH)
            local U = _G.GRND_FORM_UI or {}
            local R = grndFormUiRects(fx, fy)
            if type(R) == "table" then
                fx, fy = grndFormUiDrag(form, fx, fy, FW, FH, resX, resY,
                    R.head, R.close)
            end

            -- =================================================================
            --  v1.14.15: РЕШЕНИЕ ПРИНИМАЕТСЯ ДО ОТРИСОВКИ КАДРА.
            --  Раньше и [Y]/[N] (из основного цикла), и клик мышью (из
            --  InvisibleButton в конце этого же блока) срабатывали ПОСЛЕ того,
            --  как окно уже нарисовали в текущем кадре: окно исчезало только
            --  со следующим кадром, а если кадр не заказывался — висело.
            --  Теперь опрашиваем и клавиши, и мышь ЗДЕСЬ, до im.Begin: если
            --  форму приняли/отклонили — окно в этом кадре не рисуется ВООБЩЕ,
            --  то есть пропадает в тот же кадр.
            -- =================================================================
            if type(_G.grndFormsKeyTick) == "function" then pcall(_G.grndFormsKeyTick) end
            local preAct = grndFormUiClick(fx, fy)
            if preAct and type(_G.grndFormsResolve) == "function" then
                pcall(_G.grndFormsResolve, preAct)
            end
            if (not _G.GRND_FORMS) or (_G.GRND_FORMS.active ~= form) then
                return false                       -- окна в этом кадре уже нет
            end

            im.SetNextWindowPos(im.ImVec2(fx, fy), COND_ALWAYS)
            im.SetNextWindowSize(im.ImVec2(FW, FH), COND_ALWAYS)
            if im.SetNextWindowFocus then pcall(im.SetNextWindowFocus) end

            local styleN, colorN = 0, 0
            if grndPushStyleF(im.StyleVar and im.StyleVar.WindowRounding, 12) then styleN = styleN + 1 end
            if grndPushStyleV2(im.StyleVar and im.StyleVar.WindowPadding, 0, 0) then styleN = styleN + 1 end
            if grndPushCol(im.Col and im.Col.WindowBg, rgba(0, 0, 0, 0)) then colorN = colorN + 1 end
            if grndPushCol(im.Col and im.Col.Border, rgba(0, 0, 0, 0)) then colorN = colorN + 1 end
            local flagsF = wf("NoTitleBar", "NoResize", "NoMove", "NoCollapse", "NoScrollbar", "NoScrollWithMouse")

            local drawn = false
            if grndBegin("##grnd_form_popup", flagsF) then
                drawn = true
                if im.BringWindowToDisplayFront then pcall(im.BringWindowToDisplayFront, im.GetCurrentWindow()) end
                local pos = im.GetWindowPos()
                local dl = im.GetWindowDrawList()
                local function at(x, y) return im.ImVec2(pos.x + x, pos.y + y) end

                -- Компактная тёмная карточка, тонкая обводка и акцентная линия.
                roundRect(dl, at(4, 4), at(FW + 4, FH + 4), col32(0, 0, 0, 82), 10)
                roundRect(dl, at(0, 0), at(FW, FH), col32(11, 16, 24, 248), 10)
                if dl.AddRect then pcall(dl.AddRect, dl, at(0.5, 0.5), at(FW - 0.5, FH - 0.5), col32(255, 255, 255, 28), 10, 0, 1.0) end
                -- # v1.19.09: акцентная полоска у верхней кромки убрана (просьба заказчика)

                -- Короткая шапка не заходит под кнопку закрытия и ручку перетаскивания.
                local headerText = "Форма от: " .. grndUtf8Text(form.adminNick)
                    .. " [" .. tostring(form.adminId) .. "]"
                local clippedHeader = false
                while #headerText > 0 and drawnWb(headerText, 0.90) > FW - 78 do
                    local before = #headerText
                    headerText = grndFormUtf8Cut(headerText, before - 1)
                    if #headerText >= before then break end
                    clippedHeader = true
                end
                if clippedHeader then headerText = headerText:gsub("%s+$", "") .. "…" end
                uiText(14, 9, headerText, c4(TH.textHi), 0.90)

                -- v1.14.13: «ручка» перетаскивания — шесть точек слева от «×».
                -- Окно тащится мышью за шапку при включённом курсоре (ПКМ).
                do
                    local grip = U.dragging and c4(TH.accent) or col32(255, 255, 255, 70)
                    for r = 0, 1 do
                        for cIdx = 0, 2 do
                            local gx = FW - 52 + cIdx * 5
                            local gy = 14 + r * 5
                            roundRect(dl, at(gx, gy), at(gx + 2, gy + 2), grip, 1)
                        end
                    end
                end

                -- Кнопка закрытия «×» — координаты совпадают с hitbox.
                local closeX = tonumber(L.closeX) or (FW - 26)
                local closeY = tonumber(L.closeY) or 5
                local closeW = tonumber(L.closeW) or 20
                local closeH = tonumber(L.closeH) or 20
                im.SetCursorPos(im.ImVec2(closeX, closeY))
                local closeClicked = im.InvisibleButton("##form_x_btn", im.ImVec2(closeW, closeH))
                local closeHov = (im.IsItemHovered and im.IsItemHovered()) or false
                if closeClicked then wantReject = true end
                uiText(closeX + 6, closeY + 2, "×", closeHov and c4(TH.textHi) or c4(TH.textMuted), 0.92)

                -- Плашка команды с аккуратным обрезанием длинной строки.
                local cmdY, cmdH = 32, 30
                roundRect(dl, at(12, cmdY), at(FW - 12, cmdY + cmdH), col32(20, 28, 40, 240), 7)
                if dl.AddRect then pcall(dl.AddRect, dl, at(12.5, cmdY + 0.5), at(FW - 12.5, cmdY + cmdH - 0.5), col32(TH.accent[1], TH.accent[2], TH.accent[3], 90), 7, 0, 1.0) end
                local cmdText = grndUtf8Text(form.cmd)
                local clippedCmd = false
                while #cmdText > 0 and drawnWb(cmdText, 0.94) > FW - 44 do
                    local before = #cmdText
                    cmdText = grndFormUtf8Cut(cmdText, before - 1)
                    if #cmdText >= before then break end
                    clippedCmd = true
                end
                if clippedCmd then cmdText = cmdText:gsub("%s+$", "") .. "…" end
                uiText(20, cmdY + 7, cmdText, col32(50, 220, 255, 255), 0.94)

                -- Кнопки действий: [ Y ] Принять форму и [ N ] Отклонить
                local btnX = tonumber(L.btnX) or 12
                local btnY = tonumber(L.btnY) or 70
                local btnH = tonumber(L.btnH) or 34
                local btnGap = tonumber(L.btnGap) or 8
                local btnW = math.floor((FW - 2 * btnX - btnGap) / 2)

                -- Кнопка 1: [ Y ] Принять форму
                local b1X = btnX
                im.SetCursorPos(im.ImVec2(b1X, btnY))
                local btn1Clicked = im.InvisibleButton("##form_accept_btn", im.ImVec2(btnW, btnH))
                local b1Hov = (im.IsItemHovered and im.IsItemHovered()) or false
                local b1Act = (im.IsItemActive and im.IsItemActive()) or false
                if btn1Clicked then wantAccept = true end
                roundRect(dl, at(b1X, btnY), at(b1X + btnW, btnY + btnH),
                    (b1Act or b1Hov) and col32(36, 160, 85, 245) or col32(26, 125, 68, 215), 7)
                if dl.AddRect then pcall(dl.AddRect, dl, at(b1X + 0.5, btnY + 0.5), at(b1X + btnW - 0.5, btnY + btnH - 0.5), col32(50, 220, 115, 180), 7, 0, 1.0) end
                local t1 = "[ Y ] Принять форму"
                local tw1 = drawnWb(t1, 0.88)
                uiText(b1X + (btnW - tw1) / 2, btnY + 10, t1, c4(TH.textHi), 0.88)

                -- Кнопка 2: [ N ] Отклонить
                local b2X = b1X + btnW + btnGap
                im.SetCursorPos(im.ImVec2(b2X, btnY))
                local btn2Clicked = im.InvisibleButton("##form_reject_btn", im.ImVec2(btnW, btnH))
                local b2Hov = (im.IsItemHovered and im.IsItemHovered()) or false
                local b2Act = (im.IsItemActive and im.IsItemActive()) or false
                if btn2Clicked then wantReject = true end
                roundRect(dl, at(b2X, btnY), at(b2X + btnW, btnY + btnH),
                    (b2Act or b2Hov) and col32(185, 50, 50, 245) or col32(145, 38, 38, 200), 7)
                if dl.AddRect then pcall(dl.AddRect, dl, at(b2X + 0.5, btnY + 0.5), at(b2X + btnW - 0.5, btnY + btnH - 0.5), col32(235, 70, 70, 180), 7, 0, 1.0) end
                local t2 = "[ N ] Отклонить"
                local tw2 = drawnWb(t2, 0.88)
                uiText(b2X + (btnW - tw2) / 2, btnY + 10, t2, c4(TH.textHi), 0.88)

                uiText(14, FH - 16, "Автозакрытие: " .. tostring(math.ceil(remaining)) .. " сек",
                    c4(TH.textMuted), 0.72)
                local timerX, timerW = FW - 70, 56
                roundRect(dl, at(timerX, FH - 5), at(timerX + timerW, FH - 3), col32(255, 255, 255, 30), 1)
                local ratio = math.max(0, math.min(1, remaining / timeout))
                if ratio > 0 then
                    gradRect(dl, at(timerX, FH - 5), at(timerX + timerW * ratio, FH - 3),
                        col32(TH.accent[1], TH.accent[2], TH.accent[3], 245),
                        col32(TH.accent2[1], TH.accent2[2], TH.accent2[3], 245), 1)
                end

                if endDepth > 0 then endDepth = endDepth - 1; pcall(im.End) end
            end
            grndPopCol(colorN)
            grndPopStyle(styleN)

            -- v1.13.0: всё действие — через grndFormsResolve. Он СНАЧАЛА
            -- убирает окно (GRND_FORMS.active = следующая форма или nil) и
            -- держит кадр на стирание, и только потом отправляет команду,
            -- включает сторожа ответа сервера и показывает уведомления.
            -- Раньше окно закрывалось ПОСЛЕ отправки: любая ошибка на этом
            -- пути оставляла окно висеть до тайм-аута.
            if wantAccept then
                if type(_G.grndFormsResolve) == "function" then
                    pcall(_G.grndFormsResolve, "accept")
                end
            elseif wantReject then
                if type(_G.grndFormsResolve) == "function" then
                    pcall(_G.grndFormsResolve, "reject")
                end
            end

            return drawn
        end

        -- =====================================================================
        --  v1.11.79: ОКНО «Принять гос.волну?» (/acceptgnews).
        --  Появляется сразу, как только в чате мелькнула заявка на
        --  государственные новости. [Y] — принять (команда + отчёт в /a),
        --  [N] — отклонить. Само закрывается через 5 секунд без принятия.
        -- =====================================================================
        function drawGnewsPopup()
            local G = _G.GRND_GNEWS
            if type(G) ~= "table" or not G.active then return false end

            local now = os.clock()
            local timeout = tonumber(_G.GRND_GNEWS_POPUP_TIMEOUT_SEC) or 5.0
            local openedAt = tonumber(G.at)
            if not openedAt or openedAt <= 0 then
                openedAt = now
                G.at = now
            end
            local elapsed = math.max(0, now - openedAt)
            local remaining = math.max(0, timeout - elapsed)
            if elapsed >= timeout then
                grndGnewsClose() -- тайм-аут только закрывает; /acceptgnews не отправляем
                return false
            end

            local wantAccept, wantReject = false, false

            -- горячие клавиши Y / N (только если не печатаешь в чате)
            local typing = false
            if type(sampIsChatInputActive) == "function" then
                local okC, isC = pcall(sampIsChatInputActive)
                if okC and isC then typing = true end
            end
            if not typing and type(sampIsDialogActive) == "function" then
                local okD, isD = pcall(sampIsDialogActive)
                if okD and isD then typing = true end
            end
            if not typing and type(wasKeyTapped) == "function" then
                if wasKeyTapped(0x59) then -- Y
                    wantAccept = true
                elseif wasKeyTapped(0x4E) then -- N
                    wantReject = true
                end
            end

            local resX, resY = getScreenResolution()
            local FW, FH = 400, 124
            local fx = math.floor((resX - FW) / 2)
            local fy = math.floor(resY * 0.18)

            im.SetNextWindowPos(im.ImVec2(fx, fy), COND_ALWAYS)
            im.SetNextWindowSize(im.ImVec2(FW, FH), COND_ALWAYS)
            if im.SetNextWindowFocus then pcall(im.SetNextWindowFocus) end

            local styleN, colorN = 0, 0
            if grndPushStyleF(im.StyleVar and im.StyleVar.WindowRounding, 12) then styleN = styleN + 1 end
            if grndPushStyleV2(im.StyleVar and im.StyleVar.WindowPadding, 0, 0) then styleN = styleN + 1 end
            if grndPushCol(im.Col and im.Col.WindowBg, rgba(0, 0, 0, 0)) then colorN = colorN + 1 end
            if grndPushCol(im.Col and im.Col.Border, rgba(0, 0, 0, 0)) then colorN = colorN + 1 end
            local flagsG = wf("NoTitleBar", "NoResize", "NoMove", "NoCollapse", "NoScrollbar", "NoScrollWithMouse")

            local drawn = false
            if grndBegin("##grnd_gnews_popup", flagsG) then
                drawn = true
                if im.BringWindowToDisplayFront then pcall(im.BringWindowToDisplayFront, im.GetCurrentWindow()) end
                local pos = im.GetWindowPos()
                local dl = im.GetWindowDrawList()
                local function at(x, y) return im.ImVec2(pos.x + x, pos.y + y) end

                roundRect(dl, at(4, 4), at(FW + 4, FH + 4), col32(0, 0, 0, 82), 10)
                roundRect(dl, at(0, 0), at(FW, FH), col32(11, 16, 24, 248), 10)
                if dl.AddRect then
                    pcall(dl.AddRect, dl, at(0.5, 0.5), at(FW - 0.5, FH - 0.5),
                        col32(255, 255, 255, 28), 10, 0, 1.0)
                end
                -- # v1.19.09: акцентная полоска у верхней кромки убрана (просьба заказчика)

                -- Заголовок
                uiText(14, 9, "Принять гос.волну?", c4(TH.textHi), 0.94)

                -- Кнопка закрытия «×» (то же, что [N])
                local closeX, closeY = FW - 26, 5
                im.SetCursorPos(im.ImVec2(closeX, closeY))
                local gxClicked = im.InvisibleButton("##gnews_x_btn", im.ImVec2(20, 20))
                local gxHov = (im.IsItemHovered and im.IsItemHovered()) or false
                if gxClicked then wantReject = true end
                uiText(closeX + 6, closeY + 2, "×", gxHov and c4(TH.textHi) or c4(TH.textMuted), 0.92)

                -- Плашка-пояснение
                local cmdY, cmdH = 32, 30
                roundRect(dl, at(12, cmdY), at(FW - 12, cmdY + cmdH), col32(20, 28, 40, 240), 7)
                if dl.AddRect then
                    pcall(dl.AddRect, dl, at(12.5, cmdY + 0.5), at(FW - 12.5, cmdY + cmdH - 0.5),
                        col32(TH.accent[1], TH.accent[2], TH.accent[3], 90), 7, 0, 1.0)
                end
                uiText(20, cmdY + 7, "Заявка на государственные новости  ·  /acceptgnews",
                    col32(50, 220, 255, 255), 0.88)

                -- Кнопки: [ Y ] Принять  /  [ N ] Отклонить
                local btnX, btnY, btnH, btnGap = 12, 70, 34, 8
                local btnW = math.floor((FW - 2 * btnX - btnGap) / 2)

                local b1X = btnX
                im.SetCursorPos(im.ImVec2(b1X, btnY))
                local gb1 = im.InvisibleButton("##gnews_accept_btn", im.ImVec2(btnW, btnH))
                local g1Hov = (im.IsItemHovered and im.IsItemHovered()) or false
                local g1Act = (im.IsItemActive and im.IsItemActive()) or false
                if gb1 then wantAccept = true end
                roundRect(dl, at(b1X, btnY), at(b1X + btnW, btnY + btnH),
                    (g1Act or g1Hov) and col32(36, 160, 85, 245) or col32(26, 125, 68, 215), 7)
                if dl.AddRect then
                    pcall(dl.AddRect, dl, at(b1X + 0.5, btnY + 0.5),
                        at(b1X + btnW - 0.5, btnY + btnH - 0.5), col32(50, 220, 115, 180), 7, 0, 1.0)
                end
                local gt1 = "[ Y ] Принять"
                local gtw1 = drawnWb(gt1, 0.88)
                uiText(b1X + (btnW - gtw1) / 2, btnY + 10, gt1, c4(TH.textHi), 0.88)

                local b2X = b1X + btnW + btnGap
                im.SetCursorPos(im.ImVec2(b2X, btnY))
                local gb2 = im.InvisibleButton("##gnews_reject_btn", im.ImVec2(btnW, btnH))
                local g2Hov = (im.IsItemHovered and im.IsItemHovered()) or false
                local g2Act = (im.IsItemActive and im.IsItemActive()) or false
                if gb2 then wantReject = true end
                roundRect(dl, at(b2X, btnY), at(b2X + btnW, btnY + btnH),
                    (g2Act or g2Hov) and col32(185, 50, 50, 245) or col32(145, 38, 38, 200), 7)
                if dl.AddRect then
                    pcall(dl.AddRect, dl, at(b2X + 0.5, btnY + 0.5),
                        at(b2X + btnW - 0.5, btnY + btnH - 0.5), col32(235, 70, 70, 180), 7, 0, 1.0)
                end
                local gt2 = "[ N ] Отклонить"
                local gtw2 = drawnWb(gt2, 0.88)
                uiText(b2X + (btnW - gtw2) / 2, btnY + 10, gt2, c4(TH.textHi), 0.88)

                uiText(14, FH - 16, "Автозакрытие: " .. tostring(math.ceil(remaining)) .. " сек",
                    c4(TH.textMuted), 0.72)
                local timerX, timerW = FW - 70, 56
                roundRect(dl, at(timerX, FH - 5), at(timerX + timerW, FH - 3), col32(255, 255, 255, 30), 1)
                local ratio = math.max(0, math.min(1, remaining / timeout))
                if ratio > 0 then
                    gradRect(dl, at(timerX, FH - 5), at(timerX + timerW * ratio, FH - 3),
                        col32(TH.accent[1], TH.accent[2], TH.accent[3], 245),
                        col32(TH.accent2[1], TH.accent2[2], TH.accent2[3], 245), 1)
                end

                if endDepth > 0 then endDepth = endDepth - 1; pcall(im.End) end
            end
            grndPopCol(colorN)
            grndPopStyle(styleN)

            if wantAccept then
                pcall(_G.grndGnewsAccept)
            elseif wantReject then
                pcall(_G.grndGnewsReject)
            end

            return drawn
        end

        -- =====================================================================
        --  v1.11.78: ОТДЕЛЬНОЕ ОКНО СО СТАТИСТИКОЙ ИГРОКА.
        --  Появляется при /stats <id> и кнопке «Статистика», когда
        --  окно рекона уже на экране (во время слежки) — там «открытие
        --  карточки» внешне ничего не меняет. Данные берутся из кэша ПО
        --  ИГРОКУ, поэтому окно обновляется само, когда приходит ответ.
        --  Закрыть: [×] в окне или ESC; само закрывается через 60 секунд.
        -- =====================================================================
        _G.grndDrawStatsPopup = function()
            -- Re-check the session at draw time so a stale popup cannot leak
            -- onto login screens after reconnect. A native SAMP dialog owns the
            -- screen/input; hide this overlay until that dialog is dismissed.
            if type(grndSessionReady) == "function" then
                local okReady, ready = pcall(grndSessionReady)
                if not okReady or not ready then return false end
            elseif type(grndUiBlocked) == "function" then
                local okBlocked, blocked = pcall(grndUiBlocked)
                if not okBlocked or blocked then return false end
            end
            if type(sampIsDialogActive) == "function" then
                local okDialog, activeDialog = pcall(sampIsDialogActive)
                if okDialog and activeDialog then return false end
            end
            local RC = GRND_RC
            local P = RC and RC.statsPop
            if type(P) ~= "table" then return false end
            if os.clock() - (P.at or 0) > (GRND_STATS_VIEW_KEEP or 60) then
                RC.statsPop = nil
                return false
            end
            local pid = tonumber(P.id) or tonumber(RC.id) or 0
            local data = (type(RC.statsCache) == "table") and RC.statsCache[pid] or nil
            if not data and tonumber(RC.id) == pid then data = RC.live end
            data = data or {}

            local rows = {
                { "Аккаунт",          "rc_account"   },
                { "Уровень (EXP)",    "rc_level_exp" },
                { "Номер телефона",   "rc_phone"     },
                { "Варнов",           "rc_varnov"    },
                { "Пол",              "rc_gender"    },
                { "Женат на",         "rc_married"   },
                { "Орг. (ранг)",      "rc_org"       },
                { "Работа/Должность", "rc_job"       },
                { "Бизнес",           "rc_business"  },
                { "Игровой статус",   "rc_status"    },
                { "Дом",              "rc_house"     },
                { "Квартира",         "rc_flat"      },
                { "VIP статус",       "rc_vip"       },
                { "Семья",            "rc_family"    },
                { "За сегодня",       "today"        },
            }

            local resX, resY = getScreenResolution()
            local FW = 400
            local rowH = 20
            local FH = 74 + #rows * rowH + 30
            local fx = math.floor((resX - FW) / 2)
            local fy = math.max(20, math.floor((resY - FH) / 2) - 30)

            im.SetNextWindowPos(im.ImVec2(fx, fy), COND_ALWAYS)
            im.SetNextWindowSize(im.ImVec2(FW, FH), COND_ALWAYS)

            local styleN, colorN = 0, 0
            if grndPushStyleF(im.StyleVar and im.StyleVar.WindowRounding, 12) then styleN = styleN + 1 end
            if grndPushStyleV2(im.StyleVar and im.StyleVar.WindowPadding, 0, 0) then styleN = styleN + 1 end
            if grndPushCol(im.Col and im.Col.WindowBg, rgba(0, 0, 0, 0)) then colorN = colorN + 1 end
            if grndPushCol(im.Col and im.Col.Border, rgba(0, 0, 0, 0)) then colorN = colorN + 1 end
            local flags = wf("NoTitleBar", "NoResize", "NoMove", "NoCollapse",
                "NoScrollbar", "NoScrollWithMouse", "NoBringToFrontOnFocus")

            local drawn = false
            local wantClose = false
            if grndBegin("##grnd_stats_popup", flags) then
                drawn = true
                -- Raise once on first appearance only. The old per-frame raise
                -- kept this popup above every menu/dialog and blocked their UI.
                if P.frontPending then
                    P.frontPending = false
                    if im.BringWindowToDisplayFront and im.GetCurrentWindow then
                        local okWindow, currentWindow = pcall(im.GetCurrentWindow)
                        if okWindow then pcall(im.BringWindowToDisplayFront, currentWindow) end
                    end
                end
                local pos = im.GetWindowPos()
                local dl = im.GetWindowDrawList()
                local function at(x, y) return im.ImVec2(pos.x + x, pos.y + y) end

                roundRect(dl, at(4, 4), at(FW + 4, FH + 4), col32(0, 0, 0, 90), 12)
                roundRect(dl, at(0, 0), at(FW, FH), col32(11, 16, 24, 250), 12)
                if dl.AddRect then
                    pcall(dl.AddRect, dl, at(0.5, 0.5), at(FW - 0.5, FH - 0.5),
                        col32(255, 255, 255, 25), 12, 0, 1.0)
                end
                -- # v1.19.09: акцентная полоска у верхней кромки убрана (просьба заказчика)

                local who = tostring(P.nick or "")
                if who == "" then who = "ID " .. tostring(pid) end
                uiText(16, 11, "Статистика игрока: " .. grndUtf8Text(who)
                    .. " [" .. tostring(pid) .. "]", c4(TH.textHi), 0.96)

                im.SetCursorPos(im.ImVec2(FW - 26, 7))
                if im.InvisibleButton("##stats_pop_x", im.ImVec2(20, 20)) then wantClose = true end
                local xHov = (im.IsItemHovered and im.IsItemHovered()) or false
                uiText(FW - 20, 9, "×", xHov and c4(TH.textHi) or c4(TH.textMuted), 0.95)

                local y = 40
                for i = 1, #rows do
                    local lbl, key = rows[i][1], rows[i][2]
                    local val = data[key]
                    if val == nil or val == "" then val = "—" end
                    uiText(18, y, lbl, c4(TH.textMuted), 0.88)
                    uiText(FW - 18 - drawnWb(tostring(val), 0.92), y, tostring(val),
                        c4(TH.text), 0.92)
                    y = y + rowH
                end

                if data.rc_stats_at then
                    uiText(18, FH - 26, "данные /stats: " .. tostring(data.rc_stats_at)
                        .. "   ·   [ESC] закрыть", c4(TH.textMuted), 0.72)
                else
                    uiText(18, FH - 26, "ожидаю ответ сервера…   ·   [ESC] закрыть",
                        c4(TH.textMuted), 0.72)
                end

                pcall(im.End)
            end
            grndPopCol(colorN)
            grndPopStyle(styleN)

            if wantClose then
                RC.statsPop = nil
                return false
            end
            return drawn
        end

        -- =============================================================
        --  ОВЕРЛЕЙ «РЕПОРТЫ НА ЭКРАН» (v1.15.1: ОДИН размер на всё окно)
        --
        --  Размер оверлея задаётся ЕДИНОЙ настройкой «Размер окна»
        --  (GRND_REPHUD.scale) — она же в карточке настроек. От одного
        --  множителя считаются:
        --    * само окно: ширина, высота, отступы, шаг строки, значки;
        --    * КЕГЛЬ всего текста внутри (шапка, строки, подписи).
        --  Раньше это были ДВА ползунка («Ширина» + «Текст») и они могли
        --  рассогласоваться: окно росло, а буквы оставались мелкими (и
        --  наоборот) — вёрстка «съезжала». Теперь масштаб общий.
        --
        --  Кегль берём НАТИВНЫЙ из «лестницы» шрифтов (как в килл-листе):
        --  текст рисуется ровно в том кегле, в котором отрисован в атласе,
        --  поэтому буквы остаются резкими на любом положении ползунка.
        --  «Лестницы» нет (шрифт не собрался) — тянем базовый шрифт
        --  SetWindowFontScale на тот же множитель и на него же умножаем
        --  измеренные ширины текста, иначе подписи вылезли бы за строку.
        -- =============================================================
        -- =============================================================
        --  v1.15.2: КАК В ЭТОМ КЛИЕНТЕ МАСШТАБИРУЕТСЯ ТЕКСТ — определяем
        --  прямо в бою и используем то, что реально работает.
        --
        --  Почему так: разные обёртки (mimgui / moonimgui) и разные их
        --  версии поддерживают РАЗНЫЕ способы. На практике встречались:
        --    * im.PushFont(font, size)  — динамический кегль (ImGui 1.92+);
        --    * im.SetWindowFontScale(k) — растяжка (умеет не всякая сборка);
        --    * im.PushFont(готовый шрифт нужного кегля) — «лестница»;
        --    * io.FontGlobalScale = k   — глобальный масштаб шрифта.
        --  Проблема была в том, что окно росло, а выбранный способ молча
        --  ничего не делал — текст оставался базовым. Теперь каждый способ
        --  ПРОВЕРЯЕТСЯ замером (CalcTextSize пробы): если ширина пробы на
        --  K=2 не выросла — способ нерабочий. Результат кэшируется.
        --
        --  Возвращает: mode, font (для режима «pushsize»), at (os.clock()).
        -- =============================================================
        -- =============================================================
        --  v1.15.53: DX-ПУТЬ (render-библиотека MoonLoader, GDI).
        --  Зачем: на части сборок ImGui НЕ меняет кегль текста ни одним
        --  из способов (ни PushFont(font,size), ни SetWindowFontScale, ни
        --  «лестницей», ни io.FontGlobalScale) — окно росло, а буквы
        --  оставались мелкими. GDI-шрифт создаётся ЗАНОВО ровно нужного
        --  кегля (renderCreateFont), поэтому размер текста здесь всегда
        --  тот, что заказан, и он резкий (без растянутой текстуры).
        --  Этим же путём давно рисуется килл-лист и панель админов.
        -- =============================================================
        GRND_REPHUD.dxReady = function()
            -- v1.15.55: DX — это и текст, и подложка. Проверять только
            -- шрифт было недостаточно: при отсутствующем API фона окно
            -- становилось прозрачным, а надписи висели прямо над игрой.
            return (type(renderCreateFont) == "function")
                and (type(renderFontDrawText) == "function")
                and (type(renderGetFontDrawTextLength) == "function")
                and (type(renderDrawBox) == "function")
        end
        -- ARGB (как ждёт render-библиотека) из RGBA 0..255
        GRND_REPHUD.dxCol = function(r, g, b, a)
            local function cc(v)
                -- mimgui ImVec4 — float: округляем 149.99999 обратно в 150.
                v = math.floor((tonumber(v) or 0) + 0.5)
                if v < 0 then v = 0 elseif v > 255 then v = 255 end
                return v
            end
            return cc(a) * 0x1000000 + cc(r) * 0x10000 + cc(g) * 0x100 + cc(b)
        end
        -- шрифт ровно этого кегля (кэш по кеглю), Tahoma/Arial, charset 204
        GRND_REPHUD.dxFont = function(px)
            local R = GRND_REPHUD
            if R.dxDead then return nil end
            if not R.dxReady() then R.dxDead = true return nil end
            px = math.floor(tonumber(px) or 16)
            if px < 7 then px = 7 elseif px > 40 then px = 40 end
            R.dxFonts = R.dxFonts or {}
            local f = R.dxFonts[px]
            if f then return f end
            local fams = { "Tahoma", "Arial", "Verdana" }
            if GRND_FONT and type(GRND_FONT.family) == "string" then
                table.insert(fams, 1, GRND_FONT.family)
            end
            for _, fam in ipairs(fams) do
                local ok1, f1 = pcall(renderCreateFont, fam, -px, 1, 204)
                if ok1 and f1 then f = f1 break end
                local ok2, f2 = pcall(renderCreateFont, fam, -px, 1)
                if ok2 and f2 then f = f2 break end
            end
            if f then
                R.dxFonts[px] = f
                return f
            end
            R.dxDead = true
            pcall(print, "[GRND] репорт-оверлей: renderCreateFont не сработал — DX-путь выключен")
            return nil
        end
        -- ширина надписи тем самым GDI-шрифтом (CP1251 — как рисуем)
        GRND_REPHUD.dxW = function(s, px)
            local R = GRND_REPHUD
            local f = R.dxFont(px)
            if not f then return nil end
            local txt = tostring(s or "")
            if type(grndToAnsi) == "function" then
                local ok, o = pcall(grndToAnsi, txt)
                if ok and type(o) == "string" then txt = o end
            end
            local okw, w = pcall(renderGetFontDrawTextLength, f, txt)
            if okw and type(w) == "number" and w > 0 then return w end
            if type(renderGetFontDrawTextSize) == "function" then
                local oks, sw = pcall(renderGetFontDrawTextSize, f, txt)
                if oks and type(sw) == "number" and sw > 0 then return sw end
            end
            return nil
        end
        -- высота строки GDI-шрифта (для центровки надписи в строке)
        GRND_REPHUD.dxH = function(px)
            local R = GRND_REPHUD
            local f = R.dxFont(px)
            if not f then return nil end
            if type(renderGetFontDrawHeight) == "function" then
                local okh, hh = pcall(renderGetFontDrawHeight, f)
                if okh and type(hh) == "number" and hh > 0 then return hh end
            end
            return nil
        end
        GRND_REPHUD.dxText = function(s, x, y, r, g, b, a, px)
            local R = GRND_REPHUD
            local f = R.dxFont(px)
            if not f then return false end
            local txt = tostring(s or "")
            if type(grndToAnsi) == "function" then
                local ok, o = pcall(grndToAnsi, txt)
                if ok and type(o) == "string" then txt = o end
            end
            return pcall(renderFontDrawText, f, txt, math.floor(x), math.floor(y),
                R.dxCol(r, g, b, a))
        end
        GRND_REPHUD.dxRect = function(x, y, w, h, r, g, b, a)
            -- MoonLoader 0.26: штатный API прямоугольника — renderDrawBox.
            -- В v1.15.53/54 здесь было неверное имя функции, поэтому фон,
            -- рамка, бейдж и ручка окна молча не рисовались.
            if type(renderDrawBox) ~= "function" then return false end
            return pcall(renderDrawBox, math.floor(x), math.floor(y),
                math.max(1, math.ceil(w)), math.max(1, math.ceil(h)),
                GRND_REPHUD.dxCol(r, g, b, a))
        end
        -- =============================================================
        --  v1.17: СКРУГЛЁННЫЙ прямоугольник и вертикальный ГРАДИЕНТ
        --  средствами render-библиотеки. У renderDrawBox нет ни
        --  скруглений, ни градиента, поэтому:
        --    * углы растеризуются ПОСТРОЧНО — только в зоне радиуса
        --      (rad строк сверху и снизу), там силуэт и закругляется;
        --    * середина рисуется полосами (steps штук) с интерполяцией
        --      цвета от c1 к c2 — получается плавный градиент;
        --    * rowStep > 1 — крупный шаг построчной растеризации: для
        --      МЯГКОЙ ТЕНИ этого достаточно (на низкой альфе ступеньки
        --      не видны), а вызовов renderDrawBox втрое меньше.
        --  c1/c2 — таблицы {r, g, b, a}. При c2 == c1 — плоская заливка.
        --  Вызовов на кадр немного: 2*rad/rowStep + steps (у панели это
        --  ~36 штук), поэтому оверлей не «съедает» кадр.
        -- =============================================================
        GRND_REPHUD.dxRoundGrad = function(x, y, w, h, rad, c1, c2, steps, rowStep)
            local R = GRND_REPHUD
            if type(R.dxCol) ~= "function" then return false end
            if type(c1) ~= "table" then return false end
            x, y = math.floor(tonumber(x) or 0), math.floor(tonumber(y) or 0)
            w, h = math.floor(tonumber(w) or 0), math.floor(tonumber(h) or 0)
            if w < 1 or h < 1 then return false end
            c2 = (type(c2) == "table") and c2 or c1
            steps = math.max(1, math.floor(tonumber(steps) or 5))
            rowStep = math.max(1, math.floor(tonumber(rowStep) or 1))
            rad = math.max(0, math.min(math.floor(tonumber(rad) or 0),
                math.floor(math.min(w, h) / 2)))
            local function mix(t, a, b)
                return math.floor(a + (b - a) * t + 0.5)
            end
            -- полоса с инсетом по горизонтали (0 — во всю ширину)
            local function band(by, bh, inset)
                if bh < 1 then bh = 1 end
                local t = (by - y) / math.max(1, h)
                R.dxRect(x + inset, by, w - inset * 2, bh,
                    mix(t, c1[1], c2[1]), mix(t, c1[2], c2[2]),
                    mix(t, c1[3], c2[3]), mix(t, c1[4], c2[4]))
            end
            -- верхние углы: построчно, «ступеньками» высотой rowStep
            local i = 0
            while i < rad do
                local d = rad - i
                local inset = math.floor(rad - math.sqrt(math.max(0, rad * rad - d * d)) + 0.5)
                band(y + i, math.min(rowStep, rad - i), inset)
                i = i + rowStep
            end
            -- середина: полосами с интерполяцией цвета
            local midT, midB = y + rad, y + h - rad
            if midB > midT then
                local n = math.max(1, math.min(steps, midB - midT))
                local bh = (midB - midT) / n
                for k = 0, n - 1 do
                    local ya = math.floor(midT + k * bh)
                    local yb = math.floor(midT + (k + 1) * bh)
                    if yb <= ya then yb = ya + 1 end
                    band(ya, yb - ya, 0)
                end
            end
            -- нижние углы: построчно снизу вверх
            i = 0
            while i < rad do
                local d = rad - i
                local inset = math.floor(rad - math.sqrt(math.max(0, rad * rad - d * d)) + 0.5)
                local bh = math.min(rowStep, rad - i)
                band(y + h - i - bh, bh, inset)
                i = i + rowStep
            end
            return true
        end
        -- ГОРИЗОНТАЛЬНЫЙ градиент средствами render-библиотеки: strips
        -- вертикальных полос с интерполяцией цвета (для линии-акцента).
        -- Полос немного (8) и полоса ОДНА на кадр — на кадр не влияет.
        GRND_REPHUD.dxHGrad = function(x, y, w, h, r1, g1, b1, a1, r2, g2, b2, a2, strips)
            local R = GRND_REPHUD
            x, y = math.floor(tonumber(x) or 0), math.floor(tonumber(y) or 0)
            w, h = math.floor(tonumber(w) or 0), math.floor(tonumber(h) or 0)
            if w < 1 or h < 1 then return false end
            strips = math.max(1, math.min(math.floor(tonumber(strips) or 8), 32))
            local sw = w / strips
            for k = 0, strips - 1 do
                local xa = math.floor(x + k * sw)
                local xb = math.floor(x + (k + 1) * sw)
                if xb <= xa then xb = xa + 1 end
                local t = (k + 0.5) / strips
                R.dxRect(xa, y, xb - xa, h,
                    math.floor(r1 + (r2 - r1) * t + 0.5),
                    math.floor(g1 + (g2 - g1) * t + 0.5),
                    math.floor(b1 + (b2 - b1) * t + 0.5),
                    math.floor(a1 + (a2 - a1) * t + 0.5))
            end
            return true
        end
        -- вертикальный градиент (ImGui: AddRectFilledMultiColor «сверху вниз»)
        GRND_REPHUD.vgrad = function(dl, p1, p2, cTop, cBot)
            if im.ImDrawList_AddRectFilledMultiColor then
                local ok = pcall(im.ImDrawList_AddRectFilledMultiColor, dl, p1, p2,
                    cTop, cTop, cBot, cBot)
                if ok then return true end
            end
            local ok = pcall(dl.AddRectFilledMultiColor, dl, p1, p2, cTop, cTop, cBot, cBot)
            if ok then return true end
            return false
        end
        -- горизонтальный градиент (для линии-акцента и «затухающих» линий)
        GRND_REPHUD.hgrad = function(dl, p1, p2, c1, c2)
            if im.ImDrawList_AddRectFilledMultiColor then
                local ok = pcall(im.ImDrawList_AddRectFilledMultiColor, dl, p1, p2,
                    c1, c2, c2, c1)
                if ok then return true end
            end
            return pcall(dl.AddRectFilledMultiColor, dl, p1, p2, c1, c2, c2, c1)
        end

        -- v1.15.54: прогон проб ВНУТРИ настоящего ImGui-окна.
        -- РАНЬШЕ (v1.15.2/53) пробы делались до Begin: вне окна
        -- SetWindowFontScale и PushFont либо не влияют на g.FontSize, либо
        -- просто ничего не делают (у обёртки нет CurrentWindow). Замер
        -- поэтому не менялся на ВСЕХ способах, детектор честно отвечал
        -- «ничего не работает», а окно по предохранителю замирало на 360 px —
        -- ровно то, что вы и видели («окно вообще не меняется»).
        -- Теперь пробы идут в крошечном невидимом окне за краем экрана.
        GRND_REPHUD.detectTextMode = function(basePx)
            local R = GRND_REPHUD
            basePx = tonumber(basePx) or 16
            local probe = "РЕПОРТЫ"
            local dbg = {}
            local function note(t) dbg[#dbg + 1] = tostring(t) end

            -- чем меряем: прямой кегль шрифта (честнее всего), а нет —
            -- ширина пробы строки
            local hasFS = (type(im.GetFontSize) == "function")
            local function cur()
                if hasFS then
                    local ok, v = pcall(im.GetFontSize)
                    local n = tonumber(v)
                    if ok and n and n > 0 then return n end
                end
                if type(im.CalcTextSize) ~= "function" then return nil end
                local ok, a = pcall(im.CalcTextSize, probe)
                if not ok then return nil end
                local ta = type(a)
                local w = (ta == "table" or ta == "cdata") and tonumber(a.x) or tonumber(a)
                return (w and w > 0) and w or nil
            end
            local s0 = nil
            local function grew(v) return (v and s0 and v > s0 * 1.4) and true or false end

            local canPush = (type(im.PushFont) == "function")
                and (type(im.PopFont) == "function")
            -- шрифты-кандидаты: базовый интерфейсный и любой из «лестницы»
            local fonts = {}
            if GRND_FONT and GRND_FONT.fontObj then fonts[#fonts + 1] = GRND_FONT.fontObj end
            if im.__grndUiFont then fonts[#fonts + 1] = im.__grndUiFont end
            local L = im.__grndFontLadder
            if type(L) == "table" then
                for _, f in pairs(L) do
                    fonts[#fonts + 1] = f
                    if #fonts >= 4 then break end
                end
            end

            local res, resFont = "none", nil

            -- -------- пробы ImGui (только внутри окна!) --------
            local function probeImgui()
                s0 = cur()
                note("база " .. (hasFS and "кегль " or "шир. ")
                    .. tostring(s0 and (math.floor(s0 * 10 + 0.5) / 10) or "нет"))
                if not s0 then note("измерять нечем") return end
                local K = 2.0
                -- 1) PushFont(font, size) — динамический кегль (ImGui 1.92+)
                if canPush then
                    for i = 1, #fonts do
                        local okp = pcall(im.PushFont, fonts[i], basePx * K)
                        if okp then
                            local v = cur()
                            pcall(im.PopFont)          -- ТОЛЬКО если нажали
                            note("pushsize " .. tostring(v and (math.floor(v * 10 + 0.5) / 10) or "нет"))
                            if grew(v) then res, resFont = "pushsize", fonts[i] return end
                        end
                    end
                    note("pushsize нет")
                end
                -- 2) SetWindowFontScale
                if type(im.SetWindowFontScale) == "function" then
                    local oks = pcall(im.SetWindowFontScale, K)
                    if oks then
                        local v = cur()
                        pcall(im.SetWindowFontScale, 1)
                        note("scale " .. tostring(v and (math.floor(v * 10 + 0.5) / 10) or "нет"))
                        if grew(v) then res = "scale" return end
                    end
                end
                -- 3) PushFont(шрифт нужного кегля из «лестницы»)
                if canPush and type(grndUiFontPick) == "function" then
                    local okp, fobj = pcall(grndUiFontPick, math.floor(basePx * K + 0.5))
                    if okp and fobj then
                        local okf = pcall(im.PushFont, fobj)
                        if okf then
                            local v = cur()
                            pcall(im.PopFont)
                            note("кегль-шрифт " .. tostring(v and (math.floor(v * 10 + 0.5) / 10) or "нет"))
                            if grew(v) then res = "push" return end
                        end
                    end
                end
                -- 4) io.FontGlobalScale (после смены нужно перевыбрать шрифт,
                --    иначе g.FontSize останется прежним)
                if type(im.GetIO) == "function" then
                    local okio, io = pcall(im.GetIO)
                    if okio and io then
                        local okGet, old = pcall(function() return io.FontGlobalScale end)
                        old = okGet and tonumber(old) or 1
                        local okSet = pcall(function() io.FontGlobalScale = old * K end)
                        if okSet then
                            local pushed = false
                            if canPush and fonts[1] then pushed = pcall(im.PushFont, fonts[1]) end
                            local v = cur()
                            if pushed then pcall(im.PopFont) end
                            pcall(function() io.FontGlobalScale = old end)
                            note("global " .. tostring(v and (math.floor(v * 10 + 0.5) / 10) or "нет"))
                            if grew(v) then res = "global" return end
                        end
                    end
                end
            end

            -- -------- пробы DX (от ImGui не зависит) --------
            local function probeDx()
                if type(R.dxReady) ~= "function" or not R.dxReady() then
                    note("dx: нет функций render-библиотеки")
                    return
                end
                local pa = math.floor(basePx + 0.5)
                local pb = math.floor(basePx * 2 + 0.5)
                local wa, wb = R.dxW(probe, pa), R.dxW(probe, pb)
                note("dx " .. tostring(pa) .. "px=" .. tostring(wa)
                    .. " → " .. tostring(pb) .. "px=" .. tostring(wb))
                -- Запасной путь не перетирает уже проверенный ImGui-способ.
                if res == "none" and wa and wb and wa > 0 and wb > wa * 1.4 then res = "dx" end
            end

            -- маленькое окно за краем экрана: пробы ImGui обязаны быть в нём
            -- ВАЖНО: открываем окно НАПРЯМУЮ (im.Begin), а не через grndBegin:
            -- grndBegin ведёт счётчик endDepth для чужих «доводчиков» кадра, и
            -- лишний не закрытый им End потом уронил бы кадр (Mismatched Begin/End).
            local opened = false
            pcall(function()
                pcall(im.SetNextWindowPos, im.ImVec2(-3000, -3000), COND_ALWAYS)
                pcall(im.SetNextWindowSize, im.ImVec2(120, 60), COND_ALWAYS)
                local okb, res = pcall(im.Begin, "##grnd_txtprobe", nil,
                    wf("NoTitleBar", "NoResize", "NoMove", "NoCollapse",
                        "NoScrollbar", "NoScrollWithMouse", "NoInputs",
                        "NoFocusOnAppearing", "NoBringToFrontOnFocus"))
                -- Begin(false) означает «содержимое окна отсечено», а не
                -- отсутствие окна в стеке. CurrentWindow уже есть: замер
                -- допустим, и парный End ОБЯЗАТЕЛЕН даже за краем экрана.
                opened = okb and true or false
            end)
            if opened then
                pcall(probeImgui)
                pcall(im.End)
            else
                note("окно пробы не открылось")
            end
            pcall(probeDx)
            return res, resFont, table.concat(dbg, " · ")
        end


        local function drawReportHud()
            local H = GRND_REPHUD
            if not (H and H.enabled) then
                H.rect = nil
                H.pressPid = nil
                return false
            end
            local items = H.items or {}
            local n = #items
            local resX, resY = getScreenResolution()
            local vis = math.min(n, H.max or 12)

            -- ---------- ЕДИНЫЙ «Размер окна» ----------
            local basePx = tonumber(GRND_FONT and GRND_FONT.fontBase) or 16
            local scWant = H.clampScale(H.scale)
            -- ЧЕМ масштабируется текст в этом клиенте — определяем замером
            -- (см. GRND_REPHUD.detectTextMode). Перепроверяем, если способ
            -- не найден (шрифты могли появиться позже) или изменилась
            -- «лестница» шрифтов. Если способа нет вовсе — окно держим
            -- базового размера: растущее окно с мелким текстом выглядит
            -- сломанным, это и был прошлый дефект.
            local T = H.txt
            local ladN = 0
            if type(im.__grndFontLadder) == "table" then
                for _ in pairs(im.__grndFontLadder) do ladN = ladN + 1 end
            end
            if (not T) or (T.ladN ~= ladN)
                or (T.mode == "none" and (os.clock() - (T.at or 0)) > 5) then
                local m, f, dbg = H.detectTextMode(basePx)
                T = { mode = m, font = f, at = os.clock(), ladN = ladN,
                    forced = H.forceMode }   -- ручной выбор не теряем при переопросе
                if (not H.txt) or H.txt.mode ~= m then
                    pcall(print, "[GRND] репорт-оверлей: масштаб текста — " ..
                        (m == "none" and "НИ ОДИН способ не сработал"
                            or ("способ «" .. m .. "» — проверен замером")))
                    -- Замеры пробы пишем в лог MoonLoader сразу: по ним видно,
                    -- что именно умеет клиент (в том числе когда все способы
                    -- «молчат» и режим оказался none)
                    pcall(print, "[GRND] репорт-оверлей: пробы «РЕПОРТЫ» — "
                        .. tostring(dbg))
                end
                H.txt = T
            end
            local txtMode = T.mode
            local fontObj = T.font
            -- РУЧНОЙ ВЫБОР способа (команда /grnd hud mode …): если автовыбор
            -- ошибся в вашем клиенте, способ задаётся одной командой, без правки
            -- файла. Проверяем, что такой способ вообще возможен.
            local forced = H.forceMode
            if forced and (T.mode ~= forced or T.forced ~= forced) then
                local allow = (forced == "dx" or forced == "scale" or forced == "pushsize"
                    or forced == "push" or forced == "global" or forced == "none")
                if allow then
                    txtMode = forced
                    T.mode, T.forced = forced, forced
                    pcall(print, "[GRND] репорт-оверлей: способ задан вручную — «"
                        .. forced .. "» (/grnd hud mode auto вернёт автовыбор)")
                else
                    H.forceMode = nil
                end
            end
            -- «pushsize» нужен объект шрифта: если детектор его не дал — берём
            -- любой интерфейсный (иначе режим молча выродится в обычный текст)
            if txtMode == "pushsize" and not fontObj then
                fontObj = (GRND_FONT and GRND_FONT.fontObj) or im.__grndUiFont
                if not fontObj and type(im.__grndFontLadder) == "table" then
                    for _, f in pairs(im.__grndFontLadder) do fontObj = f break end
                end
                T.font = fontObj
            end
            if txtMode == "none" then scWant = 1.0 end
            -- «push»: шрифт берём из «лестницы» — он ЦЕЛОГО кегля и может быть
            -- на пиксель-два крупнее запрошенного. Окно считаем ровно под
            -- ФАКТИЧЕСКИЙ кегль, иначе текст не влезет в пропорции.
            local fontPick, fontPx = nil, nil
            if txtMode == "push" then
                if type(grndUiFontPick) == "function" then
                    local okp, rf, rs = pcall(grndUiFontPick, math.floor(basePx * scWant + 0.5))
                    if okp then fontPick, fontPx = rf, tonumber(rs) end
                end
                if fontPick and fontPx and fontPx >= 9 and fontPx <= 40 then
                    scWant = H.clampScale(fontPx / basePx)
                else
                    scWant = 1.0                 -- шрифт не дали — как в «none»
                    txtMode = "none"
                end
            end
            -- «dx»: текст рисует render-библиотека (GDI) СВОИМ шрифтом ровно
            -- этого кегля. Кегль целый, поэтому и окно (22.5 × кегль), и
            -- буквы всегда совпадают — тот самый «шаг в шаг». Этот путь не
            -- зависит от ImGui вообще, поэтому работает и там, где ImGui-кегль
            -- не меняется ничем.
            local dxPx = nil
            if txtMode == "dx" then
                dxPx = math.floor(basePx * scWant + 0.5)
                if dxPx < 8 then dxPx = 8 elseif dxPx > 40 then dxPx = 40 end
                if H.dxFont(dxPx) then
                    scWant = H.clampScale(dxPx / basePx)
                else
                    scWant = 1.0                 -- шрифт не создался — как в «none
                    txtMode = "none"
                end
            end
            -- сколько строк влезет в экран при этом размере (окно не должно
            -- уезжать за нижний край: при крупном размере строки выше)
            local M0 = H.metrics(scWant, basePx, 0)
            -- v1.17: в высоте окна теперь есть поля тени (2*sh) — учитываем их,
            -- иначе список «не доезжал» до нижнего края экрана на пару строк
            local fitRows = math.floor((resY - 2 * (M0.sh or 0) - M0.headH - 2 * M0.gap)
                / math.max(1, M0.rowH))
            if fitRows < 0 then fitRows = 0 end
            if vis > fitRows then vis = fitRows end
            if vis > n then vis = n end
            -- метрики окна: us — масштаб, от него считаются ВСЕ размеры оверлея
            local M = H.metrics(scWant, basePx, vis)
            local W, rowH, headH, pad, Hgt = M.W, M.rowH, M.headH, M.pad, M.Hgt
            local us = M.us
            local function S(v) return math.floor(v * us + 0.5) end

            -- ---------- мышь и позиция окна ----------
            -- Позиция нужна и тексту, и DX-слою: DX рисует по АБСОЛЮТНЫМ
            -- координатам, поэтому px/py считаем ДО обёрток вывода текста.
            local down = (GRND_MOUSE and GRND_MOUSE.down) and true or false
            local was = H.mouseWasDown and true or false
            local justDown = down and not was
            local justUp = (not down) and was
            H.mouseWasDown = down

            local px = tonumber(H.x) or 16
            local py = tonumber(H.y) or 90
            if H.dragging then
                if down then
                    px = GRND_MOUSE.x - (H.dragDX or 0)
                    py = GRND_MOUSE.y - (H.dragDY or 0)
                else
                    H.dragging = false
                    pcall(grndCamCfgSave)
                end
            end
            px = math.max(0, math.min(resX - W, px))
            py = math.max(0, math.min(resY - Hgt, py))
            H.x, H.y = px, py
            H.rect = { x = px, y = py, w = W, h = Hgt }
            -- ---------- текст: тем способом, который РАБОТАЕТ ----------
            -- В «pushsize» (ImGui 1.92+: PushFont(font, size)) и «push»
            -- (готовый шрифт «лестницы») размер задаёт сам шрифт, поэтому
            -- окно рисует текст нажатым шрифтом, fsc = 1. В «scale» —
            -- растяжка SetWindowFontScale, как в uiText. В «global» —
            -- масштаб ставится на весь кадр текста окна и снимается.
            -- В «dx» кегль задаёт GDI-шрифт (создаём его под каждую надпись).
            local dxMode = (txtMode == "dx")
            local canScale = (type(im.SetWindowFontScale) == "function")
                and (type(im.CalcTextSize) == "function")
            -- в «scale» размер задаёт SetWindowFontScale, в «pushsize» — размер,
            -- переданный в PushFont(font, size): там коэффициент нужен обоим.
            -- В «push»/«global»/«none» ПОДмасштабы невозможны (второй механизм
            -- в клиенте не работает) — тогда весь текст окна одного размера,
            -- иначе замер и отрисовка разошлись бы и подписи вылезли.
            local subOK = (txtMode == "scale" or txtMode == "pushsize")
            local fsc = subOK and us or 1
            local function tk(sc) return subOK and ((sc or 1) * fsc) or 1 end
            -- кегль GDI-шрифта под конкретную надпись (целый: так рисует GDI,
            -- и так же мы его ЗАМЕРИМ — замер и вывод всегда совпадают)
            local function dxP(sc)
                local v = math.floor((dxPx or basePx) * (sc or 1) + 0.5)
                if v < 7 then v = 7 elseif v > 40 then v = 40 end
                return v
            end
            -- v1.16: высота надписи в текущем режиме — ЗАМЕР того шрифта,
            -- которым надпись реально рисуется. Раньше это была одна
            -- переменная для строк (lineH), а шапка и «пустое» состояние
            -- прижимались к фиксированным отступам S(9)/S(4) — из-за этого
            -- одни надписи стояли выше, другие ниже своей полосы.
            -- Теперь ЛЮБАЯ надпись окна центрируется по своей полосе одной
            -- и той же функцией — вертикали совпадают на любом размере.
            local function rhH(sc)
                sc = sc or 1
                if dxMode then
                    return H.dxH(dxP(sc)) or math.max(1, math.floor(M.fpx * sc + 0.5))
                end
                return M.fpx
            end
            local lineH = rhH(1)
            -- нажать шрифт «лестницы» на весь кадр окна (режим «push»)
            local fontPushed = false
            if txtMode == "push" and fontPick
                and type(im.PushFont) == "function" and type(im.PopFont) == "function" then
                fontPushed = pcall(im.PushFont, fontPick) and true or false
            end
            -- глобальный масштаб шрифта на время окна (режим «global»)
            local ioObj, ioOld = nil, nil
            if txtMode == "global" and type(im.GetIO) == "function" then
                local okio, io = pcall(im.GetIO)
                if okio and io then
                    ioObj = io
                    local okGet, old = pcall(function() return io.FontGlobalScale end)
                    ioOld = okGet and old or 1
                    if not pcall(function() io.FontGlobalScale = ioOld * us end) then
                        ioObj = nil
                    end
                end
            end
            -- ширина текста РОВНО тем, чем он будет нарисован
            local function rhW(s, sc)
                s = tostring(s or "")
                if dxMode then
                    local w = H.dxW(s, dxP(sc))
                    if w and w > 0 then return w end
                    return grndTextW(s) * (dxP(sc) / basePx)
                end
                local k = tk(sc)
                if txtMode == "pushsize" and fontObj then
                    local ok = pcall(im.PushFont, fontObj, basePx * k)
                    if ok then
                        local okm, a = pcall(im.CalcTextSize, s)
                        pcall(im.PopFont)
                        if okm then
                            local ta = type(a)
                            local w = (ta == "table" or ta == "cdata") and tonumber(a.x) or tonumber(a)
                            if w and w > 0 then return w end
                        end
                    else
                        pcall(im.PopFont)
                    end
                elseif txtMode == "scale" and canScale and k ~= 1 then
                    pcall(im.SetWindowFontScale, k)
                    local ok, a = pcall(im.CalcTextSize, s)
                    pcall(im.SetWindowFontScale, 1)
                    if ok then
                        local ta = type(a)
                        local w = (ta == "table" or ta == "cdata") and tonumber(a.x) or tonumber(a)
                        if w and w > 0 then return w end
                    end
                end
                -- push / global / none: шрифт уже нужного размера
                return grndTextW(s) * k
            end
            local function rhText(x, y, s, col, sc)
                if dxMode then
                    -- DX: абсолютные координаты, цвет — ARGB
                    local r, g, b, a
                    -- mimgui ImVec4 — cdata, не Lua-таблица. Иначе
                    -- цвета терялись и весь DX-текст становился белым.
                    if type(col) == "table" or type(col) == "cdata" then
                        if col.w ~= nil then
                            r, g, b, a = col.x * 255, col.y * 255, col.z * 255, col.w * 255
                        else
                            r, g, b, a = col.r, col.g, col.b, col.a
                        end
                    end
                    H.dxText(s, px + x, py + y, r or 255, g or 255, b or 255, a or 255, dxP(sc))
                    return
                end
                local k = tk(sc)
                if txtMode == "pushsize" and fontObj then
                    im.SetCursorPos(im.ImVec2(x, y))
                    local npush = 0
                    if grndPushCol(im.Col and im.Col.Text, col) then npush = 1 end
                    if pcall(im.PushFont, fontObj, basePx * k) then
                        if im.TextUnformatted then pcall(im.TextUnformatted, tostring(s))
                        elseif im.Text then pcall(im.Text, tostring(s)) end
                        pcall(im.PopFont)
                    else
                        pcall(im.PopFont)
                    end
                    if npush > 0 then grndPopCol(npush) end
                    return
                end
                return uiText(x, y, s, col, k)
            end
            -- обрезка надписи по ширине (без разрыва UTF-8-символов)
            local function rhFit(s, maxW, sc)
                if rhW(s, sc) <= maxW then return s end
                local out = ""
                for ch in tostring(s):gmatch("[%z\1-\127\194-\244][\128-\191]*") do
                    if rhW(out .. ch .. "…", sc) > maxW then break end
                    out = out .. ch
                end
                if out == "" then return "…" end
                return out .. "…"
            end
            -- УКРАШЕНИЯ и подложка. В DX-режиме их тоже рисует render-
            -- библиотека: ImGui-слой ложится ПОВЕРХ DX-текста, и фон,
            -- нарисованный ImGui, закрыл бы надписи (проверено в килл-листе).
            local function dxr(x, y, w, h, r, g, b, a)
                if dxMode then H.dxRect(px + x, py + y, w, h, r, g, b, a) end
            end

            im.SetNextWindowPos(im.ImVec2(px, py), COND_ALWAYS)
            im.SetNextWindowSize(im.ImVec2(W, Hgt), COND_ALWAYS)
            local styleN, colorN = 0, 0
            if grndPushStyleF(im.StyleVar and im.StyleVar.WindowRounding, S(12)) then styleN = styleN + 1 end
            if grndPushStyleV2(im.StyleVar and im.StyleVar.WindowPadding, 0, 0) then styleN = styleN + 1 end
            if grndPushCol(im.Col and im.Col.WindowBg, rgba(0, 0, 0, 0)) then colorN = colorN + 1 end
            local flags = wf("NoTitleBar", "NoResize", "NoMove", "NoCollapse",
                "NoScrollbar", "NoScrollWithMouse", "NoInputs",
                "NoFocusOnAppearing", "NoBringToFrontOnFocus")
            -- v1.15.53: в DX-режиме окно обязано быть ПОЛНОСТЬЮ прозрачным —
            -- DX-текст лежит НИЖЕ ImGui-слоя, и любой (пусть даже чуть
            -- заметный) фон окна закрыл бы надписи. grndBeginTransparent
            -- гасит и фон, и рамку — им же рисуется килл-лист.
            local opened
            if dxMode then
                opened = grndBeginTransparent("##grnd_rephud", flags)
            else
                opened = grndBegin("##grnd_rephud", flags)
            end
            if opened then
                local pos = im.GetWindowPos()
                local dl = im.GetWindowDrawList()
                local function at(x, y) return im.ImVec2(pos.x + x, pos.y + y) end
                -- ---------- ЗАЛИВКА «ПИЛЮЛЬ» / ЧИПОВ (v1.17) ----------
                -- ВАЖНО про слои: в DX-режиме render-библиотека рисует СВОЙ
                -- слой ПОД ImGui, и если заливку сделать ещё и средствами
                -- ImGui, полупрозрачный прямоугольник ляжет ПОВЕРХ DX-текста
                -- и подкрасит буквы. Поэтому вызов ровно один: DX-скругление
                -- (а если его нет — простой DX-прямоугольник), иначе ImGui.
                local function rfill(x, y, w, h, rr, r, g, b, al)
                    if dxMode then
                        local okR = H.dxRoundGrad
                            and H.dxRoundGrad(px + x, py + y, w, h, rr,
                                { r, g, b, al }, { r, g, b, al }, 1, 2)
                        if not okR then H.dxRect(px + x, py + y, w, h, r, g, b, al) end
                    else
                        roundRect(dl, at(x, y), at(x + w, y + h), col32(r, g, b, al), rr)
                    end
                end
                -- =================================================
                --  v1.17: «СТЕКЛЯННАЯ» ПАНЕЛЬ
                --  Геометрия панели отсчитывается от sh — поля тени внутри
                --  окна. Панель меньше окна на sh с каждой стороны, поэтому
                --  мягкая тень и скруглённые углы НИКОГДА не обрезаются
                --  краем ImGui-окна; вся контентная сетка и мышь тоже
                --  живут в координатах панели (0..Wp), а не окна.
                -- =================================================
                local sh  = M.sh or 0
                local Wp, Hp = W - 2 * sh, Hgt - 2 * sh
                local rad = math.min(S(14), math.floor(Hp / 2))
                -- ---------- ЕДИНАЯ КОНТЕНТНАЯ РАМКА ----------
                -- Заголовок, бейдж-счётчик, разделитель, линия-акцент и все
                -- строки начинаются с ОДНОЙ вертикали, и каждая надпись
                -- центрируется по своей полосе.
                local contentL = pad
                local contentR = Wp - pad
                local TH_ACC = TH.accent or { 164, 112, 224 }
                local TH_ACC2 = TH.accent2 or TH_ACC
                -- v1.18.00: тёплый цвет пометки «на репорт не ответили» (бот)
                local TH_LATE = TH.late or { 240, 122, 132 }
                -- ---------- ПАНЕЛЬ ----------
                -- СЛОИ (важно): render-библиотека пишет СВОЙ слой ПОД ImGui.
                -- Поэтому в DX-режиме панель рисуем ТОЛЬКО DX-примитивами, а в
                -- обычном — только ImGui: если сделать «на всякий случай» оба,
                -- непрозрачный ImGui-фон ляжет поверх DX-текста и закроет его.
                local p1, p2 = at(sh, sh), at(sh + Wp, sh + Hp)
                -- v1.18.00: тень, «стеклянный» блик и тонкий кант по периметру
                -- УБРАНЫ (по просьбе): вокруг окна оставались тонкие
                -- полупрозрачные полосы по краям и углам, а блик по шапке
                -- выглядел лишним. Панель — чистая градиентная плашка со
                -- скруглением, плюс акцентная линия сверху.
                if dxMode then
                    if not (H.dxRoundGrad and H.dxRoundGrad(px + sh, py + sh, Wp, Hp, rad,
                        { 25, 22, 36, 252 }, { 13, 11, 20, 252 }, 8, 1)) then
                        H.dxRect(px + sh, py + sh, Wp, Hp, 17, 14, 26, 252)
                    end
                else
                    if not H.vgrad(dl, p1, p2, col32(25, 22, 36, 252), col32(13, 11, 20, 252)) then
                        roundRect(dl, p1, p2, col32(17, 14, 26, 252), rad)
                    end
                end
                -- v1.19.09: градиентная линия-акцент по верхнему краю панели
                -- убрана (просьба заказчика: лишняя полоса сверху). Раньше
                -- здесь рисовалась полоса 3 px акцентом темы — и в ImGui-пути,
                -- и в DX-пути (render-библиотека). Панель остаётся чистой
                -- градиентной плашкой со скруглением.

                local headTy = math.max(0, math.floor((headH - lineH) / 2)) + sh
                local headCy = headTy + math.floor(lineH / 2)

                -- ШАПКА: пульсирующая точка · заголовок · бейдж-счётчик
                local pulse = 0.72 + 0.28 * math.abs(math.sin(os.clock() * 2.6))
                local dotAl = (n > 0) and math.floor(160 + 95 * pulse) or 70
                -- точка-индикатор стоит в поле СЛЕВА от текста, а сам
                -- заголовок начинается ровно с contentL — на одной линии
                -- со временем в строках списка.
                local dotSz = math.max(4, S(5))
                local dotX = sh + math.max(0, contentL - dotSz - S(4))
                local dotY = headCy - math.floor(dotSz / 2)
                if dxMode then
                    dxr(dotX, dotY, dotSz, dotSz,
                        TH_ACC[1], TH_ACC[2], TH_ACC[3], dotAl)
                else
                    dl:AddCircleFilled(at(dotX + dotSz / 2, headCy), dotSz / 2 + 0.2,
                        (n > 0)
                            and col32(TH_ACC[1], TH_ACC[2], TH_ACC[3], dotAl)
                            or  col32(255, 255, 255, 70))
                end
                rhText(sh + contentL, headTy, "РЕПОРТЫ", c4(TH.textHi), 1.0)

                local cnt = tostring(n)
                local cw = rhW(cnt, 0.9)
                local badgeH = S(17)
                local bw2 = math.max(S(22), cw + S(14))
                local bx2 = contentL + rhW("РЕПОРТЫ") + S(10)
                -- бейдж и его цифра — по центру той же полосы шапки
                local by2 = math.floor(headCy - badgeH / 2)
                local badgeTxtH = dxMode and rhH(0.9) or math.floor(M.fpx * 0.9 + 0.5)
                local byTxt = by2 + math.floor((badgeH - badgeTxtH) / 2)
                local badgeRad = math.floor(badgeH / 2)
                if n > 0 then
                    rfill(sh + bx2, by2, bw2, badgeH, badgeRad,
                        TH_ACC[1], TH_ACC[2], TH_ACC[3], 235)
                    rhText(sh + bx2 + (bw2 - cw) / 2, byTxt, cnt, rgba(10, 16, 14, 255), 0.9)
                else
                    rfill(sh + bx2, by2, bw2, badgeH, badgeRad, 255, 255, 255, 18)
                    rhText(sh + bx2 + (bw2 - cw) / 2, byTxt, cnt, c4(TH.textDim), 0.9)
                end

                -- ручка перетаскивания: сетка точек справа — прижата к правому
                -- краю контентной рамки и отцентрирована по высоте шапки
                local handW, handH = S(10) + 2, S(5) + 2
                local hdx = sh + contentR - handW
                local hdy = math.max(sh, math.floor((headH - handH) / 2) + sh)
                for gx = 0, 2 do
                    for gy = 0, 1 do
                        if dxMode then
                            dxr(hdx + gx * S(5), hdy + gy * S(5), 2, 2, 255, 255, 255, 60)
                        else
                            dl:AddCircleFilled(at(hdx + gx * S(5), hdy + gy * S(5)), 1.4 * us,
                                col32(255, 255, 255, 60))
                        end
                    end
                end

                local headRect = { x = px + sh, y = py + sh, w = Wp, h = headH }
                if justDown and grndMouseInside(headRect) then
                    H.dragging = true
                    H.pressPid = nil
                    H.dragDX = GRND_MOUSE.x - px
                    H.dragDY = GRND_MOUSE.y - py
                end

                -- разделитель под шапкой — по той же рамке, что и надписи,
                -- и с «затуханием» к краям (не перерезает панель пополам)
                local sepH = math.max(1, S(1))
                local sepY = sh + headH
                if dxMode then
                    dxr(sh + contentL, sepY, contentR - contentL, sepH, 255, 255, 255, 16)
                else
                    -- градиент градиентом: у ImGui-обёрток MultiColor бывает
                    -- недоступен — тогда обычная тонкая линия
                    local cMid = col32(255, 255, 255, 16)
                    if not H.hgrad(dl, at(sh + contentL, sepY),
                        at(sh + contentR, sepY + sepH),
                        col32(255, 255, 255, 0), cMid) then
                        dl:AddRectFilled(at(sh + contentL, sepY),
                            at(sh + contentR, sepY + sepH), cMid)
                    end
                end

                -- Строки списка начинаются ровно на M.gap ниже шапки — сверху
                -- и снизу от списка одинаковый отступ.
                local y = sh + headH + M.gap
                -- ---------- КОЛОНКИ СПИСКА (считаются ДО отрисовки) ----------
                -- Ширины колонок берутся по видимым строкам, поэтому у ВСЕХ
                -- строк время, ник и [ID] стоят на одних и тех же x: список
                -- выглядит таблицей. Раньше каждый элемент шёл сразу за
                -- предыдущим, и колонка [ID] зависела от длины ника в СВОЕЙ
                -- строке — она собиралась «лесенкой» (213 / 171 / 163 px),
                -- а подсказка «взять репорт» появлялась то в одной строке,
                -- то в другой. Теперь обе колонки общие для всего списка.
                local hint, hintShort = "взять репорт", "взять"
                local gTime, gNick, gId = 0, 0, 0
                for i = 1, vis do
                    local it = items[i] or {}
                    local w = rhW(tostring(it.time or ""), 0.94)
                    if w > gTime then gTime = w end
                    w = rhW(tostring(it.nick or "?"), 1.0)
                    if w > gNick then gNick = w end
                    w = rhW("[" .. tostring(it.pid) .. "]", 1.0)
                    if w > gId then gId = w end
                end
                -- Подсветка строки-пилюли: чуть шире контентной рамки и уже
                -- строки, поэтому подсветка не «слипается» с соседней строкой.
                local hlPad = S(9)
                local hlL = sh + math.max(0, contentL - hlPad)
                local hlR = sh + math.min(Wp, contentR + hlPad)
                local hlH = math.max(1, rowH - S(5))
                local hlRad = math.min(S(9), math.floor(hlH / 2))
                local hlLn = S(3)
                -- «взять репорт» — чип: подпись + плашка с подсветкой при наведении
                local chipPadX, chipPadY = S(10), math.max(2, S(4))
                local chipMaxW = math.max(S(40), math.floor(Wp * 0.42))
                local hintW = rhW(hint, 0.92)
                local chipW = math.min(hintW + 2 * chipPadX, chipMaxW)
                local chipH = math.min(rowH - S(4), rhH(0.92) + 2 * chipPadY)
                -- v1.19.04: «намазка» (акцентная плашка) под [ID] убрана —
                -- ID просто текст. Поля в 2 px хватает, чтобы подпись не
                -- липла к чипу «взять репорт».
                local padIdX = S(2)
                local idPillW = gId + 2 * padIdX
                local idPillH = math.min(rowH, math.max(rhH(1.0) + S(6), S(18)))
                local gapA, gapB, gapC = S(8), S(6), S(8)
                local xTime = contentL
                local xNick = xTime + gTime + gapA
                -- место под ники, если правую колонку отдать чипу
                local nickWithHint = (contentR - gapC - chipW - padIdX - gId - padIdX - gapB) - xNick
                -- Если с полной подписью ники не влезают, а с короткой — влезают,
                -- показываем короткую («взять»): и ники целы, и действие видно.
                if gNick > nickWithHint then
                    local w2 = rhW(hintShort, 0.92)
                    local chipW2 = math.min(w2 + 2 * chipPadX, chipMaxW)
                    local nwh2 = (contentR - gapC - chipW2 - padIdX - gId - padIdX - gapB) - xNick
                    if gNick <= nwh2 or nwh2 >= gNick * 0.75 then
                        hint, hintW, chipW, nickWithHint = hintShort, w2, chipW2, nwh2
                    end
                end
                local showHint, nickCol
                if gNick <= nickWithHint then
                    showHint, nickCol = true, gNick
                elseif nickWithHint >= gNick * 0.75 then
                    showHint, nickCol = true, math.max(0, nickWithHint)
                else
                    showHint = false
                    nickCol = math.min(gNick, contentR - xNick - gapB - idPillW)
                    if nickCol < 0 then nickCol = 0 end
                end
                local xId = xNick + nickCol + gapB
                local chipX = contentR - chipW
                local chipY = math.floor((rowH - chipH) / 2)

                if vis == 0 then
                    -- пустое состояние: две строки по центру области под
                    -- шапкой — приглушённый заголовок ожидания и подсказка,
                    -- что делать (раньше была одна строка и «дырка» вокруг)
                    local eTitle = "ожидание обращений"
                    local eHint  = "новые репорты появятся здесь"
                    local eAl = math.floor(90 + 120 * pulse)
                    local eH1 = math.max(1, math.floor(M.fpx * 0.9 + 0.5))
                    local eH2 = math.max(1, math.floor(M.fpx * 0.82 + 0.5))
                    local eGap2 = S(10)
                    local areaTop = sh + headH
                    local areaH = math.max(0, (sh + Hp) - areaTop)
                    local blkH = eH1 + eGap2 + eH2
                    local eT1 = areaTop + math.max(0, math.floor((areaH - blkH) / 2))
                    local eT2 = eT1 + eH1 + eGap2
                    local eC = eT1 + math.floor(eH1 / 2)
                    local eDot = math.max(4, S(5))
                    local eGap = S(8)
                    local w1 = rhW(eTitle, 0.9)
                    local w2 = rhW(eHint, 0.82)
                    local g1X = math.floor((Wp - (eDot + eGap + w1)) / 2)
                    if dxMode then
                        dxr(sh + g1X, eC - math.floor(eDot / 2), eDot, eDot,
                            TH_ACC[1], TH_ACC[2], TH_ACC[3], eAl)
                    else
                        dl:AddCircleFilled(at(sh + g1X + eDot / 2, eC), eDot / 2 + 0.2,
                            col32(TH_ACC[1], TH_ACC[2], TH_ACC[3], eAl))
                    end
                    rhText(sh + g1X + eDot + eGap, eT1, eTitle, c4(TH.textMuted), 0.9)
                    rhText(sh + math.floor((Wp - w2) / 2), eT2, eHint, c4(TH.textDim), 0.82)
                end
                for i = 1, vis do
                    local it = items[i]
                    -- Пилюля строки И клик — по одной геометрии (раньше
                    -- прямоугольник клика был шире закрашенного — строка
                    -- «срабатывала» на пустом месте).
                    local rowRect = { x = px + hlL, y = py + y, w = hlR - hlL, h = rowH }
                    local rowHov = (not H.dragging) and grndMouseInside(rowRect)
                    -- курсор в координатах ПАНЕЛИ (учитываем поле тени sh)
                    local hoverX = GRND_MOUSE.x - px - sh
                    local chipHov = rowHov and hoverX >= chipX - hlPad
                        and hoverX <= chipX + chipW + hlPad
                    if rowHov then
                        -- подсветка строки-пилюли + акцентная «таблетка» слева
                        local hlY = y + S(2)
                        rfill(hlL, hlY, hlR - hlL, hlH, hlRad,
                            TH_ACC[1], TH_ACC[2], TH_ACC[3], 26)
                        local lx = hlL + S(2)
                        local lyH = math.max(2, hlH - 2 * S(5))
                        local lyT = hlY + math.floor((hlH - lyH) / 2)
                        rfill(lx, lyT, hlLn, lyH, math.floor(hlLn / 2),
                            TH_ACC[1], TH_ACC[2], TH_ACC[3], 210)
                    end
                    if (not H.dragging) then
                        if justDown and rowHov then
                            H.pressPid = tostring(it.pid)
                        elseif justUp and H.pressPid and tostring(H.pressPid) == tostring(it.pid)
                            and rowHov then
                            pcall(grndRepHudOpenItem, it)
                            H.pressPid = nil
                        end
                    end
                    -- СТРОКА: [время] [ник] [ID-пилюля] …… [чип «взять репорт»]
                    -- Каждая надпись центрируется по своей высоте: время (0.94)
                    -- и чип (0.92) мельче ника (1.0) — при общем верхнем крае
                    -- они «висели» бы на пиксель-два выше строки.
                    local function rowTy(sc)
                        return y + math.max(0, math.floor((rowH - rhH(sc)) / 2))
                    end
                    local idPillY = y + math.floor((rowH - idPillH) / 2)
                    local idTy = idPillY + math.max(0, math.floor((idPillH - rhH(1.0)) / 2))
                    local tstr = tostring(it.time or "")
                    local idstr = "[" .. tostring(it.pid) .. "]"
                    local nick = tostring(it.nick or "?")
                    if nickCol > 0 then nick = rhFit(nick, nickCol, 1.0) end
                    -- xTime/xNick/xId/chipX — координаты В ПАНЕЛИ, при выводе
                    -- добавляем sh (поле тени внутри ImGui-окна)
                    -- v1.18.00: репорт, по которому бот написал «НА РЕПОРТ НЕ
                    -- ОТВЕТИЛИ ЗА N СЕКУНД!», помечается тёплым цветом —
                    -- строку видно сразу, не читая текст жалобы.
                    rhText(sh + xTime, rowTy(0.94), tstr,
                        it.late and c4(TH_LATE) or c4(TH.textMuted), 0.94)
                    rhText(sh + xNick, rowTy(1.0), nick, c4(TH.textHi), 1.0)
                    -- [ID] — просто текст (v1.19.04: плашку-«намазку» убрали).
                    -- Просроченный ботом репорт по-прежнему виден: ID и
                    -- время краснеют, ник остаётся обычным.
                    rhText(sh + xId, idTy, idstr,
                        it.late and c4(TH_LATE) or c4(TH_ACC), 1.0)
                    if showHint then
                        -- чип подсказки: подсвечивается, когда курсор над ним
                        if chipHov then
                            rfill(sh + chipX, y + chipY, chipW, chipH,
                                math.floor(chipH / 2),
                                TH_ACC[1], TH_ACC[2], TH_ACC[3], 22)
                        end
                        local cx = sh + chipX + math.floor((chipW - hintW) / 2)
                        local cy = y + chipY + math.max(0, math.floor((chipH - rhH(0.92)) / 2))
                        rhText(cx, cy, hint,
                            chipHov and c4(TH.textHi) or c4(TH.textDim), 0.92)
                    end
                    y = y + rowH
                end
                if justUp then H.pressPid = nil end
            end
            if endDepth > 0 then endDepth = endDepth - 1; pcall(im.End) end
            grndPopCol(colorN)
            grndPopStyle(styleN)
            -- снять нажатый шрифт «лестницы» и глобальный масштаб: следующие
            -- окна кадра должны рисоваться как обычно
            if fontPushed then pcall(im.PopFont) end
            if ioObj then pcall(function() ioObj.FontGlobalScale = ioOld end) end
            return false
        end

        -- =============================================================
        --  МОДУЛЬ 13: отрисовка кастомного рекона (слежка) - MODERN UI
        --  Полностью переработанная система с вкладками и современным дизайном
        -- =============================================================
        -- =============================================================
        --  ИСТОЧНИКИ ДАННЫХ (v1.11.0): реальные, не заглушки.
        --  Координаты/скин/оружие/пинг — штатный API MoonLoader;
        --  ХП/броня/авто — проверенная память SAMP (модуль 13b).
        --  Все функции защищены: при недоступности данных возвращают
        --  nil/0 и окно продолжает работать.
        -- =============================================================
        local localPlayer = 0  -- обновляется каждый кадр в drawRecon
        local function playerIsValid(id)
            if type(id) ~= "number" or id < 0 or id > 1003 then return false end
            local SN = _G.grndSpecNative
            if not SN or not SN.pedOf then return false end
            return SN.pedOf(id) ~= nil
        end
        local function getPlayerPos(id)
            local SN = _G.grndSpecNative
            local ped = SN and SN.pedOf and SN.pedOf(id) or nil
            if not ped or type(getCharCoordinates) ~= "function" then return nil end
            local ok, x, y, z = pcall(getCharCoordinates, ped)
            if ok and type(x) == "number" and type(y) == "number" and type(z) == "number" then
                return {x = x, y = y, z = z}
            end
            return nil
        end
        local function getPlayerPing(id)
            if type(sampGetPlayerPing) == "function" then
                local ok, v = pcall(sampGetPlayerPing, id)
                if ok and type(v) == "number" and v >= 0 and v < 100000 then return v end
            end
            return nil
        end
        local function getPlayerSkin(id)
            local SN = _G.grndSpecNative
            local ped = SN and SN.pedOf and SN.pedOf(id) or nil
            if not ped or type(getCharModel) ~= "function" then return nil end
            local ok, m = pcall(getCharModel, ped)
            if ok and type(m) == "number" and m >= 0 and m < 20000 then return m end
            return nil
        end
        local function getPlayerVehicle(id)
            local SN = _G.grndSpecNative
            if SN and SN.getVehicleId then
                return SN.getVehicleId(id)
            end
            return nil
        end
        local function getVehicleModel(veh)
            local SN = _G.grndSpecNative
            if SN and SN.getVehicleModel and type(veh) == "number" then
                return SN.getVehicleModel(veh)
            end
            return nil
        end
        local function getVehicleName(model)
            -- Честно: показываем модельный ID (названия моделей в клиенте
            -- не читаются штатными средствами)
            if type(model) == "number" and model > 0 then
                return "Модель " .. tostring(model)
            end
            return nil
        end
        local function getPlayerHealth(id)
            local SN = _G.grndSpecNative
            if SN and SN.getHealth then return SN.getHealth(id) end
            return nil
        end
        local function getPlayerArmor(id)
            local SN = _G.grndSpecNative
            if SN and SN.getArmor then return SN.getArmor(id) end
            return nil
        end
        local function getPlayerWeaponSlot(id, slot)
            local SN = _G.grndSpecNative
            local ped = SN and SN.pedOf and SN.pedOf(id) or nil
            if not ped or type(getCharWeaponInSlot) ~= "function" then return nil end
            local ok, w = pcall(getCharWeaponInSlot, ped, slot)
            if ok and type(w) == "number" and w > 0 and w < 100 then return w end
            return nil
        end
        local function getWeaponName(weapon)
            if type(weapon) == "number" and weapon > 0 then
                return "Оружие #" .. tostring(weapon)
            end
            return nil
        end
        local function getPlayerAmmo(id, slot)
            local SN = _G.grndSpecNative
            local ped = SN and SN.pedOf and SN.pedOf(id) or nil
            if not ped or type(getCharWeaponInSlot) ~= "function" then return nil end
            local ok, w, ammo = pcall(getCharWeaponInSlot, ped, slot)
            if ok and type(w) == "number" and w > 0 and type(ammo) == "number" then
                return ammo
            end
            return nil
        end
        local function getInterior(id) return nil end
        local function getVW(id) return nil end
        local function setPlayerPos(id, x, y, z)
            if type(_G.setPlayerPos) == "function" then
                local ok, r = pcall(_G.setPlayerPos, id, x, y, z)
                return ok and (r and true or true) or false
            end
            return false
        end

        -- Глобальная функция: у grndMainBody уже почти достигнут лимит
        -- локальных переменных Lua 5.1 (200), поэтому не добавляем сюда
        -- ещё один local.
        function reconCopyNickname(text)
            local okF, ffi = pcall(require, "ffi")
            if not okF or not ffi then return false end
            local ansi = tostring(text or "")
            if type(grndToAnsi) == "function" then
                local okA, out = pcall(grndToAnsi, ansi)
                if okA and type(out) == "string" then ansi = out end
            end
            if ansi == "" then return false end
            pcall(function()
                ffi.cdef[[
                    int OpenClipboard(void* hWndNewOwner);
                    int EmptyClipboard(void);
                    void* GlobalAlloc(unsigned int uFlags, size_t dwBytes);
                    void* GlobalLock(void* hMem);
                    int GlobalUnlock(void* hMem);
                    void* SetClipboardData(unsigned int uFormat, void* hMem);
                    int CloseClipboard(void);
                    void* GlobalFree(void* hMem);
                ]]
            end)
            local ok, result = pcall(function()
                if ffi.C.OpenClipboard(nil) == 0 then return false end
                ffi.C.EmptyClipboard()
                local h = ffi.C.GlobalAlloc(0x0002, #ansi + 1) -- GMEM_MOVEABLE / CF_TEXT
                if h == nil then ffi.C.CloseClipboard(); return false end
                local p = ffi.C.GlobalLock(h)
                if p == nil then ffi.C.GlobalFree(h); ffi.C.CloseClipboard(); return false end
                ffi.copy(p, ansi, #ansi)
                ffi.cast("unsigned char*", p)[#ansi] = 0
                ffi.C.GlobalUnlock(h)
                if ffi.C.SetClipboardData(1, h) == nil then
                    ffi.C.GlobalFree(h)
                    ffi.C.CloseClipboard()
                    return false
                end
                ffi.C.CloseClipboard()
                return true
            end)
            return ok and result == true
        end

        local function drawRecon()
            local RC = GRND_RC
            if not RC or not RC.show or not im then return false end

            local function reconUtf(v)
                v = tostring(v or "")
                if type(grndToUtf) == "function" then
                    local ok, out = pcall(grndToUtf, v)
                    if ok and type(out) == "string" then return out end
                end
                return v
            end
            RC.imguiHealthy = false
            RC.imguiLastAt = os.clock()

            local id = tonumber(RC.id)
            if not id and GRND_SPEC and GRND_SPEC.active then
                id = tonumber(GRND_SPEC.id)
                RC.id = id
            end
            if not id then return false end

            local resX, resY = getScreenResolution()
            -- v1.11.9: компактное окно + перетаскивание за шапку
            -- v1.19.60: карточка рекона — раскладка как в образце заказчика:
            -- шапка «Ник [ID]» по центру, слева колонка с «моделью» и кнопками
            -- наказаний (JAIL, BAN, KICK, MUTE), справа — единый список строк.
            -- 3D-модель персонажа в ImGui нарисовать нельзя, поэтому на её
            -- месте — буква ника; «Оружие», «Патроны» и «AFK» в карточку не
            -- выводятся (просьба заказчика).
            -- v1.19.61: карточка рекона — по образцу заказчика.
            --   • ник слева, рядом ЗНАЧОК «копировать» (в игровом шрифте
            --     символа нет — рисуем две наложенные рамки сами);
            --   • место 3D-модели персонажа пустое: ImGui модель нарисовать
            --     не может, поэтому там НИЧЕГО нет (просьба заказчика);
            --   • справа — один прокручиваемый список: сначала характеристика
            --     игрока (Пинг, Здоровье, Броня, Скорость), затем
            --     полупрозрачная линия и ПОЛНАЯ статистика из /stats
            --     («Имя» в неё не входит — ник есть в шапке).
            --     «Оружие», «Патроны» и «AFK» не выводятся;
            --   • стрелка внизу сворачивает и разворачивает весь блок
            --     информации и статистики: в свёрнутом виде карточка
            --     складывается ВЛЕВО — остаётся узкая полоса с колонкой
            --     кнопок наказаний и со самой стрелочкой (v1.19.64).
            local pad = 14
            local HEAD = 34             -- шапка: ник слева + значок «копировать»
            local BOT = 22              -- низ: стрелка «свернуть/развернуть»
            -- состояние «развёрнуто/свёрнуто» живёт в RC: стрелка внизу его
            -- меняет, а свёрнутая карточка уезжает ВЛЕВО (правая часть
            -- складывается, стрелка остаётся на месте — внизу полосы)
            local openState = (RC.cardOpen ~= false)
            local Wfull = math.floor(math.max(400, math.min(460, resX * 0.28)))
            local LW = math.floor(Wfull * 0.30)  -- колонка кнопок наказаний
            local Wmini = pad + LW + 6  -- свёрнутая: остаётся только эта колонка
            local W = openState and Wfull or Wmini
            local RX = pad + LW + 12    -- с этой линии — колонка строк
            local RW = Wfull - pad - 12 - RX  -- ширина колонки строк
            local ROW_H = 24            -- высота строки сведений
            local ROWS_A = 4            -- характеристика игрока
            -- статистика: все поля ответа /stats (без «Имя» — ник есть в шапке)
            local ROWS_B = 15
            local DIV_H = 13            -- полупрозрачная линия между блоками
            local PUN_BH = 30           -- высота кнопки наказания
            local PUN_BG = 6            -- зазор между кнопками
            local PUN_TOP = 4           -- сколько кнопок в карточке
            local TOP_Y = HEAD + 6      -- верх списка и колонки кнопок
            local SCROLL_STEP = ROW_H   -- один оборот колеса = одна строка
            local H_MIN = 180           -- ниже карточка не сжимается
            -- ник в шапке: в свёрнутой карточке он короче (места меньше)
            local nickShort = openState and 18 or 8
            -- карточка сама загружает настройки наказаний (раньше это делала
            -- отдельная панель): оттуда приходит и тумблер «кнопки в карточке»
            if GRND_PUN and not GRND_PUN.loaded then pcall(GRND_PUN.load) end
            local punList = (GRND_PUN and GRND_PUN.barOn ~= false)
                and GRND_PUN.list or nil
            -- v1.19.64: порядок кнопок в карточке — ФИКСИРОВАННЫЙ:
            -- JAIL, BAN, KICK, MUTE. Раньше брались первые PUN_TOP записей
            -- из настроек, а там обычный порядок (JAIL, BAN, WARN, KICK,
            -- MUTE) — и кнопка MUTE в карточку не попадала вовсе
            local punOrder = { "JAIL", "BAN", "KICK", "MUTE", "WARN", "SKICK", "SBAN" }
            local punItems = {}
            if type(punList) == "table" then
                local used = {}
                for i = 1, #punOrder do
                    if #punItems >= PUN_TOP then break end
                    for j = 1, #punList do
                        local it = punList[j]
                        if it and not used[j] and tostring(it.id) == punOrder[i] then
                            used[j] = true
                            punItems[#punItems + 1] = it
                            break
                        end
                    end
                end
                -- наказания, которых нет в списке приоритета, — после них
                for j = 1, #punList do
                    if #punItems >= PUN_TOP then break end
                    if not used[j] and punList[j] then
                        used[j] = true
                        punItems[#punItems + 1] = punList[j]
                    end
                end
            end
            local punCnt = #punItems
            local punH = (punCnt > 0)
                and (punCnt * PUN_BH + (punCnt - 1) * PUN_BG) or 0
            local rowsH = ROWS_A * ROW_H + DIV_H + ROWS_B * ROW_H
            -- v1.19.62: панель наказаний прижата к шапке (была ниже — под
            -- пустым местом 3D-модели, из-за чего кнопки «уезжали» вниз)
            local leftTop = TOP_Y + 2
            local leftBottom = leftTop + punH
            -- v1.19.63: карточка кончается там же, где и панель наказаний
            -- («сделай меньше — на уровне конца всех кнопок»). Весь список
            -- строк живёт в окне прокрутки под шапкой.
            local contentH = leftBottom + BOT + 6
            -- Высота окна ограничена ЭКРАНОМ, а не содержимым: всё, что не
            -- влезло, живёт в окне прокрутки (шапка при этом не уезжает).
            local H_MAX = math.max(H_MIN, math.min(560, resY - 42))
            local H = math.max(H_MIN, math.min(H_MAX, contentH))
            local listTop = TOP_Y
            local listH = math.max(24, H - listTop - BOT - 4)
            local scrollMax = openState and math.max(0, rowsH - listH) or 0
            local scroll = math.max(0, math.min(scrollMax,
                tonumber(RC.scroll) or 0))
            RC.scroll = scroll
            -- рисуем и нажимаем только те строки, что видны ЦЕЛИКОМ (текст
            -- ImGui не режется нашей маской — половина строки, вылезшая за
            -- окно прокрутки, выглядела бы обрывком)
            local function inList(y0, h0)
                return openState and (y0 >= listTop - 0.5)
                    and (y0 + h0 <= listTop + listH + 0.5)
            end
            -- правый край значений и короткая шкала ХП/брони под ними
            local valueRight = W - pad - 12
            local barW = math.max(40, math.floor(RW * 0.35))
            local barX = valueRight - barW
            local px = resX - W - 24
            local py = math.max(22, math.floor((resY - H) / 2))
            if RC.posX and RC.posY then px, py = RC.posX, RC.posY end
            local valueX = math.floor(W * 0.51)
            local valueW = W - pad - valueX
            RC.activeTab = "overview"
            -- Курсор включается только правой кнопкой мыши.
            if RC.cursor == nil then RC.cursor = false end
            RC.windowPos = { x = px, y = py }
            RC.windowSize = { w = W, h = H }
            -- v1.19.59: колесо мыши над этим прямоугольником листает список
            -- (свёрнутый блок не листается — колесо уходит игре, как раньше)
            if openState and scrollMax > 0 then
                RC.scrollRect = { x = px + RX - 8, y = py + listTop,
                    w = math.min(RW + 20, W - RX - 4), h = listH }
            else
                RC.scrollRect = nil
            end
            RC.scrollStep = SCROLL_STEP   -- шаг прокрутки (его читает обработчик колеса)

            local function textValue(key, fallback)
                local v = RC.live and RC.live[key]
                if v ~= nil then
                    v = reconUtf(v)
                    if v ~= "" then return v end
                end
                return fallback or "—"
            end
            local function numberValue(key, fallback)
                local v = RC.live and RC.live[key]
                if v ~= nil then
                    v = tostring(v):gsub(",", ".")
                    local n = tonumber(v:match("[-+]?%d+%.?%d*"))
                    if n then return n end
                end
                return fallback
            end
            local function shortValue(v, maxChars)
                v = tostring(v or "—")
                if grndUtf8Len(v) <= maxChars then return v end
                local out, count = {}, 0
                for ch in v:gmatch("[%z\1-\127\194-\244][\128-\191]*") do
                    count = count + 1
                    if count >= maxChars then out[#out + 1] = "…"; break end
                    out[#out + 1] = ch
                end
                return table.concat(out)
            end
            local function clamp(v, lo, hi)
                v = tonumber(v) or 0
                if v < lo then return lo end
                if v > hi then return hi end
                return v
            end

            local nick = reconUtf(RC.nick or "Игрок")
            if nick == "" then nick = "Игрок" end
            local pingNum = getPlayerPing(id)
            -- v1.11.80: пинг меняется каждый кадр на ±1 — показываем
            -- устоявшееся значение, чтобы цифра не дрожала
            local pingStable = grndParamNum(id, "ping",
                pingNum or (tonumber(tostring(textValue("ping", "")):match("%d+")) or nil))
            -- в образце единицы не пишутся: пинг — просто число
            local ping = pingStable and tostring(math.floor(pingStable + 0.5))
                or tostring(textValue("ping", "—")):match("%d+") or "—"
            -- v1.11.80: значения проходят через сглаживание — серверный
            -- TextDraw и память игры дают близкие, но разные числа, из-за
            -- чего ХП/броня «тряслись» (99.6 / 100.0 туда-сюда).
            -- В образце ХП и броня — с одним знаком: «100.0», «40.0».
            local hpNum = grndParamNum(id, "hp", numberValue("hp", getPlayerHealth(id)))
            local armNum = grndParamNum(id, "arm", numberValue("arm", getPlayerArmor(id)))
            local hpText = hpNum and string.format("%.1f", hpNum) or "—"
            local armText = armNum and string.format("%.1f", armNum) or "—"
            -- v1.11.83: серверная скорость сглаживается окном ПО КАДРАМ
            -- (прошлая версия считала окно по os.clock — в игре это
            -- процессорное время, окно растянулось и показывало 0), а если
            -- сервер молчит или показывает 0, скорость берём у игры (км/ч).
            -- v1.19.61: в карточке — просто число, как в образце.
            local speed = grndSpeedDisplay(id, textValue("speed", ""), true)
            -- «Уровень» — только число уровня: если отдельного поля нет,
            -- берём его из «Уровень (EXP)» («18 (12345)» → «18»)
            local lvlRaw = textValue("rc_level", "")
            if lvlRaw == "" then
                lvlRaw = tostring(textValue("rc_level_exp", "—")):gsub("%s*%b()", "")
            end
            if lvlRaw == "" then lvlRaw = "—" end

            -- v1.19.63: окно можно взять за ЛЮБОЕ свободное место и утащить
            -- (шапка, строки, пустота слева, края). Кнопки наказаний, значок
            -- «копировать» и стрелка внизу — не «ручки»: по ним обычный клик.
            -- Тянем только при включённом курсоре (ПКМ): иначе ЛКМ-клик уходит
            -- в игру (выстрел) — тащить было бы нельзя. Позиция окна — экранная,
            -- курсор тоже, поэтому всё сравниваем в одних координатах.
            local title = shortValue(nick, nickShort) .. " [" .. tostring(id) .. "]"
            local titleW = grndTextW(title)
            local icRect = { x = px + pad + titleW + 10, y = py + 6, w = 22, h = 22 }
            local function onWidget(mx, my)
                -- значок «копировать»
                if mx >= icRect.x and mx <= icRect.x + icRect.w
                    and my >= icRect.y and my <= icRect.y + icRect.h then return true end
                -- кнопки наказаний
                local bxx = px + pad + 6
                local bw2 = LW - 12
                for i = 1, punCnt do
                    local byy = py + leftTop + (i - 1) * (PUN_BH + PUN_BG)
                    if mx >= bxx and mx <= bxx + bw2
                        and my >= byy and my <= byy + PUN_BH then return true end
                end
                -- стрелка «свернуть/развернуть»
                local ax = px + math.floor(W / 2) - 12
                local ay = py + H - BOT + 1
                if mx >= ax and mx <= ax + 24 and my >= ay and my <= ay + 18 then
                    return true
                end
                return false
            end
            local winRect = { x = px, y = py, w = W, h = H }
            if RC.cursor and GRND_MOUSE.down then
                if not RC.dragging and grndMouseInside(winRect)
                    and not onWidget(GRND_MOUSE.x, GRND_MOUSE.y) then
                    RC.dragging = true
                    RC.dragDX = GRND_MOUSE.x - px
                    RC.dragDY = GRND_MOUSE.y - py
                end
            elseif RC.dragging then
                RC.dragging = false
                pcall(grndCamCfgSave)   -- запомнили позицию окна
            end
            if RC.dragging then
                px = math.max(0, math.min(resX - W, GRND_MOUSE.x - (RC.dragDX or 0)))
                py = math.max(0, math.min(resY - H, GRND_MOUSE.y - (RC.dragDY or 0)))
                RC.posX, RC.posY = px, py
                -- окно уехало в этом же кадре: обновляем рамки (позиция окна,
                -- значок копирования, область колеса) — иначе при перетаске
                -- «отставали» на кадр
                RC.windowPos = { x = px, y = py }
                icRect.x, icRect.y = px + pad + titleW + 10, py + 6
                if openState and scrollMax > 0 then
                    RC.scrollRect = { x = px + RX - 8, y = py + listTop,
                        w = math.min(RW + 20, W - RX - 4), h = listH }
                end
            end

            im.SetNextWindowPos(im.ImVec2(px, py), COND_ALWAYS)
            im.SetNextWindowSize(im.ImVec2(W, H), COND_ALWAYS)
            local styleN, colorN = 0, 0
            if grndPushStyleV2(im.StyleVar and im.StyleVar.WindowPadding, 0, 0) then styleN = styleN + 1 end
            if grndPushStyleF(im.StyleVar and im.StyleVar.WindowRounding, 12) then styleN = styleN + 1 end
            if grndPushCol(im.Col and im.Col.WindowBg, rgba(0, 0, 0, 0)) then colorN = colorN + 1 end
            if grndPushCol(im.Col and im.Col.Border, rgba(0, 0, 0, 0)) then colorN = colorN + 1 end

            -- Без NoInputs: значок «копировать», кнопки наказаний и стрелка
            -- должны быть кликабельны. NoScrollWithMouse: карточка листается
            -- своим колесом (см. RC.scrollRect), а не колесом ImGui.
            local flags = wf("NoTitleBar", "NoResize", "NoMove", "NoScrollbar",
                "NoCollapse", "NoFocusOnAppearing", "NoBringToFrontOnFocus",
                "NoScrollWithMouse")
            if not RC.cursor then flags = flags + wflag("NoInputs") end
            if grndBegin("##grnd_recon_card", flags) then
                RC.imguiHealthy = true
                RC.drawError = nil
                local pos = im.GetWindowPos()
                local dl = im.GetWindowDrawList()
                local function at(x, y) return im.ImVec2(pos.x + x, pos.y + y) end
                local function fill(x, y, w, h, color, radius)
                    roundRect(dl, at(x, y), at(x + w, y + h), color, radius or 0)
                end
                local function frame(x, y, w, h, color, radius)
                    if dl.AddRect then
                        pcall(dl.AddRect, dl, at(x, y), at(x + w, y + h), color, radius or 0, 0, 1.0)
                    end
                end
                local function put(x, y, s, color, scale)
                    uiText(x, y, s, color, scale or 1.0)
                end
                local function label(x, y, s, scale)
                    put(x, y, s, c4(TH.textMuted), scale or 0.78)
                end
                -- ширина текста ТАК, как он реально нарисуется. Часть обёрток
                -- ImGui не имеет SetWindowFontScale — там uiText рисует без
                -- масштаба (полным кеглем), и прежняя оценка «grndTextW*scale»
                -- занижала ширину: правое выравнивание уводило длинные
                -- кириллические значения за правый край окна.
                local function drawnW(s, scale)
                    scale = scale or 1
                    if type(im.SetWindowFontScale) == "function" then
                        if scale ~= 1 then
                            pcall(im.SetWindowFontScale, scale)
                            local ok, a = pcall(im.CalcTextSize, tostring(s))
                            pcall(im.SetWindowFontScale, 1)
                            if ok then
                                local ta = type(a)
                                local w = (ta == "table" or ta == "cdata")
                                    and tonumber(a.x) or tonumber(a)
                                if w and w > 0 then return w end
                            end
                        end
                        return grndTextW(s) * scale
                    end
                    -- масштаба нет: текст рисуется полным кеглем
                    return grndTextW(s)
                end

                fill(5, 6, W - 5, H - 5, col32(0, 0, 0, 85), 13)
                fill(0, 0, W, H, col32(10, 15, 20, 247), 13)
                frame(0.5, 0.5, W - 1, H - 1, col32(255, 255, 255, 25), 13)
                -- # v1.19.09: акцентная полоска у верхней кромки убрана (просьба заказчика)

                -- Шапка: ник СЛЕВА, сразу за ним значок «копировать»
                -- (title/titleW посчитаны выше — там же, где рамки «ручек»
                -- перетаскивания).
                put(pad, 9, title, c4(TH.textHi), 1.0)
                local icS = 22
                local icX = pad + titleW + 10
                local icY = 6
                im.SetCursorPos(im.ImVec2(icX, icY))
                local copyClick = im.InvisibleButton("##grnd_recon_copy", im.ImVec2(icS, icS))
                local copyHover = (im.IsItemHovered and im.IsItemHovered()) or false
                if copyHover then
                    fill(icX, icY, icS, icS,
                        col32(TH.accent[1], TH.accent[2], TH.accent[3], 26), 6)
                end
                -- значок рисуем сами: в игровом шрифте символа «копировать» нет
                local icCol = copyHover
                    and col32(TH.accent[1], TH.accent[2], TH.accent[3], 235)
                    or col32(255, 255, 255, 150)
                if dl.AddRect then
                    pcall(dl.AddRect, dl, at(icX + 5, icY + 4), at(icX + 13, icY + 12),
                        icCol, 2, 0, 1.2)
                    fill(icX + 8, icY + 7, 8, 8, col32(10, 15, 20, 255), 1)
                    pcall(dl.AddRect, dl, at(icX + 8, icY + 7), at(icX + 16, icY + 15),
                        icCol, 2, 0, 1.2)
                end
                if copyClick and notify and notify.add then
                    local copied = reconCopyNickname(nick)
                    pcall(notify.add,
                        copied and "Ник скопирован в буфер" or "Не удалось скопировать ник",
                        copied and "ok" or "warn", 2)
                end

                -- Кнопки наказаний: столбиком в левой колонке. Место 3D-модели
                -- над ними пустое (модель ImGui нарисовать не может). Тумблер
                -- GRND_PUN.barOn прячет и показывает весь блок.
                for i = 1, punCnt do
                    local itm = punItems[i]
                    local btnLabel = tostring((itm and itm.id) or "")
                    local bw2 = LW - 12
                    local bxx = pad + 6
                    local byy = leftTop + (i - 1) * (PUN_BH + PUN_BG)
                    im.SetCursorPos(im.ImVec2(bxx, byy))
                    local clicked = im.InvisibleButton("##rcb_p_" .. btnLabel,
                        im.ImVec2(bw2, PUN_BH))
                    local hov = (im.IsItemHovered and im.IsItemHovered()) or false
                    local act = (im.IsItemActive and im.IsItemActive()) or false
                    fill(bxx, byy, bw2, PUN_BH,
                        act and col32(TH.accent[1], TH.accent[2], TH.accent[3], 55)
                            or (hov and col32(TH.accent[1], TH.accent[2], TH.accent[3], 30)
                                or col32(255, 255, 255, 9)), 8)
                    frame(bxx + 0.5, byy + 0.5, bw2 - 1, PUN_BH - 1,
                        (hov or act)
                            and col32(TH.accent[1], TH.accent[2], TH.accent[3], 120)
                            or col32(255, 255, 255, 20), 8)
                    put(bxx + (bw2 - drawnW(btnLabel, 0.9)) / 2, byy + (PUN_BH - 14) / 2,
                        btnLabel, hov and c4(TH.textHi) or c4(TH.text), 0.9)
                    if clicked and notify and notify.add then
                        pcall(notify.add, "Наказание " .. btnLabel
                            .. ": команда подключится позже", "info", 2.2)
                    end
                end

                -- Список: метка слева, значение справа (как в образце).
                -- v1.19.61: один прокручиваемый блок — характеристика игрока,
                -- полупрозрачная линия, статистика.
                local y = listTop - scroll
                local rowN = 0
                local function row(name, value, color, numeric, maxValue, height)
                    height = height or ROW_H
                    rowN = rowN + 1
                    local ry = y
                    y = y + height
                    if not inList(ry, height) then return end
                    label(RX, ry + 3, name, 0.80)
                    local s = shortValue(value, 26)
                    local scale = 0.84
                    local tw = drawnW(s, scale)
                    put(valueRight - tw, ry + 2, s, color or c4(TH.text), scale)
                    if maxValue then
                        -- v1.11.80: шкала 100 = полная линия; ширина заливки
                        -- округляется до пикселя, чтобы полоска не «дышала»
                        local maxV = tonumber(maxValue) or 100
                        if maxV <= 0 then maxV = 100 end
                        local pct = clamp(numeric, 0, maxV) / maxV
                        fill(barX, ry + height - 6, barW, 2, col32(255, 255, 255, 15), 1)
                        if pct > 0 then
                            local wFill = barW * pct
                            if pct >= 1 then wFill = barW
                            elseif wFill < 2 then wFill = 2 end
                            fill(barX, ry + height - 6, wFill, 2,
                                col32(TH.accent[1], TH.accent[2], TH.accent[3], 220), 1)
                        end
                    end
                end
                -- полупрозрачная линия между характеристикой и статистикой
                local function divider()
                    y = y + 6
                    local dy = y
                    y = y + 1 + 6
                    if inList(dy, 1) then
                        fill(RX, dy, W - pad - RX - 12, 1, col32(255, 255, 255, 38), 0)
                    end
                end

                -- v1.19.61: порядок строк — как в образце; «Оружие»,
                -- «Патроны» и «AFK» в карточку не выводятся.
                row("Пинг", ping, c4(TH.text), nil, nil, ROW_H)
                row("Здоровье", hpText, c4(TH.accent), hpNum, grndParamScale(hpNum), ROW_H)
                row("Броня", armText, c4(TH.accent2), armNum, grndParamScale(armNum), ROW_H)
                row("Скорость", speed, c4(TH.text), nil, nil, ROW_H)
                divider()
                -- v1.19.62: статистика — все поля ответа /stats, а не три
                -- строки. «Имя» из статистики убрано (ник есть в шапке).
                row("Номер аккаунта:", textValue("rc_account", "—"), c4(TH.text), nil, nil, ROW_H)
                row("Уровень:", lvlRaw, c4(TH.text), nil, nil, ROW_H)
                row("Номер телефона", textValue("rc_phone", "—"), c4(TH.text), nil, nil, ROW_H)
                row("Варнов", textValue("rc_varnov", "—"), c4(TH.text), nil, nil, ROW_H)
                row("Пол", textValue("rc_gender", "—"), c4(TH.text), nil, nil, ROW_H)
                row("Женат на", textValue("rc_married", "—"), c4(TH.text), nil, nil, ROW_H)
                row("Орг. (ранг)", textValue("rc_org", "—"), c4(TH.text), nil, nil, ROW_H)
                row("Работа/Должность", textValue("rc_job", "—"), c4(TH.text), nil, nil, ROW_H)
                row("Бизнес", textValue("rc_business", "—"), c4(TH.text), nil, nil, ROW_H)
                row("Игровой статус", textValue("rc_status", "—"), c4(TH.text), nil, nil, ROW_H)
                row("Дом", textValue("rc_house", "—"), c4(TH.text), nil, nil, ROW_H)
                row("Квартира", textValue("rc_flat", "—"), c4(TH.text), nil, nil, ROW_H)
                row("VIP статус", textValue("rc_vip", "—"), c4(TH.text), nil, nil, ROW_H)
                row("За сегодня", textValue("today", "—"), c4(TH.text), nil, nil, ROW_H)
                row("Семья", textValue("rc_family", "—"), c4(TH.text), nil, nil, ROW_H)

                -- v1.19.59: полоса прокрутки у правого края (появляется
                -- только когда список длиннее окна). Ведём и мышью, а
                -- основное — колесо мыши (см. RC.scrollRect).
                if openState and scrollMax > 0 then
                    local trX = W - pad + 2
                    roundRect(dl, at(trX, listTop), at(trX + 3, listTop + listH),
                        col32(255, 255, 255, 14), 2)
                    local barH = math.max(26, listH * (listH / rowsH))
                    local barY = listTop + (scroll / scrollMax) * (listH - barH)
                    roundRect(dl, at(trX, barY), at(trX + 3, barY + barH),
                        col32(255, 255, 255, 120), 2)
                end
                -- Стрелка внизу по центру: сворачивает и разворачивает весь
                -- блок информации и статистики (свёрнуто — стрелка вниз).
                im.SetCursorPos(im.ImVec2(math.floor(W / 2) - 12, H - BOT + 1))
                local topClick = im.InvisibleButton("##grnd_recon_top", im.ImVec2(24, 18))
                local topHover = (im.IsItemHovered and im.IsItemHovered()) or false
                local cx2 = math.floor(W / 2)
                local cy2 = H - BOT / 2 + 1
                local triA = topHover and 235 or (openState and 170 or 120)
                local triCol = col32(TH.accent[1], TH.accent[2], TH.accent[3], triA)
                if dl.AddTriangleFilled then
                    if openState then
                        pcall(dl.AddTriangleFilled, dl,
                            at(cx2 - 5, cy2 + 3), at(cx2, cy2 - 3), at(cx2 + 5, cy2 + 3),
                            triCol)
                    else
                        pcall(dl.AddTriangleFilled, dl,
                            at(cx2 - 5, cy2 - 3), at(cx2 + 5, cy2 - 3), at(cx2, cy2 + 3),
                            triCol)
                    end
                end
                if topClick then
                    -- v1.19.64: стрелка сворачивает карточку ВЛЕВО (правая
                    -- часть складывается — остаётся колонка кнопок и стрелка)
                    -- и разворачивает обратно. Левый край окна не прыгает:
                    -- запоминаем текущую позицию до смены ширины.
                    RC.cardOpen = not openState
                    RC.posX, RC.posY = px, py
                    RC.scroll = 0          -- развернём — список с начала
                end
            end
            if endDepth > 0 then endDepth = endDepth - 1; pcall(im.End) end
            grndPopCol(colorN)
            grndPopStyle(styleN)
            -- =====================================================
            --  v1.12+: ПАНЕЛЬ НАКАЗАНИЙ рекона (слева от карточки).
            --  Оставлены ТОЛЬКО наказания (JAIL…SBAN). Действия над
            --  игроком вынесены в интерактивную круглую кнопку.
            -- =====================================================
            do
                -- v1.19.58: отдельной панели наказаний слева от карточки
                -- больше нет — кнопки переехали внутрь самой карточки
                -- (см. блок кнопок сразу под строками сведений).

                -- =====================================================
                --  ИНТЕРАКТИВНОЕ ВЗАИМОДЕЙСТВИЕ С ИГРОКАМИ (РЕКОН):
                --  При наведении курсора на ЛЮБОГО персонажа появляется
                --  белая круглая кнопка и чуть ниже «Нажмите для взаимодействия».
                --  Окно «Действия» открывается ТОЛЬКО при нажатии на эту кнопку.
                -- =====================================================
                local candidates = {}
                local seenPeds = {}
                local seenIds = {}

                -- 1) Основная цель рекона (если активен рекон)
                local tid = tonumber(RC.id)
                if tid then
                    local SN = _G.grndSpecNative
                    local spPed = SN and SN.pedOf and SN.pedOf(tid) or nil
                    if (not spPed) and type(sampGetCharHandleBySampPlayerId) == "function" then
                        local okP, p = pcall(sampGetCharHandleBySampPlayerId, tid)
                        if okP and type(p) == "number" and p ~= 0 then spPed = p end
                    end
                    local nick = RC.nick
                    if (not nick or nick == "") and type(sampGetPlayerNickname) == "function" then
                        local okN, n = pcall(sampGetPlayerNickname, tid)
                        if okN and type(n) == "string" and n ~= "" then nick = n end
                    end
                    local wx, wy, wz = nil, nil, nil
                    if spPed and type(doesCharExist) == "function" and doesCharExist(spPed)
                        and type(getCharCoordinates) == "function" then
                        local okC, cx, cy, cz = pcall(getCharCoordinates, spPed)
                        if okC and type(cx) == "number" then wx, wy, wz = cx, cy, cz end
                    end
                    if (not wx) and SN and SN.camLastTgt and type(SN.camLastTgt.x) == "number" then
                        wx, wy, wz = SN.camLastTgt.x, SN.camLastTgt.y, SN.camLastTgt.z
                    end
                    if wx then
                        table.insert(candidates, {
                            ped = spPed,
                            id = tid,
                            nick = (nick and nick ~= "") and nick or ("ID " .. tid),
                            wx = wx, wy = wy, wz = wz,
                            isSpec = true,
                        })
                        if spPed then seenPeds[spPed] = true end
                        seenIds[tid] = true
                    end
                end

                -- 2) Все остальные персонажи в зоне стрима (getAllChars)
                if type(getAllChars) == "function" then
                    local okG, all = pcall(getAllChars)
                    if okG and type(all) == "table" then
                        for _, p in ipairs(all) do
                            if p and type(p) == "number" and p ~= 0
                                and (not seenPeds[p]) and (p ~= PLAYER_PED)
                                and (type(doesCharExist) ~= "function" or doesCharExist(p)) then

                                local pid = nil
                                if type(sampGetPlayerIdByCharHandle) == "function" then
                                    local okI, r1, r2 = pcall(sampGetPlayerIdByCharHandle, p)
                                    if okI then
                                        if type(r1) == "boolean" and r1 and tonumber(r2) then
                                            pid = tonumber(r2)
                                        elseif type(r1) == "number" then
                                            pid = r1
                                        end
                                    end
                                end

                                local nick = nil
                                if pid and type(sampGetPlayerNickname) == "function" then
                                    local okN, n = pcall(sampGetPlayerNickname, pid)
                                    if okN and type(n) == "string" and n ~= "" then nick = n end
                                end
                                if not nick then
                                    nick = pid and ("ID " .. pid) or "Игрок"
                                end

                                local wx, wy, wz = nil, nil, nil
                                if type(getCharCoordinates) == "function" then
                                    local okC, cx, cy, cz = pcall(getCharCoordinates, p)
                                    if okC and type(cx) == "number" then wx, wy, wz = cx, cy, cz end
                                end

                                if wx then
                                    table.insert(candidates, {
                                        ped = p,
                                        id = pid,
                                        nick = nick,
                                        wx = wx, wy = wy, wz = wz,
                                        isSpec = false,
                                    })
                                    seenPeds[p] = true
                                    if pid then seenIds[pid] = true end
                                end
                            end
                        end
                    end
                end

                -- 3) Если getAllChars вернул только спек-цель или пуст, проверяем подключённых игроков
                if #candidates <= 1 and type(sampGetCharHandleBySampPlayerId) == "function" then
                    for i = 0, 1000 do
                        if not seenIds[i] then
                            local conn = true
                            if type(sampIsPlayerConnected) == "function" then
                                local okC, c = pcall(sampIsPlayerConnected, i)
                                conn = okC and c
                            end
                            if conn then
                                local okH, h = pcall(sampGetCharHandleBySampPlayerId, i)
                                if okH and type(h) == "number" and h ~= 0 and (h ~= PLAYER_PED) and (not seenPeds[h])
                                    and (type(doesCharExist) ~= "function" or doesCharExist(h)) then
                                    local wx, wy, wz = nil, nil, nil
                                    if type(getCharCoordinates) == "function" then
                                        local okC, cx, cy, cz = pcall(getCharCoordinates, h)
                                        if okC and type(cx) == "number" then wx, wy, wz = cx, cy, cz end
                                    end
                                    if wx then
                                        local nick = nil
                                        if type(sampGetPlayerNickname) == "function" then
                                            local okN, n = pcall(sampGetPlayerNickname, i)
                                            if okN and type(n) == "string" and n ~= "" then nick = n end
                                        end
                                        table.insert(candidates, {
                                            ped = h,
                                            id = i,
                                            nick = nick or ("ID " .. i),
                                            wx = wx, wy = wy, wz = wz,
                                            isSpec = false,
                                        })
                                        seenPeds[h] = true
                                        seenIds[i] = true
                                    end
                                end
                            end
                        end
                    end
                end

                -- Поиск персонажа под курсором
                local mx, my = GRND_MOUSE.x, GRND_MOUSE.y
                if im and im.GetIO then
                    local okIo, io = pcall(im.GetIO)
                    if okIo and io and io.MousePos and io.MousePos.x and io.MousePos.x > -1000 then
                        mx, my = io.MousePos.x, io.MousePos.y
                    end
                end

                local hoveredCandidate = nil
                local bestDist = 99999999

                if RC.cursor and not RC.actionsWinOpen and not (menu and menu.open) and type(convert3DCoordsToScreen) == "function" then
                    for _, cand in ipairs(candidates) do
                        local okC, csx, csy = pcall(convert3DCoordsToScreen, cand.wx, cand.wy, cand.wz + 0.35)
                        if okC and csx and type(csx) == "number"
                            and csx >= -50 and csx <= resX + 50
                            and csy >= -50 and csy <= resY + 50 then

                            local okH, _, hsy = pcall(convert3DCoordsToScreen, cand.wx, cand.wy, cand.wz + 0.95)
                            local okF, _, fsy = pcall(convert3DCoordsToScreen, cand.wx, cand.wy, cand.wz - 0.75)
                            local pedH = 80
                            if okH and okF and hsy and fsy and type(hsy) == "number" and type(fsy) == "number" then
                                pedH = math.abs(fsy - hsy)
                            end
                            if pedH < 24 then pedH = 24 end
                            if pedH > 700 then pedH = 700 end
                            local pedW = math.max(34, pedH * 0.45)

                            cand.csx = csx
                            cand.csy = csy
                            cand.pedW = pedW
                            cand.pedH = pedH

                            local inPed = (mx >= csx - pedW * 0.5 - 15 and mx <= csx + pedW * 0.5 + 15
                                and my >= csy - pedH * 0.5 - 15 and my <= csy + pedH * 0.5 + 20)

                            -- Если над этим игроком уже висит кнопка, зона над кнопкой тоже удерживает фокус
                            local isPrevTarget = RC.hoverTarget and (RC.hoverTarget.ped == cand.ped or (cand.id and RC.hoverTarget.id == cand.id))
                            local inBtn = isPrevTarget and (mx >= csx - 125 and mx <= csx + 125 and my >= csy - 30 and my <= csy + 75)

                            if inPed or inBtn then
                                local dist = (mx - csx) ^ 2 + (my - csy) ^ 2
                                if inBtn then dist = dist * 0.1 end
                                if dist < bestDist then
                                    bestDist = dist
                                    hoveredCandidate = cand
                                end
                            end
                        end
                    end
                end

                local nowTime = os.clock()
                if RC.actionsWinOpen then
                    RC.interactHover = false
                    RC.hoverTarget = nil
                elseif hoveredCandidate then
                    RC.hoverTarget = hoveredCandidate
                    RC.interactHover = true
                    RC.interactHoverAt = nowTime
                else
                    if nowTime - (RC.interactHoverAt or 0) > 0.25 then
                        RC.interactHover = false
                        RC.hoverTarget = nil
                    end
                end

                -- Отрисовка белой круглой кнопки при наведении на персонажа
                local curTarget = RC.hoverTarget

                -- Когда открыто окно «Действия» (или главное меню) — кнопки при наведении не появляются
                if not RC.actionsWinOpen and RC.interactHover and curTarget and curTarget.csx and RC.cursor and not (menu and menu.open) then
                    local csx = curTarget.csx
                    local csy = curTarget.csy
                    local IW, IH = 240, 96
                    local ix = math.floor(csx - IW / 2)
                    local iy = math.floor(csy - 24)
                    ix = math.max(6, math.min(resX - IW - 6, ix))
                    iy = math.max(6, math.min(resY - IH - 6, iy))

                    im.SetNextWindowPos(im.ImVec2(ix, iy), COND_ALWAYS)
                    im.SetNextWindowSize(im.ImVec2(IW, IH), COND_ALWAYS)
                    local stI, clI = 0, 0
                    if grndPushStyleV2(im.StyleVar and im.StyleVar.WindowPadding, 0, 0) then stI = stI + 1 end
                    if grndPushStyleF(im.StyleVar and im.StyleVar.WindowRounding, 0) then stI = stI + 1 end
                    if grndPushCol(im.Col and im.Col.WindowBg, rgba(0, 0, 0, 0)) then clI = clI + 1 end
                    if grndPushCol(im.Col and im.Col.Border, rgba(0, 0, 0, 0)) then clI = clI + 1 end
                    local flagsI = wf("NoTitleBar", "NoResize", "NoMove", "NoScrollbar",
                        "NoCollapse", "NoFocusOnAppearing", "NoBringToFrontOnFocus")

                    if grndBegin("##grnd_recon_interact", flagsI) then
                        local ipos = im.GetWindowPos()
                        local idl = im.GetWindowDrawList()
                        local function iat(x2, y2) return im.ImVec2(ipos.x + x2, ipos.y + y2) end

                        local btnCX = IW / 2
                        local btnCY = 24
                        local R = 18

                        local hintText = "Нажмите для взаимодействия"
                        local scaleText1 = 0.80
                        local tw1 = drawnWb(hintText, scaleText1)

                        local targetLine = "Игрок"
                        local safeNick = curTarget.nick
                        if type(reconUtf) == "function" and safeNick then
                            safeNick = reconUtf(safeNick)
                        end
                        if safeNick and safeNick ~= "" then
                            if curTarget.id and not safeNick:match("^ID %d+$") then
                                targetLine = safeNick .. " [" .. tostring(curTarget.id) .. "]"
                            else
                                targetLine = safeNick
                            end
                        elseif curTarget.id then
                            targetLine = "ID " .. tostring(curTarget.id)
                        end
                        local scaleText2 = 0.84
                        local tw2 = drawnWb(targetLine, scaleText2)

                        local maxTw = math.max(tw1, tw2)
                        local pw = math.max(maxTw + 20, 160)
                        local th = 38
                        local px = btnCX - pw / 2
                        local py = btnCY + R + 7

                        -- ОБЛАСТЬ КЛИКА: ТОЛЬКО сама кнопка и плашка под ней (не весь персонаж!)
                        local clickW = math.max(R * 2 + 10, pw)
                        local clickH = (py + th) - (btnCY - R)
                        local clickX = btnCX - clickW / 2
                        local clickY = btnCY - R

                        im.SetCursorPos(im.ImVec2(clickX, clickY))
                        local btnClicked = im.InvisibleButton("##grnd_act_interact_btn", im.ImVec2(clickW, clickH))
                        local btnHov = (im.IsItemHovered and im.IsItemHovered()) or false
                        local btnAct = (im.IsItemActive and im.IsItemActive()) or false

                        -- Мягкая тень кнопки
                        idl:AddCircleFilled(iat(btnCX + 1, btnCY + 2), R + 3, col32(0, 0, 0, 90), 32)
                        idl:AddCircleFilled(iat(btnCX, btnCY), R + 1, col32(0, 0, 0, 160), 32)

                        -- Белая круглая кнопка
                        local circleBg = (btnAct and col32(230, 230, 235, 255))
                            or (btnHov and col32(255, 255, 255, 255) or col32(245, 245, 250, 245))
                        idl:AddCircleFilled(iat(btnCX, btnCY), R, circleBg, 32)

                        -- Обводка кнопки с подсветкой акцентом
                        local ringCol = (btnHov or btnAct)
                            and col32(TH.accent[1], TH.accent[2], TH.accent[3], 230)
                            or col32(210, 215, 225, 220)
                        idl:AddCircle(iat(btnCX, btnCY), R, ringCol, 32, (btnHov or btnAct) and 2.0 or 1.2)

                        -- Иконка в центре белой кнопки (стильное кольцо с точкой)
                        idl:AddCircle(iat(btnCX, btnCY), 6, col32(20, 28, 38, 220), 20, 1.8)
                        idl:AddCircleFilled(iat(btnCX, btnCY), 2.5, col32(20, 28, 38, 240), 12)

                        -- Контрастный бейдж под текстом для читаемости на любом фоне игры
                        roundRect(idl, iat(px, py), iat(px + pw, py + th),
                            (btnHov and col32(10, 15, 22, 245) or col32(12, 17, 24, 225)), 6)
                        if idl.AddRect then
                            pcall(idl.AddRect, idl, iat(px + 0.5, py + 0.5), iat(px + pw - 0.5, py + th - 0.5),
                                (btnHov and col32(TH.accent[1], TH.accent[2], TH.accent[3], 150)
                                    or col32(255, 255, 255, 30)), 6, 0, 1.0)
                        end

                        -- Тонкий разделитель между строками
                        idl:AddLine(iat(px + 8, py + 18), iat(px + pw - 8, py + 18), col32(255, 255, 255, 18), 1.0)

                        -- Первая строчка: подсказка
                        local tx1 = btnCX - tw1 / 2
                        uiText(tx1, py + 3, hintText,
                            (btnHov and c4(TH.text) or c4(TH.textMuted)), scaleText1)

                        -- Вторая строчка: Ник и [ID]
                        local tx2 = btnCX - tw2 / 2
                        uiText(tx2, py + 20, targetLine,
                            (btnHov and c4(TH.accent) or c4(TH.textHi)), scaleText2)

                        -- АКТИВАЦИЯ: ТОЛЬКО при нажатии на эту кнопку!
                        if btnClicked then
                            RC.actionsWinOpen = true
                            RC.actionsWinFocus = true
                            RC.interactHover = false
                            RC.hoverTarget = nil
                            RC.actTargetId = curTarget.id
                            RC.actTargetNick = curTarget.nick
                            RC.actTargetPed = curTarget.ped
                            RC.actSubPopup = nil

                            -- Открытие окна «Действия»: если пользователь уже перетаскивал панель — открываем на том же месте!
                            if not RC.savedActionsWinX or not RC.savedActionsWinY then
                                local calcW = math.max(680, math.min(resX - 24, 960))
                                local calcRows = math.ceil(19 / 6)
                                local calcH = 34 + 6 + calcRows * 42 + 10
                                RC.actionsWinX = math.floor((resX - calcW) / 2)
                                RC.actionsWinY = math.floor((resY - calcH) / 2)
                                RC.savedActionsWinX = RC.actionsWinX
                                RC.savedActionsWinY = RC.actionsWinY
                            else
                                RC.actionsWinX = RC.savedActionsWinX
                                RC.actionsWinY = RC.savedActionsWinY
                            end
                        end
                    end
                    if endDepth > 0 then endDepth = endDepth - 1; pcall(im.End) end
                    grndPopCol(clI)
                    grndPopStyle(stI)
                end

                -- =====================================================
                --  ОКНО «ДЕЙСТВИЯ» (открывается ТОЛЬКО по клику на кнопку)
                --  6 кнопок в одном ряду, расширение в ширину, по центру.
                -- =====================================================
                if RC.actionsWinOpen and RC.show then
                    local PUN = GRND_PUN
                    local actItems = (PUN and PUN.actions) or {
                        "Выдать ХП", "Выдать броню", "Подбросить", "Заспавнить", "Заморозить", "Разморозить",
                        "Починить т/с", "Перевернуть т/с", "Заправить т/с", "Заспавнить т/с", "ТП на дорогу", "ТП к игроку",
                        "ТП игрока к себе", "Оружие", "Отобрать все оружие", "Статистика", "Активные наказания", "Лицензии",
                        "Сообщить в /a",
                    }

                    local targetTitle = "Действия"
                    if RC.actTargetNick and RC.actTargetNick ~= "" then
                        if RC.actTargetId then
                            targetTitle = "Действия: " .. RC.actTargetNick .. " [" .. RC.actTargetId .. "]"
                        else
                            targetTitle = "Действия: " .. RC.actTargetNick
                        end
                    elseif RC.actTargetId then
                        targetTitle = "Действия [ID " .. RC.actTargetId .. "]"
                    end

                    local COLS = 6
                    local aCnt = #actItems
                    local rows = math.ceil(aCnt / COLS)

                    local AH_HEAD = 34
                    local AH_ROW = 36
                    local AH_GAP_X = 6
                    local AH_GAP_Y = 6
                    local AH_PAD = 12

                    -- Расширение в ширину: 6 кнопок в ряд
                    local maxW = math.min(resX - 24, 960)
                    local AW = math.max(680, maxW)
                    local availW = AW - AH_PAD * 2 - (COLS - 1) * AH_GAP_X
                    local BTN_W = math.floor(availW / COLS)

                    local baseAH = AH_HEAD + 6 + rows * (AH_ROW + AH_GAP_Y) + 10
                    local subH = 0
                    if RC.actSubPopup == "hp" or RC.actSubPopup == "arm" or RC.actSubPopup == "fuel" then
                        subH = 76
                    elseif RC.actSubPopup == "report_a" then
                        subH = 58
                    end
                    local AH = baseAH + subH

                    -- Позиция окна: сохранённая точка перетаскивания (или центр экрана)
                    local ax = RC.savedActionsWinX or RC.actionsWinX or math.floor((resX - AW) / 2)
                    local ay = RC.savedActionsWinY or RC.actionsWinY or math.floor((resY - AH) / 2)
                    ax = math.max(4, math.min(resX - AW - 4, ax))
                    ay = math.max(4, math.min(resY - AH - 4, ay))
                    RC.actionsWinX, RC.actionsWinY = ax, ay
                    RC.savedActionsWinX, RC.savedActionsWinY = ax, ay

                    -- Перетаскивание за шапку окна «Действия» с сохранением позиции
                    local actHeadRect = { x = ax, y = ay, w = AW, h = AH_HEAD }
                    local actCloseRect = { x = ax + AW - 30, y = ay + 4, w = 26, h = 24 }
                    if RC.cursor and GRND_MOUSE.down then
                        if not RC.actDragging and grndMouseInside(actHeadRect)
                            and not grndMouseInside(actCloseRect) then
                            RC.actDragging = true
                            RC.actDragDX = GRND_MOUSE.x - ax
                            RC.actDragDY = GRND_MOUSE.y - ay
                        end
                    end
                    if RC.actDragging then
                        if not (GRND_MOUSE and GRND_MOUSE.down) then
                            RC.actDragging = false
                            RC.savedActionsWinX = RC.actionsWinX
                            RC.savedActionsWinY = RC.actionsWinY
                            if PUN and PUN.save then
                                PUN.cfgDirty = true
                                pcall(PUN.save)
                            end
                        else
                            RC.actionsWinX = math.max(4, math.min(resX - AW - 4, GRND_MOUSE.x - (RC.actDragDX or 0)))
                            RC.actionsWinY = math.max(4, math.min(resY - AH - 4, GRND_MOUSE.y - (RC.actDragDY or 0)))
                            ax, ay = RC.actionsWinX, RC.actionsWinY
                            RC.savedActionsWinX = ax
                            RC.savedActionsWinY = ay
                        end
                    end

                    -- Открывается ПОВЕРХ ВСЕГО: фокус и выдвижение на передний план
                    if RC.actionsWinFocus then
                        RC.actionsWinFocus = false
                        if im.SetNextWindowFocus then
                            pcall(im.SetNextWindowFocus)
                        end
                    end

                    im.SetNextWindowPos(im.ImVec2(ax, ay), COND_ALWAYS)
                    im.SetNextWindowSize(im.ImVec2(AW, AH), COND_ALWAYS)
                    local stA, clA = 0, 0
                    if grndPushStyleV2(im.StyleVar and im.StyleVar.WindowPadding, 0, 0) then stA = stA + 1 end
                    if grndPushStyleF(im.StyleVar and im.StyleVar.WindowRounding, 12) then stA = stA + 1 end
                    if grndPushCol(im.Col and im.Col.WindowBg, rgba(0, 0, 0, 0)) then clA = clA + 1 end
                    if grndPushCol(im.Col and im.Col.Border, rgba(0, 0, 0, 0)) then clA = clA + 1 end
                    local flagsA = wf("NoTitleBar", "NoResize", "NoMove", "NoScrollbar", "NoCollapse")
                    if (not RC.cursor) or (menu and menu.open) then
                        flagsA = flagsA + wflag("NoInputs")
                    end

                    if grndBegin("##grnd_recon_actions", flagsA) then
                        if im.BringWindowToDisplayFront then
                            pcall(im.BringWindowToDisplayFront, im.GetCurrentWindow())
                        end
                        if im.SetWindowFocus then
                            pcall(im.SetWindowFocus)
                        end
                        local apos = im.GetWindowPos()
                        local adl = im.GetWindowDrawList()
                        local function aat(x2, y2) return im.ImVec2(apos.x + x2, apos.y + y2) end
                        local function afill(x2, y2, w2, h2, c, r)
                            roundRect(adl, aat(x2, y2), aat(x2 + w2, y2 + h2), c, r or 0)
                        end
                        local function aframe(x2, y2, w2, h2, c, r)
                            if adl.AddRect then
                                pcall(adl.AddRect, adl, aat(x2, y2), aat(x2 + w2, y2 + h2),
                                    c, r or 0, 0, 1.0)
                            end
                        end

                        -- Каркас окна в общем стиле рекона
                        afill(5, 6, AW - 5, AH - 5, col32(0, 0, 0, 85), 13)
                        afill(0, 0, AW, AH, col32(10, 15, 20, 247), 13)
                        aframe(0.5, 0.5, AW - 1, AH - 1, col32(255, 255, 255, 25), 13)
                        -- # v1.19.09: акцентная полоска у верхней кромки убрана (просьба заказчика)

                        -- Шапка: название с ником / ID игрока
                        uiText(AH_PAD + 2, 10, targetTitle, c4(TH.textHi), 0.95)

                        -- Кнопка закрытия «×»
                        im.SetCursorPos(im.ImVec2(AW - 28, 7))
                        local closeClicked = im.InvisibleButton("##act_close_btn", im.ImVec2(22, 22))
                        local closeHov = (im.IsItemHovered and im.IsItemHovered()) or false
                        if closeHov then
                            afill(AW - 28, 7, 22, 22, col32(255, 255, 255, 18), 4)
                        end
                        uiText(AW - 22, 9, "×", closeHov and c4(TH.textHi) or c4(TH.textMuted), 0.95)
                        if closeClicked then
                            RC.actionsWinOpen = false
                            RC.actSubPopup = nil
                        end

                        -- Разделитель под шапкой
                        adl:AddRectFilled(aat(AH_PAD, AH_HEAD - 2), aat(AW - AH_PAD, AH_HEAD - 1),
                            col32(255, 255, 255, 16))

                        -- Функция автоматического разбиения длинного текста на 2 строки
                        local function splitBtnLines(str, maxW)
                            if not str or str == "" then return { "" } end
                            if str:find("\n") then
                                local r = {}
                                for line in str:gmatch("[^\r\n]+") do table.insert(r, line) end
                                return r
                            end
                            local tw0 = drawnWb(str, 0.82)
                            if (tw0 > (maxW - 8) or #str > 14) and str:find(" ") then
                                local mid = math.floor(#str / 2)
                                local bestSp = nil
                                local bestDist = 999
                                for sp = 1, #str do
                                    if str:sub(sp, sp) == " " then
                                        local d = math.abs(sp - mid)
                                        if d < bestDist then
                                            bestDist = d
                                            bestSp = sp
                                        end
                                    end
                                end
                                if bestSp then
                                    return { str:sub(1, bestSp - 1), str:sub(bestSp + 1) }
                                end
                            end
                            return { str }
                        end

                        -- Сетка кнопок действий: 6 кнопок в ряд
                        for i = 1, aCnt do
                            local rawLabel = tostring(actItems[i])
                            local tag = "act_btn_" .. i

                            local col = (i - 1) % COLS
                            local row = math.floor((i - 1) / COLS)
                            local bx = AH_PAD + col * (BTN_W + AH_GAP_X)
                            local by = AH_HEAD + 6 + row * (AH_ROW + AH_GAP_Y)

                            im.SetCursorPos(im.ImVec2(bx, by))
                            local clicked = im.InvisibleButton("##" .. tag, im.ImVec2(BTN_W, AH_ROW))
                            local hov = (im.IsItemHovered and im.IsItemHovered()) or false
                            local act = (im.IsItemActive and im.IsItemActive()) or false

                            local isSubActive = false
                            if (rawLabel == "Выдать ХП" and RC.actSubPopup == "hp")
                                or (rawLabel == "Выдать броню" and RC.actSubPopup == "arm")
                                or (rawLabel == "Заправить т/с" and RC.actSubPopup == "fuel")
                                or (rawLabel == "Сообщить в /a" and RC.actSubPopup == "report_a") then
                                isSubActive = true
                            end

                            afill(bx, by, BTN_W, AH_ROW,
                                isSubActive and col32(TH.accent[1], TH.accent[2], TH.accent[3], 70)
                                    or (act and col32(TH.accent[1], TH.accent[2], TH.accent[3], 55)
                                        or (hov and col32(TH.accent[1], TH.accent[2], TH.accent[3], 30)
                                            or col32(255, 255, 255, 9))), 8)
                            aframe(bx + 0.5, by + 0.5, BTN_W - 1, AH_ROW - 1,
                                (isSubActive or hov or act)
                                    and col32(TH.accent[1], TH.accent[2], TH.accent[3], 150)
                                    or col32(255, 255, 255, 20), 8)

                            -- Отрисовка текста (1 или 2 строки с центрированием и защитой от вылезания)
                            local bLines = splitBtnLines(rawLabel, BTN_W)
                            if #bLines <= 1 then
                                local scale = 0.84
                                local twL = drawnWb(bLines[1], scale)
                                if twL > (BTN_W - 8) then
                                    scale = scale * ((BTN_W - 8) / twL)
                                    if scale < 0.60 then scale = 0.60 end
                                    twL = drawnWb(bLines[1], scale)
                                end
                                local tx = bx + (BTN_W - twL) / 2
                                local ty = by + (AH_ROW - 14 * scale) / 2
                                uiText(tx, ty, bLines[1], (isSubActive or hov) and c4(TH.textHi) or c4(TH.text), scale)
                            else
                                local lineH = 13
                                local totalH = #bLines * lineH
                                local startY = by + (AH_ROW - totalH) / 2
                                for lIdx = 1, #bLines do
                                    local lText = bLines[lIdx]
                                    local scale = 0.78
                                    local twL = drawnWb(lText, scale)
                                    if twL > (BTN_W - 6) then
                                        scale = scale * ((BTN_W - 6) / twL)
                                        if scale < 0.60 then scale = 0.60 end
                                        twL = drawnWb(lText, scale)
                                    end
                                    local tx = bx + (BTN_W - twL) / 2
                                    local ty = startY + (lIdx - 1) * lineH
                                    uiText(tx, ty, lText, (isSubActive or hov) and c4(TH.textHi) or c4(TH.text), scale)
                                end
                            end

                            if clicked then
                                local cleanLabel = rawLabel:gsub("\n", " ")
                                local tid = tonumber(RC.actTargetId) or tonumber(RC.id)
                                    or (_G.GRND_SPEC and tonumber(_G.GRND_SPEC.id))
                                local tNick = (RC.actTargetNick and RC.actTargetNick ~= "") and RC.actTargetNick
                                    or (RC.nick and RC.nick ~= "" and RC.nick) or ("ID " .. tostring(tid or 0))

                                if _G.grndHandleActionBtn then
                                    _G.grndHandleActionBtn(cleanLabel, tid, tNick, RC.actTargetPed)
                                end
                            end
                        end

                        if subH > 0 and _G.grndDrawActSubPopup then
                            local tid = tonumber(RC.actTargetId) or tonumber(RC.id)
                                or (_G.GRND_SPEC and tonumber(_G.GRND_SPEC.id))
                            local tNick = (RC.actTargetNick and RC.actTargetNick ~= "") and RC.actTargetNick
                                or (RC.nick and RC.nick ~= "" and RC.nick) or ("ID " .. tostring(tid or 0))
                            local subY = AH_HEAD + 6 + rows * (AH_ROW + AH_GAP_Y) + 3
                            -- v1.11.72: примитивы рисования передаём ЯВНО.
                            -- Плюс pcall: даже если внутри что-то упадёт,
                            -- окно «Действия» будет закрыто корректно
                            -- (im.End ниже), а не останется висеть.
                            local okSub, errSub = pcall(_G.grndDrawActSubPopup, RC, TH, tid, tNick,
                                RC.actTargetPed, apos, adl, aat, afill, aframe, AW, AH_PAD, subY, subH,
                                { imgui = im, uiText = uiText, c4 = c4, col32 = col32, drawnWb = drawnWb })
                            if not okSub then
                                RC.actSubError = tostring(errSub)
                                if logRenderErr then logRenderErr("act_sub", errSub) end
                            end
                            -- v1.11.72b: любую причину «панель пустая» показываем
                            -- в чате ОДИН раз — больше не будет молчаливых пустых панелей.
                            if RC.actSubError and RC.actSubError ~= RC.actSubErrShown then
                                RC.actSubErrShown = RC.actSubError
                                if notify and notify.add then
                                    pcall(notify.add, "Подпанель действий: " .. tostring(RC.actSubError), "error", 6)
                                end
                                print("{FF6666}[GRND]{FFFFFF} подпанель действий: " .. tostring(RC.actSubError))
                            end
                        end
                    end
                    if endDepth > 0 then endDepth = endDepth - 1; pcall(im.End) end
                    grndPopCol(clA)
                    grndPopStyle(stA)
                end
            end
            return (RC.cursor or RC.actionsWinOpen) and true or false
        end
        -- Подсказка висит в правом нижнем углу ВСЁ время, пока открыт
        -- рекон: статичная, не мигает, не зависит от состояния курсора.
        -- v1.11.12: подсказка больше НЕ ImGui-бейдж — рисуется DX-стилем,
        -- ImGui-путь просто делегирует в DX-отрисовку.
        function drawReconHint()
            pcall(drawReconHintDx)
            return false
        end

        -- Независимая DX-подсказка. Она не зависит от ImGui Begin/End и
        -- поэтому видна даже на сборках, где окно ImGui не отрисовалось.
        -- v1.11.16: СТАТИЧНА — не привязана к курсору (чтобы не было
        -- «багов с курсором» через мигание надписи); ширина и позиция
        -- кэшируются один раз — надпись не дёргается.
        function drawReconHintDx()
            local R = GRND_RC
            if not R or not R.show then return end
            if type(renderFontDrawText) ~= "function" then return end
            -- v1.11.15: шрифтовая лесенка как у кил-листа (эти комбинации
            -- точно рендерятся в боевых сборках)
            if not R.hintBarFont and type(renderCreateFont) == "function" then
                for _, arg in ipairs({
                    { "Tahoma", -13, 1, 204 },
                    { "Tahoma", -13, 5, 204 },
                    { "Arial", -13, 1, 204 },
                    { "Tahoma", -13 },
                }) do
                    local okF, f = pcall(renderCreateFont, unpack(arg))
                    if okF and f then R.hintBarFont = f; break end
                end
            end
            if not R.hintBarFont then R.hintBarFont = R.hintFont end
            if not R.hintBarFont then return end
            local sx, sy = getScreenResolution()
            local hint = "Чтобы включить/выключить курсор, нажмите ПКМ."
            local text = hint
            if type(grndToAnsi) == "function" then
                local okA, out = pcall(grndToAnsi, text)
                if okA and type(out) == "string" then text = out end
            end
            -- ширина фиксируется ОДИН раз: дальше позиция неподвижна
            local tw = R.hintW
            if not tw then
                if type(renderGetFontDrawTextSize) == "function" then
                    local okW, w = pcall(renderGetFontDrawTextSize, R.hintBarFont, text)
                    if okW and type(w) == "number" and w > 10 then tw = math.floor(w) end
                end
                if not tw then tw = #text * 10 end
                R.hintW = tw
            end
            local x = sx - tw - 14
            if x < 4 then x = 4 end
            local y = sy - 26
            if y < 4 then y = 4 end
            -- как в кил-листе: одна чёрная тень +1,+1 и белый текст — чисто
            -- и читаемо, без «зачёркиваний» и лишних проходов
            pcall(renderFontDrawText, R.hintBarFont, text, x + 1, y + 1, 0xFF000000)
            pcall(renderFontDrawText, R.hintBarFont, text, x, y, 0xFFFFFFFF)

        end

        -- Запасной рендер через lib.moonloader. Он нужен, если на конкретной
        -- сборке ImGui не загрузился или одна из её обёрток не принимает окно.
        -- Основной красивый вариант выше используется первым; fallback не
        -- появляется поверх исправного ImGui.
        -- Глобальная функция по той же причине: не увеличиваем число
        -- локальных переменных grndMainBody.
        function drawReconFallback()
            local RC = GRND_RC
            local hasData = RC and RC.live and (RC.live.id or RC.live.weap
                or RC.live.hp or RC.live.ping)
            if not RC or (not RC.show and not hasData) then return end
            local function reconUtf(v)
                v = tostring(v or "")
                if type(grndToUtf) == "function" then
                    local ok, out = pcall(grndToUtf, v)
                    if ok and type(out) == "string" then return out end
                end
                return v
            end
            local recentImgui = RC.imguiHealthy and RC.imguiLastAt
                and (os.clock() - RC.imguiLastAt < 0.5)
            if recentImgui and not RC.drawError then return end
            if type(renderFontDrawText) ~= "function" then return end

            local resX, resY = getScreenResolution()
            local W, H = 350, 274
            local x, y = resX - W - 22, 92
            local font = RC.fallbackFont
            if not font and type(renderCreateFont) == "function" then
                local okF, f = pcall(renderCreateFont, "Tahoma", -14, 1, 204)
                if okF and f then
                    font = f
                    RC.fallbackFont = f
                end
            end
            if not font then return end
            local function val(k, fallback)
                local v = RC.live and RC.live[k]
                if v == nil or tostring(v) == "" then return fallback or "—" end
                return reconUtf(v)
            end
            local function drawText(text, tx, ty, color, scale)
                local s = reconUtf(tostring(text or ""))
                if type(grndToAnsi) == "function" then s = grndToAnsi(s) end
                pcall(renderFontDrawText, font, s, x + tx, y + ty, color)
            end
            local function box(bx, by, bw, bh, color)
                if type(renderDrawBox) == "function" then
                    pcall(renderDrawBox, x + bx, y + by, bw, bh, color)
                end
            end
            box(4, 5, W, H, 0x60000000)
            box(0, 0, W, H, 0xE60B0F16)
            -- # v1.19.09: акцентная полоска у верхней кромки убрана (просьба заказчика)
            drawText("GRND  /  RECON", 16, 12, 0xFF00D6AA)
            drawText(val("id", RC.id and ("ID " .. tostring(RC.id)) or "ID —"), 236, 12, 0xFFDDE8F2)
            drawText(reconUtf(RC.nick or "Игрок"), 16, 34, 0xFFFFFFFF)
            drawText("GUN: " .. val("weap"), 16, 66, 0xFFE9EDF6)
            drawText("AMMO: " .. val("ammo"), 188, 66, 0xFFE9EDF6)
            drawText("PING: " .. val("ping"), 16, 91, 0xFFE9EDF6)
            drawText("AFK: " .. val("afk", "0"), 188, 91, 0xFFF79248)
            drawText("HP: " .. val("hp"), 16, 116, 0xFF4CD14F)
            drawText("ARM: " .. val("arm"), 188, 116, 0xFF6094FF)
            drawText("FRACTION: " .. val("frac"), 16, 141, 0xFFE9EDF6)
            drawText("SPEED: " .. val("speed", "0"), 16, 166, 0xFFE9EDF6)
            box(16, 198, W - 32, 1, 0x35FFFFFF)
            drawText("Интерфейс реконa загружен", 16, 216, 0xFF8C94A6)
        end

        _G.grndReconFallback = drawReconFallback
        local function drawAll()
            renderedOnce = true
            _G.GRND_IMGUI_ALIVE = true
            if T_frames() == 0 then
                grndTraceFrames(1)
                grndTrace("imgui", "ПЕРВЫЙ отрисованный кадр — рендер жив")
            else
                grndTraceFrames(1)
            end
            local now = os.clock()
            local dt  = now - (menu.lastFrame or now)
            menu.lastFrame = now
            if dt < 0 or dt > 0.25 then dt = 0.016 end
            -- v1.12.1: на экране входа (подключение/авторизация) НИЧЕГО из
            -- наших оверлеев не рисуем: чекеры, окно репорта, оверлей
            -- репортов, рекон, формы — всё это включено настройками и
            -- раньше «висело» поверх окна пароля.
            local gated = grndUiBlocked()
            if gated then
                GRND_GATE.blockedFrames = (GRND_GATE.blockedFrames or 0) + 1
                if grndUiWantsToShow() then
                    GRND_GATE.suppressed = (GRND_GATE.suppressed or 0) + 1
                    -- окно репорта не могло быть настоящим (мы ещё не в игре)
                    if _G.GRND_REP then _G.GRND_REP.open = false end
                    if _G.GRND_QR then
                        _G.GRND_QR.pickOpen = false
                        if type(_G.GRND_QR.pun) == "table" then _G.GRND_QR.pun.pickOpen = false end
                    end
                end
            end
            local wantCursor = false
            if menu.open or menu.anim > 0 then
                local ok, e = pcall(drawMenu, dt)
                if not ok then
                    -- v1.14.58 (фикс): если меню упало на середине кадра,
                    -- обязательно закрываем окно и снимаем стили — иначе весь
                    -- кадр ImGui ломается: остальные окна рисуются без текста,
                    -- а курсор пропадает.
                    pcall(grndEnds)
                    logRenderErr("menu", e)
                else wantCursor = menu.open end
            end
            if GRND_TAB.open or scoreboard.anim > 0 then
                local ok, e = pcall(drawScoreboard, dt)
                if not ok then logRenderErr("scoreboard", e)
                elseif e then wantCursor = true end
            end
            if #queue > 0 then
                local ok, e = pcall(drawToasts)
                if not ok then logRenderErr("toast", e) end
            end
            -- МОДУЛЬ 11 (v1.5): килл-лист (чекер №1). Рисуется всегда, пока
            -- чекер включён (или пока панель «в руке» при перемещении) и не
            -- зависит от меню и таблицы.
            if not gated and GRND_KL then
                local ok, e = pcall(drawKillList, dt)
                if not ok then logRenderErr("killlist", e)
                elseif e then wantCursor = true end
            end
            if not gated and GRND_AO then
                local ok, e = pcall(drawAdminsOnline, dt)
                if not ok then logRenderErr("admins", e)
                elseif e then wantCursor = true end
            end
            if not gated and GRND_RC and (GRND_RC.show
                or (GRND_RC.live and (GRND_RC.live.id or GRND_RC.live.weap
                    or GRND_RC.live.hp or GRND_RC.live.ping))) then
                local ok, e = pcall(drawRecon)
                if not ok then
                    GRND_RC.drawError = tostring(e)
                    logRenderErr("recon", e)
                elseif e then
                    wantCursor = true
                end
            end
            -- v1.11.16: подсказка больше не рисуется из ImGui-кадра — она
            -- статичная и живёт только в основном DX-проходе (см. ниже
            -- pcall(_G.drawReconHintDx) в главном цикле). Убрали связь
            -- «надпись <-> курсор», чтобы не было миганий и багов.
            if not gated and GRND_CATCH and GRND_CATCH.active then
                local ok, e = pcall(drawCatchWindow)
                if not ok then logRenderErr("catch", e) end
            end
            if not gated and GRND_REPHUD and GRND_REPHUD.enabled then
                local ok, e = pcall(drawReportHud)
                if not ok then logRenderErr("rephud", e)
                elseif e then wantCursor = true end
            end
            if not gated and GRND_REP and GRND_REP.open then
                local ok, e = pcall(drawReportWindow)
                if not ok then logRenderErr("report", e)
                elseif e then wantCursor = true end
            end
            -- v1.19.01: окно шаблонов («Быстрые ответы») рисуется поверх всего;
            -- сам модуль живёт вне grndMainBody и получает помощники через ctx.
            if not gated and type(_G.grndQrPickerDraw) == "function" then
                local qrCtx = {
                    im = im, always = COND_ALWAYS, wf = wf, begin = grndBegin,
                    uiText = uiText, roundRect = roundRect, col32 = col32,
                    rgba = rgba, c4 = c4, gradRect = gradRect, drawnW = drawnWb,
                    pushCol = grndPushCol, popCol = grndPopCol,
                    pushVarF = grndPushStyleF, pushVarV2 = grndPushStyleV2,
                    popVar = grndPopStyle,
                }
                local ok, e = pcall(_G.grndQrPickerDraw, qrCtx)
                if not ok then logRenderErr("quick_reply", e)
                elseif e then wantCursor = true end
                -- v1.19.16: полоса шаблонов наказаний (по центру окна репорта)
                if type(_G.grndQrPunPickerDraw) == "function" then
                    local okP, eP = pcall(_G.grndQrPunPickerDraw, qrCtx)
                    if not okP then logRenderErr("punish_reply", eP)
                    elseif eP then wantCursor = true end
                end
            end
            if _G.GRND_FORMS and _G.GRND_FORMS.active then
                local ok, e = pcall(drawFormPopup)
                if not ok then logRenderErr("forms", e)
                -- v1.14.13: окно формы перетаскивается мышью, а для этого
                -- нужен курсор. Раньше он включался только при уже открытом
                -- реконе (ПКМ) или меню — тащить окно было практически нечем.
                -- Теперь как у окон репорта: окно нарисовано — курсор нужен.
                -- Окно живёт до [Y]/[N] или пятисекундного тайм-аута.
                elseif e then wantCursor = true end
            end
            -- v1.11.78: отдельное окно со статистикой игрока (/stats, кнопка)
            if GRND_RC and GRND_RC.statsPop and _G.grndDrawStatsPopup then
                local ok, e = pcall(_G.grndDrawStatsPopup)
                if not ok then logRenderErr("stats_pop", e)
                elseif e and ((GRND_RC and GRND_RC.cursor) or menu.open) then wantCursor = true end
            end
            -- v1.11.79: заявка на гос.новости — окно «Принять гос.волну?»
            if _G.GRND_GNEWS and _G.GRND_GNEWS.active then
                local ok, e = pcall(drawGnewsPopup)
                if not ok then logRenderErr("gnews", e)
                elseif e and ((GRND_RC and GRND_RC.cursor) or menu.open) then wantCursor = true end
            end
            if GRND_LOG.wanted() then
                local depth=endDepth
                local ok,result=pcall(GRND_LOG.windows,{
                    im=im,begin=grndBegin,flags=wf('NoTitleBar','NoCollapse','NoResize'),
                    once=(im.Cond and im.Cond.Once) or 2,always=COND_ALWAYS,
                    push=grndPushCol,pop=grndPopCol,color=c4,color32=c32,
                    finish=function() if endDepth>depth then endDepth=endDepth-1;im.End() end end,
                    recover=function() while endDepth>depth do endDepth=endDepth-1;pcall(im.End) end end
                })
                if not ok then GRND_LOG.warn(result,'viewer');logRenderErr('chat_logs',result) elseif result then wantCursor=true end
            end
            if GRND_INPUT.active() then
                local depth=endDepth
                local ok,e=pcall(GRND_INPUT.draw,{
                    im=im,begin=grndBeginTransparent,always=COND_ALWAYS,
                    flags=wf('NoTitleBar','NoResize','NoMove','NoScrollbar','NoScrollWithMouse',
                        'NoCollapse','NoSavedSettings','NoInputs','NoNavInputs','NoNavFocus',
                        'NoFocusOnAppearing','NoBringToFrontOnFocus'),
                    text=uiText,measure=drawnWb,col32=col32,rgba=rgba,roundRect=roundRect,
                    pushFont=uiPushFont,popFont=uiPopFont,
                    finish=function()
                        while endDepth>depth do endDepth=endDepth-1;pcall(im.End) end
                    end,
                })
                if not ok then pcall(grndEnds);logRenderErr('native_input_overlay',e) end
                -- This non-modal decoration must not change ImGui cursor ownership.
            end
            return wantCursor
        end
        local renderRegistered = false
        local function setupRender()
            if renderRegistered then
                if imKind == "moonimgui" then im.Process = true end
                return
            end
            renderRegistered = true
            uiFontRegister()
            local function safeDraw()
                local ok, res = pcall(drawAll)
                if ok then return res end
                -- ФИКС v1.2: после падения кадра «докрыть» окна и скинуть
                -- стили, иначе ImGui начинает возвращать Begin()==false для
                -- ВСЕХ окон: меню маргает, TAB не открывается, кнопки
                -- не нажимаются.
                pcall(grndEnds)
                _G.GRND_IMGUI_ALIVE = false
                logRenderErr("frame", res)
                return false
            end
            local function syncIoFlags()
                local okIO, io3 = pcall(im.GetIO)
                if okIO and io3 then
                    GRND_KEYS.imguiText = (io3.WantTextInput and true) or false
                end
            end
            if imKind == "moonimgui" then
                im.OnDrawFrame = function()
                    GRND_UIFRAME = (GRND_UIFRAME or 0) + 1
                    endDepth, styleDepth, colorDepth = 0, 0, 0
                    if GRND_MOUSE.clicked or GRND_MOUSE.rclicked then
                        GRND_MOUSE.pending = true
                    else
                        GRND_MOUSE.pending = false
                    end
                    syncIoFlags()
                    -- v1.11.15: при открытом реконе с выключенным курсором
                    -- плоский курсор F1 не имеет права показывать курсор
                    local rcLock = (GRND_RC and GRND_RC.show and not GRND_RC.cursor) and true or false
                    local cursorWanted = safeDraw() or (plainCursorOn and not rcLock)
                        or ((clw ~= nil) and clw.aiming)
                        or (GRND_KL and GRND_KL.moving)
                        or (GRND_RC and GRND_RC.show and GRND_RC.cursor)
                        or false
                    GRND_KEYS.cursorOn = cursorWanted and true or false
                    im.ShowCursor = cursorWanted
                end
                im.Process = true
            else
                im.OnFrame(
                    function()
                        -- v1.7.0: раньше кадр «держал» кастомный чат (он рисовался
                        -- всегда). Теперь в список добавлены плоский курсор F1 и
                        -- прицел ClickWarp — иначе курсорная логика (GRND_KEYS.cursorOn)
                        -- перестала бы пересчитываться при закрытых меню/таблице.
                        -- v1.13.0: окно формы и окно гос.волны добавлены в
                        -- условие видимости кадра. Без этого кадр мог не
                        -- рисоваться (окно не появлялось), а после закрытия
                        -- на экране оставался «последний кадр» с окном.
                        local formUi = false
                        if type(_G.grndFormsUiWanted) == "function" then
                            formUi = _G.grndFormsUiWanted() and true or false
                        elseif _G.GRND_FORMS and _G.GRND_FORMS.active then
                            formUi = true
                        end
                        return GRND_INPUT.wanted() or GRND_LOG.wanted() or menu.open or menu.anim > 0 or #queue > 0 or GRND_TAB.open
                            or scoreboard.anim > 0
                            or (GRND_KL and (GRND_KL.enabled or GRND_KL.moving))
                            or (GRND_REP and GRND_REP.open)
                            or (GRND_REPHUD and GRND_REPHUD.enabled)
                            or (GRND_RC and GRND_RC.show)
                            or (GRND_CATCH and GRND_CATCH.active)
                            or formUi
                            or (_G.grndGnewsUiWanted and _G.grndGnewsUiWanted())
                            or plainCursorOn or ((clw ~= nil) and clw.aiming)
                    end,
                    function(self)
                        GRND_UIFRAME = (GRND_UIFRAME or 0) + 1
                        endDepth, styleDepth, colorDepth = 0, 0, 0
                        syncIoFlags()
                        local want = safeDraw()
                        -- v1.11.15: рекон с выключенным курсором глушит плоский курсор
                        local rcLock = (GRND_RC and GRND_RC.show and not GRND_RC.cursor) and true or false
                        local cursorWanted = want or (plainCursorOn and not rcLock)
                            or ((clw ~= nil) and clw.aiming)
                            or (GRND_KL and GRND_KL.moving)
                            or (GRND_RC and GRND_RC.show and GRND_RC.cursor)
                        GRND_KEYS.cursorOn = cursorWanted and true or false
                        if self then self.HideCursor = not cursorWanted end
                    end
                )
            end
        end
        ensureRender = function(force)
            setupRender()
            if force and imKind == "moonimgui" then im.Process = true end
        end
        ensureToasts = ensureRender
        -- ensureRender теперь глобальная (см. начало файла): хук переподписывается
        -- и из onWindowMessage, и после D3DDeviceReset, и из основного цикла.
        _G.grndEnsureRender = ensureRender
        addEventHandler('onD3DDeviceReset', function()
            ensureRender(true)
        end)
        -- =============================================================
        --  МОДУЛЬ 6 (v1.2): ВТОРОЙ обработчик onWindowMessage УДАЛЁН.
        --  В v1.1 один и тот же разбор клавиш жил и в глобальной функции
        --  onWindowMessage(), и в addEventHandler("onWindowMessage", ...) —
        --  MoonLoader вызывает оба. Итог: consumeWindowMessage(true, true) из
        --  одного обработчика съедал сообщение у второго (в т.ч. у нашего же),
        --  TAB/F1 «проглатывались» без действия, T-логика конфликтовала сама с
        --  собой. PgUp/PgDn теперь обрабатываются в onWindowMessage (см. выше).
        -- =============================================================
        function notify.add(text, kind, life, force)
            kind = (kind == "ok" or kind == "warn" or kind == "error") and kind or "info"
            if not force and type(_G.grndSessionReady) == "function" then
                local okReady, ready = pcall(_G.grndSessionReady)
                if okReady and not ready then return false end
            end
            local message = tostring(text or "")
            if message == "" then return false end
            life = math.max(1, math.min(10, tonumber(life) or 3.5))
            local now = os.clock()
            local function enqueueToast()
                -- Merge identical messages generated by duplicate event paths.
                for i = #queue, math.max(1, #queue - 5), -1 do
                    local item = queue[i]
                    if item.kind == kind and item.text == message
                        and now >= item.start and now - item.start <= 0.9 then
                        item.start, item.life, item.alpha = now, life, 1
                        if imKind == "moonimgui" then im.Process = true end
                        return true
                    end
                end
                nextId = nextId + 1
                while #queue >= 6 do table.remove(queue, 1) end
                queue[#queue + 1] = {
                    id = nextId, text = message, kind = kind,
                    life = life, start = now, alpha = 1,
                }
                if imKind == "moonimgui" then im.Process = true end
                return true
            end
            if not renderedOnce or _G.GRND_IMGUI_ALIVE == false then
                if force and im and imKind then
                    local queued = enqueueToast()
                    pcall(ensureRender, true)
                    if imKind == "moonimgui" then im.Process = true end
                    return queued
                end
                -- Non-forced notices fall back to chat if the renderer is unavailable.
                local oldChat = notify.chat
                notify.chat = true
                pcall(notify.say, message, kind)
                notify.chat = oldChat
                return false
            end
            return enqueueToast()
        end
        -- ссылки для хоткеев, живущих ВНЕ grndMainBody (onWindowMessage)
        _G.GRND_IM = im
        _G.GRND_IM_KIND = imKind
        GRND_REF.im, GRND_REF.menu, GRND_REF.clw = im, menu, clw
        GRND_REF.clwSetAiming = clwSetAiming
        GRND_REF.clwApplyAim = clwApplyAim
        GRND_REF.gm, GRND_REF.spec = GRND_GM, GRND_SPEC
        GRND_REF.ensureRender = function(f) ensureRender(f) end
        ensureRender()
        IMGUI_WRAP = (imKind == "moonimgui") and "MoonImGui" or "FYP mimgui"
        if imKind == "moonimgui" or type(im.OnFrame) == "function" then
            AUTH.panelOpen = false
            AUTH.ok = true
        end
        grndTrace("imgui", "обёртка " .. tostring(IMGUI_WRAP))
        print("{00FFAA}[GRND]{FFFFFF} ImGui загружен (" .. IMGUI_WRAP .. "), рендер запущен")
        notify.chat = false
    else
        grndTrace("imgui", "ImGui НЕ загрузился — меню/таблица/килл-лист не появятся")
        print("{FF6666}[GRND]{FFFFFF} ВНИМАНИЕ: ImGui НЕ загрузился!")
        print("{FF6666}[GRND]{FFFFFF} Проверьте, что в папке moonloader/lib есть imgui.lua / mimgui.lua")
        IMGUI_WRAP = "НЕТ (imgui.lua/mimgui.lua не найдены)"
        pcall(notify.say, "ImGui не найден — меню/таблица/килл-лист недоступны.", "error")
        -- Даже без ImGui рекон остаётся видимым через DX-рендер.
        _G.grndReconFallback = function()
            local R = GRND_RC
            local hasData = R and R.live and (R.live.id or R.live.weap
                or R.live.hp or R.live.ping)
            if not R or (not R.show and not hasData) then return end
            if type(renderFontDrawText) ~= "function" then return end
            local sx, sy = getScreenResolution()
            local x, y, w, h = sx - 372, 92, 350, 274
            if not R.fallbackFont and type(renderCreateFont) == "function" then
                local okF, f = pcall(renderCreateFont, "Tahoma", -14, 1, 204)
                if okF and f then R.fallbackFont = f end
            end
            if not R.fallbackFont then return end
            local function utf(v)
                v = tostring(v or "")
                if type(grndToUtf) == "function" then
                    local ok, out = pcall(grndToUtf, v)
                    if ok and type(out) == "string" then v = out end
                end
                if type(grndToAnsi) == "function" then v = grndToAnsi(v) end
                return v
            end
            local function v(k, fallback)
                local z = R.live and R.live[k]
                return (z ~= nil and tostring(z) ~= "") and utf(z) or (fallback or "—")
            end
            if type(renderDrawBox) == "function" then
                pcall(renderDrawBox, x + 4, y + 5, w, h, 0x60000000)
                pcall(renderDrawBox, x, y, w, h, 0xE60B0F16)
                pcall(renderDrawBox, x, y, w, 3, 0xFF00D6AA)
            end
            local function t(s, dx, dy, c)
                pcall(renderFontDrawText, R.fallbackFont, utf(s), x + dx, y + dy, c)
            end
            t("GRND / RECON", 16, 12, 0xFF00D6AA)
            t("ID " .. v("id", R.id or "—"), 236, 12, 0xFFDDE8F2)
            t(R.nick or "Игрок", 16, 34, 0xFFFFFFFF)
            t("GUN: " .. v("weap"), 16, 66, 0xFFE9EDF6)
            t("AMMO: " .. v("ammo"), 188, 66, 0xFFE9EDF6)
            t("PING: " .. v("ping"), 16, 91, 0xFFE9EDF6)
            t("AFK: " .. v("afk", "0"), 188, 91, 0xFFF79248)
            t("HP: " .. v("hp"), 16, 116, 0xFF4CD14F)
            t("ARM: " .. v("arm"), 188, 116, 0xFF6094FF)
            t("FRACTION: " .. v("frac"), 16, 141, 0xFFE9EDF6)
            t("SPEED: " .. v("speed", "0"), 16, 166, 0xFFE9EDF6)
            t("Интерфейс реконa загружен", 16, 216, 0xFF8C94A6)
        end
    end
    -- =================================================================
    --  Безопасная проверка нажатия клавиши (физический опрос)
    -- =================================================================
    local lastDown = {}
    -- ФИКС v1.2: wasKeyTapped был локалом ЭТОГО блока, но вызывался из
    -- clwVkTapped/shake-хелперов, объявленных ВЫШЕ, — те видели nil и
    -- ClickWarp падал на «attempt to call a nil value». Функция глобальная.
    function wasKeyTapped(vk)
        if isKeyDown then
            local ok, down = pcall(isKeyDown, vk)
            if ok then
                down = down and true or false
                local prev = lastDown[vk]
                lastDown[vk] = down
                if down and not prev then return true end
            end
        end
        if wasKeyPressed then
            local ok, res = pcall(wasKeyPressed, vk)
            if ok and res then return true end
        end
        return false
    end
    local AUTH_OK_DELAY = AUTH.okDelay
    local isAuthDialog = grndAuthDialogOpen
    local function getChatLine(id)
        if not sampGetChatString then return nil, nil end
        local ok, text, prefix = pcall(sampGetChatString, id)
        if not ok then return nil, nil end
        return text, prefix
    end
    local function countAuthFailInChat()
        if not sampGetChatString then return 0 end
        local n = 0
        for id = 0, 99 do
            local t, p = getChatLine(id)
            if authTextIsFail(t) or authTextIsFail(p) then
                n = n + 1
            end
        end
        return n
    end
    -- =================================================================
    --  Перехват чата через samp.events
    -- =================================================================
    do
        local ok, sampev = pcall(require, "samp.events")
        if not ok or not sampev then
            ok, sampev = pcall(require, "lib.samp.events")
        end
        if ok and sampev then
            function sampev.onInitGame(...)
                pcall(grndCamUiEnd,false)
                authChat.failAt = 0
                GRND_GATE.authSeen, GRND_GATE.unblockAt = false, 0
                GRND_GATE.why = ""
                if type(_G.GRND_AUTH_STATE) == "table" then
                    local state = _G.GRND_AUTH_STATE
                    state.showedLoaded, state.showedAuthOk, state.windowSeen = false, false, false
                    state.closedAt, state.attemptFailed, state.failCountBase = nil, false, 0
                    state.failScanAt, state.dialog, state.spawned = 0, false, false
                end
                GRND_TRACER.rates={}
                if GRND_BULK.running then GRND_BULK.stop("Подключение изменилось. Очередь остановлена.") end
                GRND_WH.native=nil;GRND_WH.nativeAt=-999
                GRND_WH.players={};GRND_WH.scanAt=-999
            end
            function sampev.onAimSync(playerId, data)
                pcall(GRND_TRACER.aim, playerId, data)
            end
            function sampev.onSendAimSync(data)
                pcall(function() GRND_TRACER.aim(GRND_TRACER.localId(), data) end)
            end
            function sampev.onBulletSync(playerId, data)
                GRND_TRACER.receive(playerId, data, false)
            end
            function sampev.onSendBulletSync(data)
                GRND_TRACER.receive(GRND_TRACER.localId(), data, true)
            end
            function sampev.onShowDialog(dialogId, style, title, button1, button2, text)
                if not grndSessionReady() then return end
                -- МОДУЛЬ 14: окно ответа /stats -> «Сведения игрока» рекона.
                -- true = прячем окно-ответ, чтобы не мешало игроку.
                local okSt, hideSt = pcall(grndStatsOnDialog, dialogId, style, title, button1, button2, text)
                if okSt and hideSt then return false end
                -- v1.11.63: аварийная ветка — если сам хук упал, решение
                -- «прятать ли» принимается отдельно (без инжеста).
                if not okSt and type(_G.grndStatsShouldHide) == "function" then
                    local okH2, hideH2 = pcall(_G.grndStatsShouldHide, title, text)
                    if okH2 and hideH2 then return false end
                end
                -- /arep на этом сервере показывает диалог 10. Событие приходит
                -- именно в момент появления окна, даже если после команды была
                -- задержка. Возвращаем false, чтобы родное окно не рисовалось.
                -- v1.12: ФИКС «окно репорта всплывало на заходе» — сначала
                -- проверяем, что диалог действительно похож на репорт
                -- (см. grndRepAcceptDialog): id 10 у сервера используется и
                -- для окон авторизации/меню.
                if grndRepAcceptDialog(dialogId, title, text) then
                    grndRepSet(dialogId, title, text)
                    return false
                end
                -- «Наказания игрока» и {punishments} автопилота: окно
                -- /getinfo ID читается и прячется — true = игроку его
                -- показывать не нужно.
                if type(_G.grndQrPunOnDialog) == "function" then
                    local okPn, hidePn = pcall(_G.grndQrPunOnDialog,
                        dialogId, style, title, button1, button2, text)
                    if okPn and hidePn then return false end
                end
                local okA, hideA = pcall(grndAoOnDialog, dialogId, style, title, button1, button2, text)
                if okA and hideA then return false end
                local okRc, hideRc = pcall(grndRcOnDialog, dialogId, style, title, button1, button2, text)
                if okRc and hideRc then return false end
            end
            function sampev.onServerMessage(color, text)
                if type(text) == "string" and authTextIsFail(text) then authNoteFail() end
                if not grndSessionReady() then return end

                -- All ordinary parsing starts only after an actual in-game session.
                if _G.MP then pcall(_G.MP.onServerMessage, text) end
                local okAo, hideAo = pcall(grndAoOnChat, color, text)
                if okAo and hideAo == true then return false end
                local okAp, isApproved = pcall(_G.grndFormsApprovedOnChat, text, "server")
                pcall(grndRepRememberChat, text)
                pcall(grndCatchOnChat, text)
                pcall(grndRepHudOnChat, text)
                if not (okAp and isApproved) then pcall(grndFormsOnChat, text) end
                pcall(_G.grndFormWatchOnChat, text)
                pcall(_G.grndGnewsOnChat, text)
                pcall(gmSniffServerMsg, text)
                pcall(grndKlFeedChat, text)
                pcall(grndRepShouldHideChat, text)
                pcall(grndRcOnChat, color, text)
                local okCi, edit = pcall(grndChatIdOnMsg, color, text)
                if okCi and type(edit) == "table" then return edit end
            end
            -- Основная цепочка уже вызывает MP.onServerMessage напрямую;
            -- запасной хук не должен ошибочно сообщать «перехват не установлен».
            if _G.MP then
                _G.MP.chainReady = true
                _G.MP.hookOk = true
            end
            do
                local original=sampev.onServerMessage
                function sampev.onServerMessage(color,text)
                    local ready = grndSessionReady()
                    if ready then pcall(function() GRND_LOG.capture(text,'server');GRND_LOG.inServer=true end) end
                    local ok,result=pcall(original,color,text)
                    if ready then pcall(function() GRND_LOG.inServer=false end) end
                    -- Auxiliary parsing must never cancel ordinary chat on error.
                    if not ok then result=nil end
                    if result==false then return false end
                    local shownColor,shownText=color,text
                    if type(result)=='table' then shownColor,shownText=result[1],result[2] end
                    local okColor,corrected=pcall(grndChatServerColor,shownText,shownColor)
                    if okColor and corrected~=shownColor then return {corrected,shownText} end
                    return result
                end
            end
            function sampev.onChatMessage(playerId,text)
                if grndSessionReady() then
                    pcall(function() GRND_LOG.capture(GRND_LOG.nick(playerId)..'['..tostring(playerId)..']: '..GRND_LOG.utf(text),'player') end)
                end
                -- Native player chat must not be cancelled for local reprinting.
                -- Keep the client's nickname prefix and complete original text.
            end
            GRND_SPEC_EVENTS = true
            function sampev.onSendCommand(cmd)
                if not grndSessionReady() then return end
                pcall(grndSpecTrackCommand, cmd)
                pcall(grndAoOnCommand, cmd)
                pcall(grndRcOnCommand, cmd)
            end
            local function rcTdEvent(id, data, extra)
                if not grndSessionReady() then return end
                local text = ""
                if type(data) == "string" then
                    text = data
                elseif type(extra) == "string" then
                    text = extra
                elseif type(data) == "table" then
                    text = data.text or data.string or data.szString or ""
                end
                if text == "" and type(sampTextdrawGetString) == "function" then
                    local okS, s = pcall(sampTextdrawGetString, id)
                    if okS and type(s) == "string" then text = s end
                end
                local okH, hide = pcall(grndRcOnTextDraw, id, text)
                if okH and hide then return false end
            end
            function sampev.onShowTextDraw(id, data, extra)
                return rcTdEvent(id, data, extra)
            end
            function sampev.onTextDrawSetString(id, text)
                return rcTdEvent(id, text)
            end
            function sampev.onShowPlayerTextDraw(id, data, extra)
                return rcTdEvent(id, data, extra)
            end
            function sampev.onPlayerTextDrawSetString(id, text)
                return rcTdEvent(id, text)
            end
            function sampev.onHideTextDraw(id)
                pcall(grndRcOnTextDrawHide, id)
            end
            function sampev.onTextDrawHide(id)
                pcall(grndRcOnTextDrawHide, id)
            end
            function sampev.onSendChat(msg)
                if not grndSessionReady() then return end
                local m = tostring(msg or "")
                pcall(grndStatsOnSendChat, m)   -- МОДУЛЬ 14: пометить /stats
                if m:gsub("^%s*", ""):sub(1, 1) == "/" then
                    pcall(grndSpecTrackCommand, m)
                end
            end
            function sampev.onSendPlayerSync(data)
                if GRND_INVIS and GRND_INVIS.on and data then
                    local vehFound = false
                    if type(findAllRandomVehiclesInSphere) == "function" and data.position then
                        local okV, hVeh = pcall(findAllRandomVehiclesInSphere, data.position.x, data.position.y, data.position.z, 50.0, false, false)
                        if okV and hVeh and doesVehicleExist(hVeh) and type(sampGetVehicleIdByCarHandle) == "function" then
                            local okId, vehId = pcall(sampGetVehicleIdByCarHandle, hVeh)
                            if okId and vehId and vehId > 0 then
                                data.surfingVehicleId = vehId
                                if type(data.surfingOffsets) == "table" then
                                    data.surfingOffsets.x = 50.5
                                    data.surfingOffsets.y = 50.5
                                    data.surfingOffsets.z = -50.5
                                else
                                    data.surfingOffsets = { x = 50.5, y = 50.5, z = -50.5 }
                                end
                                vehFound = true
                            end
                        end
                    end
                    if not vehFound and data.position and type(data.position.z) == "number" then
                        data.position.z = data.position.z - 25.0
                    end
                end
            end
            function sampev.onSendPassengerSync(data)
                if GRND_INVIS and GRND_INVIS.on and data.position then
                    data.position.z = data.position.z - 25.0
                end
            end
            function sampev.onSendVehicleSync(data)
                if GRND_INVIS and GRND_INVIS.on and data.position then
                    data.position.z = data.position.z - 15.0
                end
            end
            -- v1.7.5: перехват RPC килл-листа. false = клиент НЕ рисует
            -- строку в родном списке (перехват без поиска структуры в памяти).
            function sampev.onPlayerDeathNotification(killerId, killedId, reason)
                pcall(GRND_LOG.death,killerId,killedId,reason)
                if GRND_KL and GRND_KL.enabled then
                    local ok, handled = pcall(grndKlFeedRpc, killerId, killedId, reason)
                    if ok and handled then return false end
                end
            end
            function sampev.onPlayerJoin(pid,data)
                GRND_CHATID.at=-10
            end
            function sampev.onPlayerQuit(pid, reason)
                GRND_CHATID.at=-10
                GRND_TRACER.rates[pid]=nil
                GRND_TRACER.aims[pid]=nil
                GRND_TRACER.suspects[pid]=nil
                for id,state in pairs(GRND_TRACER.suspects) do
                    if state.target==pid then GRND_TRACER.suspects[id]=nil end
                end
                local curTid = (_G.GRND_SPEC and tonumber(_G.GRND_SPEC.id))
                    or (_G.GRND_RC and tonumber(_G.GRND_RC.id))
                    or (_G.GRND_SPEC_AUTOREF and tonumber(_G.GRND_SPEC_AUTOREF.lastTargetId))
                if (curTid and curTid == pid) or (GRND_SPEC.active and GRND_SPEC.id == pid) then
                    if type(_G.grndRcForceClose) == "function" then
                        pcall(_G.grndRcForceClose, "quit")
                    end
                    grndSpecForget("quit")
                end
            end
            SAMPEV_OK = true
            print("{00FFAA}[GRND]{FFFFFF} перехват чата: samp.events")
        else
            print("{FFAA00}[GRND]{FFFFFF} samp.events не найден")
        end
    end
    -- =================================================================
    --  МОДУЛЬ 5v: ленивая регистрация команд (samp может быть ещё не
    --  загружен на старте, поэтому регистрируем из основного цикла).
    --  Сюда перенесены /grnd, /cwsp из однократных
    --  блоков — те больше не существуют.
    -- =================================================================
    local GRND_CMDS_DONE = false
    local function grndRegisterCmds()
        if GRND_CMDS_DONE then return end
        if type(sampRegisterChatCommand) ~= "function" then return end
        GRND_CMDS_DONE = true
        -- =================================================================
        --  v1.12: ЕДИНЫЙ ЦЕНТР ДИАГНОСТИКИ /grnd
        --  Раньше диагностика жила в пяти командах (/grndkeys, /grndtrace,
        --  /grndchat, /cwdbg, /grndact). В релизе оставляем одну точку входа:
        --      /grnd            — состояние скрипта
        --      /grnd keys       — почему не работают клавиши (+ any / unbind)
        --      /grnd chat       — диагностика настроек чата
        --      /grnd trace      — записать трассу в файл (on/off — вкл/выкл)
        -- =================================================================
        local function grndDiagKeys(arg)
            local a = tostring(arg or ""):lower():gsub("%s+", "")
            if a == "any" or a == "0" then
                BLOCK_KEYS_ON_ANY_DIALOG = not BLOCK_KEYS_ON_ANY_DIALOG
                notify.add("Блокировать клавиши при ЛЮБОМ окне сервера: "
                    .. (BLOCK_KEYS_ON_ANY_DIALOG and "ДА" or "НЕТ"), "warn", 5)
                return true
            end
            if a == "unbind" then
                F1_UNBIND_ENABLED = true
                GRND_F1.unbindDone, GRND_F1.forceUnbind = false, true
                notify.add("Пробую отвязать F1 в памяти samp.dll (на свой страх и риск)", "warn", 6)
                return true
            end
            local K = GRND_KEYS
            local out = {}
            for k, v in pairs(GRND_TRACE.keys or {}) do
                out[#out + 1] = k .. "=" .. tostring(v)
            end
            table.sort(out)
            local lines = {
                "рендер ImGui: " .. tostring(_G.GRND_IMGUI_ALIVE)
                    .. " (" .. tostring(IMGUI_WRAP or "нет обёртки") .. ")",
                "кадров нарисовано: " .. tostring(T_frames())
                    .. "   меню: " .. tostring(GRND_REF.menu ~= nil),
                "что глушит клавиши: blocked=" .. tostring(K.blocked)
                    .. " dlgActive=" .. tostring(K.dlgActive)
                    .. " (блокировка по любому окну: "
                    .. (BLOCK_KEYS_ON_ANY_DIALOG and "вкл" or "выкл") .. ")",
                "  imguiText(WantTextInput)=" .. tostring(K.imguiText)
                    .. "  uiBusy(меню/таблица)=" .. tostring(K.uiBusy),
                "  перехват клавиш у других скриптов: consumeWindowMessage "
                    .. (type(consumeWindowMessage) == "function" and "есть" or "НЕТ"),
                "чат: штатный ввод SA-MP + надстройка Tab /a и история (v1.15.52)",
                "  печать в чате: typing=" .. tostring(K.typing)
                    .. " typingFresh=" .. tostring(K.typingFresh),
                "последние нажатия (события): "
                    .. (#out == 0 and "НИ ОДНОГО сообщения не дошло" or table.concat(out, " ")),
                "подкоманды: /grnd keys any — блок по любому окну, "
                    .. "/grnd keys unbind — F1-патч",
            }
            for i = 1, #lines do
                print("{00FFAA}[GRND]{FFFFFF} " .. lines[i])
                pcall(notify.say, lines[i], "info")
            end
            pcall(grndTraceDump, "/grnd keys")
            return true
        end

        local function grndDiagTrace(arg)
            local a = tostring(arg or ""):lower():gsub("%s+", " ")
            if a == "off" then
                GRND_TRACE.on = false
                pcall(notify.say, "трассировка выключена", "warn")
            elseif a == "on" then
                GRND_TRACE.on = true
                pcall(notify.say, "трассировка включена", "ok")
            else
                local okd, path = pcall(grndTraceDump, "команда /grnd trace")
                GRND_TRACE.dumped = 9
                pcall(notify.say, (okd and path) and ("трасса записана: " .. tostring(path))
                    or "не удалось записать файл трассы", okd and "ok" or "error")
            end
            return true
        end

        -- Form processing is built-in; no form setup or simulation commands.
        pcall(sampRegisterChatCommand, "grnd", function(arg)
            local sub = tostring(arg or ""):lower():gsub("^%s+", ""):gsub("%s+$", "")
            local head, rest = sub:match("^(%S+)%s*(.*)$")
            if head == "hud" then
                -- v1.15.54: РУЧНОЙ ВЫБОР способа масштаба текста. Если
                -- автовыбор ошибся в вашем клиенте, способ задаётся одной
                -- командой — без правки файла. Варианты:
                --   /grnd hud mode auto     — вернуть автовыбор
                --   /grnd hud mode dx       — текст через render-библиотеку
                --   /grnd hud mode scale    — SetWindowFontScale
                --   /grnd hud mode pushsize — PushFont(шрифт, кегль)
                --   /grnd hud mode push     — шрифт нужного кегля из «лестницы»
                --   /grnd hud mode global   — io.FontGlobalScale
                --   /grnd hud mode none     — не масштабировать текст
                local sub2, arg2 = tostring(rest or ""):lower():match("^(%S+)%s*(.*)$")
                if sub2 == "mode" then
                    local want = tostring(arg2 or ""):match("^(%S+)") or ""
                    local RH2 = GRND_REPHUD
                    if want == "" or want == "?" then
                        print("{00FFAA}[GRND]{FFFFFF} способ сейчас: "
                            .. tostring(RH2.forceMode or ("авто («" .. tostring(
                                (RH2.txt and RH2.txt.mode) or "ещё не определён") .. "»)")))
                        print("{00FFAA}[GRND]{FFFFFF} /grnd hud mode auto|dx|scale|pushsize|push|global|none")
                        return true
                    end
                    if want == "auto" then
                        RH2.forceMode = nil
                        RH2.txt = nil                 -- переопределить заново
                        pcall(grndCamCfgSave)
                        print("{00FFAA}[GRND]{FFFFFF} способ масштаба текста: АВТОВЫБОР")
                        return true
                    end
                    if want == "dx" or want == "scale" or want == "pushsize"
                        or want == "push" or want == "global" or want == "none" then
                        RH2.forceMode = want
                        RH2.txt = nil
                        pcall(grndCamCfgSave)
                        print("{00FFAA}[GRND]{FFFFFF} способ масштаба текста задан: «"
                            .. want .. "» (окно пересчитается на следующем кадре)")
                        return true
                    end
                    print("{FF6666}[GRND]{FFFFFF} нет такого способа: " .. want
                        .. " — можно: auto, dx, scale, pushsize, push, global, none")
                    return true
                end
                -- v1.15.2: диагностика оверлея «Репорты на экране»: каким
                -- способом в ЭТОМ клиенте масштабируется текст (определяется
                -- замером, см. GRND_REPHUD.detectTextMode) и что вообще есть.
                local RH = GRND_REPHUD
                local basePx = tonumber(GRND_FONT and GRND_FONT.fontBase) or 16
                local m, f, dbg = RH.detectTextMode(basePx)
                local ladCnt = 0
                if type(im.__grndFontLadder) == "table" then
                    for _ in pairs(im.__grndFontLadder) do ladCnt = ladCnt + 1 end
                end
                local ioGS = "нет"
                if type(im.GetIO) == "function" then
                    local okio, io = pcall(im.GetIO)
                    if okio and io then
                        local okg, v = pcall(function() return io.FontGlobalScale end)
                        ioGS = okg and tostring(v) or "нет"
                    end
                end
                local sv, sp = "1.18.01", "?"
                pcall(function()
                    sv = tostring(thisScript().version or sv)
                    sp = tostring(thisScript().path or "?")
                end)
                local lines = {
                    "сборка v" .. sv .. " · файл: " .. sp,
                    "оверлей «Репорты на экране»: " .. (RH.enabled and "вкл" or "выкл")
                        .. " · размер " .. tostring(math.floor((RH.scale or 1) * 100 + 0.5)) .. "%"
                        .. " · окно " .. tostring(RH.metrics(RH.clampScale(RH.scale), basePx, 0).W) .. " px",
                    "масштаб текста: " .. (m == "none"
                        and "НЕ ПОДДЕРЖИВАЕТСЯ клиентом (окно держим базового размера)"
                        or ("способ «" .. m .. "» — работает, проверено замером"))
                        .. " · выбрано: " .. (RH.forceMode
                            and ("ВРУЧНУЮ (/grnd hud mode auto — вернуть авто)" ) or "авто"),
                    "переключить способ: /grnd hud mode dx|scale|pushsize|push|global|none|auto",
                    "шрифт интерфейса: " .. tostring(GRND_FONT and (GRND_FONT.fontLoadedPath
                        or GRND_FONT.fontPath) or "НЕ загружен (системный обёртки)"),
                    "пробы кегля (ширина надписи «РЕПОРТЫ», px): " .. tostring(dbg or "—"),
                    "DX-текст (render-библиотека): renderCreateFont=" ..
                        (type(renderCreateFont) == "function" and "есть" or "НЕТ")
                        .. " · renderFontDrawText=" ..
                        (type(renderFontDrawText) == "function" and "есть" or "НЕТ")
                        .. " · renderGetFontDrawTextLength=" ..
                        (type(renderGetFontDrawTextLength) == "function" and "есть" or "НЕТ")
                        .. " · renderDrawBox=" ..
                        (type(renderDrawBox) == "function" and "есть" or "НЕТ"),
                    "кегль базы: " .. tostring(basePx)
                        .. " · «лестница»: " .. tostring(ladCnt) .. " размеров"
                        .. " · im: " .. tostring(IMGUI_WRAP or "?"),
                    "SetWindowFontScale: " .. (type(im.SetWindowFontScale) == "function" and "есть" or "НЕТ")
                        .. " · PushFont: " .. (type(im.PushFont) == "function" and "есть" or "НЕТ")
                        .. " · GetIO: " .. (type(im.GetIO) == "function" and "есть" or "НЕТ")
                        .. " · io.FontGlobalScale: " .. ioGS,
                }
                for i = 1, #lines do
                    print("{00FFAA}[GRND]{FFFFFF} " .. lines[i])
                    pcall(notify.say, lines[i], "info")
                end
                return true
            end
            if head == "keys" then return grndDiagKeys(rest) end
            if head == "trace" then return grndDiagTrace(rest) end
            if head == "input" then return GRND_INPUT.command(rest) end
            if head == "chat" then
                if type(grndChatTest) == "function" then pcall(grndChatTest, rest) end
                return true
            end
            local mem = grndMemLib()
            local lines = {
                "ImGui: " .. tostring(IMGUI_WRAP or "не загружен"),
                "кадр отрисован: " .. (renderedOnce and "да" or "НЕТ"),
                "bit.lua: " .. (bit and "есть" or "нет"),
                "memory.lua: " .. (mem and "есть" or "нет"),
                "чат: штатный ввод SA-MP; панель ввода " .. (GRND_INPUT.enabled and "ВКЛ" or "ВЫКЛ"),
                "samp.events: " .. (SAMPEV_OK and "есть" or "нет"),
                "клавиши: " .. (GRND_KEYS.blocked
                    and "перехват снят (авторизация)"
                    or "живы (F1/TAB/M/ESC)")
                    .. "  путь: события+опрос, меню="
                    .. tostring(GRND_REF.menu ~= nil)
                    .. "  печать: " .. (GRND_KEYS.typingFresh and "идёт"
                    or (GRND_KEYS.typingSince and "залипла" or "нет"))
                    .. "  диалог: " .. (GRND_KEYS.authBusy and "ОТКРЫТ" or "нет")
                    .. "  спавн: " .. (GRND_KEYS.spawnedNow and "да" or "нет"),
                "интерфейс: " .. ((type(_G.grndUiBlocked) == "function" and _G.grndUiBlocked())
                    and ("СПРЯТАН (" .. tostring(_G.GRND_GATE.why) .. ")")
                    or "показывается")
                    .. " | подавлено кадров: " .. tostring(_G.GRND_GATE.suppressed or 0),
                "диагностика: /grnd keys | /grnd chat | /grnd input | /grnd trace",
                "авторизация: диалог=" .. tostring(AUTH.dialog)
                    .. " seen=" .. tostring(AUTH.windowSeen)
                    .. " ok=" .. tostring(AUTH.showedAuthOk)
                    .. " fail=" .. tostring(AUTH.attemptFailed),
            }
            for i = 1, #lines do
                print("{00FFAA}[GRND]{FFFFFF} " .. lines[i])
                pcall(notify.say, lines[i], "info")
            end
            return true
        end)
        pcall(sampRegisterChatCommand, "cwsp", function(arg)
            local a = tostring(arg or ""):lower():gsub("%s+", " ")
            if a == "off" or a == "0" or a == "" then
                GRND_SPEC.active = false
                GRND_SPEC.id = nil
                GRND_SPEC.nick = ""
                GRND_SPEC.confirmT = 0
                GRND_SPEC.manualExit = true
                if _G.GRND_SPEC_AUTOREF then
                    _G.GRND_SPEC_AUTOREF.manualExit = true
                    _G.GRND_SPEC_AUTOREF.lastTargetId = nil
                    _G.GRND_SPEC_AUTOREF.lostSince = nil
                    _G.GRND_SPEC_AUTOREF.refreshCount = 0
                end
                notify.add("Слежка: трекинг сброшен вручную", "info", 3)
            else
                local id = tonumber(a)
                if id then
                    grndSpecTrackCommand("/sp " .. id)
                else
                    notify.add("Использование: /cwsp <id> или /cwsp off", "warn", 4)
                end
            end
        end)
        grndTrace("cmd", "команды зарегистрированы: /grnd /grndkl /cwsp /invis /cam /cgm /chatid")
    end
    local function clwSafe(fn, name)
        local ok, err = pcall(fn)
        if not ok then
            print("{FF6666}[GRND]{FFFFFF} ОШИБКА ClickWarp [" .. tostring(name) .. "]: " .. tostring(err))
            notify.add("ClickWarp: ошибка (" .. tostring(name) .. ") — см. консоль", "error", 4)
        end
    end
    local lastTry = os.clock()
    local tries   = 0
    -- =================================================================
    --  ОСНОВНОЙ ЦИКЛ (МОДУЛЬ 7: добавлены grndRegisterCmds и
    --  grndF1UnbindTick — раньше разбинд F1 не вызывался вообще)
    -- =================================================================
    grndConfigRuntimeInit()
    grndConfigSnapshot(true)
    while true do
        wait(0)
        pcall(grndConfigSnapshot,false)
        pcall(grndKeysTick)        -- native chat still owns the text editing and sending
        pcall(GRND_INPUT.tick)     -- v1.15.44: session history / layout / overlay lifecycle
        pcall(grndRepPoll)         -- report: ждём dialogId=10 сколько нужно после /arep
        -- report: окно /getinfo (наказания) — кнопка «Наказания игрока» и {punishments}
        if _G.GRND_QR and type(_G.GRND_QR.punPoll) == "function" then pcall(_G.GRND_QR.punPoll) end
        pcall(grndRepQueueTick)    -- report: очередь /ans, /goto
        if _G.MP then pcall(_G.MP.tick) end  -- МОДУЛЬ 15: очередь команд МП
        pcall(grndKlTick)          -- МОДУЛЬ 11 (v1.5.1): чтение stKillInfo + гашение системного списка
        pcall(grndAoTick)          -- МОДУЛЬ 12 (v1.8.5): чекер «Админы в сети»
        pcall(grndRcTick)          -- МОДУЛЬ 13 (v1.10.0): кастомный рекон
        pcall(grndSpecAutoRefreshTick) -- авто-обновление слежки (/sp) при потере цели
        pcall(grndStatsTick)       -- МОДУЛЬ 14 (v1.11.3): /stats -> сведения игрока
        pcall(grndFormWatchTick)   -- v1.13.0: сторож ответа сервера по форме
        pcall(grndFormsKeyTick)    -- v1.13.0: [Y]/[N] окна формы — каждый тик
        if _G.grndBinderTick then pcall(_G.grndBinderTick) end
        do
            local okBulk, errBulk = pcall(GRND_BULK.tick)
            if not okBulk then GRND_BULK.stop("Ошибка очереди: " .. tostring(errBulk)) end
        end
        pcall(grndRingTick)       -- настройки/сохранение/опрос действий круга
        if type(grndAirBreakTick) == "function" then
            pcall(grndAirBreakTick) -- v1.11.64: AirBreak — полёт на удержании клавиши
        end
        -- DX-fallbacks are overlays too: keep stale recon cards/hints off
        -- connection and login screens just like the ImGui windows.
        local gateOverlays = type(grndUiBlocked) == "function" and grndUiBlocked()
        if not gateOverlays then
            if type(_G.grndReconFallback) == "function" then
                pcall(_G.grndReconFallback)
            end
            if type(_G.drawReconHintDx) == "function" then
                pcall(_G.drawReconHintDx)
            end
        end
        do
            local okWh,errWh=pcall(GRND_WH.frame)
            if not okWh then
                GRND_WH.frameError=tostring(errWh)
                GRND_WH.nativeStatus='Ошибка WH: '..tostring(errWh)
                pcall(GRND_WH.diagnose)
            end
        end
        pcall(GRND_TRACER.frame) -- DX tracer; no additional ImGui window
        pcall(grndTargetRingFrame)  -- DX: круг/линия к цели, без ImGui-окна
        pcall(grndTraceTick)
        pcall(grndRegisterCmds)
        pcall(grndF1UnbindTick)
        do
            local okCamera,errCamera=pcall(grndCamTick)
            if not okCamera then
                pcall(grndCamUiEnd,false)
                pcall(grndCamLookRestore)
                grndCamReportError('normal',errCamera)
            end
            pcall(grndCamDiagTick,not okCamera and errCamera or nil)
        end
        pcall(grndChatStampApply)
        GRND_KEYS.uiBusy = (((menu ~= nil) and menu.open)
            or GRND_TAB.open or (GRND_REP and GRND_REP.open)
            or (GRND_RC and GRND_RC.show)
            or (_G.GRND_KL and _G.GRND_KL.moving)
            or (_G.GRND_AO and _G.GRND_AO.moving)) and true or false
        GRND_KEYS.aiming = ((clw ~= nil) and clw.aiming) and true or false
        pcall(grndUiMouseUpdate)
        pcall(grndUiMovementGuardTick)
        pcall(grndStickyKeysTick)
        if type(_G.grndQrAutoTick) == "function" then pcall(_G.grndQrAutoTick) end
        -- синхронизация флага UI input-guard: окно могло закрыться
        -- не хоткеем (сторож, ESC из чужого места) — сверяемся
        do
            local wantUi = ((menu and menu.open) or GRND_TAB.open
                or (GRND_REP and GRND_REP.open)
                or (GRND_RC and GRND_RC.show)
                or (_G.GRND_KL and _G.GRND_KL.moving)
                or (_G.GRND_AO and _G.GRND_AO.moving)) and true or false
            if wantUi ~= grndUiControlsOn and not clw.aiming then
                grndUiControls(wantUi)
            end
        end
        if not ((menu and menu.open) or GRND_TAB.open
            or (GRND_REP and GRND_REP.open)
            or (GRND_RC and GRND_RC.show)
            or (GRND_RC and GRND_RC.prompt)) then
            GRND_KEYS.imguiText = false
        end
        if GRND_TAB.open then ensureRender() end
        if GRND_CATCH and GRND_CATCH.active then ensureRender() end
        -- v1.13.0: окно формы держит кадр (и ~0.35 с после закрытия — чтобы
        -- оно гарантированно стёрлось, а не «зависло» на экране)
        if type(_G.grndFormsUiWanted) == "function" and _G.grndFormsUiWanted() then
            ensureRender(true)
        end
        if type(_G.grndGnewsUiWanted) == "function" and _G.grndGnewsUiWanted() then
            ensureRender(true)
        end
        if GRND_REPHUD and GRND_REPHUD.enabled then ensureRender() end
        if GRND_RC and GRND_RC.show then ensureRender() end

        if GRND_TAB.specId ~= nil then
            local sid = GRND_TAB.specId
            GRND_TAB.specId = nil
            if sampSendChat then
                pcall(sampSendChat, "/sp " .. tostring(sid))
            end
            pcall(grndSpecTrackCommand, "/sp " .. tostring(sid))
        end
        local spawnedNow = grndIsSpawned()
        local manualExitMain = (_G.GRND_SPEC and _G.GRND_SPEC.manualExit)
            or (_G.GRND_SPEC_AUTOREF and _G.GRND_SPEC_AUTOREF.manualExit)
        if spawnedNow and not specWasSpawned and (manualExitMain or not GRND_SPEC.active) then
            grndSpecForget("spawn")
        end
        specWasSpawned = spawnedNow
        do
            local now = os.clock()
            if now - specWatchT >= 0.5 then
                specWatchT = now
                local okS, st = pcall(specProbeState)
                if not okS then st = nil end
                if st == false and manualExitMain then
                    grndSpecForget("state")
                elseif st == true then
                    if GRND_SPEC.active then
                        specConfirm()
                    else
                        local okI, tid = pcall(specProbeSpectId)
                        if okI and tid then
                            pcall(grndSpecTrackCommand, "/sp " .. tid)
                        end
                    end
                end
            end
            if GRND_SPEC.active and not GRND_SPEC_EVENTS then
                if now - (GRND_SPEC.confirmT or 0) > GRND_SPEC_CONFIRM_SEC then
                    grndSpecForget("stale")
                end
            end
        end
        local _okAuth, _errAuth = pcall(function()
            local dialogActive = isAuthDialog()
            AUTH.dialog, AUTH.spawned = dialogActive, spawnedNow

            if dialogActive then
                if not AUTH.showedLoaded then
                    AUTH.showedLoaded = true
                    notify.add("Скрипт загружен", "ok", 5, true)
                    grndTrace("auth", "показано уведомление о загрузке скрипта")
                end
                if not AUTH.windowSeen or AUTH.closedAt ~= nil or AUTH.attemptFailed then
                    AUTH.failCountBase = countAuthFailInChat()
                    AUTH.attemptFailed = false
                    AUTH.failScanAt = 0
                    authChat.failAt = 0
                    AUTH.closedAt = nil
                end
                AUTH.windowSeen = true
                GRND_TRACE.authSeen = now0()
            end

            if AUTH.windowSeen and not AUTH.showedAuthOk and not AUTH.attemptFailed then
                local now = os.clock()
                local failFromHook = authChat.failAt > 0
                local failFromChat = false
                if not failFromHook and not dialogActive and now - (AUTH.failScanAt or 0) >= 0.15 then
                    AUTH.failScanAt = now
                    local okCount, failCount = pcall(countAuthFailInChat)
                    failFromChat = okCount and type(failCount) == "number"
                        and failCount > (AUTH.failCountBase or 0)
                end
                if failFromHook or failFromChat then
                    AUTH.attemptFailed = true
                    AUTH.closedAt = nil
                    authChat.failAt = 0
                    notify.add("Пароль не подошёл — попробуйте ещё раз", "error", 4, true)
                    grndTrace("auth", "ошибка пароля в активном окне авторизации")
                elseif not dialogActive then
                    if AUTH.closedAt == nil then
                        AUTH.closedAt = now
                        grndTrace("auth", "диалог авторизации закрыт — проверяем вход")
                    elseif now - AUTH.closedAt >= AUTH_OK_DELAY and spawnedNow then
                        AUTH.showedAuthOk = true
                        notify.add("Авторизация прошла успешно", "ok", 4, true)
                        grndTrace("auth", "авторизация подтверждена спавном игрока")
                        lastTry = now
                    end
                else
                    AUTH.closedAt = nil
                end
            end
        end)
        if not _okAuth then
            print("{FF6666}[GRND]{FFFFFF} auth-frame: " .. tostring(_errAuth))
        end
        if not renderedOnce and os.clock() - lastTry > 3 and tries < 10 then
            ensureRender(true)
            lastTry = os.clock()
            tries = tries + 1
        end
        -- =====================================================================
        --  Горячие клавиши: ЗАПАСНОЙ путь (опрос). Основной — onWindowMessage;
        --  чтобы один и тот же тап не переключал дважды, каждый ключ
        --  защищён таймером GRND_TAP (tapOnce в обработчике сообщений).
        --  ФИКС v1.1: hotBusy зависал намертво, т.к. строилcя из
        --  grndAuthDialogActive() (ЛЮБОЕ окно сервера) и io.WantTextInput,
        --  который обновляется только в кадре ImGui.
        -- =====================================================================
        local _okHot, _errHot = pcall(function()
            local function poll(k)
                if not wasKeyTapped(k) then return false end
                -- то же «нажатие», что уже обработал onWindowMessage — молчим
                if not grndPollTap(k) then return false end
                return true
            end
            local function pollRelease(k)
                -- как только клавиша физически отжата — освобождаем защёлку
                if type(isKeyDown) == "function" then
                    local ok, d = pcall(isKeyDown, k)
                    if (not ok) or not d then grndTapEnd(k) end
                else
                    grndTapEnd(k)
                end
            end
            -- v1.7.0: T (0x54), F6 (0x75), F7 (0x76) и G (0x47) больше не наши —
            -- их не перехватываем, они остались родному чату и игре.
            for _, k in ipairs({ GRND_MENU_HOTKEY, 0x09, 0x1B, 0x70,
                GRND_GM_TOGGLE_KEY, 0x52, 0x45 }) do
                pollRelease(k)
            end
            if GRND_INVIS and GRND_INVIS.key then
                pollRelease(GRND_INVIS.key)
            end
            if GRND_CHAT and GRND_CHAT.key then pollRelease(GRND_CHAT.key) end
            -- Открытие чата своей клавишей: запрос из onWindowMessage ИЛИ
            -- прямой опрос клавиши (если сообщение до нас не дошло).
            if GRND_CHAT and GRND_CHAT.key and not GRND_CHAT.binding then
                local isT = (GRND_CHAT.key == 0x54)
                local busy = grndIsTyping()
                    or (menu and menu.open) or GRND_TAB.open
                    or (GRND_REP and GRND_REP.open)
                if not isT and not busy and not GRND_CHAT.wantOpen and poll(GRND_CHAT.key) then
                    GRND_CHAT.wantOpen = os.clock()
                    GRND_CHAT.nativeT = false
                end
                if GRND_CHAT.wantOpen then
                    if isT then
                        -- даём родному обработчику T один кадр; если чат так и
                        -- не открылся — открываем через API (без эмуляции T,
                        -- иначе было бы двойное нажатие)
                        if os.clock() - GRND_CHAT.wantOpen > 0.05 then
                            GRND_CHAT.wantOpen = nil
                            if not busy then pcall(grndChatOpen, true) end
                        end
                    else
                        GRND_CHAT.wantOpen = nil
                        if not busy then pcall(grndChatOpen, false) end
                    end
                end
            end
            if GRND_AREP and GRND_AREP.key then pollRelease(GRND_AREP.key) end
            if GRND_CATCH and GRND_CATCH.key then pollRelease(GRND_CATCH.key) end
            local hotBusy = GRND_KEYS.blocked
                or (BLOCK_KEYS_ON_ANY_DIALOG and GRND_KEYS.dlgActive)
                or grndIsTyping()
            -- Резервный опрос R/E, если onWindowMessage пропустил короткий тап.
            -- Общая защёлка GRND_TAP не даст включить круг дважды.
            if not hotBusy then
                if grndTargetRingCanUseKey(0x52) and poll(0x52) then
                    grndTargetRingUseKey(0x52)
                end
                if grndTargetRingCanUseKey(0x45) and poll(0x45) then
                    grndTargetRingUseKey(0x45)
                end
            end
            if menu then
                if not hotBusy and poll(GRND_MENU_HOTKEY) then
                    menu.open = not menu.open
                    if menu.open then ensureRender() end
                    grndTrace("key", "M(опрос) -> меню " .. (menu.open and "открыто" or "закрыто"))
                end
                if not hotBusy and poll(0x09) then
                    GRND_TAB.open = not GRND_TAB.open
                    GRND_TAB.held = false
                    if GRND_TAB.open then ensureRender() end
                    grndTrace("key", "TAB(опрос) -> " .. tostring(GRND_TAB.open))
                end
                if poll(0x1B) then grndEscAction() end
            end
            if not hotBusy and poll(0x70) and grndF1Debounced() then
                -- v1.11.10: при открытом реконе F1 не управляет курсором
                if not (GRND_RC and GRND_RC.show) then
                    grndTogglePlainCursor()
                end
            end
            -- v1.7.0: ветки T / F6 (своя строка ввода), F7 (показать/скрыть
            -- чат) и G (настройки чата) УДАЛЕНЫ вместе с кастомным чатом.
        end)
        if not _okHot then
            print("{FF6666}[GRND]{FFFFFF} hotkey-frame: " .. tostring(_errHot))
            pcall(grndTrace, "ERROR", "hotkey-frame: " .. tostring(_errHot))
        end
        -- GM
        if not GRND_GM.cmdReg then
            GRND_GM.cmdReg = true
            if type(sampRegisterChatCommand) == "function" then
                pcall(sampRegisterChatCommand, "cgm", function() grndGMToggle() end)
                pcall(sampRegisterChatCommand, "cgmauto", function()
                    local v = not (GRND_GM.autoClient and GRND_GM.autoServer)
                    GRND_GM.autoClient, GRND_GM.autoServer = v, v
                    pcall(grndCamCfgSave)
                    if notify and type(notify.add) == "function" then
                        pcall(notify.add, "Авто-GM: " .. (v and "ВКЛ" or "ВЫКЛ"), "info", 3)
                    end
                end)
            end
        end
        grndGMFrame()
        pcall(grndInvisFrame)
        local gmSpawned = false
        if type(grndIsSpawned) == "function" then
            local okS, sp = pcall(grndIsSpawned)
            if okS then gmSpawned = sp and true or false end
        end
        if not gmSpawned then
            GRND_GM.autoFired = false
        elseif AUTH.showedAuthOk and not GRND_GM.autoFired then
            GRND_GM.autoFired = true
            local changed = false
            if GRND_GM.autoClient and not GRND_GM.on then
                grndGMClientSet(true)
                changed = true
            end
            if GRND_GM.autoServer and not GRND_GM.srv then
                grndGMSrvSet(true)
                changed = true
            end
            if changed then grndGMToast(true) end
        end
        -- ClickWarp
        if clw then
            -- не глушим ClickWarp из-за ЛЮБОГО окна SA:MP (справка F1 / диалоги):
            -- из-за этого прицел выключался после первого раза и больше не вставал.
            -- v1.7.0: «печатает» — только родной чат (штатный API клиента)
            local clwTyping = false
            if sampIsChatInputActive then
                local ok, r = pcall(sampIsChatInputActive)
                if ok and r then clwTyping = true end
            end
            if GRND_KEYS.typing then clwTyping = true end
            local uiBusy = clwTyping or (menu and menu.open) or GRND_TAB.open
            if not uiBusy then
                if GRND_SPEC.active then
                    for _, ek in ipairs(GRND_SPEC_EXIT_KEYS) do
                        if wasKeyTapped(ek) then
                            grndSpecForget("key")
                            break
                        end
                    end
                end
                if clw.mode == "click" then
                    if clwBtnTapped(clw.keyToggle) then
                        clwSetAiming(not clw.aiming)
                    elseif clw.aiming and clwBtnTapped(clw.keyApply) then
                        clwSafe(clwApplyAim, "warp")
                    elseif clw.aiming and wasKeyTapped(GRND_SPEC_WARP_KEY) then
                        clwSafe(specWarpAim, "spec")
                    elseif clw.aiming and wasKeyTapped(GRND_SPEC_CAR_KEY) then
                        clwSafe(specRememberCar, "car-save")
                    elseif clw.aiming and wasKeyTapped(GRND_SPEC_CARGO_KEY) then
                        clwSafe(specWarpCarAim, "car-tp")
                    elseif clw.aiming and wasKeyTapped(0x1B) then
                        clwSetAiming(false)
                    end
                else
                    if clwBtnTapped(clw.keyToggle) then
                        if clw.aiming then clwSetAiming(false) end
                        clwSafe(clwDoWarp, "instant")
                    end
                end
            elseif clw.aiming then
                clwSetAiming(false)
            end
            if clw.aiming and not grndIsSpawned() then
                clwSetAiming(false)
            end
            if plainCursorOn and not grndIsSpawned() then
                plainCursorOn = false
                grndPlainCursorShow(false)
            end
            if clw.aiming then
                pcall(clwAimFrame)
            end
        end
    end
end
-- =====================================================================
--  main() = обёртка над grndMainBody()
-- =====================================================================
-- v1.12: ссылки на внутренние таблицы для автоматического стенда
-- (dev/harness.lua). Сами по себе ничего не делают, из игры не наблюдаемы;
-- нужны, чтобы тесты могли проверить состояние окон, не открывая меню руками.
_G.GRND_INT = {
    F = GRND_FONT, T = GRND_TAB, K = GRND_KEYS, F1 = GRND_F1,
    S = grndSpecNative,
}
function grndConfigRuntimeInit()
    local C=GRND_CONFIG
    if C.runtimeReady then return end
    C.ensure()
    local loaders={camCfgLoad,grndUiCfgLoad,grndBinderLoad,grndRingLoad,grndCharLoad}
    for _,fn in ipairs(loaders) do
        local ok,err=pcall(fn);if not ok then C.warn(err);C.readOnly=true;return end
    end
    if GRND_PUN and not GRND_PUN.loaded then GRND_PUN.load() end
    if GRND_KL and not GRND_KL.cfgLoaded then grndKlCfgLoad() end
    if GRND_AO and not GRND_AO.cfgLoaded then grndAoCfgLoad() end
    C.restorePanels()
    if GRND_CHATID and GRND_CHATID.register then pcall(GRND_CHATID.register) end
    C.runtimeReady=true
end
function grndConfigSnapshot(force)
    if GRND_LOG then
        local ok,err=pcall(GRND_LOG.tick,force)
        if not ok then GRND_LOG.warn(err) end
    end
    local C=GRND_CONFIG
    if not C.runtimeReady or C.readOnly then return end
    if not force and os.clock()-(C.lastPoll or -10)<1 then return end
    C.lastPoll=os.clock();C.collecting=true
    -- Flush current multiline contents, but never commit an unfinished rename.
    if grndBinderFlushBuf then pcall(grndBinderFlushBuf) end
    if grndRingUiFlush then pcall(grndRingUiFlush) end
    local savers={grndCamCfgSave,grndUiCfgSave,grndKlCfgSave,grndAoCfgSave,
        grndBinderSave,grndRingSave,grndCharSave}
    for _,fn in ipairs(savers) do
        local ok,err=pcall(fn);if not ok then C.warn(err) end
    end
    if GRND_PUN and GRND_PUN.loaded then pcall(GRND_PUN.save) end
    C.extraSnapshot();C.collecting=false
    C.flush()
end
function main()
    GRND_CONFIG.ensure()
    GRND_CONFIG.restoreHotkeys()
    GRND_LOG.init()
    GRND_CONFIG.flush()
    local ok, err = pcall(grndMainBody)
    if not ok then
        GRND_MAIN_ERR = tostring(err)
        print("{FF6666}[GRND]{FFFFFF} main() упал: " .. GRND_MAIN_ERR)
        if type(sampAddChatMessage) == "function" then
            pcall(grndChatSay, "{FF6666}[GRND] main() упал: " .. GRND_MAIN_ERR, -1)
        end
    end
end